--
-- Name: count_audit_logs(uuid, text[], text[], uuid, uuid, timestamp with time zone, timestamp with time zone, integer, text); Type: FUNCTION; Schema: logs; Owner: -
--

CREATE FUNCTION logs.count_audit_logs(p_org_id uuid, p_module text[] DEFAULT NULL::text[], p_action text[] DEFAULT NULL::text[], p_user_id uuid DEFAULT NULL::uuid, p_target_id uuid DEFAULT NULL::uuid, p_start_date timestamp with time zone DEFAULT NULL::timestamp with time zone, p_end_date timestamp with time zone DEFAULT NULL::timestamp with time zone, p_retention_days integer DEFAULT NULL::integer, p_search text DEFAULT NULL::text) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_cutoff_date timestamp with time zone;
  v_search_pattern text;
  v_count bigint;
BEGIN
  -- Calculate retention cutoff date if specified
  IF p_retention_days IS NOT NULL THEN
    v_cutoff_date := NOW() - (p_retention_days || ' days')::interval;
  END IF;

  -- Prepare search pattern for ILIKE queries (pg_trgm will optimize these)
  IF p_search IS NOT NULL AND p_search != '' THEN
    v_search_pattern := '%' || p_search || '%';
  END IF;

  SELECT COUNT(*)
  INTO v_count
  FROM logs.org_audit_logs oal
  LEFT JOIN public.profiles p ON oal.user_id = p.id
  WHERE oal.organization_id = p_org_id
    AND (p_module IS NULL OR oal.module = ANY(p_module))
    AND (p_action IS NULL OR oal.action = ANY(p_action))
    AND (p_user_id IS NULL OR oal.user_id = p_user_id)
    AND (p_target_id IS NULL OR oal.target_id = p_target_id)
    AND (p_start_date IS NULL OR oal.created_at >= p_start_date)
    AND (p_end_date IS NULL OR oal.created_at <= p_end_date)
    AND (v_cutoff_date IS NULL OR oal.created_at >= v_cutoff_date)
    AND (
      v_search_pattern IS NULL OR
      oal.target_name ILIKE v_search_pattern OR
      p.name ILIKE v_search_pattern OR
      p.email ILIKE v_search_pattern OR
      oal.module ILIKE v_search_pattern OR
      oal.action ILIKE v_search_pattern
    );

  RETURN v_count;
END;
$$;


--
-- Name: get_audit_log_by_id(uuid, uuid); Type: FUNCTION; Schema: logs; Owner: -
--

CREATE FUNCTION logs.get_audit_log_by_id(p_log_id uuid, p_org_id uuid) RETURNS TABLE(id uuid, organization_id uuid, user_id uuid, module text, action text, target_id uuid, target_name text, target_table text, target_extra jsonb, changes jsonb, metadata jsonb, created_at timestamp with time zone, user_name text, user_email text)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    oal.id,
    oal.organization_id,
    oal.user_id,
    oal.module,
    oal.action,
    oal.target_id,
    oal.target_name,
    oal.target_table,
    oal.target_extra,
    oal.changes,
    oal.metadata,
    oal.created_at,
    p.name as user_name,
    p.email as user_email
  FROM logs.org_audit_logs oal
  LEFT JOIN public.profiles p ON oal.user_id = p.id
  WHERE oal.id = p_log_id
    AND oal.organization_id = p_org_id;
END;
$$;


--
-- Name: get_audit_logs_with_users(uuid, text[], text[], uuid, uuid, timestamp with time zone, timestamp with time zone, integer, integer, integer, text); Type: FUNCTION; Schema: logs; Owner: -
--

CREATE FUNCTION logs.get_audit_logs_with_users(p_org_id uuid, p_module text[] DEFAULT NULL::text[], p_action text[] DEFAULT NULL::text[], p_user_id uuid DEFAULT NULL::uuid, p_target_id uuid DEFAULT NULL::uuid, p_start_date timestamp with time zone DEFAULT NULL::timestamp with time zone, p_end_date timestamp with time zone DEFAULT NULL::timestamp with time zone, p_retention_days integer DEFAULT NULL::integer, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0, p_search text DEFAULT NULL::text) RETURNS TABLE(id uuid, organization_id uuid, user_id uuid, module text, action text, target_id uuid, target_name text, target_table text, target_extra jsonb, changes jsonb, metadata jsonb, created_at timestamp with time zone, user_name text, user_email text)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$DECLARE
  v_cutoff_date timestamp with time zone;
  v_search_pattern text;
BEGIN
  -- Calculate retention cutoff date if specified
  IF p_retention_days IS NOT NULL THEN
    v_cutoff_date := NOW() - (p_retention_days || ' days')::interval;
  END IF;

  -- Prepare search pattern for ILIKE queries (pg_trgm will optimize these)
  IF p_search IS NOT NULL AND p_search != '' THEN
    v_search_pattern := '%' || p_search || '%';
  END IF;

  RETURN QUERY
  SELECT
    oal.id,
    oal.organization_id,
    oal.user_id,
    oal.module,
    oal.action,
    oal.target_id,
    oal.target_name,
    oal.target_table,
    oal.target_extra,
    oal.changes,
    oal.metadata,
    oal.created_at,
    p.display_name as user_name,
    p.email as user_email
  FROM logs.org_audit_logs oal
  LEFT JOIN public.profiles p ON oal.user_id = p.id
  WHERE oal.organization_id = p_org_id
    AND (p_module IS NULL OR oal.module = ANY(p_module))
    AND (p_action IS NULL OR oal.action = ANY(p_action))
    AND (p_user_id IS NULL OR oal.user_id = p_user_id)
    AND (p_target_id IS NULL OR oal.target_id = p_target_id)
    AND (p_start_date IS NULL OR oal.created_at >= p_start_date)
    AND (p_end_date IS NULL OR oal.created_at <= p_end_date)
    AND (v_cutoff_date IS NULL OR oal.created_at >= v_cutoff_date)
    AND (
      v_search_pattern IS NULL OR
      oal.target_name ILIKE v_search_pattern OR
      p.name ILIKE v_search_pattern OR
      p.email ILIKE v_search_pattern OR
      oal.module ILIKE v_search_pattern OR
      oal.action ILIKE v_search_pattern
    )
  ORDER BY oal.created_at DESC
  LIMIT p_limit
  OFFSET p_offset;
END;$$;


--
-- Name: get_destination_history_v2(uuid, uuid, timestamp with time zone, timestamp with time zone, text); Type: FUNCTION; Schema: logs; Owner: -
--

CREATE FUNCTION logs.get_destination_history_v2(p_org_id uuid, p_tp_id uuid, p_start_time timestamp with time zone DEFAULT NULL::timestamp with time zone, p_end_time timestamp with time zone DEFAULT NULL::timestamp with time zone, p_timezone text DEFAULT 'UTC'::text) RETURNS TABLE(destination text, changed_at timestamp with time zone, segment_type text, type text)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    WITH activity_logs AS (
        SELECT 
            oal.changes,
            oal.created_at
        FROM logs.org_audit_logs oal
        WHERE oal.organization_id = p_org_id
            AND oal.target_id = p_tp_id
            AND oal.module = 'touch_point'
            AND oal.changes IS NOT NULL
            AND (p_start_time IS NULL OR oal.created_at >= p_start_time)
            AND (p_end_time IS NULL OR oal.created_at <= p_end_time)
    ),
    extracted_destinations AS (
        -- Extract from content_value.new field
        SELECT 
            al.changes->'content_value'->>'new' AS dest,
            al.created_at,
            'default' AS segment_type,
            'logs' AS type
        FROM activity_logs al
        WHERE al.changes ? 'content_value'
            AND al.changes->'content_value' ? 'new'
            AND al.changes->'content_value'->>'new' IS NOT NULL
            AND al.changes->'content_value'->>'new' != ''

        UNION ALL

        -- Extract from targeting.new.targets array
        SELECT 
            target->>'destination' AS dest,
            al.created_at,
            'targeting' AS segment_type,
            'logs' AS type
        FROM activity_logs al,
            jsonb_array_elements(
                al.changes->'targeting'->'new'->'targets'
            ) WITH ORDINALITY AS ord(target, ordinality)
        WHERE al.changes ? 'targeting'
            AND al.changes->'targeting' ? 'new'
            AND al.changes->'targeting'->'new' ? 'targets'
            AND target ? 'destination'
            AND target->>'destination' IS NOT NULL
            AND target->>'destination' != ''

        UNION ALL

        -- Extract from targeting.old.targets array
        SELECT 
            target->>'destination' AS dest,
            al.created_at,
            'targeting' AS segment_type,
            'logs' AS type
        FROM activity_logs al,
            jsonb_array_elements(
                al.changes->'targeting'->'old'->'targets'
            ) WITH ORDINALITY AS ord(target, ordinality)
        WHERE al.changes ? 'targeting'
            AND al.changes->'targeting' ? 'old'
            AND al.changes->'targeting'->'old' ? 'targets'
            AND target ? 'destination'
            AND target->>'destination' IS NOT NULL
            AND target->>'destination' != ''
    ),
    current_destinations AS (
        -- Extract current content_value from touch_points table
        SELECT 
            tp.content_value AS dest,
            NOW() AS created_at,
            'default' AS segment_type,
            'current' AS type
        FROM public.touch_points tp
        WHERE tp.organization_id = p_org_id
            AND tp.id = p_tp_id
            AND tp.content_value IS NOT NULL
            AND tp.content_value != ''

        UNION ALL

        -- Extract destinations from current targeting.targets array
        SELECT 
            target->>'destination' AS dest,
            NOW() AS created_at,
            'targeting' AS segment_type,
            'current' AS type
        FROM public.touch_points tp,
            jsonb_array_elements(tp.targeting->'targets') WITH ORDINALITY AS ord(target, ordinality)
        WHERE tp.organization_id = p_org_id
            AND tp.id = p_tp_id
            AND tp.targeting IS NOT NULL
            AND tp.targeting ? 'targets'
            AND target ? 'destination'
            AND target->>'destination' IS NOT NULL
            AND target->>'destination' != ''
    ),
    all_destinations AS (
        SELECT * FROM extracted_destinations
        UNION ALL
        SELECT * FROM current_destinations
    )
    SELECT DISTINCT ON (ad.dest, ad.segment_type)
        ad.dest AS destination,
        ad.created_at AS changed_at,
        ad.segment_type,
        ad.type
    FROM all_destinations ad
    ORDER BY 
        ad.dest, 
        ad.segment_type,
        CASE WHEN ad.type = 'current' THEN 0 ELSE 1 END,  -- Priority: 'current' first
        ad.created_at DESC;
END;
$$;


--
-- Name: archive_old_free_visits(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.archive_old_free_visits() RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    batch_size INT := 50000;
    rows_moved INT := 1;
BEGIN
    WHILE rows_moved > 0 LOOP
        WITH ids AS (
            SELECT v.id
            FROM visits v
            JOIN user_plans up ON up.user_id = v.user_id
            WHERE up.plan_id = '80e46841-b185-4640-a95b-103cb9a85be3'
              AND v.created_at < now() - INTERVAL '7 days'
            LIMIT batch_size
        ),
        moved AS (
            DELETE FROM visits v
            USING ids
            WHERE v.id = ids.id
            RETURNING 
                v.id,
                v.created_at,
                v.fp,
                v.tp_id,
                v.os,
                v.platform,
                v.campaign_id,
                v.type,
                v.user_id,
                v.organization_id,
                v.city,
                v.country,
                v.referrer,
                v.user_agent,
                v.content_value,
                v.ip,
                v.isp,
                v.is_bot,
                v.asn,
                v.raw_referrer,
                v.region,
                v.segment_type,
                v.utm_campaign_id,
                v.utm_channel_id,
                v.utm_tags
        )
        INSERT INTO visit_archives (
                id,
                created_at,
                fp,
                tp_id,
                os,
                platform,
                campaign_id,
                type,
                user_id,
                organization_id,
                city,
                country,
                referrer,
                user_agent,
                content_value,
                ip,
                isp,
                is_bot,
                asn,
                raw_referrer,
                region,
                segment_type,
                utm_campaign_id,
                utm_channel_id,
                utm_tags,
                archived_at
        )
        SELECT 
            *,
            now()
        FROM moved;

        GET DIAGNOSTICS rows_moved = ROW_COUNT;

        -- Stop if nothing was deleted this batch
        IF rows_moved = 0 THEN
            EXIT;
        END IF;

        -- Small sleep to avoid table lock pressure
        PERFORM pg_sleep(0.1);
    END LOOP;
END;
$$;


