--
-- Name: artifacts; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.artifacts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    user_id uuid NOT NULL,
    name text NOT NULL,
    kind text NOT NULL,
    status text DEFAULT 'draft'::text NOT NULL,
    serve_token text NOT NULL,
    storage_path text NOT NULL,
    content_type text NOT NULL,
    size_bytes bigint NOT NULL,
    touch_point_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    access_mode text DEFAULT 'public'::text NOT NULL,
    password_hash text,
    access_version integer DEFAULT 1 NOT NULL,
    password_set_at timestamp with time zone,
    CONSTRAINT artifacts_access_mode_check CHECK ((access_mode = ANY (ARRAY['public'::text, 'private'::text, 'password'::text, 'google'::text]))),
    CONSTRAINT artifacts_kind_check CHECK ((kind = ANY (ARRAY['html'::text, 'markdown'::text, 'pdf'::text, 'site'::text, 'slides'::text, 'document'::text, 'sheet'::text, 'image'::text, 'video'::text]))),
    CONSTRAINT artifacts_password_hash_check CHECK (((access_mode = 'password'::text) = (password_hash IS NOT NULL))),
    CONSTRAINT artifacts_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'scanning'::text, 'live'::text, 'blocked'::text, 'expired'::text, 'quarantined'::text, 'removed'::text])))
);


--
-- Name: artifact_create_if_within_quota(uuid, uuid, uuid, text, text, text, text, text, bigint, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.artifact_create_if_within_quota(p_id uuid, p_org_id uuid, p_user_id uuid, p_name text, p_kind text, p_serve_token text, p_storage_path text, p_content_type text, p_size_bytes bigint, p_quota_bytes bigint) RETURNS SETOF public.artifacts
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_used bigint;
  v_row "public"."artifacts";
BEGIN
  PERFORM pg_advisory_xact_lock(hashtextextended(p_org_id::text, 0));

  SELECT COALESCE(sum("size_bytes"), 0) INTO v_used
  FROM "public"."artifacts"
  WHERE "organization_id" = p_org_id AND "status" <> 'removed';

  IF v_used + p_size_bytes > p_quota_bytes THEN
    RETURN;
  END IF;

  INSERT INTO "public"."artifacts" (
    "id", "organization_id", "user_id", "name", "kind", "status",
    "serve_token", "storage_path", "content_type", "size_bytes"
  ) VALUES (
    p_id, p_org_id, p_user_id, p_name, p_kind, 'draft',
    p_serve_token, p_storage_path, p_content_type, p_size_bytes
  )
  RETURNING * INTO v_row;

  RETURN NEXT v_row;
  RETURN;
END;
$$;


--
-- Name: artifact_publish_if_within_quota(uuid, uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.artifact_publish_if_within_quota(p_org_id uuid, p_artifact_id uuid, p_touch_point_id uuid, p_limit integer) RETURNS SETOF public.artifacts
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_live integer;
  v_row "public"."artifacts";
BEGIN
  PERFORM pg_advisory_xact_lock(hashtextextended(p_org_id::text, 0));

  SELECT count(*) INTO v_live
  FROM "public"."artifacts"
  WHERE "organization_id" = p_org_id AND "status" = 'live';

  IF v_live >= p_limit THEN
    RETURN;
  END IF;

  UPDATE "public"."artifacts"
  SET "status" = 'live', "touch_point_id" = p_touch_point_id
  WHERE "id" = p_artifact_id AND "organization_id" = p_org_id
    AND "status" IN ('draft', 'scanning')
  RETURNING * INTO v_row;

  IF NOT FOUND THEN
    RETURN;
  END IF;

  RETURN NEXT v_row;
  RETURN;
END;
$$;


--
-- Name: artifact_replace_if_within_quota(uuid, uuid, text, text, text, bigint, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.artifact_replace_if_within_quota(p_org_id uuid, p_artifact_id uuid, p_kind text, p_storage_path text, p_content_type text, p_size_bytes bigint, p_quota_bytes bigint) RETURNS SETOF public.artifacts
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_used bigint;
  v_old "public"."artifacts";
BEGIN
  PERFORM pg_advisory_xact_lock(hashtextextended(p_org_id::text, 0));

  SELECT * INTO v_old
  FROM "public"."artifacts"
  WHERE "id" = p_artifact_id AND "organization_id" = p_org_id
    AND "status" IN ('live', 'draft')
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN;
  END IF;

  SELECT COALESCE(sum("size_bytes"), 0) INTO v_used
  FROM "public"."artifacts"
  WHERE "organization_id" = p_org_id AND "status" <> 'removed';

  IF v_used - v_old."size_bytes" + p_size_bytes > p_quota_bytes THEN
    RETURN;
  END IF;

  UPDATE "public"."artifacts"
  SET "kind" = p_kind,
      "storage_path" = p_storage_path,
      "content_type" = p_content_type,
      "size_bytes" = p_size_bytes,
      "updated_at" = now()
  WHERE "id" = p_artifact_id;

  RETURN NEXT v_old;
  RETURN;
END;
$$;


--
-- Name: artifact_visit_counts(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.artifact_visit_counts(p_tp_ids uuid[]) RETURNS TABLE(tp_id uuid, visits bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT "v"."tp_id", count(*) AS "visits"
  FROM "public"."visits" AS "v"
  WHERE "v"."tp_id" = ANY (p_tp_ids)
    AND "v"."is_bot" = false
  GROUP BY "v"."tp_id"
$$;


