--
-- Name: assign_free_plan(uuid, uuid, text, text, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assign_free_plan(_user_id uuid, _plan_id uuid, _fp text, _ip text, _limit integer, _max_per_fp integer, _max_per_ip integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  user_exists INT;
  total_plan_users INT;
  fp_count INT;
  ip_count INT;
BEGIN
  -- Lock all related profiles (by id, fp, ip)
  WITH locked_profiles AS (
    SELECT * FROM profiles
    WHERE id = _user_id OR signup_fp = _fp OR signup_ip = _ip
    FOR UPDATE
  ),
  locked_user_plans AS (
    SELECT * FROM user_plans
    WHERE plan_id = _plan_id
    FOR UPDATE
  )

  -- Count everything safely from locked rows
  SELECT 
    COUNT(*) FILTER (WHERE p.id = _user_id) AS user_exists,
    (SELECT COUNT(*) FROM locked_user_plans) AS total_plan_users,
    (SELECT COUNT(*) FROM locked_user_plans up JOIN locked_profiles p ON p.id = up.user_id WHERE p.signup_fp = _fp) AS fp_count,
    (SELECT COUNT(*) FROM locked_user_plans up JOIN locked_profiles p ON p.id = up.user_id WHERE p.signup_ip = _ip) AS ip_count
  INTO user_exists, total_plan_users, fp_count, ip_count
  FROM locked_profiles p;

  -- Check all limits
  IF user_exists = 0 THEN
    RETURN '{"success":false,"message":"User not found"}'::jsonb;
  ELSIF total_plan_users >= _limit THEN
    RETURN '{"success":false,"message":"Plan limit reached"}'::jsonb;
  ELSIF fp_count >= _max_per_fp THEN
    RETURN '{"success":false,"message":"Fingerprint limit reached"}'::jsonb;
  ELSIF ip_count >= _max_per_ip THEN
    RETURN '{"success":false,"message":"IP address limit reached"}'::jsonb;
  END IF;

  -- Safe upsert
  INSERT INTO user_plans (user_id, plan_id, subscribed_at, expires_at)
  VALUES (_user_id, _plan_id,  NOW(), DATE_TRUNC('day', NOW() + INTERVAL '1 year'))
  ON CONFLICT (user_id)
  DO UPDATE SET
    plan_id = EXCLUDED.plan_id,
    subscribed_at = NOW(),
    expires_at = DATE_TRUNC('day', NOW() + INTERVAL '1 year');

  RETURN '{"success":true,"message":"Free plan assigned successfully"}'::jsonb;

EXCEPTION
  WHEN OTHERS THEN
    RETURN jsonb_build_object('success', false, 'message', 'Error: ' || SQLERRM);
END;
$$;


