--
-- Name: create_org_credit_after_org_insert(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_org_credit_after_org_insert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_plan_id uuid;
  v_max_ai_credits smallint;
begin
  -- Get the user's plan from user_plans
  select up.plan_id
  into v_plan_id
  from public.user_plans up
  where up.user_id = new.user_id;

  -- Fetch max_ai_credits from that plan
  if v_plan_id is not null then
    select pl.max_ai_credits
    into v_max_ai_credits
    from public.plans pl
    where pl.id = v_plan_id;
  else
    v_max_ai_credits := null;
  end if;

  -- Fallback if user has no plan or plan is invalid
  if v_max_ai_credits is null then
    v_max_ai_credits := 3;
  end if;

  -- Create org_credits record
  insert into public.org_credits (
    org_id,
    ai_credits_balance,
    ai_credits_used_this_month,
    ai_credits_last_reset,
    created_at,
    updated_at
  )
  values (
    new.id,
    v_max_ai_credits,
    0,
    date_trunc('month', now()),
    now(),
    now()
  );

  return new;
end;
$$;


--
-- Name: export_all_profiles(text, text, uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.export_all_profiles(search_column text DEFAULT NULL::text, search_value text DEFAULT NULL::text, filter_plan uuid DEFAULT NULL::uuid, created_from timestamp with time zone DEFAULT NULL::timestamp with time zone, created_to timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS json
    LANGUAGE plpgsql
    AS $_$
DECLARE
  result JSON;
  sql TEXT;
BEGIN
  sql := '
    SELECT COALESCE(json_agg(t), ''[]''::json)
    FROM (
      SELECT m.id, m.name, m.email, m.created_at,
             up.expires_at, up.subscribed_at,
             row_to_json(p) AS plan
      FROM profiles m
      LEFT JOIN user_plans up ON up.user_id = m.id
      LEFT JOIN plans p ON p.id = up.plan_id
      WHERE 1=1';

  -- Add filters conditionally
  IF search_column IS NOT NULL AND search_value IS NOT NULL THEN
    sql := sql || ' AND m.' || quote_ident(search_column) || ' ILIKE $1';
  END IF;

  IF filter_plan IS NOT NULL THEN
    sql := sql || ' AND up.plan_id = $2';
  END IF;

  IF created_from IS NOT NULL THEN
    sql := sql || ' AND m.created_at >= $3';
  END IF;

  IF created_to IS NOT NULL THEN
    sql := sql || ' AND m.created_at <= $4';
  END IF;

  sql := sql || '
      ORDER BY m.created_at DESC
    ) t';

  EXECUTE sql
  INTO result
  USING
    CASE WHEN search_column IS NOT NULL AND search_value IS NOT NULL THEN '%' || search_value || '%' ELSE NULL END,
    filter_plan,
    created_from,
    created_to;

  RETURN result;
END;
$_$;


--
-- Name: generate_all_weekly_reports(date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_all_weekly_reports(target_week date DEFAULT (date_trunc('week'::text, (now() - '7 days'::interval)))::date) RETURNS TABLE(organization_id uuid, organization_name text, report_generated boolean, report_id uuid, error_message text)
    LANGUAGE plpgsql
    AS $$
DECLARE
  org_record RECORD;
  report_result JSONB;
  new_report_id UUID;
BEGIN
  -- Loop through all active organizations
  FOR org_record IN 
    SELECT o.id, o.name, pf.email
    FROM organizations o
    left join profiles pf on o.user_id = pf.id
    -- WHERE EXISTS (
    --   SELECT 1 FROM visits v 
    --   WHERE v.organization_id = o.id 
    --     AND DATE(v.created_at) BETWEEN target_week AND target_week + INTERVAL '6 days'
    -- )
  LOOP
    BEGIN
      -- Generate report for this organization
      report_result := generate_weekly_report(org_record.id, target_week);
      
      -- Insert report record
      INSERT INTO organization_reports (
        organization_id,
        report_type,
        report_period_start,
        report_period_end,
        report_data,
        status,
        recipient_emails
      ) VALUES (
        org_record.id,
        'weekly',
        target_week,
        target_week + INTERVAL '6 days',
        report_result,
        'sent',
        ARRAY[org_record.email]
      ) RETURNING id INTO new_report_id;
      
      -- Return success
      organization_id := org_record.id;
      organization_name := org_record.name;
      report_generated := TRUE;
      report_id := new_report_id;
      error_message := NULL;
      RETURN NEXT;
      
    EXCEPTION WHEN OTHERS THEN
      -- Return error
      organization_id := org_record.id;
      organization_name := org_record.name;
      report_generated := FALSE;
      report_id := NULL;
      error_message := SQLERRM;
      RETURN NEXT;
    END;
  END LOOP;
END;
$$;


--
-- Name: generate_weekly_report(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_weekly_report(target_organization_id uuid, report_week_start date DEFAULT (date_trunc('week'::text, (now() - '7 days'::interval)))::date) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
  report_data JSONB := '{}';
  exec_summary JSONB;
  touchpoint_rankings JSONB;
  channel_performance JSONB;
  geographic_insights JSONB;
  timing_insights JSONB;
  utm_performance JSONB;
  weekly_trends JSONB;
  device_insights JSONB;
  week_end_date DATE;
BEGIN
  -- Calculate week end date
  week_end_date := report_week_start + INTERVAL '6 days';
  
  -- 1. EXECUTIVE SUMMARY
  WITH weekly_metrics AS (
    SELECT 
      COUNT(*) as total_visits,
      COUNT(DISTINCT fp) as unique_visitors,
      COUNT(DISTINCT tp_id) as active_touchpoints,
      COUNT(DISTINCT country) as countries_reached,
      COUNT(CASE WHEN type = 'QR' THEN 1 END) as qr_scans,
      COUNT(CASE WHEN type = 'LINK' THEN 1 END) as link_clicks
    FROM visits 
    WHERE DATE(created_at) BETWEEN report_week_start AND week_end_date
      AND organization_id = target_organization_id
  ),
  previous_week AS (
    SELECT 
      COUNT(*) as prev_total_visits,
      COUNT(DISTINCT fp) as prev_unique_visitors
    FROM visits 
    WHERE DATE(created_at) BETWEEN (report_week_start - INTERVAL '7 days') AND (report_week_start - INTERVAL '1 day')
      AND organization_id = target_organization_id
  )
  SELECT JSON_BUILD_OBJECT(
    'total_visits', w.total_visits,
    'unique_visitors', w.unique_visitors,
    'active_touchpoints', w.active_touchpoints,
    'countries_reached', w.countries_reached,
    'qr_scans', w.qr_scans,
    'link_clicks', w.link_clicks,
    'visits_growth_pct', ROUND(((w.total_visits - p.prev_total_visits) * 100.0 / NULLIF(p.prev_total_visits, 0)), 1),
    'visitors_growth_pct', ROUND(((w.unique_visitors - p.prev_unique_visitors) * 100.0 / NULLIF(p.prev_unique_visitors, 0)), 1),
    'qr_share_pct', ROUND((w.qr_scans * 100.0 / NULLIF(w.total_visits, 0)), 1),
    'link_share_pct', ROUND((w.link_clicks * 100.0 / NULLIF(w.total_visits, 0)), 1)
  ) INTO exec_summary
  FROM weekly_metrics w
  CROSS JOIN previous_week p;

  -- 2. TOP TOUCHPOINTS (Week Period)
  WITH touchpoint_stats AS (
    SELECT 
      v.tp_id,
      tp.name,
      COUNT(v.*) as total_visits,
      COUNT(DISTINCT v.fp) as unique_visitors,
      COUNT(CASE WHEN v.type = 'QR' THEN 1 END) as qr_scans,
      COUNT(CASE WHEN v.type = 'LINK' THEN 1 END) as link_clicks,
      ROUND((COUNT(DISTINCT v.fp) * 100.0 / NULLIF(COUNT(*), 0)), 1) as engagement_rate
    FROM visits v
    LEFT JOIN touch_points tp ON v.tp_id = tp.id
    WHERE DATE(v.created_at) BETWEEN report_week_start AND week_end_date
      AND v.tp_id IS NOT NULL
      AND v.organization_id = target_organization_id
    GROUP BY v.tp_id, tp.name
  )
  SELECT JSON_AGG(
    JSON_BUILD_OBJECT(
      'tp_id', tp_id,
      'tp_name', name,
      'total_visits', total_visits,
      'unique_visitors', unique_visitors,
      'engagement_rate', engagement_rate,
      'qr_scans', qr_scans,
      'link_clicks', link_clicks
    ) ORDER BY total_visits DESC
  ) INTO touchpoint_rankings
  FROM touchpoint_stats
  LIMIT 10;

  -- 3. CHANNEL PERFORMANCE (Fixed window function issue)
  WITH channel_stats AS (
    SELECT 
      type as channel_type,
      COUNT(*) as total_visits,
      COUNT(DISTINCT fp) as unique_visitors,
      ROUND((COUNT(DISTINCT fp) * 100.0 / NULLIF(COUNT(*), 0)), 1) as engagement_rate
    FROM visits 
    WHERE DATE(created_at) BETWEEN report_week_start AND week_end_date
      AND type IN ('QR', 'LINK')
      AND organization_id = target_organization_id
    GROUP BY type
  ),
  channel_with_totals AS (
    SELECT 
      channel_type,
      total_visits,
      unique_visitors,
      engagement_rate,
      SUM(total_visits) OVER() as total_all_visits
    FROM channel_stats
  )
  SELECT JSON_AGG(
    JSON_BUILD_OBJECT(
      'channel_type', channel_type,
      'total_visits', total_visits,
      'unique_visitors', unique_visitors,
      'engagement_rate', engagement_rate,
      'market_share_pct', ROUND((total_visits * 100.0 / NULLIF(total_all_visits, 0)), 1)
    )
  ) INTO channel_performance
  FROM channel_with_totals;

  -- 4. GEOGRAPHIC INSIGHTS (Fixed window function issue)
  WITH geo_stats AS (
    SELECT 
      country,
      COUNT(*) as visits,
      COUNT(DISTINCT fp) as unique_visitors,
      COUNT(DISTINCT city) as cities_count
    FROM visits 
    WHERE DATE(created_at) BETWEEN report_week_start AND week_end_date
      AND country IS NOT NULL
      AND organization_id = target_organization_id
    GROUP BY country
  ),
  geo_with_totals AS (
    SELECT 
      country,
      visits,
      unique_visitors,
      cities_count,
      SUM(visits) OVER() as total_all_visits
    FROM geo_stats
  )
  SELECT JSON_AGG(
    JSON_BUILD_OBJECT(
      'country', country,
      'visits', visits,
      'unique_visitors', unique_visitors,
      'cities_count', cities_count,
      'visit_share_pct', ROUND((visits * 100.0 / NULLIF(total_all_visits, 0)), 1)
    ) ORDER BY visits DESC
  ) INTO geographic_insights
  FROM geo_with_totals
  LIMIT 10;

  -- 5. PEAK ACTIVITY TIMES
  WITH hourly_stats AS (
    SELECT 
      EXTRACT(hour FROM created_at) as hour_of_day,
      COUNT(*) as visits
    FROM visits 
    WHERE DATE(created_at) BETWEEN report_week_start AND week_end_date
      AND organization_id = target_organization_id
    GROUP BY EXTRACT(hour FROM created_at)
  )
  SELECT JSON_AGG(
    JSON_BUILD_OBJECT(
      'hour', hour_of_day,
      'visits', visits
    ) ORDER BY visits DESC
  ) INTO timing_insights
  FROM hourly_stats
  LIMIT 5;

  -- 6. DEVICE/PLATFORM MIX (Fixed window function issue)
  WITH device_stats AS (
    SELECT 
      COALESCE(platform, 'Unknown') as platform,
      COUNT(*) as visits,
      COUNT(DISTINCT fp) as unique_users
    FROM visits 
    WHERE DATE(created_at) BETWEEN report_week_start AND week_end_date
      AND organization_id = target_organization_id
    GROUP BY platform
  ),
  device_with_totals AS (
    SELECT 
      platform,
      visits,
      unique_users,
      SUM(visits) OVER() as total_all_visits
    FROM device_stats
  )
  SELECT JSON_AGG(
    JSON_BUILD_OBJECT(
      'platform', platform,
      'visits', visits,
      'unique_users', unique_users,
      'market_share_pct', ROUND((visits * 100.0 / NULLIF(total_all_visits, 0)), 1)
    ) ORDER BY visits DESC
  ) INTO device_insights
  FROM device_with_totals;

  -- Compile final report
  report_data := JSON_BUILD_OBJECT(
    'report_metadata', JSON_BUILD_OBJECT(
      'organization_id', target_organization_id,
      'report_period_start', report_week_start,
      'report_period_end', week_end_date,
      'generated_at', NOW(),
      'report_type', 'weekly'
    ),
    'executive_summary', exec_summary,
    'touchpoint_rankings', touchpoint_rankings,
    'channel_performance', channel_performance,
    'geographic_insights', geographic_insights,
    'timing_insights', timing_insights,
    'device_insights', device_insights
  );

  RETURN report_data;
END;
$$;


--
-- Name: geolite_lookup(text, text[], text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.geolite_lookup(_type text, _continent_codes text[] DEFAULT NULL::text[], _country_codes text[] DEFAULT NULL::text[]) RETURNS TABLE(value text, label text)
    LANGUAGE plpgsql STABLE
    AS $$
begin
  -- Continents: (code + name)
  if lower(_type) = 'continent' then
    return query
    select distinct g.continent_code as value, g.continent as label
    from public.geolite g
    where g.continent_code is not null
      and g.continent is not null
    order by label, value;

  -- Countries: (country_code + country) filtered by continent codes (array)
  elsif lower(_type) = 'country' then
    -- If the caller passed an *empty* array, return nothing.
    if _continent_codes is not null and cardinality(_continent_codes) = 0 then
      return;
    end if;

    return query
    select distinct g.country_code as value, g.country as label
    from public.geolite g
    where g.country_code is not null
      and g.country is not null
      and (
        _continent_codes is null            -- null => no filter (return all)
        or g.continent_code = any (_continent_codes)
      )
    order by label, value;

  -- Subdivisions: (code + subdivision_name) filtered by country codes (array)
  elsif lower(_type) = 'subdivision' then
    -- If the caller passed an *empty* array, return nothing.
    if _country_codes is not null and cardinality(_country_codes) = 0 then
      return;
    end if;

    return query
    select distinct g.code as value, g.subdivision_name as label
    from public.geolite g
    where g.code is not null
      and g.subdivision_name is not null
      and (
        _country_codes is null              -- null => no filter (return all)
        or g.country_code = any (_country_codes)
      )
    order by label, value;

  else
    -- Unknown type -> return nothing
    return;
  end if;
end;
$$;


--
-- Name: get_acquisition_campaign_performance(uuid, integer, text, uuid[], uuid[], boolean, uuid[], boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_acquisition_campaign_performance(p_organization_id uuid, p_period_days integer, p_timezone text DEFAULT 'UTC'::text, p_tag_ids uuid[] DEFAULT NULL::uuid[], p_touchpoint_ids uuid[] DEFAULT NULL::uuid[], p_is_premium boolean DEFAULT false, p_collection_ids uuid[] DEFAULT NULL::uuid[], p_include_null_collection boolean DEFAULT false) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    start_date TIMESTAMPTZ;
    end_date TIMESTAMPTZ;
    result JSON;
BEGIN
    -- Validate tier restrictions
    IF NOT p_is_premium AND p_period_days != 7 THEN
        RETURN json_build_object('error', TRUE, 'message', 'Free tier limited to 7 days only');
    END IF;
    
    IF NOT p_is_premium AND p_touchpoint_ids IS NOT NULL AND array_length(p_touchpoint_ids, 1) > 1 THEN
        RETURN json_build_object('error', TRUE, 'message', 'Free tier limited to 1 touchpoint only');
    END IF;

    -- Calculate date range in user's timezone
    end_date := CURRENT_TIMESTAMP AT TIME ZONE p_timezone;
    start_date := end_date - (p_period_days || ' days')::INTERVAL;
    
    WITH filtered_visits AS (
        -- JOIN visits with touch_points to get UTM data
        SELECT 
            v.referrer,
            v.fp,
            v.type,
            v.created_at,
            v.tp_id,
            v.platform,
            v.country,
            tp.name as touchpoint_name,
            tp.utm_tags,
            -- Extract UTM parameters from touch_points.utm_tags JSONB column
            COALESCE(tp.utm_tags->>'utm_campaign', 'no_campaign') as utm_campaign,
            COALESCE(tp.utm_tags->>'utm_source', 'unknown') as utm_source,
            COALESCE(tp.utm_tags->>'utm_medium', 'unknown') as utm_medium,
            COALESCE(tp.utm_tags->>'utm_content', 'no_content') as utm_content,
            COALESCE(tp.utm_tags->>'utm_term', 'no_term') as utm_term,
            -- Check if UTM is enabled for this touchpoint
            COALESCE((tp.utm_tags->>'enabled')::boolean, false) as utm_enabled
        FROM visits v
        INNER JOIN touch_points tp ON v.tp_id = tp.id
        WHERE v.organization_id = p_organization_id
            AND v.created_at >= start_date
            AND v.created_at < end_date            
            AND tp.deleted_at IS NULL
            AND tp.utm_tags IS NOT NULL  -- Only touchpoints with UTM configuration
            AND COALESCE((tp.utm_tags->>'enabled')::boolean, false) = true  -- Only enabled UTM tracking
            AND (
                -- No filtering if no filters specified
                (p_tag_ids IS NULL AND p_touchpoint_ids IS NULL)
                OR 
                -- Apply hierarchical filtering: tags first, then touchpoints
                (
                    (p_tag_ids IS NULL OR v.tp_id IN (
                        SELECT DISTINCT ttl.tp_id 
                        FROM tp_tag_links ttl 
                        WHERE ttl.tag_id = ANY(p_tag_ids)
                    ))
                    AND
                    (p_touchpoint_ids IS NULL OR v.tp_id = ANY(p_touchpoint_ids))
                )
            )
            AND (
                p_collection_ids IS NULL
                OR v.tp_id IN (
                    SELECT tp.id
                    FROM touch_points tp
                    WHERE tp.collection_id = ANY(p_collection_ids)
                       OR (p_include_null_collection AND tp.collection_id IS NULL)
                )
            )
    ),
    campaign_aggregation AS (
        -- Campaign-level performance analysis
        SELECT 
            utm_campaign,
            utm_source,
            utm_medium,
            -- Touchpoint information
            COUNT(DISTINCT tp_id) as touchpoints_in_campaign,
            json_agg(DISTINCT touchpoint_name) as touchpoint_names,
            COUNT(*) as total_visits,
            COUNT(DISTINCT fp) as unique_users,
            COUNT(DISTINCT country) as countries_reached,
            COUNT(DISTINCT DATE(created_at AT TIME ZONE p_timezone)) as active_days,
            -- Interaction breakdown
            COUNT(CASE WHEN type = 'LINK' THEN 1 END) as link_interactions,
            COUNT(CASE WHEN type = 'QR' THEN 1 END) as qr_interactions,
            COUNT(CASE WHEN type = 'NFC' THEN 1 END) as nfc_interactions,
            COUNT(CASE WHEN type = 'WIFI' THEN 1 END) as wifi_interactions,
            -- Engagement metrics
            ROUND(COUNT(*)::DECIMAL / NULLIF(COUNT(DISTINCT fp), 0), 2) as visits_per_user,
            -- Platform distribution
            COUNT(CASE WHEN platform = 'Mobile' THEN 1 END) as mobile_visits,
            COUNT(CASE WHEN platform = 'Desktop' THEN 1 END) as desktop_visits,
            -- Time-based patterns (Premium insight)
            COUNT(CASE WHEN EXTRACT(dow FROM created_at AT TIME ZONE p_timezone) BETWEEN 1 AND 5 THEN 1 END) as weekday_visits,
            COUNT(CASE WHEN EXTRACT(dow FROM created_at AT TIME ZONE p_timezone) IN (0, 6) THEN 1 END) as weekend_visits,
            COUNT(CASE WHEN EXTRACT(hour FROM created_at AT TIME ZONE p_timezone) BETWEEN 9 AND 17 THEN 1 END) as business_hours_visits,
            -- User retention analysis (Premium)
            COUNT(DISTINCT fp) FILTER (
                WHERE fp IN (
                    SELECT fp 
                    FROM filtered_visits 
                    GROUP BY fp 
                    HAVING COUNT(*) > 1
                )
            ) as repeat_users,
            -- Campaign timeframe
            MIN(created_at) as campaign_start,
            MAX(created_at) as campaign_end,
            EXTRACT(EPOCH FROM (MAX(created_at) - MIN(created_at))) / 3600 as campaign_duration_hours
        FROM filtered_visits
        GROUP BY utm_campaign, utm_source, utm_medium
    ),
    campaign_performance_scoring AS (
        -- Calculate performance scores for campaigns
        SELECT 
            *,
            -- Market share calculation
            ROUND(total_visits::DECIMAL / SUM(total_visits) OVER() * 100, 1) as campaign_share_pct,
            -- Performance score components
            CASE 
                WHEN visits_per_user >= 3.0 THEN 30
                WHEN visits_per_user >= 2.0 THEN 25
                WHEN visits_per_user >= 1.5 THEN 20
                WHEN visits_per_user >= 1.2 THEN 15
                ELSE 10
            END as engagement_score,
            
            CASE 
                WHEN total_visits >= 500 THEN 25
                WHEN total_visits >= 100 THEN 20
                WHEN total_visits >= 50 THEN 15
                WHEN total_visits >= 10 THEN 10
                ELSE 5
            END as volume_score,
            
            CASE 
                WHEN countries_reached >= 5 THEN 20
                WHEN countries_reached >= 3 THEN 15
                WHEN countries_reached >= 2 THEN 10
                ELSE 5
            END as reach_score,
            
            CASE 
                WHEN active_days >= p_period_days * 0.8 THEN 15
                WHEN active_days >= p_period_days * 0.5 THEN 12
                WHEN active_days >= p_period_days * 0.3 THEN 8
                ELSE 5
            END as consistency_score,
            
            CASE 
                WHEN touchpoints_in_campaign >= 3 THEN 10
                WHEN touchpoints_in_campaign >= 2 THEN 7
                ELSE 5
            END as touchpoint_diversity_score,
            
            -- Repeat user rate
            ROUND(repeat_users::DECIMAL / NULLIF(unique_users, 0) * 100, 1) as repeat_user_rate
        FROM campaign_aggregation
    ),
    source_medium_analysis AS (
        -- Analyze utm_source and utm_medium combinations
        SELECT 
            utm_source,
            utm_medium,
            CONCAT(utm_source, ' / ', utm_medium) as source_medium_combo,
            COUNT(DISTINCT utm_campaign) as campaigns_count,
            SUM(total_visits) as total_visits,
            SUM(unique_users) as total_unique_users,
            SUM(touchpoints_in_campaign) as total_touchpoints_used,
            ROUND(AVG(visits_per_user), 2) as avg_engagement,
            ROUND(SUM(total_visits)::DECIMAL / SUM(SUM(total_visits)) OVER() * 100, 1) as combo_share_pct,
            ROW_NUMBER() OVER (ORDER BY SUM(total_visits) DESC) as combo_rank
        FROM campaign_performance_scoring
        GROUP BY utm_source, utm_medium
    ),
    final_campaign_ranking AS (
        -- Final campaign ranking with performance scores
        SELECT 
            *,
            (engagement_score + volume_score + reach_score + consistency_score + touchpoint_diversity_score) as performance_score,
            ROW_NUMBER() OVER (ORDER BY total_visits DESC) as volume_rank,
            ROW_NUMBER() OVER (ORDER BY visits_per_user DESC) as engagement_rank,
            ROW_NUMBER() OVER (ORDER BY (engagement_score + volume_score + reach_score + consistency_score + touchpoint_diversity_score) DESC) as performance_rank,
            -- Performance tier classification
            CASE 
                WHEN (engagement_score + volume_score + reach_score + consistency_score + touchpoint_diversity_score) >= 80 THEN 'top_performer'
                WHEN (engagement_score + volume_score + reach_score + consistency_score + touchpoint_diversity_score) >= 60 THEN 'good_performer'
                WHEN (engagement_score + volume_score + reach_score + consistency_score + touchpoint_diversity_score) >= 40 THEN 'average_performer'
                ELSE 'underperformer'
            END as performance_tier
        FROM campaign_performance_scoring
    ),
    campaign_summary AS (
        -- Summary statistics
        SELECT 
            COUNT(*) as total_campaigns,
            COUNT(DISTINCT utm_source) as total_sources,
            COUNT(DISTINCT utm_medium) as total_mediums,
            SUM(total_visits) as total_campaign_visits,
            SUM(unique_users) as total_campaign_users,
            SUM(touchpoints_in_campaign) as total_touchpoints_with_utm,
            ROUND(AVG(visits_per_user), 2) as avg_campaign_engagement,
            ROUND(AVG(performance_score), 1) as avg_performance_score
        FROM final_campaign_ranking
    )
    SELECT json_build_object(
        'period_info', json_build_object(
            'period_days', p_period_days,
            'start_date', start_date,
            'end_date', end_date,
            'timezone', p_timezone,
            'is_premium', p_is_premium,
            'data_requirement', 'UTM-enabled touchpoints required'
        ),
        'filters_applied', json_build_object(
            'has_filters', (p_tag_ids IS NOT NULL OR p_touchpoint_ids IS NOT NULL),
            'tags_count', COALESCE(array_length(p_tag_ids, 1), 0),
            'touchpoints_count', COALESCE(array_length(p_touchpoint_ids, 1), 0)
        ),
        'campaign_performance', json_build_object(
            -- Tier-specific campaign data
            'campaigns', CASE 
                WHEN p_is_premium THEN
                    -- Premium: Full campaign list with performance scoring
                    (
                        SELECT json_agg(
                            json_build_object(
                                'utm_campaign', fcr.utm_campaign,
                                'utm_source', fcr.utm_source,
                                'utm_medium', fcr.utm_medium,
                                'touchpoints_in_campaign', fcr.touchpoints_in_campaign,
                                'touchpoint_names', fcr.touchpoint_names,
                                'volume_rank', fcr.volume_rank,
                                'engagement_rank', fcr.engagement_rank,
                                'performance_rank', fcr.performance_rank,
                                'performance_score', fcr.performance_score,
                                'performance_tier', fcr.performance_tier,
                                'total_visits', fcr.total_visits,
                                'unique_users', fcr.unique_users,
                                'campaign_share_pct', fcr.campaign_share_pct,
                                'visits_per_user', fcr.visits_per_user,
                                'repeat_user_rate', fcr.repeat_user_rate,
                                'countries_reached', fcr.countries_reached,
                                'active_days', fcr.active_days,
                                'campaign_duration_hours', ROUND(fcr.campaign_duration_hours, 1),
                                'platform_distribution', json_build_object(
                                    'mobile_visits', fcr.mobile_visits,
                                    'desktop_visits', fcr.desktop_visits,
                                    'mobile_pct', ROUND(fcr.mobile_visits::DECIMAL / fcr.total_visits * 100, 1)
                                ),
                                'time_patterns', json_build_object(
                                    'weekday_visits', fcr.weekday_visits,
                                    'weekend_visits', fcr.weekend_visits,
                                    'business_hours_visits', fcr.business_hours_visits,
                                    'weekend_pct', ROUND(fcr.weekend_visits::DECIMAL / fcr.total_visits * 100, 1),
                                    'business_hours_pct', ROUND(fcr.business_hours_visits::DECIMAL / fcr.total_visits * 100, 1)
                                ),
                                'interaction_breakdown', json_build_object(
                                    'link_interactions', fcr.link_interactions,
                                    'qr_interactions', fcr.qr_interactions,
                                    'nfc_interactions', fcr.nfc_interactions,
                                    'wifi_interactions', fcr.wifi_interactions
                                ),
                                'performance_breakdown', json_build_object(
                                    'engagement_score', fcr.engagement_score,
                                    'volume_score', fcr.volume_score,
                                    'reach_score', fcr.reach_score,
                                    'consistency_score', fcr.consistency_score,
                                    'touchpoint_diversity_score', fcr.touchpoint_diversity_score
                                )
                            ) ORDER BY fcr.performance_rank
                        )
                        FROM final_campaign_ranking fcr
                    )
                ELSE
                    -- Free: Top 5 campaigns by volume only
                    (
                        SELECT json_agg(
                            json_build_object(
                                'utm_campaign', fcr.utm_campaign,
                                'utm_source', fcr.utm_source,
                                'utm_medium', fcr.utm_medium,
                                'touchpoints_in_campaign', fcr.touchpoints_in_campaign,
                                'volume_rank', fcr.volume_rank,
                                'total_visits', fcr.total_visits,
                                'unique_users', fcr.unique_users,
                                'campaign_share_pct', fcr.campaign_share_pct,
                                'visits_per_user', fcr.visits_per_user
                            ) ORDER BY fcr.volume_rank
                        )
                        FROM final_campaign_ranking fcr
                        WHERE fcr.volume_rank <= 5
                    )
            END,
            -- Source/Medium analysis (Premium only)
            'source_medium_combinations', CASE 
                WHEN p_is_premium THEN
                    (
                        SELECT json_agg(
                            json_build_object(
                                'source_medium_combo', sma.source_medium_combo,
                                'utm_source', sma.utm_source,
                                'utm_medium', sma.utm_medium,
                                'combo_rank', sma.combo_rank,
                                'campaigns_count', sma.campaigns_count,
                                'total_visits', sma.total_visits,
                                'total_unique_users', sma.total_unique_users,
                                'total_touchpoints_used', sma.total_touchpoints_used,
                                'avg_engagement', sma.avg_engagement,
                                'combo_share_pct', sma.combo_share_pct
                            ) ORDER BY sma.combo_rank
                        )
                        FROM source_medium_analysis sma
                        WHERE sma.combo_rank <= 10  -- Top 10 combinations
                    )
                ELSE 
                    NULL
            END,
            -- Summary with tier-appropriate data
            'summary', (
                SELECT json_build_object(
                    'total_campaigns', cs.total_campaigns,
                    'total_sources', cs.total_sources,
                    'total_mediums', cs.total_mediums,
                    'total_touchpoints_with_utm', cs.total_touchpoints_with_utm,
                    'campaigns_shown', CASE WHEN p_is_premium THEN cs.total_campaigns ELSE LEAST(5, cs.total_campaigns) END,
                    'total_campaign_visits', cs.total_campaign_visits,
                    'total_campaign_users', cs.total_campaign_users,
                    'avg_campaign_engagement', cs.avg_campaign_engagement,
                    'avg_performance_score', CASE WHEN p_is_premium THEN cs.avg_performance_score ELSE NULL END,
                    'data_completeness', CASE 
                        WHEN cs.total_campaigns = 0 THEN 'no_utm_enabled_touchpoints'
                        WHEN cs.total_campaigns < 3 THEN 'limited_campaign_data'
                        ELSE 'sufficient_data'
                    END
                )
                FROM campaign_summary cs
            )
        ),
        'insights', json_build_object(
            -- Basic insights (both tiers)
            'top_campaign', (
                SELECT json_build_object(
                    'utm_campaign', fcr.utm_campaign,
                    'utm_source', fcr.utm_source,
                    'utm_medium', fcr.utm_medium,
                    'visits', fcr.total_visits,
                    'touchpoints_used', fcr.touchpoints_in_campaign,
                    'market_share_pct', fcr.campaign_share_pct,
                    'engagement_rate', fcr.visits_per_user
                )
                FROM final_campaign_ranking fcr
                WHERE fcr.volume_rank = 1
            ),
            'utm_setup_status', (
                SELECT json_build_object(
                    'total_touchpoints_analyzed', (
                        SELECT COUNT(DISTINCT tp_id) 
                        FROM filtered_visits
                    ),
                    'message', CASE 
                        WHEN (SELECT COUNT(*) FROM campaign_summary) = 0 THEN 
                            'No UTM-enabled touchpoints found. Enable UTM tracking on touchpoints to see campaign data.'
                        ELSE 'Campaign tracking active'
                    END
                )
            ),
            -- Premium-only insights
            'premium_insights', CASE 
                WHEN p_is_premium THEN
                    json_build_object(
                        'best_performing_campaign', (
                            SELECT json_build_object(
                                'utm_campaign', fcr.utm_campaign,
                                'utm_source', fcr.utm_source,
                                'utm_medium', fcr.utm_medium,
                                'performance_score', fcr.performance_score,
                                'performance_tier', fcr.performance_tier,
                                'visits_per_user', fcr.visits_per_user,
                                'repeat_user_rate', fcr.repeat_user_rate,
                                'touchpoints_used', fcr.touchpoints_in_campaign
                            )
                            FROM final_campaign_ranking fcr
                            WHERE fcr.performance_rank = 1
                        ),
                        'top_source_medium', (
                            SELECT json_build_object(
                                'combo', sma.source_medium_combo,
                                'campaigns_count', sma.campaigns_count,
                                'total_visits', sma.total_visits,
                                'avg_engagement', sma.avg_engagement,
                                'market_share_pct', sma.combo_share_pct
                            )
                            FROM source_medium_analysis sma
                            WHERE sma.combo_rank = 1
                        ),
                        'campaign_recommendations', (
                            SELECT json_agg(recommendation)
                            FROM (
                                SELECT CASE 
                                    WHEN fcr.performance_tier = 'top_performer' AND fcr.campaign_share_pct < 15 THEN 
                                        CONCAT('Scale up "', fcr.utm_campaign, '" campaign - high performance, low volume')
                                    WHEN fcr.performance_tier = 'underperformer' AND fcr.campaign_share_pct > 10 THEN 
                                        CONCAT('Optimize or pause "', fcr.utm_campaign, '" - high volume, low performance')
                                    WHEN fcr.repeat_user_rate < 15 AND fcr.total_visits > 100 THEN 
                                        CONCAT('Improve "', fcr.utm_campaign, '" retention strategy - low repeat rate')
                                    WHEN fcr.touchpoints_in_campaign = 1 AND fcr.total_visits > 200 THEN 
                                        CONCAT('Expand "', fcr.utm_campaign, '" to more touchpoints for better reach')
                                    ELSE NULL
                                END as recommendation
                                FROM final_campaign_ranking fcr
                                WHERE fcr.total_visits >= 20  -- Only meaningful data
                            ) recommendations
                            WHERE recommendation IS NOT NULL
                        ),
                        'performance_distribution', json_build_object(
                            'top_performers', (SELECT COUNT(*) FROM final_campaign_ranking WHERE performance_tier = 'top_performer'),
                            'good_performers', (SELECT COUNT(*) FROM final_campaign_ranking WHERE performance_tier = 'good_performer'),
                            'average_performers', (SELECT COUNT(*) FROM final_campaign_ranking WHERE performance_tier = 'average_performer'),
                            'underperformers', (SELECT COUNT(*) FROM final_campaign_ranking WHERE performance_tier = 'underperformer')
                        )
                    )
                ELSE 
                    NULL
            END
        )
    ) INTO result;
    
    RETURN result;
    
EXCEPTION WHEN OTHERS THEN
    RETURN json_build_object(
        'error', TRUE,
        'message', SQLERRM,
        'organization_id', p_organization_id
    );
END;
$$;


--
-- Name: get_acquisition_campaign_performance_old(uuid, integer, text, uuid[], uuid[], boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_acquisition_campaign_performance_old(p_organization_id uuid, p_period_days integer, p_timezone text DEFAULT 'UTC'::text, p_tag_ids uuid[] DEFAULT NULL::uuid[], p_touchpoint_ids uuid[] DEFAULT NULL::uuid[], p_is_premium boolean DEFAULT false) RETURNS json
    LANGUAGE plpgsql
    AS $$DECLARE
    start_date TIMESTAMPTZ;
    end_date TIMESTAMPTZ;
    result JSON;
BEGIN
    -- Validate tier restrictions
    IF NOT p_is_premium AND p_period_days != 7 THEN
        RETURN json_build_object('error', TRUE, 'message', 'Free tier limited to 7 days only');
    END IF;
    
    IF NOT p_is_premium AND p_touchpoint_ids IS NOT NULL AND array_length(p_touchpoint_ids, 1) > 1 THEN
        RETURN json_build_object('error', TRUE, 'message', 'Free tier limited to 1 touchpoint only');
    END IF;

    -- Calculate date range in user's timezone
    end_date := CURRENT_TIMESTAMP AT TIME ZONE p_timezone;
    start_date := end_date - (p_period_days || ' days')::INTERVAL;
    
    WITH filtered_visits AS (
        -- JOIN visits with touch_points to get UTM data
        SELECT 
            v.referrer,
            v.fp,
            v.type,
            v.created_at,
            v.tp_id,
            v.platform,
            v.country,
            tp.name as touchpoint_name,
            tp.utm_tags,
            -- Extract UTM parameters from touch_points.utm_tags JSONB column
            COALESCE(tp.utm_tags->>'utm_campaign', 'no_campaign') as utm_campaign,
            COALESCE(tp.utm_tags->>'utm_source', 'unknown') as utm_source,
            COALESCE(tp.utm_tags->>'utm_medium', 'unknown') as utm_medium,
            COALESCE(tp.utm_tags->>'utm_content', 'no_content') as utm_content,
            COALESCE(tp.utm_tags->>'utm_term', 'no_term') as utm_term,
            -- Check if UTM is enabled for this touchpoint
            COALESCE((tp.utm_tags->>'enabled')::boolean, false) as utm_enabled
        FROM visits v
        INNER JOIN touch_points tp ON v.tp_id = tp.id
        WHERE v.organization_id = p_organization_id
            AND v.created_at >= start_date
            AND v.created_at < end_date            
            AND tp.deleted_at IS NULL
            AND tp.utm_tags IS NOT NULL  -- Only touchpoints with UTM configuration
            AND COALESCE((tp.utm_tags->>'enabled')::boolean, false) = true  -- Only enabled UTM tracking
            AND (
                -- No filtering if no filters specified
                (p_tag_ids IS NULL AND p_touchpoint_ids IS NULL)
                OR 
                -- Apply hierarchical filtering: tags first, then touchpoints
                (
                    (p_tag_ids IS NULL OR v.tp_id IN (
                        SELECT DISTINCT ttl.tp_id 
                        FROM tp_tag_links ttl 
                        WHERE ttl.tag_id = ANY(p_tag_ids)
                    ))
                    AND
                    (p_touchpoint_ids IS NULL OR v.tp_id = ANY(p_touchpoint_ids))
                )
            )
    ),
    campaign_aggregation AS (
        -- Campaign-level performance analysis
        SELECT 
            utm_campaign,
            utm_source,
            utm_medium,
            -- Touchpoint information
            COUNT(DISTINCT tp_id) as touchpoints_in_campaign,
            json_agg(DISTINCT touchpoint_name) as touchpoint_names,
            COUNT(*) as total_visits,
            COUNT(DISTINCT fp) as unique_users,
            COUNT(DISTINCT country) as countries_reached,
            COUNT(DISTINCT DATE(created_at AT TIME ZONE p_timezone)) as active_days,
            -- Interaction breakdown
            COUNT(CASE WHEN type = 'LINK' THEN 1 END) as link_interactions,
            COUNT(CASE WHEN type = 'QR' THEN 1 END) as qr_interactions,
            COUNT(CASE WHEN type = 'NFC' THEN 1 END) as nfc_interactions,
            COUNT(CASE WHEN type = 'WIFI' THEN 1 END) as wifi_interactions,
            -- Engagement metrics
            ROUND(COUNT(*)::DECIMAL / NULLIF(COUNT(DISTINCT fp), 0), 2) as visits_per_user,
            -- Platform distribution
            COUNT(CASE WHEN platform = 'Mobile' THEN 1 END) as mobile_visits,
            COUNT(CASE WHEN platform = 'Desktop' THEN 1 END) as desktop_visits,
            -- Time-based patterns (Premium insight)
            COUNT(CASE WHEN EXTRACT(dow FROM created_at AT TIME ZONE p_timezone) BETWEEN 1 AND 5 THEN 1 END) as weekday_visits,
            COUNT(CASE WHEN EXTRACT(dow FROM created_at AT TIME ZONE p_timezone) IN (0, 6) THEN 1 END) as weekend_visits,
            COUNT(CASE WHEN EXTRACT(hour FROM created_at AT TIME ZONE p_timezone) BETWEEN 9 AND 17 THEN 1 END) as business_hours_visits,
            -- User retention analysis (Premium)
            COUNT(DISTINCT fp) FILTER (
                WHERE fp IN (
                    SELECT fp 
                    FROM filtered_visits 
                    GROUP BY fp 
                    HAVING COUNT(*) > 1
                )
            ) as repeat_users,
            -- Campaign timeframe
            MIN(created_at) as campaign_start,
            MAX(created_at) as campaign_end,
            EXTRACT(EPOCH FROM (MAX(created_at) - MIN(created_at))) / 3600 as campaign_duration_hours
        FROM filtered_visits
        GROUP BY utm_campaign, utm_source, utm_medium
    ),
    campaign_performance_scoring AS (
        -- Calculate performance scores for campaigns
        SELECT 
            *,
            -- Market share calculation
            ROUND(total_visits::DECIMAL / SUM(total_visits) OVER() * 100, 1) as campaign_share_pct,
            -- Performance score components
            CASE 
                WHEN visits_per_user >= 3.0 THEN 30
                WHEN visits_per_user >= 2.0 THEN 25
                WHEN visits_per_user >= 1.5 THEN 20
                WHEN visits_per_user >= 1.2 THEN 15
                ELSE 10
            END as engagement_score,
            
            CASE 
                WHEN total_visits >= 500 THEN 25
                WHEN total_visits >= 100 THEN 20
                WHEN total_visits >= 50 THEN 15
                WHEN total_visits >= 10 THEN 10
                ELSE 5
            END as volume_score,
            
            CASE 
                WHEN countries_reached >= 5 THEN 20
                WHEN countries_reached >= 3 THEN 15
                WHEN countries_reached >= 2 THEN 10
                ELSE 5
            END as reach_score,
            
            CASE 
                WHEN active_days >= p_period_days * 0.8 THEN 15
                WHEN active_days >= p_period_days * 0.5 THEN 12
                WHEN active_days >= p_period_days * 0.3 THEN 8
                ELSE 5
            END as consistency_score,
            
            CASE 
                WHEN touchpoints_in_campaign >= 3 THEN 10
                WHEN touchpoints_in_campaign >= 2 THEN 7
                ELSE 5
            END as touchpoint_diversity_score,
            
            -- Repeat user rate
            ROUND(repeat_users::DECIMAL / NULLIF(unique_users, 0) * 100, 1) as repeat_user_rate
        FROM campaign_aggregation
    ),
    source_medium_analysis AS (
        -- Analyze utm_source and utm_medium combinations
        SELECT 
            utm_source,
            utm_medium,
            CONCAT(utm_source, ' / ', utm_medium) as source_medium_combo,
            COUNT(DISTINCT utm_campaign) as campaigns_count,
            SUM(total_visits) as total_visits,
            SUM(unique_users) as total_unique_users,
            SUM(touchpoints_in_campaign) as total_touchpoints_used,
            ROUND(AVG(visits_per_user), 2) as avg_engagement,
            ROUND(SUM(total_visits)::DECIMAL / SUM(SUM(total_visits)) OVER() * 100, 1) as combo_share_pct,
            ROW_NUMBER() OVER (ORDER BY SUM(total_visits) DESC) as combo_rank
        FROM campaign_performance_scoring
        GROUP BY utm_source, utm_medium
    ),
    final_campaign_ranking AS (
        -- Final campaign ranking with performance scores
        SELECT 
            *,
            (engagement_score + volume_score + reach_score + consistency_score + touchpoint_diversity_score) as performance_score,
            ROW_NUMBER() OVER (ORDER BY total_visits DESC) as volume_rank,
            ROW_NUMBER() OVER (ORDER BY visits_per_user DESC) as engagement_rank,
            ROW_NUMBER() OVER (ORDER BY (engagement_score + volume_score + reach_score + consistency_score + touchpoint_diversity_score) DESC) as performance_rank,
            -- Performance tier classification
            CASE 
                WHEN (engagement_score + volume_score + reach_score + consistency_score + touchpoint_diversity_score) >= 80 THEN 'top_performer'
                WHEN (engagement_score + volume_score + reach_score + consistency_score + touchpoint_diversity_score) >= 60 THEN 'good_performer'
                WHEN (engagement_score + volume_score + reach_score + consistency_score + touchpoint_diversity_score) >= 40 THEN 'average_performer'
                ELSE 'underperformer'
            END as performance_tier
        FROM campaign_performance_scoring
    ),
    campaign_summary AS (
        -- Summary statistics
        SELECT 
            COUNT(*) as total_campaigns,
            COUNT(DISTINCT utm_source) as total_sources,
            COUNT(DISTINCT utm_medium) as total_mediums,
            SUM(total_visits) as total_campaign_visits,
            SUM(unique_users) as total_campaign_users,
            SUM(touchpoints_in_campaign) as total_touchpoints_with_utm,
            ROUND(AVG(visits_per_user), 2) as avg_campaign_engagement,
            ROUND(AVG(performance_score), 1) as avg_performance_score
        FROM final_campaign_ranking
    )
    SELECT json_build_object(
        'period_info', json_build_object(
            'period_days', p_period_days,
            'start_date', start_date,
            'end_date', end_date,
            'timezone', p_timezone,
            'is_premium', p_is_premium,
            'data_requirement', 'UTM-enabled touchpoints required'
        ),
        'filters_applied', json_build_object(
            'has_filters', (p_tag_ids IS NOT NULL OR p_touchpoint_ids IS NOT NULL),
            'tags_count', COALESCE(array_length(p_tag_ids, 1), 0),
            'touchpoints_count', COALESCE(array_length(p_touchpoint_ids, 1), 0)
        ),
        'campaign_performance', json_build_object(
            -- Tier-specific campaign data
            'campaigns', CASE 
                WHEN p_is_premium THEN
                    -- Premium: Full campaign list with performance scoring
                    (
                        SELECT json_agg(
                            json_build_object(
                                'utm_campaign', fcr.utm_campaign,
                                'utm_source', fcr.utm_source,
                                'utm_medium', fcr.utm_medium,
                                'touchpoints_in_campaign', fcr.touchpoints_in_campaign,
                                'touchpoint_names', fcr.touchpoint_names,
                                'volume_rank', fcr.volume_rank,
                                'engagement_rank', fcr.engagement_rank,
                                'performance_rank', fcr.performance_rank,
                                'performance_score', fcr.performance_score,
                                'performance_tier', fcr.performance_tier,
                                'total_visits', fcr.total_visits,
                                'unique_users', fcr.unique_users,
                                'campaign_share_pct', fcr.campaign_share_pct,
                                'visits_per_user', fcr.visits_per_user,
                                'repeat_user_rate', fcr.repeat_user_rate,
                                'countries_reached', fcr.countries_reached,
                                'active_days', fcr.active_days,
                                'campaign_duration_hours', ROUND(fcr.campaign_duration_hours, 1),
                                'platform_distribution', json_build_object(
                                    'mobile_visits', fcr.mobile_visits,
                                    'desktop_visits', fcr.desktop_visits,
                                    'mobile_pct', ROUND(fcr.mobile_visits::DECIMAL / fcr.total_visits * 100, 1)
                                ),
                                'time_patterns', json_build_object(
                                    'weekday_visits', fcr.weekday_visits,
                                    'weekend_visits', fcr.weekend_visits,
                                    'business_hours_visits', fcr.business_hours_visits,
                                    'weekend_pct', ROUND(fcr.weekend_visits::DECIMAL / fcr.total_visits * 100, 1),
                                    'business_hours_pct', ROUND(fcr.business_hours_visits::DECIMAL / fcr.total_visits * 100, 1)
                                ),
                                'interaction_breakdown', json_build_object(
                                    'link_interactions', fcr.link_interactions,
                                    'qr_interactions', fcr.qr_interactions,
                                    'nfc_interactions', fcr.nfc_interactions,
                                    'wifi_interactions', fcr.wifi_interactions
                                ),
                                'performance_breakdown', json_build_object(
                                    'engagement_score', fcr.engagement_score,
                                    'volume_score', fcr.volume_score,
                                    'reach_score', fcr.reach_score,
                                    'consistency_score', fcr.consistency_score,
                                    'touchpoint_diversity_score', fcr.touchpoint_diversity_score
                                )
                            ) ORDER BY fcr.performance_rank
                        )
                        FROM final_campaign_ranking fcr
                    )
                ELSE
                    -- Free: Top 5 campaigns by volume only
                    (
                        SELECT json_agg(
                            json_build_object(
                                'utm_campaign', fcr.utm_campaign,
                                'utm_source', fcr.utm_source,
                                'utm_medium', fcr.utm_medium,
                                'touchpoints_in_campaign', fcr.touchpoints_in_campaign,
                                'volume_rank', fcr.volume_rank,
                                'total_visits', fcr.total_visits,
                                'unique_users', fcr.unique_users,
                                'campaign_share_pct', fcr.campaign_share_pct,
                                'visits_per_user', fcr.visits_per_user
                            ) ORDER BY fcr.volume_rank
                        )
                        FROM final_campaign_ranking fcr
                        WHERE fcr.volume_rank <= 5
                    )
            END,
            -- Source/Medium analysis (Premium only)
            'source_medium_combinations', CASE 
                WHEN p_is_premium THEN
                    (
                        SELECT json_agg(
                            json_build_object(
                                'source_medium_combo', sma.source_medium_combo,
                                'utm_source', sma.utm_source,
                                'utm_medium', sma.utm_medium,
                                'combo_rank', sma.combo_rank,
                                'campaigns_count', sma.campaigns_count,
                                'total_visits', sma.total_visits,
                                'total_unique_users', sma.total_unique_users,
                                'total_touchpoints_used', sma.total_touchpoints_used,
                                'avg_engagement', sma.avg_engagement,
                                'combo_share_pct', sma.combo_share_pct
                            ) ORDER BY sma.combo_rank
                        )
                        FROM source_medium_analysis sma
                        WHERE sma.combo_rank <= 10  -- Top 10 combinations
                    )
                ELSE 
                    NULL
            END,
            -- Summary with tier-appropriate data
            'summary', (
                SELECT json_build_object(
                    'total_campaigns', cs.total_campaigns,
                    'total_sources', cs.total_sources,
                    'total_mediums', cs.total_mediums,
                    'total_touchpoints_with_utm', cs.total_touchpoints_with_utm,
                    'campaigns_shown', CASE WHEN p_is_premium THEN cs.total_campaigns ELSE LEAST(5, cs.total_campaigns) END,
                    'total_campaign_visits', cs.total_campaign_visits,
                    'total_campaign_users', cs.total_campaign_users,
                    'avg_campaign_engagement', cs.avg_campaign_engagement,
                    'avg_performance_score', CASE WHEN p_is_premium THEN cs.avg_performance_score ELSE NULL END,
                    'data_completeness', CASE 
                        WHEN cs.total_campaigns = 0 THEN 'no_utm_enabled_touchpoints'
                        WHEN cs.total_campaigns < 3 THEN 'limited_campaign_data'
                        ELSE 'sufficient_data'
                    END
                )
                FROM campaign_summary cs
            )
        ),
        'insights', json_build_object(
            -- Basic insights (both tiers)
            'top_campaign', (
                SELECT json_build_object(
                    'utm_campaign', fcr.utm_campaign,
                    'utm_source', fcr.utm_source,
                    'utm_medium', fcr.utm_medium,
                    'visits', fcr.total_visits,
                    'touchpoints_used', fcr.touchpoints_in_campaign,
                    'market_share_pct', fcr.campaign_share_pct,
                    'engagement_rate', fcr.visits_per_user
                )
                FROM final_campaign_ranking fcr
                WHERE fcr.volume_rank = 1
            ),
            'utm_setup_status', (
                SELECT json_build_object(
                    'total_touchpoints_analyzed', (
                        SELECT COUNT(DISTINCT tp_id) 
                        FROM filtered_visits
                    ),
                    'message', CASE 
                        WHEN (SELECT COUNT(*) FROM campaign_summary) = 0 THEN 
                            'No UTM-enabled touchpoints found. Enable UTM tracking on touchpoints to see campaign data.'
                        ELSE 'Campaign tracking active'
                    END
                )
            ),
            -- Premium-only insights
            'premium_insights', CASE 
                WHEN p_is_premium THEN
                    json_build_object(
                        'best_performing_campaign', (
                            SELECT json_build_object(
                                'utm_campaign', fcr.utm_campaign,
                                'utm_source', fcr.utm_source,
                                'utm_medium', fcr.utm_medium,
                                'performance_score', fcr.performance_score,
                                'performance_tier', fcr.performance_tier,
                                'visits_per_user', fcr.visits_per_user,
                                'repeat_user_rate', fcr.repeat_user_rate,
                                'touchpoints_used', fcr.touchpoints_in_campaign
                            )
                            FROM final_campaign_ranking fcr
                            WHERE fcr.performance_rank = 1
                        ),
                        'top_source_medium', (
                            SELECT json_build_object(
                                'combo', sma.source_medium_combo,
                                'campaigns_count', sma.campaigns_count,
                                'total_visits', sma.total_visits,
                                'avg_engagement', sma.avg_engagement,
                                'market_share_pct', sma.combo_share_pct
                            )
                            FROM source_medium_analysis sma
                            WHERE sma.combo_rank = 1
                        ),
                        'campaign_recommendations', (
                            SELECT json_agg(recommendation)
                            FROM (
                                SELECT CASE 
                                    WHEN fcr.performance_tier = 'top_performer' AND fcr.campaign_share_pct < 15 THEN 
                                        CONCAT('Scale up "', fcr.utm_campaign, '" campaign - high performance, low volume')
                                    WHEN fcr.performance_tier = 'underperformer' AND fcr.campaign_share_pct > 10 THEN 
                                        CONCAT('Optimize or pause "', fcr.utm_campaign, '" - high volume, low performance')
                                    WHEN fcr.repeat_user_rate < 15 AND fcr.total_visits > 100 THEN 
                                        CONCAT('Improve "', fcr.utm_campaign, '" retention strategy - low repeat rate')
                                    WHEN fcr.touchpoints_in_campaign = 1 AND fcr.total_visits > 200 THEN 
                                        CONCAT('Expand "', fcr.utm_campaign, '" to more touchpoints for better reach')
                                    ELSE NULL
                                END as recommendation
                                FROM final_campaign_ranking fcr
                                WHERE fcr.total_visits >= 20  -- Only meaningful data
                            ) recommendations
                            WHERE recommendation IS NOT NULL
                        ),
                        'performance_distribution', json_build_object(
                            'top_performers', (SELECT COUNT(*) FROM final_campaign_ranking WHERE performance_tier = 'top_performer'),
                            'good_performers', (SELECT COUNT(*) FROM final_campaign_ranking WHERE performance_tier = 'good_performer'),
                            'average_performers', (SELECT COUNT(*) FROM final_campaign_ranking WHERE performance_tier = 'average_performer'),
                            'underperformers', (SELECT COUNT(*) FROM final_campaign_ranking WHERE performance_tier = 'underperformer')
                        )
                    )
                ELSE 
                    NULL
            END
        )
    ) INTO result;
    
    RETURN result;
    
EXCEPTION WHEN OTHERS THEN
    RETURN json_build_object(
        'error', TRUE,
        'message', SQLERRM,
        'organization_id', p_organization_id
    );
END;$$;


--
-- Name: get_acquisition_channel_attribution(uuid, integer, text, uuid[], uuid[], boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_acquisition_channel_attribution(p_organization_id uuid, p_period_days integer, p_timezone text DEFAULT 'UTC'::text, p_tag_ids uuid[] DEFAULT NULL::uuid[], p_touchpoint_ids uuid[] DEFAULT NULL::uuid[], p_is_premium boolean DEFAULT false) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    start_date TIMESTAMPTZ;
    end_date TIMESTAMPTZ;
    result JSON;
BEGIN
    -- Validate tier restrictions
    IF NOT p_is_premium AND p_period_days != 7 THEN
        RETURN json_build_object('error', TRUE, 'message', 'Free tier limited to 7 days only');
    END IF;
    
    IF NOT p_is_premium AND p_touchpoint_ids IS NOT NULL AND array_length(p_touchpoint_ids, 1) > 1 THEN
        RETURN json_build_object('error', TRUE, 'message', 'Free tier limited to 1 touchpoint only');
    END IF;

    -- Calculate date range in user's timezone
    end_date := CURRENT_TIMESTAMP AT TIME ZONE p_timezone;
    start_date := end_date - (p_period_days || ' days')::INTERVAL;
    
    WITH filtered_visits AS (
        -- Apply hierarchical filtering to visits with referrer data
        SELECT 
            v.referrer,
            v.fp,
            v.type,
            v.created_at,
            v.tp_id,
            v.platform,
            v.country,
            -- Categorize traffic sources for attribution
            CASE 
                WHEN v.referrer IS NULL OR v.referrer = '' OR v.referrer = 'direct' THEN 'direct'
                WHEN v.referrer ILIKE '%google%' THEN 'google'
                WHEN v.referrer ILIKE '%facebook%' THEN 'facebook'
                WHEN v.referrer ILIKE '%instagram%' THEN 'instagram'
                WHEN v.referrer ILIKE '%twitter%' OR v.referrer ILIKE '%x.com%' THEN 'twitter'
                WHEN v.referrer ILIKE '%linkedin%' THEN 'linkedin'
                WHEN v.referrer ILIKE '%youtube%' THEN 'youtube'
                WHEN v.referrer ILIKE '%tiktok%' THEN 'tiktok'
                WHEN v.referrer ILIKE '%whatsapp%' THEN 'whatsapp'
                WHEN v.referrer ILIKE '%telegram%' THEN 'telegram'
                ELSE 'other'
            END as channel
        FROM visits v
        WHERE v.organization_id = p_organization_id
            AND v.created_at >= start_date
            AND v.created_at < end_date            
            AND v.fp IS NOT NULL  -- Only users with valid fingerprints for attribution
            AND (
                -- No filtering if no filters specified
                (p_tag_ids IS NULL AND p_touchpoint_ids IS NULL)
                OR 
                -- Apply hierarchical filtering: tags first, then touchpoints
                (
                    (p_tag_ids IS NULL OR v.tp_id IN (
                        SELECT DISTINCT ttl.tp_id 
                        FROM tp_tag_links ttl 
                        WHERE ttl.tag_id = ANY(p_tag_ids)
                    ))
                    AND
                    (p_touchpoint_ids IS NULL OR v.tp_id = ANY(p_touchpoint_ids))
                )
            )
    ),
    user_journeys_with_attribution AS (
        -- Calculate first/last touch attribution for each visit (NO GROUP BY)
        SELECT 
            fp,
            channel,
            created_at,
            tp_id,
            type,
            -- Window functions to get first and last touch per user
            FIRST_VALUE(channel) OVER (PARTITION BY fp ORDER BY created_at ASC) as first_touch_channel,
            LAST_VALUE(channel) OVER (PARTITION BY fp ORDER BY created_at ASC 
                ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) as last_touch_channel,
            -- Journey timeline
            FIRST_VALUE(created_at) OVER (PARTITION BY fp ORDER BY created_at ASC) as first_interaction,
            LAST_VALUE(created_at) OVER (PARTITION BY fp ORDER BY created_at ASC 
                ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) as last_interaction
        FROM filtered_visits
    ),
    user_journey_summary AS (
        -- Aggregate user journey data (NOW we can GROUP BY)
        SELECT 
            fp,
            COUNT(*) as total_interactions,
            COUNT(DISTINCT channel) as channels_used,
            COUNT(DISTINCT tp_id) as touchpoints_used,
            COUNT(DISTINCT DATE(created_at AT TIME ZONE p_timezone)) as active_days,
            -- Get first and last touch (take any since they're the same for each user)
            MAX(first_touch_channel) as first_touch_channel,
            MAX(last_touch_channel) as last_touch_channel,
            MAX(first_interaction) as first_interaction,
            MAX(last_interaction) as last_interaction,
            EXTRACT(EPOCH FROM (MAX(last_interaction) - MAX(first_interaction))) / 3600 as journey_duration_hours,
            -- Channel sequence for path analysis
            STRING_AGG(DISTINCT channel, ',' ORDER BY channel) as unique_channels_used,
            -- Journey classification
            CASE 
                WHEN COUNT(DISTINCT channel) = 1 THEN 'single_channel'
                WHEN COUNT(DISTINCT channel) = 2 THEN 'two_channel'
                WHEN COUNT(DISTINCT channel) >= 3 THEN 'multi_channel'
            END as journey_type
        FROM user_journeys_with_attribution
        GROUP BY fp
    ),
    first_touch_attribution AS (
        -- First-touch attribution analysis
        SELECT 
            first_touch_channel as channel,
            COUNT(*) as attributed_users,
            SUM(total_interactions) as total_attributed_interactions,
            ROUND(AVG(total_interactions), 2) as avg_interactions_per_user,
            ROUND(AVG(journey_duration_hours), 1) as avg_journey_duration_hours,
            COUNT(CASE WHEN journey_type = 'single_channel' THEN 1 END) as single_channel_users,
            COUNT(CASE WHEN journey_type = 'multi_channel' THEN 1 END) as multi_channel_users
        FROM user_journey_summary
        GROUP BY first_touch_channel
    ),
    last_touch_attribution AS (
        -- Last-touch attribution analysis
        SELECT 
            last_touch_channel as channel,
            COUNT(*) as attributed_users,
            SUM(total_interactions) as total_attributed_interactions,
            ROUND(AVG(total_interactions), 2) as avg_interactions_per_user,
            COUNT(CASE WHEN journey_type = 'single_channel' THEN 1 END) as single_channel_users,
            COUNT(CASE WHEN journey_type = 'multi_channel' THEN 1 END) as multi_channel_users
        FROM user_journey_summary
        GROUP BY last_touch_channel
    ),
    channel_sequence_analysis AS (
        -- Analyze common channel sequences (Premium feature)
        SELECT 
            CASE 
                WHEN first_touch_channel != last_touch_channel THEN 
                    CONCAT(first_touch_channel, ' → ', last_touch_channel)
                ELSE first_touch_channel
            END as channel_path,
            journey_type,
            COUNT(*) as users_count,
            ROUND(AVG(total_interactions), 2) as avg_interactions,
            ROUND(AVG(journey_duration_hours), 1) as avg_duration_hours,
            ROUND(COUNT(*)::DECIMAL / SUM(COUNT(*)) OVER() * 100, 1) as path_share_pct
        FROM user_journey_summary
        GROUP BY 
            CASE 
                WHEN first_touch_channel != last_touch_channel THEN 
                    CONCAT(first_touch_channel, ' → ', last_touch_channel)
                ELSE first_touch_channel
            END,
            journey_type
    ),
    attribution_summary AS (
        -- Summary statistics for all attribution models
        SELECT 
            COUNT(DISTINCT fp) as total_users_analyzed,
            ROUND(AVG(total_interactions), 2) as avg_interactions_per_user,
            ROUND(AVG(channels_used), 2) as avg_channels_per_user,
            ROUND(AVG(journey_duration_hours), 1) as avg_journey_duration,
            COUNT(CASE WHEN journey_type = 'single_channel' THEN 1 END) as single_channel_journeys,
            COUNT(CASE WHEN journey_type = 'two_channel' THEN 1 END) as two_channel_journeys,
            COUNT(CASE WHEN journey_type = 'multi_channel' THEN 1 END) as multi_channel_journeys,
            -- Journey complexity metrics
            ROUND(COUNT(CASE WHEN journey_type != 'single_channel' THEN 1 END)::DECIMAL / COUNT(*) * 100, 1) as multi_touch_rate_pct
        FROM user_journey_summary
    )
    SELECT json_build_object(
        'period_info', json_build_object(
            'period_days', p_period_days,
            'start_date', start_date,
            'end_date', end_date,
            'timezone', p_timezone,
            'is_premium', p_is_premium,
            'analysis_type', 'channel_attribution'
        ),
        'filters_applied', json_build_object(
            'has_filters', (p_tag_ids IS NOT NULL OR p_touchpoint_ids IS NOT NULL),
            'tags_count', COALESCE(array_length(p_tag_ids, 1), 0),
            'touchpoints_count', COALESCE(array_length(p_touchpoint_ids, 1), 0)
        ),
        'attribution_analysis', json_build_object(
            -- First-touch attribution (both tiers)
            'first_touch_attribution', (
                SELECT json_agg(
                    json_build_object(
                        'channel', fta.channel,
                        'attributed_users', fta.attributed_users,
                        'total_attributed_interactions', fta.total_attributed_interactions,
                        'avg_interactions_per_user', fta.avg_interactions_per_user,
                        'user_share_pct', ROUND(fta.attributed_users::DECIMAL / (SELECT total_users_analyzed FROM attribution_summary) * 100, 1),
                        'single_channel_users', fta.single_channel_users,
                        'multi_channel_users', fta.multi_channel_users,
                        'avg_journey_duration_hours', fta.avg_journey_duration_hours
                    ) ORDER BY fta.attributed_users DESC
                )
                FROM first_touch_attribution fta
            ),
            -- Last-touch attribution (both tiers)
            'last_touch_attribution', (
                SELECT json_agg(
                    json_build_object(
                        'channel', lta.channel,
                        'attributed_users', lta.attributed_users,
                        'total_attributed_interactions', lta.total_attributed_interactions,
                        'avg_interactions_per_user', lta.avg_interactions_per_user,
                        'user_share_pct', ROUND(lta.attributed_users::DECIMAL / (SELECT total_users_analyzed FROM attribution_summary) * 100, 1),
                        'single_channel_users', lta.single_channel_users,
                        'multi_channel_users', lta.multi_channel_users
                    ) ORDER BY lta.attributed_users DESC
                )
                FROM last_touch_attribution lta
            ),
            -- Channel sequence analysis (Premium only)
            'channel_sequences', CASE 
                WHEN p_is_premium THEN
                    (
                        SELECT json_agg(
                            json_build_object(
                                'channel_path', csa.channel_path,
                                'journey_type', csa.journey_type,
                                'users_count', csa.users_count,
                                'path_share_pct', csa.path_share_pct,
                                'avg_interactions', csa.avg_interactions,
                                'avg_duration_hours', csa.avg_duration_hours
                            ) ORDER BY csa.users_count DESC
                        )
                        FROM channel_sequence_analysis csa
                        WHERE csa.users_count >= 2  -- Only meaningful sequences
                        LIMIT 15  -- Top 15 sequences
                    )
                ELSE NULL
            END,
            -- Summary statistics
            'summary', (
                SELECT json_build_object(
                    'total_users_analyzed', ats.total_users_analyzed,
                    'avg_interactions_per_user', ats.avg_interactions_per_user,
                    'avg_channels_per_user', ats.avg_channels_per_user,
                    'avg_journey_duration_hours', ats.avg_journey_duration,
                    'multi_touch_rate_pct', ats.multi_touch_rate_pct,
                    'journey_distribution', json_build_object(
                        'single_channel', ats.single_channel_journeys,
                        'two_channel', ats.two_channel_journeys,
                        'multi_channel', ats.multi_channel_journeys
                    ),
                    'attribution_reliability', CASE 
                        WHEN ats.total_users_analyzed >= 100 THEN 'high'
                        WHEN ats.total_users_analyzed >= 50 THEN 'medium'
                        WHEN ats.total_users_analyzed >= 20 THEN 'low'
                        ELSE 'insufficient_data'
                    END
                )
                FROM attribution_summary ats
            )
        ),
        'insights', json_build_object(
            -- Basic insights (both tiers)
            'dominant_first_touch_channel', (
                SELECT json_build_object(
                    'channel', fta.channel,
                    'users', fta.attributed_users,
                    'share_pct', ROUND(fta.attributed_users::DECIMAL / (SELECT total_users_analyzed FROM attribution_summary) * 100, 1)
                )
                FROM first_touch_attribution fta
                ORDER BY fta.attributed_users DESC
                LIMIT 1
            ),
            'dominant_last_touch_channel', (
                SELECT json_build_object(
                    'channel', lta.channel,
                    'users', lta.attributed_users,
                    'share_pct', ROUND(lta.attributed_users::DECIMAL / (SELECT total_users_analyzed FROM attribution_summary) * 100, 1)
                )
                FROM last_touch_attribution lta
                ORDER BY lta.attributed_users DESC
                LIMIT 1
            ),
            'attribution_model_comparison', (
                SELECT json_build_object(
                    'first_vs_last_touch_difference', CASE 
                        WHEN (SELECT channel FROM first_touch_attribution ORDER BY attributed_users DESC LIMIT 1) = 
                             (SELECT channel FROM last_touch_attribution ORDER BY attributed_users DESC LIMIT 1) THEN 'consistent_leader'
                        ELSE 'different_leaders'
                    END,
                    'multi_touch_significance', CASE 
                        WHEN ats.multi_touch_rate_pct > 60 THEN 'high_multi_touch'
                        WHEN ats.multi_touch_rate_pct > 30 THEN 'moderate_multi_touch'
                        ELSE 'primarily_single_touch'
                    END
                )
                FROM attribution_summary ats
            ),
            -- Premium-only insights
            'premium_insights', CASE 
                WHEN p_is_premium THEN
                    json_build_object(
                        'most_common_journey', (
                            SELECT json_build_object(
                                'path', csa.channel_path,
                                'users', csa.users_count,
                                'share_pct', csa.path_share_pct,
                                'avg_interactions', csa.avg_interactions
                            )
                            FROM channel_sequence_analysis csa
                            ORDER BY csa.users_count DESC
                            LIMIT 1
                        ),
                        'optimization_opportunities', (
                            SELECT json_agg(
                                json_build_object(
                                    'opportunity_type', CASE 
                                        WHEN ats.multi_touch_rate_pct > 70 THEN 'use_weighted_attribution'
                                        WHEN ats.multi_touch_rate_pct < 20 THEN 'focus_first_touch_attribution'
                                        WHEN (SELECT COUNT(*) FROM channel_sequence_analysis WHERE users_count >= 10) >= 3 THEN 'optimize_channel_sequences'
                                        WHEN ats.avg_journey_duration > 72 THEN 'nurture_long_journeys'
                                        ELSE 'maintain_current_approach'
                                    END,
                                    'confidence_level', CASE 
                                        WHEN ats.total_users_analyzed >= 100 THEN 'high'
                                        WHEN ats.total_users_analyzed >= 50 THEN 'medium'
                                        ELSE 'low'
                                    END,
                                    'supporting_metrics', json_build_object(
                                        'multi_touch_rate_pct', ats.multi_touch_rate_pct,
                                        'avg_journey_duration_hours', ats.avg_journey_duration,
                                        'strong_channel_paths_count', (SELECT COUNT(*) FROM channel_sequence_analysis WHERE users_count >= 10),
                                        'sample_size', ats.total_users_analyzed
                                    )
                                )
                            ) -- FILTER (WHERE opportunity_type != 'maintain_current_approach' OR ats.total_users_analyzed >= 50)
                            FROM attribution_summary ats
                        )
                    )
                ELSE NULL
            END
        )
    ) INTO result;
    
    RETURN result;
    
EXCEPTION WHEN OTHERS THEN
    RETURN json_build_object(
        'error', TRUE,
        'message', SQLERRM,
        'organization_id', p_organization_id
    );
END;
$$;


--
-- Name: get_acquisition_growth_trends(uuid, integer, text, uuid[], uuid[], boolean, uuid[], boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_acquisition_growth_trends(p_organization_id uuid, p_period_days integer, p_timezone text DEFAULT 'UTC'::text, p_tag_ids uuid[] DEFAULT NULL::uuid[], p_touchpoint_ids uuid[] DEFAULT NULL::uuid[], p_is_premium boolean DEFAULT false, p_collection_ids uuid[] DEFAULT NULL::uuid[], p_include_null_collection boolean DEFAULT false) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    start_date TIMESTAMPTZ;
    end_date TIMESTAMPTZ;
    comparison_start_date TIMESTAMPTZ;
    result JSON;
BEGIN
    -- Validate tier restrictions
    IF NOT p_is_premium AND p_period_days != 7 THEN
        RETURN json_build_object('error', TRUE, 'message', 'Free tier limited to 7 days only');
    END IF;
    
    IF NOT p_is_premium AND p_touchpoint_ids IS NOT NULL AND array_length(p_touchpoint_ids, 1) > 1 THEN
        RETURN json_build_object('error', TRUE, 'message', 'Free tier limited to 1 touchpoint only');
    END IF;

    -- Calculate date ranges (need double the period for comparison)
    end_date := CURRENT_TIMESTAMP AT TIME ZONE p_timezone;
    start_date := end_date - (p_period_days || ' days')::INTERVAL;
    comparison_start_date := start_date - (p_period_days || ' days')::INTERVAL;
    
    WITH filtered_visits AS (
        -- Apply hierarchical filtering with extended date range for comparison
        SELECT 
            v.referrer,
            v.fp,
            v.type,
            v.created_at,
            v.tp_id,
            v.platform,
            v.country,
            DATE(v.created_at AT TIME ZONE p_timezone) as visit_date,
            EXTRACT(hour FROM v.created_at AT TIME ZONE p_timezone) as visit_hour,
            EXTRACT(dow FROM v.created_at AT TIME ZONE p_timezone) as day_of_week,
            -- Categorize traffic sources
            CASE 
                WHEN v.referrer IS NULL OR v.referrer = '' OR v.referrer = 'direct' THEN 'direct'
                WHEN v.referrer ILIKE '%google%' THEN 'google'
                WHEN v.referrer ILIKE '%facebook%' THEN 'facebook'
                WHEN v.referrer ILIKE '%instagram%' THEN 'instagram'
                WHEN v.referrer ILIKE '%twitter%' OR v.referrer ILIKE '%x.com%' THEN 'twitter'
                WHEN v.referrer ILIKE '%linkedin%' THEN 'linkedin'
                WHEN v.referrer ILIKE '%youtube%' THEN 'youtube'
                WHEN v.referrer ILIKE '%tiktok%' THEN 'tiktok'
                WHEN v.referrer ILIKE '%whatsapp%' THEN 'whatsapp'
                WHEN v.referrer ILIKE '%telegram%' THEN 'telegram'
                ELSE 'other'
            END as channel
        FROM visits v
        WHERE v.organization_id = p_organization_id
            AND v.created_at >= comparison_start_date  -- Extended range for comparison
            AND v.created_at < end_date
            AND v.fp IS NOT NULL  -- Only valid users for acquisition tracking
            AND (
                -- No filtering if no filters specified
                (p_tag_ids IS NULL AND p_touchpoint_ids IS NULL)
                OR 
                -- Apply hierarchical filtering: tags first, then touchpoints
                (
                    (p_tag_ids IS NULL OR v.tp_id IN (
                        SELECT DISTINCT ttl.tp_id 
                        FROM tp_tag_links ttl 
                        WHERE ttl.tag_id = ANY(p_tag_ids)
                    ))
                    AND
                    (p_touchpoint_ids IS NULL OR v.tp_id = ANY(p_touchpoint_ids))
                )
            )
            AND (
                p_collection_ids IS NULL
                OR v.tp_id IN (
                    SELECT tp.id
                    FROM touch_points tp
                    WHERE tp.collection_id = ANY(p_collection_ids)
                       OR (p_include_null_collection AND tp.collection_id IS NULL)
                )
            )
    ),
    date_series AS (
        -- Generate complete date series to handle missing days
        SELECT 
            generate_series(
                comparison_start_date::date,
                (end_date - INTERVAL '1 day')::date,
                INTERVAL '1 day'
            )::date as date_bucket
    ),
    daily_acquisition_metrics AS (
        -- Aggregate daily acquisition metrics with complete date series
        SELECT 
            ds.date_bucket,
            COALESCE(COUNT(fv.fp), 0) as total_visits,
            COALESCE(COUNT(DISTINCT fv.fp), 0) as unique_users,
            COALESCE(COUNT(DISTINCT fv.country), 0) as countries_reached,
            COALESCE(COUNT(DISTINCT fv.channel), 0) as channels_active,
            -- Platform distribution
            COALESCE(COUNT(CASE WHEN fv.platform = 'Mobile' THEN 1 END), 0) as mobile_visits,
            COALESCE(COUNT(CASE WHEN fv.platform = 'Desktop' THEN 1 END), 0) as desktop_visits,
            -- Interaction types
            COALESCE(COUNT(CASE WHEN fv.type = 'LINK' THEN 1 END), 0) as link_interactions,
            COALESCE(COUNT(CASE WHEN fv.type = 'QR' THEN 1 END), 0) as qr_interactions,
            COALESCE(COUNT(CASE WHEN fv.type = 'NFC' THEN 1 END), 0) as nfc_interactions,
            COALESCE(COUNT(CASE WHEN fv.type = 'WIFI' THEN 1 END), 0) as wifi_interactions,
            -- Quality metrics
            COALESCE(ROUND(COUNT(fv.fp)::DECIMAL / NULLIF(COUNT(DISTINCT fv.fp), 0), 2), 0) as visits_per_user,
            -- Time period classification
            CASE 
                WHEN ds.date_bucket >= start_date::date THEN 'current_period'
                ELSE 'comparison_period'
            END as period_type
        FROM date_series ds
        LEFT JOIN filtered_visits fv ON ds.date_bucket = fv.visit_date
        GROUP BY ds.date_bucket
    ),
    growth_calculations AS (
        -- Calculate period-over-period growth rates
        SELECT 
            date_bucket,
            period_type,
            total_visits,
            unique_users,
            visits_per_user,
            countries_reached,
            channels_active,
            -- Day-over-day growth calculations
            LAG(total_visits, 1) OVER (ORDER BY date_bucket) as prev_day_visits,
            LAG(unique_users, 1) OVER (ORDER BY date_bucket) as prev_day_users,
            -- Calculate growth rates
            CASE 
                WHEN LAG(total_visits, 1) OVER (ORDER BY date_bucket) > 0 THEN
                    ROUND(((total_visits - LAG(total_visits, 1) OVER (ORDER BY date_bucket))::DECIMAL / 
                           LAG(total_visits, 1) OVER (ORDER BY date_bucket)) * 100, 1)
                ELSE NULL
            END as visits_growth_rate,
            CASE 
                WHEN LAG(unique_users, 1) OVER (ORDER BY date_bucket) > 0 THEN
                    ROUND(((unique_users - LAG(unique_users, 1) OVER (ORDER BY date_bucket))::DECIMAL / 
                           LAG(unique_users, 1) OVER (ORDER BY date_bucket)) * 100, 1)
                ELSE NULL
            END as users_growth_rate,
            -- Moving averages for trend smoothing
            ROUND(AVG(total_visits) OVER (ORDER BY date_bucket ROWS BETWEEN 2 PRECEDING AND CURRENT ROW), 1) as visits_3day_avg,
            ROUND(AVG(unique_users) OVER (ORDER BY date_bucket ROWS BETWEEN 2 PRECEDING AND CURRENT ROW), 1) as users_3day_avg
        FROM daily_acquisition_metrics
    ),
    source_growth_analysis AS (
        -- Analyze growth patterns by traffic source
        SELECT 
            fv.channel,
            DATE(fv.created_at AT TIME ZONE p_timezone) as date_bucket,
            COUNT(*) as daily_visits,
            COUNT(DISTINCT fv.fp) as daily_users,
            CASE 
                WHEN DATE(fv.created_at AT TIME ZONE p_timezone) >= start_date::date THEN 'current_period'
                ELSE 'comparison_period'
            END as period_type
        FROM filtered_visits fv
        GROUP BY fv.channel, DATE(fv.created_at AT TIME ZONE p_timezone)
    ),
    source_growth_summary AS (
        -- Summarize source growth trends
        SELECT 
            channel,
            SUM(CASE WHEN period_type = 'current_period' THEN daily_visits ELSE 0 END) as current_period_visits,
            SUM(CASE WHEN period_type = 'comparison_period' THEN daily_visits ELSE 0 END) as comparison_period_visits,
            SUM(CASE WHEN period_type = 'current_period' THEN daily_users ELSE 0 END) as current_period_users,
            SUM(CASE WHEN period_type = 'comparison_period' THEN daily_users ELSE 0 END) as comparison_period_users,
            -- Calculate growth rates
            CASE 
                WHEN SUM(CASE WHEN period_type = 'comparison_period' THEN daily_visits ELSE 0 END) > 0 THEN
                    ROUND(((SUM(CASE WHEN period_type = 'current_period' THEN daily_visits ELSE 0 END) - 
                           SUM(CASE WHEN period_type = 'comparison_period' THEN daily_visits ELSE 0 END))::DECIMAL / 
                           SUM(CASE WHEN period_type = 'comparison_period' THEN daily_visits ELSE 0 END)) * 100, 1)
                ELSE NULL
            END as visits_growth_rate,
            -- Growth momentum classification
            CASE 
                WHEN SUM(CASE WHEN period_type = 'comparison_period' THEN daily_visits ELSE 0 END) = 0 THEN 'emerging'
                WHEN ((SUM(CASE WHEN period_type = 'current_period' THEN daily_visits ELSE 0 END) - 
                       SUM(CASE WHEN period_type = 'comparison_period' THEN daily_visits ELSE 0 END))::DECIMAL / 
                       NULLIF(SUM(CASE WHEN period_type = 'comparison_period' THEN daily_visits ELSE 0 END), 0)) * 100 > 20 THEN 'accelerating'
                WHEN ((SUM(CASE WHEN period_type = 'current_period' THEN daily_visits ELSE 0 END) - 
                       SUM(CASE WHEN period_type = 'comparison_period' THEN daily_visits ELSE 0 END))::DECIMAL / 
                       NULLIF(SUM(CASE WHEN period_type = 'comparison_period' THEN daily_visits ELSE 0 END), 0)) * 100 BETWEEN -5 AND 20 THEN 'growing'
                WHEN ((SUM(CASE WHEN period_type = 'current_period' THEN daily_visits ELSE 0 END) - 
                       SUM(CASE WHEN period_type = 'comparison_period' THEN daily_visits ELSE 0 END))::DECIMAL / 
                       NULLIF(SUM(CASE WHEN period_type = 'comparison_period' THEN daily_visits ELSE 0 END), 0)) * 100 BETWEEN -20 AND -5 THEN 'stable'
                ELSE 'declining'
            END as growth_momentum
        FROM source_growth_analysis
        GROUP BY channel
    ),
    quality_trends AS (
        -- Track acquisition quality evolution over time
        SELECT 
            period_type,
            ROUND(AVG(visits_per_user), 2) as avg_visits_per_user,
            ROUND(AVG(countries_reached), 1) as avg_countries_per_day,
            ROUND(AVG(channels_active), 1) as avg_active_channels,
            ROUND(AVG(CASE WHEN total_visits > 0 THEN mobile_visits::DECIMAL / total_visits * 100 ELSE 0 END), 1) as mobile_percentage,
            COUNT(*) as days_analyzed
        FROM daily_acquisition_metrics
        WHERE total_visits > 0  -- Only days with actual activity
        GROUP BY period_type
    ),
    trend_summary AS (
        -- Overall trend analysis and classifications
        SELECT 
            -- Current vs comparison period totals
            SUM(CASE WHEN period_type = 'current_period' THEN total_visits ELSE 0 END) as current_total_visits,
            SUM(CASE WHEN period_type = 'comparison_period' THEN total_visits ELSE 0 END) as comparison_total_visits,
            SUM(CASE WHEN period_type = 'current_period' THEN unique_users ELSE 0 END) as current_total_users,
            SUM(CASE WHEN period_type = 'comparison_period' THEN unique_users ELSE 0 END) as comparison_total_users,
            -- Growth rate calculations
            CASE 
                WHEN SUM(CASE WHEN period_type = 'comparison_period' THEN total_visits ELSE 0 END) > 0 THEN
                    ROUND(((SUM(CASE WHEN period_type = 'current_period' THEN total_visits ELSE 0 END) - 
                           SUM(CASE WHEN period_type = 'comparison_period' THEN total_visits ELSE 0 END))::DECIMAL / 
                           SUM(CASE WHEN period_type = 'comparison_period' THEN total_visits ELSE 0 END)) * 100, 1)
                ELSE NULL
            END as overall_visits_growth_rate,
            -- Trend volatility (standard deviation of daily growth rates)
            ROUND(STDDEV(visits_growth_rate), 1) as growth_volatility,
            COUNT(CASE WHEN period_type = 'current_period' AND visits_growth_rate > 0 THEN 1 END) as positive_growth_days,
            COUNT(CASE WHEN period_type = 'current_period' THEN 1 END) as total_current_days
        FROM growth_calculations
        WHERE period_type = 'current_period' OR period_type = 'comparison_period'
    )
    SELECT json_build_object(
        'period_info', json_build_object(
            'period_days', p_period_days,
            'start_date', start_date,
            'end_date', end_date,
            'comparison_start_date', comparison_start_date,
            'timezone', p_timezone,
            'is_premium', p_is_premium,
            'analysis_type', 'growth_trends'
        ),
        'filters_applied', json_build_object(
            'has_filters', (p_tag_ids IS NOT NULL OR p_touchpoint_ids IS NOT NULL),
            'tags_count', COALESCE(array_length(p_tag_ids, 1), 0),
            'touchpoints_count', COALESCE(array_length(p_touchpoint_ids, 1), 0)
        ),
        'growth_analysis', json_build_object(
            -- Daily trends (both tiers, but limited for free)
            'daily_trends', CASE 
                WHEN p_is_premium THEN
                    (
                        SELECT json_agg(
                            json_build_object(
                                'date', gc.date_bucket,
                                'total_visits', gc.total_visits,
                                'unique_users', gc.unique_users,
                                'visits_per_user', gc.visits_per_user,
                                'visits_growth_rate', gc.visits_growth_rate,
                                'users_growth_rate', gc.users_growth_rate,
                                'visits_3day_avg', gc.visits_3day_avg,
                                'countries_reached', gc.countries_reached,
                                'channels_active', gc.channels_active
                            ) ORDER BY gc.date_bucket
                        )
                        FROM growth_calculations gc
                        WHERE gc.period_type = 'current_period'
                    )
                ELSE
                    (
                        SELECT json_agg(
                            json_build_object(
                                'date', gc.date_bucket,
                                'total_visits', gc.total_visits,
                                'unique_users', gc.unique_users,
                                'visits_growth_rate', gc.visits_growth_rate
                            ) ORDER BY gc.date_bucket
                        )
                        FROM growth_calculations gc
                        WHERE gc.period_type = 'current_period'
                    )
            END,
            -- Source growth analysis
            'source_growth', CASE 
                WHEN p_is_premium THEN
                    (
                        SELECT json_agg(
                            json_build_object(
                                'channel', sgs.channel,
                                'current_period_visits', sgs.current_period_visits,
                                'comparison_period_visits', sgs.comparison_period_visits,
                                'visits_growth_rate', sgs.visits_growth_rate,
                                'growth_momentum', sgs.growth_momentum,
                                'current_period_users', sgs.current_period_users,
                                'comparison_period_users', sgs.comparison_period_users
                            ) ORDER BY sgs.current_period_visits DESC
                        )
                        FROM source_growth_summary sgs
                    )
                ELSE
                    (
                        SELECT json_agg(
                            json_build_object(
                                'channel', sgs.channel,
                                'current_period_visits', sgs.current_period_visits,
                                'visits_growth_rate', sgs.visits_growth_rate,
                                'growth_momentum', sgs.growth_momentum
                            ) ORDER BY sgs.current_period_visits DESC
                        )
                        FROM source_growth_summary sgs
                        LIMIT 5  -- Top 5 sources for free tier
                    )
            END,
            -- Quality evolution (Premium only)
            'quality_evolution', CASE 
                WHEN p_is_premium THEN
                    (
                        SELECT json_agg(
                            json_build_object(
                                'period_type', qt.period_type,
                                'avg_visits_per_user', qt.avg_visits_per_user,
                                'avg_countries_per_day', qt.avg_countries_per_day,
                                'avg_active_channels', qt.avg_active_channels,
                                'mobile_percentage', qt.mobile_percentage,
                                'days_analyzed', qt.days_analyzed
                            )
                        )
                        FROM quality_trends qt
                    )
                ELSE NULL
            END,
            -- Summary statistics
            'summary', (
                SELECT json_build_object(
                    'current_total_visits', ts.current_total_visits,
                    'comparison_total_visits', ts.comparison_total_visits,
                    'current_total_users', ts.current_total_users,
                    'comparison_total_users', ts.comparison_total_users,
                    'overall_visits_growth_rate', ts.overall_visits_growth_rate,
                    'growth_volatility', CASE WHEN p_is_premium THEN ts.growth_volatility ELSE NULL END,
                    'positive_growth_days', ts.positive_growth_days,
                    'total_current_days', ts.total_current_days,
                    'growth_consistency', CASE 
                        WHEN ts.positive_growth_days::DECIMAL / ts.total_current_days > 0.7 THEN 'high_consistency'
                        WHEN ts.positive_growth_days::DECIMAL / ts.total_current_days > 0.4 THEN 'moderate_consistency'
                        ELSE 'low_consistency'
                    END,
                    'trend_direction', CASE 
                        WHEN ts.overall_visits_growth_rate > 10 THEN 'strong_growth'
                        WHEN ts.overall_visits_growth_rate > 0 THEN 'moderate_growth'
                        WHEN ts.overall_visits_growth_rate > -10 THEN 'stable'
                        ELSE 'declining'
                    END
                )
                FROM trend_summary ts
            )
        ),
        'insights', json_build_object(
            -- Basic insights (both tiers)
            'growth_performance', (
                SELECT json_build_object(
                    'overall_trend', CASE 
                        WHEN ts.overall_visits_growth_rate > 10 THEN 'strong_growth'
                        WHEN ts.overall_visits_growth_rate > 0 THEN 'moderate_growth'
                        WHEN ts.overall_visits_growth_rate > -10 THEN 'stable'
                        ELSE 'declining'
                    END,
                    'growth_rate', ts.overall_visits_growth_rate,
                    'growth_consistency', CASE 
                        WHEN ts.positive_growth_days::DECIMAL / ts.total_current_days > 0.7 THEN 'high_consistency'
                        WHEN ts.positive_growth_days::DECIMAL / ts.total_current_days > 0.4 THEN 'moderate_consistency'
                        ELSE 'low_consistency'
                    END
                )
                FROM trend_summary ts
            ),
            'top_growing_source', (
                SELECT json_build_object(
                    'channel', sgs.channel,
                    'growth_rate', sgs.visits_growth_rate,
                    'momentum', sgs.growth_momentum,
                    'current_visits', sgs.current_period_visits
                )
                FROM source_growth_summary sgs
                WHERE sgs.visits_growth_rate IS NOT NULL
                ORDER BY sgs.visits_growth_rate DESC
                LIMIT 1
            ),
            'fastest_declining_source', (
                SELECT json_build_object(
                    'channel', sgs.channel,
                    'decline_rate', sgs.visits_growth_rate,
                    'momentum', sgs.growth_momentum,
                    'current_visits', sgs.current_period_visits
                )
                FROM source_growth_summary sgs
                WHERE sgs.visits_growth_rate IS NOT NULL
                ORDER BY sgs.visits_growth_rate ASC
                LIMIT 1
            ),
            -- Premium-only insights
            'premium_insights', CASE 
                WHEN p_is_premium THEN
                    json_build_object(
                        'growth_opportunities', (
                            SELECT json_agg(
                                json_build_object(
                                    'opportunity_type', CASE 
                                        WHEN sgs.growth_momentum = 'emerging' AND sgs.current_period_visits > 10 THEN 'scale_emerging_channel'
                                        WHEN sgs.growth_momentum = 'accelerating' THEN 'invest_in_acceleration'
                                        WHEN sgs.growth_momentum = 'declining' AND sgs.current_period_visits > 100 THEN 'revive_declining_channel'
                                        ELSE NULL
                                    END,
                                    'target_channel', sgs.channel,
                                    'current_performance', json_build_object(
                                        'visits', sgs.current_period_visits,
                                        'growth_rate', sgs.visits_growth_rate,
                                        'momentum', sgs.growth_momentum
                                    ),
                                    'priority', CASE 
                                        WHEN sgs.current_period_visits > 200 THEN 'high'
                                        WHEN sgs.current_period_visits > 50 THEN 'medium'
                                        ELSE 'low'
                                    END
                                )
                            ) -- FILTER (WHERE opportunity_type IS NOT NULL)
                            FROM source_growth_summary sgs
                        ),
                        'quality_insights', (
                            SELECT json_build_object(
                                'engagement_trend', CASE 
                                    WHEN (SELECT avg_visits_per_user FROM quality_trends WHERE period_type = 'current_period') > 
                                         (SELECT avg_visits_per_user FROM quality_trends WHERE period_type = 'comparison_period') THEN 'improving_engagement'
                                   WHEN (SELECT avg_visits_per_user FROM quality_trends WHERE period_type = 'current_period') < 
                                        (SELECT avg_visits_per_user FROM quality_trends WHERE period_type = 'comparison_period') THEN 'declining_engagement'
                                   ELSE 'stable_engagement'
                               END,
                               'geographic_expansion', CASE 
                                   WHEN (SELECT avg_countries_per_day FROM quality_trends WHERE period_type = 'current_period') > 
                                        (SELECT avg_countries_per_day FROM quality_trends WHERE period_type = 'comparison_period') THEN 'expanding'
                                   ELSE 'stable_geography'
                               END,
                               'channel_diversification', CASE 
                                   WHEN (SELECT avg_active_channels FROM quality_trends WHERE period_type = 'current_period') > 
                                        (SELECT avg_active_channels FROM quality_trends WHERE period_type = 'comparison_period') THEN 'diversifying'
                                   ELSE 'stable_channels'
                               END
                           )
                       ),
                       'growth_forecast', (
                           -- Simple linear trend projection for next period
                           SELECT json_build_object(
                               'forecast_method', 'linear_trend',
                               'confidence_level', CASE 
                                   WHEN ts.growth_volatility < 20 THEN 'high'
                                   WHEN ts.growth_volatility < 50 THEN 'medium'
                                   ELSE 'low'
                               END,
                               'projected_growth_rate', CASE 
                                   WHEN ts.overall_visits_growth_rate IS NOT NULL THEN
                                       ROUND(ts.overall_visits_growth_rate * 1.1, 1)  -- Simple momentum-based projection
                                   ELSE NULL
                               END,
                               'projected_visits', CASE 
                                   WHEN ts.overall_visits_growth_rate IS NOT NULL THEN
                                       ROUND(ts.current_total_visits * (1 + (ts.overall_visits_growth_rate * 1.1 / 100)))
                                   ELSE NULL
                               END,
                               'forecast_period', CONCAT('Next ', p_period_days, ' days'),
                               'key_assumptions', json_build_array(
                                   'current_trend_continues',
                                   'no_major_external_changes',
                                   'same_acquisition_strategy'
                               )
                           )
                           FROM trend_summary ts
                       ),
                       'momentum_analysis', (
                           SELECT json_build_object(
                               'accelerating_channels', (
                                   SELECT COUNT(*) FROM source_growth_summary WHERE growth_momentum = 'accelerating'
                               ),
                               'emerging_channels', (
                                   SELECT COUNT(*) FROM source_growth_summary WHERE growth_momentum = 'emerging'
                               ),
                               'declining_channels', (
                                   SELECT COUNT(*) FROM source_growth_summary WHERE growth_momentum = 'declining'
                               ),
                               'portfolio_health', CASE 
                                   WHEN (SELECT COUNT(*) FROM source_growth_summary WHERE growth_momentum IN ('accelerating', 'growing')) > 
                                        (SELECT COUNT(*) FROM source_growth_summary WHERE growth_momentum = 'declining') THEN 'healthy_portfolio'
                                   WHEN (SELECT COUNT(*) FROM source_growth_summary WHERE growth_momentum = 'declining') > 
                                        (SELECT COUNT(*) FROM source_growth_summary WHERE growth_momentum IN ('accelerating', 'growing')) THEN 'portfolio_needs_attention'
                                   ELSE 'balanced_portfolio'
                               END
                           )
                       )
                   )
               ELSE NULL
           END
       )
   ) INTO result;
   
   RETURN result;
   
EXCEPTION WHEN OTHERS THEN
   RETURN json_build_object(
       'error', TRUE,
       'message', SQLERRM,
       'organization_id', p_organization_id
   );
END;
$$;


--
-- Name: get_acquisition_growth_trends_old(uuid, integer, text, uuid[], uuid[], boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_acquisition_growth_trends_old(p_organization_id uuid, p_period_days integer, p_timezone text DEFAULT 'UTC'::text, p_tag_ids uuid[] DEFAULT NULL::uuid[], p_touchpoint_ids uuid[] DEFAULT NULL::uuid[], p_is_premium boolean DEFAULT false) RETURNS json
    LANGUAGE plpgsql
    AS $$DECLARE
    start_date TIMESTAMPTZ;
    end_date TIMESTAMPTZ;
    comparison_start_date TIMESTAMPTZ;
    result JSON;
BEGIN
    -- Validate tier restrictions
    IF NOT p_is_premium AND p_period_days != 7 THEN
        RETURN json_build_object('error', TRUE, 'message', 'Free tier limited to 7 days only');
    END IF;
    
    IF NOT p_is_premium AND p_touchpoint_ids IS NOT NULL AND array_length(p_touchpoint_ids, 1) > 1 THEN
        RETURN json_build_object('error', TRUE, 'message', 'Free tier limited to 1 touchpoint only');
    END IF;

    -- Calculate date ranges (need double the period for comparison)
    end_date := CURRENT_TIMESTAMP AT TIME ZONE p_timezone;
    start_date := end_date - (p_period_days || ' days')::INTERVAL;
    comparison_start_date := start_date - (p_period_days || ' days')::INTERVAL;
    
    WITH filtered_visits AS (
        -- Apply hierarchical filtering with extended date range for comparison
        SELECT 
            v.referrer,
            v.fp,
            v.type,
            v.created_at,
            v.tp_id,
            v.platform,
            v.country,
            DATE(v.created_at AT TIME ZONE p_timezone) as visit_date,
            EXTRACT(hour FROM v.created_at AT TIME ZONE p_timezone) as visit_hour,
            EXTRACT(dow FROM v.created_at AT TIME ZONE p_timezone) as day_of_week,
            -- Categorize traffic sources
            CASE 
                WHEN v.referrer IS NULL OR v.referrer = '' OR v.referrer = 'direct' THEN 'direct'
                WHEN v.referrer ILIKE '%google%' THEN 'google'
                WHEN v.referrer ILIKE '%facebook%' THEN 'facebook'
                WHEN v.referrer ILIKE '%instagram%' THEN 'instagram'
                WHEN v.referrer ILIKE '%twitter%' OR v.referrer ILIKE '%x.com%' THEN 'twitter'
                WHEN v.referrer ILIKE '%linkedin%' THEN 'linkedin'
                WHEN v.referrer ILIKE '%youtube%' THEN 'youtube'
                WHEN v.referrer ILIKE '%tiktok%' THEN 'tiktok'
                WHEN v.referrer ILIKE '%whatsapp%' THEN 'whatsapp'
                WHEN v.referrer ILIKE '%telegram%' THEN 'telegram'
                ELSE 'other'
            END as channel
        FROM visits v
        WHERE v.organization_id = p_organization_id
            AND v.created_at >= comparison_start_date  -- Extended range for comparison
            AND v.created_at < end_date
            AND v.fp IS NOT NULL  -- Only valid users for acquisition tracking
            AND (
                -- No filtering if no filters specified
                (p_tag_ids IS NULL AND p_touchpoint_ids IS NULL)
                OR 
                -- Apply hierarchical filtering: tags first, then touchpoints
                (
                    (p_tag_ids IS NULL OR v.tp_id IN (
                        SELECT DISTINCT ttl.tp_id 
                        FROM tp_tag_links ttl 
                        WHERE ttl.tag_id = ANY(p_tag_ids)
                    ))
                    AND
                    (p_touchpoint_ids IS NULL OR v.tp_id = ANY(p_touchpoint_ids))
                )
            )
    ),
    date_series AS (
        -- Generate complete date series to handle missing days
        SELECT 
            generate_series(
                comparison_start_date::date,
                (end_date - INTERVAL '1 day')::date,
                INTERVAL '1 day'
            )::date as date_bucket
    ),
    daily_acquisition_metrics AS (
        -- Aggregate daily acquisition metrics with complete date series
        SELECT 
            ds.date_bucket,
            COALESCE(COUNT(fv.fp), 0) as total_visits,
            COALESCE(COUNT(DISTINCT fv.fp), 0) as unique_users,
            COALESCE(COUNT(DISTINCT fv.country), 0) as countries_reached,
            COALESCE(COUNT(DISTINCT fv.channel), 0) as channels_active,
            -- Platform distribution
            COALESCE(COUNT(CASE WHEN fv.platform = 'Mobile' THEN 1 END), 0) as mobile_visits,
            COALESCE(COUNT(CASE WHEN fv.platform = 'Desktop' THEN 1 END), 0) as desktop_visits,
            -- Interaction types
            COALESCE(COUNT(CASE WHEN fv.type = 'LINK' THEN 1 END), 0) as link_interactions,
            COALESCE(COUNT(CASE WHEN fv.type = 'QR' THEN 1 END), 0) as qr_interactions,
            COALESCE(COUNT(CASE WHEN fv.type = 'NFC' THEN 1 END), 0) as nfc_interactions,
            COALESCE(COUNT(CASE WHEN fv.type = 'WIFI' THEN 1 END), 0) as wifi_interactions,
            -- Quality metrics
            COALESCE(ROUND(COUNT(fv.fp)::DECIMAL / NULLIF(COUNT(DISTINCT fv.fp), 0), 2), 0) as visits_per_user,
            -- Time period classification
            CASE 
                WHEN ds.date_bucket >= start_date::date THEN 'current_period'
                ELSE 'comparison_period'
            END as period_type
        FROM date_series ds
        LEFT JOIN filtered_visits fv ON ds.date_bucket = fv.visit_date
        GROUP BY ds.date_bucket
    ),
    growth_calculations AS (
        -- Calculate period-over-period growth rates
        SELECT 
            date_bucket,
            period_type,
            total_visits,
            unique_users,
            visits_per_user,
            countries_reached,
            channels_active,
            -- Day-over-day growth calculations
            LAG(total_visits, 1) OVER (ORDER BY date_bucket) as prev_day_visits,
            LAG(unique_users, 1) OVER (ORDER BY date_bucket) as prev_day_users,
            -- Calculate growth rates
            CASE 
                WHEN LAG(total_visits, 1) OVER (ORDER BY date_bucket) > 0 THEN
                    ROUND(((total_visits - LAG(total_visits, 1) OVER (ORDER BY date_bucket))::DECIMAL / 
                           LAG(total_visits, 1) OVER (ORDER BY date_bucket)) * 100, 1)
                ELSE NULL
            END as visits_growth_rate,
            CASE 
                WHEN LAG(unique_users, 1) OVER (ORDER BY date_bucket) > 0 THEN
                    ROUND(((unique_users - LAG(unique_users, 1) OVER (ORDER BY date_bucket))::DECIMAL / 
                           LAG(unique_users, 1) OVER (ORDER BY date_bucket)) * 100, 1)
                ELSE NULL
            END as users_growth_rate,
            -- Moving averages for trend smoothing
            ROUND(AVG(total_visits) OVER (ORDER BY date_bucket ROWS BETWEEN 2 PRECEDING AND CURRENT ROW), 1) as visits_3day_avg,
            ROUND(AVG(unique_users) OVER (ORDER BY date_bucket ROWS BETWEEN 2 PRECEDING AND CURRENT ROW), 1) as users_3day_avg
        FROM daily_acquisition_metrics
    ),
    source_growth_analysis AS (
        -- Analyze growth patterns by traffic source
        SELECT 
            fv.channel,
            DATE(fv.created_at AT TIME ZONE p_timezone) as date_bucket,
            COUNT(*) as daily_visits,
            COUNT(DISTINCT fv.fp) as daily_users,
            CASE 
                WHEN DATE(fv.created_at AT TIME ZONE p_timezone) >= start_date::date THEN 'current_period'
                ELSE 'comparison_period'
            END as period_type
        FROM filtered_visits fv
        GROUP BY fv.channel, DATE(fv.created_at AT TIME ZONE p_timezone)
    ),
    source_growth_summary AS (
        -- Summarize source growth trends
        SELECT 
            channel,
            SUM(CASE WHEN period_type = 'current_period' THEN daily_visits ELSE 0 END) as current_period_visits,
            SUM(CASE WHEN period_type = 'comparison_period' THEN daily_visits ELSE 0 END) as comparison_period_visits,
            SUM(CASE WHEN period_type = 'current_period' THEN daily_users ELSE 0 END) as current_period_users,
            SUM(CASE WHEN period_type = 'comparison_period' THEN daily_users ELSE 0 END) as comparison_period_users,
            -- Calculate growth rates
            CASE 
                WHEN SUM(CASE WHEN period_type = 'comparison_period' THEN daily_visits ELSE 0 END) > 0 THEN
                    ROUND(((SUM(CASE WHEN period_type = 'current_period' THEN daily_visits ELSE 0 END) - 
                           SUM(CASE WHEN period_type = 'comparison_period' THEN daily_visits ELSE 0 END))::DECIMAL / 
                           SUM(CASE WHEN period_type = 'comparison_period' THEN daily_visits ELSE 0 END)) * 100, 1)
                ELSE NULL
            END as visits_growth_rate,
            -- Growth momentum classification
            CASE 
                WHEN SUM(CASE WHEN period_type = 'comparison_period' THEN daily_visits ELSE 0 END) = 0 THEN 'emerging'
                WHEN ((SUM(CASE WHEN period_type = 'current_period' THEN daily_visits ELSE 0 END) - 
                       SUM(CASE WHEN period_type = 'comparison_period' THEN daily_visits ELSE 0 END))::DECIMAL / 
                       NULLIF(SUM(CASE WHEN period_type = 'comparison_period' THEN daily_visits ELSE 0 END), 0)) * 100 > 20 THEN 'accelerating'
                WHEN ((SUM(CASE WHEN period_type = 'current_period' THEN daily_visits ELSE 0 END) - 
                       SUM(CASE WHEN period_type = 'comparison_period' THEN daily_visits ELSE 0 END))::DECIMAL / 
                       NULLIF(SUM(CASE WHEN period_type = 'comparison_period' THEN daily_visits ELSE 0 END), 0)) * 100 BETWEEN -5 AND 20 THEN 'growing'
                WHEN ((SUM(CASE WHEN period_type = 'current_period' THEN daily_visits ELSE 0 END) - 
                       SUM(CASE WHEN period_type = 'comparison_period' THEN daily_visits ELSE 0 END))::DECIMAL / 
                       NULLIF(SUM(CASE WHEN period_type = 'comparison_period' THEN daily_visits ELSE 0 END), 0)) * 100 BETWEEN -20 AND -5 THEN 'stable'
                ELSE 'declining'
            END as growth_momentum
        FROM source_growth_analysis
        GROUP BY channel
    ),
    quality_trends AS (
        -- Track acquisition quality evolution over time
        SELECT 
            period_type,
            ROUND(AVG(visits_per_user), 2) as avg_visits_per_user,
            ROUND(AVG(countries_reached), 1) as avg_countries_per_day,
            ROUND(AVG(channels_active), 1) as avg_active_channels,
            ROUND(AVG(CASE WHEN total_visits > 0 THEN mobile_visits::DECIMAL / total_visits * 100 ELSE 0 END), 1) as mobile_percentage,
            COUNT(*) as days_analyzed
        FROM daily_acquisition_metrics
        WHERE total_visits > 0  -- Only days with actual activity
        GROUP BY period_type
    ),
    trend_summary AS (
        -- Overall trend analysis and classifications
        SELECT 
            -- Current vs comparison period totals
            SUM(CASE WHEN period_type = 'current_period' THEN total_visits ELSE 0 END) as current_total_visits,
            SUM(CASE WHEN period_type = 'comparison_period' THEN total_visits ELSE 0 END) as comparison_total_visits,
            SUM(CASE WHEN period_type = 'current_period' THEN unique_users ELSE 0 END) as current_total_users,
            SUM(CASE WHEN period_type = 'comparison_period' THEN unique_users ELSE 0 END) as comparison_total_users,
            -- Growth rate calculations
            CASE 
                WHEN SUM(CASE WHEN period_type = 'comparison_period' THEN total_visits ELSE 0 END) > 0 THEN
                    ROUND(((SUM(CASE WHEN period_type = 'current_period' THEN total_visits ELSE 0 END) - 
                           SUM(CASE WHEN period_type = 'comparison_period' THEN total_visits ELSE 0 END))::DECIMAL / 
                           SUM(CASE WHEN period_type = 'comparison_period' THEN total_visits ELSE 0 END)) * 100, 1)
                ELSE NULL
            END as overall_visits_growth_rate,
            -- Trend volatility (standard deviation of daily growth rates)
            ROUND(STDDEV(visits_growth_rate), 1) as growth_volatility,
            COUNT(CASE WHEN period_type = 'current_period' AND visits_growth_rate > 0 THEN 1 END) as positive_growth_days,
            COUNT(CASE WHEN period_type = 'current_period' THEN 1 END) as total_current_days
        FROM growth_calculations
        WHERE period_type = 'current_period' OR period_type = 'comparison_period'
    )
    SELECT json_build_object(
        'period_info', json_build_object(
            'period_days', p_period_days,
            'start_date', start_date,
            'end_date', end_date,
            'comparison_start_date', comparison_start_date,
            'timezone', p_timezone,
            'is_premium', p_is_premium,
            'analysis_type', 'growth_trends'
        ),
        'filters_applied', json_build_object(
            'has_filters', (p_tag_ids IS NOT NULL OR p_touchpoint_ids IS NOT NULL),
            'tags_count', COALESCE(array_length(p_tag_ids, 1), 0),
            'touchpoints_count', COALESCE(array_length(p_touchpoint_ids, 1), 0)
        ),
        'growth_analysis', json_build_object(
            -- Daily trends (both tiers, but limited for free)
            'daily_trends', CASE 
                WHEN p_is_premium THEN
                    (
                        SELECT json_agg(
                            json_build_object(
                                'date', gc.date_bucket,
                                'total_visits', gc.total_visits,
                                'unique_users', gc.unique_users,
                                'visits_per_user', gc.visits_per_user,
                                'visits_growth_rate', gc.visits_growth_rate,
                                'users_growth_rate', gc.users_growth_rate,
                                'visits_3day_avg', gc.visits_3day_avg,
                                'countries_reached', gc.countries_reached,
                                'channels_active', gc.channels_active
                            ) ORDER BY gc.date_bucket
                        )
                        FROM growth_calculations gc
                        WHERE gc.period_type = 'current_period'
                    )
                ELSE
                    (
                        SELECT json_agg(
                            json_build_object(
                                'date', gc.date_bucket,
                                'total_visits', gc.total_visits,
                                'unique_users', gc.unique_users,
                                'visits_growth_rate', gc.visits_growth_rate
                            ) ORDER BY gc.date_bucket
                        )
                        FROM growth_calculations gc
                        WHERE gc.period_type = 'current_period'
                    )
            END,
            -- Source growth analysis
            'source_growth', CASE 
                WHEN p_is_premium THEN
                    (
                        SELECT json_agg(
                            json_build_object(
                                'channel', sgs.channel,
                                'current_period_visits', sgs.current_period_visits,
                                'comparison_period_visits', sgs.comparison_period_visits,
                                'visits_growth_rate', sgs.visits_growth_rate,
                                'growth_momentum', sgs.growth_momentum,
                                'current_period_users', sgs.current_period_users,
                                'comparison_period_users', sgs.comparison_period_users
                            ) ORDER BY sgs.current_period_visits DESC
                        )
                        FROM source_growth_summary sgs
                    )
                ELSE
                    (
                        SELECT json_agg(
                            json_build_object(
                                'channel', sgs.channel,
                                'current_period_visits', sgs.current_period_visits,
                                'visits_growth_rate', sgs.visits_growth_rate,
                                'growth_momentum', sgs.growth_momentum
                            ) ORDER BY sgs.current_period_visits DESC
                        )
                        FROM source_growth_summary sgs
                        LIMIT 5  -- Top 5 sources for free tier
                    )
            END,
            -- Quality evolution (Premium only)
            'quality_evolution', CASE 
                WHEN p_is_premium THEN
                    (
                        SELECT json_agg(
                            json_build_object(
                                'period_type', qt.period_type,
                                'avg_visits_per_user', qt.avg_visits_per_user,
                                'avg_countries_per_day', qt.avg_countries_per_day,
                                'avg_active_channels', qt.avg_active_channels,
                                'mobile_percentage', qt.mobile_percentage,
                                'days_analyzed', qt.days_analyzed
                            )
                        )
                        FROM quality_trends qt
                    )
                ELSE NULL
            END,
            -- Summary statistics
            'summary', (
                SELECT json_build_object(
                    'current_total_visits', ts.current_total_visits,
                    'comparison_total_visits', ts.comparison_total_visits,
                    'current_total_users', ts.current_total_users,
                    'comparison_total_users', ts.comparison_total_users,
                    'overall_visits_growth_rate', ts.overall_visits_growth_rate,
                    'growth_volatility', CASE WHEN p_is_premium THEN ts.growth_volatility ELSE NULL END,
                    'positive_growth_days', ts.positive_growth_days,
                    'total_current_days', ts.total_current_days,
                    'growth_consistency', CASE 
                        WHEN ts.positive_growth_days::DECIMAL / ts.total_current_days > 0.7 THEN 'high_consistency'
                        WHEN ts.positive_growth_days::DECIMAL / ts.total_current_days > 0.4 THEN 'moderate_consistency'
                        ELSE 'low_consistency'
                    END,
                    'trend_direction', CASE 
                        WHEN ts.overall_visits_growth_rate > 10 THEN 'strong_growth'
                        WHEN ts.overall_visits_growth_rate > 0 THEN 'moderate_growth'
                        WHEN ts.overall_visits_growth_rate > -10 THEN 'stable'
                        ELSE 'declining'
                    END
                )
                FROM trend_summary ts
            )
        ),
        'insights', json_build_object(
            -- Basic insights (both tiers)
            'growth_performance', (
                SELECT json_build_object(
                    'overall_trend', CASE 
                        WHEN ts.overall_visits_growth_rate > 10 THEN 'strong_growth'
                        WHEN ts.overall_visits_growth_rate > 0 THEN 'moderate_growth'
                        WHEN ts.overall_visits_growth_rate > -10 THEN 'stable'
                        ELSE 'declining'
                    END,
                    'growth_rate', ts.overall_visits_growth_rate,
                    'growth_consistency', CASE 
                        WHEN ts.positive_growth_days::DECIMAL / ts.total_current_days > 0.7 THEN 'high_consistency'
                        WHEN ts.positive_growth_days::DECIMAL / ts.total_current_days > 0.4 THEN 'moderate_consistency'
                        ELSE 'low_consistency'
                    END
                )
                FROM trend_summary ts
            ),
            'top_growing_source', (
                SELECT json_build_object(
                    'channel', sgs.channel,
                    'growth_rate', sgs.visits_growth_rate,
                    'momentum', sgs.growth_momentum,
                    'current_visits', sgs.current_period_visits
                )
                FROM source_growth_summary sgs
                WHERE sgs.visits_growth_rate IS NOT NULL
                ORDER BY sgs.visits_growth_rate DESC
                LIMIT 1
            ),
            'fastest_declining_source', (
                SELECT json_build_object(
                    'channel', sgs.channel,
                    'decline_rate', sgs.visits_growth_rate,
                    'momentum', sgs.growth_momentum,
                    'current_visits', sgs.current_period_visits
                )
                FROM source_growth_summary sgs
                WHERE sgs.visits_growth_rate IS NOT NULL
                ORDER BY sgs.visits_growth_rate ASC
                LIMIT 1
            ),
            -- Premium-only insights
            'premium_insights', CASE 
                WHEN p_is_premium THEN
                    json_build_object(
                        'growth_opportunities', (
                            SELECT json_agg(
                                json_build_object(
                                    'opportunity_type', CASE 
                                        WHEN sgs.growth_momentum = 'emerging' AND sgs.current_period_visits > 10 THEN 'scale_emerging_channel'
                                        WHEN sgs.growth_momentum = 'accelerating' THEN 'invest_in_acceleration'
                                        WHEN sgs.growth_momentum = 'declining' AND sgs.current_period_visits > 100 THEN 'revive_declining_channel'
                                        ELSE NULL
                                    END,
                                    'target_channel', sgs.channel,
                                    'current_performance', json_build_object(
                                        'visits', sgs.current_period_visits,
                                        'growth_rate', sgs.visits_growth_rate,
                                        'momentum', sgs.growth_momentum
                                    ),
                                    'priority', CASE 
                                        WHEN sgs.current_period_visits > 200 THEN 'high'
                                        WHEN sgs.current_period_visits > 50 THEN 'medium'
                                        ELSE 'low'
                                    END
                                )
                            ) -- FILTER (WHERE opportunity_type IS NOT NULL)
                            FROM source_growth_summary sgs
                        ),
                        'quality_insights', (
                            SELECT json_build_object(
                                'engagement_trend', CASE 
                                    WHEN (SELECT avg_visits_per_user FROM quality_trends WHERE period_type = 'current_period') > 
                                         (SELECT avg_visits_per_user FROM quality_trends WHERE period_type = 'comparison_period') THEN 'improving_engagement'
                                   WHEN (SELECT avg_visits_per_user FROM quality_trends WHERE period_type = 'current_period') < 
                                        (SELECT avg_visits_per_user FROM quality_trends WHERE period_type = 'comparison_period') THEN 'declining_engagement'
                                   ELSE 'stable_engagement'
                               END,
                               'geographic_expansion', CASE 
                                   WHEN (SELECT avg_countries_per_day FROM quality_trends WHERE period_type = 'current_period') > 
                                        (SELECT avg_countries_per_day FROM quality_trends WHERE period_type = 'comparison_period') THEN 'expanding'
                                   ELSE 'stable_geography'
                               END,
                               'channel_diversification', CASE 
                                   WHEN (SELECT avg_active_channels FROM quality_trends WHERE period_type = 'current_period') > 
                                        (SELECT avg_active_channels FROM quality_trends WHERE period_type = 'comparison_period') THEN 'diversifying'
                                   ELSE 'stable_channels'
                               END
                           )
                       ),
                       'growth_forecast', (
                           -- Simple linear trend projection for next period
                           SELECT json_build_object(
                               'forecast_method', 'linear_trend',
                               'confidence_level', CASE 
                                   WHEN ts.growth_volatility < 20 THEN 'high'
                                   WHEN ts.growth_volatility < 50 THEN 'medium'
                                   ELSE 'low'
                               END,
                               'projected_growth_rate', CASE 
                                   WHEN ts.overall_visits_growth_rate IS NOT NULL THEN
                                       ROUND(ts.overall_visits_growth_rate * 1.1, 1)  -- Simple momentum-based projection
                                   ELSE NULL
                               END,
                               'projected_visits', CASE 
                                   WHEN ts.overall_visits_growth_rate IS NOT NULL THEN
                                       ROUND(ts.current_total_visits * (1 + (ts.overall_visits_growth_rate * 1.1 / 100)))
                                   ELSE NULL
                               END,
                               'forecast_period', CONCAT('Next ', p_period_days, ' days'),
                               'key_assumptions', json_build_array(
                                   'current_trend_continues',
                                   'no_major_external_changes',
                                   'same_acquisition_strategy'
                               )
                           )
                           FROM trend_summary ts
                       ),
                       'momentum_analysis', (
                           SELECT json_build_object(
                               'accelerating_channels', (
                                   SELECT COUNT(*) FROM source_growth_summary WHERE growth_momentum = 'accelerating'
                               ),
                               'emerging_channels', (
                                   SELECT COUNT(*) FROM source_growth_summary WHERE growth_momentum = 'emerging'
                               ),
                               'declining_channels', (
                                   SELECT COUNT(*) FROM source_growth_summary WHERE growth_momentum = 'declining'
                               ),
                               'portfolio_health', CASE 
                                   WHEN (SELECT COUNT(*) FROM source_growth_summary WHERE growth_momentum IN ('accelerating', 'growing')) > 
                                        (SELECT COUNT(*) FROM source_growth_summary WHERE growth_momentum = 'declining') THEN 'healthy_portfolio'
                                   WHEN (SELECT COUNT(*) FROM source_growth_summary WHERE growth_momentum = 'declining') > 
                                        (SELECT COUNT(*) FROM source_growth_summary WHERE growth_momentum IN ('accelerating', 'growing')) THEN 'portfolio_needs_attention'
                                   ELSE 'balanced_portfolio'
                               END
                           )
                       )
                   )
               ELSE NULL
           END
       )
   ) INTO result;
   
   RETURN result;
   
EXCEPTION WHEN OTHERS THEN
   RETURN json_build_object(
       'error', TRUE,
       'message', SQLERRM,
       'organization_id', p_organization_id
   );
END;$$;


--
-- Name: get_acquisition_touchpoint_attribution(uuid, integer, text, uuid[], uuid[], boolean, uuid[], boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_acquisition_touchpoint_attribution(p_organization_id uuid, p_period_days integer, p_timezone text DEFAULT 'UTC'::text, p_tag_ids uuid[] DEFAULT NULL::uuid[], p_touchpoint_ids uuid[] DEFAULT NULL::uuid[], p_is_premium boolean DEFAULT false, p_collection_ids uuid[] DEFAULT NULL::uuid[], p_include_null_collection boolean DEFAULT false) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    start_date TIMESTAMPTZ;
    end_date TIMESTAMPTZ;
    result JSON;
BEGIN
    -- Validate tier restrictions
    IF NOT p_is_premium AND p_period_days != 7 THEN
        RETURN json_build_object('error', TRUE, 'message', 'Free tier limited to 7 days only');
    END IF;
    
    IF NOT p_is_premium AND p_touchpoint_ids IS NOT NULL AND array_length(p_touchpoint_ids, 1) > 1 THEN
        RETURN json_build_object('error', TRUE, 'message', 'Free tier limited to 1 touchpoint only');
    END IF;

    -- Calculate date range in user's timezone
    end_date := CURRENT_TIMESTAMP AT TIME ZONE p_timezone;
    start_date := end_date - (p_period_days || ' days')::INTERVAL;
    
    WITH filtered_visits AS (
        -- Get visits with touchpoint and channel information
        SELECT 
            v.referrer,
            v.fp,
            v.type as interaction_channel,  -- QR, LINK, NFC, WIFI
            v.created_at,
            v.tp_id,
            v.platform,
            v.country,
            tp.name as touchpoint_name,
            -- Categorize discovery channels (how they found this touchpoint)
            CASE 
                WHEN v.referrer IS NULL OR v.referrer = '' OR v.referrer = 'direct' THEN 'direct'
                WHEN v.referrer ILIKE '%google%' THEN 'google'
                WHEN v.referrer ILIKE '%facebook%' THEN 'facebook'
                WHEN v.referrer ILIKE '%instagram%' THEN 'instagram'
                WHEN v.referrer ILIKE '%twitter%' OR v.referrer ILIKE '%x.com%' THEN 'twitter'
                WHEN v.referrer ILIKE '%linkedin%' THEN 'linkedin'
                WHEN v.referrer ILIKE '%youtube%' THEN 'youtube'
                WHEN v.referrer ILIKE '%tiktok%' THEN 'tiktok'
                WHEN v.referrer ILIKE '%whatsapp%' THEN 'whatsapp'
                WHEN v.referrer ILIKE '%telegram%' THEN 'telegram'
                ELSE 'other'
            END as discovery_channel
        FROM visits v
        INNER JOIN touch_points tp ON v.tp_id = tp.id
        WHERE v.organization_id = p_organization_id
            AND v.created_at >= start_date
            AND v.created_at < end_date            
            AND v.fp IS NOT NULL  -- Only users with valid fingerprints for attribution
            AND tp.deleted_at IS NULL
            AND (
                -- No filtering if no filters specified
                (p_tag_ids IS NULL AND p_touchpoint_ids IS NULL)
                OR 
                -- Apply hierarchical filtering: tags first, then touchpoints
                (
                    (p_tag_ids IS NULL OR v.tp_id IN (
                        SELECT DISTINCT ttl.tp_id 
                        FROM tp_tag_links ttl 
                        WHERE ttl.tag_id = ANY(p_tag_ids)
                    ))
                    AND
                    (p_touchpoint_ids IS NULL OR v.tp_id = ANY(p_touchpoint_ids))
                )
            )
            AND (
                p_collection_ids IS NULL
                OR v.tp_id IN (
                    SELECT tp.id
                    FROM touch_points tp
                    WHERE tp.collection_id = ANY(p_collection_ids)
                       OR (p_include_null_collection AND tp.collection_id IS NULL)
                )
            )
    ),
    user_touchpoint_journeys AS (
        -- Calculate touchpoint attribution for each visit (NO GROUP BY)
        SELECT 
            fp,
            tp_id,
            touchpoint_name,
            interaction_channel,
            discovery_channel,
            created_at,
            -- Window functions to get first and last touchpoint per user
            FIRST_VALUE(tp_id) OVER (PARTITION BY fp ORDER BY created_at ASC) as first_touch_tp_id,
            FIRST_VALUE(touchpoint_name) OVER (PARTITION BY fp ORDER BY created_at ASC) as first_touch_tp_name,
            FIRST_VALUE(interaction_channel) OVER (PARTITION BY fp ORDER BY created_at ASC) as first_touch_channel,
            FIRST_VALUE(discovery_channel) OVER (PARTITION BY fp ORDER BY created_at ASC) as first_touch_discovery,
            
            LAST_VALUE(tp_id) OVER (PARTITION BY fp ORDER BY created_at ASC 
                ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) as last_touch_tp_id,
            LAST_VALUE(touchpoint_name) OVER (PARTITION BY fp ORDER BY created_at ASC 
                ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) as last_touch_tp_name,
            LAST_VALUE(interaction_channel) OVER (PARTITION BY fp ORDER BY created_at ASC 
                ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) as last_touch_channel,
            LAST_VALUE(discovery_channel) OVER (PARTITION BY fp ORDER BY created_at ASC 
                ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) as last_touch_discovery,
            
            -- Journey timeline
            FIRST_VALUE(created_at) OVER (PARTITION BY fp ORDER BY created_at ASC) as first_interaction,
            LAST_VALUE(created_at) OVER (PARTITION BY fp ORDER BY created_at ASC 
                ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) as last_interaction
        FROM filtered_visits
    ),
    user_journey_summary AS (
        -- Aggregate user journey data (NOW we can GROUP BY)
        SELECT 
            fp,
            COUNT(*) as total_interactions,
            COUNT(DISTINCT tp_id) as touchpoints_used,
            COUNT(DISTINCT interaction_channel) as channels_used,
            COUNT(DISTINCT discovery_channel) as discovery_methods_used,
            COUNT(DISTINCT DATE(created_at AT TIME ZONE p_timezone)) as active_days,
            -- Get first and last touch (use ANY since they're the same for each user)
            (ARRAY_AGG(first_touch_tp_id))[1] as first_touch_tp_id,
            (ARRAY_AGG(first_touch_tp_name))[1] as first_touch_tp_name,
            (ARRAY_AGG(first_touch_channel))[1] as first_touch_channel,
            (ARRAY_AGG(first_touch_discovery))[1] as first_touch_discovery,
            (ARRAY_AGG(last_touch_tp_id))[1] as last_touch_tp_id,
            (ARRAY_AGG(last_touch_tp_name))[1] as last_touch_tp_name,
            (ARRAY_AGG(last_touch_channel))[1] as last_touch_channel,
            (ARRAY_AGG(last_touch_discovery))[1] as last_touch_discovery,
            (ARRAY_AGG(first_interaction))[1] as first_interaction,
            (ARRAY_AGG(last_interaction))[1] as last_interaction,
            EXTRACT(EPOCH FROM ((ARRAY_AGG(last_interaction))[1] - (ARRAY_AGG(first_interaction))[1])) / 3600 as journey_duration_hours,
            -- Journey classification
            CASE 
                WHEN COUNT(DISTINCT tp_id) = 1 THEN 'single_touchpoint'
                WHEN COUNT(DISTINCT tp_id) = 2 THEN 'two_touchpoint'
                WHEN COUNT(DISTINCT tp_id) >= 3 THEN 'multi_touchpoint'
            END as journey_complexity
        FROM user_touchpoint_journeys
        GROUP BY fp
    ),
    first_touch_touchpoint_attribution AS (
        -- First-touch touchpoint attribution analysis
        SELECT 
            first_touch_tp_id as tp_id,
            first_touch_tp_name as touchpoint_name,
            first_touch_channel as interaction_channel,
            first_touch_discovery as discovery_channel,
            COUNT(*) as attributed_users,
            SUM(total_interactions) as total_attributed_interactions,
            ROUND(AVG(total_interactions), 2) as avg_interactions_per_user,
            ROUND(AVG(journey_duration_hours), 1) as avg_journey_duration_hours,
            COUNT(CASE WHEN journey_complexity = 'single_touchpoint' THEN 1 END) as single_touchpoint_users,
            COUNT(CASE WHEN journey_complexity = 'multi_touchpoint' THEN 1 END) as multi_touchpoint_users
        FROM user_journey_summary
        GROUP BY first_touch_tp_id, first_touch_tp_name, first_touch_channel, first_touch_discovery
    ),
    last_touch_touchpoint_attribution AS (
        -- Last-touch touchpoint attribution analysis
        SELECT 
            last_touch_tp_id as tp_id,
            last_touch_tp_name as touchpoint_name,
            last_touch_channel as interaction_channel,
            last_touch_discovery as discovery_channel,
            COUNT(*) as attributed_users,
            SUM(total_interactions) as total_attributed_interactions,
            ROUND(AVG(total_interactions), 2) as avg_interactions_per_user,
            COUNT(CASE WHEN journey_complexity = 'single_touchpoint' THEN 1 END) as single_touchpoint_users,
            COUNT(CASE WHEN journey_complexity = 'multi_touchpoint' THEN 1 END) as multi_touchpoint_users
        FROM user_journey_summary
        GROUP BY last_touch_tp_id, last_touch_tp_name, last_touch_channel, last_touch_discovery
    ),
    interaction_channel_performance AS (
        -- Analyze performance by interaction channel (QR, LINK, NFC, WIFI)
        SELECT 
            interaction_channel,
            COUNT(DISTINCT tp_id) as unique_touchpoints_using_channel,
            SUM(attributed_users) as total_attributed_users,
            SUM(total_attributed_interactions) as total_interactions,
            ROUND(AVG(avg_interactions_per_user), 2) as avg_engagement,
            ROUND(SUM(attributed_users)::DECIMAL / SUM(SUM(attributed_users)) OVER() * 100, 1) as channel_market_share_pct,
            ROUND(AVG(avg_journey_duration_hours), 1) as avg_journey_duration
        FROM first_touch_touchpoint_attribution
        GROUP BY interaction_channel
    ),
    touchpoint_sequence_analysis AS (
        -- Analyze common touchpoint sequences (Premium feature)
        SELECT 
            CASE 
                WHEN first_touch_tp_name != last_touch_tp_name THEN 
                    CONCAT(first_touch_tp_name, ' → ', last_touch_tp_name)
                ELSE first_touch_tp_name
            END as touchpoint_path,
            CASE 
                WHEN first_touch_channel != last_touch_channel THEN 
                    CONCAT(first_touch_channel, ' → ', last_touch_channel)
                ELSE first_touch_channel
            END as channel_path,
            journey_complexity,
            COUNT(*) as users_count,
            ROUND(AVG(total_interactions), 2) as avg_interactions,
            ROUND(AVG(journey_duration_hours), 1) as avg_duration_hours,
            ROUND(COUNT(*)::DECIMAL / SUM(COUNT(*)) OVER() * 100, 1) as path_share_pct
        FROM user_journey_summary
        GROUP BY 
            CASE 
                WHEN first_touch_tp_name != last_touch_tp_name THEN 
                    CONCAT(first_touch_tp_name, ' → ', last_touch_tp_name)
                ELSE first_touch_tp_name
            END,
            CASE 
                WHEN first_touch_channel != last_touch_channel THEN 
                    CONCAT(first_touch_channel, ' → ', last_touch_channel)
                ELSE first_touch_channel
            END,
            journey_complexity
    ),
    touchpoint_channel_combinations AS (
        -- Analyze which touchpoint + channel combinations work best
        SELECT 
            tp_id,
            touchpoint_name,
            interaction_channel,
            discovery_channel,
            SUM(attributed_users) as total_users,
            SUM(total_attributed_interactions) as total_interactions,
            ROUND(AVG(avg_interactions_per_user), 2) as avg_engagement,
            ROUND(SUM(attributed_users)::DECIMAL / SUM(SUM(attributed_users)) OVER() * 100, 1) as combination_share_pct
        FROM first_touch_touchpoint_attribution
        GROUP BY tp_id, touchpoint_name, interaction_channel, discovery_channel
    ),
    attribution_summary AS (
        -- Summary statistics for all attribution models
        SELECT 
            COUNT(DISTINCT fp) as total_users_analyzed,
            ROUND(AVG(total_interactions), 2) as avg_interactions_per_user,
            ROUND(AVG(touchpoints_used), 2) as avg_touchpoints_per_user,
            ROUND(AVG(channels_used), 2) as avg_channels_per_user,
            ROUND(AVG(journey_duration_hours), 1) as avg_journey_duration,
            COUNT(CASE WHEN journey_complexity = 'single_touchpoint' THEN 1 END) as single_touchpoint_journeys,
            COUNT(CASE WHEN journey_complexity = 'two_touchpoint' THEN 1 END) as two_touchpoint_journeys,
            COUNT(CASE WHEN journey_complexity = 'multi_touchpoint' THEN 1 END) as multi_touchpoint_journeys,
            -- Journey complexity metrics
            ROUND(COUNT(CASE WHEN journey_complexity != 'single_touchpoint' THEN 1 END)::DECIMAL / COUNT(*) * 100, 1) as multi_touch_rate_pct,
            COUNT(DISTINCT first_touch_tp_id) as unique_first_touchpoints,
            COUNT(DISTINCT last_touch_tp_id) as unique_last_touchpoints,
            COUNT(DISTINCT first_touch_channel) as unique_first_channels,
            COUNT(DISTINCT last_touch_channel) as unique_last_channels
        FROM user_journey_summary
    )
    SELECT json_build_object(
        'period_info', json_build_object(
            'period_days', p_period_days,
            'start_date', start_date,
            'end_date', end_date,
            'timezone', p_timezone,
            'is_premium', p_is_premium,
            'analysis_type', 'touchpoint_attribution'
        ),
        'filters_applied', json_build_object(
            'has_filters', (p_tag_ids IS NOT NULL OR p_touchpoint_ids IS NOT NULL),
            'tags_count', COALESCE(array_length(p_tag_ids, 1), 0),
            'touchpoints_count', COALESCE(array_length(p_touchpoint_ids, 1), 0)
        ),
        'touchpoint_attribution', json_build_object(
            -- First-touch touchpoint attribution (both tiers)
            'first_touch_attribution', (
                SELECT json_agg(
                    json_build_object(
                        'tp_id', ftta.tp_id,
                        'touchpoint_name', ftta.touchpoint_name,
                        'interaction_channel', ftta.interaction_channel,
                        'discovery_channel', ftta.discovery_channel,
                        'attributed_users', ftta.attributed_users,
                        'total_attributed_interactions', ftta.total_attributed_interactions,
                        'avg_interactions_per_user', ftta.avg_interactions_per_user,
                        'user_share_pct', ROUND(ftta.attributed_users::DECIMAL / (SELECT total_users_analyzed FROM attribution_summary) * 100, 1),
                        'single_touchpoint_users', ftta.single_touchpoint_users,
                        'multi_touchpoint_users', ftta.multi_touchpoint_users,
                        'avg_journey_duration_hours', ftta.avg_journey_duration_hours
                    ) ORDER BY ftta.attributed_users DESC
                )
                FROM first_touch_touchpoint_attribution ftta
            ),
            -- Last-touch touchpoint attribution (both tiers)
            'last_touch_attribution', (
                SELECT json_agg(
                    json_build_object(
                        'tp_id', ltta.tp_id,
                        'touchpoint_name', ltta.touchpoint_name,
                        'interaction_channel', ltta.interaction_channel,
                        'discovery_channel', ltta.discovery_channel,
                        'attributed_users', ltta.attributed_users,
                        'total_attributed_interactions', ltta.total_attributed_interactions,
                        'avg_interactions_per_user', ltta.avg_interactions_per_user,
                        'user_share_pct', ROUND(ltta.attributed_users::DECIMAL / (SELECT total_users_analyzed FROM attribution_summary) * 100, 1),
                        'single_touchpoint_users', ltta.single_touchpoint_users,
                        'multi_touchpoint_users', ltta.multi_touchpoint_users
                    ) ORDER BY ltta.attributed_users DESC
                )
                FROM last_touch_touchpoint_attribution ltta
            ),
            -- Interaction channel performance analysis
            'channel_performance', (
                SELECT json_agg(
                    json_build_object(
                        'interaction_channel', icp.interaction_channel,
                        'unique_touchpoints_using_channel', icp.unique_touchpoints_using_channel,
                        'total_attributed_users', icp.total_attributed_users,
                        'total_interactions', icp.total_interactions,
                        'avg_engagement', icp.avg_engagement,
                        'channel_market_share_pct', icp.channel_market_share_pct,
                        'avg_journey_duration', icp.avg_journey_duration
                    ) ORDER BY icp.total_attributed_users DESC
                )
                FROM interaction_channel_performance icp
            ),
            -- Touchpoint + Channel combinations (Premium only)
            'touchpoint_channel_combinations', CASE 
                WHEN p_is_premium THEN
                    (
                        SELECT json_agg(
                            json_build_object(
                                'tp_id', tcc.tp_id,
                                'touchpoint_name', tcc.touchpoint_name,
                                'interaction_channel', tcc.interaction_channel,
                                'discovery_channel', tcc.discovery_channel,
                                'total_users', tcc.total_users,
                                'total_interactions', tcc.total_interactions,
                                'avg_engagement', tcc.avg_engagement,
                                'combination_share_pct', tcc.combination_share_pct
                            ) ORDER BY tcc.total_users DESC
                        )
                        FROM touchpoint_channel_combinations tcc
                        WHERE tcc.total_users >= 2  -- Only meaningful combinations
                        LIMIT 20  -- Top 20 combinations
                    )
                ELSE NULL
            END,
            -- Touchpoint sequence analysis (Premium only)
            'touchpoint_sequences', CASE 
                WHEN p_is_premium THEN
                    (
                        SELECT json_agg(
                            json_build_object(
                                'touchpoint_path', tsa.touchpoint_path,
                                'channel_path', tsa.channel_path,
                                'journey_complexity', tsa.journey_complexity,
                                'users_count', tsa.users_count,
                                'path_share_pct', tsa.path_share_pct,
                                'avg_interactions', tsa.avg_interactions,
                                'avg_duration_hours', tsa.avg_duration_hours
                            ) ORDER BY tsa.users_count DESC
                        )
                        FROM touchpoint_sequence_analysis tsa
                        WHERE tsa.users_count >= 2  -- Only meaningful sequences
                        LIMIT 15  -- Top 15 sequences
                    )
                ELSE NULL
            END,
            -- Summary statistics
            'summary', (
                SELECT json_build_object(
                    'total_users_analyzed', ats.total_users_analyzed,
                    'avg_interactions_per_user', ats.avg_interactions_per_user,
                    'avg_touchpoints_per_user', ats.avg_touchpoints_per_user,
                    'avg_channels_per_user', ats.avg_channels_per_user,
                    'avg_journey_duration_hours', ats.avg_journey_duration,
                    'multi_touch_rate_pct', ats.multi_touch_rate_pct,
                    'unique_first_touchpoints', ats.unique_first_touchpoints,
                    'unique_last_touchpoints', ats.unique_last_touchpoints,
                    'unique_first_channels', ats.unique_first_channels,
                    'unique_last_channels', ats.unique_last_channels,
                    'journey_distribution', json_build_object(
                        'single_touchpoint', ats.single_touchpoint_journeys,
                        'two_touchpoint', ats.two_touchpoint_journeys,
                        'multi_touchpoint', ats.multi_touchpoint_journeys
                    ),
                    'attribution_reliability', CASE 
                        WHEN ats.total_users_analyzed >= 100 THEN 'high'
                        WHEN ats.total_users_analyzed >= 50 THEN 'medium'
                        WHEN ats.total_users_analyzed >= 20 THEN 'low'
                        ELSE 'insufficient_data'
                    END
                )
                FROM attribution_summary ats
            )
        ),
        'insights', json_build_object(
            -- Basic insights (both tiers)
            'dominant_first_touch_touchpoint', (
                SELECT json_build_object(
                    'tp_id', ftta.tp_id,
                    'touchpoint_name', ftta.touchpoint_name,
                    'interaction_channel', ftta.interaction_channel,
                    'users', ftta.attributed_users,
                    'share_pct', ROUND(ftta.attributed_users::DECIMAL / (SELECT total_users_analyzed FROM attribution_summary) * 100, 1)
                )
                FROM first_touch_touchpoint_attribution ftta
                ORDER BY ftta.attributed_users DESC
                LIMIT 1
            ),
            'dominant_last_touch_touchpoint', (
                SELECT json_build_object(
                    'tp_id', ltta.tp_id,
                    'touchpoint_name', ltta.touchpoint_name,
                    'interaction_channel', ltta.interaction_channel,
                    'users', ltta.attributed_users,
                    'share_pct', ROUND(ltta.attributed_users::DECIMAL / (SELECT total_users_analyzed FROM attribution_summary) * 100, 1)
                )
                FROM last_touch_touchpoint_attribution ltta
                ORDER BY ltta.attributed_users DESC
                LIMIT 1
            ),
            'best_performing_channel', (
                SELECT json_build_object(
                    'interaction_channel', icp.interaction_channel,
                    'market_share_pct', icp.channel_market_share_pct,
                    'avg_engagement', icp.avg_engagement,
                    'unique_touchpoints', icp.unique_touchpoints_using_channel
                )
                FROM interaction_channel_performance icp
                ORDER BY icp.total_attributed_users DESC
                LIMIT 1
            ),
            'touchpoint_model_comparison', (
                SELECT json_build_object(
                    'first_vs_last_touchpoint_difference', CASE 
                        WHEN (SELECT tp_id FROM first_touch_touchpoint_attribution ORDER BY attributed_users DESC LIMIT 1) = 
                             (SELECT tp_id FROM last_touch_touchpoint_attribution ORDER BY attributed_users DESC LIMIT 1) THEN 'consistent_leader'
                        ELSE 'different_leaders'
                    END,
                    'first_vs_last_channel_difference', CASE 
                        WHEN (SELECT interaction_channel FROM first_touch_touchpoint_attribution ORDER BY attributed_users DESC LIMIT 1) = 
                             (SELECT interaction_channel FROM last_touch_touchpoint_attribution ORDER BY attributed_users DESC LIMIT 1) THEN 'consistent_channel'
                        ELSE 'different_channels'
                    END,
                    'multi_touchpoint_significance', CASE 
                        WHEN ats.multi_touch_rate_pct > 60 THEN 'high_multi_touchpoint'
                        WHEN ats.multi_touch_rate_pct > 30 THEN 'moderate_multi_touchpoint'
                        ELSE 'primarily_single_touchpoint'
                    END,
                    'touchpoint_diversity', CASE 
                        WHEN ats.avg_touchpoints_per_user >= 2.5 THEN 'high_diversity'
                        WHEN ats.avg_touchpoints_per_user >= 1.5 THEN 'moderate_diversity'
                        ELSE 'low_diversity'
                    END,
                    'channel_diversity', CASE 
                        WHEN ats.avg_channels_per_user >= 2.5 THEN 'high_channel_diversity'
                        WHEN ats.avg_channels_per_user >= 1.5 THEN 'moderate_channel_diversity'
                        ELSE 'low_channel_diversity'
                    END
                )
                FROM attribution_summary ats
            ),
            -- Premium-only insights
            'premium_insights', CASE 
                WHEN p_is_premium THEN
                    json_build_object(
                        'most_common_touchpoint_journey', (
                            SELECT json_build_object(
                                'touchpoint_path', tsa.touchpoint_path,
                                'channel_path', tsa.channel_path,
                                'users', tsa.users_count,
                                'share_pct', tsa.path_share_pct,
                                'avg_interactions', tsa.avg_interactions
                            )
                            FROM touchpoint_sequence_analysis tsa
                            ORDER BY tsa.users_count DESC
                            LIMIT 1
                        ),
                        'best_touchpoint_channel_combination', (
                            SELECT json_build_object(
                                'touchpoint_name', tcc.touchpoint_name,
                                'interaction_channel', tcc.interaction_channel,
                                'discovery_channel', tcc.discovery_channel,
                                'total_users', tcc.total_users,
                                'avg_engagement', tcc.avg_engagement,
                                'share_pct', tcc.combination_share_pct
                            )
                            FROM touchpoint_channel_combinations tcc
                            ORDER BY tcc.avg_engagement DESC
                            LIMIT 1
                        ),
                        'optimization_opportunities', (
                            SELECT json_agg(
                                json_build_object(
                                    'opportunity_type', CASE 
                                        WHEN ats.multi_touch_rate_pct > 70 THEN 'optimize_touchpoint_sequences'
                                        WHEN ats.avg_touchpoints_per_user < 1.5 THEN 'increase_touchpoint_diversity'
                                        WHEN ats.avg_channels_per_user < 1.5 THEN 'activate_underused_channels'
                                        WHEN ats.unique_first_touchpoints > ats.unique_last_touchpoints * 2 THEN 'improve_conversion_touchpoints'
                                        WHEN ats.avg_journey_duration > 72 THEN 'reduce_journey_friction'
                                        ELSE 'maintain_current_approach'
                                    END,
                                    'confidence_level', CASE 
                                        WHEN ats.total_users_analyzed >= 100 THEN 'high'
                                        WHEN ats.total_users_analyzed >= 50 THEN 'medium'
                                        ELSE 'low'
                                    END,
                                    'supporting_metrics', json_build_object(
                                        'multi_touch_rate_pct', ats.multi_touch_rate_pct,
                                        'avg_touchpoints_per_user', ats.avg_touchpoints_per_user,
                                        'avg_channels_per_user', ats.avg_channels_per_user,
                                        'avg_journey_duration_hours', ats.avg_journey_duration,
                                        'touchpoint_funnel_efficiency', ROUND(ats.unique_last_touchpoints::DECIMAL / ats.unique_first_touchpoints * 100, 1),
                                        'channel_utilization', ROUND(ats.avg_channels_per_user / 4.0 * 100, 1),  -- 4 channels available per touchpoint
                                        'sample_size', ats.total_users_analyzed
                                    )
                                )
                            )
                            FROM attribution_summary ats
                            WHERE ats.total_users_analyzed >= 20
                        )
                    )
                ELSE NULL
            END
        )
    ) INTO result;
    
    RETURN result;
    
EXCEPTION WHEN OTHERS THEN
    RETURN json_build_object(
        'error', TRUE,
        'message', SQLERRM,
        'organization_id', p_organization_id
    );
END;
$$;


--
-- Name: get_acquisition_touchpoint_attribution_old(uuid, integer, text, uuid[], uuid[], boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_acquisition_touchpoint_attribution_old(p_organization_id uuid, p_period_days integer, p_timezone text DEFAULT 'UTC'::text, p_tag_ids uuid[] DEFAULT NULL::uuid[], p_touchpoint_ids uuid[] DEFAULT NULL::uuid[], p_is_premium boolean DEFAULT false) RETURNS json
    LANGUAGE plpgsql
    AS $$DECLARE
    start_date TIMESTAMPTZ;
    end_date TIMESTAMPTZ;
    result JSON;
BEGIN
    -- Validate tier restrictions
    IF NOT p_is_premium AND p_period_days != 7 THEN
        RETURN json_build_object('error', TRUE, 'message', 'Free tier limited to 7 days only');
    END IF;
    
    IF NOT p_is_premium AND p_touchpoint_ids IS NOT NULL AND array_length(p_touchpoint_ids, 1) > 1 THEN
        RETURN json_build_object('error', TRUE, 'message', 'Free tier limited to 1 touchpoint only');
    END IF;

    -- Calculate date range in user's timezone
    end_date := CURRENT_TIMESTAMP AT TIME ZONE p_timezone;
    start_date := end_date - (p_period_days || ' days')::INTERVAL;
    
    WITH filtered_visits AS (
        -- Get visits with touchpoint and channel information
        SELECT 
            v.referrer,
            v.fp,
            v.type as interaction_channel,  -- QR, LINK, NFC, WIFI
            v.created_at,
            v.tp_id,
            v.platform,
            v.country,
            tp.name as touchpoint_name,
            -- Categorize discovery channels (how they found this touchpoint)
            CASE 
                WHEN v.referrer IS NULL OR v.referrer = '' OR v.referrer = 'direct' THEN 'direct'
                WHEN v.referrer ILIKE '%google%' THEN 'google'
                WHEN v.referrer ILIKE '%facebook%' THEN 'facebook'
                WHEN v.referrer ILIKE '%instagram%' THEN 'instagram'
                WHEN v.referrer ILIKE '%twitter%' OR v.referrer ILIKE '%x.com%' THEN 'twitter'
                WHEN v.referrer ILIKE '%linkedin%' THEN 'linkedin'
                WHEN v.referrer ILIKE '%youtube%' THEN 'youtube'
                WHEN v.referrer ILIKE '%tiktok%' THEN 'tiktok'
                WHEN v.referrer ILIKE '%whatsapp%' THEN 'whatsapp'
                WHEN v.referrer ILIKE '%telegram%' THEN 'telegram'
                ELSE 'other'
            END as discovery_channel
        FROM visits v
        INNER JOIN touch_points tp ON v.tp_id = tp.id
        WHERE v.organization_id = p_organization_id
            AND v.created_at >= start_date
            AND v.created_at < end_date            
            AND v.fp IS NOT NULL  -- Only users with valid fingerprints for attribution
            AND tp.deleted_at IS NULL
            AND (
                -- No filtering if no filters specified
                (p_tag_ids IS NULL AND p_touchpoint_ids IS NULL)
                OR 
                -- Apply hierarchical filtering: tags first, then touchpoints
                (
                    (p_tag_ids IS NULL OR v.tp_id IN (
                        SELECT DISTINCT ttl.tp_id 
                        FROM tp_tag_links ttl 
                        WHERE ttl.tag_id = ANY(p_tag_ids)
                    ))
                    AND
                    (p_touchpoint_ids IS NULL OR v.tp_id = ANY(p_touchpoint_ids))
                )
            )
    ),
    user_touchpoint_journeys AS (
        -- Calculate touchpoint attribution for each visit (NO GROUP BY)
        SELECT 
            fp,
            tp_id,
            touchpoint_name,
            interaction_channel,
            discovery_channel,
            created_at,
            -- Window functions to get first and last touchpoint per user
            FIRST_VALUE(tp_id) OVER (PARTITION BY fp ORDER BY created_at ASC) as first_touch_tp_id,
            FIRST_VALUE(touchpoint_name) OVER (PARTITION BY fp ORDER BY created_at ASC) as first_touch_tp_name,
            FIRST_VALUE(interaction_channel) OVER (PARTITION BY fp ORDER BY created_at ASC) as first_touch_channel,
            FIRST_VALUE(discovery_channel) OVER (PARTITION BY fp ORDER BY created_at ASC) as first_touch_discovery,
            
            LAST_VALUE(tp_id) OVER (PARTITION BY fp ORDER BY created_at ASC 
                ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) as last_touch_tp_id,
            LAST_VALUE(touchpoint_name) OVER (PARTITION BY fp ORDER BY created_at ASC 
                ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) as last_touch_tp_name,
            LAST_VALUE(interaction_channel) OVER (PARTITION BY fp ORDER BY created_at ASC 
                ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) as last_touch_channel,
            LAST_VALUE(discovery_channel) OVER (PARTITION BY fp ORDER BY created_at ASC 
                ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) as last_touch_discovery,
            
            -- Journey timeline
            FIRST_VALUE(created_at) OVER (PARTITION BY fp ORDER BY created_at ASC) as first_interaction,
            LAST_VALUE(created_at) OVER (PARTITION BY fp ORDER BY created_at ASC 
                ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) as last_interaction
        FROM filtered_visits
    ),
    user_journey_summary AS (
        -- Aggregate user journey data (NOW we can GROUP BY)
        SELECT 
            fp,
            COUNT(*) as total_interactions,
            COUNT(DISTINCT tp_id) as touchpoints_used,
            COUNT(DISTINCT interaction_channel) as channels_used,
            COUNT(DISTINCT discovery_channel) as discovery_methods_used,
            COUNT(DISTINCT DATE(created_at AT TIME ZONE p_timezone)) as active_days,
            -- Get first and last touch (use ANY since they're the same for each user)
            (ARRAY_AGG(first_touch_tp_id))[1] as first_touch_tp_id,
            (ARRAY_AGG(first_touch_tp_name))[1] as first_touch_tp_name,
            (ARRAY_AGG(first_touch_channel))[1] as first_touch_channel,
            (ARRAY_AGG(first_touch_discovery))[1] as first_touch_discovery,
            (ARRAY_AGG(last_touch_tp_id))[1] as last_touch_tp_id,
            (ARRAY_AGG(last_touch_tp_name))[1] as last_touch_tp_name,
            (ARRAY_AGG(last_touch_channel))[1] as last_touch_channel,
            (ARRAY_AGG(last_touch_discovery))[1] as last_touch_discovery,
            (ARRAY_AGG(first_interaction))[1] as first_interaction,
            (ARRAY_AGG(last_interaction))[1] as last_interaction,
            EXTRACT(EPOCH FROM ((ARRAY_AGG(last_interaction))[1] - (ARRAY_AGG(first_interaction))[1])) / 3600 as journey_duration_hours,
            -- Journey classification
            CASE 
                WHEN COUNT(DISTINCT tp_id) = 1 THEN 'single_touchpoint'
                WHEN COUNT(DISTINCT tp_id) = 2 THEN 'two_touchpoint'
                WHEN COUNT(DISTINCT tp_id) >= 3 THEN 'multi_touchpoint'
            END as journey_complexity
        FROM user_touchpoint_journeys
        GROUP BY fp
    ),
    first_touch_touchpoint_attribution AS (
        -- First-touch touchpoint attribution analysis
        SELECT 
            first_touch_tp_id as tp_id,
            first_touch_tp_name as touchpoint_name,
            first_touch_channel as interaction_channel,
            first_touch_discovery as discovery_channel,
            COUNT(*) as attributed_users,
            SUM(total_interactions) as total_attributed_interactions,
            ROUND(AVG(total_interactions), 2) as avg_interactions_per_user,
            ROUND(AVG(journey_duration_hours), 1) as avg_journey_duration_hours,
            COUNT(CASE WHEN journey_complexity = 'single_touchpoint' THEN 1 END) as single_touchpoint_users,
            COUNT(CASE WHEN journey_complexity = 'multi_touchpoint' THEN 1 END) as multi_touchpoint_users
        FROM user_journey_summary
        GROUP BY first_touch_tp_id, first_touch_tp_name, first_touch_channel, first_touch_discovery
    ),
    last_touch_touchpoint_attribution AS (
        -- Last-touch touchpoint attribution analysis
        SELECT 
            last_touch_tp_id as tp_id,
            last_touch_tp_name as touchpoint_name,
            last_touch_channel as interaction_channel,
            last_touch_discovery as discovery_channel,
            COUNT(*) as attributed_users,
            SUM(total_interactions) as total_attributed_interactions,
            ROUND(AVG(total_interactions), 2) as avg_interactions_per_user,
            COUNT(CASE WHEN journey_complexity = 'single_touchpoint' THEN 1 END) as single_touchpoint_users,
            COUNT(CASE WHEN journey_complexity = 'multi_touchpoint' THEN 1 END) as multi_touchpoint_users
        FROM user_journey_summary
        GROUP BY last_touch_tp_id, last_touch_tp_name, last_touch_channel, last_touch_discovery
    ),
    interaction_channel_performance AS (
        -- Analyze performance by interaction channel (QR, LINK, NFC, WIFI)
        SELECT 
            interaction_channel,
            COUNT(DISTINCT tp_id) as unique_touchpoints_using_channel,
            SUM(attributed_users) as total_attributed_users,
            SUM(total_attributed_interactions) as total_interactions,
            ROUND(AVG(avg_interactions_per_user), 2) as avg_engagement,
            ROUND(SUM(attributed_users)::DECIMAL / SUM(SUM(attributed_users)) OVER() * 100, 1) as channel_market_share_pct,
            ROUND(AVG(avg_journey_duration_hours), 1) as avg_journey_duration
        FROM first_touch_touchpoint_attribution
        GROUP BY interaction_channel
    ),
    touchpoint_sequence_analysis AS (
        -- Analyze common touchpoint sequences (Premium feature)
        SELECT 
            CASE 
                WHEN first_touch_tp_name != last_touch_tp_name THEN 
                    CONCAT(first_touch_tp_name, ' → ', last_touch_tp_name)
                ELSE first_touch_tp_name
            END as touchpoint_path,
            CASE 
                WHEN first_touch_channel != last_touch_channel THEN 
                    CONCAT(first_touch_channel, ' → ', last_touch_channel)
                ELSE first_touch_channel
            END as channel_path,
            journey_complexity,
            COUNT(*) as users_count,
            ROUND(AVG(total_interactions), 2) as avg_interactions,
            ROUND(AVG(journey_duration_hours), 1) as avg_duration_hours,
            ROUND(COUNT(*)::DECIMAL / SUM(COUNT(*)) OVER() * 100, 1) as path_share_pct
        FROM user_journey_summary
        GROUP BY 
            CASE 
                WHEN first_touch_tp_name != last_touch_tp_name THEN 
                    CONCAT(first_touch_tp_name, ' → ', last_touch_tp_name)
                ELSE first_touch_tp_name
            END,
            CASE 
                WHEN first_touch_channel != last_touch_channel THEN 
                    CONCAT(first_touch_channel, ' → ', last_touch_channel)
                ELSE first_touch_channel
            END,
            journey_complexity
    ),
    touchpoint_channel_combinations AS (
        -- Analyze which touchpoint + channel combinations work best
        SELECT 
            tp_id,
            touchpoint_name,
            interaction_channel,
            discovery_channel,
            SUM(attributed_users) as total_users,
            SUM(total_attributed_interactions) as total_interactions,
            ROUND(AVG(avg_interactions_per_user), 2) as avg_engagement,
            ROUND(SUM(attributed_users)::DECIMAL / SUM(SUM(attributed_users)) OVER() * 100, 1) as combination_share_pct
        FROM first_touch_touchpoint_attribution
        GROUP BY tp_id, touchpoint_name, interaction_channel, discovery_channel
    ),
    attribution_summary AS (
        -- Summary statistics for all attribution models
        SELECT 
            COUNT(DISTINCT fp) as total_users_analyzed,
            ROUND(AVG(total_interactions), 2) as avg_interactions_per_user,
            ROUND(AVG(touchpoints_used), 2) as avg_touchpoints_per_user,
            ROUND(AVG(channels_used), 2) as avg_channels_per_user,
            ROUND(AVG(journey_duration_hours), 1) as avg_journey_duration,
            COUNT(CASE WHEN journey_complexity = 'single_touchpoint' THEN 1 END) as single_touchpoint_journeys,
            COUNT(CASE WHEN journey_complexity = 'two_touchpoint' THEN 1 END) as two_touchpoint_journeys,
            COUNT(CASE WHEN journey_complexity = 'multi_touchpoint' THEN 1 END) as multi_touchpoint_journeys,
            -- Journey complexity metrics
            ROUND(COUNT(CASE WHEN journey_complexity != 'single_touchpoint' THEN 1 END)::DECIMAL / COUNT(*) * 100, 1) as multi_touch_rate_pct,
            COUNT(DISTINCT first_touch_tp_id) as unique_first_touchpoints,
            COUNT(DISTINCT last_touch_tp_id) as unique_last_touchpoints,
            COUNT(DISTINCT first_touch_channel) as unique_first_channels,
            COUNT(DISTINCT last_touch_channel) as unique_last_channels
        FROM user_journey_summary
    )
    SELECT json_build_object(
        'period_info', json_build_object(
            'period_days', p_period_days,
            'start_date', start_date,
            'end_date', end_date,
            'timezone', p_timezone,
            'is_premium', p_is_premium,
            'analysis_type', 'touchpoint_attribution'
        ),
        'filters_applied', json_build_object(
            'has_filters', (p_tag_ids IS NOT NULL OR p_touchpoint_ids IS NOT NULL),
            'tags_count', COALESCE(array_length(p_tag_ids, 1), 0),
            'touchpoints_count', COALESCE(array_length(p_touchpoint_ids, 1), 0)
        ),
        'touchpoint_attribution', json_build_object(
            -- First-touch touchpoint attribution (both tiers)
            'first_touch_attribution', (
                SELECT json_agg(
                    json_build_object(
                        'tp_id', ftta.tp_id,
                        'touchpoint_name', ftta.touchpoint_name,
                        'interaction_channel', ftta.interaction_channel,
                        'discovery_channel', ftta.discovery_channel,
                        'attributed_users', ftta.attributed_users,
                        'total_attributed_interactions', ftta.total_attributed_interactions,
                        'avg_interactions_per_user', ftta.avg_interactions_per_user,
                        'user_share_pct', ROUND(ftta.attributed_users::DECIMAL / (SELECT total_users_analyzed FROM attribution_summary) * 100, 1),
                        'single_touchpoint_users', ftta.single_touchpoint_users,
                        'multi_touchpoint_users', ftta.multi_touchpoint_users,
                        'avg_journey_duration_hours', ftta.avg_journey_duration_hours
                    ) ORDER BY ftta.attributed_users DESC
                )
                FROM first_touch_touchpoint_attribution ftta
            ),
            -- Last-touch touchpoint attribution (both tiers)
            'last_touch_attribution', (
                SELECT json_agg(
                    json_build_object(
                        'tp_id', ltta.tp_id,
                        'touchpoint_name', ltta.touchpoint_name,
                        'interaction_channel', ltta.interaction_channel,
                        'discovery_channel', ltta.discovery_channel,
                        'attributed_users', ltta.attributed_users,
                        'total_attributed_interactions', ltta.total_attributed_interactions,
                        'avg_interactions_per_user', ltta.avg_interactions_per_user,
                        'user_share_pct', ROUND(ltta.attributed_users::DECIMAL / (SELECT total_users_analyzed FROM attribution_summary) * 100, 1),
                        'single_touchpoint_users', ltta.single_touchpoint_users,
                        'multi_touchpoint_users', ltta.multi_touchpoint_users
                    ) ORDER BY ltta.attributed_users DESC
                )
                FROM last_touch_touchpoint_attribution ltta
            ),
            -- Interaction channel performance analysis
            'channel_performance', (
                SELECT json_agg(
                    json_build_object(
                        'interaction_channel', icp.interaction_channel,
                        'unique_touchpoints_using_channel', icp.unique_touchpoints_using_channel,
                        'total_attributed_users', icp.total_attributed_users,
                        'total_interactions', icp.total_interactions,
                        'avg_engagement', icp.avg_engagement,
                        'channel_market_share_pct', icp.channel_market_share_pct,
                        'avg_journey_duration', icp.avg_journey_duration
                    ) ORDER BY icp.total_attributed_users DESC
                )
                FROM interaction_channel_performance icp
            ),
            -- Touchpoint + Channel combinations (Premium only)
            'touchpoint_channel_combinations', CASE 
                WHEN p_is_premium THEN
                    (
                        SELECT json_agg(
                            json_build_object(
                                'tp_id', tcc.tp_id,
                                'touchpoint_name', tcc.touchpoint_name,
                                'interaction_channel', tcc.interaction_channel,
                                'discovery_channel', tcc.discovery_channel,
                                'total_users', tcc.total_users,
                                'total_interactions', tcc.total_interactions,
                                'avg_engagement', tcc.avg_engagement,
                                'combination_share_pct', tcc.combination_share_pct
                            ) ORDER BY tcc.total_users DESC
                        )
                        FROM touchpoint_channel_combinations tcc
                        WHERE tcc.total_users >= 2  -- Only meaningful combinations
                        LIMIT 20  -- Top 20 combinations
                    )
                ELSE NULL
            END,
            -- Touchpoint sequence analysis (Premium only)
            'touchpoint_sequences', CASE 
                WHEN p_is_premium THEN
                    (
                        SELECT json_agg(
                            json_build_object(
                                'touchpoint_path', tsa.touchpoint_path,
                                'channel_path', tsa.channel_path,
                                'journey_complexity', tsa.journey_complexity,
                                'users_count', tsa.users_count,
                                'path_share_pct', tsa.path_share_pct,
                                'avg_interactions', tsa.avg_interactions,
                                'avg_duration_hours', tsa.avg_duration_hours
                            ) ORDER BY tsa.users_count DESC
                        )
                        FROM touchpoint_sequence_analysis tsa
                        WHERE tsa.users_count >= 2  -- Only meaningful sequences
                        LIMIT 15  -- Top 15 sequences
                    )
                ELSE NULL
            END,
            -- Summary statistics
            'summary', (
                SELECT json_build_object(
                    'total_users_analyzed', ats.total_users_analyzed,
                    'avg_interactions_per_user', ats.avg_interactions_per_user,
                    'avg_touchpoints_per_user', ats.avg_touchpoints_per_user,
                    'avg_channels_per_user', ats.avg_channels_per_user,
                    'avg_journey_duration_hours', ats.avg_journey_duration,
                    'multi_touch_rate_pct', ats.multi_touch_rate_pct,
                    'unique_first_touchpoints', ats.unique_first_touchpoints,
                    'unique_last_touchpoints', ats.unique_last_touchpoints,
                    'unique_first_channels', ats.unique_first_channels,
                    'unique_last_channels', ats.unique_last_channels,
                    'journey_distribution', json_build_object(
                        'single_touchpoint', ats.single_touchpoint_journeys,
                        'two_touchpoint', ats.two_touchpoint_journeys,
                        'multi_touchpoint', ats.multi_touchpoint_journeys
                    ),
                    'attribution_reliability', CASE 
                        WHEN ats.total_users_analyzed >= 100 THEN 'high'
                        WHEN ats.total_users_analyzed >= 50 THEN 'medium'
                        WHEN ats.total_users_analyzed >= 20 THEN 'low'
                        ELSE 'insufficient_data'
                    END
                )
                FROM attribution_summary ats
            )
        ),
        'insights', json_build_object(
            -- Basic insights (both tiers)
            'dominant_first_touch_touchpoint', (
                SELECT json_build_object(
                    'tp_id', ftta.tp_id,
                    'touchpoint_name', ftta.touchpoint_name,
                    'interaction_channel', ftta.interaction_channel,
                    'users', ftta.attributed_users,
                    'share_pct', ROUND(ftta.attributed_users::DECIMAL / (SELECT total_users_analyzed FROM attribution_summary) * 100, 1)
                )
                FROM first_touch_touchpoint_attribution ftta
                ORDER BY ftta.attributed_users DESC
                LIMIT 1
            ),
            'dominant_last_touch_touchpoint', (
                SELECT json_build_object(
                    'tp_id', ltta.tp_id,
                    'touchpoint_name', ltta.touchpoint_name,
                    'interaction_channel', ltta.interaction_channel,
                    'users', ltta.attributed_users,
                    'share_pct', ROUND(ltta.attributed_users::DECIMAL / (SELECT total_users_analyzed FROM attribution_summary) * 100, 1)
                )
                FROM last_touch_touchpoint_attribution ltta
                ORDER BY ltta.attributed_users DESC
                LIMIT 1
            ),
            'best_performing_channel', (
                SELECT json_build_object(
                    'interaction_channel', icp.interaction_channel,
                    'market_share_pct', icp.channel_market_share_pct,
                    'avg_engagement', icp.avg_engagement,
                    'unique_touchpoints', icp.unique_touchpoints_using_channel
                )
                FROM interaction_channel_performance icp
                ORDER BY icp.total_attributed_users DESC
                LIMIT 1
            ),
            'touchpoint_model_comparison', (
                SELECT json_build_object(
                    'first_vs_last_touchpoint_difference', CASE 
                        WHEN (SELECT tp_id FROM first_touch_touchpoint_attribution ORDER BY attributed_users DESC LIMIT 1) = 
                             (SELECT tp_id FROM last_touch_touchpoint_attribution ORDER BY attributed_users DESC LIMIT 1) THEN 'consistent_leader'
                        ELSE 'different_leaders'
                    END,
                    'first_vs_last_channel_difference', CASE 
                        WHEN (SELECT interaction_channel FROM first_touch_touchpoint_attribution ORDER BY attributed_users DESC LIMIT 1) = 
                             (SELECT interaction_channel FROM last_touch_touchpoint_attribution ORDER BY attributed_users DESC LIMIT 1) THEN 'consistent_channel'
                        ELSE 'different_channels'
                    END,
                    'multi_touchpoint_significance', CASE 
                        WHEN ats.multi_touch_rate_pct > 60 THEN 'high_multi_touchpoint'
                        WHEN ats.multi_touch_rate_pct > 30 THEN 'moderate_multi_touchpoint'
                        ELSE 'primarily_single_touchpoint'
                    END,
                    'touchpoint_diversity', CASE 
                        WHEN ats.avg_touchpoints_per_user >= 2.5 THEN 'high_diversity'
                        WHEN ats.avg_touchpoints_per_user >= 1.5 THEN 'moderate_diversity'
                        ELSE 'low_diversity'
                    END,
                    'channel_diversity', CASE 
                        WHEN ats.avg_channels_per_user >= 2.5 THEN 'high_channel_diversity'
                        WHEN ats.avg_channels_per_user >= 1.5 THEN 'moderate_channel_diversity'
                        ELSE 'low_channel_diversity'
                    END
                )
                FROM attribution_summary ats
            ),
            -- Premium-only insights
            'premium_insights', CASE 
                WHEN p_is_premium THEN
                    json_build_object(
                        'most_common_touchpoint_journey', (
                            SELECT json_build_object(
                                'touchpoint_path', tsa.touchpoint_path,
                                'channel_path', tsa.channel_path,
                                'users', tsa.users_count,
                                'share_pct', tsa.path_share_pct,
                                'avg_interactions', tsa.avg_interactions
                            )
                            FROM touchpoint_sequence_analysis tsa
                            ORDER BY tsa.users_count DESC
                            LIMIT 1
                        ),
                        'best_touchpoint_channel_combination', (
                            SELECT json_build_object(
                                'touchpoint_name', tcc.touchpoint_name,
                                'interaction_channel', tcc.interaction_channel,
                                'discovery_channel', tcc.discovery_channel,
                                'total_users', tcc.total_users,
                                'avg_engagement', tcc.avg_engagement,
                                'share_pct', tcc.combination_share_pct
                            )
                            FROM touchpoint_channel_combinations tcc
                            ORDER BY tcc.avg_engagement DESC
                            LIMIT 1
                        ),
                        'optimization_opportunities', (
                            SELECT json_agg(
                                json_build_object(
                                    'opportunity_type', CASE 
                                        WHEN ats.multi_touch_rate_pct > 70 THEN 'optimize_touchpoint_sequences'
                                        WHEN ats.avg_touchpoints_per_user < 1.5 THEN 'increase_touchpoint_diversity'
                                        WHEN ats.avg_channels_per_user < 1.5 THEN 'activate_underused_channels'
                                        WHEN ats.unique_first_touchpoints > ats.unique_last_touchpoints * 2 THEN 'improve_conversion_touchpoints'
                                        WHEN ats.avg_journey_duration > 72 THEN 'reduce_journey_friction'
                                        ELSE 'maintain_current_approach'
                                    END,
                                    'confidence_level', CASE 
                                        WHEN ats.total_users_analyzed >= 100 THEN 'high'
                                        WHEN ats.total_users_analyzed >= 50 THEN 'medium'
                                        ELSE 'low'
                                    END,
                                    'supporting_metrics', json_build_object(
                                        'multi_touch_rate_pct', ats.multi_touch_rate_pct,
                                        'avg_touchpoints_per_user', ats.avg_touchpoints_per_user,
                                        'avg_channels_per_user', ats.avg_channels_per_user,
                                        'avg_journey_duration_hours', ats.avg_journey_duration,
                                        'touchpoint_funnel_efficiency', ROUND(ats.unique_last_touchpoints::DECIMAL / ats.unique_first_touchpoints * 100, 1),
                                        'channel_utilization', ROUND(ats.avg_channels_per_user / 4.0 * 100, 1),  -- 4 channels available per touchpoint
                                        'sample_size', ats.total_users_analyzed
                                    )
                                )
                            )
                            FROM attribution_summary ats
                            WHERE ats.total_users_analyzed >= 20
                        )
                    )
                ELSE NULL
            END
        )
    ) INTO result;
    
    RETURN result;
    
EXCEPTION WHEN OTHERS THEN
    RETURN json_build_object(
        'error', TRUE,
        'message', SQLERRM,
        'organization_id', p_organization_id
    );
END;$$;


--
-- Name: get_acquisition_traffic_sources(uuid, integer, text, uuid[], uuid[], boolean, uuid[], boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_acquisition_traffic_sources(p_organization_id uuid, p_period_days integer, p_timezone text DEFAULT 'UTC'::text, p_tag_ids uuid[] DEFAULT NULL::uuid[], p_touchpoint_ids uuid[] DEFAULT NULL::uuid[], p_is_premium boolean DEFAULT false, p_collection_ids uuid[] DEFAULT NULL::uuid[], p_include_null_collection boolean DEFAULT false) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    start_date TIMESTAMPTZ;
    end_date TIMESTAMPTZ;
    result JSON;
BEGIN
    -- Validate tier restrictions
    IF NOT p_is_premium AND p_period_days != 7 THEN
        RETURN json_build_object('error', TRUE, 'message', 'Free tier limited to 7 days only');
    END IF;
    
    IF NOT p_is_premium AND p_touchpoint_ids IS NOT NULL AND array_length(p_touchpoint_ids, 1) > 1 THEN
        RETURN json_build_object('error', TRUE, 'message', 'Free tier limited to 1 touchpoint only');
    END IF;

    -- Calculate date range in user's timezone
    end_date := CURRENT_TIMESTAMP AT TIME ZONE p_timezone;
    start_date := end_date - (p_period_days || ' days')::INTERVAL;
    
    WITH filtered_visits AS (
        -- Apply hierarchical filtering to visits
        SELECT 
            v.referrer,
            v.fp,
            v.type,
            v.created_at,
            v.tp_id,
            v.platform,
            v.country
        FROM visits v
        WHERE v.organization_id = p_organization_id
            AND v.created_at >= start_date
            AND v.created_at < end_date            
            AND (
                -- No filtering if no filters specified
                (p_tag_ids IS NULL AND p_touchpoint_ids IS NULL)
                OR 
                -- Apply hierarchical filtering: tags first, then touchpoints
                (
                    (p_tag_ids IS NULL OR v.tp_id IN (
                        SELECT DISTINCT ttl.tp_id 
                        FROM tp_tag_links ttl 
                        WHERE ttl.tag_id = ANY(p_tag_ids)
                    ))
                    AND
                    (p_touchpoint_ids IS NULL OR v.tp_id = ANY(p_touchpoint_ids))
                )
            )
            AND (
                p_collection_ids IS NULL
                OR v.tp_id IN (
                    SELECT tp.id
                    FROM touch_points tp
                    WHERE tp.collection_id = ANY(p_collection_ids)
                       OR (p_include_null_collection AND tp.collection_id IS NULL)
                )
            )
    ),
    source_aggregation AS (
        -- Traffic source analysis with quality metrics
        SELECT 
            CASE 
                WHEN referrer IS NULL OR referrer = '' OR referrer = 'direct' THEN 'direct'
                WHEN referrer ILIKE '%google%' THEN 'google'
                WHEN referrer ILIKE '%facebook%' THEN 'facebook'
                WHEN referrer ILIKE '%instagram%' THEN 'instagram'
                WHEN referrer ILIKE '%twitter%' OR referrer ILIKE '%x.com%' THEN 'twitter'
                WHEN referrer ILIKE '%linkedin%' THEN 'linkedin'
                WHEN referrer ILIKE '%youtube%' THEN 'youtube'
                WHEN referrer ILIKE '%tiktok%' THEN 'tiktok'
                WHEN referrer ILIKE '%whatsapp%' THEN 'whatsapp'
                WHEN referrer ILIKE '%telegram%' THEN 'telegram'
                ELSE referrer
            END as source_category,
            COALESCE(referrer, 'direct') as original_referrer,
            COUNT(*) as total_visits,
            COUNT(DISTINCT fp) as unique_users,
            COUNT(DISTINCT tp_id) as touchpoints_accessed,
            COUNT(CASE WHEN type = 'LINK' THEN 1 END) as link_interactions,
            COUNT(CASE WHEN type = 'QR' THEN 1 END) as qr_interactions,
            COUNT(CASE WHEN type = 'NFC' THEN 1 END) as nfc_interactions,
            COUNT(CASE WHEN type = 'WIFI' THEN 1 END) as wifi_interactions,
            -- Engagement metrics for quality scoring
            ROUND(COUNT(*)::DECIMAL / NULLIF(COUNT(DISTINCT fp), 0), 2) as visits_per_user,
            COUNT(DISTINCT country) as countries_reached,
            COUNT(DISTINCT DATE(created_at AT TIME ZONE p_timezone)) as active_days,
            -- Platform preferences by source
            COUNT(CASE WHEN platform = 'Mobile' THEN 1 END) as mobile_visits,
            COUNT(CASE WHEN platform = 'Desktop' THEN 1 END) as desktop_visits,
            -- Repeat visitor analysis (Premium insight)
            COUNT(DISTINCT fp) FILTER (
                WHERE fp IN (
                    SELECT fp 
                    FROM filtered_visits 
                    GROUP BY fp 
                    HAVING COUNT(*) > 1
                )
            ) as repeat_users,
            -- Market share calculation
            ROUND(COUNT(*)::DECIMAL / SUM(COUNT(*)) OVER() * 100, 1) as source_share_pct
        FROM filtered_visits
        GROUP BY 
            CASE 
                WHEN referrer IS NULL OR referrer = '' OR referrer = 'direct' THEN 'direct'
                WHEN referrer ILIKE '%google%' THEN 'google'
                WHEN referrer ILIKE '%facebook%' THEN 'facebook'
                WHEN referrer ILIKE '%instagram%' THEN 'instagram'
                WHEN referrer ILIKE '%twitter%' OR referrer ILIKE '%x.com%' THEN 'twitter'
                WHEN referrer ILIKE '%linkedin%' THEN 'linkedin'
                WHEN referrer ILIKE '%youtube%' THEN 'youtube'
                WHEN referrer ILIKE '%tiktok%' THEN 'tiktok'
                WHEN referrer ILIKE '%whatsapp%' THEN 'whatsapp'
                WHEN referrer ILIKE '%telegram%' THEN 'telegram'
                ELSE referrer
            END,
            COALESCE(referrer, 'direct')
    ),
    source_quality_scoring AS (
        -- Calculate quality scores for each source
        SELECT 
            *,
            -- Quality score components (0-100 scale)
            CASE 
                WHEN visits_per_user >= 3.0 THEN 25
                WHEN visits_per_user >= 2.0 THEN 20
                WHEN visits_per_user >= 1.5 THEN 15
                WHEN visits_per_user >= 1.2 THEN 10
                ELSE 5
            END as engagement_score,
            
            CASE 
                WHEN source_share_pct >= 20 THEN 25
                WHEN source_share_pct >= 10 THEN 20
                WHEN source_share_pct >= 5 THEN 15
                WHEN source_share_pct >= 1 THEN 10
                ELSE 5
            END as volume_score,
            
            CASE 
                WHEN countries_reached >= 5 THEN 20
                WHEN countries_reached >= 3 THEN 15
                WHEN countries_reached >= 2 THEN 10
                ELSE 5
            END as reach_score,
            
            CASE 
                WHEN active_days >= p_period_days * 0.7 THEN 15
                WHEN active_days >= p_period_days * 0.5 THEN 12
                WHEN active_days >= p_period_days * 0.3 THEN 8
                ELSE 5
            END as consistency_score,
            
            CASE 
                WHEN touchpoints_accessed >= 3 THEN 15
                WHEN touchpoints_accessed >= 2 THEN 10
                ELSE 5
            END as diversity_score,
            
            -- Repeat user rate for Premium scoring
            ROUND(repeat_users::DECIMAL / NULLIF(unique_users, 0) * 100, 1) as repeat_user_rate
        FROM source_aggregation
    ),
    final_source_ranking AS (
        -- Calculate final quality scores and rankings
        SELECT 
            *,
            (engagement_score + volume_score + reach_score + consistency_score + diversity_score) as quality_score,
            ROW_NUMBER() OVER (ORDER BY total_visits DESC) as volume_rank,
            ROW_NUMBER() OVER (ORDER BY visits_per_user DESC) as engagement_rank,
            -- Quality-based ranking
            ROW_NUMBER() OVER (ORDER BY (engagement_score + volume_score + reach_score + consistency_score + diversity_score) DESC) as quality_rank,
            -- Quality tier classification
            CASE 
                WHEN (engagement_score + volume_score + reach_score + consistency_score + diversity_score) >= 80 THEN 'excellent'
                WHEN (engagement_score + volume_score + reach_score + consistency_score + diversity_score) >= 60 THEN 'good'
                WHEN (engagement_score + volume_score + reach_score + consistency_score + diversity_score) >= 40 THEN 'average'
                ELSE 'needs_improvement'
            END as quality_tier
        FROM source_quality_scoring
    ),
    source_summary AS (
        -- Summary statistics
        SELECT 
            COUNT(DISTINCT source_category) as total_source_categories,
            COUNT(*) as total_sources,
            SUM(total_visits) as total_visits_all,
            SUM(unique_users) as total_unique_users,
            ROUND(AVG(visits_per_user), 2) as avg_engagement_rate,
            ROUND(AVG(quality_score), 1) as avg_quality_score
        FROM final_source_ranking
    )
    SELECT json_build_object(
        'period_info', json_build_object(
            'period_days', p_period_days,
            'start_date', start_date,
            'end_date', end_date,
            'timezone', p_timezone,
            'is_premium', p_is_premium
        ),
        'filters_applied', json_build_object(
            'has_filters', (p_tag_ids IS NOT NULL OR p_touchpoint_ids IS NOT NULL),
            'tags_count', COALESCE(array_length(p_tag_ids, 1), 0),
            'touchpoints_count', COALESCE(array_length(p_touchpoint_ids, 1), 0)
        ),
        'traffic_sources', json_build_object(
            -- Tier-specific source data
            'sources', CASE 
                WHEN p_is_premium THEN
                    -- Premium: Full source list with quality scoring
                    (
                        SELECT json_agg(
                            json_build_object(
                                'source_category', fsr.source_category,
                                'original_referrer', fsr.original_referrer,
                                'volume_rank', fsr.volume_rank,
                                'engagement_rank', fsr.engagement_rank,
                                'quality_rank', fsr.quality_rank,
                                'quality_score', fsr.quality_score,
                                'quality_tier', fsr.quality_tier,
                                'total_visits', fsr.total_visits,
                                'unique_users', fsr.unique_users,
                                'source_share_pct', fsr.source_share_pct,
                                'visits_per_user', fsr.visits_per_user,
                                'repeat_user_rate', fsr.repeat_user_rate,
                                'touchpoints_accessed', fsr.touchpoints_accessed,
                                'countries_reached', fsr.countries_reached,
                                'active_days', fsr.active_days,
                                'platform_distribution', json_build_object(
                                    'mobile_visits', fsr.mobile_visits,
                                    'desktop_visits', fsr.desktop_visits,
                                    'mobile_pct', ROUND(fsr.mobile_visits::DECIMAL / fsr.total_visits * 100, 1)
                                ),
                                'interaction_breakdown', json_build_object(
                                    'link_interactions', fsr.link_interactions,
                                    'qr_interactions', fsr.qr_interactions,
                                    'nfc_interactions', fsr.nfc_interactions,
                                    'wifi_interactions', fsr.wifi_interactions
                                ),
                                'quality_breakdown', json_build_object(
                                    'engagement_score', fsr.engagement_score,
                                    'volume_score', fsr.volume_score,
                                    'reach_score', fsr.reach_score,
                                    'consistency_score', fsr.consistency_score,
                                    'diversity_score', fsr.diversity_score
                                )
                            ) ORDER BY fsr.quality_rank
                        )
                        FROM final_source_ranking fsr
                    )
                ELSE
                    -- Free: Top 5 sources by volume only
                    (
                        SELECT json_agg(
                            json_build_object(
                                'source_category', fsr.source_category,
                                'volume_rank', fsr.volume_rank,
                                'total_visits', fsr.total_visits,
                                'unique_users', fsr.unique_users,
                                'source_share_pct', fsr.source_share_pct,
                                'visits_per_user', fsr.visits_per_user
                            ) ORDER BY fsr.volume_rank
                        )
                        FROM final_source_ranking fsr
                        WHERE fsr.volume_rank <= 5
                    )
            END,
            -- Summary with tier-appropriate data
            'summary', (
                SELECT json_build_object(
                    'total_source_categories', ss.total_source_categories,
                    'total_sources', ss.total_sources,
                    'sources_shown', CASE WHEN p_is_premium THEN ss.total_sources ELSE LEAST(5, ss.total_sources) END,
                    'total_visits', ss.total_visits_all,
                    'total_unique_users', ss.total_unique_users,
                    'avg_engagement_rate', ss.avg_engagement_rate,
                    'avg_quality_score', CASE WHEN p_is_premium THEN ss.avg_quality_score ELSE NULL END
                )
                FROM source_summary ss
            )
        ),
        'insights', json_build_object(
            -- Basic insights (both tiers)
            'top_source', (
                SELECT json_build_object(
                    'source_category', fsr.source_category,
                    'visits', fsr.total_visits,
                    'market_share_pct', fsr.source_share_pct,
                    'engagement_rate', fsr.visits_per_user
                )
                FROM final_source_ranking fsr
                WHERE fsr.volume_rank = 1
            ),
            'source_diversity', (
                SELECT CASE 
                    WHEN ss.total_source_categories >= 6 THEN 'high_diversity'
                    WHEN ss.total_source_categories >= 3 THEN 'medium_diversity'
                    ELSE 'low_diversity'
                END
                FROM source_summary ss
            ),
            -- Premium-only insights
            'premium_insights', CASE 
                WHEN p_is_premium THEN
                    json_build_object(
                        'highest_quality_source', (
                            SELECT json_build_object(
                                'source_category', fsr.source_category,
                                'quality_score', fsr.quality_score,
                                'quality_tier', fsr.quality_tier,
                                'visits_per_user', fsr.visits_per_user,
                                'repeat_user_rate', fsr.repeat_user_rate
                            )
                            FROM final_source_ranking fsr
                            WHERE fsr.quality_rank = 1
                        ),
                        'source_recommendations', (
                            SELECT json_agg(recommendation)
                            FROM (
                                SELECT CASE 
                                    WHEN fsr.quality_tier = 'excellent' AND fsr.source_share_pct < 20 THEN 
                                        CONCAT('Scale up ', fsr.source_category, ' - high quality, low volume')
                                    WHEN fsr.quality_tier = 'needs_improvement' AND fsr.source_share_pct > 10 THEN 
                                        CONCAT('Optimize ', fsr.source_category, ' experience - high volume, low quality')
                                    WHEN fsr.repeat_user_rate < 20 AND fsr.total_visits > 50 THEN 
                                        CONCAT('Improve ', fsr.source_category, ' retention - low repeat rate')
                                    WHEN fsr.countries_reached = 1 AND fsr.total_visits > 100 THEN 
                                        CONCAT('Expand ', fsr.source_category, ' geographic reach')
                                    ELSE NULL
                                END as recommendation
                                FROM final_source_ranking fsr
                                WHERE fsr.total_visits >= 10  -- Only meaningful data
                            ) recommendations
                            WHERE recommendation IS NOT NULL
                        ),
                        'quality_distribution', json_build_object(
                            'excellent_sources', (SELECT COUNT(*) FROM final_source_ranking WHERE quality_tier = 'excellent'),
                            'good_sources', (SELECT COUNT(*) FROM final_source_ranking WHERE quality_tier = 'good'),
                            'average_sources', (SELECT COUNT(*) FROM final_source_ranking WHERE quality_tier = 'average'),
                            'needs_improvement_sources', (SELECT COUNT(*) FROM final_source_ranking WHERE quality_tier = 'needs_improvement')
                        )
                    )
                ELSE 
                    NULL
            END
        )
    ) INTO result;
    
    RETURN result;
    
EXCEPTION WHEN OTHERS THEN
    RETURN json_build_object(
        'error', TRUE,
        'message', SQLERRM,
        'organization_id', p_organization_id
    );
END;
$$;


--
-- Name: get_acquisition_traffic_sources_old(uuid, integer, text, uuid[], uuid[], boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_acquisition_traffic_sources_old(p_organization_id uuid, p_period_days integer, p_timezone text DEFAULT 'UTC'::text, p_tag_ids uuid[] DEFAULT NULL::uuid[], p_touchpoint_ids uuid[] DEFAULT NULL::uuid[], p_is_premium boolean DEFAULT false) RETURNS json
    LANGUAGE plpgsql
    AS $$DECLARE
    start_date TIMESTAMPTZ;
    end_date TIMESTAMPTZ;
    result JSON;
BEGIN
    -- Validate tier restrictions
    IF NOT p_is_premium AND p_period_days != 7 THEN
        RETURN json_build_object('error', TRUE, 'message', 'Free tier limited to 7 days only');
    END IF;
    
    IF NOT p_is_premium AND p_touchpoint_ids IS NOT NULL AND array_length(p_touchpoint_ids, 1) > 1 THEN
        RETURN json_build_object('error', TRUE, 'message', 'Free tier limited to 1 touchpoint only');
    END IF;

    -- Calculate date range in user's timezone
    end_date := CURRENT_TIMESTAMP AT TIME ZONE p_timezone;
    start_date := end_date - (p_period_days || ' days')::INTERVAL;
    
    WITH filtered_visits AS (
        -- Apply hierarchical filtering to visits
        SELECT 
            v.referrer,
            v.fp,
            v.type,
            v.created_at,
            v.tp_id,
            v.platform,
            v.country
        FROM visits v
        WHERE v.organization_id = p_organization_id
            AND v.created_at >= start_date
            AND v.created_at < end_date            
            AND (
                -- No filtering if no filters specified
                (p_tag_ids IS NULL AND p_touchpoint_ids IS NULL)
                OR 
                -- Apply hierarchical filtering: tags first, then touchpoints
                (
                    (p_tag_ids IS NULL OR v.tp_id IN (
                        SELECT DISTINCT ttl.tp_id 
                        FROM tp_tag_links ttl 
                        WHERE ttl.tag_id = ANY(p_tag_ids)
                    ))
                    AND
                    (p_touchpoint_ids IS NULL OR v.tp_id = ANY(p_touchpoint_ids))
                )
            )
    ),
    source_aggregation AS (
        -- Traffic source analysis with quality metrics
        SELECT 
            CASE 
                WHEN referrer IS NULL OR referrer = '' OR referrer = 'direct' THEN 'direct'
                WHEN referrer ILIKE '%google%' THEN 'google'
                WHEN referrer ILIKE '%facebook%' THEN 'facebook'
                WHEN referrer ILIKE '%instagram%' THEN 'instagram'
                WHEN referrer ILIKE '%twitter%' OR referrer ILIKE '%x.com%' THEN 'twitter'
                WHEN referrer ILIKE '%linkedin%' THEN 'linkedin'
                WHEN referrer ILIKE '%youtube%' THEN 'youtube'
                WHEN referrer ILIKE '%tiktok%' THEN 'tiktok'
                WHEN referrer ILIKE '%whatsapp%' THEN 'whatsapp'
                WHEN referrer ILIKE '%telegram%' THEN 'telegram'
                ELSE referrer
            END as source_category,
            COALESCE(referrer, 'direct') as original_referrer,
            COUNT(*) as total_visits,
            COUNT(DISTINCT fp) as unique_users,
            COUNT(DISTINCT tp_id) as touchpoints_accessed,
            COUNT(CASE WHEN type = 'LINK' THEN 1 END) as link_interactions,
            COUNT(CASE WHEN type = 'QR' THEN 1 END) as qr_interactions,
            COUNT(CASE WHEN type = 'NFC' THEN 1 END) as nfc_interactions,
            COUNT(CASE WHEN type = 'WIFI' THEN 1 END) as wifi_interactions,
            -- Engagement metrics for quality scoring
            ROUND(COUNT(*)::DECIMAL / NULLIF(COUNT(DISTINCT fp), 0), 2) as visits_per_user,
            COUNT(DISTINCT country) as countries_reached,
            COUNT(DISTINCT DATE(created_at AT TIME ZONE p_timezone)) as active_days,
            -- Platform preferences by source
            COUNT(CASE WHEN platform = 'Mobile' THEN 1 END) as mobile_visits,
            COUNT(CASE WHEN platform = 'Desktop' THEN 1 END) as desktop_visits,
            -- Repeat visitor analysis (Premium insight)
            COUNT(DISTINCT fp) FILTER (
                WHERE fp IN (
                    SELECT fp 
                    FROM filtered_visits 
                    GROUP BY fp 
                    HAVING COUNT(*) > 1
                )
            ) as repeat_users,
            -- Market share calculation
            ROUND(COUNT(*)::DECIMAL / SUM(COUNT(*)) OVER() * 100, 1) as source_share_pct
        FROM filtered_visits
        GROUP BY 
            CASE 
                WHEN referrer IS NULL OR referrer = '' OR referrer = 'direct' THEN 'direct'
                WHEN referrer ILIKE '%google%' THEN 'google'
                WHEN referrer ILIKE '%facebook%' THEN 'facebook'
                WHEN referrer ILIKE '%instagram%' THEN 'instagram'
                WHEN referrer ILIKE '%twitter%' OR referrer ILIKE '%x.com%' THEN 'twitter'
                WHEN referrer ILIKE '%linkedin%' THEN 'linkedin'
                WHEN referrer ILIKE '%youtube%' THEN 'youtube'
                WHEN referrer ILIKE '%tiktok%' THEN 'tiktok'
                WHEN referrer ILIKE '%whatsapp%' THEN 'whatsapp'
                WHEN referrer ILIKE '%telegram%' THEN 'telegram'
                ELSE referrer
            END,
            COALESCE(referrer, 'direct')
    ),
    source_quality_scoring AS (
        -- Calculate quality scores for each source
        SELECT 
            *,
            -- Quality score components (0-100 scale)
            CASE 
                WHEN visits_per_user >= 3.0 THEN 25
                WHEN visits_per_user >= 2.0 THEN 20
                WHEN visits_per_user >= 1.5 THEN 15
                WHEN visits_per_user >= 1.2 THEN 10
                ELSE 5
            END as engagement_score,
            
            CASE 
                WHEN source_share_pct >= 20 THEN 25
                WHEN source_share_pct >= 10 THEN 20
                WHEN source_share_pct >= 5 THEN 15
                WHEN source_share_pct >= 1 THEN 10
                ELSE 5
            END as volume_score,
            
            CASE 
                WHEN countries_reached >= 5 THEN 20
                WHEN countries_reached >= 3 THEN 15
                WHEN countries_reached >= 2 THEN 10
                ELSE 5
            END as reach_score,
            
            CASE 
                WHEN active_days >= p_period_days * 0.7 THEN 15
                WHEN active_days >= p_period_days * 0.5 THEN 12
                WHEN active_days >= p_period_days * 0.3 THEN 8
                ELSE 5
            END as consistency_score,
            
            CASE 
                WHEN touchpoints_accessed >= 3 THEN 15
                WHEN touchpoints_accessed >= 2 THEN 10
                ELSE 5
            END as diversity_score,
            
            -- Repeat user rate for Premium scoring
            ROUND(repeat_users::DECIMAL / NULLIF(unique_users, 0) * 100, 1) as repeat_user_rate
        FROM source_aggregation
    ),
    final_source_ranking AS (
        -- Calculate final quality scores and rankings
        SELECT 
            *,
            (engagement_score + volume_score + reach_score + consistency_score + diversity_score) as quality_score,
            ROW_NUMBER() OVER (ORDER BY total_visits DESC) as volume_rank,
            ROW_NUMBER() OVER (ORDER BY visits_per_user DESC) as engagement_rank,
            -- Quality-based ranking
            ROW_NUMBER() OVER (ORDER BY (engagement_score + volume_score + reach_score + consistency_score + diversity_score) DESC) as quality_rank,
            -- Quality tier classification
            CASE 
                WHEN (engagement_score + volume_score + reach_score + consistency_score + diversity_score) >= 80 THEN 'excellent'
                WHEN (engagement_score + volume_score + reach_score + consistency_score + diversity_score) >= 60 THEN 'good'
                WHEN (engagement_score + volume_score + reach_score + consistency_score + diversity_score) >= 40 THEN 'average'
                ELSE 'needs_improvement'
            END as quality_tier
        FROM source_quality_scoring
    ),
    source_summary AS (
        -- Summary statistics
        SELECT 
            COUNT(DISTINCT source_category) as total_source_categories,
            COUNT(*) as total_sources,
            SUM(total_visits) as total_visits_all,
            SUM(unique_users) as total_unique_users,
            ROUND(AVG(visits_per_user), 2) as avg_engagement_rate,
            ROUND(AVG(quality_score), 1) as avg_quality_score
        FROM final_source_ranking
    )
    SELECT json_build_object(
        'period_info', json_build_object(
            'period_days', p_period_days,
            'start_date', start_date,
            'end_date', end_date,
            'timezone', p_timezone,
            'is_premium', p_is_premium
        ),
        'filters_applied', json_build_object(
            'has_filters', (p_tag_ids IS NOT NULL OR p_touchpoint_ids IS NOT NULL),
            'tags_count', COALESCE(array_length(p_tag_ids, 1), 0),
            'touchpoints_count', COALESCE(array_length(p_touchpoint_ids, 1), 0)
        ),
        'traffic_sources', json_build_object(
            -- Tier-specific source data
            'sources', CASE 
                WHEN p_is_premium THEN
                    -- Premium: Full source list with quality scoring
                    (
                        SELECT json_agg(
                            json_build_object(
                                'source_category', fsr.source_category,
                                'original_referrer', fsr.original_referrer,
                                'volume_rank', fsr.volume_rank,
                                'engagement_rank', fsr.engagement_rank,
                                'quality_rank', fsr.quality_rank,
                                'quality_score', fsr.quality_score,
                                'quality_tier', fsr.quality_tier,
                                'total_visits', fsr.total_visits,
                                'unique_users', fsr.unique_users,
                                'source_share_pct', fsr.source_share_pct,
                                'visits_per_user', fsr.visits_per_user,
                                'repeat_user_rate', fsr.repeat_user_rate,
                                'touchpoints_accessed', fsr.touchpoints_accessed,
                                'countries_reached', fsr.countries_reached,
                                'active_days', fsr.active_days,
                                'platform_distribution', json_build_object(
                                    'mobile_visits', fsr.mobile_visits,
                                    'desktop_visits', fsr.desktop_visits,
                                    'mobile_pct', ROUND(fsr.mobile_visits::DECIMAL / fsr.total_visits * 100, 1)
                                ),
                                'interaction_breakdown', json_build_object(
                                    'link_interactions', fsr.link_interactions,
                                    'qr_interactions', fsr.qr_interactions,
                                    'nfc_interactions', fsr.nfc_interactions,
                                    'wifi_interactions', fsr.wifi_interactions
                                ),
                                'quality_breakdown', json_build_object(
                                    'engagement_score', fsr.engagement_score,
                                    'volume_score', fsr.volume_score,
                                    'reach_score', fsr.reach_score,
                                    'consistency_score', fsr.consistency_score,
                                    'diversity_score', fsr.diversity_score
                                )
                            ) ORDER BY fsr.quality_rank
                        )
                        FROM final_source_ranking fsr
                    )
                ELSE
                    -- Free: Top 5 sources by volume only
                    (
                        SELECT json_agg(
                            json_build_object(
                                'source_category', fsr.source_category,
                                'volume_rank', fsr.volume_rank,
                                'total_visits', fsr.total_visits,
                                'unique_users', fsr.unique_users,
                                'source_share_pct', fsr.source_share_pct,
                                'visits_per_user', fsr.visits_per_user
                            ) ORDER BY fsr.volume_rank
                        )
                        FROM final_source_ranking fsr
                        WHERE fsr.volume_rank <= 5
                    )
            END,
            -- Summary with tier-appropriate data
            'summary', (
                SELECT json_build_object(
                    'total_source_categories', ss.total_source_categories,
                    'total_sources', ss.total_sources,
                    'sources_shown', CASE WHEN p_is_premium THEN ss.total_sources ELSE LEAST(5, ss.total_sources) END,
                    'total_visits', ss.total_visits_all,
                    'total_unique_users', ss.total_unique_users,
                    'avg_engagement_rate', ss.avg_engagement_rate,
                    'avg_quality_score', CASE WHEN p_is_premium THEN ss.avg_quality_score ELSE NULL END
                )
                FROM source_summary ss
            )
        ),
        'insights', json_build_object(
            -- Basic insights (both tiers)
            'top_source', (
                SELECT json_build_object(
                    'source_category', fsr.source_category,
                    'visits', fsr.total_visits,
                    'market_share_pct', fsr.source_share_pct,
                    'engagement_rate', fsr.visits_per_user
                )
                FROM final_source_ranking fsr
                WHERE fsr.volume_rank = 1
            ),
            'source_diversity', (
                SELECT CASE 
                    WHEN ss.total_source_categories >= 6 THEN 'high_diversity'
                    WHEN ss.total_source_categories >= 3 THEN 'medium_diversity'
                    ELSE 'low_diversity'
                END
                FROM source_summary ss
            ),
            -- Premium-only insights
            'premium_insights', CASE 
                WHEN p_is_premium THEN
                    json_build_object(
                        'highest_quality_source', (
                            SELECT json_build_object(
                                'source_category', fsr.source_category,
                                'quality_score', fsr.quality_score,
                                'quality_tier', fsr.quality_tier,
                                'visits_per_user', fsr.visits_per_user,
                                'repeat_user_rate', fsr.repeat_user_rate
                            )
                            FROM final_source_ranking fsr
                            WHERE fsr.quality_rank = 1
                        ),
                        'source_recommendations', (
                            SELECT json_agg(recommendation)
                            FROM (
                                SELECT CASE 
                                    WHEN fsr.quality_tier = 'excellent' AND fsr.source_share_pct < 20 THEN 
                                        CONCAT('Scale up ', fsr.source_category, ' - high quality, low volume')
                                    WHEN fsr.quality_tier = 'needs_improvement' AND fsr.source_share_pct > 10 THEN 
                                        CONCAT('Optimize ', fsr.source_category, ' experience - high volume, low quality')
                                    WHEN fsr.repeat_user_rate < 20 AND fsr.total_visits > 50 THEN 
                                        CONCAT('Improve ', fsr.source_category, ' retention - low repeat rate')
                                    WHEN fsr.countries_reached = 1 AND fsr.total_visits > 100 THEN 
                                        CONCAT('Expand ', fsr.source_category, ' geographic reach')
                                    ELSE NULL
                                END as recommendation
                                FROM final_source_ranking fsr
                                WHERE fsr.total_visits >= 10  -- Only meaningful data
                            ) recommendations
                            WHERE recommendation IS NOT NULL
                        ),
                        'quality_distribution', json_build_object(
                            'excellent_sources', (SELECT COUNT(*) FROM final_source_ranking WHERE quality_tier = 'excellent'),
                            'good_sources', (SELECT COUNT(*) FROM final_source_ranking WHERE quality_tier = 'good'),
                            'average_sources', (SELECT COUNT(*) FROM final_source_ranking WHERE quality_tier = 'average'),
                            'needs_improvement_sources', (SELECT COUNT(*) FROM final_source_ranking WHERE quality_tier = 'needs_improvement')
                        )
                    )
                ELSE 
                    NULL
            END
        )
    ) INTO result;
    
    RETURN result;
    
EXCEPTION WHEN OTHERS THEN
    RETURN json_build_object(
        'error', TRUE,
        'message', SQLERRM,
        'organization_id', p_organization_id
    );
END;$$;


--
-- Name: get_ai_provider_active_key(text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_ai_provider_active_key(p_provider_types text[]) RETURNS TABLE(provider_type text, key_identifier text, api_key text)
    LANGUAGE plpgsql
    AS $$
begin
  return query
  with prefs as (
    -- QUALIFY column names from unnest to avoid collision with OUT params
    select
      u.provider_type as provider_type,
      u.ord           as ord
    from unnest(p_provider_types) with ordinality as u(provider_type, ord)
  ),
  picked as (
    select
      k.id,
      k.provider_type::text  as provider_type,
      k.key_identifier::text as key_identifier,
      k.api_key::text        as api_key
    from ai_provider_keys as k
    join prefs as p on p.provider_type = k.provider_type
    where k.status = 'active'
    order by
      p.ord,
      k.rotation_order,
      k.last_used_at nulls first
    for update skip locked
    limit 1
  ),
  upd as (
    update ai_provider_keys as t
    set last_used_at = now()
    from picked as px
    where t.id = px.id
    returning t.id
  )
  -- QUALIFY here too
  select px.provider_type, px.key_identifier, px.api_key
  from picked as px;
end;
$$;


--
-- Name: get_audience_behavior_segments(uuid, integer, text, uuid[], uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_audience_behavior_segments(p_organization_id uuid, p_period_days integer, p_timezone text DEFAULT 'UTC'::text, p_tag_ids uuid[] DEFAULT NULL::uuid[], p_touchpoint_ids uuid[] DEFAULT NULL::uuid[]) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    start_date TIMESTAMPTZ;
    end_date TIMESTAMPTZ;
    result JSON;
BEGIN
    -- This is a Premium-only feature - no tier validation needed
    
    -- Calculate date range in user's timezone
    end_date := CURRENT_TIMESTAMP AT TIME ZONE p_timezone;
    start_date := end_date - (p_period_days || ' days')::INTERVAL;
    
    WITH filtered_visits AS (
        -- Apply hierarchical filtering to current period visits
        SELECT 
            v.fp,
            v.type,
            v.created_at,
            v.tp_id,
            v.platform,
            v.country
        FROM visits v
        WHERE v.organization_id = p_organization_id
            AND v.created_at >= start_date
            AND v.created_at < end_date            
            AND v.fp IS NOT NULL  -- Only users with valid fingerprints
            AND (
                -- No filtering if no filters specified
                (p_tag_ids IS NULL AND p_touchpoint_ids IS NULL)
                OR 
                -- Apply hierarchical filtering: tags first, then touchpoints
                (
                    (p_tag_ids IS NULL OR v.tp_id IN (
                        SELECT DISTINCT ttl.tp_id 
                        FROM tp_tag_links ttl 
                        WHERE ttl.tag_id = ANY(p_tag_ids)
                    ))
                    AND
                    (p_touchpoint_ids IS NULL OR v.tp_id = ANY(p_touchpoint_ids))
                )
            )
    ),
    historical_users AS (
        -- Find users who had visits before the current period (for new vs returning analysis)
        SELECT DISTINCT v.fp
        FROM visits v
        WHERE v.organization_id = p_organization_id
            AND v.created_at < start_date            
            AND v.fp IS NOT NULL
            AND (
                -- Apply same filtering to historical data for consistency
                (p_tag_ids IS NULL AND p_touchpoint_ids IS NULL)
                OR 
                (
                    (p_tag_ids IS NULL OR v.tp_id IN (
                        SELECT DISTINCT ttl.tp_id 
                        FROM tp_tag_links ttl 
                        WHERE ttl.tag_id = ANY(p_tag_ids)
                    ))
                    AND
                    (p_touchpoint_ids IS NULL OR v.tp_id = ANY(p_touchpoint_ids))
                )
            )
    ),
    user_behavior_analysis AS (
        -- Analyze each user's behavior patterns
        SELECT 
            fv.fp,
            COUNT(*) as total_interactions,
            COUNT(DISTINCT fv.tp_id) as unique_touchpoints,
            COUNT(DISTINCT DATE(fv.created_at AT TIME ZONE p_timezone)) as active_days,
            COUNT(DISTINCT fv.platform) as platforms_used,
            COUNT(DISTINCT fv.type) as interaction_types_used,
            -- Interaction type preferences
            COUNT(CASE WHEN fv.type = 'LINK' THEN 1 END) as link_interactions,
            COUNT(CASE WHEN fv.type = 'QR' THEN 1 END) as qr_interactions,
            COUNT(CASE WHEN fv.type = 'NFC' THEN 1 END) as nfc_interactions,
            COUNT(CASE WHEN fv.type = 'WIFI' THEN 1 END) as wifi_interactions,
            -- Temporal patterns
            MIN(fv.created_at) as first_visit,
            MAX(fv.created_at) as last_visit,
            EXTRACT(EPOCH FROM (MAX(fv.created_at) - MIN(fv.created_at))) / 3600 as visit_span_hours,
            -- User lifecycle classification
            CASE 
                WHEN hu.fp IS NOT NULL THEN 'returning'
                ELSE 'new'
            END as user_lifecycle,
            -- Geographic consistency
            COUNT(DISTINCT fv.country) as countries_visited
        FROM filtered_visits fv
        LEFT JOIN historical_users hu ON fv.fp = hu.fp
        GROUP BY fv.fp, hu.fp
    ),
    user_segments AS (
        -- Classify users into behavior segments
        SELECT 
            *,
            -- Engagement depth segments
            CASE 
                WHEN total_interactions = 1 THEN 'single_touch'
                WHEN total_interactions BETWEEN 2 AND 5 THEN 'multi_touch'
                WHEN total_interactions >= 6 THEN 'power_user'
            END as engagement_segment,
            -- Interaction pattern segments
            CASE 
                WHEN interaction_types_used = 1 THEN
                    CASE 
                        WHEN link_interactions > 0 THEN 'link_focused'
                        WHEN qr_interactions > 0 THEN 'qr_focused'
                        WHEN nfc_interactions > 0 THEN 'nfc_focused'
                        WHEN wifi_interactions > 0 THEN 'wifi_focused'
                    END
                ELSE 'mixed_mode'
            END as interaction_pattern,
            -- Temporal behavior segments
            CASE 
                WHEN active_days >= p_period_days * 0.7 THEN 'consistent'
                WHEN visit_span_hours <= 24 AND total_interactions >= 3 THEN 'burst'
                WHEN active_days <= p_period_days * 0.3 THEN 'occasional'
                ELSE 'regular'
            END as temporal_behavior,
            -- Loyalty/depth segments
            CASE 
                WHEN unique_touchpoints >= 3 AND total_interactions >= 5 THEN 'explorer'
                WHEN unique_touchpoints = 1 AND total_interactions >= 3 THEN 'focused'
                WHEN platforms_used > 1 THEN 'cross_platform'
                ELSE 'standard'
            END as loyalty_segment
        FROM user_behavior_analysis
    ),
    segment_aggregations AS (
        -- Aggregate metrics for each segment type
        SELECT 
            -- Lifecycle segments
            user_lifecycle,
            COUNT(*) FILTER (WHERE user_lifecycle = 'new') as new_users_count,
            COUNT(*) FILTER (WHERE user_lifecycle = 'returning') as returning_users_count,
            ROUND(AVG(total_interactions) FILTER (WHERE user_lifecycle = 'new'), 2) as new_users_avg_interactions,
            ROUND(AVG(total_interactions) FILTER (WHERE user_lifecycle = 'returning'), 2) as returning_users_avg_interactions,
            
            -- Engagement segments
            COUNT(*) FILTER (WHERE engagement_segment = 'single_touch') as single_touch_count,
            COUNT(*) FILTER (WHERE engagement_segment = 'multi_touch') as multi_touch_count,
            COUNT(*) FILTER (WHERE engagement_segment = 'power_user') as power_user_count,
            
            -- Interaction pattern segments
            COUNT(*) FILTER (WHERE interaction_pattern = 'link_focused') as link_focused_count,
            COUNT(*) FILTER (WHERE interaction_pattern = 'qr_focused') as qr_focused_count,
            COUNT(*) FILTER (WHERE interaction_pattern = 'nfc_focused') as nfc_focused_count,
            COUNT(*) FILTER (WHERE interaction_pattern = 'wifi_focused') as wifi_focused_count,
            COUNT(*) FILTER (WHERE interaction_pattern = 'mixed_mode') as mixed_mode_count,
            
            -- Temporal behavior segments
            COUNT(*) FILTER (WHERE temporal_behavior = 'consistent') as consistent_count,
            COUNT(*) FILTER (WHERE temporal_behavior = 'burst') as burst_count,
            COUNT(*) FILTER (WHERE temporal_behavior = 'occasional') as occasional_count,
            COUNT(*) FILTER (WHERE temporal_behavior = 'regular') as regular_count,
            
            -- Loyalty segments
            COUNT(*) FILTER (WHERE loyalty_segment = 'explorer') as explorer_count,
            COUNT(*) FILTER (WHERE loyalty_segment = 'focused') as focused_count,
            COUNT(*) FILTER (WHERE loyalty_segment = 'cross_platform') as cross_platform_count,
            COUNT(*) FILTER (WHERE loyalty_segment = 'standard') as standard_count,
            
            -- Overall metrics
            COUNT(*) as total_users,
            ROUND(AVG(total_interactions), 2) as avg_interactions_per_user,
            ROUND(AVG(active_days), 2) as avg_active_days,
            ROUND(AVG(unique_touchpoints), 2) as avg_touchpoints_per_user
        FROM user_segments
        GROUP BY user_lifecycle  -- Aggregate all users together
    )
    SELECT json_build_object(
        'period_info', json_build_object(
            'period_days', p_period_days,
            'start_date', start_date,
            'end_date', end_date,
            'timezone', p_timezone,
            'is_premium', TRUE,
            'feature_type', 'behavior_segments'
        ),
        'filters_applied', json_build_object(
            'has_filters', (p_tag_ids IS NOT NULL OR p_touchpoint_ids IS NOT NULL),
            'tags_count', COALESCE(array_length(p_tag_ids, 1), 0),
            'touchpoints_count', COALESCE(array_length(p_touchpoint_ids, 1), 0)
        ),
        'behavior_segments', json_build_object(
            -- User Lifecycle Segments
            'lifecycle_segments', json_build_object(
                'new_users', json_build_object(
                    'count', COALESCE((SELECT new_users_count FROM segment_aggregations), 0),
                    'percentage', ROUND(COALESCE((SELECT new_users_count FROM segment_aggregations), 0)::DECIMAL / NULLIF((SELECT total_users FROM segment_aggregations), 0) * 100, 1),
                    'avg_interactions', COALESCE((SELECT new_users_avg_interactions FROM segment_aggregations), 0),
                    'description', 'Users with their first visit during this period'
                ),
                'returning_users', json_build_object(
                    'count', COALESCE((SELECT returning_users_count FROM segment_aggregations), 0),
                    'percentage', ROUND(COALESCE((SELECT returning_users_count FROM segment_aggregations), 0)::DECIMAL / NULLIF((SELECT total_users FROM segment_aggregations), 0) * 100, 1),
                    'avg_interactions', COALESCE((SELECT returning_users_avg_interactions FROM segment_aggregations), 0),
                    'description', 'Users who had previous visits before this period'
                )
            ),
            -- Engagement Depth Segments
            'engagement_segments', json_build_object(
                'single_touch', json_build_object(
                    'count', COALESCE((SELECT single_touch_count FROM segment_aggregations), 0),
                    'percentage', ROUND(COALESCE((SELECT single_touch_count FROM segment_aggregations), 0)::DECIMAL / NULLIF((SELECT total_users FROM segment_aggregations), 0) * 100, 1),
                    'description', 'Users with only 1 interaction'
                ),
                'multi_touch', json_build_object(
                    'count', COALESCE((SELECT multi_touch_count FROM segment_aggregations), 0),
                    'percentage', ROUND(COALESCE((SELECT multi_touch_count FROM segment_aggregations), 0)::DECIMAL / NULLIF((SELECT total_users FROM segment_aggregations), 0) * 100, 1),
                    'description', 'Users with 2-5 interactions'
                ),
                'power_users', json_build_object(
                    'count', COALESCE((SELECT power_user_count FROM segment_aggregations), 0),
                    'percentage', ROUND(COALESCE((SELECT power_user_count FROM segment_aggregations), 0)::DECIMAL / NULLIF((SELECT total_users FROM segment_aggregations), 0) * 100, 1),
                    'description', 'Users with 6+ interactions'
                )
            ),
            -- Interaction Pattern Segments
            'interaction_patterns', json_build_object(
                'link_focused', json_build_object(
                    'count', COALESCE((SELECT link_focused_count FROM segment_aggregations), 0),
                    'percentage', ROUND(COALESCE((SELECT link_focused_count FROM segment_aggregations), 0)::DECIMAL / NULLIF((SELECT total_users FROM segment_aggregations), 0) * 100, 1),
                    'description', 'Users who primarily use link interactions'
                ),
                'qr_focused', json_build_object(
                    'count', COALESCE((SELECT qr_focused_count FROM segment_aggregations), 0),
                    'percentage', ROUND(COALESCE((SELECT qr_focused_count FROM segment_aggregations), 0)::DECIMAL / NULLIF((SELECT total_users FROM segment_aggregations), 0) * 100, 1),
                    'description', 'Users who primarily use QR code interactions'
                ),
                'nfc_focused', json_build_object(
                    'count', COALESCE((SELECT nfc_focused_count FROM segment_aggregations), 0),
                    'percentage', ROUND(COALESCE((SELECT nfc_focused_count FROM segment_aggregations), 0)::DECIMAL / NULLIF((SELECT total_users FROM segment_aggregations), 0) * 100, 1),
                    'description', 'Users who primarily use NFC interactions'
                ),
                'wifi_focused', json_build_object(
                    'count', COALESCE((SELECT wifi_focused_count FROM segment_aggregations), 0),
                    'percentage', ROUND(COALESCE((SELECT wifi_focused_count FROM segment_aggregations), 0)::DECIMAL / NULLIF((SELECT total_users FROM segment_aggregations), 0) * 100, 1),
                    'description', 'Users who primarily use WiFi access'
                ),
                'mixed_mode', json_build_object(
                    'count', COALESCE((SELECT mixed_mode_count FROM segment_aggregations), 0),
                    'percentage', ROUND(COALESCE((SELECT mixed_mode_count FROM segment_aggregations), 0)::DECIMAL / NULLIF((SELECT total_users FROM segment_aggregations), 0) * 100, 1),
                    'description', 'Users who use multiple interaction types'
                )
            ),
            -- Temporal Behavior Segments
            'temporal_behavior', json_build_object(
                'consistent', json_build_object(
                    'count', COALESCE((SELECT consistent_count FROM segment_aggregations), 0),
                    'percentage', ROUND(COALESCE((SELECT consistent_count FROM segment_aggregations), 0)::DECIMAL / NULLIF((SELECT total_users FROM segment_aggregations), 0) * 100, 1),
                    'description', 'Users with regular visits across multiple days'
                ),
                'burst', json_build_object(
                    'count', COALESCE((SELECT burst_count FROM segment_aggregations), 0),
                    'percentage', ROUND(COALESCE((SELECT burst_count FROM segment_aggregations), 0)::DECIMAL / NULLIF((SELECT total_users FROM segment_aggregations), 0) * 100, 1),
                    'description', 'Users with many interactions in short time periods'
                ),
                'occasional', json_build_object(
                    'count', COALESCE((SELECT occasional_count FROM segment_aggregations), 0),
                    'percentage', ROUND(COALESCE((SELECT occasional_count FROM segment_aggregations), 0)::DECIMAL / NULLIF((SELECT total_users FROM segment_aggregations), 0) * 100, 1),
                    'description', 'Users with sporadic visit patterns'
                ),
                'regular', json_build_object(
                    'count', COALESCE((SELECT regular_count FROM segment_aggregations), 0),
                    'percentage', ROUND(COALESCE((SELECT regular_count FROM segment_aggregations), 0)::DECIMAL / NULLIF((SELECT total_users FROM segment_aggregations), 0) * 100, 1),
                    'description', 'Users with moderate, regular engagement'
                )
            ),
            -- Loyalty/Depth Segments
            'loyalty_segments', json_build_object(
                'explorers', json_build_object(
                    'count', COALESCE((SELECT explorer_count FROM segment_aggregations), 0),
                    'percentage', ROUND(COALESCE((SELECT explorer_count FROM segment_aggregations), 0)::DECIMAL / NULLIF((SELECT total_users FROM segment_aggregations), 0) * 100, 1),
                    'description', 'Users who interact with multiple touchpoints frequently'
                ),
                'focused', json_build_object(
                    'count', COALESCE((SELECT focused_count FROM segment_aggregations), 0),
                    'percentage', ROUND(COALESCE((SELECT focused_count FROM segment_aggregations), 0)::DECIMAL / NULLIF((SELECT total_users FROM segment_aggregations), 0) * 100, 1),
                    'description', 'Users who repeatedly use the same touchpoint'
                ),
                'cross_platform', json_build_object(
                    'count', COALESCE((SELECT cross_platform_count FROM segment_aggregations), 0),
                    'percentage', ROUND(COALESCE((SELECT cross_platform_count FROM segment_aggregations), 0)::DECIMAL / NULLIF((SELECT total_users FROM segment_aggregations), 0) * 100, 1),
                    'description', 'Users who access touchpoints from multiple platforms'
                ),
                'standard', json_build_object(
                    'count', COALESCE((SELECT standard_count FROM segment_aggregations), 0),
                    'percentage', ROUND(COALESCE((SELECT standard_count FROM segment_aggregations), 0)::DECIMAL / NULLIF((SELECT total_users FROM segment_aggregations), 0) * 100, 1),
                    'description', 'Users with typical interaction patterns'
                )
            )
        ),
        'summary', (
            SELECT json_build_object(
                'total_users_analyzed', sa.total_users,
                'avg_interactions_per_user', sa.avg_interactions_per_user,
                'avg_active_days', sa.avg_active_days,
                'avg_touchpoints_per_user', sa.avg_touchpoints_per_user,
                'user_quality_score', ROUND(
                    (sa.avg_interactions_per_user * 0.4 + 
                     sa.avg_active_days * 0.3 + 
                     sa.avg_touchpoints_per_user * 0.3), 2
                ),
                'dominant_segments', json_build_object(
                    'lifecycle', CASE 
                        WHEN sa.returning_users_count > sa.new_users_count THEN 'returning_dominant'
                        ELSE 'new_user_dominant'
                    END,
                    'engagement', CASE 
                        WHEN sa.power_user_count > sa.total_users * 0.2 THEN 'highly_engaged'
                        WHEN sa.single_touch_count > sa.total_users * 0.6 THEN 'low_engagement'
                        ELSE 'balanced_engagement'
                    END,
                    'behavior', CASE 
                        WHEN sa.consistent_count > sa.total_users * 0.3 THEN 'loyal_audience'
                        WHEN sa.burst_count > sa.total_users * 0.4 THEN 'impulse_driven'
                        ELSE 'mixed_behavior'
                    END
                )
            )
            FROM segment_aggregations sa
        ),
        'insights', json_build_object(
            'audience_maturity', (
                SELECT CASE 
                    WHEN sa.returning_users_count::DECIMAL / sa.total_users > 0.6 THEN 'mature_audience'
                    WHEN sa.returning_users_count::DECIMAL / sa.total_users > 0.3 THEN 'developing_audience'
                    ELSE 'new_audience'
                END
                FROM segment_aggregations sa
            ),
            'engagement_quality', (
                SELECT CASE 
                    WHEN (sa.multi_touch_count + sa.power_user_count)::DECIMAL / sa.total_users > 0.5 THEN 'high_quality'
                    WHEN sa.single_touch_count::DECIMAL / sa.total_users > 0.7 THEN 'needs_improvement'
                    ELSE 'moderate_quality'
                END
                FROM segment_aggregations sa
            ),
            'behavior_recommendations', (
                SELECT json_agg(recommendation)
                FROM (
                    SELECT CASE 
                        WHEN sa.single_touch_count::DECIMAL / sa.total_users > 0.6 THEN 
                            'High single-touch rate - focus on retention strategies and follow-up campaigns'
                        WHEN sa.power_user_count::DECIMAL / sa.total_users > 0.2 THEN 
                            'Strong power user base - consider VIP programs and exclusive content'
                        WHEN sa.mixed_mode_count::DECIMAL / sa.total_users > 0.4 THEN 
                            'Users prefer multiple interaction types - maintain diverse touchpoint options'
                        WHEN sa.explorer_count::DECIMAL / sa.total_users > 0.3 THEN 
                            'High exploration behavior - introduce more touchpoints to satisfy curiosity'
                        WHEN sa.consistent_count::DECIMAL / sa.total_users < 0.1 THEN 
                            'Low consistency - improve touchpoint value proposition and user experience'
                        ELSE NULL
                    END as recommendation
                    FROM segment_aggregations sa
                ) recommendations
                WHERE recommendation IS NOT NULL
            )
        )
    ) INTO result;
    
    RETURN result;
    
EXCEPTION WHEN OTHERS THEN
    RETURN json_build_object(
        'error', TRUE,
        'message', SQLERRM,
        'organization_id', p_organization_id
    );
END;
$$;


--
-- Name: get_audience_device_analysis(uuid, integer, text, uuid[], uuid[], boolean, uuid[], boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_audience_device_analysis(p_organization_id uuid, p_period_days integer, p_timezone text DEFAULT 'UTC'::text, p_tag_ids uuid[] DEFAULT NULL::uuid[], p_touchpoint_ids uuid[] DEFAULT NULL::uuid[], p_is_premium boolean DEFAULT false, p_collection_ids uuid[] DEFAULT NULL::uuid[], p_include_null_collection boolean DEFAULT false) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    start_date TIMESTAMPTZ;
    end_date TIMESTAMPTZ;
    result JSON;
BEGIN
    -- Validate tier restrictions
    IF NOT p_is_premium AND p_period_days != 7 THEN
        RETURN json_build_object('error', TRUE, 'message', 'Free tier limited to 7 days only');
    END IF;
    
    IF NOT p_is_premium AND p_touchpoint_ids IS NOT NULL AND array_length(p_touchpoint_ids, 1) > 1 THEN
        RETURN json_build_object('error', TRUE, 'message', 'Free tier limited to 1 touchpoint only');
    END IF;

    -- Calculate date range in user's timezone
    end_date := CURRENT_TIMESTAMP AT TIME ZONE p_timezone;
    start_date := end_date - (p_period_days || ' days')::INTERVAL;
    
    WITH filtered_visits AS (
        -- Apply hierarchical filtering directly to visits
        SELECT 
            v.platform,
            v.os,
            v.fp,
            v.type,
            v.created_at,
            v.tp_id
        FROM visits v
        WHERE v.organization_id = p_organization_id
            AND v.created_at >= start_date
            AND v.created_at < end_date            
            AND (
                -- No filtering if no filters specified
                (p_tag_ids IS NULL AND p_touchpoint_ids IS NULL)
                OR 
                -- Apply hierarchical filtering: tags first, then touchpoints
                (
                    (p_tag_ids IS NULL OR v.tp_id IN (
                        SELECT DISTINCT ttl.tp_id 
                        FROM tp_tag_links ttl 
                        WHERE ttl.tag_id = ANY(p_tag_ids)
                    ))
                    AND
                    (p_touchpoint_ids IS NULL OR v.tp_id = ANY(p_touchpoint_ids))
                )
            )
            AND (
                p_collection_ids IS NULL
                OR v.tp_id IN (
                    SELECT tp.id
                    FROM touch_points tp
                    WHERE tp.collection_id = ANY(p_collection_ids)
                       OR (p_include_null_collection AND tp.collection_id IS NULL)
                )
            )
    ),
    platform_aggregation AS (
        -- Platform-level analysis (Mobile, Desktop, etc.)
        SELECT 
            COALESCE(platform, 'Unknown') as platform,
            COUNT(*) as total_visits,
            COUNT(DISTINCT fp) as unique_users,
            COUNT(DISTINCT tp_id) as touchpoints_accessed,
            COUNT(CASE WHEN type = 'LINK' THEN 1 END) as link_clicks,
            COUNT(CASE WHEN type = 'QR' THEN 1 END) as qr_scans,
            COUNT(CASE WHEN type = 'NFC' THEN 1 END) as nfc_taps,
            COUNT(CASE WHEN type = 'WIFI' THEN 1 END) as wifi_accesses,
            -- Premium: Engagement metrics
            ROUND(COUNT(*)::DECIMAL / NULLIF(COUNT(DISTINCT fp), 0), 2) as visits_per_user,
            -- Premium: Time-based patterns
            COUNT(CASE WHEN EXTRACT(dow FROM created_at AT TIME ZONE p_timezone) BETWEEN 1 AND 5 THEN 1 END) as weekday_visits,
            COUNT(CASE WHEN EXTRACT(dow FROM created_at AT TIME ZONE p_timezone) IN (0, 6) THEN 1 END) as weekend_visits,
            COUNT(CASE WHEN EXTRACT(hour FROM created_at AT TIME ZONE p_timezone) BETWEEN 9 AND 17 THEN 1 END) as business_hours_visits,
            -- Market share calculation
            ROUND(COUNT(*)::DECIMAL / SUM(COUNT(*)) OVER() * 100, 1) as platform_share_pct
        FROM filtered_visits
        WHERE platform IS NOT NULL
        GROUP BY COALESCE(platform, 'Unknown')
    ),
    os_aggregation AS (
        -- Operating system analysis
        SELECT 
            COALESCE(platform, 'Unknown') as platform,
            COALESCE(os, 'Unknown') as os,
            COUNT(*) as total_visits,
            COUNT(DISTINCT fp) as unique_users,
            -- Premium: Engagement metrics
            ROUND(COUNT(*)::DECIMAL / NULLIF(COUNT(DISTINCT fp), 0), 2) as visits_per_user,
            -- OS rank within platform
            ROW_NUMBER() OVER (PARTITION BY COALESCE(platform, 'Unknown') ORDER BY COUNT(*) DESC) as os_rank_in_platform,
            -- Market share within platform
            ROUND(COUNT(*)::DECIMAL / SUM(COUNT(*)) OVER(PARTITION BY COALESCE(platform, 'Unknown')) * 100, 1) as os_share_in_platform_pct
        FROM filtered_visits
        WHERE platform IS NOT NULL AND os IS NOT NULL
        GROUP BY COALESCE(platform, 'Unknown'), COALESCE(os, 'Unknown')
    ),
    device_summary AS (
        -- Summary statistics
        SELECT 
            COUNT(DISTINCT COALESCE(platform, 'Unknown')) as total_platforms,
            COUNT(DISTINCT COALESCE(os, 'Unknown')) as total_os,
            COUNT(*) as total_visits_all,
            COUNT(DISTINCT fp) as total_unique_users
        FROM filtered_visits
        WHERE platform IS NOT NULL OR os IS NOT NULL
    ),
    premium_insights AS (
        -- Premium-only advanced analysis
        SELECT 
            -- Cross-platform users (users who use multiple platforms)
            COUNT(DISTINCT fp) FILTER (
                WHERE fp IN (
                    SELECT fp 
                    FROM filtered_visits 
                    WHERE platform IS NOT NULL 
                    GROUP BY fp 
                    HAVING COUNT(DISTINCT platform) > 1
                )
            ) as cross_platform_users,
            -- Device loyalty analysis
            ROUND(AVG(platform_consistency), 2) as avg_platform_consistency
        FROM (
            SELECT 
                fp,
                COUNT(DISTINCT platform)::DECIMAL / COUNT(*) as platform_consistency
            FROM filtered_visits
            WHERE fp IS NOT NULL AND platform IS NOT NULL
            GROUP BY fp
            HAVING COUNT(*) >= 2  -- Only users with multiple visits
        ) user_consistency
    )
    SELECT json_build_object(
        'period_info', json_build_object(
            'period_days', p_period_days,
            'start_date', start_date,
            'end_date', end_date,
            'timezone', p_timezone,
            'is_premium', p_is_premium
        ),
        'filters_applied', json_build_object(
            'has_filters', (p_tag_ids IS NOT NULL OR p_touchpoint_ids IS NOT NULL),
            'tags_count', COALESCE(array_length(p_tag_ids, 1), 0),
            'touchpoints_count', COALESCE(array_length(p_touchpoint_ids, 1), 0)
        ),
        'device_data', json_build_object(
            -- Platform breakdown (both tiers, but different detail levels)
            'platforms', CASE 
                WHEN p_is_premium THEN
                    -- Premium: Full platform data with engagement metrics
                    (
                        SELECT json_agg(data) 
                        FROM (
                            SELECT json_build_object(
                                'platform', pa.platform,
                                'total_visits', pa.total_visits,
                                'unique_users', pa.unique_users,
                                'platform_share_pct', pa.platform_share_pct,
                                'visits_per_user', pa.visits_per_user,
                                'touchpoints_accessed', pa.touchpoints_accessed,
                                'usage_patterns', json_build_object(
                                    'weekday_visits', pa.weekday_visits,
                                    'weekend_visits', pa.weekend_visits,
                                    'business_hours_visits', pa.business_hours_visits,
                                    'weekend_usage_pct', ROUND(pa.weekend_visits::DECIMAL / pa.total_visits * 100, 1),
                                    'business_hours_pct', ROUND(pa.business_hours_visits::DECIMAL / pa.total_visits * 100, 1)
                                ),
                                'interaction_breakdown', json_build_object(
                                    'link_clicks', pa.link_clicks,
                                    'qr_scans', pa.qr_scans,
                                    'nfc_taps', pa.nfc_taps,
                                    'wifi_accesses', pa.wifi_accesses
                                )
                            ) as data
                            FROM platform_aggregation pa
                            ORDER BY pa.total_visits DESC
                        ) as ordered
                    )
                ELSE
                    -- Free: Basic platform data only
                    (
                        SELECT json_agg(data)
                        FROM (
                            SELECT json_build_object(
                                'platform', pa.platform,
                                'total_visits', pa.total_visits,
                                'unique_users', pa.unique_users,
                                'platform_share_pct', pa.platform_share_pct
                            ) as data
                            FROM platform_aggregation pa
                            ORDER BY pa.total_visits DESC
                        ) as ordered                        
                    )
            END,
            -- Operating system breakdown
            'operating_systems', CASE 
                WHEN p_is_premium THEN
                    -- Premium: OS data with engagement metrics
                    (
                        SELECT json_agg(data)
                        FROM (
                            SELECT json_build_object(
                                'platform', oa.platform,
                                'os', oa.os,
                                'os_rank_in_platform', oa.os_rank_in_platform,
                                'total_visits', oa.total_visits,
                                'unique_users', oa.unique_users,
                                'visits_per_user', oa.visits_per_user,
                                'os_share_in_platform_pct', oa.os_share_in_platform_pct
                            ) as data
                            FROM os_aggregation oa
                            ORDER BY oa.total_visits DESC
                        ) as ordered             
                    )
                ELSE
                    -- Free: Basic OS counts only
                    (
                        SELECT json_agg(data)
                        FROM (
                            SELECT json_build_object(
                                'platform', oa.platform,
                                'os', oa.os,
                                'total_visits', oa.total_visits,
                                'unique_users', oa.unique_users
                            ) as data
                            FROM os_aggregation oa    
                            ORDER BY oa.total_visits DESC
                        ) as data
                    )
            END,
            -- Summary statistics
            'summary', (
                SELECT json_build_object(
                    'total_platforms', ds.total_platforms,
                    'total_operating_systems', ds.total_os,
                    'total_visits', ds.total_visits_all,
                    'total_unique_users', ds.total_unique_users,
                    'device_diversity', CASE 
                        WHEN ds.total_platforms >= 4 THEN 'high_diversity'
                        WHEN ds.total_platforms >= 2 THEN 'medium_diversity'
                        ELSE 'single_platform'
                    END
                )
                FROM device_summary ds
            )
        ),
        'insights', json_build_object(
            -- Basic insights (both tiers)
            'dominant_platform', (
                SELECT json_build_object(
                    'platform', pa.platform,
                    'visits', pa.total_visits,
                    'market_share_pct', pa.platform_share_pct,
                    'users', pa.unique_users
                )
                FROM platform_aggregation pa
                ORDER BY pa.total_visits DESC
                LIMIT 1
            ),            
            -- Premium-only insights
            'premium_insights', CASE 
                WHEN p_is_premium THEN
                    (
                        SELECT json_build_object(
                            'engagement_leader', (
                                SELECT json_build_object(
                                    'platform', pa.platform,
                                    'visits_per_user', pa.visits_per_user,
                                    'engagement_advantage', CASE 
                                        WHEN pa.visits_per_user > 2.5 THEN 'high'
                                        WHEN pa.visits_per_user > 1.8 THEN 'medium'
                                        ELSE 'standard'
                                    END
                                )
                                FROM platform_aggregation pa
                                ORDER BY pa.visits_per_user DESC
                                LIMIT 1
                            ),
                            'cross_platform_users', (
                                SELECT json_build_object(
                                    'count', pi.cross_platform_users,
                                    'percentage', ROUND(pi.cross_platform_users::DECIMAL / ds.total_unique_users * 100, 1)
                                )
                                FROM premium_insights pi, device_summary ds
                            ),
                            'usage_timing', (
                                SELECT json_agg(data)
                                FROM (
                                    SELECT json_build_object(
                                        'platform', pa.platform,
                                        'peak_time', CASE 
                                            WHEN pa.business_hours_visits > pa.weekend_visits THEN 'business_hours'
                                            WHEN pa.weekend_visits > pa.business_hours_visits THEN 'weekends'
                                            ELSE 'balanced'
                                        END,
                                        'business_hours_pct', ROUND(pa.business_hours_visits::DECIMAL / pa.total_visits * 100, 1)
                                    ) as data
                                    FROM platform_aggregation pa
                                    ORDER BY pa.total_visits DESC
                                ) as ordered                                
                            )
                        )
                    )
                ELSE 
                    NULL
            END
        )
    ) INTO result;
    
    RETURN result;
    
EXCEPTION WHEN OTHERS THEN
    RETURN json_build_object(
        'error', TRUE,
        'message', SQLERRM,
        'organization_id', p_organization_id
    );
END;
$$;


--
-- Name: get_audience_device_analysis_old(uuid, integer, text, uuid[], uuid[], boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_audience_device_analysis_old(p_organization_id uuid, p_period_days integer, p_timezone text DEFAULT 'UTC'::text, p_tag_ids uuid[] DEFAULT NULL::uuid[], p_touchpoint_ids uuid[] DEFAULT NULL::uuid[], p_is_premium boolean DEFAULT false) RETURNS json
    LANGUAGE plpgsql
    AS $$DECLARE
    start_date TIMESTAMPTZ;
    end_date TIMESTAMPTZ;
    result JSON;
BEGIN
    -- Validate tier restrictions
    IF NOT p_is_premium AND p_period_days != 7 THEN
        RETURN json_build_object('error', TRUE, 'message', 'Free tier limited to 7 days only');
    END IF;
    
    IF NOT p_is_premium AND p_touchpoint_ids IS NOT NULL AND array_length(p_touchpoint_ids, 1) > 1 THEN
        RETURN json_build_object('error', TRUE, 'message', 'Free tier limited to 1 touchpoint only');
    END IF;

    -- Calculate date range in user's timezone
    end_date := CURRENT_TIMESTAMP AT TIME ZONE p_timezone;
    start_date := end_date - (p_period_days || ' days')::INTERVAL;
    
    WITH filtered_visits AS (
        -- Apply hierarchical filtering directly to visits
        SELECT 
            v.platform,
            v.os,
            v.fp,
            v.type,
            v.created_at,
            v.tp_id
        FROM visits v
        WHERE v.organization_id = p_organization_id
            AND v.created_at >= start_date
            AND v.created_at < end_date            
            AND (
                -- No filtering if no filters specified
                (p_tag_ids IS NULL AND p_touchpoint_ids IS NULL)
                OR 
                -- Apply hierarchical filtering: tags first, then touchpoints
                (
                    (p_tag_ids IS NULL OR v.tp_id IN (
                        SELECT DISTINCT ttl.tp_id 
                        FROM tp_tag_links ttl 
                        WHERE ttl.tag_id = ANY(p_tag_ids)
                    ))
                    AND
                    (p_touchpoint_ids IS NULL OR v.tp_id = ANY(p_touchpoint_ids))
                )
            )
    ),
    platform_aggregation AS (
        -- Platform-level analysis (Mobile, Desktop, etc.)
        SELECT 
            COALESCE(platform, 'Unknown') as platform,
            COUNT(*) as total_visits,
            COUNT(DISTINCT fp) as unique_users,
            COUNT(DISTINCT tp_id) as touchpoints_accessed,
            COUNT(CASE WHEN type = 'LINK' THEN 1 END) as link_clicks,
            COUNT(CASE WHEN type = 'QR' THEN 1 END) as qr_scans,
            COUNT(CASE WHEN type = 'NFC' THEN 1 END) as nfc_taps,
            COUNT(CASE WHEN type = 'WIFI' THEN 1 END) as wifi_accesses,
            -- Premium: Engagement metrics
            ROUND(COUNT(*)::DECIMAL / NULLIF(COUNT(DISTINCT fp), 0), 2) as visits_per_user,
            -- Premium: Time-based patterns
            COUNT(CASE WHEN EXTRACT(dow FROM created_at AT TIME ZONE p_timezone) BETWEEN 1 AND 5 THEN 1 END) as weekday_visits,
            COUNT(CASE WHEN EXTRACT(dow FROM created_at AT TIME ZONE p_timezone) IN (0, 6) THEN 1 END) as weekend_visits,
            COUNT(CASE WHEN EXTRACT(hour FROM created_at AT TIME ZONE p_timezone) BETWEEN 9 AND 17 THEN 1 END) as business_hours_visits,
            -- Market share calculation
            ROUND(COUNT(*)::DECIMAL / SUM(COUNT(*)) OVER() * 100, 1) as platform_share_pct
        FROM filtered_visits
        WHERE platform IS NOT NULL
        GROUP BY COALESCE(platform, 'Unknown')
    ),
    os_aggregation AS (
        -- Operating system analysis
        SELECT 
            COALESCE(platform, 'Unknown') as platform,
            COALESCE(os, 'Unknown') as os,
            COUNT(*) as total_visits,
            COUNT(DISTINCT fp) as unique_users,
            -- Premium: Engagement metrics
            ROUND(COUNT(*)::DECIMAL / NULLIF(COUNT(DISTINCT fp), 0), 2) as visits_per_user,
            -- OS rank within platform
            ROW_NUMBER() OVER (PARTITION BY COALESCE(platform, 'Unknown') ORDER BY COUNT(*) DESC) as os_rank_in_platform,
            -- Market share within platform
            ROUND(COUNT(*)::DECIMAL / SUM(COUNT(*)) OVER(PARTITION BY COALESCE(platform, 'Unknown')) * 100, 1) as os_share_in_platform_pct
        FROM filtered_visits
        WHERE platform IS NOT NULL AND os IS NOT NULL
        GROUP BY COALESCE(platform, 'Unknown'), COALESCE(os, 'Unknown')
    ),
    device_summary AS (
        -- Summary statistics
        SELECT 
            COUNT(DISTINCT COALESCE(platform, 'Unknown')) as total_platforms,
            COUNT(DISTINCT COALESCE(os, 'Unknown')) as total_os,
            COUNT(*) as total_visits_all,
            COUNT(DISTINCT fp) as total_unique_users
        FROM filtered_visits
        WHERE platform IS NOT NULL OR os IS NOT NULL
    ),
    premium_insights AS (
        -- Premium-only advanced analysis
        SELECT 
            -- Cross-platform users (users who use multiple platforms)
            COUNT(DISTINCT fp) FILTER (
                WHERE fp IN (
                    SELECT fp 
                    FROM filtered_visits 
                    WHERE platform IS NOT NULL 
                    GROUP BY fp 
                    HAVING COUNT(DISTINCT platform) > 1
                )
            ) as cross_platform_users,
            -- Device loyalty analysis
            ROUND(AVG(platform_consistency), 2) as avg_platform_consistency
        FROM (
            SELECT 
                fp,
                COUNT(DISTINCT platform)::DECIMAL / COUNT(*) as platform_consistency
            FROM filtered_visits
            WHERE fp IS NOT NULL AND platform IS NOT NULL
            GROUP BY fp
            HAVING COUNT(*) >= 2  -- Only users with multiple visits
        ) user_consistency
    )
    SELECT json_build_object(
        'period_info', json_build_object(
            'period_days', p_period_days,
            'start_date', start_date,
            'end_date', end_date,
            'timezone', p_timezone,
            'is_premium', p_is_premium
        ),
        'filters_applied', json_build_object(
            'has_filters', (p_tag_ids IS NOT NULL OR p_touchpoint_ids IS NOT NULL),
            'tags_count', COALESCE(array_length(p_tag_ids, 1), 0),
            'touchpoints_count', COALESCE(array_length(p_touchpoint_ids, 1), 0)
        ),
        'device_data', json_build_object(
            -- Platform breakdown (both tiers, but different detail levels)
            'platforms', CASE 
                WHEN p_is_premium THEN
                    -- Premium: Full platform data with engagement metrics
                    (
                        SELECT json_agg(data) 
                        FROM (
                            SELECT json_build_object(
                                'platform', pa.platform,
                                'total_visits', pa.total_visits,
                                'unique_users', pa.unique_users,
                                'platform_share_pct', pa.platform_share_pct,
                                'visits_per_user', pa.visits_per_user,
                                'touchpoints_accessed', pa.touchpoints_accessed,
                                'usage_patterns', json_build_object(
                                    'weekday_visits', pa.weekday_visits,
                                    'weekend_visits', pa.weekend_visits,
                                    'business_hours_visits', pa.business_hours_visits,
                                    'weekend_usage_pct', ROUND(pa.weekend_visits::DECIMAL / pa.total_visits * 100, 1),
                                    'business_hours_pct', ROUND(pa.business_hours_visits::DECIMAL / pa.total_visits * 100, 1)
                                ),
                                'interaction_breakdown', json_build_object(
                                    'link_clicks', pa.link_clicks,
                                    'qr_scans', pa.qr_scans,
                                    'nfc_taps', pa.nfc_taps,
                                    'wifi_accesses', pa.wifi_accesses
                                )
                            ) as data
                            FROM platform_aggregation pa
                            ORDER BY pa.total_visits DESC
                        ) as ordered
                    )
                ELSE
                    -- Free: Basic platform data only
                    (
                        SELECT json_agg(data)
                        FROM (
                            SELECT json_build_object(
                                'platform', pa.platform,
                                'total_visits', pa.total_visits,
                                'unique_users', pa.unique_users,
                                'platform_share_pct', pa.platform_share_pct
                            ) as data
                            FROM platform_aggregation pa
                            ORDER BY pa.total_visits DESC
                        ) as ordered                        
                    )
            END,
            -- Operating system breakdown
            'operating_systems', CASE 
                WHEN p_is_premium THEN
                    -- Premium: OS data with engagement metrics
                    (
                        SELECT json_agg(data)
                        FROM (
                            SELECT json_build_object(
                                'platform', oa.platform,
                                'os', oa.os,
                                'os_rank_in_platform', oa.os_rank_in_platform,
                                'total_visits', oa.total_visits,
                                'unique_users', oa.unique_users,
                                'visits_per_user', oa.visits_per_user,
                                'os_share_in_platform_pct', oa.os_share_in_platform_pct
                            ) as data
                            FROM os_aggregation oa
                            ORDER BY oa.total_visits DESC
                        ) as ordered             
                    )
                ELSE
                    -- Free: Basic OS counts only
                    (
                        SELECT json_agg(data)
                        FROM (
                            SELECT json_build_object(
                                'platform', oa.platform,
                                'os', oa.os,
                                'total_visits', oa.total_visits,
                                'unique_users', oa.unique_users
                            ) as data
                            FROM os_aggregation oa    
                            ORDER BY oa.total_visits DESC
                        ) as data
                    )
            END,
            -- Summary statistics
            'summary', (
                SELECT json_build_object(
                    'total_platforms', ds.total_platforms,
                    'total_operating_systems', ds.total_os,
                    'total_visits', ds.total_visits_all,
                    'total_unique_users', ds.total_unique_users,
                    'device_diversity', CASE 
                        WHEN ds.total_platforms >= 4 THEN 'high_diversity'
                        WHEN ds.total_platforms >= 2 THEN 'medium_diversity'
                        ELSE 'single_platform'
                    END
                )
                FROM device_summary ds
            )
        ),
        'insights', json_build_object(
            -- Basic insights (both tiers)
            'dominant_platform', (
                SELECT json_build_object(
                    'platform', pa.platform,
                    'visits', pa.total_visits,
                    'market_share_pct', pa.platform_share_pct,
                    'users', pa.unique_users
                )
                FROM platform_aggregation pa
                ORDER BY pa.total_visits DESC
                LIMIT 1
            ),            
            -- Premium-only insights
            'premium_insights', CASE 
                WHEN p_is_premium THEN
                    (
                        SELECT json_build_object(
                            'engagement_leader', (
                                SELECT json_build_object(
                                    'platform', pa.platform,
                                    'visits_per_user', pa.visits_per_user,
                                    'engagement_advantage', CASE 
                                        WHEN pa.visits_per_user > 2.5 THEN 'high'
                                        WHEN pa.visits_per_user > 1.8 THEN 'medium'
                                        ELSE 'standard'
                                    END
                                )
                                FROM platform_aggregation pa
                                ORDER BY pa.visits_per_user DESC
                                LIMIT 1
                            ),
                            'cross_platform_users', (
                                SELECT json_build_object(
                                    'count', pi.cross_platform_users,
                                    'percentage', ROUND(pi.cross_platform_users::DECIMAL / ds.total_unique_users * 100, 1)
                                )
                                FROM premium_insights pi, device_summary ds
                            ),
                            'usage_timing', (
                                SELECT json_agg(data)
                                FROM (
                                    SELECT json_build_object(
                                        'platform', pa.platform,
                                        'peak_time', CASE 
                                            WHEN pa.business_hours_visits > pa.weekend_visits THEN 'business_hours'
                                            WHEN pa.weekend_visits > pa.business_hours_visits THEN 'weekends'
                                            ELSE 'balanced'
                                        END,
                                        'business_hours_pct', ROUND(pa.business_hours_visits::DECIMAL / pa.total_visits * 100, 1)
                                    ) as data
                                    FROM platform_aggregation pa
                                    ORDER BY pa.total_visits DESC
                                ) as ordered                                
                            )
                        )
                    )
                ELSE 
                    NULL
            END
        )
    ) INTO result;
    
    RETURN result;
    
EXCEPTION WHEN OTHERS THEN
    RETURN json_build_object(
        'error', TRUE,
        'message', SQLERRM,
        'organization_id', p_organization_id
    );
END;$$;


--
-- Name: get_audience_geographic_distribution(uuid, integer, text, uuid[], uuid[], boolean, uuid[], boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_audience_geographic_distribution(p_organization_id uuid, p_period_days integer, p_timezone text DEFAULT 'UTC'::text, p_tag_ids uuid[] DEFAULT NULL::uuid[], p_touchpoint_ids uuid[] DEFAULT NULL::uuid[], p_is_premium boolean DEFAULT false, p_collection_ids uuid[] DEFAULT NULL::uuid[], p_include_null_collection boolean DEFAULT false) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    start_date TIMESTAMPTZ;
    end_date TIMESTAMPTZ;
    result JSON;
BEGIN
    -- Validate tier restrictions
    IF NOT p_is_premium AND p_period_days != 7 THEN
        RETURN json_build_object('error', TRUE, 'message', 'Free tier limited to 7 days only');
    END IF;
    
    IF NOT p_is_premium AND p_touchpoint_ids IS NOT NULL AND array_length(p_touchpoint_ids, 1) > 1 THEN
        RETURN json_build_object('error', TRUE, 'message', 'Free tier limited to 1 touchpoint only');
    END IF;

    -- Calculate date range in user's timezone
    end_date := CURRENT_TIMESTAMP AT TIME ZONE p_timezone;
    start_date := end_date - (p_period_days || ' days')::INTERVAL;
    
    WITH filtered_visits AS (
        -- Apply hierarchical filtering directly to visits
        SELECT 
            v.country,
            v.city,
            v.fp,
            v.type,
            v.created_at,
            v.tp_id
        FROM visits v
        WHERE v.organization_id = p_organization_id
            AND v.created_at >= start_date
            AND v.created_at < end_date            
            AND (
                -- No filtering if no filters specified
                (p_tag_ids IS NULL AND p_touchpoint_ids IS NULL)
                OR 
                -- Apply hierarchical filtering: tags first, then touchpoints
                (
                    (p_tag_ids IS NULL OR v.tp_id IN (
                        SELECT DISTINCT ttl.tp_id 
                        FROM tp_tag_links ttl 
                        WHERE ttl.tag_id = ANY(p_tag_ids)
                    ))
                    AND
                    (p_touchpoint_ids IS NULL OR v.tp_id = ANY(p_touchpoint_ids))
                )
            )
            AND (
                p_collection_ids IS NULL
                OR v.tp_id IN (
                    SELECT tp.id
                    FROM touch_points tp
                    WHERE tp.collection_id = ANY(p_collection_ids)
                       OR (p_include_null_collection AND tp.collection_id IS NULL)
                )
            )
    ),
    country_aggregation AS (
        -- Country-level aggregation
        SELECT 
            COALESCE(country, 'Unknown') as country,
            COUNT(*) as total_visits,
            COUNT(DISTINCT fp) as unique_users,
            COUNT(DISTINCT tp_id) as touchpoints_accessed,            
            -- Engagement metrics
            ROUND(COUNT(*)::DECIMAL / NULLIF(COUNT(DISTINCT fp), 0), 2) as visits_per_user,
            COUNT(DISTINCT city) as cities_in_country,
            -- Market share calculation
            ROUND(COUNT(*)::DECIMAL / SUM(COUNT(*)) OVER() * 100, 1) as visit_share_pct,
            ROW_NUMBER() OVER (ORDER BY COUNT(*) DESC) as country_rank
        FROM filtered_visits
        GROUP BY COALESCE(country, 'Unknown')
    ),
    city_aggregation AS (
        -- City-level aggregation (Premium only)
        SELECT 
            COALESCE(country, 'Unknown') as country,
            COALESCE(city, 'Unknown') as city,
            COUNT(*) as total_visits,
            COUNT(DISTINCT fp) as unique_users,
            COUNT(DISTINCT tp_id) as touchpoints_accessed,
            COUNT(CASE WHEN type = 'LINK' THEN 1 END) as link_clicks,
            COUNT(CASE WHEN type = 'QR' THEN 1 END) as qr_scans,
            COUNT(CASE WHEN type = 'NFC' THEN 1 END) as nfc_taps,
            COUNT(CASE WHEN type = 'WIFI' THEN 1 END) as wifi_accesses,
            ROUND(COUNT(*)::DECIMAL / NULLIF(COUNT(DISTINCT fp), 0), 2) as visits_per_user,
            -- City rank within country
            ROW_NUMBER() OVER (PARTITION BY COALESCE(country, 'Unknown') ORDER BY COUNT(*) DESC) as city_rank_in_country,
            -- Overall city rank
            ROW_NUMBER() OVER (ORDER BY COUNT(*) DESC) as city_rank_global
        FROM filtered_visits
        GROUP BY COALESCE(country, 'Unknown'), COALESCE(city, 'Unknown')
    ),
    geographic_summary AS (
        -- Summary statistics
        SELECT 
            COUNT(DISTINCT country) as total_countries,
            COUNT(DISTINCT city) as total_cities,
            COUNT(*) as total_visits_all,
            COUNT(DISTINCT fp) as total_unique_users,
            ROUND(COUNT(*)::DECIMAL / NULLIF(COUNT(DISTINCT fp), 0), 2) as avg_engagement_rate
        FROM filtered_visits
        WHERE country IS NOT NULL OR city IS NOT NULL
    )
    SELECT json_build_object(
    'period_info', json_build_object(
        'period_days', p_period_days,
        'start_date', start_date,
        'end_date', end_date,
        'timezone', p_timezone,
        'is_premium', p_is_premium
    ),
    'filters_applied', json_build_object(
        'has_filters', (p_tag_ids IS NOT NULL OR p_touchpoint_ids IS NOT NULL),
        'tags_count', COALESCE(array_length(p_tag_ids, 1), 0),
        'touchpoints_count', COALESCE(array_length(p_touchpoint_ids, 1), 0)
    ),
    'geographic_data', json_build_object(
        -- Tier-specific country data
        'countries', CASE 
            WHEN p_is_premium THEN
                -- Premium: Full country list (using subquery to access country_aggregation)
                (
                    SELECT json_agg(
                        json_build_object(
                            'country', ca.country,
                            'rank', ca.country_rank,
                            'total_visits', ca.total_visits,
                            'unique_users', ca.unique_users,
                            'visits_per_user', ca.visits_per_user,
                            'visit_share_pct', ca.visit_share_pct,
                            'cities_in_country', ca.cities_in_country,
                            'touchpoints_accessed', ca.touchpoints_accessed
                        ) ORDER BY ca.country_rank
                    )
                    FROM country_aggregation ca
                )
            ELSE
                -- Free: Top 5 countries only (using subquery to access country_aggregation)
                (
                    SELECT json_agg(
                        json_build_object(
                            'country', ca.country,
                            'rank', ca.country_rank,
                            'total_visits', ca.total_visits,
                            'unique_users', ca.unique_users,
                            'visits_per_user', ca.visits_per_user,
                            'visit_share_pct', ca.visit_share_pct
                        ) ORDER BY ca.country_rank
                    )
                    FROM country_aggregation ca
                    WHERE ca.country_rank <= 5
                )
        END,
        -- Premium-only city data (using subquery to access city_aggregation)
        'cities', CASE 
            WHEN p_is_premium THEN
                (
                    SELECT json_agg(
                        json_build_object(
                            'country', cta.country,
                            'city', cta.city,
                            'city_rank_in_country', cta.city_rank_in_country,
                            'city_rank_global', cta.city_rank_global,
                            'total_visits', cta.total_visits,
                            'unique_users', cta.unique_users,
                            'visits_per_user', cta.visits_per_user,
                            'touchpoints_accessed', cta.touchpoints_accessed,
                            'interaction_breakdown', json_build_object(
                                'link_clicks', cta.link_clicks,
                                'qr_scans', cta.qr_scans,
                                'nfc_taps', cta.nfc_taps,
                                'wifi_accesses', cta.wifi_accesses
                            )
                        ) ORDER BY cta.city_rank_global
                    )
                    FROM city_aggregation cta
                    WHERE cta.city_rank_global <= 20 -- Top 20 cities globally
                )
            ELSE 
                NULL -- json_build_object('premium_feature', TRUE, 'message', 'City-level analysis requires Premium plan')
        END,
        -- Summary (using subquery to access geographic_summary)
        'summary', (
            SELECT json_build_object(
                'total_countries', gs.total_countries,
                'total_cities', CASE WHEN p_is_premium THEN gs.total_cities ELSE NULL END,
                'countries_shown', CASE WHEN p_is_premium THEN gs.total_countries ELSE LEAST(5, gs.total_countries) END,
                'cities_shown', CASE WHEN p_is_premium THEN LEAST(20, gs.total_cities) ELSE NULL END,
                'total_visits', gs.total_visits_all,
                'total_unique_users', gs.total_unique_users,
                'avg_engagement_rate', gs.avg_engagement_rate,
                'geographic_diversity', CASE 
                    WHEN p_is_premium THEN
                        CASE 
                            WHEN gs.total_countries >= 10 THEN 'high_diversity'
                            WHEN gs.total_countries >= 5 THEN 'medium_diversity'
                            WHEN gs.total_countries >= 2 THEN 'low_diversity'
                            ELSE 'single_market'
                        END
                    ELSE NULL
                END
            )
            FROM geographic_summary gs
        )
    ),
    'insights', json_build_object(
        'top_market', (
            SELECT json_build_object(
                'country', ca.country,
                'visits', ca.total_visits,
                'market_share_pct', ca.visit_share_pct,
                'engagement_rate', ca.visits_per_user
            )
            FROM country_aggregation ca
            WHERE ca.country_rank = 1
        ),
        'geographic_concentration', (
            SELECT CASE 
                WHEN ca.visit_share_pct > 70 THEN 'highly_concentrated'
                WHEN ca.visit_share_pct > 50 THEN 'moderately_concentrated'  
                ELSE 'well_distributed'
            END
            FROM country_aggregation ca 
            WHERE ca.country_rank = 1
        ),
        'premium_insights', CASE 
            WHEN p_is_premium THEN
                json_build_object(
                    'top_city', (
                        SELECT json_build_object(
                            'city', cta.city,
                            'country', cta.country,
                            'visits', cta.total_visits,
                            'engagement_rate', cta.visits_per_user
                        )
                        FROM city_aggregation cta
                        WHERE cta.city_rank_global = 1
                    ),
                    'expansion_opportunities', (
                        SELECT json_agg(data)
                        FROM (
                            SELECT json_build_object(
                                'country', ca.country,
                                'cities_count', ca.cities_in_country,
                                'current_visits', ca.total_visits,
                                'growth_potential', CASE 
                                    WHEN ca.cities_in_country = 1 AND ca.total_visits > 10 THEN 'high'
                                    WHEN ca.cities_in_country <= 3 AND ca.total_visits > 5 THEN 'medium'
                                    ELSE 'low'
                                END
                            ) AS data
                            FROM country_aggregation ca
                            WHERE ca.country_rank <= 10 AND ca.cities_in_country <= 5
                            ORDER BY ca.total_visits DESC
                        ) AS ordered
                    )
                )
            ELSE 
                NULL -- json_build_object('message', 'Premium insights require Premium plan')
        END
    )
) INTO result;
    
    RETURN result;
    
EXCEPTION WHEN OTHERS THEN
    RETURN json_build_object(
        'error', TRUE,
        'message', SQLERRM,
        'organization_id', p_organization_id
    );
END;
$$;


--
-- Name: get_audience_geographic_distribution_old(uuid, integer, text, uuid[], uuid[], boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_audience_geographic_distribution_old(p_organization_id uuid, p_period_days integer, p_timezone text DEFAULT 'UTC'::text, p_tag_ids uuid[] DEFAULT NULL::uuid[], p_touchpoint_ids uuid[] DEFAULT NULL::uuid[], p_is_premium boolean DEFAULT false) RETURNS json
    LANGUAGE plpgsql
    AS $$DECLARE
    start_date TIMESTAMPTZ;
    end_date TIMESTAMPTZ;
    result JSON;
BEGIN
    -- Validate tier restrictions
    IF NOT p_is_premium AND p_period_days != 7 THEN
        RETURN json_build_object('error', TRUE, 'message', 'Free tier limited to 7 days only');
    END IF;
    
    IF NOT p_is_premium AND p_touchpoint_ids IS NOT NULL AND array_length(p_touchpoint_ids, 1) > 1 THEN
        RETURN json_build_object('error', TRUE, 'message', 'Free tier limited to 1 touchpoint only');
    END IF;

    -- Calculate date range in user's timezone
    end_date := CURRENT_TIMESTAMP AT TIME ZONE p_timezone;
    start_date := end_date - (p_period_days || ' days')::INTERVAL;
    
    WITH filtered_visits AS (
        -- Apply hierarchical filtering directly to visits
        SELECT 
            v.country,
            v.city,
            v.fp,
            v.type,
            v.created_at,
            v.tp_id
        FROM visits v
        WHERE v.organization_id = p_organization_id
            AND v.created_at >= start_date
            AND v.created_at < end_date            
            AND (
                -- No filtering if no filters specified
                (p_tag_ids IS NULL AND p_touchpoint_ids IS NULL)
                OR 
                -- Apply hierarchical filtering: tags first, then touchpoints
                (
                    (p_tag_ids IS NULL OR v.tp_id IN (
                        SELECT DISTINCT ttl.tp_id 
                        FROM tp_tag_links ttl 
                        WHERE ttl.tag_id = ANY(p_tag_ids)
                    ))
                    AND
                    (p_touchpoint_ids IS NULL OR v.tp_id = ANY(p_touchpoint_ids))
                )
            )
    ),
    country_aggregation AS (
        -- Country-level aggregation
        SELECT 
            COALESCE(country, 'Unknown') as country,
            COUNT(*) as total_visits,
            COUNT(DISTINCT fp) as unique_users,
            COUNT(DISTINCT tp_id) as touchpoints_accessed,            
            -- Engagement metrics
            ROUND(COUNT(*)::DECIMAL / NULLIF(COUNT(DISTINCT fp), 0), 2) as visits_per_user,
            COUNT(DISTINCT city) as cities_in_country,
            -- Market share calculation
            ROUND(COUNT(*)::DECIMAL / SUM(COUNT(*)) OVER() * 100, 1) as visit_share_pct,
            ROW_NUMBER() OVER (ORDER BY COUNT(*) DESC) as country_rank
        FROM filtered_visits
        GROUP BY COALESCE(country, 'Unknown')
    ),
    city_aggregation AS (
        -- City-level aggregation (Premium only)
        SELECT 
            COALESCE(country, 'Unknown') as country,
            COALESCE(city, 'Unknown') as city,
            COUNT(*) as total_visits,
            COUNT(DISTINCT fp) as unique_users,
            COUNT(DISTINCT tp_id) as touchpoints_accessed,
            COUNT(CASE WHEN type = 'LINK' THEN 1 END) as link_clicks,
            COUNT(CASE WHEN type = 'QR' THEN 1 END) as qr_scans,
            COUNT(CASE WHEN type = 'NFC' THEN 1 END) as nfc_taps,
            COUNT(CASE WHEN type = 'WIFI' THEN 1 END) as wifi_accesses,
            ROUND(COUNT(*)::DECIMAL / NULLIF(COUNT(DISTINCT fp), 0), 2) as visits_per_user,
            -- City rank within country
            ROW_NUMBER() OVER (PARTITION BY COALESCE(country, 'Unknown') ORDER BY COUNT(*) DESC) as city_rank_in_country,
            -- Overall city rank
            ROW_NUMBER() OVER (ORDER BY COUNT(*) DESC) as city_rank_global
        FROM filtered_visits
        GROUP BY COALESCE(country, 'Unknown'), COALESCE(city, 'Unknown')
    ),
    geographic_summary AS (
        -- Summary statistics
        SELECT 
            COUNT(DISTINCT country) as total_countries,
            COUNT(DISTINCT city) as total_cities,
            COUNT(*) as total_visits_all,
            COUNT(DISTINCT fp) as total_unique_users,
            ROUND(COUNT(*)::DECIMAL / NULLIF(COUNT(DISTINCT fp), 0), 2) as avg_engagement_rate
        FROM filtered_visits
        WHERE country IS NOT NULL OR city IS NOT NULL
    )
    SELECT json_build_object(
    'period_info', json_build_object(
        'period_days', p_period_days,
        'start_date', start_date,
        'end_date', end_date,
        'timezone', p_timezone,
        'is_premium', p_is_premium
    ),
    'filters_applied', json_build_object(
        'has_filters', (p_tag_ids IS NOT NULL OR p_touchpoint_ids IS NOT NULL),
        'tags_count', COALESCE(array_length(p_tag_ids, 1), 0),
        'touchpoints_count', COALESCE(array_length(p_touchpoint_ids, 1), 0)
    ),
    'geographic_data', json_build_object(
        -- Tier-specific country data
        'countries', CASE 
            WHEN p_is_premium THEN
                -- Premium: Full country list (using subquery to access country_aggregation)
                (
                    SELECT json_agg(
                        json_build_object(
                            'country', ca.country,
                            'rank', ca.country_rank,
                            'total_visits', ca.total_visits,
                            'unique_users', ca.unique_users,
                            'visits_per_user', ca.visits_per_user,
                            'visit_share_pct', ca.visit_share_pct,
                            'cities_in_country', ca.cities_in_country,
                            'touchpoints_accessed', ca.touchpoints_accessed
                        ) ORDER BY ca.country_rank
                    )
                    FROM country_aggregation ca
                )
            ELSE
                -- Free: Top 5 countries only (using subquery to access country_aggregation)
                (
                    SELECT json_agg(
                        json_build_object(
                            'country', ca.country,
                            'rank', ca.country_rank,
                            'total_visits', ca.total_visits,
                            'unique_users', ca.unique_users,
                            'visits_per_user', ca.visits_per_user,
                            'visit_share_pct', ca.visit_share_pct
                        ) ORDER BY ca.country_rank
                    )
                    FROM country_aggregation ca
                    WHERE ca.country_rank <= 5
                )
        END,
        -- Premium-only city data (using subquery to access city_aggregation)
        'cities', CASE 
            WHEN p_is_premium THEN
                (
                    SELECT json_agg(
                        json_build_object(
                            'country', cta.country,
                            'city', cta.city,
                            'city_rank_in_country', cta.city_rank_in_country,
                            'city_rank_global', cta.city_rank_global,
                            'total_visits', cta.total_visits,
                            'unique_users', cta.unique_users,
                            'visits_per_user', cta.visits_per_user,
                            'touchpoints_accessed', cta.touchpoints_accessed,
                            'interaction_breakdown', json_build_object(
                                'link_clicks', cta.link_clicks,
                                'qr_scans', cta.qr_scans,
                                'nfc_taps', cta.nfc_taps,
                                'wifi_accesses', cta.wifi_accesses
                            )
                        ) ORDER BY cta.city_rank_global
                    )
                    FROM city_aggregation cta
                    WHERE cta.city_rank_global <= 20 -- Top 20 cities globally
                )
            ELSE 
                NULL -- json_build_object('premium_feature', TRUE, 'message', 'City-level analysis requires Premium plan')
        END,
        -- Summary (using subquery to access geographic_summary)
        'summary', (
            SELECT json_build_object(
                'total_countries', gs.total_countries,
                'total_cities', CASE WHEN p_is_premium THEN gs.total_cities ELSE NULL END,
                'countries_shown', CASE WHEN p_is_premium THEN gs.total_countries ELSE LEAST(5, gs.total_countries) END,
                'cities_shown', CASE WHEN p_is_premium THEN LEAST(20, gs.total_cities) ELSE NULL END,
                'total_visits', gs.total_visits_all,
                'total_unique_users', gs.total_unique_users,
                'avg_engagement_rate', gs.avg_engagement_rate,
                'geographic_diversity', CASE 
                    WHEN p_is_premium THEN
                        CASE 
                            WHEN gs.total_countries >= 10 THEN 'high_diversity'
                            WHEN gs.total_countries >= 5 THEN 'medium_diversity'
                            WHEN gs.total_countries >= 2 THEN 'low_diversity'
                            ELSE 'single_market'
                        END
                    ELSE NULL
                END
            )
            FROM geographic_summary gs
        )
    ),
    'insights', json_build_object(
        'top_market', (
            SELECT json_build_object(
                'country', ca.country,
                'visits', ca.total_visits,
                'market_share_pct', ca.visit_share_pct,
                'engagement_rate', ca.visits_per_user
            )
            FROM country_aggregation ca
            WHERE ca.country_rank = 1
        ),
        'geographic_concentration', (
            SELECT CASE 
                WHEN ca.visit_share_pct > 70 THEN 'highly_concentrated'
                WHEN ca.visit_share_pct > 50 THEN 'moderately_concentrated'  
                ELSE 'well_distributed'
            END
            FROM country_aggregation ca 
            WHERE ca.country_rank = 1
        ),
        'premium_insights', CASE 
            WHEN p_is_premium THEN
                json_build_object(
                    'top_city', (
                        SELECT json_build_object(
                            'city', cta.city,
                            'country', cta.country,
                            'visits', cta.total_visits,
                            'engagement_rate', cta.visits_per_user
                        )
                        FROM city_aggregation cta
                        WHERE cta.city_rank_global = 1
                    ),
                    'expansion_opportunities', (
                        SELECT json_agg(data)
                        FROM (
                            SELECT json_build_object(
                                'country', ca.country,
                                'cities_count', ca.cities_in_country,
                                'current_visits', ca.total_visits,
                                'growth_potential', CASE 
                                    WHEN ca.cities_in_country = 1 AND ca.total_visits > 10 THEN 'high'
                                    WHEN ca.cities_in_country <= 3 AND ca.total_visits > 5 THEN 'medium'
                                    ELSE 'low'
                                END
                            ) AS data
                            FROM country_aggregation ca
                            WHERE ca.country_rank <= 10 AND ca.cities_in_country <= 5
                            ORDER BY ca.total_visits DESC
                        ) AS ordered
                    )
                )
            ELSE 
                NULL -- json_build_object('message', 'Premium insights require Premium plan')
        END
    )
) INTO result;
    
    RETURN result;
    
EXCEPTION WHEN OTHERS THEN
    RETURN json_build_object(
        'error', TRUE,
        'message', SQLERRM,
        'organization_id', p_organization_id
    );
END;$$;


--
-- Name: get_batch_touch_point_ids(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_batch_touch_point_ids(batch_size integer) RETURNS TABLE(id bigint)
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN QUERY
  SELECT nextval('public.v2_touch_points_short_id_seq')
  FROM generate_series(1, batch_size);
END;
$$;


--
-- Name: get_behavior_interaction_frequency(uuid, integer, text, uuid[], uuid[], boolean, uuid[], boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_behavior_interaction_frequency(p_organization_id uuid, p_period_days integer, p_timezone text DEFAULT 'UTC'::text, p_tag_ids uuid[] DEFAULT NULL::uuid[], p_touchpoint_ids uuid[] DEFAULT NULL::uuid[], p_is_premium boolean DEFAULT false, p_collection_ids uuid[] DEFAULT NULL::uuid[], p_include_null_collection boolean DEFAULT false) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    start_date TIMESTAMPTZ;
    end_date TIMESTAMPTZ;
    result JSON;
BEGIN
    -- Validate tier restrictions
    IF NOT p_is_premium AND p_period_days != 7 THEN
        RETURN json_build_object('error', TRUE, 'message', 'Free tier limited to 7 days only');
    END IF;
    
    IF NOT p_is_premium AND p_touchpoint_ids IS NOT NULL AND array_length(p_touchpoint_ids, 1) > 1 THEN
        RETURN json_build_object('error', TRUE, 'message', 'Free tier limited to 1 touchpoint only');
    END IF;

    -- Calculate date range in user's timezone
    end_date := CURRENT_TIMESTAMP AT TIME ZONE p_timezone;
    start_date := end_date - (p_period_days || ' days')::INTERVAL;
    
    WITH filtered_visits AS (
        -- Apply hierarchical filtering
        SELECT 
            v.fp,
            v.type,
            v.created_at,
            v.tp_id,
            v.platform,
            DATE(v.created_at AT TIME ZONE p_timezone) as visit_date,
            EXTRACT(hour FROM v.created_at AT TIME ZONE p_timezone) as visit_hour,
            EXTRACT(dow FROM v.created_at AT TIME ZONE p_timezone) as day_of_week
        FROM visits v
        WHERE v.organization_id = p_organization_id
            AND v.created_at >= start_date
            AND v.created_at < end_date            
            AND v.fp IS NOT NULL
            AND (
                -- No filtering if no filters specified
                (p_tag_ids IS NULL AND p_touchpoint_ids IS NULL)
                OR 
                -- Apply hierarchical filtering: tags first, then touchpoints
                (
                    (p_tag_ids IS NULL OR v.tp_id IN (
                        SELECT DISTINCT ttl.tp_id 
                        FROM tp_tag_links ttl 
                        WHERE ttl.tag_id = ANY(p_tag_ids)
                    ))
                    AND
                    (p_touchpoint_ids IS NULL OR v.tp_id = ANY(p_touchpoint_ids))
                )
            )
            AND (
                p_collection_ids IS NULL
                OR v.tp_id IN (
                    SELECT tp.id
                    FROM touch_points tp
                    WHERE tp.collection_id = ANY(p_collection_ids)
                       OR (p_include_null_collection AND tp.collection_id IS NULL)
                )
            )
    ),
    daily_frequency_analysis AS (
        -- Analyze daily interaction patterns
        SELECT 
            visit_date,
            COUNT(*) as total_interactions,
            COUNT(DISTINCT fp) as unique_users,
            COUNT(DISTINCT tp_id) as active_touchpoints,
            -- Interaction type breakdown
            COUNT(CASE WHEN type = 'LINK' THEN 1 END) as link_interactions,
            COUNT(CASE WHEN type = 'QR' THEN 1 END) as qr_interactions,
            COUNT(CASE WHEN type = 'NFC' THEN 1 END) as nfc_interactions,
            COUNT(CASE WHEN type = 'WIFI' THEN 1 END) as wifi_interactions,
            -- Platform breakdown
            COUNT(CASE WHEN platform = 'Mobile' THEN 1 END) as mobile_interactions,
            COUNT(CASE WHEN platform = 'Desktop' THEN 1 END) as desktop_interactions,
            -- Engagement metrics
            ROUND(COUNT(*)::DECIMAL / NULLIF(COUNT(DISTINCT fp), 0), 2) as interactions_per_user,
            -- Peak hour identification
            MODE() WITHIN GROUP (ORDER BY visit_hour) as peak_hour
        FROM filtered_visits
        GROUP BY visit_date
        ORDER BY visit_date
    ),
    hourly_frequency_analysis AS (
        -- Analyze hourly patterns across all days
        SELECT 
            visit_hour,
            COUNT(*) as total_interactions,
            COUNT(DISTINCT fp) as unique_users,
            COUNT(DISTINCT visit_date) as active_days,
            ROUND(COUNT(*)::DECIMAL / NULLIF(COUNT(DISTINCT visit_date), 0), 1) as avg_interactions_per_day,
            ROUND(COUNT(DISTINCT fp)::DECIMAL / NULLIF(COUNT(DISTINCT visit_date), 0), 1) as avg_users_per_day
        FROM filtered_visits
        GROUP BY visit_hour
        ORDER BY visit_hour
    ),
    day_of_week_analysis AS (
        -- Analyze day-of-week patterns
        SELECT 
            day_of_week,
            CASE day_of_week
                WHEN 0 THEN 'Sunday'
                WHEN 1 THEN 'Monday'
                WHEN 2 THEN 'Tuesday'
                WHEN 3 THEN 'Wednesday'
                WHEN 4 THEN 'Thursday'
                WHEN 5 THEN 'Friday'
                WHEN 6 THEN 'Saturday'
            END as day_name,
            COUNT(*) as total_interactions,
            COUNT(DISTINCT fp) as unique_users,
            COUNT(DISTINCT visit_date) as occurrences,
            ROUND(COUNT(*)::DECIMAL / NULLIF(COUNT(DISTINCT visit_date), 0), 1) as avg_interactions_per_occurrence,
            ROUND(COUNT(DISTINCT fp)::DECIMAL / NULLIF(COUNT(DISTINCT visit_date), 0), 1) as avg_users_per_occurrence
        FROM filtered_visits
        GROUP BY day_of_week
        ORDER BY day_of_week
    ),
    user_frequency_segments AS (
        -- Analyze user interaction frequency patterns
        SELECT 
            fp,
            COUNT(*) as total_interactions,
            COUNT(DISTINCT visit_date) as active_days,
            COUNT(DISTINCT tp_id) as unique_touchpoints,
            ROUND(COUNT(*)::DECIMAL / NULLIF(COUNT(DISTINCT visit_date), 0), 2) as interactions_per_day,
            -- Classify users by frequency
            CASE 
                WHEN COUNT(*) = 1 THEN 'one_time'
                WHEN COUNT(*) BETWEEN 2 AND 5 THEN 'occasional'
                WHEN COUNT(*) BETWEEN 6 AND 15 THEN 'regular'
                WHEN COUNT(*) > 15 THEN 'frequent'
            END as frequency_segment,
            -- Classify by consistency
            CASE 
                WHEN COUNT(DISTINCT visit_date) = 1 THEN 'single_day'
                WHEN COUNT(DISTINCT visit_date)::DECIMAL / p_period_days > 0.7 THEN 'highly_consistent'
                WHEN COUNT(DISTINCT visit_date)::DECIMAL / p_period_days > 0.3 THEN 'moderately_consistent'
                ELSE 'sporadic'
            END as consistency_segment
        FROM filtered_visits
        GROUP BY fp
    ),
    frequency_distribution AS (
        -- Aggregate frequency segments
        SELECT 
            frequency_segment,
            consistency_segment,
            COUNT(*) as user_count,
            ROUND(AVG(total_interactions), 2) as avg_interactions,
            ROUND(AVG(active_days), 2) as avg_active_days,
            ROUND(AVG(interactions_per_day), 2) as avg_interactions_per_day
        FROM user_frequency_segments
        GROUP BY frequency_segment, consistency_segment
    ),
    peak_periods AS (
        -- Identify peak activity periods
        SELECT 
            -- Peak day of week
            (SELECT day_name FROM day_of_week_analysis ORDER BY total_interactions DESC LIMIT 1) as peak_day,
            (SELECT total_interactions FROM day_of_week_analysis ORDER BY total_interactions DESC LIMIT 1) as peak_day_interactions,
            -- Peak hour
            (SELECT visit_hour FROM hourly_frequency_analysis ORDER BY total_interactions DESC LIMIT 1) as peak_hour,
            (SELECT total_interactions FROM hourly_frequency_analysis ORDER BY total_interactions DESC LIMIT 1) as peak_hour_interactions,
            -- Low activity periods
            (SELECT day_name FROM day_of_week_analysis ORDER BY total_interactions ASC LIMIT 1) as lowest_day,
            (SELECT visit_hour FROM hourly_frequency_analysis ORDER BY total_interactions ASC LIMIT 1) as lowest_hour
    ),
    frequency_insights AS (
        -- Generate behavioral insights
        SELECT 
            -- User distribution
            (SELECT COUNT(*) FROM user_frequency_segments WHERE frequency_segment = 'one_time') as one_time_users,
            (SELECT COUNT(*) FROM user_frequency_segments WHERE frequency_segment = 'occasional') as occasional_users,
            (SELECT COUNT(*) FROM user_frequency_segments WHERE frequency_segment = 'regular') as regular_users,
            (SELECT COUNT(*) FROM user_frequency_segments WHERE frequency_segment = 'frequent') as frequent_users,
            -- Consistency distribution
            (SELECT COUNT(*) FROM user_frequency_segments WHERE consistency_segment = 'highly_consistent') as highly_consistent_users,
            (SELECT COUNT(*) FROM user_frequency_segments WHERE consistency_segment = 'moderately_consistent') as moderately_consistent_users,
            (SELECT COUNT(*) FROM user_frequency_segments WHERE consistency_segment = 'sporadic') as sporadic_users,
            -- Overall metrics
            (SELECT COUNT(DISTINCT fp) FROM filtered_visits) as total_unique_users,
            (SELECT COUNT(*) FROM filtered_visits) as total_interactions,
            (SELECT COUNT(DISTINCT visit_date) FROM filtered_visits) as total_active_days
    )
    SELECT json_build_object(
        'period_info', json_build_object(
            'period_days', p_period_days,
            'start_date', start_date,
            'end_date', end_date,
            'timezone', p_timezone,
            'is_premium', p_is_premium,
            'analysis_type', 'interaction_frequency'
        ),
        'filters_applied', json_build_object(
            'has_filters', (p_tag_ids IS NOT NULL OR p_touchpoint_ids IS NOT NULL),
            'tags_count', COALESCE(array_length(p_tag_ids, 1), 0),
            'touchpoints_count', COALESCE(array_length(p_touchpoint_ids, 1), 0)
        ),
        'frequency_analysis', json_build_object(
            -- Daily trends
            'daily_patterns', (
                SELECT json_agg(
                    json_build_object(
                        'date', visit_date,
                        'total_interactions', total_interactions,
                        'unique_users', unique_users,
                        'interactions_per_user', interactions_per_user,
                        'active_touchpoints', active_touchpoints,
                        'peak_hour', peak_hour,
                        'interaction_breakdown', json_build_object(
                            'link_interactions', link_interactions,
                            'qr_interactions', qr_interactions,
                            'nfc_interactions', nfc_interactions,
                            'wifi_interactions', wifi_interactions
                        ),
                        'platform_breakdown', json_build_object(
                            'mobile_interactions', mobile_interactions,
                            'desktop_interactions', desktop_interactions
                        )
                    ) ORDER BY visit_date
                )
                FROM daily_frequency_analysis
            ),
            -- Hourly patterns
            'hourly_patterns', (
                SELECT json_agg(
                    json_build_object(
                        'hour', visit_hour,
                        'total_interactions', total_interactions,
                        'unique_users', unique_users,
                        'avg_interactions_per_day', avg_interactions_per_day,
                        'avg_users_per_day', avg_users_per_day,
                        'active_days', active_days
                    ) ORDER BY visit_hour
                )
                FROM hourly_frequency_analysis
            ),
            -- Day of week patterns
            'day_of_week_patterns', (
                SELECT json_agg(
                    json_build_object(
                        'day_of_week', day_of_week,
                        'day_name', day_name,
                        'total_interactions', total_interactions,
                        'unique_users', unique_users,
                        'avg_interactions_per_occurrence', avg_interactions_per_occurrence,
                        'avg_users_per_occurrence', avg_users_per_occurrence,
                        'occurrences', occurrences
                    ) ORDER BY day_of_week
                )
                FROM day_of_week_analysis
            ),
            -- User frequency distribution
            'user_frequency_distribution', CASE 
                WHEN p_is_premium THEN
                    (
                        SELECT json_agg(
                            json_build_object(
                                'frequency_segment', frequency_segment,
                                'consistency_segment', consistency_segment,
                                'user_count', user_count,
                                'avg_interactions', avg_interactions,
                                'avg_active_days', avg_active_days,
                                'avg_interactions_per_day', avg_interactions_per_day
                            )
                        )
                        FROM frequency_distribution
                    )
                ELSE NULL
            END
        ),
        'insights', json_build_object(
            -- Peak activity insights
            'peak_periods', (
                SELECT json_build_object(
                    'peak_day', json_build_object(
                        'day', peak_day,
                        'interactions', peak_day_interactions
                    ),
                    'peak_hour', json_build_object(
                        'hour', peak_hour,
                        'interactions', peak_hour_interactions
                    ),
                    'lowest_activity', json_build_object(
                        'day', lowest_day,
                        'hour', lowest_hour
                    )
                )
                FROM peak_periods
            ),
            -- User behavior insights
            'user_behavior_summary', (
                SELECT json_build_object(
                    'total_users', total_unique_users,
                    'total_interactions', total_interactions,
                    'active_days', total_active_days,
                    'avg_interactions_per_user', ROUND(total_interactions::DECIMAL / NULLIF(total_unique_users, 0), 2),
                    'avg_interactions_per_day', ROUND(total_interactions::DECIMAL / NULLIF(total_active_days, 0), 1),
                    'frequency_distribution', json_build_object(
                        'one_time_users', one_time_users,
                        'occasional_users', occasional_users,
                        'regular_users', regular_users,
                        'frequent_users', frequent_users
                    ),
                    'consistency_distribution', CASE 
                        WHEN p_is_premium THEN
                            json_build_object(
                                'highly_consistent', highly_consistent_users,
                                'moderately_consistent', moderately_consistent_users,
                                'sporadic', sporadic_users
                            )
                        ELSE NULL
                    END
                )
                FROM frequency_insights
            ),
            -- Behavioral recommendations
            'recommendations', CASE 
                WHEN p_is_premium THEN
                (
                    SELECT json_agg(
                        json_build_object(
                            'recommendation_type', recommendation_type,
                            'priority', priority,
                            'category', category,
                            'metric_key', metric_key,
                            'threshold', threshold,
                            'current_value', current_value,
                            'improvement_potential', improvement_potential
                        )
                    )
                    FROM (
                        SELECT 
                            'high_one_time_users' as recommendation_type,
                            'high' as priority,
                            'retention' as category,
                            'one_time_user_rate' as metric_key,
                            0.6 as threshold,
                            ROUND(fi.one_time_users::DECIMAL / fi.total_unique_users, 3) as current_value,
                            'implement_follow_up_campaigns' as improvement_potential
                        FROM frequency_insights fi
                        WHERE fi.one_time_users::DECIMAL / fi.total_unique_users > 0.6
                        
                        UNION ALL
                        
                        SELECT 
                            'strong_frequent_users' as recommendation_type,
                            'medium' as priority,
                            'loyalty' as category,
                            'frequent_user_rate' as metric_key,
                            0.2 as threshold,
                            ROUND(fi.frequent_users::DECIMAL / fi.total_unique_users, 3) as current_value,
                            'implement_loyalty_programs' as improvement_potential
                        FROM frequency_insights fi
                        WHERE fi.frequent_users::DECIMAL / fi.total_unique_users > 0.2
                        
                        UNION ALL
                        
                        SELECT 
                            'business_hours_peak' as recommendation_type,
                            'medium' as priority,
                            'timing_optimization' as category,
                            'peak_hour' as metric_key,
                            9 as threshold,
                            pp.peak_hour as current_value,
                            'optimize_for_professional_use' as improvement_potential
                        FROM peak_periods pp
                        WHERE pp.peak_hour BETWEEN 9 AND 17
                        
                        UNION ALL
                        
                        SELECT 
                            'evening_peak' as recommendation_type,
                            'medium' as priority,
                            'timing_optimization' as category,
                            'peak_hour' as metric_key,
                            18 as threshold,
                            pp.peak_hour as current_value,
                            'focus_on_leisure_marketing' as improvement_potential
                        FROM peak_periods pp
                        WHERE pp.peak_hour BETWEEN 18 AND 22
                        
                        UNION ALL
                        
                        SELECT 
                            'high_sporadic_usage' as recommendation_type,
                            'high' as priority,
                            'engagement_consistency' as category,
                            'sporadic_user_rate' as metric_key,
                            0.5 as threshold,
                            ROUND(fi.sporadic_users::DECIMAL / fi.total_unique_users, 3) as current_value,
                            'improve_content_scheduling' as improvement_potential
                        FROM frequency_insights fi
                        WHERE fi.sporadic_users::DECIMAL / fi.total_unique_users > 0.5
                        
                        UNION ALL
                        
                        SELECT 
                            'low_engagement_consistency' as recommendation_type,
                            'medium' as priority,
                            'user_experience' as category,
                            'consistent_user_rate' as metric_key,
                            0.3 as threshold,
                            ROUND(fi.highly_consistent_users::DECIMAL / fi.total_unique_users, 3) as current_value,
                            'enhance_user_experience' as improvement_potential
                        FROM frequency_insights fi
                        WHERE fi.highly_consistent_users::DECIMAL / fi.total_unique_users < 0.3
                        
                    ) recommendations
                )
                ELSE 
                    NULL
            END
        )
    ) INTO result;
    
    RETURN result;
    
EXCEPTION WHEN OTHERS THEN
    RETURN json_build_object(
        'error', TRUE,
        'message', SQLERRM,
        'organization_id', p_organization_id
    );
END;
$$;


--
-- Name: get_behavior_interaction_frequency_old(uuid, integer, text, uuid[], uuid[], boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_behavior_interaction_frequency_old(p_organization_id uuid, p_period_days integer, p_timezone text DEFAULT 'UTC'::text, p_tag_ids uuid[] DEFAULT NULL::uuid[], p_touchpoint_ids uuid[] DEFAULT NULL::uuid[], p_is_premium boolean DEFAULT false) RETURNS json
    LANGUAGE plpgsql
    AS $$DECLARE
    start_date TIMESTAMPTZ;
    end_date TIMESTAMPTZ;
    result JSON;
BEGIN
    -- Validate tier restrictions
    IF NOT p_is_premium AND p_period_days != 7 THEN
        RETURN json_build_object('error', TRUE, 'message', 'Free tier limited to 7 days only');
    END IF;
    
    IF NOT p_is_premium AND p_touchpoint_ids IS NOT NULL AND array_length(p_touchpoint_ids, 1) > 1 THEN
        RETURN json_build_object('error', TRUE, 'message', 'Free tier limited to 1 touchpoint only');
    END IF;

    -- Calculate date range in user's timezone
    end_date := CURRENT_TIMESTAMP AT TIME ZONE p_timezone;
    start_date := end_date - (p_period_days || ' days')::INTERVAL;
    
    WITH filtered_visits AS (
        -- Apply hierarchical filtering
        SELECT 
            v.fp,
            v.type,
            v.created_at,
            v.tp_id,
            v.platform,
            DATE(v.created_at AT TIME ZONE p_timezone) as visit_date,
            EXTRACT(hour FROM v.created_at AT TIME ZONE p_timezone) as visit_hour,
            EXTRACT(dow FROM v.created_at AT TIME ZONE p_timezone) as day_of_week
        FROM visits v
        WHERE v.organization_id = p_organization_id
            AND v.created_at >= start_date
            AND v.created_at < end_date            
            AND v.fp IS NOT NULL
            AND (
                -- No filtering if no filters specified
                (p_tag_ids IS NULL AND p_touchpoint_ids IS NULL)
                OR 
                -- Apply hierarchical filtering: tags first, then touchpoints
                (
                    (p_tag_ids IS NULL OR v.tp_id IN (
                        SELECT DISTINCT ttl.tp_id 
                        FROM tp_tag_links ttl 
                        WHERE ttl.tag_id = ANY(p_tag_ids)
                    ))
                    AND
                    (p_touchpoint_ids IS NULL OR v.tp_id = ANY(p_touchpoint_ids))
                )
            )
    ),
    daily_frequency_analysis AS (
        -- Analyze daily interaction patterns
        SELECT 
            visit_date,
            COUNT(*) as total_interactions,
            COUNT(DISTINCT fp) as unique_users,
            COUNT(DISTINCT tp_id) as active_touchpoints,
            -- Interaction type breakdown
            COUNT(CASE WHEN type = 'LINK' THEN 1 END) as link_interactions,
            COUNT(CASE WHEN type = 'QR' THEN 1 END) as qr_interactions,
            COUNT(CASE WHEN type = 'NFC' THEN 1 END) as nfc_interactions,
            COUNT(CASE WHEN type = 'WIFI' THEN 1 END) as wifi_interactions,
            -- Platform breakdown
            COUNT(CASE WHEN platform = 'Mobile' THEN 1 END) as mobile_interactions,
            COUNT(CASE WHEN platform = 'Desktop' THEN 1 END) as desktop_interactions,
            -- Engagement metrics
            ROUND(COUNT(*)::DECIMAL / NULLIF(COUNT(DISTINCT fp), 0), 2) as interactions_per_user,
            -- Peak hour identification
            MODE() WITHIN GROUP (ORDER BY visit_hour) as peak_hour
        FROM filtered_visits
        GROUP BY visit_date
        ORDER BY visit_date
    ),
    hourly_frequency_analysis AS (
        -- Analyze hourly patterns across all days
        SELECT 
            visit_hour,
            COUNT(*) as total_interactions,
            COUNT(DISTINCT fp) as unique_users,
            COUNT(DISTINCT visit_date) as active_days,
            ROUND(COUNT(*)::DECIMAL / NULLIF(COUNT(DISTINCT visit_date), 0), 1) as avg_interactions_per_day,
            ROUND(COUNT(DISTINCT fp)::DECIMAL / NULLIF(COUNT(DISTINCT visit_date), 0), 1) as avg_users_per_day
        FROM filtered_visits
        GROUP BY visit_hour
        ORDER BY visit_hour
    ),
    day_of_week_analysis AS (
        -- Analyze day-of-week patterns
        SELECT 
            day_of_week,
            CASE day_of_week
                WHEN 0 THEN 'Sunday'
                WHEN 1 THEN 'Monday'
                WHEN 2 THEN 'Tuesday'
                WHEN 3 THEN 'Wednesday'
                WHEN 4 THEN 'Thursday'
                WHEN 5 THEN 'Friday'
                WHEN 6 THEN 'Saturday'
            END as day_name,
            COUNT(*) as total_interactions,
            COUNT(DISTINCT fp) as unique_users,
            COUNT(DISTINCT visit_date) as occurrences,
            ROUND(COUNT(*)::DECIMAL / NULLIF(COUNT(DISTINCT visit_date), 0), 1) as avg_interactions_per_occurrence,
            ROUND(COUNT(DISTINCT fp)::DECIMAL / NULLIF(COUNT(DISTINCT visit_date), 0), 1) as avg_users_per_occurrence
        FROM filtered_visits
        GROUP BY day_of_week
        ORDER BY day_of_week
    ),
    user_frequency_segments AS (
        -- Analyze user interaction frequency patterns
        SELECT 
            fp,
            COUNT(*) as total_interactions,
            COUNT(DISTINCT visit_date) as active_days,
            COUNT(DISTINCT tp_id) as unique_touchpoints,
            ROUND(COUNT(*)::DECIMAL / NULLIF(COUNT(DISTINCT visit_date), 0), 2) as interactions_per_day,
            -- Classify users by frequency
            CASE 
                WHEN COUNT(*) = 1 THEN 'one_time'
                WHEN COUNT(*) BETWEEN 2 AND 5 THEN 'occasional'
                WHEN COUNT(*) BETWEEN 6 AND 15 THEN 'regular'
                WHEN COUNT(*) > 15 THEN 'frequent'
            END as frequency_segment,
            -- Classify by consistency
            CASE 
                WHEN COUNT(DISTINCT visit_date) = 1 THEN 'single_day'
                WHEN COUNT(DISTINCT visit_date)::DECIMAL / p_period_days > 0.7 THEN 'highly_consistent'
                WHEN COUNT(DISTINCT visit_date)::DECIMAL / p_period_days > 0.3 THEN 'moderately_consistent'
                ELSE 'sporadic'
            END as consistency_segment
        FROM filtered_visits
        GROUP BY fp
    ),
    frequency_distribution AS (
        -- Aggregate frequency segments
        SELECT 
            frequency_segment,
            consistency_segment,
            COUNT(*) as user_count,
            ROUND(AVG(total_interactions), 2) as avg_interactions,
            ROUND(AVG(active_days), 2) as avg_active_days,
            ROUND(AVG(interactions_per_day), 2) as avg_interactions_per_day
        FROM user_frequency_segments
        GROUP BY frequency_segment, consistency_segment
    ),
    peak_periods AS (
        -- Identify peak activity periods
        SELECT 
            -- Peak day of week
            (SELECT day_name FROM day_of_week_analysis ORDER BY total_interactions DESC LIMIT 1) as peak_day,
            (SELECT total_interactions FROM day_of_week_analysis ORDER BY total_interactions DESC LIMIT 1) as peak_day_interactions,
            -- Peak hour
            (SELECT visit_hour FROM hourly_frequency_analysis ORDER BY total_interactions DESC LIMIT 1) as peak_hour,
            (SELECT total_interactions FROM hourly_frequency_analysis ORDER BY total_interactions DESC LIMIT 1) as peak_hour_interactions,
            -- Low activity periods
            (SELECT day_name FROM day_of_week_analysis ORDER BY total_interactions ASC LIMIT 1) as lowest_day,
            (SELECT visit_hour FROM hourly_frequency_analysis ORDER BY total_interactions ASC LIMIT 1) as lowest_hour
    ),
    frequency_insights AS (
        -- Generate behavioral insights
        SELECT 
            -- User distribution
            (SELECT COUNT(*) FROM user_frequency_segments WHERE frequency_segment = 'one_time') as one_time_users,
            (SELECT COUNT(*) FROM user_frequency_segments WHERE frequency_segment = 'occasional') as occasional_users,
            (SELECT COUNT(*) FROM user_frequency_segments WHERE frequency_segment = 'regular') as regular_users,
            (SELECT COUNT(*) FROM user_frequency_segments WHERE frequency_segment = 'frequent') as frequent_users,
            -- Consistency distribution
            (SELECT COUNT(*) FROM user_frequency_segments WHERE consistency_segment = 'highly_consistent') as highly_consistent_users,
            (SELECT COUNT(*) FROM user_frequency_segments WHERE consistency_segment = 'moderately_consistent') as moderately_consistent_users,
            (SELECT COUNT(*) FROM user_frequency_segments WHERE consistency_segment = 'sporadic') as sporadic_users,
            -- Overall metrics
            (SELECT COUNT(DISTINCT fp) FROM filtered_visits) as total_unique_users,
            (SELECT COUNT(*) FROM filtered_visits) as total_interactions,
            (SELECT COUNT(DISTINCT visit_date) FROM filtered_visits) as total_active_days
    )
    SELECT json_build_object(
        'period_info', json_build_object(
            'period_days', p_period_days,
            'start_date', start_date,
            'end_date', end_date,
            'timezone', p_timezone,
            'is_premium', p_is_premium,
            'analysis_type', 'interaction_frequency'
        ),
        'filters_applied', json_build_object(
            'has_filters', (p_tag_ids IS NOT NULL OR p_touchpoint_ids IS NOT NULL),
            'tags_count', COALESCE(array_length(p_tag_ids, 1), 0),
            'touchpoints_count', COALESCE(array_length(p_touchpoint_ids, 1), 0)
        ),
        'frequency_analysis', json_build_object(
            -- Daily trends
            'daily_patterns', (
                SELECT json_agg(
                    json_build_object(
                        'date', visit_date,
                        'total_interactions', total_interactions,
                        'unique_users', unique_users,
                        'interactions_per_user', interactions_per_user,
                        'active_touchpoints', active_touchpoints,
                        'peak_hour', peak_hour,
                        'interaction_breakdown', json_build_object(
                            'link_interactions', link_interactions,
                            'qr_interactions', qr_interactions,
                            'nfc_interactions', nfc_interactions,
                            'wifi_interactions', wifi_interactions
                        ),
                        'platform_breakdown', json_build_object(
                            'mobile_interactions', mobile_interactions,
                            'desktop_interactions', desktop_interactions
                        )
                    ) ORDER BY visit_date
                )
                FROM daily_frequency_analysis
            ),
            -- Hourly patterns
            'hourly_patterns', (
                SELECT json_agg(
                    json_build_object(
                        'hour', visit_hour,
                        'total_interactions', total_interactions,
                        'unique_users', unique_users,
                        'avg_interactions_per_day', avg_interactions_per_day,
                        'avg_users_per_day', avg_users_per_day,
                        'active_days', active_days
                    ) ORDER BY visit_hour
                )
                FROM hourly_frequency_analysis
            ),
            -- Day of week patterns
            'day_of_week_patterns', (
                SELECT json_agg(
                    json_build_object(
                        'day_of_week', day_of_week,
                        'day_name', day_name,
                        'total_interactions', total_interactions,
                        'unique_users', unique_users,
                        'avg_interactions_per_occurrence', avg_interactions_per_occurrence,
                        'avg_users_per_occurrence', avg_users_per_occurrence,
                        'occurrences', occurrences
                    ) ORDER BY day_of_week
                )
                FROM day_of_week_analysis
            ),
            -- User frequency distribution
            'user_frequency_distribution', CASE 
                WHEN p_is_premium THEN
                    (
                        SELECT json_agg(
                            json_build_object(
                                'frequency_segment', frequency_segment,
                                'consistency_segment', consistency_segment,
                                'user_count', user_count,
                                'avg_interactions', avg_interactions,
                                'avg_active_days', avg_active_days,
                                'avg_interactions_per_day', avg_interactions_per_day
                            )
                        )
                        FROM frequency_distribution
                    )
                ELSE NULL
            END
        ),
        'insights', json_build_object(
            -- Peak activity insights
            'peak_periods', (
                SELECT json_build_object(
                    'peak_day', json_build_object(
                        'day', peak_day,
                        'interactions', peak_day_interactions
                    ),
                    'peak_hour', json_build_object(
                        'hour', peak_hour,
                        'interactions', peak_hour_interactions
                    ),
                    'lowest_activity', json_build_object(
                        'day', lowest_day,
                        'hour', lowest_hour
                    )
                )
                FROM peak_periods
            ),
            -- User behavior insights
            'user_behavior_summary', (
                SELECT json_build_object(
                    'total_users', total_unique_users,
                    'total_interactions', total_interactions,
                    'active_days', total_active_days,
                    'avg_interactions_per_user', ROUND(total_interactions::DECIMAL / NULLIF(total_unique_users, 0), 2),
                    'avg_interactions_per_day', ROUND(total_interactions::DECIMAL / NULLIF(total_active_days, 0), 1),
                    'frequency_distribution', json_build_object(
                        'one_time_users', one_time_users,
                        'occasional_users', occasional_users,
                        'regular_users', regular_users,
                        'frequent_users', frequent_users
                    ),
                    'consistency_distribution', CASE 
                        WHEN p_is_premium THEN
                            json_build_object(
                                'highly_consistent', highly_consistent_users,
                                'moderately_consistent', moderately_consistent_users,
                                'sporadic', sporadic_users
                            )
                        ELSE NULL
                    END
                )
                FROM frequency_insights
            ),
            -- Behavioral recommendations
            'recommendations', CASE 
                WHEN p_is_premium THEN
                (
                    SELECT json_agg(
                        json_build_object(
                            'recommendation_type', recommendation_type,
                            'priority', priority,
                            'category', category,
                            'metric_key', metric_key,
                            'threshold', threshold,
                            'current_value', current_value,
                            'improvement_potential', improvement_potential
                        )
                    )
                    FROM (
                        SELECT 
                            'high_one_time_users' as recommendation_type,
                            'high' as priority,
                            'retention' as category,
                            'one_time_user_rate' as metric_key,
                            0.6 as threshold,
                            ROUND(fi.one_time_users::DECIMAL / fi.total_unique_users, 3) as current_value,
                            'implement_follow_up_campaigns' as improvement_potential
                        FROM frequency_insights fi
                        WHERE fi.one_time_users::DECIMAL / fi.total_unique_users > 0.6
                        
                        UNION ALL
                        
                        SELECT 
                            'strong_frequent_users' as recommendation_type,
                            'medium' as priority,
                            'loyalty' as category,
                            'frequent_user_rate' as metric_key,
                            0.2 as threshold,
                            ROUND(fi.frequent_users::DECIMAL / fi.total_unique_users, 3) as current_value,
                            'implement_loyalty_programs' as improvement_potential
                        FROM frequency_insights fi
                        WHERE fi.frequent_users::DECIMAL / fi.total_unique_users > 0.2
                        
                        UNION ALL
                        
                        SELECT 
                            'business_hours_peak' as recommendation_type,
                            'medium' as priority,
                            'timing_optimization' as category,
                            'peak_hour' as metric_key,
                            9 as threshold,
                            pp.peak_hour as current_value,
                            'optimize_for_professional_use' as improvement_potential
                        FROM peak_periods pp
                        WHERE pp.peak_hour BETWEEN 9 AND 17
                        
                        UNION ALL
                        
                        SELECT 
                            'evening_peak' as recommendation_type,
                            'medium' as priority,
                            'timing_optimization' as category,
                            'peak_hour' as metric_key,
                            18 as threshold,
                            pp.peak_hour as current_value,
                            'focus_on_leisure_marketing' as improvement_potential
                        FROM peak_periods pp
                        WHERE pp.peak_hour BETWEEN 18 AND 22
                        
                        UNION ALL
                        
                        SELECT 
                            'high_sporadic_usage' as recommendation_type,
                            'high' as priority,
                            'engagement_consistency' as category,
                            'sporadic_user_rate' as metric_key,
                            0.5 as threshold,
                            ROUND(fi.sporadic_users::DECIMAL / fi.total_unique_users, 3) as current_value,
                            'improve_content_scheduling' as improvement_potential
                        FROM frequency_insights fi
                        WHERE fi.sporadic_users::DECIMAL / fi.total_unique_users > 0.5
                        
                        UNION ALL
                        
                        SELECT 
                            'low_engagement_consistency' as recommendation_type,
                            'medium' as priority,
                            'user_experience' as category,
                            'consistent_user_rate' as metric_key,
                            0.3 as threshold,
                            ROUND(fi.highly_consistent_users::DECIMAL / fi.total_unique_users, 3) as current_value,
                            'enhance_user_experience' as improvement_potential
                        FROM frequency_insights fi
                        WHERE fi.highly_consistent_users::DECIMAL / fi.total_unique_users < 0.3
                        
                    ) recommendations
                )
                ELSE 
                    NULL
            END
        )
    ) INTO result;
    
    RETURN result;
    
EXCEPTION WHEN OTHERS THEN
    RETURN json_build_object(
        'error', TRUE,
        'message', SQLERRM,
        'organization_id', p_organization_id
    );
END;$$;


--
-- Name: get_behavior_temporal_patterns(uuid, integer, text, uuid[], uuid[], boolean, uuid[], boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_behavior_temporal_patterns(p_organization_id uuid, p_period_days integer, p_timezone text DEFAULT 'UTC'::text, p_tag_ids uuid[] DEFAULT NULL::uuid[], p_touchpoint_ids uuid[] DEFAULT NULL::uuid[], p_is_premium boolean DEFAULT false, p_collection_ids uuid[] DEFAULT NULL::uuid[], p_include_null_collection boolean DEFAULT false) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    start_date TIMESTAMPTZ;
    end_date TIMESTAMPTZ;
    result JSON;
BEGIN
    -- Validate tier restrictions
    IF NOT p_is_premium AND p_period_days != 7 THEN
        RETURN json_build_object('error', TRUE, 'message', 'Free tier limited to 7 days only');
    END IF;
    
    IF NOT p_is_premium AND p_touchpoint_ids IS NOT NULL AND array_length(p_touchpoint_ids, 1) > 1 THEN
        RETURN json_build_object('error', TRUE, 'message', 'Free tier limited to 1 touchpoint only');
    END IF;

    -- Calculate date range in user's timezone
    end_date := CURRENT_TIMESTAMP AT TIME ZONE p_timezone;
    start_date := end_date - (p_period_days || ' days')::INTERVAL;
    
    WITH filtered_visits AS (
        -- Apply hierarchical filtering
        SELECT 
            v.fp,
            v.type,
            v.created_at,
            v.tp_id,
            v.platform,
            v.country,
            tp.name as touchpoint_name,
            -- Extract temporal components in user's timezone
            EXTRACT(hour FROM v.created_at AT TIME ZONE p_timezone) as hour_of_day,
            EXTRACT(dow FROM v.created_at AT TIME ZONE p_timezone) as day_of_week,
            DATE(v.created_at AT TIME ZONE p_timezone) as interaction_date,
            EXTRACT(week FROM v.created_at AT TIME ZONE p_timezone) as week_number
        FROM visits v
        LEFT JOIN touch_points tp ON v.tp_id = tp.id
        WHERE v.organization_id = p_organization_id
            AND v.created_at >= start_date
            AND v.created_at < end_date            
            AND v.fp IS NOT NULL
            AND (
                -- No filtering if no filters specified
                (p_tag_ids IS NULL AND p_touchpoint_ids IS NULL)
                OR 
                -- Apply hierarchical filtering: tags first, then touchpoints
                (
                    (p_tag_ids IS NULL OR v.tp_id IN (
                        SELECT DISTINCT ttl.tp_id 
                        FROM tp_tag_links ttl 
                        WHERE ttl.tag_id = ANY(p_tag_ids)
                    ))
                    AND
                    (p_touchpoint_ids IS NULL OR v.tp_id = ANY(p_touchpoint_ids))
                )
            )
            AND (
                p_collection_ids IS NULL
                OR v.tp_id IN (
                    SELECT tp.id
                    FROM touch_points tp
                    WHERE tp.collection_id = ANY(p_collection_ids)
                       OR (p_include_null_collection AND tp.collection_id IS NULL)
                )
            )
    ),
    base_temporal_data AS (
        -- Single scan with multiple aggregation levels
        SELECT 
            hour_of_day,
            day_of_week,
            week_number,
            tp_id,
            touchpoint_name,
            type,
            platform,
            fp,
            interaction_date,
            GROUPING(hour_of_day) as is_hourly_null,
            GROUPING(day_of_week) as is_daily_null,
            GROUPING(week_number) as is_weekly_null,
            GROUPING(tp_id) as is_touchpoint_null,
            COUNT(*) as interaction_count
        FROM filtered_visits
        GROUP BY GROUPING SETS (
            (hour_of_day, type, platform, interaction_date),     -- For hourly patterns
            (day_of_week, type, platform, interaction_date),     -- For daily patterns  
            (week_number, fp, interaction_date),                 -- For weekly trends
            (tp_id, touchpoint_name, hour_of_day, day_of_week, fp, interaction_date)  -- For touchpoint patterns
        )
    ),
    hourly_patterns AS (
        -- Derive hourly patterns from base data
        SELECT 
            hour_of_day,
            SUM(interaction_count) as total_interactions,
            COUNT(DISTINCT interaction_date) as active_days,
            -- Interaction type breakdown
            SUM(CASE WHEN type = 'LINK' THEN interaction_count ELSE 0 END) as link_interactions,
            SUM(CASE WHEN type = 'QR' THEN interaction_count ELSE 0 END) as qr_interactions,
            SUM(CASE WHEN type = 'NFC' THEN interaction_count ELSE 0 END) as nfc_interactions,
            SUM(CASE WHEN type = 'WIFI' THEN interaction_count ELSE 0 END) as wifi_interactions,
            -- Platform breakdown
            SUM(CASE WHEN platform = 'Mobile' THEN interaction_count ELSE 0 END) as mobile_interactions,
            SUM(CASE WHEN platform = 'Desktop' THEN interaction_count ELSE 0 END) as desktop_interactions,
            -- Calculate unique users separately to avoid grouping issues
            (SELECT COUNT(DISTINCT fp) FROM filtered_visits WHERE EXTRACT(hour FROM created_at AT TIME ZONE p_timezone) = btd.hour_of_day) as unique_users,
            (SELECT COUNT(DISTINCT tp_id) FROM filtered_visits WHERE EXTRACT(hour FROM created_at AT TIME ZONE p_timezone) = btd.hour_of_day) as active_touchpoints
        FROM base_temporal_data btd
        WHERE is_hourly_null = 0 AND hour_of_day IS NOT NULL
        GROUP BY hour_of_day
    ),
    hourly_patterns_with_metrics AS (
        -- Add calculated metrics to hourly patterns
        SELECT 
            *,
            ROUND(total_interactions::DECIMAL / NULLIF(unique_users, 0), 2) as interactions_per_user,
            ROUND(total_interactions::DECIMAL / NULLIF(active_days, 0), 1) as avg_interactions_per_day
        FROM hourly_patterns
    ),
    daily_patterns AS (
        -- Derive daily patterns from base data
        SELECT 
            day_of_week,
            CASE day_of_week
                WHEN 0 THEN 'Sunday'
                WHEN 1 THEN 'Monday'
                WHEN 2 THEN 'Tuesday'
                WHEN 3 THEN 'Wednesday'
                WHEN 4 THEN 'Thursday'
                WHEN 5 THEN 'Friday'
                WHEN 6 THEN 'Saturday'
            END as day_name,
            SUM(interaction_count) as total_interactions,
            COUNT(DISTINCT interaction_date) as occurrences,
            -- Interaction type breakdown
            SUM(CASE WHEN type = 'LINK' THEN interaction_count ELSE 0 END) as link_interactions,
            SUM(CASE WHEN type = 'QR' THEN interaction_count ELSE 0 END) as qr_interactions,
            SUM(CASE WHEN type = 'NFC' THEN interaction_count ELSE 0 END) as nfc_interactions,
            SUM(CASE WHEN type = 'WIFI' THEN interaction_count ELSE 0 END) as wifi_interactions,
            -- Calculate unique users separately
            (SELECT COUNT(DISTINCT fp) FROM filtered_visits WHERE EXTRACT(dow FROM created_at AT TIME ZONE p_timezone) = btd.day_of_week) as unique_users,
            (SELECT COUNT(DISTINCT tp_id) FROM filtered_visits WHERE EXTRACT(dow FROM created_at AT TIME ZONE p_timezone) = btd.day_of_week) as active_touchpoints
        FROM base_temporal_data btd
        WHERE is_daily_null = 0 AND day_of_week IS NOT NULL
        GROUP BY day_of_week
    ),
    daily_patterns_with_metrics AS (
        -- Add calculated metrics to daily patterns
        SELECT 
            *,
            ROUND(total_interactions::DECIMAL / NULLIF(unique_users, 0), 2) as interactions_per_user,
            ROUND(total_interactions::DECIMAL / NULLIF(occurrences, 0), 1) as avg_interactions_per_occurrence
        FROM daily_patterns
    ),
    weekly_trends AS (
        -- Derive weekly trends from base data (Premium feature)
        SELECT 
            week_number,
            SUM(interaction_count) as total_interactions,
            COUNT(DISTINCT fp) as unique_users,
            COUNT(DISTINCT interaction_date) as active_days,
            (SELECT COUNT(DISTINCT tp_id) FROM filtered_visits WHERE EXTRACT(week FROM created_at AT TIME ZONE p_timezone) = btd.week_number) as active_touchpoints
        FROM base_temporal_data btd
        WHERE is_weekly_null = 0 AND week_number IS NOT NULL
        GROUP BY week_number
    ),
    weekly_trends_with_metrics AS (
        -- Add calculated metrics to weekly trends
        SELECT 
            *,
            ROUND(total_interactions::DECIMAL / NULLIF(unique_users, 0), 2) as interactions_per_user,
            ROUND(total_interactions::DECIMAL / NULLIF(active_days, 0), 1) as avg_interactions_per_day
        FROM weekly_trends
        ORDER BY week_number
    ),
    touchpoint_temporal_patterns AS (
        -- Analyze temporal patterns by touchpoint (Premium feature)
        SELECT 
            tp_id,
            touchpoint_name,
            COUNT(DISTINCT hour_of_day) as hours_active,
            COUNT(DISTINCT day_of_week) as days_of_week_active,
            SUM(interaction_count) as total_interactions,
            COUNT(DISTINCT fp) as unique_users,
            COUNT(DISTINCT interaction_date) as active_days,
            -- Peak periods (using mode approximation)
            (array_agg(hour_of_day ORDER BY interaction_count DESC))[1] as peak_hour,
            (array_agg(day_of_week ORDER BY interaction_count DESC))[1] as peak_day_of_week,
            -- Time-based engagement
            ROUND(SUM(interaction_count)::DECIMAL / NULLIF(COUNT(DISTINCT interaction_date), 0), 1) as avg_daily_interactions,
            CASE 
                WHEN COUNT(DISTINCT hour_of_day) >= 20 THEN 'all_day'
                WHEN COUNT(DISTINCT hour_of_day) >= 12 THEN 'extended_hours'
                WHEN COUNT(DISTINCT hour_of_day) >= 6 THEN 'moderate_hours'
                ELSE 'limited_hours'
            END as activity_spread,
            CASE 
                WHEN COUNT(DISTINCT day_of_week) = 7 THEN 'all_week'
                WHEN COUNT(DISTINCT day_of_week) >= 5 THEN 'most_days'
                WHEN COUNT(DISTINCT day_of_week) >= 3 THEN 'some_days'
                ELSE 'few_days'
            END as weekly_consistency
        FROM base_temporal_data btd
        WHERE is_touchpoint_null = 0 AND tp_id IS NOT NULL
        GROUP BY tp_id, touchpoint_name
    ),
    peak_activity_analysis AS (        
        SELECT 
            (SELECT hour_of_day FROM hourly_patterns_with_metrics ORDER BY total_interactions DESC LIMIT 1) as peak_hour,
            (SELECT total_interactions FROM hourly_patterns_with_metrics ORDER BY total_interactions DESC LIMIT 1) as peak_hour_interactions,
            (SELECT day_name FROM daily_patterns_with_metrics ORDER BY total_interactions DESC LIMIT 1) as peak_day,
            (SELECT total_interactions FROM daily_patterns_with_metrics ORDER BY total_interactions DESC LIMIT 1) as peak_day_interactions,
            (SELECT hour_of_day FROM hourly_patterns_with_metrics ORDER BY total_interactions ASC LIMIT 1) as lowest_hour,
            (SELECT total_interactions FROM hourly_patterns_with_metrics ORDER BY total_interactions ASC LIMIT 1) as lowest_hour_interactions,
            (SELECT day_name FROM daily_patterns_with_metrics ORDER BY total_interactions ASC LIMIT 1) as lowest_day,
            (SELECT total_interactions FROM daily_patterns_with_metrics ORDER BY total_interactions ASC LIMIT 1) as lowest_day_interactions
    ),
    temporal_insights AS (
        -- Generate temporal behavior insights from raw data
        SELECT 
            COUNT(DISTINCT fp) as total_users,
            COUNT(*) as total_interactions,
            COUNT(DISTINCT interaction_date) as total_active_days,
            COUNT(DISTINCT tp_id) as total_active_touchpoints,
            -- Temporal distribution metrics
            ROUND(AVG(hour_of_day), 1) as avg_interaction_hour,
            (array_agg(hour_of_day ORDER BY hour_of_day))[COUNT(*)/2] as most_common_hour, -- Median approximation
            (array_agg(day_of_week ORDER BY day_of_week))[COUNT(*)/2] as most_common_day, -- Median approximation
            -- Activity consistency
            COUNT(DISTINCT hour_of_day) as unique_hours_active,
            COUNT(DISTINCT day_of_week) as unique_days_active
        FROM filtered_visits
    ),
    temporal_insights_with_patterns AS (
        -- Add pattern classifications
        SELECT 
            *,
            CASE 
                WHEN most_common_hour BETWEEN 6 AND 8 THEN 'morning_peak'
                WHEN most_common_hour BETWEEN 9 AND 17 THEN 'business_hours'
                WHEN most_common_hour BETWEEN 18 AND 22 THEN 'evening_peak'
                WHEN most_common_hour BETWEEN 23 AND 23 OR most_common_hour BETWEEN 0 AND 5 THEN 'late_night'
                ELSE 'varied'
            END as activity_pattern,
            CASE 
                WHEN most_common_day IN (1,2,3,4,5) THEN 'weekday_focused'
                WHEN most_common_day IN (0,6) THEN 'weekend_focused'
                ELSE 'balanced'
            END as weekly_pattern
        FROM temporal_insights
    ),
    activity_concentration AS (
        -- Calculate activity concentration metrics
        SELECT 
            (SELECT COUNT(*) FROM hourly_patterns_with_metrics WHERE total_interactions >= (SELECT AVG(total_interactions) FROM hourly_patterns_with_metrics)) as above_avg_hours,
            (SELECT COUNT(*) FROM daily_patterns_with_metrics WHERE total_interactions >= (SELECT AVG(total_interactions) FROM daily_patterns_with_metrics)) as above_avg_days
    )
    SELECT json_build_object(
        'period_info', json_build_object(
            'period_days', p_period_days,
            'start_date', start_date,
            'end_date', end_date,
            'timezone', p_timezone,
            'is_premium', p_is_premium,
            'analysis_type', 'temporal_patterns'
        ),
        'filters_applied', json_build_object(
            'has_filters', (p_tag_ids IS NOT NULL OR p_touchpoint_ids IS NOT NULL),
            'tags_count', COALESCE(array_length(p_tag_ids, 1), 0),
            'touchpoints_count', COALESCE(array_length(p_touchpoint_ids, 1), 0)
        ),
        'temporal_analysis', json_build_object(
            -- Hourly activity patterns
            'hourly_patterns', (
                SELECT json_agg(
                    json_build_object(
                        'hour', hour_of_day,
                        'total_interactions', total_interactions,
                        'unique_users', unique_users,
                        'interactions_per_user', interactions_per_user,
                        'avg_interactions_per_day', avg_interactions_per_day,
                        'active_touchpoints', active_touchpoints,
                        'interaction_breakdown', json_build_object(
                            'link_interactions', link_interactions,
                            'qr_interactions', qr_interactions,
                            'nfc_interactions', nfc_interactions,
                            'wifi_interactions', wifi_interactions
                        ),
                        'platform_breakdown', json_build_object(
                            'mobile_interactions', mobile_interactions,
                            'desktop_interactions', desktop_interactions
                        )
                    )
                )
                FROM (
                    SELECT * FROM hourly_patterns_with_metrics ORDER BY hour_of_day
                ) ordered_hourly
            ),
            -- Daily patterns
            'daily_patterns', (
                SELECT json_agg(
                    json_build_object(
                        'day_of_week', day_of_week,
                        'day_name', day_name,
                        'total_interactions', total_interactions,
                        'unique_users', unique_users,
                        'interactions_per_user', interactions_per_user,
                        'avg_interactions_per_occurrence', avg_interactions_per_occurrence,
                        'occurrences', occurrences,
                        'active_touchpoints', active_touchpoints,
                        'interaction_breakdown', json_build_object(
                            'link_interactions', link_interactions,
                            'qr_interactions', qr_interactions,
                            'nfc_interactions', nfc_interactions,
                            'wifi_interactions', wifi_interactions
                        )
                    )
                )
                FROM (
                    SELECT * FROM daily_patterns_with_metrics ORDER BY day_of_week
                ) ordered_daily
            ),
            -- Weekly trends (Premium feature)
            'weekly_trends', CASE 
                WHEN p_is_premium THEN
                    (
                        SELECT json_agg(
                            json_build_object(
                                'week_number', week_number,
                                'total_interactions', total_interactions,
                                'unique_users', unique_users,
                                'interactions_per_user', interactions_per_user,
                                'avg_interactions_per_day', avg_interactions_per_day,
                                'active_touchpoints', active_touchpoints,
                                'active_days', active_days
                            )
                        )
                        FROM weekly_trends_with_metrics
                    )
                ELSE NULL
            END,
            -- Touchpoint temporal patterns (Premium feature)
            'touchpoint_temporal_patterns', CASE 
                WHEN p_is_premium THEN
                    (
                        SELECT json_agg(
                            json_build_object(
                                'touchpoint_name', touchpoint_name,
                                'peak_hour', peak_hour,
                                'peak_day_of_week', peak_day_of_week,
                                'total_interactions', total_interactions,
                                'unique_users', unique_users,
                                'avg_daily_interactions', avg_daily_interactions,
                                'activity_spread', activity_spread,
                                'weekly_consistency', weekly_consistency,
                                'hours_active', hours_active,
                                'days_of_week_active', days_of_week_active
                            )
                        )
                        FROM (
                            SELECT * FROM touchpoint_temporal_patterns ORDER BY total_interactions DESC
                        ) ordered_touchpoints
                    )
                ELSE NULL
            END
        ),
        'insights', json_build_object(
            -- Peak activity analysis
            'peak_activity', (
                SELECT json_build_object(
                    'peak_periods', json_build_object(
                        'peak_hour', json_build_object(
                            'hour', peak_hour,
                            'interactions', peak_hour_interactions
                        ),
                        'peak_day', json_build_object(
                            'day', peak_day,
                            'interactions', peak_day_interactions
                        )
                    ),
                    'low_activity_periods', json_build_object(
                        'lowest_hour', json_build_object(
                            'hour', lowest_hour,
                            'interactions', lowest_hour_interactions
                        ),
                        'lowest_day', json_build_object(
                            'day', lowest_day,
                            'interactions', lowest_day_interactions
                        )
                    ),
                    'activity_concentration', json_build_object(
                        'above_avg_hours', ac.above_avg_hours,
                        'above_avg_days', ac.above_avg_days,
                        'concentration_score', ROUND((ac.above_avg_hours::DECIMAL / 24 + ac.above_avg_days::DECIMAL / 7) / 2 * 100, 1)
                    )
                )
                FROM peak_activity_analysis paa
                CROSS JOIN activity_concentration ac
            ),
            -- Temporal behavior summary
            'temporal_summary', (
                SELECT json_build_object(
                    'total_users', total_users,
                    'total_interactions', total_interactions,
                    'total_active_days', total_active_days,
                    'avg_interaction_hour', avg_interaction_hour,
                    'most_common_hour', most_common_hour,
                    'most_common_day', most_common_day,
                    'unique_hours_active', unique_hours_active,
                    'unique_days_active', unique_days_active,
                    'activity_pattern', activity_pattern,
                    'weekly_pattern', weekly_pattern,
                    'temporal_diversity', json_build_object(
                        'hour_spread_percentage', ROUND(unique_hours_active::DECIMAL / 24 * 100, 1),
                        'day_spread_percentage', ROUND(unique_days_active::DECIMAL / 7 * 100, 1)
                    )
                )
                FROM temporal_insights_with_patterns
            ),
            -- Timing optimization recommendations
            'recommendations', CASE 
                WHEN p_is_premium THEN
                (
                    SELECT json_agg(
                        json_build_object(
                            'recommendation_type', recommendation_type,
                            'priority', priority,
                            'category', category,
                            'metric_key', metric_key,
                            'threshold', threshold,
                            'current_value', current_value,
                            'improvement_potential', improvement_potential
                        )
                    )
                    FROM (
                        SELECT 
                            'optimize_peak_hours' as recommendation_type,
                            'high' as priority,
                            'timing_optimization' as category,
                            'peak_hour' as metric_key,
                            null::TEXT as threshold,
                            paa.peak_hour::TEXT as current_value,
                            'schedule_campaigns_during_peak' as improvement_potential
                        FROM peak_activity_analysis paa
                        
                        UNION ALL
                        
                        SELECT 
                            'leverage_peak_day' as recommendation_type,
                            'high' as priority,
                            'weekly_optimization' as category,
                            'peak_day' as metric_key,
                            null::TEXT as threshold,
                            paa.peak_day::TEXT as current_value,   
                            'focus_weekly_campaigns' as improvement_potential
                        FROM peak_activity_analysis paa
                        
                        UNION ALL
                        
                        SELECT 
                            'improve_low_activity_periods' as recommendation_type,
                            'medium' as priority,
                            'coverage_optimization' as category,
                            'activity_concentration' as metric_key,
                            '60.0'::TEXT as threshold,
                            ROUND(ac.above_avg_hours::DECIMAL / 24 * 100, 1)::TEXT as current_value,  
                            'increase_off_peak_engagement' as improvement_potential
                        FROM activity_concentration ac
                        WHERE (ac.above_avg_hours::DECIMAL / 24 * 100) < 60
                        
                        UNION ALL
                        
                        SELECT 
                            'expand_temporal_reach' as recommendation_type,
                            'low' as priority,
                            'reach_optimization' as category,
                            'temporal_diversity' as metric_key,
                            '80.0'::TEXT as threshold,
                            ROUND(ti.unique_hours_active::DECIMAL / 24 * 100, 1)::TEXT as current_value, 
                            'diversify_interaction_times' as improvement_potential
                        FROM temporal_insights_with_patterns ti
                        WHERE (ti.unique_hours_active::DECIMAL / 24 * 100) < 80
                        
                    ) recommendations
                )
                ELSE 
                    NULL
            END
        )
    ) INTO result;
    
    RETURN result;
    
EXCEPTION WHEN OTHERS THEN
    RETURN json_build_object(
        'error', TRUE,
        'message', SQLERRM,
        'organization_id', p_organization_id
    );
END;
$$;


--
-- Name: get_behavior_temporal_patterns_old(uuid, integer, text, uuid[], uuid[], boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_behavior_temporal_patterns_old(p_organization_id uuid, p_period_days integer, p_timezone text DEFAULT 'UTC'::text, p_tag_ids uuid[] DEFAULT NULL::uuid[], p_touchpoint_ids uuid[] DEFAULT NULL::uuid[], p_is_premium boolean DEFAULT false) RETURNS json
    LANGUAGE plpgsql
    AS $$DECLARE
    start_date TIMESTAMPTZ;
    end_date TIMESTAMPTZ;
    result JSON;
BEGIN
    -- Validate tier restrictions
    IF NOT p_is_premium AND p_period_days != 7 THEN
        RETURN json_build_object('error', TRUE, 'message', 'Free tier limited to 7 days only');
    END IF;
    
    IF NOT p_is_premium AND p_touchpoint_ids IS NOT NULL AND array_length(p_touchpoint_ids, 1) > 1 THEN
        RETURN json_build_object('error', TRUE, 'message', 'Free tier limited to 1 touchpoint only');
    END IF;

    -- Calculate date range in user's timezone
    end_date := CURRENT_TIMESTAMP AT TIME ZONE p_timezone;
    start_date := end_date - (p_period_days || ' days')::INTERVAL;
    
    WITH filtered_visits AS (
        -- Apply hierarchical filtering
        SELECT 
            v.fp,
            v.type,
            v.created_at,
            v.tp_id,
            v.platform,
            v.country,
            tp.name as touchpoint_name,
            -- Extract temporal components in user's timezone
            EXTRACT(hour FROM v.created_at AT TIME ZONE p_timezone) as hour_of_day,
            EXTRACT(dow FROM v.created_at AT TIME ZONE p_timezone) as day_of_week,
            DATE(v.created_at AT TIME ZONE p_timezone) as interaction_date,
            EXTRACT(week FROM v.created_at AT TIME ZONE p_timezone) as week_number
        FROM visits v
        LEFT JOIN touch_points tp ON v.tp_id = tp.id
        WHERE v.organization_id = p_organization_id
            AND v.created_at >= start_date
            AND v.created_at < end_date            
            AND v.fp IS NOT NULL
            AND (
                -- No filtering if no filters specified
                (p_tag_ids IS NULL AND p_touchpoint_ids IS NULL)
                OR 
                -- Apply hierarchical filtering: tags first, then touchpoints
                (
                    (p_tag_ids IS NULL OR v.tp_id IN (
                        SELECT DISTINCT ttl.tp_id 
                        FROM tp_tag_links ttl 
                        WHERE ttl.tag_id = ANY(p_tag_ids)
                    ))
                    AND
                    (p_touchpoint_ids IS NULL OR v.tp_id = ANY(p_touchpoint_ids))
                )
            )
    ),
    base_temporal_data AS (
        -- Single scan with multiple aggregation levels
        SELECT 
            hour_of_day,
            day_of_week,
            week_number,
            tp_id,
            touchpoint_name,
            type,
            platform,
            fp,
            interaction_date,
            GROUPING(hour_of_day) as is_hourly_null,
            GROUPING(day_of_week) as is_daily_null,
            GROUPING(week_number) as is_weekly_null,
            GROUPING(tp_id) as is_touchpoint_null,
            COUNT(*) as interaction_count
        FROM filtered_visits
        GROUP BY GROUPING SETS (
            (hour_of_day, type, platform, interaction_date),     -- For hourly patterns
            (day_of_week, type, platform, interaction_date),     -- For daily patterns  
            (week_number, fp, interaction_date),                 -- For weekly trends
            (tp_id, touchpoint_name, hour_of_day, day_of_week, fp, interaction_date)  -- For touchpoint patterns
        )
    ),
    hourly_patterns AS (
        -- Derive hourly patterns from base data
        SELECT 
            hour_of_day,
            SUM(interaction_count) as total_interactions,
            COUNT(DISTINCT interaction_date) as active_days,
            -- Interaction type breakdown
            SUM(CASE WHEN type = 'LINK' THEN interaction_count ELSE 0 END) as link_interactions,
            SUM(CASE WHEN type = 'QR' THEN interaction_count ELSE 0 END) as qr_interactions,
            SUM(CASE WHEN type = 'NFC' THEN interaction_count ELSE 0 END) as nfc_interactions,
            SUM(CASE WHEN type = 'WIFI' THEN interaction_count ELSE 0 END) as wifi_interactions,
            -- Platform breakdown
            SUM(CASE WHEN platform = 'Mobile' THEN interaction_count ELSE 0 END) as mobile_interactions,
            SUM(CASE WHEN platform = 'Desktop' THEN interaction_count ELSE 0 END) as desktop_interactions,
            -- Calculate unique users separately to avoid grouping issues
            (SELECT COUNT(DISTINCT fp) FROM filtered_visits WHERE EXTRACT(hour FROM created_at AT TIME ZONE p_timezone) = btd.hour_of_day) as unique_users,
            (SELECT COUNT(DISTINCT tp_id) FROM filtered_visits WHERE EXTRACT(hour FROM created_at AT TIME ZONE p_timezone) = btd.hour_of_day) as active_touchpoints
        FROM base_temporal_data btd
        WHERE is_hourly_null = 0 AND hour_of_day IS NOT NULL
        GROUP BY hour_of_day
    ),
    hourly_patterns_with_metrics AS (
        -- Add calculated metrics to hourly patterns
        SELECT 
            *,
            ROUND(total_interactions::DECIMAL / NULLIF(unique_users, 0), 2) as interactions_per_user,
            ROUND(total_interactions::DECIMAL / NULLIF(active_days, 0), 1) as avg_interactions_per_day
        FROM hourly_patterns
    ),
    daily_patterns AS (
        -- Derive daily patterns from base data
        SELECT 
            day_of_week,
            CASE day_of_week
                WHEN 0 THEN 'Sunday'
                WHEN 1 THEN 'Monday'
                WHEN 2 THEN 'Tuesday'
                WHEN 3 THEN 'Wednesday'
                WHEN 4 THEN 'Thursday'
                WHEN 5 THEN 'Friday'
                WHEN 6 THEN 'Saturday'
            END as day_name,
            SUM(interaction_count) as total_interactions,
            COUNT(DISTINCT interaction_date) as occurrences,
            -- Interaction type breakdown
            SUM(CASE WHEN type = 'LINK' THEN interaction_count ELSE 0 END) as link_interactions,
            SUM(CASE WHEN type = 'QR' THEN interaction_count ELSE 0 END) as qr_interactions,
            SUM(CASE WHEN type = 'NFC' THEN interaction_count ELSE 0 END) as nfc_interactions,
            SUM(CASE WHEN type = 'WIFI' THEN interaction_count ELSE 0 END) as wifi_interactions,
            -- Calculate unique users separately
            (SELECT COUNT(DISTINCT fp) FROM filtered_visits WHERE EXTRACT(dow FROM created_at AT TIME ZONE p_timezone) = btd.day_of_week) as unique_users,
            (SELECT COUNT(DISTINCT tp_id) FROM filtered_visits WHERE EXTRACT(dow FROM created_at AT TIME ZONE p_timezone) = btd.day_of_week) as active_touchpoints
        FROM base_temporal_data btd
        WHERE is_daily_null = 0 AND day_of_week IS NOT NULL
        GROUP BY day_of_week
    ),
    daily_patterns_with_metrics AS (
        -- Add calculated metrics to daily patterns
        SELECT 
            *,
            ROUND(total_interactions::DECIMAL / NULLIF(unique_users, 0), 2) as interactions_per_user,
            ROUND(total_interactions::DECIMAL / NULLIF(occurrences, 0), 1) as avg_interactions_per_occurrence
        FROM daily_patterns
    ),
    weekly_trends AS (
        -- Derive weekly trends from base data (Premium feature)
        SELECT 
            week_number,
            SUM(interaction_count) as total_interactions,
            COUNT(DISTINCT fp) as unique_users,
            COUNT(DISTINCT interaction_date) as active_days,
            (SELECT COUNT(DISTINCT tp_id) FROM filtered_visits WHERE EXTRACT(week FROM created_at AT TIME ZONE p_timezone) = btd.week_number) as active_touchpoints
        FROM base_temporal_data btd
        WHERE is_weekly_null = 0 AND week_number IS NOT NULL
        GROUP BY week_number
    ),
    weekly_trends_with_metrics AS (
        -- Add calculated metrics to weekly trends
        SELECT 
            *,
            ROUND(total_interactions::DECIMAL / NULLIF(unique_users, 0), 2) as interactions_per_user,
            ROUND(total_interactions::DECIMAL / NULLIF(active_days, 0), 1) as avg_interactions_per_day
        FROM weekly_trends
        ORDER BY week_number
    ),
    touchpoint_temporal_patterns AS (
        -- Analyze temporal patterns by touchpoint (Premium feature)
        SELECT 
            tp_id,
            touchpoint_name,
            COUNT(DISTINCT hour_of_day) as hours_active,
            COUNT(DISTINCT day_of_week) as days_of_week_active,
            SUM(interaction_count) as total_interactions,
            COUNT(DISTINCT fp) as unique_users,
            COUNT(DISTINCT interaction_date) as active_days,
            -- Peak periods (using mode approximation)
            (array_agg(hour_of_day ORDER BY interaction_count DESC))[1] as peak_hour,
            (array_agg(day_of_week ORDER BY interaction_count DESC))[1] as peak_day_of_week,
            -- Time-based engagement
            ROUND(SUM(interaction_count)::DECIMAL / NULLIF(COUNT(DISTINCT interaction_date), 0), 1) as avg_daily_interactions,
            CASE 
                WHEN COUNT(DISTINCT hour_of_day) >= 20 THEN 'all_day'
                WHEN COUNT(DISTINCT hour_of_day) >= 12 THEN 'extended_hours'
                WHEN COUNT(DISTINCT hour_of_day) >= 6 THEN 'moderate_hours'
                ELSE 'limited_hours'
            END as activity_spread,
            CASE 
                WHEN COUNT(DISTINCT day_of_week) = 7 THEN 'all_week'
                WHEN COUNT(DISTINCT day_of_week) >= 5 THEN 'most_days'
                WHEN COUNT(DISTINCT day_of_week) >= 3 THEN 'some_days'
                ELSE 'few_days'
            END as weekly_consistency
        FROM base_temporal_data btd
        WHERE is_touchpoint_null = 0 AND tp_id IS NOT NULL
        GROUP BY tp_id, touchpoint_name
    ),
    peak_activity_analysis AS (        
        SELECT 
            (SELECT hour_of_day FROM hourly_patterns_with_metrics ORDER BY total_interactions DESC LIMIT 1) as peak_hour,
            (SELECT total_interactions FROM hourly_patterns_with_metrics ORDER BY total_interactions DESC LIMIT 1) as peak_hour_interactions,
            (SELECT day_name FROM daily_patterns_with_metrics ORDER BY total_interactions DESC LIMIT 1) as peak_day,
            (SELECT total_interactions FROM daily_patterns_with_metrics ORDER BY total_interactions DESC LIMIT 1) as peak_day_interactions,
            (SELECT hour_of_day FROM hourly_patterns_with_metrics ORDER BY total_interactions ASC LIMIT 1) as lowest_hour,
            (SELECT total_interactions FROM hourly_patterns_with_metrics ORDER BY total_interactions ASC LIMIT 1) as lowest_hour_interactions,
            (SELECT day_name FROM daily_patterns_with_metrics ORDER BY total_interactions ASC LIMIT 1) as lowest_day,
            (SELECT total_interactions FROM daily_patterns_with_metrics ORDER BY total_interactions ASC LIMIT 1) as lowest_day_interactions
    ),
    temporal_insights AS (
        -- Generate temporal behavior insights from raw data
        SELECT 
            COUNT(DISTINCT fp) as total_users,
            COUNT(*) as total_interactions,
            COUNT(DISTINCT interaction_date) as total_active_days,
            COUNT(DISTINCT tp_id) as total_active_touchpoints,
            -- Temporal distribution metrics
            ROUND(AVG(hour_of_day), 1) as avg_interaction_hour,
            (array_agg(hour_of_day ORDER BY hour_of_day))[COUNT(*)/2] as most_common_hour, -- Median approximation
            (array_agg(day_of_week ORDER BY day_of_week))[COUNT(*)/2] as most_common_day, -- Median approximation
            -- Activity consistency
            COUNT(DISTINCT hour_of_day) as unique_hours_active,
            COUNT(DISTINCT day_of_week) as unique_days_active
        FROM filtered_visits
    ),
    temporal_insights_with_patterns AS (
        -- Add pattern classifications
        SELECT 
            *,
            CASE 
                WHEN most_common_hour BETWEEN 6 AND 8 THEN 'morning_peak'
                WHEN most_common_hour BETWEEN 9 AND 17 THEN 'business_hours'
                WHEN most_common_hour BETWEEN 18 AND 22 THEN 'evening_peak'
                WHEN most_common_hour BETWEEN 23 AND 23 OR most_common_hour BETWEEN 0 AND 5 THEN 'late_night'
                ELSE 'varied'
            END as activity_pattern,
            CASE 
                WHEN most_common_day IN (1,2,3,4,5) THEN 'weekday_focused'
                WHEN most_common_day IN (0,6) THEN 'weekend_focused'
                ELSE 'balanced'
            END as weekly_pattern
        FROM temporal_insights
    ),
    activity_concentration AS (
        -- Calculate activity concentration metrics
        SELECT 
            (SELECT COUNT(*) FROM hourly_patterns_with_metrics WHERE total_interactions >= (SELECT AVG(total_interactions) FROM hourly_patterns_with_metrics)) as above_avg_hours,
            (SELECT COUNT(*) FROM daily_patterns_with_metrics WHERE total_interactions >= (SELECT AVG(total_interactions) FROM daily_patterns_with_metrics)) as above_avg_days
    )
    SELECT json_build_object(
        'period_info', json_build_object(
            'period_days', p_period_days,
            'start_date', start_date,
            'end_date', end_date,
            'timezone', p_timezone,
            'is_premium', p_is_premium,
            'analysis_type', 'temporal_patterns'
        ),
        'filters_applied', json_build_object(
            'has_filters', (p_tag_ids IS NOT NULL OR p_touchpoint_ids IS NOT NULL),
            'tags_count', COALESCE(array_length(p_tag_ids, 1), 0),
            'touchpoints_count', COALESCE(array_length(p_touchpoint_ids, 1), 0)
        ),
        'temporal_analysis', json_build_object(
            -- Hourly activity patterns
            'hourly_patterns', (
                SELECT json_agg(
                    json_build_object(
                        'hour', hour_of_day,
                        'total_interactions', total_interactions,
                        'unique_users', unique_users,
                        'interactions_per_user', interactions_per_user,
                        'avg_interactions_per_day', avg_interactions_per_day,
                        'active_touchpoints', active_touchpoints,
                        'interaction_breakdown', json_build_object(
                            'link_interactions', link_interactions,
                            'qr_interactions', qr_interactions,
                            'nfc_interactions', nfc_interactions,
                            'wifi_interactions', wifi_interactions
                        ),
                        'platform_breakdown', json_build_object(
                            'mobile_interactions', mobile_interactions,
                            'desktop_interactions', desktop_interactions
                        )
                    )
                )
                FROM (
                    SELECT * FROM hourly_patterns_with_metrics ORDER BY hour_of_day
                ) ordered_hourly
            ),
            -- Daily patterns
            'daily_patterns', (
                SELECT json_agg(
                    json_build_object(
                        'day_of_week', day_of_week,
                        'day_name', day_name,
                        'total_interactions', total_interactions,
                        'unique_users', unique_users,
                        'interactions_per_user', interactions_per_user,
                        'avg_interactions_per_occurrence', avg_interactions_per_occurrence,
                        'occurrences', occurrences,
                        'active_touchpoints', active_touchpoints,
                        'interaction_breakdown', json_build_object(
                            'link_interactions', link_interactions,
                            'qr_interactions', qr_interactions,
                            'nfc_interactions', nfc_interactions,
                            'wifi_interactions', wifi_interactions
                        )
                    )
                )
                FROM (
                    SELECT * FROM daily_patterns_with_metrics ORDER BY day_of_week
                ) ordered_daily
            ),
            -- Weekly trends (Premium feature)
            'weekly_trends', CASE 
                WHEN p_is_premium THEN
                    (
                        SELECT json_agg(
                            json_build_object(
                                'week_number', week_number,
                                'total_interactions', total_interactions,
                                'unique_users', unique_users,
                                'interactions_per_user', interactions_per_user,
                                'avg_interactions_per_day', avg_interactions_per_day,
                                'active_touchpoints', active_touchpoints,
                                'active_days', active_days
                            )
                        )
                        FROM weekly_trends_with_metrics
                    )
                ELSE NULL
            END,
            -- Touchpoint temporal patterns (Premium feature)
            'touchpoint_temporal_patterns', CASE 
                WHEN p_is_premium THEN
                    (
                        SELECT json_agg(
                            json_build_object(
                                'touchpoint_name', touchpoint_name,
                                'peak_hour', peak_hour,
                                'peak_day_of_week', peak_day_of_week,
                                'total_interactions', total_interactions,
                                'unique_users', unique_users,
                                'avg_daily_interactions', avg_daily_interactions,
                                'activity_spread', activity_spread,
                                'weekly_consistency', weekly_consistency,
                                'hours_active', hours_active,
                                'days_of_week_active', days_of_week_active
                            )
                        )
                        FROM (
                            SELECT * FROM touchpoint_temporal_patterns ORDER BY total_interactions DESC
                        ) ordered_touchpoints
                    )
                ELSE NULL
            END
        ),
        'insights', json_build_object(
            -- Peak activity analysis
            'peak_activity', (
                SELECT json_build_object(
                    'peak_periods', json_build_object(
                        'peak_hour', json_build_object(
                            'hour', peak_hour,
                            'interactions', peak_hour_interactions
                        ),
                        'peak_day', json_build_object(
                            'day', peak_day,
                            'interactions', peak_day_interactions
                        )
                    ),
                    'low_activity_periods', json_build_object(
                        'lowest_hour', json_build_object(
                            'hour', lowest_hour,
                            'interactions', lowest_hour_interactions
                        ),
                        'lowest_day', json_build_object(
                            'day', lowest_day,
                            'interactions', lowest_day_interactions
                        )
                    ),
                    'activity_concentration', json_build_object(
                        'above_avg_hours', ac.above_avg_hours,
                        'above_avg_days', ac.above_avg_days,
                        'concentration_score', ROUND((ac.above_avg_hours::DECIMAL / 24 + ac.above_avg_days::DECIMAL / 7) / 2 * 100, 1)
                    )
                )
                FROM peak_activity_analysis paa
                CROSS JOIN activity_concentration ac
            ),
            -- Temporal behavior summary
            'temporal_summary', (
                SELECT json_build_object(
                    'total_users', total_users,
                    'total_interactions', total_interactions,
                    'total_active_days', total_active_days,
                    'avg_interaction_hour', avg_interaction_hour,
                    'most_common_hour', most_common_hour,
                    'most_common_day', most_common_day,
                    'unique_hours_active', unique_hours_active,
                    'unique_days_active', unique_days_active,
                    'activity_pattern', activity_pattern,
                    'weekly_pattern', weekly_pattern,
                    'temporal_diversity', json_build_object(
                        'hour_spread_percentage', ROUND(unique_hours_active::DECIMAL / 24 * 100, 1),
                        'day_spread_percentage', ROUND(unique_days_active::DECIMAL / 7 * 100, 1)
                    )
                )
                FROM temporal_insights_with_patterns
            ),
            -- Timing optimization recommendations
            'recommendations', CASE 
                WHEN p_is_premium THEN
                (
                    SELECT json_agg(
                        json_build_object(
                            'recommendation_type', recommendation_type,
                            'priority', priority,
                            'category', category,
                            'metric_key', metric_key,
                            'threshold', threshold,
                            'current_value', current_value,
                            'improvement_potential', improvement_potential
                        )
                    )
                    FROM (
                        SELECT 
                            'optimize_peak_hours' as recommendation_type,
                            'high' as priority,
                            'timing_optimization' as category,
                            'peak_hour' as metric_key,
                            null::TEXT as threshold,
                            paa.peak_hour::TEXT as current_value,
                            'schedule_campaigns_during_peak' as improvement_potential
                        FROM peak_activity_analysis paa
                        
                        UNION ALL
                        
                        SELECT 
                            'leverage_peak_day' as recommendation_type,
                            'high' as priority,
                            'weekly_optimization' as category,
                            'peak_day' as metric_key,
                            null::TEXT as threshold,
                            paa.peak_day::TEXT as current_value,   
                            'focus_weekly_campaigns' as improvement_potential
                        FROM peak_activity_analysis paa
                        
                        UNION ALL
                        
                        SELECT 
                            'improve_low_activity_periods' as recommendation_type,
                            'medium' as priority,
                            'coverage_optimization' as category,
                            'activity_concentration' as metric_key,
                            '60.0'::TEXT as threshold,
                            ROUND(ac.above_avg_hours::DECIMAL / 24 * 100, 1)::TEXT as current_value,  
                            'increase_off_peak_engagement' as improvement_potential
                        FROM activity_concentration ac
                        WHERE (ac.above_avg_hours::DECIMAL / 24 * 100) < 60
                        
                        UNION ALL
                        
                        SELECT 
                            'expand_temporal_reach' as recommendation_type,
                            'low' as priority,
                            'reach_optimization' as category,
                            'temporal_diversity' as metric_key,
                            '80.0'::TEXT as threshold,
                            ROUND(ti.unique_hours_active::DECIMAL / 24 * 100, 1)::TEXT as current_value, 
                            'diversify_interaction_times' as improvement_potential
                        FROM temporal_insights_with_patterns ti
                        WHERE (ti.unique_hours_active::DECIMAL / 24 * 100) < 80
                        
                    ) recommendations
                )
                ELSE 
                    NULL
            END
        )
    ) INTO result;
    
    RETURN result;
    
EXCEPTION WHEN OTHERS THEN
    RETURN json_build_object(
        'error', TRUE,
        'message', SQLERRM,
        'organization_id', p_organization_id
    );
END;$$;


--
-- Name: get_behavior_user_journeys(uuid, integer, text, uuid[], uuid[], boolean, uuid[], boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_behavior_user_journeys(p_organization_id uuid, p_period_days integer, p_timezone text DEFAULT 'UTC'::text, p_tag_ids uuid[] DEFAULT NULL::uuid[], p_touchpoint_ids uuid[] DEFAULT NULL::uuid[], p_is_premium boolean DEFAULT false, p_collection_ids uuid[] DEFAULT NULL::uuid[], p_include_null_collection boolean DEFAULT false) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    start_date TIMESTAMPTZ;
    end_date TIMESTAMPTZ;
    result JSON;
BEGIN
    -- Validate tier restrictions
    IF NOT p_is_premium AND p_period_days != 7 THEN
        RETURN json_build_object('error', TRUE, 'message', 'Free tier limited to 7 days only');
    END IF;
    
    IF NOT p_is_premium AND p_touchpoint_ids IS NOT NULL AND array_length(p_touchpoint_ids, 1) > 1 THEN
        RETURN json_build_object('error', TRUE, 'message', 'Free tier limited to 1 touchpoint only');
    END IF;

    -- Calculate date range in user's timezone
    end_date := CURRENT_TIMESTAMP AT TIME ZONE p_timezone;
    start_date := end_date - (p_period_days || ' days')::INTERVAL;
    
    WITH filtered_visits AS (
        -- Apply hierarchical filtering
        SELECT 
            v.fp,
            v.type,
            v.created_at,
            v.tp_id,
            v.platform,
            v.country,
            tp.name as touchpoint_name
        FROM visits v
        LEFT JOIN touch_points tp ON v.tp_id = tp.id
        WHERE v.organization_id = p_organization_id
            AND v.created_at >= start_date
            AND v.created_at < end_date            
            AND v.fp IS NOT NULL
            AND (
                -- No filtering if no filters specified
                (p_tag_ids IS NULL AND p_touchpoint_ids IS NULL)
                OR 
                -- Apply hierarchical filtering: tags first, then touchpoints
                (
                    (p_tag_ids IS NULL OR v.tp_id IN (
                        SELECT DISTINCT ttl.tp_id 
                        FROM tp_tag_links ttl 
                        WHERE ttl.tag_id = ANY(p_tag_ids)
                    ))
                    AND
                    (p_touchpoint_ids IS NULL OR v.tp_id = ANY(p_touchpoint_ids))
                )
            )
            AND (
                p_collection_ids IS NULL
                OR v.tp_id IN (
                    SELECT tp.id
                    FROM touch_points tp
                    WHERE tp.collection_id = ANY(p_collection_ids)
                       OR (p_include_null_collection AND tp.collection_id IS NULL)
                )
            )
    ),
    user_journeys AS (
        -- Analyze individual user journeys
        SELECT 
            fp,
            COUNT(*) as total_interactions,
            COUNT(DISTINCT tp_id) as unique_touchpoints_visited,
            COUNT(DISTINCT type) as interaction_types_used,
            COUNT(DISTINCT DATE(created_at AT TIME ZONE p_timezone)) as active_days,
            MIN(created_at) as journey_start,
            MAX(created_at) as journey_end,
            EXTRACT(EPOCH FROM (MAX(created_at) - MIN(created_at))) / 60 as journey_duration_minutes,
            -- Get first touchpoint using MIN(created_at)
            (array_agg(tp_id ORDER BY created_at))[1] as first_touchpoint_id,
            (array_agg(touchpoint_name ORDER BY created_at))[1] as first_touchpoint_name,
            (array_agg(type ORDER BY created_at))[1] as first_interaction_type,
            -- Get last touchpoint using MAX(created_at)
            (array_agg(tp_id ORDER BY created_at DESC))[1] as last_touchpoint_id,
            (array_agg(touchpoint_name ORDER BY created_at DESC))[1] as last_touchpoint_name,
            (array_agg(type ORDER BY created_at DESC))[1] as last_interaction_type,
            -- Journey classification
            CASE 
                WHEN COUNT(DISTINCT tp_id) = 1 THEN 'single_touchpoint'
                WHEN COUNT(DISTINCT tp_id) = 2 THEN 'two_touchpoint'
                WHEN COUNT(DISTINCT tp_id) >= 3 THEN 'multi_touchpoint'
            END as journey_complexity,
            -- Interaction patterns
            CASE 
                WHEN COUNT(DISTINCT type) = 1 THEN 'single_method'
                WHEN COUNT(DISTINCT type) >= 2 THEN 'multi_method'
            END as interaction_diversity
        FROM filtered_visits
        GROUP BY fp
    ),
    journey_patterns AS (
        -- Analyze journey patterns and flows
        SELECT 
            journey_complexity,
            interaction_diversity,
            COUNT(*) as users_count,
            ROUND(AVG(total_interactions), 2) as avg_interactions_per_journey,
            ROUND(AVG(unique_touchpoints_visited), 2) as avg_touchpoints_per_journey,
            ROUND(AVG(journey_duration_minutes), 1) as avg_journey_duration_minutes,
            ROUND(AVG(active_days), 2) as avg_active_days
        FROM user_journeys
        GROUP BY journey_complexity, interaction_diversity
    ),
    journey_patterns_with_percentages AS (
        -- Calculate percentages using window function
        SELECT 
            *,
            ROUND(users_count::DECIMAL / SUM(users_count) OVER() * 100, 1) as pattern_percentage
        FROM journey_patterns
    ),
    touchpoint_transitions AS (
        -- Analyze touchpoint-to-touchpoint flows (Premium feature)
        SELECT 
            lag_tp_name as from_touchpoint,
            current_tp_name as to_touchpoint,
            lag_type as from_interaction_type,
            current_type as to_interaction_type,
            COUNT(*) as transition_count,
            COUNT(DISTINCT fp) as unique_users,
            ROUND(AVG(time_between_minutes), 1) as avg_time_between_minutes
        FROM (
            SELECT 
                fv.fp,
                fv.touchpoint_name as current_tp_name,
                fv.type as current_type,
                LAG(fv.touchpoint_name) OVER (PARTITION BY fv.fp ORDER BY fv.created_at) as lag_tp_name,
                LAG(fv.type) OVER (PARTITION BY fv.fp ORDER BY fv.created_at) as lag_type,
                EXTRACT(EPOCH FROM (fv.created_at - LAG(fv.created_at) OVER (PARTITION BY fv.fp ORDER BY fv.created_at))) / 60 as time_between_minutes
            FROM filtered_visits fv
        ) transitions
        WHERE lag_tp_name IS NOT NULL
            AND lag_tp_name != current_tp_name -- Only cross-touchpoint transitions
        GROUP BY lag_tp_name, current_tp_name, lag_type, current_type
        HAVING COUNT(*) >= 3 -- Only significant transition patterns
    ),
    entry_exit_analysis AS (
        -- Analyze entry and exit touchpoints
        SELECT 
            'entry' as touchpoint_role,
            first_touchpoint_name as touchpoint_name,
            first_interaction_type as interaction_type,
            COUNT(*) as users_count,
            ROUND(AVG(total_interactions), 2) as avg_interactions,
            ROUND(AVG(journey_duration_minutes), 1) as avg_journey_duration,
            ROUND(COUNT(CASE WHEN journey_complexity != 'single_touchpoint' THEN 1 END)::DECIMAL / COUNT(*) * 100, 1) as effectiveness_metric
        FROM user_journeys
        GROUP BY first_touchpoint_name, first_interaction_type
        
        UNION ALL
        
        SELECT 
            'exit' as touchpoint_role,
            last_touchpoint_name as touchpoint_name,
            last_interaction_type as interaction_type,
            COUNT(*) as users_count,
            ROUND(AVG(total_interactions), 2) as avg_interactions,
            ROUND(AVG(journey_duration_minutes), 1) as avg_journey_duration,
            ROUND(COUNT(CASE WHEN journey_complexity != 'single_touchpoint' THEN 1 END)::DECIMAL / COUNT(*) * 100, 1) as effectiveness_metric 
        FROM user_journeys
        GROUP BY last_touchpoint_name, last_interaction_type
    ),
    journey_insights AS (
        -- Generate journey insights and metrics
        SELECT 
            COUNT(DISTINCT fp) as total_users,
            COUNT(*) as total_interactions_analyzed,
            ROUND(AVG(total_interactions), 2) as avg_interactions_per_user,
            ROUND(AVG(journey_duration_minutes), 1) as avg_journey_duration_minutes,
            ROUND(AVG(unique_touchpoints_visited), 2) as avg_touchpoints_per_user,
            -- Journey complexity distribution
            ROUND(COUNT(CASE WHEN journey_complexity = 'single_touchpoint' THEN 1 END)::DECIMAL / COUNT(*) * 100, 1) as single_touchpoint_percentage,
            ROUND(COUNT(CASE WHEN journey_complexity = 'two_touchpoint' THEN 1 END)::DECIMAL / COUNT(*) * 100, 1) as two_touchpoint_percentage,
            ROUND(COUNT(CASE WHEN journey_complexity = 'multi_touchpoint' THEN 1 END)::DECIMAL / COUNT(*) * 100, 1) as multi_touchpoint_percentage,
            -- Interaction diversity
            ROUND(COUNT(CASE WHEN interaction_diversity = 'multi_method' THEN 1 END)::DECIMAL / COUNT(*) * 100, 1) as multi_method_percentage,
            -- Duration insights
            PERCENTILE_CONT(0.5) WITHIN GROUP (ORDER BY journey_duration_minutes) as median_journey_duration_minutes,
            MAX(journey_duration_minutes) as longest_journey_minutes,
            COUNT(CASE WHEN journey_duration_minutes > 60 THEN 1 END) as journeys_over_1_hour
        FROM user_journeys
    )
    SELECT json_build_object(
        'period_info', json_build_object(
            'period_days', p_period_days,
            'start_date', start_date,
            'end_date', end_date,
            'timezone', p_timezone,
            'is_premium', p_is_premium,
            'analysis_type', 'user_journeys'
        ),
        'filters_applied', json_build_object(
            'has_filters', (p_tag_ids IS NOT NULL OR p_touchpoint_ids IS NOT NULL),
            'tags_count', COALESCE(array_length(p_tag_ids, 1), 0),
            'touchpoints_count', COALESCE(array_length(p_touchpoint_ids, 1), 0)
        ),
        'journey_analysis', json_build_object(
            -- Journey patterns and complexity
            'journey_patterns', (
                SELECT json_agg(
                    json_build_object(
                        'complexity', journey_complexity,
                        'interaction_diversity', interaction_diversity,
                        'users_count', users_count,
                        'pattern_percentage', pattern_percentage,
                        'avg_interactions_per_journey', avg_interactions_per_journey,
                        'avg_touchpoints_per_journey', avg_touchpoints_per_journey,
                        'avg_journey_duration_minutes', avg_journey_duration_minutes,
                        'avg_active_days', avg_active_days
                    )
                )
                FROM (
                    SELECT *
                    FROM journey_patterns_with_percentages
                    ORDER BY users_count DESC
                ) ordered_patterns
            ),
            -- Entry and exit point analysis
            'entry_exit_analysis', (
                SELECT json_agg(
                    json_build_object(
                        'role', touchpoint_role,
                        'touchpoint_name', touchpoint_name,
                        'interaction_type', interaction_type,
                        'users_count', users_count,
                        'avg_interactions', avg_interactions,
                        'avg_journey_duration', avg_journey_duration,
                        'effectiveness_metric', effectiveness_metric
                    )
                )
                FROM (
                    SELECT *
                    FROM entry_exit_analysis
                    ORDER BY users_count DESC
                ) ordered_entry_exit
            ),
            -- Touchpoint transitions (Premium only)
            'touchpoint_transitions', CASE 
                WHEN p_is_premium THEN
                    (
                        SELECT json_agg(
                            json_build_object(
                                'from_touchpoint', from_touchpoint,
                                'to_touchpoint', to_touchpoint,
                                'from_interaction_type', from_interaction_type,
                                'to_interaction_type', to_interaction_type,
                                'transition_count', transition_count,
                                'unique_users', unique_users,
                                'avg_time_between_minutes', avg_time_between_minutes,
                                'flow_strength', CASE 
                                    WHEN transition_count >= 20 THEN 'strong'
                                    WHEN transition_count >= 10 THEN 'moderate'
                                    ELSE 'weak'
                                END
                            )
                        )
                        FROM (
                            SELECT *
                            FROM touchpoint_transitions
                            ORDER BY transition_count DESC
                            LIMIT CASE WHEN p_is_premium THEN 20 ELSE 5 END
                        ) ordered_transitions
                    )
                ELSE NULL
            END
        ),
        'insights', json_build_object(
            -- Journey summary metrics
            'journey_summary', (
                SELECT json_build_object(
                    'total_users', total_users,
                    'avg_interactions_per_user', avg_interactions_per_user,
                    'avg_journey_duration_minutes', avg_journey_duration_minutes,
                    'median_journey_duration_minutes', median_journey_duration_minutes,
                    'avg_touchpoints_per_user', avg_touchpoints_per_user,
                    'longest_journey_minutes', longest_journey_minutes,
                    'journeys_over_1_hour', journeys_over_1_hour,
                    'complexity_distribution', json_build_object(
                        'single_touchpoint_percentage', single_touchpoint_percentage,
                        'two_touchpoint_percentage', two_touchpoint_percentage,
                        'multi_touchpoint_percentage', multi_touchpoint_percentage
                    ),
                    'interaction_diversity', json_build_object(
                        'multi_method_percentage', multi_method_percentage
                    )
                )
                FROM journey_insights
            ),
            -- Journey optimization recommendations
            'recommendations', CASE 
                WHEN p_is_premium THEN
                    (
                        SELECT json_agg(
                            json_build_object(
                                'recommendation_type', recommendation_type,
                                'priority', priority,
                                'category', category,
                                'metric_key', metric_key,
                                'threshold', threshold,
                                'current_value', current_value,
                                'improvement_potential', improvement_potential
                            )
                        )
                        FROM (
                            SELECT 
                                'high_single_touchpoint_rate' as recommendation_type,
                                'high' as priority,
                                'journey_optimization' as category,
                                'single_touchpoint_percentage' as metric_key,
                                70.0 as threshold,
                                ji.single_touchpoint_percentage as current_value,
                                'create_touchpoint_connections' as improvement_potential
                            FROM journey_insights ji
                            WHERE ji.single_touchpoint_percentage > 70
                            
                            UNION ALL
                            
                            SELECT 
                                'low_multi_touchpoint_engagement' as recommendation_type,
                                'medium' as priority,
                                'engagement_depth' as category,
                                'multi_touchpoint_percentage' as metric_key,
                                20.0 as threshold,
                                ji.multi_touchpoint_percentage as current_value,
                                'improve_cross_touchpoint_flows' as improvement_potential
                            FROM journey_insights ji
                            WHERE ji.multi_touchpoint_percentage < 20
                            
                            UNION ALL
                            
                            SELECT 
                                'short_journey_duration' as recommendation_type,
                                'medium' as priority,
                                'user_engagement' as category,
                                'avg_journey_duration_minutes' as metric_key,
                                5.0 as threshold,
                                ji.avg_journey_duration_minutes as current_value,
                                'increase_engagement_depth' as improvement_potential
                            FROM journey_insights ji
                            WHERE ji.avg_journey_duration_minutes < 5
                            
                            UNION ALL
                            
                            SELECT 
                                'limited_interaction_diversity' as recommendation_type,
                                'low' as priority,
                                'interaction_optimization' as category,
                                'multi_method_percentage' as metric_key,
                                25.0 as threshold,
                                ji.multi_method_percentage as current_value,
                                'diversify_interaction_types' as improvement_potential
                            FROM journey_insights ji
                            WHERE ji.multi_method_percentage < 25
                            
                        ) recommendations
                    )
                ELSE 
                    NULL
            END
        )
    ) INTO result;
    
    RETURN result;
    
EXCEPTION WHEN OTHERS THEN
    RETURN json_build_object(
        'error', TRUE,
        'message', SQLERRM,
        'organization_id', p_organization_id
    );
END;
$$;


--
-- Name: get_behavior_user_journeys_old(uuid, integer, text, uuid[], uuid[], boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_behavior_user_journeys_old(p_organization_id uuid, p_period_days integer, p_timezone text DEFAULT 'UTC'::text, p_tag_ids uuid[] DEFAULT NULL::uuid[], p_touchpoint_ids uuid[] DEFAULT NULL::uuid[], p_is_premium boolean DEFAULT false) RETURNS json
    LANGUAGE plpgsql
    AS $$DECLARE
    start_date TIMESTAMPTZ;
    end_date TIMESTAMPTZ;
    result JSON;
BEGIN
    -- Validate tier restrictions
    IF NOT p_is_premium AND p_period_days != 7 THEN
        RETURN json_build_object('error', TRUE, 'message', 'Free tier limited to 7 days only');
    END IF;
    
    IF NOT p_is_premium AND p_touchpoint_ids IS NOT NULL AND array_length(p_touchpoint_ids, 1) > 1 THEN
        RETURN json_build_object('error', TRUE, 'message', 'Free tier limited to 1 touchpoint only');
    END IF;

    -- Calculate date range in user's timezone
    end_date := CURRENT_TIMESTAMP AT TIME ZONE p_timezone;
    start_date := end_date - (p_period_days || ' days')::INTERVAL;
    
    WITH filtered_visits AS (
        -- Apply hierarchical filtering
        SELECT 
            v.fp,
            v.type,
            v.created_at,
            v.tp_id,
            v.platform,
            v.country,
            tp.name as touchpoint_name
        FROM visits v
        LEFT JOIN touch_points tp ON v.tp_id = tp.id
        WHERE v.organization_id = p_organization_id
            AND v.created_at >= start_date
            AND v.created_at < end_date            
            AND v.fp IS NOT NULL
            AND (
                -- No filtering if no filters specified
                (p_tag_ids IS NULL AND p_touchpoint_ids IS NULL)
                OR 
                -- Apply hierarchical filtering: tags first, then touchpoints
                (
                    (p_tag_ids IS NULL OR v.tp_id IN (
                        SELECT DISTINCT ttl.tp_id 
                        FROM tp_tag_links ttl 
                        WHERE ttl.tag_id = ANY(p_tag_ids)
                    ))
                    AND
                    (p_touchpoint_ids IS NULL OR v.tp_id = ANY(p_touchpoint_ids))
                )
            )
    ),
    user_journeys AS (
        -- Analyze individual user journeys
        SELECT 
            fp,
            COUNT(*) as total_interactions,
            COUNT(DISTINCT tp_id) as unique_touchpoints_visited,
            COUNT(DISTINCT type) as interaction_types_used,
            COUNT(DISTINCT DATE(created_at AT TIME ZONE p_timezone)) as active_days,
            MIN(created_at) as journey_start,
            MAX(created_at) as journey_end,
            EXTRACT(EPOCH FROM (MAX(created_at) - MIN(created_at))) / 60 as journey_duration_minutes,
            -- Get first touchpoint using MIN(created_at)
            (array_agg(tp_id ORDER BY created_at))[1] as first_touchpoint_id,
            (array_agg(touchpoint_name ORDER BY created_at))[1] as first_touchpoint_name,
            (array_agg(type ORDER BY created_at))[1] as first_interaction_type,
            -- Get last touchpoint using MAX(created_at)
            (array_agg(tp_id ORDER BY created_at DESC))[1] as last_touchpoint_id,
            (array_agg(touchpoint_name ORDER BY created_at DESC))[1] as last_touchpoint_name,
            (array_agg(type ORDER BY created_at DESC))[1] as last_interaction_type,
            -- Journey classification
            CASE 
                WHEN COUNT(DISTINCT tp_id) = 1 THEN 'single_touchpoint'
                WHEN COUNT(DISTINCT tp_id) = 2 THEN 'two_touchpoint'
                WHEN COUNT(DISTINCT tp_id) >= 3 THEN 'multi_touchpoint'
            END as journey_complexity,
            -- Interaction patterns
            CASE 
                WHEN COUNT(DISTINCT type) = 1 THEN 'single_method'
                WHEN COUNT(DISTINCT type) >= 2 THEN 'multi_method'
            END as interaction_diversity
        FROM filtered_visits
        GROUP BY fp
    ),
    journey_patterns AS (
        -- Analyze journey patterns and flows
        SELECT 
            journey_complexity,
            interaction_diversity,
            COUNT(*) as users_count,
            ROUND(AVG(total_interactions), 2) as avg_interactions_per_journey,
            ROUND(AVG(unique_touchpoints_visited), 2) as avg_touchpoints_per_journey,
            ROUND(AVG(journey_duration_minutes), 1) as avg_journey_duration_minutes,
            ROUND(AVG(active_days), 2) as avg_active_days
        FROM user_journeys
        GROUP BY journey_complexity, interaction_diversity
    ),
    journey_patterns_with_percentages AS (
        -- Calculate percentages using window function
        SELECT 
            *,
            ROUND(users_count::DECIMAL / SUM(users_count) OVER() * 100, 1) as pattern_percentage
        FROM journey_patterns
    ),
    touchpoint_transitions AS (
        -- Analyze touchpoint-to-touchpoint flows (Premium feature)
        SELECT 
            lag_tp_name as from_touchpoint,
            current_tp_name as to_touchpoint,
            lag_type as from_interaction_type,
            current_type as to_interaction_type,
            COUNT(*) as transition_count,
            COUNT(DISTINCT fp) as unique_users,
            ROUND(AVG(time_between_minutes), 1) as avg_time_between_minutes
        FROM (
            SELECT 
                fv.fp,
                fv.touchpoint_name as current_tp_name,
                fv.type as current_type,
                LAG(fv.touchpoint_name) OVER (PARTITION BY fv.fp ORDER BY fv.created_at) as lag_tp_name,
                LAG(fv.type) OVER (PARTITION BY fv.fp ORDER BY fv.created_at) as lag_type,
                EXTRACT(EPOCH FROM (fv.created_at - LAG(fv.created_at) OVER (PARTITION BY fv.fp ORDER BY fv.created_at))) / 60 as time_between_minutes
            FROM filtered_visits fv
        ) transitions
        WHERE lag_tp_name IS NOT NULL
            AND lag_tp_name != current_tp_name -- Only cross-touchpoint transitions
        GROUP BY lag_tp_name, current_tp_name, lag_type, current_type
        HAVING COUNT(*) >= 3 -- Only significant transition patterns
    ),
    entry_exit_analysis AS (
        -- Analyze entry and exit touchpoints
        SELECT 
            'entry' as touchpoint_role,
            first_touchpoint_name as touchpoint_name,
            first_interaction_type as interaction_type,
            COUNT(*) as users_count,
            ROUND(AVG(total_interactions), 2) as avg_interactions,
            ROUND(AVG(journey_duration_minutes), 1) as avg_journey_duration,
            ROUND(COUNT(CASE WHEN journey_complexity != 'single_touchpoint' THEN 1 END)::DECIMAL / COUNT(*) * 100, 1) as effectiveness_metric
        FROM user_journeys
        GROUP BY first_touchpoint_name, first_interaction_type
        
        UNION ALL
        
        SELECT 
            'exit' as touchpoint_role,
            last_touchpoint_name as touchpoint_name,
            last_interaction_type as interaction_type,
            COUNT(*) as users_count,
            ROUND(AVG(total_interactions), 2) as avg_interactions,
            ROUND(AVG(journey_duration_minutes), 1) as avg_journey_duration,
            ROUND(COUNT(CASE WHEN journey_complexity != 'single_touchpoint' THEN 1 END)::DECIMAL / COUNT(*) * 100, 1) as effectiveness_metric 
        FROM user_journeys
        GROUP BY last_touchpoint_name, last_interaction_type
    ),
    journey_insights AS (
        -- Generate journey insights and metrics
        SELECT 
            COUNT(DISTINCT fp) as total_users,
            COUNT(*) as total_interactions_analyzed,
            ROUND(AVG(total_interactions), 2) as avg_interactions_per_user,
            ROUND(AVG(journey_duration_minutes), 1) as avg_journey_duration_minutes,
            ROUND(AVG(unique_touchpoints_visited), 2) as avg_touchpoints_per_user,
            -- Journey complexity distribution
            ROUND(COUNT(CASE WHEN journey_complexity = 'single_touchpoint' THEN 1 END)::DECIMAL / COUNT(*) * 100, 1) as single_touchpoint_percentage,
            ROUND(COUNT(CASE WHEN journey_complexity = 'two_touchpoint' THEN 1 END)::DECIMAL / COUNT(*) * 100, 1) as two_touchpoint_percentage,
            ROUND(COUNT(CASE WHEN journey_complexity = 'multi_touchpoint' THEN 1 END)::DECIMAL / COUNT(*) * 100, 1) as multi_touchpoint_percentage,
            -- Interaction diversity
            ROUND(COUNT(CASE WHEN interaction_diversity = 'multi_method' THEN 1 END)::DECIMAL / COUNT(*) * 100, 1) as multi_method_percentage,
            -- Duration insights
            PERCENTILE_CONT(0.5) WITHIN GROUP (ORDER BY journey_duration_minutes) as median_journey_duration_minutes,
            MAX(journey_duration_minutes) as longest_journey_minutes,
            COUNT(CASE WHEN journey_duration_minutes > 60 THEN 1 END) as journeys_over_1_hour
        FROM user_journeys
    )
    SELECT json_build_object(
        'period_info', json_build_object(
            'period_days', p_period_days,
            'start_date', start_date,
            'end_date', end_date,
            'timezone', p_timezone,
            'is_premium', p_is_premium,
            'analysis_type', 'user_journeys'
        ),
        'filters_applied', json_build_object(
            'has_filters', (p_tag_ids IS NOT NULL OR p_touchpoint_ids IS NOT NULL),
            'tags_count', COALESCE(array_length(p_tag_ids, 1), 0),
            'touchpoints_count', COALESCE(array_length(p_touchpoint_ids, 1), 0)
        ),
        'journey_analysis', json_build_object(
            -- Journey patterns and complexity
            'journey_patterns', (
                SELECT json_agg(
                    json_build_object(
                        'complexity', journey_complexity,
                        'interaction_diversity', interaction_diversity,
                        'users_count', users_count,
                        'pattern_percentage', pattern_percentage,
                        'avg_interactions_per_journey', avg_interactions_per_journey,
                        'avg_touchpoints_per_journey', avg_touchpoints_per_journey,
                        'avg_journey_duration_minutes', avg_journey_duration_minutes,
                        'avg_active_days', avg_active_days
                    )
                )
                FROM (
                    SELECT *
                    FROM journey_patterns_with_percentages
                    ORDER BY users_count DESC
                ) ordered_patterns
            ),
            -- Entry and exit point analysis
            'entry_exit_analysis', (
                SELECT json_agg(
                    json_build_object(
                        'role', touchpoint_role,
                        'touchpoint_name', touchpoint_name,
                        'interaction_type', interaction_type,
                        'users_count', users_count,
                        'avg_interactions', avg_interactions,
                        'avg_journey_duration', avg_journey_duration,
                        'effectiveness_metric', effectiveness_metric
                    )
                )
                FROM (
                    SELECT *
                    FROM entry_exit_analysis
                    ORDER BY users_count DESC
                ) ordered_entry_exit
            ),
            -- Touchpoint transitions (Premium only)
            'touchpoint_transitions', CASE 
                WHEN p_is_premium THEN
                    (
                        SELECT json_agg(
                            json_build_object(
                                'from_touchpoint', from_touchpoint,
                                'to_touchpoint', to_touchpoint,
                                'from_interaction_type', from_interaction_type,
                                'to_interaction_type', to_interaction_type,
                                'transition_count', transition_count,
                                'unique_users', unique_users,
                                'avg_time_between_minutes', avg_time_between_minutes,
                                'flow_strength', CASE 
                                    WHEN transition_count >= 20 THEN 'strong'
                                    WHEN transition_count >= 10 THEN 'moderate'
                                    ELSE 'weak'
                                END
                            )
                        )
                        FROM (
                            SELECT *
                            FROM touchpoint_transitions
                            ORDER BY transition_count DESC
                            LIMIT CASE WHEN p_is_premium THEN 20 ELSE 5 END
                        ) ordered_transitions
                    )
                ELSE NULL
            END
        ),
        'insights', json_build_object(
            -- Journey summary metrics
            'journey_summary', (
                SELECT json_build_object(
                    'total_users', total_users,
                    'avg_interactions_per_user', avg_interactions_per_user,
                    'avg_journey_duration_minutes', avg_journey_duration_minutes,
                    'median_journey_duration_minutes', median_journey_duration_minutes,
                    'avg_touchpoints_per_user', avg_touchpoints_per_user,
                    'longest_journey_minutes', longest_journey_minutes,
                    'journeys_over_1_hour', journeys_over_1_hour,
                    'complexity_distribution', json_build_object(
                        'single_touchpoint_percentage', single_touchpoint_percentage,
                        'two_touchpoint_percentage', two_touchpoint_percentage,
                        'multi_touchpoint_percentage', multi_touchpoint_percentage
                    ),
                    'interaction_diversity', json_build_object(
                        'multi_method_percentage', multi_method_percentage
                    )
                )
                FROM journey_insights
            ),
            -- Journey optimization recommendations
            'recommendations', CASE 
                WHEN p_is_premium THEN
                    (
                        SELECT json_agg(
                            json_build_object(
                                'recommendation_type', recommendation_type,
                                'priority', priority,
                                'category', category,
                                'metric_key', metric_key,
                                'threshold', threshold,
                                'current_value', current_value,
                                'improvement_potential', improvement_potential
                            )
                        )
                        FROM (
                            SELECT 
                                'high_single_touchpoint_rate' as recommendation_type,
                                'high' as priority,
                                'journey_optimization' as category,
                                'single_touchpoint_percentage' as metric_key,
                                70.0 as threshold,
                                ji.single_touchpoint_percentage as current_value,
                                'create_touchpoint_connections' as improvement_potential
                            FROM journey_insights ji
                            WHERE ji.single_touchpoint_percentage > 70
                            
                            UNION ALL
                            
                            SELECT 
                                'low_multi_touchpoint_engagement' as recommendation_type,
                                'medium' as priority,
                                'engagement_depth' as category,
                                'multi_touchpoint_percentage' as metric_key,
                                20.0 as threshold,
                                ji.multi_touchpoint_percentage as current_value,
                                'improve_cross_touchpoint_flows' as improvement_potential
                            FROM journey_insights ji
                            WHERE ji.multi_touchpoint_percentage < 20
                            
                            UNION ALL
                            
                            SELECT 
                                'short_journey_duration' as recommendation_type,
                                'medium' as priority,
                                'user_engagement' as category,
                                'avg_journey_duration_minutes' as metric_key,
                                5.0 as threshold,
                                ji.avg_journey_duration_minutes as current_value,
                                'increase_engagement_depth' as improvement_potential
                            FROM journey_insights ji
                            WHERE ji.avg_journey_duration_minutes < 5
                            
                            UNION ALL
                            
                            SELECT 
                                'limited_interaction_diversity' as recommendation_type,
                                'low' as priority,
                                'interaction_optimization' as category,
                                'multi_method_percentage' as metric_key,
                                25.0 as threshold,
                                ji.multi_method_percentage as current_value,
                                'diversify_interaction_types' as improvement_potential
                            FROM journey_insights ji
                            WHERE ji.multi_method_percentage < 25
                            
                        ) recommendations
                    )
                ELSE 
                    NULL
            END
        )
    ) INTO result;
    
    RETURN result;
    
EXCEPTION WHEN OTHERS THEN
    RETURN json_build_object(
        'error', TRUE,
        'message', SQLERRM,
        'organization_id', p_organization_id
    );
END;$$;


--
-- Name: get_campaign_analytic(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_campaign_analytic(p_campaign_id uuid) RETURNS TABLE(date date, total integer, os jsonb[], platform jsonb[], type jsonb[], unique_visit jsonb[])
    LANGUAGE sql
    AS $$WITH base AS (
    SELECT
      DATE(created_at) AS date,
      os,
      platform,
      type,
      fp
    FROM visits
    WHERE campaign_id = p_campaign_id
  ),
  agg_data AS (
    SELECT
      date,
      os,
      platform,
      type,
      fp,
      COUNT(*) OVER (PARTITION BY date, os) AS os_count,
      COUNT(*) OVER (PARTITION BY date, platform) AS platform_count,
      COUNT(*) OVER (PARTITION BY date, type) AS type_count
    FROM base
  ),
  fp_visits AS (
    SELECT
      date,
      fp,
      MIN(os) AS os,
      MIN(platform) AS platform,
      COUNT(*) AS visit
    FROM base
    GROUP BY date, fp
  )
  SELECT
    a.date,
    COUNT(*) AS total,
    ARRAY_AGG(DISTINCT jsonb_build_object('os', a.os, 'count', a.os_count)) AS os,
    ARRAY_AGG(DISTINCT jsonb_build_object('platform', a.platform, 'count', a.platform_count)) AS platform,
    ARRAY_AGG(DISTINCT jsonb_build_object('type', a.type, 'count', a.type_count)) AS type,
    ARRAY_AGG(DISTINCT jsonb_build_object(
    'fp', f.fp,
    'visit', f.visit,
    'os', f.os,
    'platform', f.platform
  )) AS unique_visit
  FROM agg_data a
  LEFT JOIN fp_visits f ON a.date = f.date AND a.fp = f.fp
  GROUP BY a.date
  ORDER BY a.date ASC;$$;


--
-- Name: requesting_user_id(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.requesting_user_id() RETURNS uuid
    LANGUAGE sql
    AS $$SELECT NULLIF(
    current_setting('request.jwt.claims', true)::json->>'sub',
    ''
)::uuid;$$;


--
-- Name: campaigns; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.campaigns (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    user_id uuid DEFAULT public.requesting_user_id() NOT NULL,
    name text NOT NULL,
    "desc" text,
    organization_id uuid NOT NULL,
    enabled boolean DEFAULT true NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    nodes jsonb[],
    edges jsonb[],
    affected_tag_ids uuid[],
    pre_combination jsonb
);


--
-- Name: get_campaigns_from_touch_point(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_campaigns_from_touch_point(tp_id uuid) RETURNS SETOF public.campaigns
    LANGUAGE sql
    AS $$
  select *
  from campaigns
  where exists (
    select 1
    from tp_tag_links
    where tp_tag_links.tp_id = tp_id
      and tp_tag_links.tag_id = any(campaigns.affected_tag_ids)
  );
$$;


--
-- Name: get_conversion_stats(uuid, uuid[], uuid[], uuid[], uuid[], timestamp without time zone, timestamp without time zone, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_conversion_stats(_organization_id uuid, _viewable_tp_ids uuid[] DEFAULT NULL::uuid[], _tp_ids uuid[] DEFAULT NULL::uuid[], _tag_ids uuid[] DEFAULT NULL::uuid[], _collection_ids uuid[] DEFAULT NULL::uuid[], _start_date timestamp without time zone DEFAULT NULL::timestamp without time zone, _end_date timestamp without time zone DEFAULT NULL::timestamp without time zone, _exclude_bot boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    result jsonb;
    tp_ids_from_tags uuid[];
    tp_ids_from_collections uuid[];
    final_tp_ids uuid[];
    leads_count bigint;
    customers_count bigint;
    sales_count bigint;
    revenue_data jsonb;
    default_currency text;
BEGIN
    -- Start with viewable touch points as the base
    final_tp_ids := _viewable_tp_ids;

    -- Apply tp_ids filter if provided
    IF _tp_ids IS NOT NULL AND array_length(_tp_ids, 1) > 0 THEN
        IF final_tp_ids IS NOT NULL THEN
            -- Intersect with viewable
            SELECT array_agg(DISTINCT tp_id)
            INTO final_tp_ids
            FROM unnest(final_tp_ids) AS tp_id
            WHERE tp_id = ANY(_tp_ids);
        ELSE
            final_tp_ids := _tp_ids;
        END IF;
    END IF;

    -- Apply tag_ids filter if provided
    IF _tag_ids IS NOT NULL AND array_length(_tag_ids, 1) > 0 THEN
        SELECT array_agg(DISTINCT tp_id)
        INTO tp_ids_from_tags
        FROM tp_tag_links
        WHERE tag_id = ANY(_tag_ids);

        IF final_tp_ids IS NOT NULL THEN
            -- Intersect with current filter
            SELECT array_agg(DISTINCT tp_id)
            INTO final_tp_ids
            FROM unnest(final_tp_ids) AS tp_id
            WHERE tp_id = ANY(tp_ids_from_tags);
        ELSE
            final_tp_ids := tp_ids_from_tags;
        END IF;
    END IF;

    -- Apply collection_ids filter if provided
    IF _collection_ids IS NOT NULL AND array_length(_collection_ids, 1) > 0 THEN
        SELECT array_agg(DISTINCT id)
        INTO tp_ids_from_collections
        FROM touch_points
        WHERE collection_id = ANY(_collection_ids);

        IF final_tp_ids IS NOT NULL THEN
            -- Intersect with current filter
            SELECT array_agg(DISTINCT tp_id)
            INTO final_tp_ids
            FROM unnest(final_tp_ids) AS tp_id
            WHERE tp_id = ANY(tp_ids_from_collections);
        ELSE
            final_tp_ids := tp_ids_from_collections;
        END IF;
    END IF;

    -- Get organization's default currency
    SELECT COALESCE(o.default_currency, 'USD')
    INTO default_currency
    FROM organizations o
    WHERE o.id = _organization_id;

    -- Count leads with filters
    SELECT COUNT(*)
    INTO leads_count
    FROM conversion_events
    WHERE organization_id = _organization_id
      AND event_type = 'lead'
      AND (final_tp_ids IS NULL OR touch_point_id = ANY(final_tp_ids))
      AND (_start_date IS NULL OR created_at >= _start_date)
      AND (_end_date IS NULL OR created_at <= _end_date);

    -- Count customers (org-wide, no date/touchpoint filter - customers persist)
    SELECT COUNT(*)
    INTO customers_count
    FROM customer_profiles
    WHERE organization_id = _organization_id;

    -- Count sales with filters
    SELECT COUNT(*)
    INTO sales_count
    FROM conversion_events
    WHERE organization_id = _organization_id
      AND event_type = 'sale'
      AND (final_tp_ids IS NULL OR touch_point_id = ANY(final_tp_ids))
      AND (_start_date IS NULL OR created_at >= _start_date)
      AND (_end_date IS NULL OR created_at <= _end_date);

    -- Calculate revenue grouped by currency
    WITH revenue_by_currency AS (
        SELECT
            COALESCE(ce.currency, default_currency) AS currency,
            SUM(COALESCE(ce.amount, 0)) AS total_amount
        FROM conversion_events ce
        WHERE ce.organization_id = _organization_id
          AND ce.event_type = 'sale'
          AND ce.amount IS NOT NULL
          AND (final_tp_ids IS NULL OR ce.touch_point_id = ANY(final_tp_ids))
          AND (_start_date IS NULL OR ce.created_at >= _start_date)
          AND (_end_date IS NULL OR ce.created_at <= _end_date)
        GROUP BY ce.currency
    )
    SELECT jsonb_object_agg(
        COALESCE(UPPER(currency), UPPER(default_currency)),
        total_amount
    )
    INTO revenue_data
    FROM revenue_by_currency;

    -- Build result object
    SELECT jsonb_build_object(
        'leads', leads_count,
        'customers', customers_count,
        'sales', sales_count,
        'revenue_by_currency', COALESCE(revenue_data, '{}'::jsonb),
        'default_currency', default_currency
    )
    INTO result;

    RETURN result;
END;
$$;


--
-- Name: get_conversion_stats(uuid, uuid[], uuid[], uuid[], uuid[], timestamp without time zone, timestamp without time zone, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_conversion_stats(_organization_id uuid, _viewable_tp_ids uuid[] DEFAULT NULL::uuid[], _tp_ids uuid[] DEFAULT NULL::uuid[], _tag_ids uuid[] DEFAULT NULL::uuid[], _collection_ids uuid[] DEFAULT NULL::uuid[], _start_date timestamp without time zone DEFAULT NULL::timestamp without time zone, _end_date timestamp without time zone DEFAULT NULL::timestamp without time zone, _exclude_bot boolean DEFAULT false, _source text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    result jsonb;
    tp_ids_from_tags uuid[];
    tp_ids_from_collections uuid[];
    final_tp_ids uuid[];
    leads_count bigint;
    customers_count bigint;
    sales_count bigint;
    revenue_data jsonb;
    default_currency text;
BEGIN
    -- Start with viewable touch points as the base
    final_tp_ids := _viewable_tp_ids;

    -- Apply tp_ids filter if provided
    IF _tp_ids IS NOT NULL AND array_length(_tp_ids, 1) > 0 THEN
        IF final_tp_ids IS NOT NULL THEN
            SELECT array_agg(DISTINCT tp_id)
            INTO final_tp_ids
            FROM unnest(final_tp_ids) AS tp_id
            WHERE tp_id = ANY(_tp_ids);
        ELSE
            final_tp_ids := _tp_ids;
        END IF;
    END IF;

    -- Apply tag_ids filter if provided
    IF _tag_ids IS NOT NULL AND array_length(_tag_ids, 1) > 0 THEN
        SELECT array_agg(DISTINCT tp_id)
        INTO tp_ids_from_tags
        FROM tp_tag_links
        WHERE tag_id = ANY(_tag_ids);

        IF final_tp_ids IS NOT NULL THEN
            SELECT array_agg(DISTINCT tp_id)
            INTO final_tp_ids
            FROM unnest(final_tp_ids) AS tp_id
            WHERE tp_id = ANY(tp_ids_from_tags);
        ELSE
            final_tp_ids := tp_ids_from_tags;
        END IF;
    END IF;

    -- Apply collection_ids filter if provided
    IF _collection_ids IS NOT NULL AND array_length(_collection_ids, 1) > 0 THEN
        SELECT array_agg(DISTINCT id)
        INTO tp_ids_from_collections
        FROM touch_points
        WHERE collection_id = ANY(_collection_ids);

        IF final_tp_ids IS NOT NULL THEN
            SELECT array_agg(DISTINCT tp_id)
            INTO final_tp_ids
            FROM unnest(final_tp_ids) AS tp_id
            WHERE tp_id = ANY(tp_ids_from_collections);
        ELSE
            final_tp_ids := tp_ids_from_collections;
        END IF;
    END IF;

    -- Get organization's default currency
    SELECT COALESCE(o.default_currency, 'USD')
    INTO default_currency
    FROM organizations o
    WHERE o.id = _organization_id;

    -- Count leads with filters.
    -- tp visibility guard OR-with-NULL when source allows direct, so that a
    -- non-owner viewer with scoped tp_ids still sees direct leads. Mirrors
    -- conversion.service.findAllConversions' OR(touch_point_id.is.null).
    SELECT COUNT(*)
    INTO leads_count
    FROM conversion_events
    WHERE organization_id = _organization_id
      AND event_type = 'lead'
      AND (
          final_tp_ids IS NULL
          OR touch_point_id = ANY(final_tp_ids)
          OR (COALESCE(_source, 'all') IN ('direct', 'all') AND touch_point_id IS NULL)
      )
      AND (_start_date IS NULL OR created_at >= _start_date)
      AND (_end_date IS NULL OR created_at <= _end_date)
      AND (
          _source IS NULL OR _source = 'all'
          OR (_source = 'direct'     AND touch_point_id IS NULL)
          OR (_source = 'attributed' AND touch_point_id IS NOT NULL)
      );

    -- Count customers acquired within window whose attribution matches filters.
    -- For Direct source, first_touch_point_id IS NULL bypasses the tp_ids
    -- filter (mirrors the OR-with-NULL convention used elsewhere).
    SELECT COUNT(*)
    INTO customers_count
    FROM customer_profiles
    WHERE organization_id = _organization_id
      AND (
          final_tp_ids IS NULL
          OR first_touch_point_id = ANY(final_tp_ids)
          OR (COALESCE(_source, 'all') IN ('direct', 'all') AND first_touch_point_id IS NULL)
      )
      AND (_start_date IS NULL OR created_at >= _start_date)
      AND (_end_date IS NULL OR created_at <= _end_date)
      AND (
          _source IS NULL OR _source = 'all'
          OR (_source = 'direct'     AND first_touch_point_id IS NULL)
          OR (_source = 'attributed' AND first_touch_point_id IS NOT NULL)
      );

    -- Count sales with filters (same OR-with-NULL tp guard as leads).
    SELECT COUNT(*)
    INTO sales_count
    FROM conversion_events
    WHERE organization_id = _organization_id
      AND event_type = 'sale'
      AND (
          final_tp_ids IS NULL
          OR touch_point_id = ANY(final_tp_ids)
          OR (COALESCE(_source, 'all') IN ('direct', 'all') AND touch_point_id IS NULL)
      )
      AND (_start_date IS NULL OR created_at >= _start_date)
      AND (_end_date IS NULL OR created_at <= _end_date)
      AND (
          _source IS NULL OR _source = 'all'
          OR (_source = 'direct'     AND touch_point_id IS NULL)
          OR (_source = 'attributed' AND touch_point_id IS NOT NULL)
      );

    -- Revenue grouped by currency (same OR-with-NULL tp guard).
    WITH revenue_by_currency AS (
        SELECT
            COALESCE(ce.currency, default_currency) AS currency,
            SUM(COALESCE(ce.amount, 0)) AS total_amount
        FROM conversion_events ce
        WHERE ce.organization_id = _organization_id
          AND ce.event_type = 'sale'
          AND ce.amount IS NOT NULL
          AND (
              final_tp_ids IS NULL
              OR ce.touch_point_id = ANY(final_tp_ids)
              OR (COALESCE(_source, 'all') IN ('direct', 'all') AND ce.touch_point_id IS NULL)
          )
          AND (_start_date IS NULL OR ce.created_at >= _start_date)
          AND (_end_date IS NULL OR ce.created_at <= _end_date)
          AND (
              _source IS NULL OR _source = 'all'
              OR (_source = 'direct'     AND ce.touch_point_id IS NULL)
              OR (_source = 'attributed' AND ce.touch_point_id IS NOT NULL)
          )
        GROUP BY ce.currency
    )
    SELECT jsonb_object_agg(
        COALESCE(UPPER(currency), UPPER(default_currency)),
        total_amount
    )
    INTO revenue_data
    FROM revenue_by_currency;

    -- Build result object
    SELECT jsonb_build_object(
        'leads', leads_count,
        'customers', customers_count,
        'sales', sales_count,
        'revenue_by_currency', COALESCE(revenue_data, '{}'::jsonb),
        'default_currency', default_currency
    )
    INTO result;

    RETURN result;
END;
$$;


--
-- Name: get_conversion_stats_v2(uuid, uuid[], uuid[], uuid[], uuid[], timestamp without time zone, timestamp without time zone, boolean, text, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_conversion_stats_v2(_organization_id uuid, _viewable_tp_ids uuid[] DEFAULT NULL::uuid[], _tp_ids uuid[] DEFAULT NULL::uuid[], _tag_ids uuid[] DEFAULT NULL::uuid[], _collection_ids uuid[] DEFAULT NULL::uuid[], _start_date timestamp without time zone DEFAULT NULL::timestamp without time zone, _end_date timestamp without time zone DEFAULT NULL::timestamp without time zone, _exclude_bot boolean DEFAULT false, _source text DEFAULT NULL::text, _event_names text[] DEFAULT NULL::text[]) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    result jsonb;
    tp_ids_from_tags uuid[];
    tp_ids_from_collections uuid[];
    final_tp_ids uuid[];
    leads_count bigint;
    customers_count bigint;
    sales_count bigint;
    revenue_data jsonb;
    default_currency text;
BEGIN
    final_tp_ids := _viewable_tp_ids;

    IF _tp_ids IS NOT NULL AND array_length(_tp_ids, 1) > 0 THEN
        IF final_tp_ids IS NOT NULL THEN
            SELECT array_agg(DISTINCT tp_id) INTO final_tp_ids
            FROM unnest(final_tp_ids) AS tp_id WHERE tp_id = ANY(_tp_ids);
        ELSE
            final_tp_ids := _tp_ids;
        END IF;
    END IF;

    IF _tag_ids IS NOT NULL AND array_length(_tag_ids, 1) > 0 THEN
        SELECT array_agg(DISTINCT tp_id) INTO tp_ids_from_tags
        FROM tp_tag_links WHERE tag_id = ANY(_tag_ids);
        IF final_tp_ids IS NOT NULL THEN
            SELECT array_agg(DISTINCT tp_id) INTO final_tp_ids
            FROM unnest(final_tp_ids) AS tp_id WHERE tp_id = ANY(tp_ids_from_tags);
        ELSE
            final_tp_ids := tp_ids_from_tags;
        END IF;
    END IF;

    IF _collection_ids IS NOT NULL AND array_length(_collection_ids, 1) > 0 THEN
        SELECT array_agg(DISTINCT id) INTO tp_ids_from_collections
        FROM touch_points WHERE collection_id = ANY(_collection_ids);
        IF final_tp_ids IS NOT NULL THEN
            SELECT array_agg(DISTINCT tp_id) INTO final_tp_ids
            FROM unnest(final_tp_ids) AS tp_id WHERE tp_id = ANY(tp_ids_from_collections);
        ELSE
            final_tp_ids := tp_ids_from_collections;
        END IF;
    END IF;

    SELECT COALESCE(o.default_currency, 'USD') INTO default_currency
    FROM organizations o WHERE o.id = _organization_id;

    SELECT COUNT(*) INTO leads_count
    FROM conversion_events
    WHERE organization_id = _organization_id
      AND event_type = 'lead'
      AND (
          final_tp_ids IS NULL
          OR touch_point_id = ANY(final_tp_ids)
          OR (COALESCE(_source, 'all') IN ('direct', 'all') AND touch_point_id IS NULL)
      )
      AND (_start_date IS NULL OR created_at >= _start_date)
      AND (_end_date IS NULL OR created_at <= _end_date)
      AND (
          _source IS NULL OR _source = 'all'
          OR (_source = 'direct'     AND touch_point_id IS NULL)
          OR (_source = 'attributed' AND touch_point_id IS NOT NULL)
      )
      AND (_event_names IS NULL OR array_length(_event_names, 1) IS NULL OR event_name = ANY(_event_names));

    SELECT COUNT(*) INTO customers_count
    FROM customer_profiles
    WHERE organization_id = _organization_id
      AND (
          final_tp_ids IS NULL
          OR first_touch_point_id = ANY(final_tp_ids)
          OR (COALESCE(_source, 'all') IN ('direct', 'all') AND first_touch_point_id IS NULL)
      )
      AND (_start_date IS NULL OR created_at >= _start_date)
      AND (_end_date IS NULL OR created_at <= _end_date)
      AND (
          _source IS NULL OR _source = 'all'
          OR (_source = 'direct'     AND first_touch_point_id IS NULL)
          OR (_source = 'attributed' AND first_touch_point_id IS NOT NULL)
      );

    SELECT COUNT(*) INTO sales_count
    FROM conversion_events
    WHERE organization_id = _organization_id
      AND event_type = 'sale'
      AND (
          final_tp_ids IS NULL
          OR touch_point_id = ANY(final_tp_ids)
          OR (COALESCE(_source, 'all') IN ('direct', 'all') AND touch_point_id IS NULL)
      )
      AND (_start_date IS NULL OR created_at >= _start_date)
      AND (_end_date IS NULL OR created_at <= _end_date)
      AND (
          _source IS NULL OR _source = 'all'
          OR (_source = 'direct'     AND touch_point_id IS NULL)
          OR (_source = 'attributed' AND touch_point_id IS NOT NULL)
      )
      AND (_event_names IS NULL OR array_length(_event_names, 1) IS NULL OR event_name = ANY(_event_names));

    WITH revenue_by_currency AS (
        SELECT
            COALESCE(ce.currency, default_currency) AS currency,
            SUM(COALESCE(ce.amount, 0)) AS total_amount
        FROM conversion_events ce
        WHERE ce.organization_id = _organization_id
          AND ce.event_type = 'sale'
          AND ce.amount IS NOT NULL
          AND (
              final_tp_ids IS NULL
              OR ce.touch_point_id = ANY(final_tp_ids)
              OR (COALESCE(_source, 'all') IN ('direct', 'all') AND ce.touch_point_id IS NULL)
          )
          AND (_start_date IS NULL OR ce.created_at >= _start_date)
          AND (_end_date IS NULL OR ce.created_at <= _end_date)
          AND (
              _source IS NULL OR _source = 'all'
              OR (_source = 'direct'     AND ce.touch_point_id IS NULL)
              OR (_source = 'attributed' AND ce.touch_point_id IS NOT NULL)
          )
          AND (_event_names IS NULL OR array_length(_event_names, 1) IS NULL OR ce.event_name = ANY(_event_names))
        GROUP BY ce.currency
    )
    SELECT jsonb_object_agg(COALESCE(UPPER(currency), UPPER(default_currency)), total_amount)
    INTO revenue_data FROM revenue_by_currency;

    SELECT jsonb_build_object(
        'leads', leads_count,
        'customers', customers_count,
        'sales', sales_count,
        'revenue_by_currency', COALESCE(revenue_data, '{}'::jsonb),
        'default_currency', default_currency
    ) INTO result;

    RETURN result;
END;
$$;


--
-- Name: get_conversion_stats_v3(uuid, uuid[], uuid[], uuid[], uuid[], timestamp without time zone, timestamp without time zone, boolean, text, text[], text[], text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_conversion_stats_v3(_organization_id uuid, _viewable_tp_ids uuid[] DEFAULT NULL::uuid[], _tp_ids uuid[] DEFAULT NULL::uuid[], _tag_ids uuid[] DEFAULT NULL::uuid[], _collection_ids uuid[] DEFAULT NULL::uuid[], _start_date timestamp without time zone DEFAULT NULL::timestamp without time zone, _end_date timestamp without time zone DEFAULT NULL::timestamp without time zone, _exclude_bot boolean DEFAULT false, _source text DEFAULT NULL::text, _event_names text[] DEFAULT NULL::text[], _utm_sources text[] DEFAULT NULL::text[], _channels text[] DEFAULT NULL::text[]) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    result              jsonb;
    tp_ids_from_tags    uuid[];
    tp_ids_from_collections uuid[];
    final_tp_ids        uuid[];
    leads_count         bigint;
    customers_count     bigint;
    sales_count         bigint;
    revenue_data        jsonb;
    default_currency    text;
    utm_filter_active   boolean;
    matched_click_ids   text[];
    matched_session_ids text[];
BEGIN
    -- ── touch-point resolution (unchanged from v2) ──────────────────────────
    final_tp_ids := _viewable_tp_ids;

    IF _tp_ids IS NOT NULL AND array_length(_tp_ids, 1) > 0 THEN
        IF final_tp_ids IS NOT NULL THEN
            SELECT array_agg(DISTINCT tp_id) INTO final_tp_ids
            FROM unnest(final_tp_ids) AS tp_id WHERE tp_id = ANY(_tp_ids);
        ELSE
            final_tp_ids := _tp_ids;
        END IF;
    END IF;

    IF _tag_ids IS NOT NULL AND array_length(_tag_ids, 1) > 0 THEN
        SELECT array_agg(DISTINCT tp_id) INTO tp_ids_from_tags
        FROM tp_tag_links WHERE tag_id = ANY(_tag_ids);
        IF final_tp_ids IS NOT NULL THEN
            SELECT array_agg(DISTINCT tp_id) INTO final_tp_ids
            FROM unnest(final_tp_ids) AS tp_id WHERE tp_id = ANY(tp_ids_from_tags);
        ELSE
            final_tp_ids := tp_ids_from_tags;
        END IF;
    END IF;

    IF _collection_ids IS NOT NULL AND array_length(_collection_ids, 1) > 0 THEN
        SELECT array_agg(DISTINCT id) INTO tp_ids_from_collections
        FROM touch_points WHERE collection_id = ANY(_collection_ids);
        IF final_tp_ids IS NOT NULL THEN
            SELECT array_agg(DISTINCT tp_id) INTO final_tp_ids
            FROM unnest(final_tp_ids) AS tp_id WHERE tp_id = ANY(tp_ids_from_collections);
        ELSE
            final_tp_ids := tp_ids_from_collections;
        END IF;
    END IF;

    SELECT COALESCE(o.default_currency, 'USD') INTO default_currency
    FROM organizations o WHERE o.id = _organization_id;

    -- ── UTM/channel: resolve once, reuse across all queries ─────────────────
    utm_filter_active := (
        (_utm_sources IS NOT NULL AND array_length(_utm_sources, 1) > 0)
        OR (_channels  IS NOT NULL AND array_length(_channels,  1) > 0)
    );

    IF utm_filter_active THEN
        -- click_id path: conversion came via a short-link visit
        SELECT array_agg(DISTINCT li2_cid) INTO matched_click_ids
        FROM visits
        WHERE organization_id = _organization_id
          AND li2_cid IS NOT NULL
          AND (_utm_sources IS NULL OR array_length(_utm_sources, 1) IS NULL OR utm_tags->>'utm_source' = ANY(_utm_sources))
          AND (_channels    IS NULL OR array_length(_channels,    1) IS NULL OR channel                = ANY(_channels));

        -- session_id path: direct conversion (no short-link click)
        SELECT array_agg(DISTINCT session_id) INTO matched_session_ids
        FROM sessions
        WHERE organization_id = _organization_id
          AND session_id IS NOT NULL
          AND (_utm_sources IS NULL OR array_length(_utm_sources, 1) IS NULL OR utm_source = ANY(_utm_sources))
          AND (_channels    IS NULL OR array_length(_channels,    1) IS NULL OR channel    = ANY(_channels));

        -- ensure empty arrays rather than NULL so zero-match returns 0 counts
        IF matched_click_ids   IS NULL THEN matched_click_ids   := '{}'; END IF;
        IF matched_session_ids IS NULL THEN matched_session_ids := '{}'; END IF;
    END IF;

    -- ── counts ───────────────────────────────────────────────────────────────
    SELECT COUNT(*) INTO leads_count
    FROM conversion_events
    WHERE organization_id = _organization_id
      AND event_type = 'lead'
      AND (
          final_tp_ids IS NULL
          OR touch_point_id = ANY(final_tp_ids)
          OR (COALESCE(_source, 'all') IN ('direct', 'all') AND touch_point_id IS NULL)
      )
      AND (_start_date IS NULL OR created_at >= _start_date)
      AND (_end_date   IS NULL OR created_at <= _end_date)
      AND (
          _source IS NULL OR _source = 'all'
          OR (_source = 'direct'     AND touch_point_id IS NULL)
          OR (_source = 'attributed' AND touch_point_id IS NOT NULL)
      )
      AND (_event_names IS NULL OR array_length(_event_names, 1) IS NULL OR event_name = ANY(_event_names))
      AND (
          NOT utm_filter_active
          OR click_id   = ANY(matched_click_ids)
          OR session_id = ANY(matched_session_ids)
      );

    -- customer_profiles has no click_id/session_id; not filtered by UTM/channel
    SELECT COUNT(*) INTO customers_count
    FROM customer_profiles
    WHERE organization_id = _organization_id
      AND (
          final_tp_ids IS NULL
          OR first_touch_point_id = ANY(final_tp_ids)
          OR (COALESCE(_source, 'all') IN ('direct', 'all') AND first_touch_point_id IS NULL)
      )
      AND (_start_date IS NULL OR created_at >= _start_date)
      AND (_end_date   IS NULL OR created_at <= _end_date)
      AND (
          _source IS NULL OR _source = 'all'
          OR (_source = 'direct'     AND first_touch_point_id IS NULL)
          OR (_source = 'attributed' AND first_touch_point_id IS NOT NULL)
      );

    SELECT COUNT(*) INTO sales_count
    FROM conversion_events
    WHERE organization_id = _organization_id
      AND event_type = 'sale'
      AND (
          final_tp_ids IS NULL
          OR touch_point_id = ANY(final_tp_ids)
          OR (COALESCE(_source, 'all') IN ('direct', 'all') AND touch_point_id IS NULL)
      )
      AND (_start_date IS NULL OR created_at >= _start_date)
      AND (_end_date   IS NULL OR created_at <= _end_date)
      AND (
          _source IS NULL OR _source = 'all'
          OR (_source = 'direct'     AND touch_point_id IS NULL)
          OR (_source = 'attributed' AND touch_point_id IS NOT NULL)
      )
      AND (_event_names IS NULL OR array_length(_event_names, 1) IS NULL OR event_name = ANY(_event_names))
      AND (
          NOT utm_filter_active
          OR click_id   = ANY(matched_click_ids)
          OR session_id = ANY(matched_session_ids)
      );

    WITH revenue_by_currency AS (
        SELECT
            COALESCE(ce.currency, default_currency) AS currency,
            SUM(COALESCE(ce.amount, 0)) AS total_amount
        FROM conversion_events ce
        WHERE ce.organization_id = _organization_id
          AND ce.event_type = 'sale'
          AND ce.amount IS NOT NULL
          AND (
              final_tp_ids IS NULL
              OR ce.touch_point_id = ANY(final_tp_ids)
              OR (COALESCE(_source, 'all') IN ('direct', 'all') AND ce.touch_point_id IS NULL)
          )
          AND (_start_date IS NULL OR ce.created_at >= _start_date)
          AND (_end_date   IS NULL OR ce.created_at <= _end_date)
          AND (
              _source IS NULL OR _source = 'all'
              OR (_source = 'direct'     AND ce.touch_point_id IS NULL)
              OR (_source = 'attributed' AND ce.touch_point_id IS NOT NULL)
          )
          AND (_event_names IS NULL OR array_length(_event_names, 1) IS NULL OR ce.event_name = ANY(_event_names))
          AND (
              NOT utm_filter_active
              OR ce.click_id   = ANY(matched_click_ids)
              OR ce.session_id = ANY(matched_session_ids)
          )
        GROUP BY ce.currency
    )
    SELECT jsonb_object_agg(COALESCE(UPPER(currency), UPPER(default_currency)), total_amount)
    INTO revenue_data FROM revenue_by_currency;

    SELECT jsonb_build_object(
        'leads',              leads_count,
        'customers',          customers_count,
        'sales',              sales_count,
        'revenue_by_currency', COALESCE(revenue_data, '{}'::jsonb),
        'default_currency',   default_currency
    ) INTO result;

    RETURN result;
END;
$$;


--
-- Name: get_dashboard_analytics(uuid, text, text[], boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_dashboard_analytics(_organization_id uuid, _timezone text DEFAULT 'UTC'::text, _collection_ids text[] DEFAULT NULL::text[], _include_null_collection boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
  result JSONB;

  current_timestamp_tz TIMESTAMPTZ;
  today_start TIMESTAMPTZ;
  today_end   TIMESTAMPTZ;
  last_day_start TIMESTAMPTZ;
  last_day_end   TIMESTAMPTZ;
  last_week_start TIMESTAMPTZ;
  last_week_end   TIMESTAMPTZ;
  last_month_start TIMESTAMPTZ;
  last_month_end   TIMESTAMPTZ;

  -- rolling 7-day windows for WoW
  curr7_start TIMESTAMPTZ;
  curr7_end   TIMESTAMPTZ;
  prev7_start TIMESTAMPTZ;
  prev7_end   TIMESTAMPTZ;

  curr7_total BIGINT;
  prev7_total BIGINT;
  curr7_unique BIGINT;
  prev7_unique BIGINT;

  pct_total NUMERIC;
  pct_unique NUMERIC;

  -- NEW: filtered touch-point IDs based on collection access
  filtered_tp_ids UUID[];
  has_collection_filter BOOLEAN;
  collection_ids_uuid UUID[];  -- Cast text[] to uuid[] for comparison
BEGIN
  -- timezone
  EXECUTE format('SET TIME ZONE %L', _timezone);
  current_timestamp_tz := NOW();

  -- ranges you already had
  today_start := DATE_TRUNC('day', current_timestamp_tz);
  today_end   := current_timestamp_tz;

  last_day_start := DATE_TRUNC('day', current_timestamp_tz - INTERVAL '1 day');
  last_day_end   := last_day_start + INTERVAL '1 day' - INTERVAL '1 microsecond';

  last_week_start := DATE_TRUNC('week', current_timestamp_tz) - INTERVAL '7 days';
  last_week_end   := last_week_start + INTERVAL '7 days' - INTERVAL '1 microsecond';

  last_month_start := DATE_TRUNC('month', current_timestamp_tz - INTERVAL '1 month');
  last_month_end   := DATE_TRUNC('month', current_timestamp_tz) - INTERVAL '1 microsecond';

  -- WoW 7d rolling windows (now -> now-7d vs previous 7d)
  curr7_end   := current_timestamp_tz;
  curr7_start := curr7_end - INTERVAL '7 days';
  prev7_end   := curr7_start;
  prev7_start := prev7_end - INTERVAL '7 days';

  -- NEW: Check if collection filtering is needed
  has_collection_filter := _collection_ids IS NOT NULL AND array_length(_collection_ids, 1) > 0;

  -- NEW: Cast text[] to uuid[] for comparison
  IF has_collection_filter THEN
    collection_ids_uuid := ARRAY(SELECT unnest(_collection_ids)::uuid);
  END IF;

  -- NEW: Apply collection filtering to get allowed touch-point IDs
  IF has_collection_filter THEN
    SELECT COALESCE(array_agg(DISTINCT id), ARRAY[]::uuid[]) INTO filtered_tp_ids
    FROM touch_points
    WHERE organization_id = _organization_id
    AND (
      -- Touch-points in specified collections (use uuid[] for comparison)
      collection_id = ANY(collection_ids_uuid)
      -- OR uncategorized touch-points (if includeNull is true)
      OR (
        _include_null_collection = true
        AND collection_id IS NULL
      )
    );
  END IF;

  -- compute WoW totals (with collection filtering)
  SELECT COUNT(*)
  INTO curr7_total
  FROM visits
  WHERE organization_id = _organization_id
    AND created_at >= curr7_start AND created_at < curr7_end
    AND (NOT has_collection_filter OR tp_id = ANY(filtered_tp_ids));

  SELECT COUNT(*)
  INTO prev7_total
  FROM visits
  WHERE organization_id = _organization_id
    AND created_at >= prev7_start AND created_at < prev7_end
    AND (NOT has_collection_filter OR tp_id = ANY(filtered_tp_ids));

  SELECT COUNT(DISTINCT fp)
  INTO curr7_unique
  FROM visits
  WHERE organization_id = _organization_id
    AND fp IS NOT NULL
    AND created_at >= curr7_start AND created_at < curr7_end
    AND (NOT has_collection_filter OR tp_id = ANY(filtered_tp_ids));

  SELECT COUNT(DISTINCT fp)
  INTO prev7_unique
  FROM visits
  WHERE organization_id = _organization_id
    AND fp IS NOT NULL
    AND created_at >= prev7_start AND created_at < prev7_end
    AND (NOT has_collection_filter OR tp_id = ANY(filtered_tp_ids));

  -- percent changes (signed)
  pct_total := CASE
    WHEN prev7_total > 0 THEN ((curr7_total - prev7_total)::numeric * 100.0) / prev7_total
    WHEN prev7_total = 0 AND curr7_total > 0 THEN 100
    ELSE 0
  END;

  pct_unique := CASE
    WHEN prev7_unique > 0 THEN ((curr7_unique - prev7_unique)::numeric * 100.0) / prev7_unique
    WHEN prev7_unique = 0 AND curr7_unique > 0 THEN 100
    ELSE 0
  END;

  -- When collection filter is applied, bypass visits_by_organization view
  -- and query visits table directly
  IF has_collection_filter THEN
    WITH
    all_visits AS (
      SELECT *
      FROM visits
      WHERE organization_id = _organization_id
        AND created_at >= (last_month_start - INTERVAL '1 day')
        AND tp_id = ANY(filtered_tp_ids)
    ),
    type_visits_filtered AS (
      SELECT
        COALESCE(type, 'unknown') AS visit_type,
        COUNT(*) AS visit_count
      FROM visits
      WHERE organization_id = _organization_id
        AND tp_id = ANY(filtered_tp_ids)
      GROUP BY type
      ORDER BY visit_count DESC
    ),
    today_performance AS (
      SELECT DATE_TRUNC('hour', created_at) AS time_period, COUNT(*) AS visit_count
      FROM all_visits
      WHERE created_at >= today_start AND created_at <= today_end
      GROUP BY time_period
      ORDER BY time_period
    ),
    last_day_performance AS (
      SELECT DATE_TRUNC('hour', created_at) AS time_period, COUNT(*) AS visit_count
      FROM all_visits
      WHERE created_at >= last_day_start AND created_at <= last_day_end
      GROUP BY time_period
      ORDER BY time_period
    ),
    last_week_performance AS (
      SELECT DATE(created_at) AS time_period, COUNT(*) AS visit_count
      FROM all_visits
      WHERE created_at >= last_week_start AND created_at <= last_week_end
      GROUP BY time_period
      ORDER BY time_period
    ),
    last_month_performance AS (
      SELECT DATE(created_at) AS time_period, COUNT(*) AS visit_count
      FROM all_visits
      WHERE created_at >= last_month_start AND created_at <= last_month_end
      GROUP BY time_period
      ORDER BY time_period
    )
    SELECT jsonb_build_object(
      'typeVisits', COALESCE((
        SELECT jsonb_agg(jsonb_build_object('name', visit_type, 'count', visit_count))
        FROM type_visits_filtered
      ), '[]'::jsonb),
      'performanceOverTime', jsonb_build_object(
        'today', COALESCE((
          SELECT jsonb_agg(jsonb_build_object('name', time_period, 'count', visit_count))
          FROM today_performance
        ), '[]'::jsonb),
        'lastDay', COALESCE((
          SELECT jsonb_agg(jsonb_build_object('name', time_period, 'count', visit_count))
          FROM last_day_performance
        ), '[]'::jsonb),
        'lastWeek', COALESCE((
          SELECT jsonb_agg(jsonb_build_object('name', time_period, 'count', visit_count))
          FROM last_week_performance
        ), '[]'::jsonb),
        'lastMonth', COALESCE((
          SELECT jsonb_agg(jsonb_build_object('name', time_period, 'count', visit_count))
          FROM last_month_performance
        ), '[]'::jsonb)
      ),
      'totalVisits', (
        SELECT COUNT(*)
        FROM visits
        WHERE organization_id = _organization_id
          AND tp_id = ANY(filtered_tp_ids)
      ),
      'totalUniqueVisits', (
        SELECT COUNT(DISTINCT fp)
        FROM visits
        WHERE organization_id = _organization_id
          AND fp IS NOT NULL
          AND tp_id = ANY(filtered_tp_ids)
      ),
      'totalVisitWoWPercent', pct_total,
      'uniqueVisitWoWPercent', pct_unique,
      'debug', jsonb_build_object(
        'timezone', _timezone,
        'curr7_start', curr7_start, 'curr7_end', curr7_end,
        'prev7_start', prev7_start, 'prev7_end', prev7_end,
        'has_collection_filter', has_collection_filter,
        'collection_ids_input', _collection_ids,
        'collection_ids_uuid', collection_ids_uuid::text[],
        'filtered_tp_ids', filtered_tp_ids::text[],
        'filtered_tp_count', COALESCE(array_length(filtered_tp_ids, 1), 0)
      )
    )
    INTO result;
  ELSE
    -- No collection filter - use original logic with visits_by_organization view
    WITH
    all_visits AS (
      SELECT *
      FROM visits
      WHERE organization_id = _organization_id
        AND created_at >= (last_month_start - INTERVAL '1 day')
    ),
    type_visits AS (
      SELECT
        (jsonb_array_elements(type)->>'type') AS visit_type,
        (jsonb_array_elements(type)->>'count')::INTEGER AS visit_count,
        total AS total_visits
      FROM visits_by_organization
      WHERE organization_id = _organization_id
    ),
    today_performance AS (
      SELECT DATE_TRUNC('hour', created_at) AS time_period, COUNT(*) AS visit_count
      FROM all_visits
      WHERE created_at >= today_start AND created_at <= today_end
      GROUP BY time_period
      ORDER BY time_period
    ),
    last_day_performance AS (
      SELECT DATE_TRUNC('hour', created_at) AS time_period, COUNT(*) AS visit_count
      FROM all_visits
      WHERE created_at >= last_day_start AND created_at <= last_day_end
      GROUP BY time_period
      ORDER BY time_period
    ),
    last_week_performance AS (
      SELECT DATE(created_at) AS time_period, COUNT(*) AS visit_count
      FROM all_visits
      WHERE created_at >= last_week_start AND created_at <= last_week_end
      GROUP BY time_period
      ORDER BY time_period
    ),
    last_month_performance AS (
      SELECT DATE(created_at) AS time_period, COUNT(*) AS visit_count
      FROM all_visits
      WHERE created_at >= last_month_start AND created_at <= last_month_end
      GROUP BY time_period
      ORDER BY time_period
    )
    SELECT jsonb_build_object(
      'typeVisits', (
        SELECT jsonb_agg(jsonb_build_object('name', visit_type, 'count', visit_count))
        FROM type_visits
      ),
      'performanceOverTime', jsonb_build_object(
        'today', (
          SELECT jsonb_agg(jsonb_build_object('name', time_period, 'count', visit_count))
          FROM today_performance
        ),
        'lastDay', (
          SELECT jsonb_agg(jsonb_build_object('name', time_period, 'count', visit_count))
          FROM last_day_performance
        ),
        'lastWeek', (
          SELECT jsonb_agg(jsonb_build_object('name', time_period, 'count', visit_count))
          FROM last_week_performance
        ),
        'lastMonth', (
          SELECT jsonb_agg(jsonb_build_object('name', time_period, 'count', visit_count))
          FROM last_month_performance
        )
      ),
      'totalVisits', (SELECT total_visits FROM type_visits LIMIT 1),
      'totalUniqueVisits', (
        SELECT COUNT(DISTINCT fp)
        FROM visits
        WHERE organization_id = _organization_id
          AND fp IS NOT NULL
      ),
      'totalVisitWoWPercent', pct_total,
      'uniqueVisitWoWPercent', pct_unique,
      'debug', jsonb_build_object(
        'timezone', _timezone,
        'curr7_start', curr7_start, 'curr7_end', curr7_end,
        'prev7_start', prev7_start, 'prev7_end', prev7_end
      )
    )
    INTO result;
  END IF;

  RETURN COALESCE(result, '{}'::jsonb);
END;
$$;


--
-- Name: FUNCTION get_dashboard_analytics(_organization_id uuid, _timezone text, _collection_ids text[], _include_null_collection boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_dashboard_analytics(_organization_id uuid, _timezone text, _collection_ids text[], _include_null_collection boolean) IS 'Get dashboard analytics with optional filtering by collections (spaces).
Supports filtering by collection IDs to restrict data visibility for Viewers.
Use _collection_ids with _include_null_collection to control visibility of uncategorized touch-points.
When collection filter is applied, bypasses visits_by_organization view and queries visits table directly.';


--
-- Name: get_dashboard_analytics_old(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_dashboard_analytics_old(_organization_id uuid, _timezone text DEFAULT 'UTC'::text) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$DECLARE
  result JSONB;

  current_timestamp_tz TIMESTAMPTZ;
  today_start TIMESTAMPTZ;
  today_end   TIMESTAMPTZ;
  last_day_start TIMESTAMPTZ;
  last_day_end   TIMESTAMPTZ;
  last_week_start TIMESTAMPTZ;
  last_week_end   TIMESTAMPTZ;
  last_month_start TIMESTAMPTZ;
  last_month_end   TIMESTAMPTZ;

  -- rolling 7-day windows for WoW
  curr7_start TIMESTAMPTZ;
  curr7_end   TIMESTAMPTZ;
  prev7_start TIMESTAMPTZ;
  prev7_end   TIMESTAMPTZ;

  curr7_total BIGINT;
  prev7_total BIGINT;
  curr7_unique BIGINT;
  prev7_unique BIGINT;

  pct_total NUMERIC;
  pct_unique NUMERIC;
BEGIN
  -- timezone
  EXECUTE format('SET TIME ZONE %L', _timezone);
  current_timestamp_tz := NOW();

  -- ranges you already had
  today_start := DATE_TRUNC('day', current_timestamp_tz);
  today_end   := current_timestamp_tz;

  last_day_start := DATE_TRUNC('day', current_timestamp_tz - INTERVAL '1 day');
  last_day_end   := last_day_start + INTERVAL '1 day' - INTERVAL '1 microsecond';

  last_week_start := DATE_TRUNC('week', current_timestamp_tz) - INTERVAL '7 days';
  last_week_end   := last_week_start + INTERVAL '7 days' - INTERVAL '1 microsecond';

  last_month_start := DATE_TRUNC('month', current_timestamp_tz - INTERVAL '1 month');
  last_month_end   := DATE_TRUNC('month', current_timestamp_tz) - INTERVAL '1 microsecond';

  -- WoW 7d rolling windows (now -> now-7d vs previous 7d)
  curr7_end   := current_timestamp_tz;
  curr7_start := curr7_end - INTERVAL '7 days';
  prev7_end   := curr7_start;
  prev7_start := prev7_end - INTERVAL '7 days';

  -- compute WoW totals
  SELECT COUNT(*)
  INTO curr7_total
  FROM visits
  WHERE organization_id = _organization_id
    AND created_at >= curr7_start AND created_at < curr7_end;

  SELECT COUNT(*)
  INTO prev7_total
  FROM visits
  WHERE organization_id = _organization_id
    AND created_at >= prev7_start AND created_at < prev7_end;

  SELECT COUNT(DISTINCT fp)
  INTO curr7_unique
  FROM visits
  WHERE organization_id = _organization_id
    AND fp IS NOT NULL
    AND created_at >= curr7_start AND created_at < curr7_end;

  SELECT COUNT(DISTINCT fp)
  INTO prev7_unique
  FROM visits
  WHERE organization_id = _organization_id
    AND fp IS NOT NULL
    AND created_at >= prev7_start AND created_at < prev7_end;

  -- percent changes (signed)
  pct_total := CASE
    WHEN prev7_total > 0 THEN ((curr7_total - prev7_total)::numeric * 100.0) / prev7_total
    WHEN prev7_total = 0 AND curr7_total > 0 THEN 100
    ELSE 0
  END;

  pct_unique := CASE
    WHEN prev7_unique > 0 THEN ((curr7_unique - prev7_unique)::numeric * 100.0) / prev7_unique
    WHEN prev7_unique = 0 AND curr7_unique > 0 THEN 100
    ELSE 0
  END;

  WITH
  all_visits AS (
    SELECT *
    FROM visits
    WHERE organization_id = _organization_id
      AND created_at >= (last_month_start - INTERVAL '1 day')
  ),
  type_visits AS (
    SELECT 
      (jsonb_array_elements(type)->>'type') AS visit_type,
      (jsonb_array_elements(type)->>'count')::INTEGER AS visit_count,
      total AS total_visits
    FROM visits_by_organization
    WHERE organization_id = _organization_id
  ),
  today_performance AS (
    SELECT DATE_TRUNC('hour', created_at) AS time_period, COUNT(*) AS visit_count
    FROM all_visits
    WHERE created_at >= today_start AND created_at <= today_end
    GROUP BY time_period
    ORDER BY time_period
  ),
  last_day_performance AS (
    SELECT DATE_TRUNC('hour', created_at) AS time_period, COUNT(*) AS visit_count
    FROM all_visits
    WHERE created_at >= last_day_start AND created_at <= last_day_end
    GROUP BY time_period
    ORDER BY time_period
  ),
  last_week_performance AS (
    SELECT DATE(created_at) AS time_period, COUNT(*) AS visit_count
    FROM all_visits
    WHERE created_at >= last_week_start AND created_at <= last_week_end
    GROUP BY time_period
    ORDER BY time_period
  ),
  last_month_performance AS (
    SELECT DATE(created_at) AS time_period, COUNT(*) AS visit_count
    FROM all_visits
    WHERE created_at >= last_month_start AND created_at <= last_month_end
    GROUP BY time_period
    ORDER BY time_period
  )
  SELECT jsonb_build_object(
    'typeVisits', (
      SELECT jsonb_agg(jsonb_build_object('name', visit_type, 'count', visit_count))
      FROM type_visits
    ),
    'performanceOverTime', jsonb_build_object(
      'today', (
        SELECT jsonb_agg(jsonb_build_object('name', time_period, 'count', visit_count))
        FROM today_performance
      ),
      'lastDay', (
        SELECT jsonb_agg(jsonb_build_object('name', time_period, 'count', visit_count))
        FROM last_day_performance
      ),
      'lastWeek', (
        SELECT jsonb_agg(jsonb_build_object('name', time_period, 'count', visit_count))
        FROM last_week_performance
      ),
      'lastMonth', (
        SELECT jsonb_agg(jsonb_build_object('name', time_period, 'count', visit_count))
        FROM last_month_performance
      )
    ),
    'totalVisits', (SELECT total_visits FROM type_visits LIMIT 1),
    'totalUniqueVisits', (
      SELECT COUNT(DISTINCT fp)
      FROM visits
      WHERE organization_id = _organization_id
        AND fp IS NOT NULL
    ),

    -- NEW: percent change WoW (signed)
    'totalVisitWoWPercent', pct_total,
    'uniqueVisitWoWPercent', pct_unique,

    'debug', jsonb_build_object(
      'timezone', _timezone,
      'curr7_start', curr7_start, 'curr7_end', curr7_end,
      'prev7_start', prev7_start, 'prev7_end', prev7_end
    )
  )
  INTO result;

  RETURN COALESCE(result, '{}'::jsonb);
END;$$;


--
-- Name: get_dashboard_analytics_v3(uuid, text, text[], boolean, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_dashboard_analytics_v3(_organization_id uuid, _timezone text DEFAULT 'UTC'::text, _collection_ids text[] DEFAULT NULL::text[], _include_null_collection boolean DEFAULT true, _user_id uuid DEFAULT NULL::uuid, _exclude_bot boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
  result JSONB;

  current_timestamp_tz TIMESTAMPTZ;
  today_start TIMESTAMPTZ;
  today_end   TIMESTAMPTZ;
  last_day_start TIMESTAMPTZ;
  last_day_end   TIMESTAMPTZ;
  last_week_start TIMESTAMPTZ;
  last_week_end   TIMESTAMPTZ;
  last_month_start TIMESTAMPTZ;
  last_month_end   TIMESTAMPTZ;

  -- rolling 7-day windows for WoW
  curr7_start TIMESTAMPTZ;
  curr7_end   TIMESTAMPTZ;
  prev7_start TIMESTAMPTZ;
  prev7_end   TIMESTAMPTZ;

  curr7_total BIGINT;
  prev7_total BIGINT;
  curr7_unique BIGINT;
  prev7_unique BIGINT;

  pct_total NUMERIC;
  pct_unique NUMERIC;

  -- filtered touch-point IDs based on collection access
  filtered_tp_ids UUID[];
  has_collection_filter BOOLEAN;
  collection_ids_uuid UUID[];  -- Cast text[] to uuid[] for comparison
BEGIN
  -- Initialize
  filtered_tp_ids := NULL;
  has_collection_filter := false;

  -- timezone
  EXECUTE format('SET TIME ZONE %L', _timezone);
  current_timestamp_tz := NOW();

  -- ranges
  today_start := DATE_TRUNC('day', current_timestamp_tz);
  today_end   := current_timestamp_tz;

  last_day_start := DATE_TRUNC('day', current_timestamp_tz - INTERVAL '1 day');
  last_day_end   := last_day_start + INTERVAL '1 day' - INTERVAL '1 microsecond';

  last_week_start := DATE_TRUNC('week', current_timestamp_tz) - INTERVAL '7 days';
  last_week_end   := last_week_start + INTERVAL '7 days' - INTERVAL '1 microsecond';

  last_month_start := DATE_TRUNC('month', current_timestamp_tz - INTERVAL '1 month');
  last_month_end   := DATE_TRUNC('month', current_timestamp_tz) - INTERVAL '1 microsecond';

  -- WoW 7d rolling windows (now -> now-7d vs previous 7d)
  curr7_end   := current_timestamp_tz;
  curr7_start := curr7_end - INTERVAL '7 days';
  prev7_end   := curr7_start;
  prev7_start := prev7_end - INTERVAL '7 days';

  -- Check if collection filtering is needed
  -- Use IS NOT NULL to properly detect when filter was provided
  IF _collection_ids IS NOT NULL THEN
    has_collection_filter := true;

    -- Cast text[] to uuid[] safely
    IF array_length(_collection_ids, 1) IS NOT NULL THEN
      collection_ids_uuid := ARRAY(SELECT unnest(_collection_ids)::uuid);
    ELSE
      collection_ids_uuid := ARRAY[]::uuid[];
    END IF;

    -- Get allowed touch-point IDs based on collection access
    SELECT COALESCE(array_agg(DISTINCT id), ARRAY[]::uuid[]) INTO filtered_tp_ids
    FROM touch_points
    WHERE organization_id = _organization_id
    AND deleted_at IS NULL
    AND (
      -- Touch-points in specified collections
      collection_id = ANY(collection_ids_uuid)
      -- OR uncategorized touch-points owned by the user
      OR (
        _include_null_collection = true
        AND collection_id IS NULL
        AND user_id = _user_id
      )
    );
  END IF;

  -- compute WoW totals (with collection filtering AND bot filtering)
  SELECT COUNT(*)
  INTO curr7_total
  FROM visits
  WHERE organization_id = _organization_id
    AND created_at >= curr7_start AND created_at < curr7_end
    AND (
      CASE
        WHEN has_collection_filter THEN tp_id = ANY(filtered_tp_ids)
        ELSE TRUE
      END
    )
    AND (NOT _exclude_bot OR is_bot = FALSE);  -- NEW: Bot filtering

  SELECT COUNT(*)
  INTO prev7_total
  FROM visits
  WHERE organization_id = _organization_id
    AND created_at >= prev7_start AND created_at < prev7_end
    AND (
      CASE
        WHEN has_collection_filter THEN tp_id = ANY(filtered_tp_ids)
        ELSE TRUE
      END
    )
    AND (NOT _exclude_bot OR is_bot = FALSE);  -- NEW: Bot filtering

  SELECT COUNT(DISTINCT fp)
  INTO curr7_unique
  FROM visits
  WHERE organization_id = _organization_id
    AND fp IS NOT NULL
    AND created_at >= curr7_start AND created_at < curr7_end
    AND (
      CASE
        WHEN has_collection_filter THEN tp_id = ANY(filtered_tp_ids)
        ELSE TRUE
      END
    )
    AND (NOT _exclude_bot OR is_bot = FALSE);  -- NEW: Bot filtering

  SELECT COUNT(DISTINCT fp)
  INTO prev7_unique
  FROM visits
  WHERE organization_id = _organization_id
    AND fp IS NOT NULL
    AND created_at >= prev7_start AND created_at < prev7_end
    AND (
      CASE
        WHEN has_collection_filter THEN tp_id = ANY(filtered_tp_ids)
        ELSE TRUE
      END
    )
    AND (NOT _exclude_bot OR is_bot = FALSE);  -- NEW: Bot filtering

  -- percent changes (signed)
  pct_total := CASE
    WHEN prev7_total > 0 THEN ((curr7_total - prev7_total)::numeric * 100.0) / prev7_total
    WHEN prev7_total = 0 AND curr7_total > 0 THEN 100
    ELSE 0
  END;

  pct_unique := CASE
    WHEN prev7_unique > 0 THEN ((curr7_unique - prev7_unique)::numeric * 100.0) / prev7_unique
    WHEN prev7_unique = 0 AND curr7_unique > 0 THEN 100
    ELSE 0
  END;

  -- When collection filter is applied, bypass visits_by_organization view
  -- and query visits table directly
  IF has_collection_filter THEN
    WITH
    all_visits AS (
      SELECT *
      FROM visits
      WHERE organization_id = _organization_id
        AND created_at >= (last_month_start - INTERVAL '1 day')
        AND tp_id = ANY(filtered_tp_ids)
        AND (NOT _exclude_bot OR is_bot = FALSE)  -- NEW: Bot filtering
    ),
    type_visits_filtered AS (
      SELECT
        COALESCE(type, 'unknown') AS visit_type,
        COUNT(*) AS visit_count
      FROM visits
      WHERE organization_id = _organization_id
        AND tp_id = ANY(filtered_tp_ids)
        AND (NOT _exclude_bot OR is_bot = FALSE)  -- NEW: Bot filtering
      GROUP BY type
      ORDER BY visit_count DESC
    ),
    today_performance AS (
      SELECT DATE_TRUNC('hour', created_at) AS time_period, COUNT(*) AS visit_count
      FROM all_visits
      WHERE created_at >= today_start AND created_at <= today_end
      GROUP BY time_period
      ORDER BY time_period
    ),
    last_day_performance AS (
      SELECT DATE_TRUNC('hour', created_at) AS time_period, COUNT(*) AS visit_count
      FROM all_visits
      WHERE created_at >= last_day_start AND created_at <= last_day_end
      GROUP BY time_period
      ORDER BY time_period
    ),
    last_week_performance AS (
      SELECT DATE(created_at) AS time_period, COUNT(*) AS visit_count
      FROM all_visits
      WHERE created_at >= last_week_start AND created_at <= last_week_end
      GROUP BY time_period
      ORDER BY time_period
    ),
    last_month_performance AS (
      SELECT DATE(created_at) AS time_period, COUNT(*) AS visit_count
      FROM all_visits
      WHERE created_at >= last_month_start AND created_at <= last_month_end
      GROUP BY time_period
      ORDER BY time_period
    )
    SELECT jsonb_build_object(
      'typeVisits', COALESCE((
        SELECT jsonb_agg(jsonb_build_object('name', visit_type, 'count', visit_count))
        FROM type_visits_filtered
      ), '[]'::jsonb),
      'performanceOverTime', jsonb_build_object(
        'today', COALESCE((
          SELECT jsonb_agg(jsonb_build_object('name', time_period, 'count', visit_count))
          FROM today_performance
        ), '[]'::jsonb),
        'lastDay', COALESCE((
          SELECT jsonb_agg(jsonb_build_object('name', time_period, 'count', visit_count))
          FROM last_day_performance
        ), '[]'::jsonb),
        'lastWeek', COALESCE((
          SELECT jsonb_agg(jsonb_build_object('name', time_period, 'count', visit_count))
          FROM last_week_performance
        ), '[]'::jsonb),
        'lastMonth', COALESCE((
          SELECT jsonb_agg(jsonb_build_object('name', time_period, 'count', visit_count))
          FROM last_month_performance
        ), '[]'::jsonb)
      ),
      'totalVisits', (
        SELECT COUNT(*)
        FROM visits
        WHERE organization_id = _organization_id
          AND tp_id = ANY(filtered_tp_ids)
          AND (NOT _exclude_bot OR is_bot = FALSE)  -- NEW: Bot filtering
      ),
      'totalUniqueVisits', (
        SELECT COUNT(DISTINCT fp)
        FROM visits
        WHERE organization_id = _organization_id
          AND fp IS NOT NULL
          AND tp_id = ANY(filtered_tp_ids)
          AND (NOT _exclude_bot OR is_bot = FALSE)  -- NEW: Bot filtering
      ),
      'totalVisitWoWPercent', pct_total,
      'uniqueVisitWoWPercent', pct_unique,
      'debug', jsonb_build_object(
        'timezone', _timezone,
        'curr7_start', curr7_start, 'curr7_end', curr7_end,
        'prev7_start', prev7_start, 'prev7_end', prev7_end,
        'has_collection_filter', has_collection_filter,
        'collection_ids_input', _collection_ids,
        'collection_ids_uuid', collection_ids_uuid::text[],
        'filtered_tp_ids', filtered_tp_ids::text[],
        'filtered_tp_count', COALESCE(array_length(filtered_tp_ids, 1), 0),
        'exclude_bot', _exclude_bot  -- NEW: Debug info
      )
    )
    INTO result;
  ELSE
    -- No collection filter - query visits directly with bot filtering
    WITH
    all_visits AS (
      SELECT *
      FROM visits
      WHERE organization_id = _organization_id
        AND created_at >= (last_month_start - INTERVAL '1 day')
        AND (NOT _exclude_bot OR is_bot = FALSE)  -- NEW: Bot filtering
    ),
    type_visits AS (
      SELECT
        COALESCE(type, 'unknown') AS visit_type,
        COUNT(*) AS visit_count
      FROM visits
      WHERE organization_id = _organization_id
        AND (NOT _exclude_bot OR is_bot = FALSE)  -- NEW: Bot filtering
      GROUP BY type
      ORDER BY visit_count DESC
    ),
    today_performance AS (
      SELECT DATE_TRUNC('hour', created_at) AS time_period, COUNT(*) AS visit_count
      FROM all_visits
      WHERE created_at >= today_start AND created_at <= today_end
      GROUP BY time_period
      ORDER BY time_period
    ),
    last_day_performance AS (
      SELECT DATE_TRUNC('hour', created_at) AS time_period, COUNT(*) AS visit_count
      FROM all_visits
      WHERE created_at >= last_day_start AND created_at <= last_day_end
      GROUP BY time_period
      ORDER BY time_period
    ),
    last_week_performance AS (
      SELECT DATE(created_at) AS time_period, COUNT(*) AS visit_count
      FROM all_visits
      WHERE created_at >= last_week_start AND created_at <= last_week_end
      GROUP BY time_period
      ORDER BY time_period
    ),
    last_month_performance AS (
      SELECT DATE(created_at) AS time_period, COUNT(*) AS visit_count
      FROM all_visits
      WHERE created_at >= last_month_start AND created_at <= last_month_end
      GROUP BY time_period
      ORDER BY time_period
    ),
    total_visits_count AS (
      SELECT COUNT(*) AS total
      FROM visits
      WHERE organization_id = _organization_id
        AND (NOT _exclude_bot OR is_bot = FALSE)  -- NEW: Bot filtering
    )
    SELECT jsonb_build_object(
      'typeVisits', COALESCE((
        SELECT jsonb_agg(jsonb_build_object('name', visit_type, 'count', visit_count))
        FROM type_visits
      ), '[]'::jsonb),
      'performanceOverTime', jsonb_build_object(
        'today', COALESCE((
          SELECT jsonb_agg(jsonb_build_object('name', time_period, 'count', visit_count))
          FROM today_performance
        ), '[]'::jsonb),
        'lastDay', COALESCE((
          SELECT jsonb_agg(jsonb_build_object('name', time_period, 'count', visit_count))
          FROM last_day_performance
        ), '[]'::jsonb),
        'lastWeek', COALESCE((
          SELECT jsonb_agg(jsonb_build_object('name', time_period, 'count', visit_count))
          FROM last_week_performance
        ), '[]'::jsonb),
        'lastMonth', COALESCE((
          SELECT jsonb_agg(jsonb_build_object('name', time_period, 'count', visit_count))
          FROM last_month_performance
        ), '[]'::jsonb)
      ),
      'totalVisits', (SELECT total FROM total_visits_count),
      'totalUniqueVisits', (
        SELECT COUNT(DISTINCT fp)
        FROM visits
        WHERE organization_id = _organization_id
          AND fp IS NOT NULL
          AND (NOT _exclude_bot OR is_bot = FALSE)  -- NEW: Bot filtering
      ),
      'totalVisitWoWPercent', pct_total,
      'uniqueVisitWoWPercent', pct_unique,
      'debug', jsonb_build_object(
        'timezone', _timezone,
        'curr7_start', curr7_start, 'curr7_end', curr7_end,
        'prev7_start', prev7_start, 'prev7_end', prev7_end,
        'exclude_bot', _exclude_bot  -- NEW: Debug info
      )
    )
    INTO result;
  END IF;

  RETURN COALESCE(result, '{}'::jsonb);
END;
$$;


--
-- Name: FUNCTION get_dashboard_analytics_v3(_organization_id uuid, _timezone text, _collection_ids text[], _include_null_collection boolean, _user_id uuid, _exclude_bot boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_dashboard_analytics_v3(_organization_id uuid, _timezone text, _collection_ids text[], _include_null_collection boolean, _user_id uuid, _exclude_bot boolean) IS 'Get dashboard analytics with bot filtering and optional collection filtering.
V3 adds bot traffic filtering capability with _exclude_bot parameter (default: true).
Use _collection_ids with _include_null_collection to control visibility of uncategorized touch-points.
When collection filter is applied, bypasses visits_by_organization view and queries visits table directly.';


--
-- Name: get_deep_link_click_summary(uuid, uuid[], uuid[], uuid[], uuid[], timestamp with time zone, timestamp with time zone, text[], text[], text[], boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_deep_link_click_summary(_organization_id uuid, _viewable_tp_ids uuid[] DEFAULT NULL::uuid[], _tp_ids uuid[] DEFAULT NULL::uuid[], _tag_ids uuid[] DEFAULT NULL::uuid[], _collection_ids uuid[] DEFAULT NULL::uuid[], _start_date timestamp with time zone DEFAULT NULL::timestamp with time zone, _end_date timestamp with time zone DEFAULT NULL::timestamp with time zone, _utm_sources text[] DEFAULT NULL::text[], _utm_mediums text[] DEFAULT NULL::text[], _utm_campaigns text[] DEFAULT NULL::text[], _exclude_bot boolean DEFAULT false) RETURNS TABLE(clicks bigint, by_channel jsonb, by_segment_type jsonb)
    LANGUAGE plpgsql
    AS $$
DECLARE
    dl_tp_ids               uuid[];
    historical_tp_ids       uuid[];
    final_tp_ids            uuid[];
    tp_ids_from_tags        uuid[];
    tp_ids_from_collections uuid[];
BEGIN
    SELECT array_agg(DISTINCT tp.id) INTO dl_tp_ids
    FROM touch_points tp
    JOIN domains d ON d.id = tp.domain_id
    WHERE tp.organization_id = _organization_id
      AND d.is_verified = true
      AND d.deep_link_apps->>'enabled' = 'true'
      AND jsonb_array_length(d.deep_link_apps->'apps') > 0;

    IF dl_tp_ids IS NULL THEN
        dl_tp_ids := '{}';
    END IF;

    -- Per-link history augmentation (see migration header).
    IF _tp_ids IS NOT NULL AND array_length(_tp_ids, 1) > 0 THEN
        SELECT array_agg(DISTINCT e.touch_point_id) INTO historical_tp_ids
        FROM deep_link_events e
        WHERE e.organization_id = _organization_id
          AND e.touch_point_id = ANY(_tp_ids);
        IF historical_tp_ids IS NOT NULL THEN
            dl_tp_ids := ARRAY(SELECT DISTINCT unnest(dl_tp_ids || historical_tp_ids));
        END IF;
    END IF;

    final_tp_ids := dl_tp_ids;

    IF _viewable_tp_ids IS NOT NULL THEN
        SELECT array_agg(DISTINCT t) INTO final_tp_ids
        FROM unnest(final_tp_ids) AS t WHERE t = ANY(_viewable_tp_ids);
    END IF;

    IF _tp_ids IS NOT NULL AND array_length(_tp_ids, 1) > 0 THEN
        SELECT array_agg(DISTINCT t) INTO final_tp_ids
        FROM unnest(COALESCE(final_tp_ids, '{}')) AS t WHERE t = ANY(_tp_ids);
    END IF;

    IF _tag_ids IS NOT NULL AND array_length(_tag_ids, 1) > 0 THEN
        SELECT array_agg(DISTINCT tp_id) INTO tp_ids_from_tags
        FROM tp_tag_links WHERE tag_id = ANY(_tag_ids);
        SELECT array_agg(DISTINCT t) INTO final_tp_ids
        FROM unnest(COALESCE(final_tp_ids, '{}')) AS t WHERE t = ANY(COALESCE(tp_ids_from_tags, '{}'));
    END IF;

    IF _collection_ids IS NOT NULL AND array_length(_collection_ids, 1) > 0 THEN
        SELECT array_agg(DISTINCT id) INTO tp_ids_from_collections
        FROM touch_points WHERE collection_id = ANY(_collection_ids);
        SELECT array_agg(DISTINCT t) INTO final_tp_ids
        FROM unnest(COALESCE(final_tp_ids, '{}')) AS t WHERE t = ANY(COALESCE(tp_ids_from_collections, '{}'));
    END IF;

    IF final_tp_ids IS NULL THEN final_tp_ids := '{}'; END IF;

    RETURN QUERY
    WITH v AS (
        SELECT vi.channel, vi.segment_type
        FROM visits vi
        WHERE vi.organization_id = _organization_id
          AND vi.tp_id = ANY(final_tp_ids)
          AND (_start_date IS NULL OR vi.created_at >= _start_date)
          AND (_end_date   IS NULL OR vi.created_at <= _end_date)
          AND (_exclude_bot = false OR vi.is_bot = false)
          AND (_utm_sources   IS NULL OR array_length(_utm_sources,   1) IS NULL OR vi.utm_tags->>'utm_source'   = ANY(_utm_sources))
          AND (_utm_mediums   IS NULL OR array_length(_utm_mediums,   1) IS NULL OR vi.utm_tags->>'utm_medium'   = ANY(_utm_mediums))
          AND (_utm_campaigns IS NULL OR array_length(_utm_campaigns, 1) IS NULL OR vi.utm_tags->>'utm_campaign' = ANY(_utm_campaigns))
    )
    SELECT
        count(*)::bigint,
        (SELECT COALESCE(jsonb_object_agg(k, c), '{}'::jsonb)
           FROM (SELECT COALESCE(channel, 'Unknown') AS k, count(*) AS c FROM v GROUP BY 1) s),
        (SELECT COALESCE(jsonb_object_agg(k, c), '{}'::jsonb)
           FROM (SELECT COALESCE(segment_type, 'default') AS k, count(*) AS c FROM v GROUP BY 1) s)
    FROM v;
END;
$$;


--
-- Name: get_deep_link_click_timeseries(uuid, uuid[], uuid[], uuid[], uuid[], timestamp with time zone, timestamp with time zone, text[], text[], text[], boolean, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_deep_link_click_timeseries(_organization_id uuid, _viewable_tp_ids uuid[] DEFAULT NULL::uuid[], _tp_ids uuid[] DEFAULT NULL::uuid[], _tag_ids uuid[] DEFAULT NULL::uuid[], _collection_ids uuid[] DEFAULT NULL::uuid[], _start_date timestamp with time zone DEFAULT NULL::timestamp with time zone, _end_date timestamp with time zone DEFAULT NULL::timestamp with time zone, _utm_sources text[] DEFAULT NULL::text[], _utm_mediums text[] DEFAULT NULL::text[], _utm_campaigns text[] DEFAULT NULL::text[], _exclude_bot boolean DEFAULT false, _bucket text DEFAULT 'day'::text, _timezone text DEFAULT 'UTC'::text) RETURNS TABLE(bucket timestamp with time zone, clicks bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE
    dl_tp_ids               uuid[];
    historical_tp_ids       uuid[];
    final_tp_ids            uuid[];
    tp_ids_from_tags        uuid[];
    tp_ids_from_collections uuid[];
    _trunc                  text;
    _tz                     text;
BEGIN
    SELECT array_agg(DISTINCT tp.id) INTO dl_tp_ids
    FROM touch_points tp
    JOIN domains d ON d.id = tp.domain_id
    WHERE tp.organization_id = _organization_id
      AND d.is_verified = true
      AND d.deep_link_apps->>'enabled' = 'true'
      AND jsonb_array_length(d.deep_link_apps->'apps') > 0;

    IF dl_tp_ids IS NULL THEN
        dl_tp_ids := '{}';
    END IF;

    -- Per-link history augmentation (see migration header).
    IF _tp_ids IS NOT NULL AND array_length(_tp_ids, 1) > 0 THEN
        SELECT array_agg(DISTINCT e.touch_point_id) INTO historical_tp_ids
        FROM deep_link_events e
        WHERE e.organization_id = _organization_id
          AND e.touch_point_id = ANY(_tp_ids);
        IF historical_tp_ids IS NOT NULL THEN
            dl_tp_ids := ARRAY(SELECT DISTINCT unnest(dl_tp_ids || historical_tp_ids));
        END IF;
    END IF;

    final_tp_ids := dl_tp_ids;

    IF _viewable_tp_ids IS NOT NULL THEN
        SELECT array_agg(DISTINCT t) INTO final_tp_ids
        FROM unnest(final_tp_ids) AS t WHERE t = ANY(_viewable_tp_ids);
    END IF;

    IF _tp_ids IS NOT NULL AND array_length(_tp_ids, 1) > 0 THEN
        SELECT array_agg(DISTINCT t) INTO final_tp_ids
        FROM unnest(COALESCE(final_tp_ids, '{}')) AS t WHERE t = ANY(_tp_ids);
    END IF;

    IF _tag_ids IS NOT NULL AND array_length(_tag_ids, 1) > 0 THEN
        SELECT array_agg(DISTINCT tp_id) INTO tp_ids_from_tags
        FROM tp_tag_links WHERE tag_id = ANY(_tag_ids);
        SELECT array_agg(DISTINCT t) INTO final_tp_ids
        FROM unnest(COALESCE(final_tp_ids, '{}')) AS t WHERE t = ANY(COALESCE(tp_ids_from_tags, '{}'));
    END IF;

    IF _collection_ids IS NOT NULL AND array_length(_collection_ids, 1) > 0 THEN
        SELECT array_agg(DISTINCT id) INTO tp_ids_from_collections
        FROM touch_points WHERE collection_id = ANY(_collection_ids);
        SELECT array_agg(DISTINCT t) INTO final_tp_ids
        FROM unnest(COALESCE(final_tp_ids, '{}')) AS t WHERE t = ANY(COALESCE(tp_ids_from_collections, '{}'));
    END IF;

    IF final_tp_ids IS NULL THEN final_tp_ids := '{}'; END IF;

    _trunc := CASE WHEN _bucket = 'hour' THEN 'hour' ELSE 'day' END;
    _tz := COALESCE((SELECT name FROM pg_timezone_names WHERE name = _timezone), 'UTC');

    RETURN QUERY
    SELECT
        (date_trunc(_trunc, vi.created_at AT TIME ZONE _tz) AT TIME ZONE _tz),
        count(*)::bigint
    FROM visits vi
    WHERE vi.organization_id = _organization_id
      AND vi.tp_id = ANY(final_tp_ids)
      AND (_start_date IS NULL OR vi.created_at >= _start_date)
      AND (_end_date   IS NULL OR vi.created_at <= _end_date)
      AND (_exclude_bot = false OR vi.is_bot = false)
      AND (_utm_sources   IS NULL OR array_length(_utm_sources,   1) IS NULL OR vi.utm_tags->>'utm_source'   = ANY(_utm_sources))
      AND (_utm_mediums   IS NULL OR array_length(_utm_mediums,   1) IS NULL OR vi.utm_tags->>'utm_medium'   = ANY(_utm_mediums))
      AND (_utm_campaigns IS NULL OR array_length(_utm_campaigns, 1) IS NULL OR vi.utm_tags->>'utm_campaign' = ANY(_utm_campaigns))
    GROUP BY 1
    ORDER BY 1;
END;
$$;


--
-- Name: get_deep_link_ranking(uuid, text, uuid[], uuid[], uuid[], uuid[], timestamp with time zone, timestamp with time zone, text[], text[], text[], boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_deep_link_ranking(_organization_id uuid, _group_by text, _viewable_tp_ids uuid[] DEFAULT NULL::uuid[], _tp_ids uuid[] DEFAULT NULL::uuid[], _tag_ids uuid[] DEFAULT NULL::uuid[], _collection_ids uuid[] DEFAULT NULL::uuid[], _start_date timestamp with time zone DEFAULT NULL::timestamp with time zone, _end_date timestamp with time zone DEFAULT NULL::timestamp with time zone, _utm_sources text[] DEFAULT NULL::text[], _utm_mediums text[] DEFAULT NULL::text[], _utm_campaigns text[] DEFAULT NULL::text[], _exclude_bot boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    dl_tp_ids               uuid[];
    historical_tp_ids       uuid[];
    final_tp_ids            uuid[];
    tp_ids_from_tags        uuid[];
    tp_ids_from_collections uuid[];
BEGIN
    SELECT array_agg(DISTINCT tp.id) INTO dl_tp_ids
    FROM touch_points tp
    JOIN domains d ON d.id = tp.domain_id
    WHERE tp.organization_id = _organization_id
      AND d.is_verified = true
      AND d.deep_link_apps->>'enabled' = 'true'
      AND jsonb_array_length(d.deep_link_apps->'apps') > 0;
    IF dl_tp_ids IS NULL THEN dl_tp_ids := '{}'; END IF;

    -- Per-link history augmentation (see migration header).
    IF _tp_ids IS NOT NULL AND array_length(_tp_ids, 1) > 0 THEN
        SELECT array_agg(DISTINCT e.touch_point_id) INTO historical_tp_ids
        FROM deep_link_events e
        WHERE e.organization_id = _organization_id
          AND e.touch_point_id = ANY(_tp_ids);
        IF historical_tp_ids IS NOT NULL THEN
            dl_tp_ids := ARRAY(SELECT DISTINCT unnest(dl_tp_ids || historical_tp_ids));
        END IF;
    END IF;

    final_tp_ids := dl_tp_ids;

    IF _viewable_tp_ids IS NOT NULL THEN
        SELECT array_agg(DISTINCT t) INTO final_tp_ids
        FROM unnest(final_tp_ids) AS t WHERE t = ANY(_viewable_tp_ids);
    END IF;
    IF _tp_ids IS NOT NULL AND array_length(_tp_ids, 1) > 0 THEN
        SELECT array_agg(DISTINCT t) INTO final_tp_ids
        FROM unnest(COALESCE(final_tp_ids, '{}')) AS t WHERE t = ANY(_tp_ids);
    END IF;
    IF _tag_ids IS NOT NULL AND array_length(_tag_ids, 1) > 0 THEN
        SELECT array_agg(DISTINCT tp_id) INTO tp_ids_from_tags
        FROM tp_tag_links WHERE tag_id = ANY(_tag_ids);
        SELECT array_agg(DISTINCT t) INTO final_tp_ids
        FROM unnest(COALESCE(final_tp_ids, '{}')) AS t WHERE t = ANY(COALESCE(tp_ids_from_tags, '{}'));
    END IF;
    IF _collection_ids IS NOT NULL AND array_length(_collection_ids, 1) > 0 THEN
        SELECT array_agg(DISTINCT id) INTO tp_ids_from_collections
        FROM touch_points WHERE collection_id = ANY(_collection_ids);
        SELECT array_agg(DISTINCT t) INTO final_tp_ids
        FROM unnest(COALESCE(final_tp_ids, '{}')) AS t WHERE t = ANY(COALESCE(tp_ids_from_collections, '{}'));
    END IF;
    IF final_tp_ids IS NULL THEN final_tp_ids := '{}'; END IF;

    IF _group_by IN ('referrer', 'utm_source', 'utm_medium', 'utm_campaign') THEN
        RETURN (
            WITH v AS (
                SELECT CASE _group_by
                           WHEN 'referrer'     THEN COALESCE(NULLIF(vi.referrer, ''), 'direct')
                           WHEN 'utm_source'   THEN vi.utm_tags->>'utm_source'
                           WHEN 'utm_medium'   THEN vi.utm_tags->>'utm_medium'
                           WHEN 'utm_campaign' THEN vi.utm_tags->>'utm_campaign'
                       END AS k
                FROM visits vi
                WHERE vi.organization_id = _organization_id
                  AND vi.tp_id = ANY(final_tp_ids)
                  AND (_start_date IS NULL OR vi.created_at >= _start_date)
                  AND (_end_date   IS NULL OR vi.created_at <= _end_date)
                  AND (_exclude_bot = false OR vi.is_bot = false)
                  AND (_utm_sources   IS NULL OR array_length(_utm_sources,1)   IS NULL OR vi.utm_tags->>'utm_source'   = ANY(_utm_sources))
                  AND (_utm_mediums   IS NULL OR array_length(_utm_mediums,1)   IS NULL OR vi.utm_tags->>'utm_medium'   = ANY(_utm_mediums))
                  AND (_utm_campaigns IS NULL OR array_length(_utm_campaigns,1) IS NULL OR vi.utm_tags->>'utm_campaign' = ANY(_utm_campaigns))
            ),
            g AS (
                SELECT k, count(*) AS clicks
                FROM v WHERE k IS NOT NULL AND k <> ''
                GROUP BY k
                ORDER BY clicks DESC, k
                LIMIT 500
            )
            SELECT jsonb_build_object(
                'group_by', _group_by,
                'data', COALESCE(jsonb_agg(jsonb_build_object(
                            'key', g.k, 'name', g.k,
                            'clicks', g.clicks, 'direct_opens', 0, 'matched', 0)
                            ORDER BY g.clicks DESC, g.k), '[]'::jsonb),
                'total', (SELECT count(*) FROM v WHERE k IS NOT NULL AND k <> '')
            )
            FROM g
        );
    END IF;

    RETURN (
        WITH tp_clicks AS (
            SELECT vi.tp_id, count(*) AS clicks
            FROM visits vi
            WHERE vi.organization_id = _organization_id
              AND vi.tp_id = ANY(final_tp_ids)
              AND (_start_date IS NULL OR vi.created_at >= _start_date)
              AND (_end_date   IS NULL OR vi.created_at <= _end_date)
              AND (_exclude_bot = false OR vi.is_bot = false)
              AND (_utm_sources   IS NULL OR array_length(_utm_sources,1)   IS NULL OR vi.utm_tags->>'utm_source'   = ANY(_utm_sources))
              AND (_utm_mediums   IS NULL OR array_length(_utm_mediums,1)   IS NULL OR vi.utm_tags->>'utm_medium'   = ANY(_utm_mediums))
              AND (_utm_campaigns IS NULL OR array_length(_utm_campaigns,1) IS NULL OR vi.utm_tags->>'utm_campaign' = ANY(_utm_campaigns))
            GROUP BY vi.tp_id
        ),
        tp_events AS (
            SELECT e.touch_point_id,
                   count(*) FILTER (WHERE e.event_type = 'app_open')       AS direct_opens,
                   count(*) FILTER (WHERE e.event_type = 'deferred_match') AS matched
            FROM deep_link_events e
            WHERE e.organization_id = _organization_id
              AND e.touch_point_id = ANY(final_tp_ids)
              AND (_start_date IS NULL OR e.created_at >= _start_date)
              AND (_end_date   IS NULL OR e.created_at <= _end_date)
            GROUP BY e.touch_point_id
        ),
        tp_base AS (
            SELECT tp.id, tp.short_url, tp.collection_id,
                   COALESCE(c.clicks, 0)        AS clicks,
                   COALESCE(ev.direct_opens, 0) AS direct_opens,
                   COALESCE(ev.matched, 0)      AS matched
            FROM touch_points tp
            LEFT JOIN tp_clicks c  ON c.tp_id = tp.id
            LEFT JOIN tp_events ev ON ev.touch_point_id = tp.id
            WHERE tp.id = ANY(final_tp_ids)
        ),
        rows AS (
            SELECT b.id::text AS key, b.short_url AS name,
                   b.clicks::bigint, b.direct_opens::bigint, b.matched::bigint
            FROM tp_base b
            WHERE _group_by = 'link'
              AND (b.clicks > 0 OR b.direct_opens > 0 OR b.matched > 0)

            UNION ALL
            SELECT t.id::text, t.name,
                   sum(b.clicks)::bigint, sum(b.direct_opens)::bigint, sum(b.matched)::bigint
            FROM tp_base b
            JOIN tp_tag_links ttl ON ttl.tp_id = b.id
            JOIN tags t ON t.id = ttl.tag_id
            WHERE _group_by = 'tag'
            GROUP BY t.id, t.name
            HAVING sum(b.clicks) > 0 OR sum(b.direct_opens) > 0 OR sum(b.matched) > 0

            UNION ALL
            SELECT c.id::text, c.name,
                   sum(b.clicks)::bigint, sum(b.direct_opens)::bigint, sum(b.matched)::bigint
            FROM tp_base b
            JOIN collections c ON c.id = b.collection_id
            WHERE _group_by = 'space'
            GROUP BY c.id, c.name
            HAVING sum(b.clicks) > 0 OR sum(b.direct_opens) > 0 OR sum(b.matched) > 0
        ),
        ordered AS (
            SELECT * FROM rows ORDER BY clicks DESC, key LIMIT 500
        )
        SELECT jsonb_build_object(
            'group_by', _group_by,
            'data', COALESCE(jsonb_agg(jsonb_build_object(
                        'key', key, 'name', name,
                        'clicks', clicks, 'direct_opens', direct_opens, 'matched', matched)
                        ORDER BY clicks DESC, key), '[]'::jsonb),
            'total', (SELECT COALESCE(sum(r.clicks), 0) FROM rows r)
        )
        FROM ordered
    );
END;
$$;


--
-- Name: get_deep_link_summary(uuid, uuid[], uuid[], uuid[], uuid[], timestamp with time zone, timestamp with time zone, text[], text[], text[], boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_deep_link_summary(_organization_id uuid, _viewable_tp_ids uuid[] DEFAULT NULL::uuid[], _tp_ids uuid[] DEFAULT NULL::uuid[], _tag_ids uuid[] DEFAULT NULL::uuid[], _collection_ids uuid[] DEFAULT NULL::uuid[], _start_date timestamp with time zone DEFAULT NULL::timestamp with time zone, _end_date timestamp with time zone DEFAULT NULL::timestamp with time zone, _utm_sources text[] DEFAULT NULL::text[], _utm_mediums text[] DEFAULT NULL::text[], _utm_campaigns text[] DEFAULT NULL::text[], _exclude_bot boolean DEFAULT false) RETURNS TABLE(app_opens bigint, deferred_matches bigint, deferred_misses bigint, match_rate numeric, by_platform jsonb, by_method jsonb, by_miss_reason jsonb)
    LANGUAGE plpgsql
    AS $$
DECLARE
    final_tp_ids            uuid[];
    tp_ids_from_tags        uuid[];
    tp_ids_from_collections uuid[];
    utm_tp_ids              uuid[];
    utm_filter_active       boolean;
BEGIN
    -- ── touch-point resolution (intersection) ───────────────────────────────
    final_tp_ids := _viewable_tp_ids;

    IF _tp_ids IS NOT NULL AND array_length(_tp_ids, 1) > 0 THEN
        IF final_tp_ids IS NOT NULL THEN
            SELECT array_agg(DISTINCT t) INTO final_tp_ids
            FROM unnest(final_tp_ids) AS t WHERE t = ANY(_tp_ids);
        ELSE
            final_tp_ids := _tp_ids;
        END IF;
    END IF;

    IF _tag_ids IS NOT NULL AND array_length(_tag_ids, 1) > 0 THEN
        SELECT array_agg(DISTINCT tp_id) INTO tp_ids_from_tags
        FROM tp_tag_links WHERE tag_id = ANY(_tag_ids);
        IF final_tp_ids IS NOT NULL THEN
            SELECT array_agg(DISTINCT t) INTO final_tp_ids
            FROM unnest(final_tp_ids) AS t WHERE t = ANY(COALESCE(tp_ids_from_tags, '{}'));
        ELSE
            final_tp_ids := COALESCE(tp_ids_from_tags, '{}');
        END IF;
    END IF;

    IF _collection_ids IS NOT NULL AND array_length(_collection_ids, 1) > 0 THEN
        SELECT array_agg(DISTINCT id) INTO tp_ids_from_collections
        FROM touch_points WHERE collection_id = ANY(_collection_ids);
        IF final_tp_ids IS NOT NULL THEN
            SELECT array_agg(DISTINCT t) INTO final_tp_ids
            FROM unnest(final_tp_ids) AS t WHERE t = ANY(COALESCE(tp_ids_from_collections, '{}'));
        ELSE
            final_tp_ids := COALESCE(tp_ids_from_collections, '{}');
        END IF;
    END IF;

    -- ── UTM: link-level resolution (see header note #2) ──────────────────────
    utm_filter_active := (
           (_utm_sources   IS NOT NULL AND array_length(_utm_sources,   1) > 0)
        OR (_utm_mediums   IS NOT NULL AND array_length(_utm_mediums,   1) > 0)
        OR (_utm_campaigns IS NOT NULL AND array_length(_utm_campaigns, 1) > 0)
    );
    IF utm_filter_active THEN
        SELECT array_agg(DISTINCT id) INTO utm_tp_ids
        FROM touch_points
        WHERE organization_id = _organization_id
          AND (_utm_sources   IS NULL OR array_length(_utm_sources,   1) IS NULL OR utm_tags->>'utm_source'   = ANY(_utm_sources))
          AND (_utm_mediums   IS NULL OR array_length(_utm_mediums,   1) IS NULL OR utm_tags->>'utm_medium'   = ANY(_utm_mediums))
          AND (_utm_campaigns IS NULL OR array_length(_utm_campaigns, 1) IS NULL OR utm_tags->>'utm_campaign' = ANY(_utm_campaigns));
        IF final_tp_ids IS NOT NULL THEN
            SELECT array_agg(DISTINCT t) INTO final_tp_ids
            FROM unnest(final_tp_ids) AS t WHERE t = ANY(COALESCE(utm_tp_ids, '{}'));
        ELSE
            final_tp_ids := COALESCE(utm_tp_ids, '{}');
        END IF;
    END IF;

    RETURN QUERY
    WITH ev AS (
        SELECT e.event_type, e.platform, e.match_method, e.miss_reason
        FROM deep_link_events e
        WHERE e.organization_id = _organization_id
          AND (_start_date IS NULL OR e.created_at >= _start_date)
          AND (_end_date   IS NULL OR e.created_at <= _end_date)
          AND (final_tp_ids IS NULL OR e.touch_point_id = ANY(final_tp_ids))
          -- _exclude_bot intentionally not applied (no is_bot column — header note #3)
    )
    SELECT
        count(*) FILTER (WHERE ev.event_type = 'app_open')::bigint,
        count(*) FILTER (WHERE ev.event_type = 'deferred_match')::bigint,
        count(*) FILTER (WHERE ev.event_type = 'deferred_miss')::bigint,
        round(
            count(*) FILTER (WHERE ev.event_type = 'deferred_match')::numeric
            / nullif(count(*) FILTER (WHERE ev.event_type IN ('deferred_match','deferred_miss')), 0),
            4
        ),
        (SELECT COALESCE(jsonb_object_agg(k, c), '{}'::jsonb)
           FROM (SELECT COALESCE(platform, 'unknown') AS k, count(*) AS c FROM ev GROUP BY 1) s),
        (SELECT COALESCE(jsonb_object_agg(k, c), '{}'::jsonb)
           FROM (SELECT COALESCE(match_method, 'unknown') AS k, count(*) AS c
                   FROM ev WHERE event_type IN ('app_open','deferred_match') GROUP BY 1) s),
        (SELECT jsonb_object_agg(reason, cnt)
           FROM (
               SELECT u.reason, COALESCE(g.c, 0) AS cnt
               FROM unnest(ARRAY[
                   'clipboard_denied','clipboard_empty','opt_out','no_candidate',
                   'ambiguous_candidate','ua_mismatch','cross_tenant_blocked'
               ]) AS u(reason)
               LEFT JOIN (
                   SELECT miss_reason, count(*) AS c
                   FROM ev WHERE event_type = 'deferred_miss' AND miss_reason IS NOT NULL
                   GROUP BY 1
               ) g ON g.miss_reason = u.reason
           ) z)
    FROM ev;
END;
$$;


--
-- Name: get_deep_link_timeseries(uuid, uuid[], uuid[], uuid[], uuid[], timestamp with time zone, timestamp with time zone, text[], text[], text[], boolean, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_deep_link_timeseries(_organization_id uuid, _viewable_tp_ids uuid[] DEFAULT NULL::uuid[], _tp_ids uuid[] DEFAULT NULL::uuid[], _tag_ids uuid[] DEFAULT NULL::uuid[], _collection_ids uuid[] DEFAULT NULL::uuid[], _start_date timestamp with time zone DEFAULT NULL::timestamp with time zone, _end_date timestamp with time zone DEFAULT NULL::timestamp with time zone, _utm_sources text[] DEFAULT NULL::text[], _utm_mediums text[] DEFAULT NULL::text[], _utm_campaigns text[] DEFAULT NULL::text[], _exclude_bot boolean DEFAULT false, _bucket text DEFAULT 'day'::text, _timezone text DEFAULT 'UTC'::text) RETURNS TABLE(bucket timestamp with time zone, app_opens bigint, deferred_matches bigint, deferred_misses bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE
    final_tp_ids            uuid[];
    tp_ids_from_tags        uuid[];
    tp_ids_from_collections uuid[];
    utm_tp_ids              uuid[];
    utm_filter_active       boolean;
    _trunc                  text;
    _tz                     text;
BEGIN
    -- touch-point resolution (identical to get_deep_link_summary)
    final_tp_ids := _viewable_tp_ids;

    IF _tp_ids IS NOT NULL AND array_length(_tp_ids, 1) > 0 THEN
        IF final_tp_ids IS NOT NULL THEN
            SELECT array_agg(DISTINCT t) INTO final_tp_ids
            FROM unnest(final_tp_ids) AS t WHERE t = ANY(_tp_ids);
        ELSE
            final_tp_ids := _tp_ids;
        END IF;
    END IF;

    IF _tag_ids IS NOT NULL AND array_length(_tag_ids, 1) > 0 THEN
        SELECT array_agg(DISTINCT tp_id) INTO tp_ids_from_tags
        FROM tp_tag_links WHERE tag_id = ANY(_tag_ids);
        IF final_tp_ids IS NOT NULL THEN
            SELECT array_agg(DISTINCT t) INTO final_tp_ids
            FROM unnest(final_tp_ids) AS t WHERE t = ANY(COALESCE(tp_ids_from_tags, '{}'));
        ELSE
            final_tp_ids := COALESCE(tp_ids_from_tags, '{}');
        END IF;
    END IF;

    IF _collection_ids IS NOT NULL AND array_length(_collection_ids, 1) > 0 THEN
        SELECT array_agg(DISTINCT id) INTO tp_ids_from_collections
        FROM touch_points WHERE collection_id = ANY(_collection_ids);
        IF final_tp_ids IS NOT NULL THEN
            SELECT array_agg(DISTINCT t) INTO final_tp_ids
            FROM unnest(final_tp_ids) AS t WHERE t = ANY(COALESCE(tp_ids_from_collections, '{}'));
        ELSE
            final_tp_ids := COALESCE(tp_ids_from_collections, '{}');
        END IF;
    END IF;

    utm_filter_active := (
           (_utm_sources   IS NOT NULL AND array_length(_utm_sources,   1) > 0)
        OR (_utm_mediums   IS NOT NULL AND array_length(_utm_mediums,   1) > 0)
        OR (_utm_campaigns IS NOT NULL AND array_length(_utm_campaigns, 1) > 0)
    );
    IF utm_filter_active THEN
        SELECT array_agg(DISTINCT id) INTO utm_tp_ids
        FROM touch_points
        WHERE organization_id = _organization_id
          AND (_utm_sources   IS NULL OR array_length(_utm_sources,   1) IS NULL OR utm_tags->>'utm_source'   = ANY(_utm_sources))
          AND (_utm_mediums   IS NULL OR array_length(_utm_mediums,   1) IS NULL OR utm_tags->>'utm_medium'   = ANY(_utm_mediums))
          AND (_utm_campaigns IS NULL OR array_length(_utm_campaigns, 1) IS NULL OR utm_tags->>'utm_campaign' = ANY(_utm_campaigns));
        IF final_tp_ids IS NOT NULL THEN
            SELECT array_agg(DISTINCT t) INTO final_tp_ids
            FROM unnest(final_tp_ids) AS t WHERE t = ANY(COALESCE(utm_tp_ids, '{}'));
        ELSE
            final_tp_ids := COALESCE(utm_tp_ids, '{}');
        END IF;
    END IF;

    _trunc := CASE WHEN _bucket = 'hour' THEN 'hour' ELSE 'day' END;  -- anything else → day
    _tz := COALESCE((SELECT name FROM pg_timezone_names WHERE name = _timezone), 'UTC');

    RETURN QUERY
    SELECT
        (date_trunc(_trunc, e.created_at AT TIME ZONE _tz) AT TIME ZONE _tz),
        count(*) FILTER (WHERE e.event_type = 'app_open')::bigint,
        count(*) FILTER (WHERE e.event_type = 'deferred_match')::bigint,
        count(*) FILTER (WHERE e.event_type = 'deferred_miss')::bigint
    FROM deep_link_events e
    WHERE e.organization_id = _organization_id
      AND (_start_date IS NULL OR e.created_at >= _start_date)
      AND (_end_date   IS NULL OR e.created_at <= _end_date)
      AND (final_tp_ids IS NULL OR e.touch_point_id = ANY(final_tp_ids))
    GROUP BY 1
    ORDER BY 1;
END;
$$;


--
-- Name: get_distinct_event_names(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_distinct_event_names(_org_id uuid) RETURNS TABLE(event_name text)
    LANGUAGE sql STABLE
    AS $$
  SELECT DISTINCT event_name::text
  FROM pageviews
  WHERE organization_id = _org_id
    AND event_name IS NOT NULL
    AND event_name != ''
    AND created_at >= now() - interval '30 days'
  ORDER BY event_name
  LIMIT 100;
$$;


--
-- Name: get_distinct_utm_values(uuid, uuid[], uuid[], uuid[], uuid[], boolean, timestamp without time zone, timestamp without time zone, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_distinct_utm_values(_organization_id uuid, _campaign_ids uuid[] DEFAULT NULL::uuid[], _tp_ids uuid[] DEFAULT NULL::uuid[], _tag_ids uuid[] DEFAULT NULL::uuid[], _collection_ids uuid[] DEFAULT NULL::uuid[], _include_null_collection boolean DEFAULT false, _start_time timestamp without time zone DEFAULT NULL::timestamp without time zone, _end_time timestamp without time zone DEFAULT NULL::timestamp without time zone, _exclude_bot boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$DECLARE
    result JSONB;
    tp_ids_from_tags UUID[];
    filtered_tp_ids UUID[];
BEGIN
    -- If tag_ids are provided, get all touch points linked to those tags
    IF _tag_ids IS NOT NULL AND array_length(_tag_ids, 1) > 0 THEN
        SELECT array_agg(DISTINCT tp_id) INTO tp_ids_from_tags
        FROM tp_tag_links
        WHERE tag_id = ANY(_tag_ids);

        -- Combine with explicitly provided tp_ids if any
        IF _tp_ids IS NOT NULL AND array_length(_tp_ids, 1) > 0 THEN
            _tp_ids := _tp_ids || tp_ids_from_tags;
        ELSE
            _tp_ids := tp_ids_from_tags;
        END IF;
    END IF;

    -- Apply collection filtering to tp_ids
    IF _collection_ids IS NOT NULL AND array_length(_collection_ids, 1) > 0 THEN
        SELECT array_agg(DISTINCT touch_points.id) INTO filtered_tp_ids
        FROM touch_points
        WHERE (
            collection_id = ANY(_collection_ids)
            OR (
                _include_null_collection = true
                AND collection_id IS NULL
            )
        )
        AND (_tp_ids IS NULL OR array_length(_tp_ids, 1) IS NULL OR touch_points.id = ANY(_tp_ids));

        _tp_ids := filtered_tp_ids;
    END IF;

    -- Extract distinct UTM values from filtered visits
    WITH filtered_visits AS (
        SELECT DISTINCT utm_tags
        FROM visits
        WHERE
            organization_id = _organization_id
            AND utm_tags IS NOT NULL
            AND (_campaign_ids IS NULL OR array_length(_campaign_ids, 1) IS NULL OR campaign_id = ANY(_campaign_ids))
            AND (_tp_ids IS NULL OR array_length(_tp_ids, 1) IS NULL OR tp_id = ANY(_tp_ids))
            AND (_start_time IS NULL OR created_at >= _start_time)
            AND (_end_time IS NULL OR created_at <= _end_time)
            AND (NOT _exclude_bot OR is_bot = FALSE)
    ),
    utm_sources AS (
        SELECT DISTINCT utm_tags->>'utm_source' AS value
        FROM filtered_visits
        WHERE utm_tags->>'utm_source' IS NOT NULL
          AND utm_tags->>'utm_source' != ''
        ORDER BY value
    ),
    utm_mediums AS (
        SELECT DISTINCT utm_tags->>'utm_medium' AS value
        FROM filtered_visits
        WHERE utm_tags->>'utm_medium' IS NOT NULL
          AND utm_tags->>'utm_medium' != ''
        ORDER BY value
    ),
    utm_campaigns AS (
        SELECT DISTINCT utm_tags->>'utm_campaign' AS value
        FROM filtered_visits
        WHERE utm_tags->>'utm_campaign' IS NOT NULL
          AND utm_tags->>'utm_campaign' != ''
        ORDER BY value
    )
    SELECT jsonb_build_object(
        'utm_source', COALESCE((SELECT jsonb_agg(value) FROM utm_sources), '[]'::jsonb),
        'utm_medium', COALESCE((SELECT jsonb_agg(value) FROM utm_mediums), '[]'::jsonb),
        'utm_campaign', COALESCE((SELECT jsonb_agg(value) FROM utm_campaigns), '[]'::jsonb)
    ) INTO result;

    RETURN COALESCE(result, '{}'::jsonb);
END;$$;


--
-- Name: get_fingerprint(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_fingerprint(_client_key text, _canvas_fp text, _browser_fp text) RETURNS SETOF public.fingerprints
    LANGUAGE plpgsql
    AS $$
begin
  return query
    select * from fingerprints f
    where f.client_key = _client_key
       or f.canvas_fp = _canvas_fp
       or f.browser_fp = _browser_fp
    order by created_at desc
    limit 3;
end;
$$;


--
-- Name: get_forms_daily(uuid, timestamp with time zone, timestamp with time zone, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_forms_daily(_org_id uuid, _from timestamp with time zone, _to timestamp with time zone, _form_id text DEFAULT NULL::text, _form_name text DEFAULT NULL::text, _page_path text DEFAULT NULL::text) RETURNS TABLE(day date, fills bigint, submits bigint)
    LANGUAGE sql STABLE
    AS $$
  SELECT
    date_trunc('day', timestamp)::date AS day,
    COUNT(*) FILTER (WHERE interaction_type = 'form_fill')   AS fills,
    COUNT(*) FILTER (WHERE interaction_type = 'form_submit') AS submits
  FROM interactions
  WHERE organization_id = _org_id
    AND interaction_type IN ('form_fill', 'form_submit')
    AND timestamp BETWEEN _from AND _to
    AND is_bot = false
    AND (_form_id   IS NULL OR form_id   = _form_id)
    AND (_form_name IS NULL OR form_name = _form_name)
    AND (_page_path IS NULL OR page_path = _page_path)
  GROUP BY 1
  ORDER BY 1;
$$;


--
-- Name: get_forms_daily(uuid, timestamp with time zone, timestamp with time zone, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_forms_daily(_org_id uuid, _from timestamp with time zone, _to timestamp with time zone, _form_id text DEFAULT NULL::text, _form_name text DEFAULT NULL::text, _page_path text DEFAULT NULL::text, _hostname text DEFAULT NULL::text) RETURNS TABLE(day date, fills bigint, submits bigint)
    LANGUAGE sql STABLE
    AS $$
  SELECT
    date_trunc('day', timestamp)::date AS day,
    COUNT(*) FILTER (WHERE interaction_type = 'form_fill')   AS fills,
    COUNT(*) FILTER (WHERE interaction_type = 'form_submit') AS submits
  FROM interactions
  WHERE organization_id = _org_id
    AND interaction_type IN ('form_fill', 'form_submit')
    AND timestamp BETWEEN _from AND _to
    AND is_bot = false
    AND (_form_id   IS NULL OR form_id   = _form_id)
    AND (_form_name IS NULL OR form_name = _form_name)
    AND (_page_path IS NULL OR page_path = _page_path)
    AND (_hostname  IS NULL OR regexp_replace(page_url, '^https?://([^/]+).*', '\1') = _hostname)
  GROUP BY 1
  ORDER BY 1;
$$;


--
-- Name: get_forms_overview(uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_forms_overview(_org_id uuid, _from timestamp with time zone, _to timestamp with time zone) RETURNS TABLE(form_id text, form_name text, form_action text, page_path text, fills bigint, submits bigint, completion_pct numeric, avg_time_on_form numeric)
    LANGUAGE sql STABLE
    AS $$
  SELECT
    form_id,
    form_name,
    form_action,
    page_path,
    COUNT(*) FILTER (WHERE interaction_type = 'form_fill')   AS fills,
    COUNT(*) FILTER (WHERE interaction_type = 'form_submit') AS submits,
    ROUND(
      COUNT(*) FILTER (WHERE interaction_type = 'form_submit')::numeric
      / NULLIF(COUNT(*) FILTER (WHERE interaction_type = 'form_fill'), 0) * 100,
      1
    ) AS completion_pct,
    ROUND(AVG(time_on_form) FILTER (WHERE interaction_type = 'form_submit') / 1000) AS avg_time_on_form
  FROM interactions
  WHERE organization_id = _org_id
    AND interaction_type IN ('form_fill', 'form_submit')
    AND timestamp BETWEEN _from AND _to
    AND is_bot = false
  GROUP BY form_id, form_name, form_action, page_path
  ORDER BY fills DESC;
$$;


--
-- Name: get_forms_overview(uuid, timestamp with time zone, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_forms_overview(_org_id uuid, _from timestamp with time zone, _to timestamp with time zone, _hostname text DEFAULT NULL::text) RETURNS TABLE(form_id text, form_name text, form_action text, page_path text, fills bigint, submits bigint, completion_pct numeric, avg_time_on_form numeric)
