    ROUND(
      COUNT(*) FILTER (WHERE interaction_type = 'form_submit')::numeric
      / NULLIF(COUNT(*) FILTER (WHERE interaction_type = 'form_fill'), 0) * 100,
      1
    ) AS completion_pct,
    ROUND(AVG(time_on_form) FILTER (WHERE interaction_type = 'form_submit') / 1000) AS avg_time_on_form
  FROM interactions
  WHERE organization_id = _org_id
    AND interaction_type IN ('form_fill', 'form_submit')
    AND timestamp BETWEEN _from AND _to
    AND is_bot = false
    AND (_hostname IS NULL OR regexp_replace(page_url, '^https?://([^/]+).*', '\1') = _hostname)
  GROUP BY form_id, form_name, form_action, page_path
  ORDER BY fills DESC;
$$;


--
-- Name: get_funnel_data(uuid, uuid[], uuid[], uuid[], uuid[], timestamp without time zone, timestamp without time zone, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_funnel_data(_organization_id uuid, _viewable_tp_ids uuid[] DEFAULT NULL::uuid[], _tp_ids uuid[] DEFAULT NULL::uuid[], _tag_ids uuid[] DEFAULT NULL::uuid[], _collection_ids uuid[] DEFAULT NULL::uuid[], _start_date timestamp without time zone DEFAULT NULL::timestamp without time zone, _end_date timestamp without time zone DEFAULT NULL::timestamp without time zone, _exclude_bot boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    result jsonb;
    tp_ids_from_tags uuid[];
    tp_ids_from_collections uuid[];
    final_tp_ids uuid[];
    clicks_count bigint;
    leads_count bigint;
    sales_count bigint;
    direct_visits_count bigint;
    direct_leads_count bigint;
    direct_sales_count bigint;
    total_visits_count bigint;
BEGIN
    -- Start with viewable touch points as the base
    final_tp_ids := _viewable_tp_ids;

    -- Apply tp_ids filter if provided
    IF _tp_ids IS NOT NULL AND array_length(_tp_ids, 1) > 0 THEN
        IF final_tp_ids IS NOT NULL THEN
            SELECT array_agg(DISTINCT tp_id)
            INTO final_tp_ids
            FROM unnest(final_tp_ids) AS tp_id
            WHERE tp_id = ANY(_tp_ids);
        ELSE
            final_tp_ids := _tp_ids;
        END IF;
    END IF;

    -- Apply tag_ids filter if provided
    IF _tag_ids IS NOT NULL AND array_length(_tag_ids, 1) > 0 THEN
        SELECT array_agg(DISTINCT tp_id)
        INTO tp_ids_from_tags
        FROM tp_tag_links
        WHERE tag_id = ANY(_tag_ids);

        IF final_tp_ids IS NOT NULL THEN
            SELECT array_agg(DISTINCT tp_id)
            INTO final_tp_ids
            FROM unnest(final_tp_ids) AS tp_id
            WHERE tp_id = ANY(tp_ids_from_tags);
        ELSE
            final_tp_ids := tp_ids_from_tags;
        END IF;
    END IF;

    -- Apply collection_ids filter if provided
    IF _collection_ids IS NOT NULL AND array_length(_collection_ids, 1) > 0 THEN
        SELECT array_agg(DISTINCT id)
        INTO tp_ids_from_collections
        FROM touch_points
        WHERE collection_id = ANY(_collection_ids);

        IF final_tp_ids IS NOT NULL THEN
            SELECT array_agg(DISTINCT tp_id)
            INTO final_tp_ids
            FROM unnest(final_tp_ids) AS tp_id
            WHERE tp_id = ANY(tp_ids_from_collections);
        ELSE
            final_tp_ids := tp_ids_from_collections;
        END IF;
    END IF;

    -- Count clicks (visits) with filters
    SELECT COUNT(*)
    INTO clicks_count
    FROM visits
    WHERE organization_id = _organization_id
      AND (_exclude_bot = false OR is_bot = false)
      AND (final_tp_ids IS NULL OR tp_id = ANY(final_tp_ids))
      AND (_start_date IS NULL OR created_at >= _start_date)
      AND (_end_date IS NULL OR created_at <= _end_date);

    -- Count leads with filters (excluding direct leads with empty click_id)
    SELECT COUNT(*)
    INTO leads_count
    FROM conversion_events
    WHERE organization_id = _organization_id
      AND event_type = 'lead'
      AND click_id != ''
      AND (final_tp_ids IS NULL OR touch_point_id = ANY(final_tp_ids))
      AND (_start_date IS NULL OR created_at >= _start_date)
      AND (_end_date IS NULL OR created_at <= _end_date);

    -- Count sales with filters (excluding direct sales with empty click_id)
    SELECT COUNT(*)
    INTO sales_count
    FROM conversion_events
    WHERE organization_id = _organization_id
      AND event_type = 'sale'
      AND click_id != ''
      AND (final_tp_ids IS NULL OR touch_point_id = ANY(final_tp_ids))
      AND (_start_date IS NULL OR created_at >= _start_date)
      AND (_end_date IS NULL OR created_at <= _end_date);

    -- Count direct visits: sessions with no li2_cid (not attributed to any tracked link)
    SELECT COUNT(*)
    INTO direct_visits_count
    FROM sessions
    WHERE organization_id = _organization_id
      AND li2_cid IS NULL
      AND (_exclude_bot = false OR is_bot = false)
      AND (_start_date IS NULL OR started_at >= _start_date)
      AND (_end_date IS NULL OR started_at <= _end_date);

    -- Count direct leads: conversion events with empty click_id (no link attribution)
    SELECT COUNT(*)
    INTO direct_leads_count
    FROM conversion_events
    WHERE organization_id = _organization_id
      AND event_type = 'lead'
      AND click_id = ''
      AND (_start_date IS NULL OR created_at >= _start_date)
      AND (_end_date IS NULL OR created_at <= _end_date);

    -- Count direct sales: conversion events with empty click_id (no link attribution)
    SELECT COUNT(*)
    INTO direct_sales_count
    FROM conversion_events
    WHERE organization_id = _organization_id
      AND event_type = 'sale'
      AND click_id = ''
      AND (_start_date IS NULL OR created_at >= _start_date)
      AND (_end_date IS NULL OR created_at <= _end_date);

    -- Total visits = attributed (visits table) + direct (sessions without li2_cid)
    total_visits_count := clicks_count + direct_visits_count;

    SELECT jsonb_build_object(
        'clicks', clicks_count,
        'leads', leads_count,
        'sales', sales_count,
        'direct_visits', direct_visits_count,
        'direct_leads', direct_leads_count,
        'direct_sales', direct_sales_count,
        'clicks_to_leads_rate', CASE WHEN total_visits_count > 0 THEN ROUND(((leads_count + direct_leads_count)::numeric / total_visits_count::numeric * 100)::numeric, 2) ELSE 0 END,
        'leads_to_sales_rate', CASE WHEN (leads_count + direct_leads_count) > 0 THEN ROUND(((sales_count + direct_sales_count)::numeric / (leads_count + direct_leads_count)::numeric * 100)::numeric, 2) ELSE 0 END,
        'overall_rate', CASE WHEN total_visits_count > 0 THEN ROUND(((sales_count + direct_sales_count)::numeric / total_visits_count::numeric * 100)::numeric, 2) ELSE 0 END
    )
    INTO result;

    RETURN result;
END;
$$;


--
-- Name: get_funnel_data_v2(uuid, uuid[], uuid[], uuid[], uuid[], timestamp without time zone, timestamp without time zone, boolean, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_funnel_data_v2(_organization_id uuid, _viewable_tp_ids uuid[] DEFAULT NULL::uuid[], _tp_ids uuid[] DEFAULT NULL::uuid[], _tag_ids uuid[] DEFAULT NULL::uuid[], _collection_ids uuid[] DEFAULT NULL::uuid[], _start_date timestamp without time zone DEFAULT NULL::timestamp without time zone, _end_date timestamp without time zone DEFAULT NULL::timestamp without time zone, _exclude_bot boolean DEFAULT false, _event_names text[] DEFAULT NULL::text[]) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    result jsonb;
    tp_ids_from_tags uuid[];
    tp_ids_from_collections uuid[];
    final_tp_ids uuid[];
    clicks_count bigint;
    leads_count bigint;
    sales_count bigint;
    direct_visits_count bigint;
    direct_leads_count bigint;
    direct_sales_count bigint;
    total_visits_count bigint;
BEGIN
    final_tp_ids := _viewable_tp_ids;

    IF _tp_ids IS NOT NULL AND array_length(_tp_ids, 1) > 0 THEN
        IF final_tp_ids IS NOT NULL THEN
            SELECT array_agg(DISTINCT tp_id) INTO final_tp_ids
            FROM unnest(final_tp_ids) AS tp_id WHERE tp_id = ANY(_tp_ids);
        ELSE
            final_tp_ids := _tp_ids;
        END IF;
    END IF;

    IF _tag_ids IS NOT NULL AND array_length(_tag_ids, 1) > 0 THEN
        SELECT array_agg(DISTINCT tp_id) INTO tp_ids_from_tags
        FROM tp_tag_links WHERE tag_id = ANY(_tag_ids);
        IF final_tp_ids IS NOT NULL THEN
            SELECT array_agg(DISTINCT tp_id) INTO final_tp_ids
            FROM unnest(final_tp_ids) AS tp_id WHERE tp_id = ANY(tp_ids_from_tags);
        ELSE
            final_tp_ids := tp_ids_from_tags;
        END IF;
    END IF;

    IF _collection_ids IS NOT NULL AND array_length(_collection_ids, 1) > 0 THEN
        SELECT array_agg(DISTINCT id) INTO tp_ids_from_collections
        FROM touch_points WHERE collection_id = ANY(_collection_ids);
        IF final_tp_ids IS NOT NULL THEN
            SELECT array_agg(DISTINCT tp_id) INTO final_tp_ids
            FROM unnest(final_tp_ids) AS tp_id WHERE tp_id = ANY(tp_ids_from_collections);
        ELSE
            final_tp_ids := tp_ids_from_collections;
        END IF;
    END IF;

    SELECT COUNT(*) INTO clicks_count
    FROM visits
    WHERE organization_id = _organization_id
      AND (_exclude_bot = false OR is_bot = false)
      AND (final_tp_ids IS NULL OR tp_id = ANY(final_tp_ids))
      AND (_start_date IS NULL OR created_at >= _start_date)
      AND (_end_date IS NULL OR created_at <= _end_date);

    SELECT COUNT(*) INTO leads_count
    FROM conversion_events
    WHERE organization_id = _organization_id
      AND event_type = 'lead' AND click_id != ''
      AND (final_tp_ids IS NULL OR touch_point_id = ANY(final_tp_ids))
      AND (_start_date IS NULL OR created_at >= _start_date)
      AND (_end_date IS NULL OR created_at <= _end_date)
      AND (_event_names IS NULL OR array_length(_event_names, 1) IS NULL OR event_name = ANY(_event_names));

    SELECT COUNT(*) INTO sales_count
    FROM conversion_events
    WHERE organization_id = _organization_id
      AND event_type = 'sale' AND click_id != ''
      AND (final_tp_ids IS NULL OR touch_point_id = ANY(final_tp_ids))
      AND (_start_date IS NULL OR created_at >= _start_date)
      AND (_end_date IS NULL OR created_at <= _end_date)
      AND (_event_names IS NULL OR array_length(_event_names, 1) IS NULL OR event_name = ANY(_event_names));

    SELECT COUNT(*) INTO direct_visits_count
    FROM sessions
    WHERE organization_id = _organization_id
      AND li2_cid IS NULL
      AND (_exclude_bot = false OR is_bot = false)
      AND (_start_date IS NULL OR started_at >= _start_date)
      AND (_end_date IS NULL OR started_at <= _end_date);

    SELECT COUNT(*) INTO direct_leads_count
    FROM conversion_events
    WHERE organization_id = _organization_id
      AND event_type = 'lead' AND click_id = ''
      AND (_start_date IS NULL OR created_at >= _start_date)
      AND (_end_date IS NULL OR created_at <= _end_date)
      AND (_event_names IS NULL OR array_length(_event_names, 1) IS NULL OR event_name = ANY(_event_names));

    SELECT COUNT(*) INTO direct_sales_count
    FROM conversion_events
    WHERE organization_id = _organization_id
      AND event_type = 'sale' AND click_id = ''
      AND (_start_date IS NULL OR created_at >= _start_date)
      AND (_end_date IS NULL OR created_at <= _end_date)
      AND (_event_names IS NULL OR array_length(_event_names, 1) IS NULL OR event_name = ANY(_event_names));

    total_visits_count := clicks_count + direct_visits_count;

    SELECT jsonb_build_object(
        'clicks', clicks_count,
        'leads', leads_count,
        'sales', sales_count,
        'direct_visits', direct_visits_count,
        'direct_leads', direct_leads_count,
        'direct_sales', direct_sales_count,
        'clicks_to_leads_rate', CASE WHEN total_visits_count > 0 THEN ROUND(((leads_count + direct_leads_count)::numeric / total_visits_count::numeric * 100)::numeric, 2) ELSE 0 END,
        'leads_to_sales_rate', CASE WHEN (leads_count + direct_leads_count) > 0 THEN ROUND(((sales_count + direct_sales_count)::numeric / (leads_count + direct_leads_count)::numeric * 100)::numeric, 2) ELSE 0 END,
        'overall_rate', CASE WHEN total_visits_count > 0 THEN ROUND(((sales_count + direct_sales_count)::numeric / total_visits_count::numeric * 100)::numeric, 2) ELSE 0 END
    ) INTO result;

    RETURN result;
END;
$$;


--
-- Name: get_funnel_data_v3(uuid, uuid[], uuid[], uuid[], uuid[], timestamp without time zone, timestamp without time zone, boolean, text[], text[], text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_funnel_data_v3(_organization_id uuid, _viewable_tp_ids uuid[] DEFAULT NULL::uuid[], _tp_ids uuid[] DEFAULT NULL::uuid[], _tag_ids uuid[] DEFAULT NULL::uuid[], _collection_ids uuid[] DEFAULT NULL::uuid[], _start_date timestamp without time zone DEFAULT NULL::timestamp without time zone, _end_date timestamp without time zone DEFAULT NULL::timestamp without time zone, _exclude_bot boolean DEFAULT false, _event_names text[] DEFAULT NULL::text[], _utm_sources text[] DEFAULT NULL::text[], _channels text[] DEFAULT NULL::text[]) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    result                jsonb;
    tp_ids_from_tags      uuid[];
    tp_ids_from_collections uuid[];
    final_tp_ids          uuid[];
    clicks_count          bigint;
    leads_count           bigint;
    sales_count           bigint;
    direct_visits_count   bigint;
    direct_leads_count    bigint;
    direct_sales_count    bigint;
    total_visits_count    bigint;
    utm_filter_active     boolean;
    matched_click_ids     text[];
    matched_session_ids   text[];
BEGIN
    final_tp_ids := _viewable_tp_ids;

    IF _tp_ids IS NOT NULL AND array_length(_tp_ids, 1) > 0 THEN
        IF final_tp_ids IS NOT NULL THEN
            SELECT array_agg(DISTINCT tp_id) INTO final_tp_ids
            FROM unnest(final_tp_ids) AS tp_id WHERE tp_id = ANY(_tp_ids);
        ELSE
            final_tp_ids := _tp_ids;
        END IF;
    END IF;

    IF _tag_ids IS NOT NULL AND array_length(_tag_ids, 1) > 0 THEN
        SELECT array_agg(DISTINCT tp_id) INTO tp_ids_from_tags
        FROM tp_tag_links WHERE tag_id = ANY(_tag_ids);
        IF final_tp_ids IS NOT NULL THEN
            SELECT array_agg(DISTINCT tp_id) INTO final_tp_ids
            FROM unnest(final_tp_ids) AS tp_id WHERE tp_id = ANY(tp_ids_from_tags);
        ELSE
            final_tp_ids := tp_ids_from_tags;
        END IF;
    END IF;

    IF _collection_ids IS NOT NULL AND array_length(_collection_ids, 1) > 0 THEN
        SELECT array_agg(DISTINCT id) INTO tp_ids_from_collections
        FROM touch_points WHERE collection_id = ANY(_collection_ids);
        IF final_tp_ids IS NOT NULL THEN
            SELECT array_agg(DISTINCT tp_id) INTO final_tp_ids
            FROM unnest(final_tp_ids) AS tp_id WHERE tp_id = ANY(tp_ids_from_collections);
        ELSE
            final_tp_ids := tp_ids_from_collections;
        END IF;
    END IF;

    -- ── UTM/channel: resolve once ────────────────────────────────────────────
    utm_filter_active := (
        (_utm_sources IS NOT NULL AND array_length(_utm_sources, 1) > 0)
        OR (_channels  IS NOT NULL AND array_length(_channels,  1) > 0)
    );

    IF utm_filter_active THEN
        SELECT array_agg(DISTINCT li2_cid) INTO matched_click_ids
        FROM visits
        WHERE organization_id = _organization_id
          AND li2_cid IS NOT NULL
          AND (_utm_sources IS NULL OR array_length(_utm_sources, 1) IS NULL OR utm_tags->>'utm_source' = ANY(_utm_sources))
          AND (_channels    IS NULL OR array_length(_channels,    1) IS NULL OR channel                = ANY(_channels));

        SELECT array_agg(DISTINCT session_id) INTO matched_session_ids
        FROM sessions
        WHERE organization_id = _organization_id
          AND session_id IS NOT NULL
          AND (_utm_sources IS NULL OR array_length(_utm_sources, 1) IS NULL OR utm_source = ANY(_utm_sources))
          AND (_channels    IS NULL OR array_length(_channels,    1) IS NULL OR channel    = ANY(_channels));

        IF matched_click_ids   IS NULL THEN matched_click_ids   := '{}'; END IF;
        IF matched_session_ids IS NULL THEN matched_session_ids := '{}'; END IF;
    END IF;

    -- ── attributed visits: filter visits table directly by UTM/channel ───────
    SELECT COUNT(*) INTO clicks_count
    FROM visits
    WHERE organization_id = _organization_id
      AND (_exclude_bot = false OR is_bot = false)
      AND (final_tp_ids IS NULL OR tp_id = ANY(final_tp_ids))
      AND (_start_date IS NULL OR created_at >= _start_date)
      AND (_end_date   IS NULL OR created_at <= _end_date)
      AND (
          NOT utm_filter_active
          OR (
              (_utm_sources IS NULL OR array_length(_utm_sources, 1) IS NULL OR utm_tags->>'utm_source' = ANY(_utm_sources))
              AND (_channels IS NULL OR array_length(_channels, 1) IS NULL OR channel = ANY(_channels))
          )
      );

    SELECT COUNT(*) INTO leads_count
    FROM conversion_events
    WHERE organization_id = _organization_id
      AND event_type = 'lead' AND click_id != ''
      AND (final_tp_ids IS NULL OR touch_point_id = ANY(final_tp_ids))
      AND (_start_date IS NULL OR created_at >= _start_date)
      AND (_end_date   IS NULL OR created_at <= _end_date)
      AND (_event_names IS NULL OR array_length(_event_names, 1) IS NULL OR event_name = ANY(_event_names))
      AND (NOT utm_filter_active OR click_id = ANY(matched_click_ids));

    SELECT COUNT(*) INTO sales_count
    FROM conversion_events
    WHERE organization_id = _organization_id
      AND event_type = 'sale' AND click_id != ''
      AND (final_tp_ids IS NULL OR touch_point_id = ANY(final_tp_ids))
      AND (_start_date IS NULL OR created_at >= _start_date)
      AND (_end_date   IS NULL OR created_at <= _end_date)
      AND (_event_names IS NULL OR array_length(_event_names, 1) IS NULL OR event_name = ANY(_event_names))
      AND (NOT utm_filter_active OR click_id = ANY(matched_click_ids));

    -- ── direct visits: filter sessions table directly by UTM/channel ─────────
    SELECT COUNT(*) INTO direct_visits_count
    FROM sessions
    WHERE organization_id = _organization_id
      AND li2_cid IS NULL
      AND (_exclude_bot = false OR is_bot = false)
      AND (_start_date IS NULL OR started_at >= _start_date)
      AND (_end_date   IS NULL OR started_at <= _end_date)
      AND (
          NOT utm_filter_active
          OR (
              (_utm_sources IS NULL OR array_length(_utm_sources, 1) IS NULL OR utm_source = ANY(_utm_sources))
              AND (_channels IS NULL OR array_length(_channels, 1) IS NULL OR channel = ANY(_channels))
          )
      );

    SELECT COUNT(*) INTO direct_leads_count
    FROM conversion_events
    WHERE organization_id = _organization_id
      AND event_type = 'lead' AND click_id = ''
      AND (_start_date IS NULL OR created_at >= _start_date)
      AND (_end_date   IS NULL OR created_at <= _end_date)
      AND (_event_names IS NULL OR array_length(_event_names, 1) IS NULL OR event_name = ANY(_event_names))
      AND (NOT utm_filter_active OR session_id = ANY(matched_session_ids));

    SELECT COUNT(*) INTO direct_sales_count
    FROM conversion_events
    WHERE organization_id = _organization_id
      AND event_type = 'sale' AND click_id = ''
      AND (_start_date IS NULL OR created_at >= _start_date)
      AND (_end_date   IS NULL OR created_at <= _end_date)
      AND (_event_names IS NULL OR array_length(_event_names, 1) IS NULL OR event_name = ANY(_event_names))
      AND (NOT utm_filter_active OR session_id = ANY(matched_session_ids));

    total_visits_count := clicks_count + direct_visits_count;

    SELECT jsonb_build_object(
        'clicks',        clicks_count,
        'leads',         leads_count,
        'sales',         sales_count,
        'direct_visits', direct_visits_count,
        'direct_leads',  direct_leads_count,
        'direct_sales',  direct_sales_count,
        'clicks_to_leads_rate', CASE WHEN total_visits_count > 0 THEN ROUND(((leads_count + direct_leads_count)::numeric / total_visits_count::numeric * 100)::numeric, 2) ELSE 0 END,
        'leads_to_sales_rate',  CASE WHEN (leads_count + direct_leads_count) > 0 THEN ROUND(((sales_count + direct_sales_count)::numeric / (leads_count + direct_leads_count)::numeric * 100)::numeric, 2) ELSE 0 END,
        'overall_rate',         CASE WHEN total_visits_count > 0 THEN ROUND(((sales_count + direct_sales_count)::numeric / total_visits_count::numeric * 100)::numeric, 2) ELSE 0 END
    ) INTO result;

    RETURN result;
END;
$$;


--
-- Name: get_funnel_list_stats(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_funnel_list_stats(p_org_id uuid) RETURNS TABLE(funnel_id uuid, total_entries bigint, total_conversions bigint, conversion_rate numeric, cvr_trend numeric, biggest_dropoff_step_position integer, biggest_dropoff_step_name text, biggest_dropoff_next_step_name text, biggest_dropoff_drop_offs bigint, biggest_dropoff_rate numeric)
    LANGUAGE sql STABLE
    AS $$
  WITH
  -- All-time aggregates (start → today)
  alltime AS (
    SELECT
      funnel_id,
      SUM(total_entries)::bigint     AS total_entries,
      SUM(total_conversions)::bigint AS total_conversions
    FROM funnel_results
    WHERE organization_id = p_org_id
      AND period_type = 'day'
    GROUP BY funnel_id
  ),
  -- Snapshot as of 7 days ago (start → 7 days ago), for trend baseline
  before_7d AS (
    SELECT
      funnel_id,
      SUM(total_entries)::bigint     AS total_entries,
      SUM(total_conversions)::bigint AS total_conversions
    FROM funnel_results
    WHERE organization_id = p_org_id
      AND period_type = 'day'
      AND period_start < CURRENT_DATE - INTERVAL '7 days'
    GROUP BY funnel_id
  ),
  -- Unnest step_metrics JSONB for all steps (including step 1 which can have the most drop-offs)
  step_unnested AS (
    SELECT
      fr.funnel_id,
      fr.period_start,
      (step->>'step_position')::int  AS step_position,
      (step->>'step_name')::text     AS step_name,
      (step->>'visits')::bigint      AS visits,
      (step->>'drop_offs')::bigint   AS drop_offs
    FROM funnel_results fr,
         jsonb_array_elements(fr.step_metrics) AS step
    WHERE fr.organization_id = p_org_id
      AND fr.period_type = 'day'
  ),
  step_agg AS (
    SELECT
      funnel_id,
      step_position,
      (array_agg(step_name ORDER BY period_start DESC))[1] AS step_name,
      SUM(visits)    AS total_visits,
      SUM(drop_offs) AS total_drop_offs
    FROM step_unnested
    GROUP BY funnel_id, step_position
  ),
  -- True last step per funnel from funnel_steps table (not step_agg, which may miss zero-data steps)
  funnel_last_step AS (
    SELECT funnel_id, MAX(position) AS max_pos
    FROM funnel_steps
    GROUP BY funnel_id
  ),
  -- One row per funnel: highest drop-off rate among non-final, non-empty, required steps
  -- Matches drop-off-insight.tsx: exclude last step, exclude 0-visit steps
  biggest_drop AS (
    SELECT DISTINCT ON (a.funnel_id)
      a.funnel_id,
      a.step_position,
      a.step_name,
      a.total_drop_offs,
      CASE WHEN a.total_visits > 0
        THEN ROUND((a.total_drop_offs::numeric / a.total_visits) * 100, 1)
        ELSE 0
      END AS drop_off_rate,
      b.step_name AS next_step_name
    FROM step_agg a
    JOIN funnel_last_step fls
      ON fls.funnel_id = a.funnel_id
      AND a.step_position < fls.max_pos
    LEFT JOIN step_agg b
      ON b.funnel_id = a.funnel_id
      AND b.step_position = a.step_position + 1
    WHERE a.total_visits > 0
    ORDER BY a.funnel_id,
             (a.total_drop_offs::numeric / a.total_visits) * 100 DESC
  )
  SELECT
    a.funnel_id,
    a.total_entries,
    a.total_conversions,
    -- Current CVR: all-time
    CASE WHEN a.total_entries > 0
      THEN ROUND((a.total_conversions::numeric / a.total_entries) * 100, 2)
      ELSE 0
    END AS conversion_rate,
    -- Trend: current all-time CVR minus CVR as of 7 days ago
    -- Positive = improving, negative = declining
    CASE WHEN b7.total_entries IS NOT NULL THEN
      ROUND(
        CASE WHEN a.total_entries > 0
          THEN (a.total_conversions::numeric / a.total_entries) * 100
          ELSE 0
        END
        -
        CASE WHEN b7.total_entries > 0
          THEN (b7.total_conversions::numeric / b7.total_entries) * 100
          ELSE 0
        END,
        2
      )
    ELSE NULL
    END AS cvr_trend,
    bd.step_position   AS biggest_dropoff_step_position,
    bd.step_name       AS biggest_dropoff_step_name,
    bd.next_step_name  AS biggest_dropoff_next_step_name,
    bd.total_drop_offs AS biggest_dropoff_drop_offs,
    bd.drop_off_rate   AS biggest_dropoff_rate
  FROM alltime a
  LEFT JOIN before_7d b7    ON b7.funnel_id = a.funnel_id
  LEFT JOIN biggest_drop bd ON bd.funnel_id = a.funnel_id
$$;


--
-- Name: get_group_analytic(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_group_analytic(p_org_id uuid) RETURNS TABLE(total integer[], fp integer[], platform jsonb[], os jsonb[], type jsonb[])
    LANGUAGE plpgsql
    AS $$BEGIN
  RETURN QUERY
  WITH valid_groups AS (
    SELECT id AS group_id
    FROM groups
    WHERE organization_id = p_org_id
  ),
  base AS (
    SELECT
      vsg.group_id,
      vsg.platform,
      vsg.os,
      vsg.type,
      vsg.total,  
      vsg.fp    
    FROM visits_by_group vsg
    WHERE vsg.user_id = requesting_user_id()
      AND vsg.group_id IN (SELECT group_id FROM valid_groups)
  ),
  grouped AS (
    SELECT
      group_id,
      SUM(base.total)::INTEGER AS total,
      SUM(base.fp)::INTEGER AS fp
    FROM base
    GROUP BY group_id
  ),
  platform_counts AS (
    SELECT
      COALESCE(base.platform::TEXT, '') AS platform,
      COUNT(*)::INTEGER AS count
    FROM base
    GROUP BY COALESCE(base.platform::TEXT, '')
  ),
  os_counts AS (
    SELECT
      COALESCE(base.os::TEXT, '') AS os,
      COUNT(*)::INTEGER AS count
    FROM base
    GROUP BY COALESCE(base.os::TEXT, '')
  ),
  type_counts AS (
    SELECT
      COALESCE(base.type::TEXT, '') AS type,
      COUNT(*)::INTEGER AS count
    FROM base
    GROUP BY COALESCE(base.type::TEXT, '')
  ),
  platform_final AS (
    SELECT array_agg(jsonb_build_object('platform', platform_counts.platform, 'count', platform_counts.count)) AS result
    FROM platform_counts
  ),
  os_final AS (
    SELECT array_agg(jsonb_build_object('os', os_counts.os, 'count', os_counts.count)) AS result
    FROM os_counts
  ),
  type_final AS (
    SELECT array_agg(jsonb_build_object('type', type_counts.type, 'count', type_counts.count)) AS result
    FROM type_counts
  )
  SELECT
    ARRAY(SELECT g.total FROM grouped g),
    ARRAY(SELECT g.fp FROM grouped g),
    (SELECT pf.result FROM platform_final pf),
    (SELECT of.result FROM os_final of),
    (SELECT tf.result FROM type_final tf);
END;$$;


--
-- Name: get_group_analytic_overtime(uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_group_analytic_overtime(p_tp_id uuid DEFAULT NULL::uuid, p_location_id uuid DEFAULT NULL::uuid, p_group_id uuid DEFAULT NULL::uuid, p_org_id uuid DEFAULT NULL::uuid) RETURNS TABLE(date date, total integer, os jsonb[], platform jsonb[], type jsonb[], unique_visit jsonb[])
    LANGUAGE sql
    AS $$
WITH base AS (
  SELECT
    DATE(created_at) AS date,
    os,
    platform,
    type,
    fp
  FROM visits
  WHERE (
    (p_tp_id IS NOT NULL AND tp_id = p_tp_id)
    OR (p_location_id IS NOT NULL AND location_id = p_location_id)
    OR (p_group_id IS NOT NULL AND group_id = p_group_id)
    OR (
      p_tp_id IS NULL AND
      p_location_id IS NULL AND
      p_group_id IS NULL AND
      organization_id = p_org_id AND
      user_id = requesting_user_id()
    )
  )
),

agg_data AS (
  SELECT
    date,
    os,
    platform,
    type,
    fp,
    COUNT(*) OVER (PARTITION BY date, os) AS os_count,
    COUNT(*) OVER (PARTITION BY date, platform) AS platform_count,
    COUNT(*) OVER (PARTITION BY date, type) AS type_count
  FROM base
),

fp_visits AS (
  SELECT
    date,
    fp,
    MIN(os) AS os,
    MIN(platform) AS platform,
    COUNT(*) AS visit
  FROM base
  GROUP BY date, fp
)

SELECT
  a.date,
  COUNT(*) AS total,
  ARRAY_AGG(DISTINCT jsonb_build_object('os', a.os, 'count', a.os_count)) AS os,
  ARRAY_AGG(DISTINCT jsonb_build_object('platform', a.platform, 'count', a.platform_count)) AS platform,
  CASE
    WHEN p_tp_id IS NOT NULL THEN ARRAY[]::JSONB[] -- empty array if tp_id is provided
    ELSE ARRAY_AGG(DISTINCT jsonb_build_object('type', a.type, 'count', a.type_count))
  END AS type,
  ARRAY_AGG(DISTINCT jsonb_build_object(
    'fp', f.fp,
    'visit', f.visit,
    'os', f.os,
    'platform', f.platform
  )) AS unique_visit
FROM agg_data a
LEFT JOIN fp_visits f ON a.date = f.date AND a.fp = f.fp
GROUP BY a.date, p_tp_id
ORDER BY a.date ASC;
$$;


--
-- Name: get_heatmap_clicks(uuid, text, timestamp with time zone, timestamp with time zone, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_heatmap_clicks(_org_id uuid, _page_path text, _from timestamp with time zone, _to timestamp with time zone, _device_type text DEFAULT NULL::text, _grid_size integer DEFAULT 10) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
  result jsonb;
BEGIN
  SELECT jsonb_build_object(
    'total_clicks', count(*),
    'unique_visitors', count(DISTINCT visitor_id),
    'grid', (
      SELECT coalesce(jsonb_agg(row_to_json(g)), '[]'::jsonb)
      FROM (
        SELECT
          (floor(x::numeric / _grid_size) * _grid_size)::int AS x,
          (floor(y::numeric / _grid_size) * _grid_size)::int AS y,
          count(*) AS count
        FROM interactions
        WHERE organization_id = _org_id
          AND page_path = _page_path
          AND timestamp BETWEEN _from AND _to
          AND (_device_type IS NULL OR device_type = _device_type)
          AND is_bot = false
        GROUP BY 1, 2
        ORDER BY count DESC
        LIMIT 10000
      ) g
    ),
    'elements', (
      SELECT coalesce(jsonb_agg(row_to_json(e)), '[]'::jsonb)
      FROM (
        SELECT
          selector_path AS selector,
          element_text AS text,
          element_tag AS tag,
          count(*) AS count
        FROM interactions
        WHERE organization_id = _org_id
          AND page_path = _page_path
          AND timestamp BETWEEN _from AND _to
          AND (_device_type IS NULL OR device_type = _device_type)
          AND is_bot = false
          AND selector_path IS NOT NULL
        GROUP BY selector_path, element_text, element_tag
        ORDER BY count DESC
        LIMIT 50
      ) e
    )
  ) INTO result
  FROM interactions
  WHERE organization_id = _org_id
    AND page_path = _page_path
    AND timestamp BETWEEN _from AND _to
    AND (_device_type IS NULL OR device_type = _device_type)
    AND is_bot = false;

  RETURN coalesce(result, '{"total_clicks":0,"unique_visitors":0,"grid":[],"elements":[]}'::jsonb);
END;
$$;


--
-- Name: get_heatmap_clicks(uuid, text, timestamp with time zone, timestamp with time zone, text, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_heatmap_clicks(_org_id uuid, _page_path text, _from timestamp with time zone, _to timestamp with time zone, _device_type text DEFAULT NULL::text, _grid_size integer DEFAULT 10, _hostname text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
  result jsonb;
BEGIN
  SELECT jsonb_build_object(
    'total_clicks', count(*),
    'unique_visitors', count(DISTINCT visitor_id),
    'grid', (
      SELECT coalesce(jsonb_agg(row_to_json(g)), '[]'::jsonb)
      FROM (
        SELECT
          (floor(x::numeric / _grid_size) * _grid_size)::int AS x,
          (floor(y::numeric / _grid_size) * _grid_size)::int AS y,
          count(*) AS count
        FROM interactions
        WHERE organization_id = _org_id
          AND page_path = _page_path
          AND timestamp >= _from AND timestamp < _to + interval '1 day'
          AND (_device_type IS NULL OR device_type = _device_type)
          AND (_hostname IS NULL OR page_url LIKE 'https://' || _hostname || '/%' OR page_url LIKE 'http://' || _hostname || '/%')
          AND is_bot = false
        GROUP BY 1, 2
        ORDER BY count DESC
        LIMIT 10000
      ) g
    ),
    'elements', (
      SELECT coalesce(jsonb_agg(row_to_json(e)), '[]'::jsonb)
      FROM (
        SELECT
          selector_path AS selector,
          element_text AS text,
          element_tag AS tag,
          count(*) AS count,
          (array_agg(element_id) FILTER (WHERE element_id IS NOT NULL))[1] AS element_id,
          (array_agg(element_href) FILTER (WHERE element_href IS NOT NULL))[1] AS element_href
        FROM interactions
        WHERE organization_id = _org_id
          AND page_path = _page_path
          AND timestamp >= _from AND timestamp < _to + interval '1 day'
          AND (_device_type IS NULL OR device_type = _device_type)
          AND (_hostname IS NULL OR page_url LIKE 'https://' || _hostname || '/%' OR page_url LIKE 'http://' || _hostname || '/%')
          AND is_bot = false
          AND selector_path IS NOT NULL
        GROUP BY selector_path, element_text, element_tag
        ORDER BY count DESC
        LIMIT 50
      ) e
    )
  ) INTO result
  FROM interactions
  WHERE organization_id = _org_id
    AND page_path = _page_path
    AND timestamp >= _from AND timestamp < _to + interval '1 day'
    AND (_device_type IS NULL OR device_type = _device_type)
    AND (_hostname IS NULL OR page_url LIKE 'https://' || _hostname || '/%' OR page_url LIKE 'http://' || _hostname || '/%')
    AND is_bot = false;

  RETURN coalesce(result, '{"total_clicks":0,"unique_visitors":0,"grid":[],"elements":[]}'::jsonb);
END;
$$;


--
-- Name: get_heatmap_clicks(uuid, text, timestamp with time zone, timestamp with time zone, text, integer, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_heatmap_clicks(_org_id uuid, _page_path text, _from timestamp with time zone, _to timestamp with time zone, _device_type text DEFAULT NULL::text, _grid_size integer DEFAULT 10, _hostname text DEFAULT NULL::text, _target_width integer DEFAULT 1440) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
  result jsonb;
BEGIN
  SELECT jsonb_build_object(
    'total_clicks', count(*),
    'unique_visitors', count(DISTINCT visitor_id),
    'grid', (
      SELECT coalesce(jsonb_agg(row_to_json(g)), '[]'::jsonb)
      FROM (
