    AND (_hostname IS NULL OR page_url LIKE 'https://' || _hostname || '/%' OR page_url LIKE 'http://' || _hostname || '/%')
    AND is_bot = false;

  RETURN coalesce(result, '{"total_clicks":0,"unique_visitors":0,"grid":[],"elements":[]}'::jsonb);
END;
$$;


--
-- Name: get_heatmap_clicks(uuid, text, timestamp with time zone, timestamp with time zone, text, integer, text, integer, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_heatmap_clicks(_org_id uuid, _page_path text, _from timestamp with time zone, _to timestamp with time zone, _device_type text DEFAULT NULL::text, _grid_size integer DEFAULT 10, _hostname text DEFAULT NULL::text, _target_width integer DEFAULT 1440, _tp_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
  result jsonb;
BEGIN
  SELECT jsonb_build_object(
    'total_clicks', count(*),
    'unique_visitors', count(DISTINCT visitor_id),
    'grid', (
      SELECT coalesce(jsonb_agg(row_to_json(g)), '[]'::jsonb)
      FROM (
        SELECT
          (floor((x::numeric * _target_width / viewport_width) / _grid_size) * _grid_size)::int AS x,
          (floor(y::numeric / _grid_size) * _grid_size)::int AS y,
          count(*) AS count
        FROM interactions
        WHERE organization_id = _org_id
          AND page_path = _page_path
          AND interaction_type IN ('click', 'rage_click')
          AND timestamp >= _from AND timestamp < _to + interval '1 day'
          AND (_device_type IS NULL OR device_type = _device_type)
          AND (_hostname IS NULL OR page_url LIKE 'https://' || _hostname || '/%' OR page_url LIKE 'http://' || _hostname || '/%')
          AND is_bot = false
          AND viewport_width > 0
          AND (_tp_id IS NULL OR session_id IN (
              SELECT DISTINCT session_id FROM pageviews
              WHERE tp_id = _tp_id AND organization_id = _org_id
          ))
        GROUP BY 1, 2
        ORDER BY count DESC
        LIMIT 10000
      ) g
    ),
    'elements', (
      SELECT coalesce(jsonb_agg(row_to_json(e)), '[]'::jsonb)
      FROM (
        SELECT
          selector_path AS selector,
          element_text AS text,
          element_tag AS tag,
          count(*) AS count,
          (array_agg(element_id) FILTER (WHERE element_id IS NOT NULL))[1] AS element_id,
          (array_agg(element_href) FILTER (WHERE element_href IS NOT NULL))[1] AS element_href
        FROM interactions
        WHERE organization_id = _org_id
          AND page_path = _page_path
          AND interaction_type IN ('click', 'rage_click')
          AND timestamp >= _from AND timestamp < _to + interval '1 day'
          AND (_device_type IS NULL OR device_type = _device_type)
          AND (_hostname IS NULL OR page_url LIKE 'https://' || _hostname || '/%' OR page_url LIKE 'http://' || _hostname || '/%')
          AND is_bot = false
          AND selector_path IS NOT NULL
          AND (_tp_id IS NULL OR session_id IN (
              SELECT DISTINCT session_id FROM pageviews
              WHERE tp_id = _tp_id AND organization_id = _org_id
          ))
        GROUP BY selector_path, element_text, element_tag
        ORDER BY count DESC
        LIMIT 50
      ) e
    )
  ) INTO result
  FROM interactions
  WHERE organization_id = _org_id
    AND page_path = _page_path
    AND interaction_type IN ('click', 'rage_click')
    AND timestamp >= _from AND timestamp < _to + interval '1 day'
    AND (_device_type IS NULL OR device_type = _device_type)
    AND (_hostname IS NULL OR page_url LIKE 'https://' || _hostname || '/%' OR page_url LIKE 'http://' || _hostname || '/%')
    AND is_bot = false
    AND (_tp_id IS NULL OR session_id IN (
        SELECT DISTINCT session_id FROM pageviews
        WHERE tp_id = _tp_id AND organization_id = _org_id
    ));

  RETURN coalesce(result, '{"total_clicks":0,"unique_visitors":0,"grid":[],"elements":[]}'::jsonb);
END;
$$;


--
-- Name: get_heatmap_clicks_v2(uuid, text, timestamp with time zone, timestamp with time zone, text, integer, text, integer, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_heatmap_clicks_v2(_org_id uuid, _page_path text, _from timestamp with time zone, _to timestamp with time zone, _device_type text DEFAULT NULL::text, _grid_size integer DEFAULT 10, _hostname text DEFAULT NULL::text, _target_width integer DEFAULT 1440, _tp_id uuid DEFAULT NULL::uuid, _target_height integer DEFAULT NULL::integer) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
  result jsonb;
BEGIN
  SELECT jsonb_build_object(
    'total_clicks', count(*),
    'unique_visitors', count(DISTINCT visitor_id),
    'grid', (
      SELECT coalesce(jsonb_agg(row_to_json(g)), '[]'::jsonb)
      FROM (
        SELECT
          (floor((x::numeric * _target_width / viewport_width) / _grid_size) * _grid_size)::int AS x,
          (floor(
            CASE WHEN _target_height IS NOT NULL AND page_height > 0
              THEN y::numeric * _target_height / page_height
              ELSE y::numeric
            END / _grid_size
          ) * _grid_size)::int AS y,
          count(*) AS count
        FROM interactions
        WHERE organization_id = _org_id
          AND page_path = _page_path
          AND interaction_type IN ('click', 'rage_click')
          AND timestamp >= _from AND timestamp < _to + interval '1 day'
          AND (_device_type IS NULL OR device_type = _device_type)
          AND (_hostname IS NULL OR page_url LIKE 'https://' || _hostname || '/%' OR page_url LIKE 'http://' || _hostname || '/%')
          AND is_bot = false
          AND viewport_width > 0
          AND (_tp_id IS NULL OR session_id IN (
              SELECT DISTINCT session_id FROM pageviews
              WHERE tp_id = _tp_id AND organization_id = _org_id
          ))
        GROUP BY 1, 2
        ORDER BY count DESC
        LIMIT 10000
      ) g
    ),
    'elements', (
      SELECT coalesce(jsonb_agg(row_to_json(e)), '[]'::jsonb)
      FROM (
        SELECT
          selector_path AS selector,
          element_text AS text,
          element_tag AS tag,
          count(*) AS count,
          (array_agg(element_id) FILTER (WHERE element_id IS NOT NULL))[1] AS element_id,
          (array_agg(element_href) FILTER (WHERE element_href IS NOT NULL))[1] AS element_href
        FROM interactions
        WHERE organization_id = _org_id
          AND page_path = _page_path
          AND interaction_type IN ('click', 'rage_click')
          AND timestamp >= _from AND timestamp < _to + interval '1 day'
          AND (_device_type IS NULL OR device_type = _device_type)
          AND (_hostname IS NULL OR page_url LIKE 'https://' || _hostname || '/%' OR page_url LIKE 'http://' || _hostname || '/%')
          AND is_bot = false
          AND selector_path IS NOT NULL
          AND (_tp_id IS NULL OR session_id IN (
              SELECT DISTINCT session_id FROM pageviews
              WHERE tp_id = _tp_id AND organization_id = _org_id
          ))
        GROUP BY selector_path, element_text, element_tag
        ORDER BY count DESC
        LIMIT 50
      ) e
    )
  ) INTO result
  FROM interactions
  WHERE organization_id = _org_id
    AND page_path = _page_path
    AND interaction_type IN ('click', 'rage_click')
    AND timestamp >= _from AND timestamp < _to + interval '1 day'
    AND (_device_type IS NULL OR device_type = _device_type)
    AND (_hostname IS NULL OR page_url LIKE 'https://' || _hostname || '/%' OR page_url LIKE 'http://' || _hostname || '/%')
    AND is_bot = false
    AND (_tp_id IS NULL OR session_id IN (
        SELECT DISTINCT session_id FROM pageviews
        WHERE tp_id = _tp_id AND organization_id = _org_id
    ));

  RETURN coalesce(result, '{"total_clicks":0,"unique_visitors":0,"grid":[],"elements":[]}'::jsonb);
END;
$$;


--
-- Name: get_last_day_report(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_last_day_report() RETURNS jsonb
    LANGUAGE plpgsql
    AS $$DECLARE
    result JSONB;
    start_ts TIMESTAMPTZ;
    end_ts TIMESTAMPTZ;
    current_time_gmt7 TIMESTAMP;  -- VN local time without timezone
BEGIN
    -- Get current time in Asia/Ho_Chi_Minh as timestamp without time zone
    current_time_gmt7 := NOW() AT TIME ZONE 'Asia/Ho_Chi_Minh';

    -- Calculate start of previous day in VN time converted to UTC timestamptz
    start_ts := (DATE_TRUNC('day', current_time_gmt7 - INTERVAL '1 day')) AT TIME ZONE 'Asia/Ho_Chi_Minh';

    -- Calculate end of previous day in VN time converted to UTC timestamptz
    end_ts := (DATE_TRUNC('day', current_time_gmt7 - INTERVAL '1 day') + INTERVAL '1 day' - INTERVAL '1 second')
              AT TIME ZONE 'Asia/Ho_Chi_Minh';

    WITH filtered_visits AS (
        SELECT *,
               TO_CHAR(created_at AT TIME ZONE 'Asia/Ho_Chi_Minh', 'YYYY-MM-DD') AS date
        FROM visits
        WHERE created_at >= start_ts AND created_at <= end_ts
    ),
    new_users AS (
        SELECT COUNT(*) AS count
        FROM profiles
        WHERE created_at >= start_ts AND created_at <= end_ts
    ),
    new_users_plan AS (
        SELECT 
            p.email,
            COALESCE(pl.name, 'No Plan') AS plan_name
        FROM profiles p
        LEFT JOIN user_plans up ON p.id = up.user_id
        LEFT JOIN plans pl ON up.plan_id = pl.id
        WHERE p.created_at >= start_ts AND p.created_at <= end_ts
        ORDER BY p.created_at DESC
    ),
    referrer_counts AS (
        SELECT COALESCE(referrer, 'unknown') AS referrer, COUNT(*) AS count
        FROM filtered_visits
        GROUP BY referrer
        ORDER BY count DESC
    ),
    type_counts AS (
        SELECT COALESCE(type, 'unknown') AS type, COUNT(*) AS count
        FROM filtered_visits
        GROUP BY type
        ORDER BY count DESC
    ),
    os_counts AS (
        SELECT COALESCE(os, 'unknown') AS os, COUNT(*) AS count
        FROM filtered_visits
        GROUP BY os
        ORDER BY count DESC
    ),
    platform_counts AS (
        SELECT COALESCE(platform, 'unknown') AS platform, COUNT(*) AS count
        FROM filtered_visits
        GROUP BY platform
        ORDER BY count DESC
    ),
    country_counts AS (
        SELECT COALESCE(country, 'unknown') AS country, COUNT(*) AS count
        FROM filtered_visits
        GROUP BY country
        ORDER BY count DESC
    ),
    country_city_counts AS (
        SELECT COALESCE(country, 'unknown') AS country,
               COALESCE(city, 'unknown') AS city,
               COUNT(*) AS count
        FROM filtered_visits
        GROUP BY country, city
        ORDER BY country, count DESC
    ),
    countries_formatted AS (
        SELECT
            cc.country,
            cnt.count AS total_count,
            (
                SELECT jsonb_agg(
                    jsonb_build_object(
                        'city', city,
                        'count', count
                    )
                )
                FROM country_city_counts cc2
                WHERE cc2.country = cc.country
            ) AS cities
        FROM country_counts cnt
        JOIN country_city_counts cc ON cnt.country = cc.country
        GROUP BY cc.country, cnt.count
        ORDER BY cnt.count DESC
    ),
    top_dates AS (
        SELECT date AS visit_date, COUNT(*) AS count
        FROM filtered_visits
        GROUP BY date
        ORDER BY count DESC
        LIMIT 3
    )
    SELECT jsonb_build_object(
        'referrers', (SELECT jsonb_agg(jsonb_build_object('name', referrer, 'count', count)) FROM referrer_counts),
        'types', (SELECT jsonb_agg(jsonb_build_object('name', type, 'count', count)) FROM type_counts),
        'os', (SELECT jsonb_agg(jsonb_build_object('name', os, 'count', count)) FROM os_counts),
        'platforms', (SELECT jsonb_agg(jsonb_build_object('name', platform, 'count', count)) FROM platform_counts),
        'countries', (SELECT jsonb_agg(
                        jsonb_build_object(
                            'name', country, 
                            'count', total_count,
                            'cities', cities
                        )
                    ) FROM countries_formatted),
        'topPerformingDates', (SELECT jsonb_agg(
                                jsonb_build_object(
                                    'name', visit_date,
                                    'count', count
                                )
                            ) FROM top_dates),
        'totalVisits', (SELECT COUNT(*) FROM filtered_visits),
        'newUsers', (SELECT count FROM new_users),
        'newUsersPlan', (SELECT jsonb_agg(
                            jsonb_build_object(
                                'email', email,
                                'plan', plan_name
                            )
                        ) FROM new_users_plan),

        -- Existing formatted string versions:
        'startTime', TO_CHAR(start_ts AT TIME ZONE 'Asia/Ho_Chi_Minh', 'YYYY-MM-DD HH24:MI:SS'),
        'endTime', TO_CHAR(end_ts AT TIME ZONE 'Asia/Ho_Chi_Minh', 'YYYY-MM-DD HH24:MI:SS'),
        'date', TO_CHAR(start_ts AT TIME ZONE 'Asia/Ho_Chi_Minh', 'YYYY-MM-DD'),

        -- Raw timestamptz outputs in ISO 8601
        'startTimeRaw', start_ts,
        'endTimeRaw', end_ts

    ) INTO result;

    RETURN COALESCE(result, '{}'::jsonb);
END;$$;


--
-- Name: get_link_journey_behavioral(uuid, uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_link_journey_behavioral(_org_id uuid, _tp_id uuid, _start_date timestamp with time zone, _end_date timestamp with time zone) RETURNS json
    LANGUAGE sql STABLE
    AS $$
    WITH link_sessions AS (
        SELECT DISTINCT session_id
        FROM pageviews
        WHERE tp_id = _tp_id
          AND organization_id = _org_id
          AND created_at BETWEEN _start_date AND _end_date
    )
    SELECT json_build_object(
        'total_interactions', (
            SELECT COUNT(*) FROM interactions i
            INNER JOIN link_sessions ls ON i.session_id = ls.session_id
            WHERE i.organization_id = _org_id
              AND i.created_at BETWEEN _start_date AND _end_date
        ),
        'rage_clicks', (
            SELECT COUNT(*) FROM interactions i
            INNER JOIN link_sessions ls ON i.session_id = ls.session_id
            WHERE i.organization_id = _org_id
              AND i.interaction_type = 'rage_click'
              AND i.created_at BETWEEN _start_date AND _end_date
        ),
        'top_clicked_elements', (
            SELECT COALESCE(json_agg(row_to_json(t)), '[]'::json)
            FROM (
                SELECT
                    selector_path,
                    element_text,
                    element_tag,
                    COUNT(*) as click_count
                FROM interactions i
                INNER JOIN link_sessions ls ON i.session_id = ls.session_id
                WHERE i.organization_id = _org_id
                  AND i.interaction_type = 'click'
                  AND i.created_at BETWEEN _start_date AND _end_date
                GROUP BY selector_path, element_text, element_tag
                ORDER BY click_count DESC
                LIMIT 5
            ) t
        )
    );
$$;


--
-- Name: get_link_journey_conversions(uuid, uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_link_journey_conversions(_org_id uuid, _tp_id uuid, _start_date timestamp with time zone, _end_date timestamp with time zone) RETURNS json
    LANGUAGE sql STABLE
    AS $$
    SELECT json_build_object(
        'total_leads', (
            SELECT COUNT(*) FROM conversion_events
            WHERE touch_point_id = _tp_id
              AND organization_id = _org_id
              AND event_type = 'lead'
              AND created_at BETWEEN _start_date AND _end_date
        ),
        'total_sales', (
            SELECT COUNT(*) FROM conversion_events
            WHERE touch_point_id = _tp_id
              AND organization_id = _org_id
              AND event_type = 'sale'
              AND created_at BETWEEN _start_date AND _end_date
        ),
        'total_revenue', (
            SELECT COALESCE(SUM(amount), 0) FROM conversion_events
            WHERE touch_point_id = _tp_id
              AND organization_id = _org_id
              AND event_type = 'sale'
              AND created_at BETWEEN _start_date AND _end_date
        ),
        'recent_conversions', (
            SELECT COALESCE(json_agg(row_to_json(t)), '[]'::json)
            FROM (
                SELECT
                    ce.id,
                    ce.event_type,
                    ce.event_name,
                    ce.amount,
                    ce.currency,
                    ce.created_at,
                    cp.name as customer_name,
                    cp.email as customer_email
                FROM conversion_events ce
                LEFT JOIN customer_profiles cp ON ce.customer_profile_id = cp.id
                WHERE ce.touch_point_id = _tp_id
                  AND ce.organization_id = _org_id
                  AND ce.created_at BETWEEN _start_date AND _end_date
                ORDER BY ce.created_at DESC
                LIMIT 5
            ) t
        )
    );
$$;


--
-- Name: get_link_journey_page_flow(uuid, uuid, timestamp with time zone, timestamp with time zone, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_link_journey_page_flow(_org_id uuid, _tp_id uuid, _start_date timestamp with time zone, _end_date timestamp with time zone, _limit integer DEFAULT 10) RETURNS json
    LANGUAGE sql STABLE
    AS $$
    SELECT COALESCE(json_agg(row_to_json(t)), '[]'::json)
    FROM (
        SELECT
            page_path,
            page_title,
            COUNT(*) as pageviews,
            COUNT(DISTINCT session_id) as sessions,
            COUNT(DISTINCT visitor_id) as visitors
        FROM pageviews
        WHERE tp_id = _tp_id
          AND organization_id = _org_id
          AND created_at BETWEEN _start_date AND _end_date
        GROUP BY page_path, page_title
        ORDER BY pageviews DESC
        LIMIT _limit
    ) t;
$$;


--
-- Name: get_link_journey_touch_points(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_link_journey_touch_points(_org_id uuid) RETURNS json
    LANGUAGE sql STABLE
    AS $$
    SELECT COALESCE(json_agg(row_to_json(t)), '[]'::json)
    FROM (
        SELECT DISTINCT
            tp.id,
            tp.name,
            tp.short_url,
            tp.content_value as destination_url,
            COUNT(pv.id) as pageview_count
        FROM touch_points tp
        INNER JOIN pageviews pv ON pv.tp_id = tp.id
        WHERE tp.organization_id = _org_id
          AND tp.deleted_at IS NULL
        GROUP BY tp.id, tp.name, tp.short_url, tp.content_value
        ORDER BY pageview_count DESC
    ) t;
$$;


--
-- Name: get_link_journey_traffic_summary(uuid, uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_link_journey_traffic_summary(_org_id uuid, _tp_id uuid, _start_date timestamp with time zone, _end_date timestamp with time zone) RETURNS json
    LANGUAGE sql STABLE
    AS $$
    SELECT json_build_object(
        'total_clicks', (
            SELECT COUNT(*) FROM visits
            WHERE tp_id = _tp_id
              AND organization_id = _org_id
              AND created_at BETWEEN _start_date AND _end_date
        ),
        'unique_visitors', (
            SELECT COUNT(DISTINCT visitor_id) FROM pageviews
            WHERE tp_id = _tp_id
              AND organization_id = _org_id
              AND created_at BETWEEN _start_date AND _end_date
        ),
        'total_sessions', (
            SELECT COUNT(DISTINCT session_id) FROM pageviews
            WHERE tp_id = _tp_id
              AND organization_id = _org_id
              AND created_at BETWEEN _start_date AND _end_date
        ),
        'bounce_rate', (
            SELECT COALESCE(
                ROUND(
                    COUNT(*) FILTER (WHERE page_count = 1)::numeric /
                    NULLIF(COUNT(*), 0) * 100, 1
                ), 0
            )
            FROM (
                SELECT session_id, COUNT(*) as page_count
                FROM pageviews
                WHERE tp_id = _tp_id
                  AND organization_id = _org_id
                  AND created_at BETWEEN _start_date AND _end_date
                GROUP BY session_id
            ) session_pages
        )
    );
$$;


