--
-- Name: get_organization_details(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_organization_details(org_id uuid) RETURNS TABLE(id uuid, name text, user_id uuid, total_touch_points integer, total_members integer, total_tags integer, total_domains integer, total_integrations integer, max_members_per_org integer, max_tps_per_org integer, max_tags_per_org integer, max_tags_per_tp integer, max_domains_per_org integer, max_integrations_per_org integer, max_slugs_per_tp integer, allowed_tp_types text[], allow_custom_meta_tags boolean, allow_custom_utm_tags boolean)
    LANGUAGE sql SECURITY DEFINER
    AS $$
    SELECT
        o.id,
        o.name,
        o.user_id,
        o.total_touch_points,
        o.total_members,
        o.total_tags,
        o.total_domains,
        o.total_integrations,
        p.max_members_per_org,
        p.max_tps_per_org,
        p.max_tags_per_org,
        p.max_tags_per_tp,
        p.max_domains_per_org,
        p.max_integrations_per_org,
        p.max_slugs_per_tp,
        p.allowed_tp_types,
        p.allow_custom_meta_tags,
        p.allow_custom_utm_tags
    FROM organizations o
    JOIN user_plans u ON o.user_id = u.user_id
    JOIN plans p ON u.plan_id = p.id
    WHERE o.id = org_id;
$$;


--
-- Name: get_organization_details_backup(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_organization_details_backup(org_id uuid) RETURNS TABLE(id uuid, name text, user_id uuid, total_touch_points integer, total_members integer, total_tags integer, total_domains integer, max_members_per_org integer, max_tps_per_org integer, max_tags_per_org integer, max_tags_per_tp integer, max_domains_per_org integer, allowed_tp_types text[])
    LANGUAGE plpgsql
    AS $$BEGIN
  RETURN QUERY
  SELECT
    o.id,
    o.name,
    o.user_id,
    o.total_touch_points,
    o.total_members,
    o.total_tags,
    o.total_domains,
    p.max_members_per_org,
    p.max_tps_per_org,
    p.max_tags_per_org,
    p.max_tags_per_tp,
    p.max_domains_per_org,
