  WHERE o.id = org_id;
END;$$;


--
-- Name: get_organization_reports(uuid, uuid, character varying, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_organization_reports(requesting_user_id uuid, target_organization_id uuid DEFAULT NULL::uuid, report_type_filter character varying DEFAULT NULL::character varying, limit_count integer DEFAULT 50) RETURNS TABLE(report_id uuid, organization_id uuid, organization_name text, report_type character varying, report_period_start timestamp with time zone, report_period_end timestamp with time zone, generated_at timestamp with time zone, status character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- Check if user has access to the organization
  IF target_organization_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM org_members om
    WHERE om.user_id = requesting_user_id 
      AND om.org_id = target_organization_id
  ) THEN
    RAISE EXCEPTION 'Access denied: User does not belong to organization';
  END IF;
  
  RETURN QUERY
  SELECT 
    orp.id,
    orp.organization_id,
    o.name,
    orp.report_type,
    orp.report_period_start,
    orp.report_period_end,
    orp.generated_at,
    orp.status
  FROM organization_reports orp
  JOIN organizations o ON orp.organization_id = o.id
  JOIN org_members om ON o.id = om.org_id
  WHERE om.user_id = requesting_user_id
    AND (target_organization_id IS NULL OR orp.organization_id = target_organization_id)
    AND (report_type_filter IS NULL OR orp.report_type = report_type_filter)
  ORDER BY orp.generated_at DESC
  LIMIT limit_count;
END;
$$;


--
-- Name: get_overview_daily_trend(uuid, integer, text, uuid[], uuid[], boolean, uuid[], boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_overview_daily_trend(p_organization_id uuid, p_period_days integer, p_timezone text DEFAULT 'UTC'::text, p_tag_ids uuid[] DEFAULT NULL::uuid[], p_touchpoint_ids uuid[] DEFAULT NULL::uuid[], p_is_premium boolean DEFAULT false, p_collection_ids uuid[] DEFAULT NULL::uuid[], p_include_null_collection boolean DEFAULT false) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    start_date TIMESTAMPTZ;
    end_date TIMESTAMPTZ;
    result JSON;
BEGIN
    -- Validate tier restrictions
    IF NOT p_is_premium AND p_period_days != 7 THEN
        RETURN json_build_object('error', TRUE, 'message', 'Free tier limited to 7 days only');
    END IF;
    
    IF NOT p_is_premium AND p_touchpoint_ids IS NOT NULL AND array_length(p_touchpoint_ids, 1) > 1 THEN
        RETURN json_build_object('error', TRUE, 'message', 'Free tier limited to 1 touchpoint only');
    END IF;

    -- Calculate date range in user's timezone
    end_date := CURRENT_TIMESTAMP AT TIME ZONE p_timezone;
    start_date := end_date - (p_period_days || ' days')::INTERVAL;
    
    WITH daily_series AS (
        SELECT 
            generate_series(
                DATE_TRUNC('day', start_date),
                DATE_TRUNC('day', end_date - interval '1 day'),
                interval '1 day'
            )::DATE as date
    ),
    filtered_touchpoints AS (
        -- Apply hierarchical filtering including collections
        SELECT DISTINCT tp.id as tp_id
        FROM touch_points tp
        WHERE tp.organization_id = p_organization_id
            AND tp.deleted_at IS NULL
            AND (
                p_tag_ids IS NULL
                OR tp.id IN (
                    SELECT DISTINCT ttl.tp_id
                    FROM tp_tag_links ttl
                    WHERE ttl.tag_id = ANY(p_tag_ids)
                )
            )
            AND (
                p_touchpoint_ids IS NULL
                OR tp.id = ANY(p_touchpoint_ids)
            )
            AND (
                p_collection_ids IS NULL
                OR tp.collection_id = ANY(p_collection_ids)
                OR (p_include_null_collection AND tp.collection_id IS NULL)
            )
    ),
    daily_stats AS (
        SELECT 
            DATE(v.created_at AT TIME ZONE p_timezone) as date,
            COUNT(CASE WHEN v.type = 'LINK' THEN 1 END) as link_clicks,
            COUNT(CASE WHEN v.type = 'QR' THEN 1 END) as qr_scans,
            COUNT(CASE WHEN v.type = 'NFC' THEN 1 END) as nfc_taps,
            COUNT(CASE WHEN v.type = 'WIFI' THEN 1 END) as wifi_accesses,
            COUNT(*) as total_interactions,
            COUNT(DISTINCT v.fp) as unique_users,
            COUNT(DISTINCT v.tp_id) as active_touchpoints
        FROM visits v
        WHERE v.organization_id = p_organization_id
            AND v.created_at >= start_date
            AND v.created_at < end_date            
            AND (
                -- FIXED: Include p_collection_ids in the no-filter check
                (p_tag_ids IS NULL AND p_touchpoint_ids IS NULL AND p_collection_ids IS NULL)
                OR 
                -- Apply hierarchical filtering
                v.tp_id IN (SELECT tp_id FROM filtered_touchpoints)
            )
        GROUP BY DATE(v.created_at AT TIME ZONE p_timezone)
    ),
    complete_daily_data AS (
        SELECT 
            ds.date,
            COALESCE(s.link_clicks, 0) as link_clicks,
            COALESCE(s.qr_scans, 0) as qr_scans,
            COALESCE(s.nfc_taps, 0) as nfc_taps,
            COALESCE(s.wifi_accesses, 0) as wifi_accesses,
            COALESCE(s.total_interactions, 0) as total_interactions,
            COALESCE(s.unique_users, 0) as unique_users,
            COALESCE(s.active_touchpoints, 0) as active_touchpoints
        FROM daily_series ds
        LEFT JOIN daily_stats s ON ds.date = s.date
        ORDER BY ds.date
    ),
    trend_analysis AS (
        SELECT 
            *,
            -- Calculate 3-day moving average for trend smoothing
            ROUND(AVG(total_interactions) OVER (
                ORDER BY date 
                ROWS BETWEEN 2 PRECEDING AND CURRENT ROW
            ), 1) as moving_avg_3day,
            -- Week-over-week comparison where applicable
            LAG(total_interactions, 7) OVER (ORDER BY date) as same_day_last_week,
            -- Growth rate calculation
            CASE 
                WHEN LAG(total_interactions) OVER (ORDER BY date) > 0 THEN
                    ROUND(
                        ((total_interactions - LAG(total_interactions) OVER (ORDER BY date))::DECIMAL / 
                         LAG(total_interactions) OVER (ORDER BY date)) * 100, 1
                    )
                ELSE NULL
            END as daily_growth_pct
        FROM complete_daily_data
    )
    SELECT json_build_object(
        'daily_data', json_agg(
            json_build_object(
                'date', date,
                'link_clicks', link_clicks,
                'qr_scans', qr_scans,
                'nfc_taps', nfc_taps,
                'wifi_accesses', wifi_accesses,
                'total_interactions', total_interactions,
                'unique_users', unique_users,
                'active_touchpoints', active_touchpoints,
                'moving_avg_3day', moving_avg_3day,
                'daily_growth_pct', daily_growth_pct,
                'same_day_last_week', same_day_last_week
            ) ORDER BY date
        ),
        'summary', json_build_object(
            'total_days', COUNT(*),
            'days_with_activity', COUNT(CASE WHEN total_interactions > 0 THEN 1 END),
            'avg_daily_interactions', ROUND(AVG(total_interactions), 1),
            'avg_daily_users', ROUND(AVG(unique_users), 1),
            'peak_day', json_build_object(
                'date', (SELECT date FROM trend_analysis ORDER BY total_interactions DESC LIMIT 1),
                'interactions', (SELECT total_interactions FROM trend_analysis ORDER BY total_interactions DESC LIMIT 1)
            ),
            'trend_direction', CASE
                WHEN AVG(daily_growth_pct) > 5 THEN 'strong_growth'
                WHEN AVG(daily_growth_pct) > 0 THEN 'growth'
                WHEN AVG(daily_growth_pct) > -5 THEN 'stable'
                ELSE 'decline'
            END
        )
    ) INTO result
    FROM trend_analysis;
    
    RETURN result;
    
EXCEPTION WHEN OTHERS THEN
    RETURN json_build_object(
        'error', TRUE,
        'message', SQLERRM,
        'period_days', p_period_days,
        'organization_id', p_organization_id
    );
END;
$$;


--
-- Name: get_overview_daily_trend_old(uuid, integer, text, uuid[], uuid[], boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_overview_daily_trend_old(p_organization_id uuid, p_period_days integer, p_timezone text DEFAULT 'UTC'::text, p_tag_ids uuid[] DEFAULT NULL::uuid[], p_touchpoint_ids uuid[] DEFAULT NULL::uuid[], p_is_premium boolean DEFAULT false) RETURNS json
    LANGUAGE plpgsql
    AS $$DECLARE
    start_date TIMESTAMPTZ;
    end_date TIMESTAMPTZ;
    result JSON;
BEGIN
    -- Validate tier restrictions
    IF NOT p_is_premium AND p_period_days != 7 THEN
        RETURN json_build_object('error', TRUE, 'message', 'Free tier limited to 7 days only');
    END IF;
    
    IF NOT p_is_premium AND p_touchpoint_ids IS NOT NULL AND array_length(p_touchpoint_ids, 1) > 1 THEN
        RETURN json_build_object('error', TRUE, 'message', 'Free tier limited to 1 touchpoint only');
    END IF;

    -- Calculate date range in user's timezone
    end_date := CURRENT_TIMESTAMP AT TIME ZONE p_timezone;
    start_date := end_date - (p_period_days || ' days')::INTERVAL;
    
    WITH daily_series AS (
        SELECT 
            generate_series(
                DATE_TRUNC('day', start_date),
                DATE_TRUNC('day', end_date - interval '1 day'),
                interval '1 day'
            )::DATE as date
    ),
    filtered_touchpoints AS (
        -- Apply hierarchical filtering
        SELECT DISTINCT tp.id as tp_id
        FROM touch_points tp
        WHERE tp.organization_id = p_organization_id
            AND tp.deleted_at IS NULL
            AND (
                p_tag_ids IS NULL 
                OR tp.id IN (
                    SELECT DISTINCT ttl.tp_id 
                    FROM tp_tag_links ttl 
                    WHERE ttl.tag_id = ANY(p_tag_ids)
                )
            )
            AND (
                p_touchpoint_ids IS NULL 
                OR tp.id = ANY(p_touchpoint_ids)
            )
    ),
    daily_stats AS (
        SELECT 
            DATE(v.created_at AT TIME ZONE p_timezone) as date,
            COUNT(CASE WHEN v.type = 'LINK' THEN 1 END) as link_clicks,
            COUNT(CASE WHEN v.type = 'QR' THEN 1 END) as qr_scans,
            COUNT(CASE WHEN v.type = 'NFC' THEN 1 END) as nfc_taps,
            COUNT(CASE WHEN v.type = 'WIFI' THEN 1 END) as wifi_accesses,
            COUNT(*) as total_interactions,
            COUNT(DISTINCT v.fp) as unique_users,
            COUNT(DISTINCT v.tp_id) as active_touchpoints
        FROM visits v
        WHERE v.organization_id = p_organization_id
            AND v.created_at >= start_date
            AND v.created_at < end_date            
            AND (
                -- No filtering if no touchpoints specified
                (p_tag_ids IS NULL AND p_touchpoint_ids IS NULL)
                OR 
                -- Apply hierarchical filtering
                v.tp_id IN (SELECT tp_id FROM filtered_touchpoints)
            )
        GROUP BY DATE(v.created_at AT TIME ZONE p_timezone)
    ),
    complete_daily_data AS (
        SELECT 
            ds.date,
            COALESCE(s.link_clicks, 0) as link_clicks,
            COALESCE(s.qr_scans, 0) as qr_scans,
            COALESCE(s.nfc_taps, 0) as nfc_taps,
            COALESCE(s.wifi_accesses, 0) as wifi_accesses,
            COALESCE(s.total_interactions, 0) as total_interactions,
            COALESCE(s.unique_users, 0) as unique_users,
            COALESCE(s.active_touchpoints, 0) as active_touchpoints
        FROM daily_series ds
        LEFT JOIN daily_stats s ON ds.date = s.date
        ORDER BY ds.date
    ),
    trend_analysis AS (
        SELECT 
            *,
            -- Calculate 3-day moving average for trend smoothing
            ROUND(AVG(total_interactions) OVER (
                ORDER BY date 
                ROWS BETWEEN 2 PRECEDING AND CURRENT ROW
            ), 1) as moving_avg_3day,
            -- Week-over-week comparison where applicable
            LAG(total_interactions, 7) OVER (ORDER BY date) as same_day_last_week,
            -- Growth rate calculation
            CASE 
                WHEN LAG(total_interactions) OVER (ORDER BY date) > 0 THEN
                    ROUND(
                        ((total_interactions - LAG(total_interactions) OVER (ORDER BY date))::DECIMAL / 
                         LAG(total_interactions) OVER (ORDER BY date)) * 100, 1
                    )
                ELSE NULL
            END as daily_growth_pct
        FROM complete_daily_data
    )
    SELECT json_build_object(
        -- 'period_info', json_build_object(
        --     'period_days', p_period_days,
        --     'start_date', start_date,
        --     'end_date', end_date,
        --     'timezone', p_timezone,
        --     'is_premium', p_is_premium
        -- ),
        -- 'filters_applied', json_build_object(
        --     'has_filters', (p_tag_ids IS NOT NULL OR p_touchpoint_ids IS NOT NULL),
        --     'tags_count', COALESCE(array_length(p_tag_ids, 1), 0),
        --     'touchpoints_count', COALESCE(array_length(p_touchpoint_ids, 1), 0),
        --     'filtered_touchpoints_available', (SELECT COUNT(*) FROM filtered_touchpoints)
        -- ),
        'daily_data', json_agg(
            json_build_object(
                'date', date,
                'link_clicks', link_clicks,
                'qr_scans', qr_scans,
                'nfc_taps', nfc_taps,
                'wifi_accesses', wifi_accesses,
                'total_interactions', total_interactions,
                'unique_users', unique_users,
                'active_touchpoints', active_touchpoints,
                'moving_avg_3day', moving_avg_3day,
                'daily_growth_pct', daily_growth_pct,
                'same_day_last_week', same_day_last_week
            ) ORDER BY date
        ),
        'summary', json_build_object(
            'total_days', COUNT(*),
            'days_with_activity', COUNT(CASE WHEN total_interactions > 0 THEN 1 END),
            'avg_daily_interactions', ROUND(AVG(total_interactions), 1),
            'avg_daily_users', ROUND(AVG(unique_users), 1),
            'peak_day', json_build_object(
                'date', (SELECT date FROM trend_analysis ORDER BY total_interactions DESC LIMIT 1),
                'interactions', (SELECT total_interactions FROM trend_analysis ORDER BY total_interactions DESC LIMIT 1)
            ),
            'trend_direction', CASE
                WHEN AVG(daily_growth_pct) > 5 THEN 'strong_growth'
                WHEN AVG(daily_growth_pct) > 0 THEN 'growth'
                WHEN AVG(daily_growth_pct) > -5 THEN 'stable'
                ELSE 'decline'
            END
        )
    ) INTO result
    FROM trend_analysis;
    
    RETURN result;
    
EXCEPTION WHEN OTHERS THEN
    RETURN json_build_object(
        'error', TRUE,
        'message', SQLERRM,
        'period_days', p_period_days,
        'organization_id', p_organization_id
    );
END;$$;


--
-- Name: get_overview_data(uuid, text, uuid[], boolean, uuid, boolean, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_overview_data(_organization_id uuid, _timezone text DEFAULT 'UTC'::text, _collection_ids uuid[] DEFAULT NULL::uuid[], _include_null_collection boolean DEFAULT true, _user_id uuid DEFAULT NULL::uuid, _exclude_bot boolean DEFAULT true, _include_pro boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql
    AS $_$
DECLARE
  -- Compute period boundaries in UTC, timezone-aware:
  -- date_trunc in user's tz → AT TIME ZONE converts back to UTC timestamptz
  _period_start timestamptz := date_trunc('day', NOW() AT TIME ZONE _timezone - interval '6 days') AT TIME ZONE _timezone;
  _period_end   timestamptz := (date_trunc('day', NOW() AT TIME ZONE _timezone) + interval '1 day') AT TIME ZONE _timezone;
  _prev_start   timestamptz := _period_start - interval '7 days';
  _prev_end     timestamptz := _period_start;
  _result jsonb := '{}'::jsonb;
  _links jsonb;
  _website jsonb;
  _conversions jsonb;
  _trend jsonb;
BEGIN
  -- Normalize empty array to NULL (empty array bypasses user_id filter via IS NOT NULL)
  IF _collection_ids IS NOT NULL AND array_length(_collection_ids, 1) IS NULL THEN
    _collection_ids := NULL;
  END IF;

  -- TREND: 7-day daily aggregation
  WITH days AS (
    SELECT generate_series(
      (_period_start AT TIME ZONE _timezone)::date,
      ((_period_end - interval '1 second') AT TIME ZONE _timezone)::date,
      interval '1 day'
    )::date AS day
  ),
  daily_clicks AS (
    SELECT date_trunc('day', v.created_at AT TIME ZONE _timezone)::date AS day,
           COUNT(*) AS cnt
    FROM visits v
    WHERE v.organization_id = _organization_id
      AND v.created_at >= _period_start AND v.created_at < _period_end
      AND (_exclude_bot = false OR v.is_bot = false)
      AND (
        _collection_ids IS NULL
        OR v.tp_id IN (SELECT tp.id FROM touch_points tp WHERE tp.collection_id = ANY(_collection_ids))
        OR (_include_null_collection AND v.tp_id IN (SELECT tp.id FROM touch_points tp WHERE tp.collection_id IS NULL AND tp.organization_id = _organization_id))
      )
      AND (
        _collection_ids IS NOT NULL
        OR _user_id IS NULL
        OR v.tp_id IN (SELECT tp.id FROM touch_points tp WHERE tp.collection_id IS NULL AND tp.user_id = _user_id AND tp.organization_id = _organization_id)
      )
    GROUP BY 1
  ),
  daily_pageviews AS (
    SELECT date_trunc('day', p.timestamp AT TIME ZONE _timezone)::date AS day,
           COUNT(*) AS cnt
    FROM pageviews p
    WHERE p.organization_id = _organization_id
      AND p.timestamp >= _period_start AND p.timestamp < _period_end
      AND _include_pro = true
      AND (_exclude_bot = false OR p.is_bot = false)
    GROUP BY 1
  ),
  daily_conversions AS (
    SELECT date_trunc('day', ce.created_at AT TIME ZONE _timezone)::date AS day,
           COUNT(*) AS cnt
    FROM conversion_events ce
    WHERE ce.organization_id = _organization_id
      AND ce.created_at >= _period_start AND ce.created_at < _period_end
      AND _include_pro = true
    GROUP BY 1
  )
  SELECT jsonb_agg(
    jsonb_build_object(
      'date', d.day::text,
      'clicks', COALESCE(dc.cnt, 0),
      'pageviews', COALESCE(dp.cnt, 0),
      'conversions', COALESCE(dconv.cnt, 0)
    ) ORDER BY d.day
  )
  INTO _trend
  FROM days d
  LEFT JOIN daily_clicks dc ON dc.day = d.day
  LEFT JOIN daily_pageviews dp ON dp.day = d.day
  LEFT JOIN daily_conversions dconv ON dconv.day = d.day;

  _result := _result || jsonb_build_object('trend', COALESCE(_trend, '[]'::jsonb));

  -- LINKS: current + previous period
  WITH visit_filter AS (
    SELECT v.id, v.fp, v.type, v.tp_id, v.created_at
    FROM visits v
    WHERE v.organization_id = _organization_id
      AND (_exclude_bot = false OR v.is_bot = false)
      AND (
        _collection_ids IS NULL
        OR v.tp_id IN (SELECT tp.id FROM touch_points tp WHERE tp.collection_id = ANY(_collection_ids))
        OR (_include_null_collection AND v.tp_id IN (SELECT tp.id FROM touch_points tp WHERE tp.collection_id IS NULL AND tp.organization_id = _organization_id))
      )
      AND (
        _collection_ids IS NOT NULL
        OR _user_id IS NULL
        OR v.tp_id IN (SELECT tp.id FROM touch_points tp WHERE tp.collection_id IS NULL AND tp.user_id = _user_id AND tp.organization_id = _organization_id)
      )
  ),
  current_totals AS (
    SELECT COUNT(*) AS total,
           COUNT(DISTINCT fp) FILTER (WHERE fp IS NOT NULL) AS unique_count
    FROM visit_filter
    WHERE created_at >= _period_start AND created_at < _period_end
  ),
  current_channels AS (
    SELECT type, COUNT(*) AS count
    FROM visit_filter
    WHERE created_at >= _period_start AND created_at < _period_end
    GROUP BY type
  ),
  prev_totals AS (
    SELECT COUNT(*) AS total,
           COUNT(DISTINCT fp) FILTER (WHERE fp IS NOT NULL) AS unique_count
    FROM visit_filter
    WHERE created_at >= _prev_start AND created_at < _prev_end
  ),
  top_links AS (
    SELECT tp.name, s.slug, COUNT(v.id) AS cnt
    FROM visits v
    JOIN touch_points tp ON tp.id = v.tp_id
    LEFT JOIN LATERAL (
      SELECT sl.slug FROM slugs sl WHERE sl.tp_id = tp.id LIMIT 1
    ) s ON true
    WHERE v.organization_id = _organization_id
      AND v.created_at >= _period_start AND v.created_at < _period_end
      AND (_exclude_bot = false OR v.is_bot = false)
      AND (
        _collection_ids IS NULL
        OR tp.collection_id = ANY(_collection_ids)
        OR (_include_null_collection AND tp.collection_id IS NULL)
      )
      AND (
        _collection_ids IS NOT NULL
        OR _user_id IS NULL
        OR (tp.collection_id IS NULL AND tp.user_id = _user_id AND tp.organization_id = _organization_id)
      )
    GROUP BY tp.name, s.slug
    ORDER BY cnt DESC
    LIMIT 3
  )
  SELECT jsonb_build_object(
    'totalClicks', (SELECT COALESCE(total, 0) FROM current_totals),
    'totalClicksPrev', (SELECT COALESCE(total, 0) FROM prev_totals),
    'uniqueClicks', (SELECT COALESCE(unique_count, 0) FROM current_totals),
    'uniqueClicksPrev', (SELECT COALESCE(unique_count, 0) FROM prev_totals),
    'avgPerDay', ROUND((SELECT COALESCE(total, 0) FROM current_totals)::numeric / 7, 0),
    'avgPerDayPrev', ROUND((SELECT COALESCE(total, 0) FROM prev_totals)::numeric / 7, 0),
    'channels', (SELECT COALESCE(jsonb_agg(jsonb_build_object('name', type, 'count', count)), '[]'::jsonb) FROM current_channels),
    'topLinks', (SELECT COALESCE(jsonb_agg(jsonb_build_object('name', name, 'slug', slug, 'count', cnt) ORDER BY cnt DESC), '[]'::jsonb) FROM top_links)
  )
  INTO _links;

  _result := _result || jsonb_build_object('links', _links);

  -- WEBSITE (Pro only)
  IF _include_pro THEN
    WITH current_pv AS (
      SELECT COUNT(*) AS total_pv,
             COUNT(DISTINCT li2_cid) AS unique_visitors,
             COUNT(DISTINCT session_id) AS total_sessions
      FROM pageviews
      WHERE organization_id = _organization_id
        AND timestamp >= _period_start AND timestamp < _period_end
        AND (_exclude_bot = false OR is_bot = false)
    ),
    prev_pv AS (
      SELECT COUNT(*) AS total_pv,
             COUNT(DISTINCT li2_cid) AS unique_visitors,
             COUNT(DISTINCT session_id) AS total_sessions
      FROM pageviews
      WHERE organization_id = _organization_id
        AND timestamp >= _prev_start AND timestamp < _prev_end
        AND (_exclude_bot = false OR is_bot = false)
    ),
    top_sources AS (
      SELECT CASE
               WHEN page_referrer IS NULL OR page_referrer = '' THEN 'Direct'
               ELSE COALESCE(
                 regexp_replace(page_referrer, '^https?://([^/]+).*$', '\1'),
                 page_referrer
               )
             END AS source,
             COUNT(*) AS cnt
      FROM pageviews
      WHERE organization_id = _organization_id
        AND timestamp >= _period_start AND timestamp < _period_end
        AND (_exclude_bot = false OR is_bot = false)
      GROUP BY 1
      ORDER BY cnt DESC
      LIMIT 3
    ),
    total_pv_for_pct AS (
      SELECT COUNT(*) AS total FROM pageviews
      WHERE organization_id = _organization_id
        AND timestamp >= _period_start AND timestamp < _period_end
        AND (_exclude_bot = false OR is_bot = false)
    ),
    top_pages AS (
      SELECT
        regexp_replace(page_url, '^https?://([^/]+).*', '\1') AS hostname,
        page_path,
        COUNT(*) AS cnt
      FROM pageviews
      WHERE organization_id = _organization_id
        AND timestamp >= _period_start AND timestamp < _period_end
        AND (_exclude_bot = false OR is_bot = false)
      GROUP BY hostname, page_path
      ORDER BY cnt DESC
      LIMIT 3
    )
    SELECT jsonb_build_object(
      'totalPageviews', (SELECT total_pv FROM current_pv),
      'totalPageviewsPrev', (SELECT total_pv FROM prev_pv),
      'uniqueVisitors', (SELECT unique_visitors FROM current_pv),
      'uniqueVisitorsPrev', (SELECT unique_visitors FROM prev_pv),
      'totalSessions', (SELECT total_sessions FROM current_pv),
      'totalSessionsPrev', (SELECT total_sessions FROM prev_pv),
      'topSources', (SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'name', source,
        'percentage', ROUND(cnt::numeric / GREATEST((SELECT total FROM total_pv_for_pct), 1) * 100, 1)
      ) ORDER BY cnt DESC), '[]'::jsonb) FROM top_sources),
      'topPages', (SELECT COALESCE(jsonb_agg(jsonb_build_object('hostname', hostname, 'path', page_path, 'count', cnt) ORDER BY cnt DESC), '[]'::jsonb) FROM top_pages)
    )
    INTO _website;

    _result := _result || jsonb_build_object('website', _website);
  ELSE
    _result := _result || jsonb_build_object('website', null);
  END IF;

  -- CONVERSIONS (Pro only)
  IF _include_pro THEN
    WITH current_conv AS (
      SELECT COUNT(*) AS total,
             COUNT(*) FILTER (WHERE event_type = 'lead') AS leads,
             COUNT(*) FILTER (WHERE event_type = 'sale') AS sales
      FROM conversion_events
      WHERE organization_id = _organization_id
        AND created_at >= _period_start AND created_at < _period_end
    ),
    prev_conv AS (
      SELECT COUNT(*) AS total,
             COUNT(*) FILTER (WHERE event_type = 'lead') AS leads,
             COUNT(*) FILTER (WHERE event_type = 'sale') AS sales
      FROM conversion_events
      WHERE organization_id = _organization_id
        AND created_at >= _prev_start AND created_at < _prev_end
    ),
    click_count AS (
      SELECT COUNT(*) AS cnt FROM visits v
      WHERE v.organization_id = _organization_id
        AND v.created_at >= _period_start AND v.created_at < _period_end
        AND (_exclude_bot = false OR v.is_bot = false)
        AND (
          _collection_ids IS NULL
          OR v.tp_id IN (SELECT tp.id FROM touch_points tp WHERE tp.collection_id = ANY(_collection_ids))
          OR (_include_null_collection AND v.tp_id IN (SELECT tp.id FROM touch_points tp WHERE tp.collection_id IS NULL AND tp.organization_id = _organization_id))
        )
        AND (
          _collection_ids IS NOT NULL
          OR _user_id IS NULL
          OR v.tp_id IN (SELECT tp.id FROM touch_points tp WHERE tp.collection_id IS NULL AND tp.user_id = _user_id AND tp.organization_id = _organization_id)
        )
    )
    SELECT jsonb_build_object(
      'totalConversions', (SELECT total FROM current_conv),
      'totalConversionsPrev', (SELECT total FROM prev_conv),
      'totalLeads', (SELECT leads FROM current_conv),
      'totalLeadsPrev', (SELECT leads FROM prev_conv),
      'totalSales', (SELECT sales FROM current_conv),
      'totalSalesPrev', (SELECT sales FROM prev_conv),
      'clickToLeadRate', ROUND(
        (SELECT leads FROM current_conv)::numeric / GREATEST((SELECT cnt FROM click_count), 1) * 100, 1
      ),
      'leadToSaleRate', ROUND(
        (SELECT sales FROM current_conv)::numeric / GREATEST((SELECT leads FROM current_conv), 1) * 100, 1
      )
    )
    INTO _conversions;

    _result := _result || jsonb_build_object('conversions', _conversions);
  ELSE
    _result := _result || jsonb_build_object('conversions', null);
  END IF;

  RETURN _result;
END;
$_$;


--
-- Name: get_overview_peak_heatmap(uuid, integer, text, uuid[], uuid[], boolean, uuid[], boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_overview_peak_heatmap(p_organization_id uuid, p_period_days integer, p_timezone text DEFAULT 'UTC'::text, p_tag_ids uuid[] DEFAULT NULL::uuid[], p_touchpoint_ids uuid[] DEFAULT NULL::uuid[], p_is_premium boolean DEFAULT false, p_collection_ids uuid[] DEFAULT NULL::uuid[], p_include_null_collection boolean DEFAULT false) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    start_date TIMESTAMPTZ;
    end_date TIMESTAMPTZ;
    result JSON;
BEGIN
    -- Premium feature check
    IF NOT p_is_premium THEN
        RETURN json_build_object(
            'premium_feature', TRUE,
            'message', 'Peak Performance Heatmap requires Premium plan'
        );
    END IF;

    -- Calculate date range in user's timezone
    end_date := CURRENT_TIMESTAMP AT TIME ZONE p_timezone;
    start_date := end_date - (p_period_days || ' days')::INTERVAL;
    
    WITH hourly_dow_matrix AS (
        -- Generate complete 24×7 matrix (168 time slots)
        SELECT 
            days.day_of_week,
            hours.hour_of_day
        FROM generate_series(0, 6) AS days(day_of_week)  -- 7 days
        CROSS JOIN generate_series(0, 23) AS hours(hour_of_day)  -- 24 hours
    ),
    filtered_visits AS (
        -- Apply hierarchical filtering directly to visits
        SELECT 
            v.created_at,
            v.fp,
            v.type,
            v.tp_id
        FROM visits v
        WHERE v.organization_id = p_organization_id
            AND v.created_at >= start_date
            AND v.created_at < end_date            
            AND (
                -- No filtering if no filters specified
                (p_tag_ids IS NULL AND p_touchpoint_ids IS NULL)
                OR 
                -- Apply hierarchical filtering: tags first, then touchpoints
                (
                    (p_tag_ids IS NULL OR v.tp_id IN (
                        SELECT DISTINCT ttl.tp_id 
                        FROM tp_tag_links ttl 
                        WHERE ttl.tag_id = ANY(p_tag_ids)
                    ))
                    AND
                    (p_touchpoint_ids IS NULL OR v.tp_id = ANY(p_touchpoint_ids))
                )
            )
            AND (
                p_collection_ids IS NULL
                OR v.tp_id IN (
                    SELECT tp.id
                    FROM touch_points tp
                    WHERE tp.collection_id = ANY(p_collection_ids)
                       OR (p_include_null_collection AND tp.collection_id IS NULL)
                )
            )
    ),
    activity_heatmap AS (
        -- Aggregate interactions by hour and day of week
        SELECT 
            EXTRACT(dow FROM fv.created_at AT TIME ZONE p_timezone)::INTEGER as day_of_week,
            EXTRACT(hour FROM fv.created_at AT TIME ZONE p_timezone)::INTEGER as hour_of_day,
            COUNT(*) as total_interactions,
            COUNT(DISTINCT fv.fp) as unique_users,
            COUNT(CASE WHEN fv.type = 'LINK' THEN 1 END) as link_clicks,
            COUNT(CASE WHEN fv.type = 'QR' THEN 1 END) as qr_scans,
            COUNT(CASE WHEN fv.type = 'NFC' THEN 1 END) as nfc_taps,
            COUNT(CASE WHEN fv.type = 'WIFI' THEN 1 END) as wifi_accesses,
            COUNT(DISTINCT fv.tp_id) as active_touchpoints,
            -- Calculate interactions per user for this time slot
            ROUND(COUNT(*)::DECIMAL / NULLIF(COUNT(DISTINCT fv.fp), 0), 2) as interactions_per_user
        FROM filtered_visits fv
        GROUP BY 
            EXTRACT(dow FROM fv.created_at AT TIME ZONE p_timezone),
            EXTRACT(hour FROM fv.created_at AT TIME ZONE p_timezone)
    ),
    complete_heatmap AS (
        -- Fill in all 168 time slots with data
        SELECT 
            hdm.day_of_week,
            hdm.hour_of_day,
            CASE hdm.day_of_week
                WHEN 0 THEN 'Sunday'
                WHEN 1 THEN 'Monday'
                WHEN 2 THEN 'Tuesday'
                WHEN 3 THEN 'Wednesday'
                WHEN 4 THEN 'Thursday'
                WHEN 5 THEN 'Friday'
                WHEN 6 THEN 'Saturday'
            END as day_name,
            COALESCE(ah.total_interactions, 0) as interactions,
            COALESCE(ah.unique_users, 0) as unique_users,
            COALESCE(ah.link_clicks, 0) as link_clicks,
            COALESCE(ah.qr_scans, 0) as qr_scans,
            COALESCE(ah.nfc_taps, 0) as nfc_taps,
            COALESCE(ah.wifi_accesses, 0) as wifi_accesses,
            COALESCE(ah.active_touchpoints, 0) as active_touchpoints,
            COALESCE(ah.interactions_per_user, 0) as interactions_per_user,
            -- Simple business hours classification
            CASE 
                WHEN hdm.hour_of_day BETWEEN 9 AND 17 AND hdm.day_of_week BETWEEN 1 AND 5 THEN 'business_hours'
                WHEN hdm.hour_of_day BETWEEN 18 AND 22 THEN 'evening'
                WHEN hdm.day_of_week IN (0, 6) THEN 'weekend'
                WHEN hdm.hour_of_day BETWEEN 0 AND 6 THEN 'late_night'
                ELSE 'other'
            END as time_category
        FROM hourly_dow_matrix hdm
        LEFT JOIN activity_heatmap ah ON hdm.day_of_week = ah.day_of_week 
                                     AND hdm.hour_of_day = ah.hour_of_day
    ),
    heatmap_with_intensity AS (
        -- Calculate intensity levels using simple quartile-based approach
        SELECT 
            *,
            -- Calculate intensity using actual data distribution (not percentiles of sparse data)
            CASE 
                WHEN interactions = 0 THEN 'no_activity'
                WHEN interactions = 1 THEN 'minimal'
                WHEN interactions <= 5 THEN 'low'
                WHEN interactions <= 15 THEN 'moderate'
                WHEN interactions <= 30 THEN 'high'
                ELSE 'peak'
            END as activity_level,
            -- Calculate intensity score (0-100) for heatmap visualization
            CASE 
                WHEN interactions = 0 THEN 0
                ELSE LEAST(100, ROUND((interactions::DECIMAL / NULLIF((SELECT MAX(interactions) FROM complete_heatmap), 0)) * 100))
            END as intensity_score
        FROM complete_heatmap
    ),
    top_performers AS (
        -- Pre-calculate top performing time slots with ranking
        SELECT 
            day_name,
            hour_of_day,
            interactions,
            unique_users,
            time_category,
            ROW_NUMBER() OVER (ORDER BY interactions DESC, unique_users DESC) as rank
        FROM heatmap_with_intensity 
        WHERE interactions > 0
    ),
    summary_stats AS (
        -- Calculate summary statistics for insights
        SELECT 
            COUNT(*) as total_time_slots,
            COUNT(CASE WHEN interactions > 0 THEN 1 END) as active_time_slots,
            ROUND(AVG(interactions), 1) as avg_interactions_per_slot,
            MAX(interactions) as peak_interactions,
            COUNT(CASE WHEN time_category = 'business_hours' AND interactions > 0 THEN 1 END) as active_business_hours,
            COUNT(CASE WHEN time_category = 'weekend' AND interactions > 0 THEN 1 END) as active_weekend_slots,
            COUNT(CASE WHEN time_category = 'evening' AND interactions > 0 THEN 1 END) as active_evening_slots
        FROM heatmap_with_intensity
    )
    SELECT json_build_object(
        'period_info', json_build_object(
            'period_days', p_period_days,
            'start_date', start_date,
            'end_date', end_date,
            'timezone', p_timezone,
            'is_premium', p_is_premium
        ),
        'filters_applied', json_build_object(
            'has_filters', (p_tag_ids IS NOT NULL OR p_touchpoint_ids IS NOT NULL),
            'tags_count', COALESCE(array_length(p_tag_ids, 1), 0),
            'touchpoints_count', COALESCE(array_length(p_touchpoint_ids, 1), 0)
        ),
        'heatmap_data', (
            SELECT json_agg(
                json_build_object(
                    'day_of_week', day_of_week,
                    'day_name', day_name,
                    'hour_of_day', hour_of_day,
                    'interactions', interactions,
                    'unique_users', unique_users,
                    'active_touchpoints', active_touchpoints,
                    'interactions_per_user', interactions_per_user,
                    'intensity_score', intensity_score,
                    'activity_level', activity_level,
                    'time_category', time_category,
                    'breakdown', json_build_object(
                        'link_clicks', link_clicks,
                        'qr_scans', qr_scans,
                        'nfc_taps', nfc_taps,
                        'wifi_accesses', wifi_accesses
                    )
                ) ORDER BY day_of_week, hour_of_day
            )
            FROM heatmap_with_intensity
        ),
        'insights', json_build_object(
            'peak_performance', (
                SELECT json_build_object(
                    'day_name', day_name,
                    'hour', hour_of_day,
                    'interactions', interactions,
                    'time_category', time_category,
                    'unique_users', unique_users
                ) 
                FROM top_performers 
                WHERE rank = 1
            ),
            'top_5_time_slots', (
                SELECT json_agg(
                    json_build_object(
                        'rank', rank,
                        'day_name', day_name,
                        'hour', hour_of_day,
                        'interactions', interactions,
                        'unique_users', unique_users,
                        'time_category', time_category
                    ) ORDER BY rank
                )
                FROM top_performers 
                WHERE rank <= 5
            ),
            'activity_summary', (
                SELECT json_build_object(
                    'total_time_slots', total_time_slots,
                    'active_time_slots', active_time_slots,
                    'activity_rate_pct', ROUND(active_time_slots::DECIMAL / total_time_slots * 100, 1),
                    'avg_interactions_per_slot', avg_interactions_per_slot,
                    'peak_interactions', peak_interactions,
                    'business_hours_active', active_business_hours,
                    'weekend_active', active_weekend_slots,
                    'evening_active', active_evening_slots
                )
                FROM summary_stats
            ),
            'recommendations', json_build_object(
                'best_posting_times', (
                    SELECT json_agg(
                        json_build_object(
                            'day_name', day_name,
                            'hour_range', CONCAT(hour_of_day, ':00-', (hour_of_day + 1), ':00'),
                            'expected_interactions', interactions,
                            'time_category', time_category
                        ) ORDER BY rank
                    )
                    FROM top_performers 
                    WHERE rank <= 3
                ),
                'optimization_tip', (
                    SELECT CASE
                        WHEN active_business_hours = 0 THEN 'Consider targeting business hours (9 AM - 5 PM weekdays)'
                        WHEN active_weekend_slots >= active_business_hours THEN 'Strong weekend performance - focus on weekend campaigns'
                        WHEN active_evening_slots > active_business_hours THEN 'Evening hours show good engagement'
                        WHEN peak_interactions < 10 THEN 'Low overall activity - consider increasing touchpoint promotion'
                        ELSE 'Good activity distribution across time periods'
                    END
                    FROM summary_stats
                )
            )
        )
    ) INTO result;
    
    RETURN result;
    
EXCEPTION WHEN OTHERS THEN
    RETURN json_build_object(
        'error', TRUE,
        'message', SQLERRM,
        'period_days', p_period_days,
        'organization_id', p_organization_id
    );
END;
$$;


--
-- Name: get_overview_peak_heatmap_old(uuid, integer, text, uuid[], uuid[], boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_overview_peak_heatmap_old(p_organization_id uuid, p_period_days integer, p_timezone text DEFAULT 'UTC'::text, p_tag_ids uuid[] DEFAULT NULL::uuid[], p_touchpoint_ids uuid[] DEFAULT NULL::uuid[], p_is_premium boolean DEFAULT false) RETURNS json
    LANGUAGE plpgsql
    AS $$DECLARE
    start_date TIMESTAMPTZ;
    end_date TIMESTAMPTZ;
    result JSON;
BEGIN
    -- Premium feature check
    IF NOT p_is_premium THEN
        RETURN json_build_object(
            'premium_feature', TRUE,
            'message', 'Peak Performance Heatmap requires Premium plan'
        );
    END IF;

    -- Calculate date range in user's timezone
    end_date := CURRENT_TIMESTAMP AT TIME ZONE p_timezone;
    start_date := end_date - (p_period_days || ' days')::INTERVAL;
    
    WITH hourly_dow_matrix AS (
        -- Generate complete 24×7 matrix (168 time slots)
        SELECT 
            days.day_of_week,
            hours.hour_of_day
        FROM generate_series(0, 6) AS days(day_of_week)  -- 7 days
        CROSS JOIN generate_series(0, 23) AS hours(hour_of_day)  -- 24 hours
    ),
    filtered_visits AS (
        -- Apply hierarchical filtering directly to visits
        SELECT 
            v.created_at,
            v.fp,
            v.type,
            v.tp_id
        FROM visits v
        WHERE v.organization_id = p_organization_id
            AND v.created_at >= start_date
            AND v.created_at < end_date            
            AND (
                -- No filtering if no filters specified
                (p_tag_ids IS NULL AND p_touchpoint_ids IS NULL)
                OR 
                -- Apply hierarchical filtering: tags first, then touchpoints
                (
                    (p_tag_ids IS NULL OR v.tp_id IN (
                        SELECT DISTINCT ttl.tp_id 
                        FROM tp_tag_links ttl 
                        WHERE ttl.tag_id = ANY(p_tag_ids)
                    ))
                    AND
                    (p_touchpoint_ids IS NULL OR v.tp_id = ANY(p_touchpoint_ids))
                )
            )
    ),
    activity_heatmap AS (
        -- Aggregate interactions by hour and day of week
        SELECT 
            EXTRACT(dow FROM fv.created_at AT TIME ZONE p_timezone)::INTEGER as day_of_week,
            EXTRACT(hour FROM fv.created_at AT TIME ZONE p_timezone)::INTEGER as hour_of_day,
            COUNT(*) as total_interactions,
            COUNT(DISTINCT fv.fp) as unique_users,
            COUNT(CASE WHEN fv.type = 'LINK' THEN 1 END) as link_clicks,
            COUNT(CASE WHEN fv.type = 'QR' THEN 1 END) as qr_scans,
            COUNT(CASE WHEN fv.type = 'NFC' THEN 1 END) as nfc_taps,
            COUNT(CASE WHEN fv.type = 'WIFI' THEN 1 END) as wifi_accesses,
            COUNT(DISTINCT fv.tp_id) as active_touchpoints,
            -- Calculate interactions per user for this time slot
            ROUND(COUNT(*)::DECIMAL / NULLIF(COUNT(DISTINCT fv.fp), 0), 2) as interactions_per_user
        FROM filtered_visits fv
        GROUP BY 
            EXTRACT(dow FROM fv.created_at AT TIME ZONE p_timezone),
            EXTRACT(hour FROM fv.created_at AT TIME ZONE p_timezone)
    ),
    complete_heatmap AS (
        -- Fill in all 168 time slots with data
        SELECT 
            hdm.day_of_week,
            hdm.hour_of_day,
            CASE hdm.day_of_week
                WHEN 0 THEN 'Sunday'
                WHEN 1 THEN 'Monday'
                WHEN 2 THEN 'Tuesday'
                WHEN 3 THEN 'Wednesday'
                WHEN 4 THEN 'Thursday'
                WHEN 5 THEN 'Friday'
                WHEN 6 THEN 'Saturday'
            END as day_name,
            COALESCE(ah.total_interactions, 0) as interactions,
            COALESCE(ah.unique_users, 0) as unique_users,
            COALESCE(ah.link_clicks, 0) as link_clicks,
            COALESCE(ah.qr_scans, 0) as qr_scans,
            COALESCE(ah.nfc_taps, 0) as nfc_taps,
            COALESCE(ah.wifi_accesses, 0) as wifi_accesses,
            COALESCE(ah.active_touchpoints, 0) as active_touchpoints,
            COALESCE(ah.interactions_per_user, 0) as interactions_per_user,
            -- Simple business hours classification
            CASE 
                WHEN hdm.hour_of_day BETWEEN 9 AND 17 AND hdm.day_of_week BETWEEN 1 AND 5 THEN 'business_hours'
                WHEN hdm.hour_of_day BETWEEN 18 AND 22 THEN 'evening'
                WHEN hdm.day_of_week IN (0, 6) THEN 'weekend'
                WHEN hdm.hour_of_day BETWEEN 0 AND 6 THEN 'late_night'
                ELSE 'other'
            END as time_category
        FROM hourly_dow_matrix hdm
        LEFT JOIN activity_heatmap ah ON hdm.day_of_week = ah.day_of_week 
                                     AND hdm.hour_of_day = ah.hour_of_day
    ),
    heatmap_with_intensity AS (
        -- Calculate intensity levels using simple quartile-based approach
        SELECT 
            *,
            -- Calculate intensity using actual data distribution (not percentiles of sparse data)
            CASE 
                WHEN interactions = 0 THEN 'no_activity'
                WHEN interactions = 1 THEN 'minimal'
                WHEN interactions <= 5 THEN 'low'
                WHEN interactions <= 15 THEN 'moderate'
                WHEN interactions <= 30 THEN 'high'
                ELSE 'peak'
            END as activity_level,
            -- Calculate intensity score (0-100) for heatmap visualization
            CASE 
                WHEN interactions = 0 THEN 0
                ELSE LEAST(100, ROUND((interactions::DECIMAL / NULLIF((SELECT MAX(interactions) FROM complete_heatmap), 0)) * 100))
            END as intensity_score
        FROM complete_heatmap
    ),
    top_performers AS (
        -- Pre-calculate top performing time slots with ranking
        SELECT 
            day_name,
            hour_of_day,
            interactions,
            unique_users,
            time_category,
            ROW_NUMBER() OVER (ORDER BY interactions DESC, unique_users DESC) as rank
        FROM heatmap_with_intensity 
        WHERE interactions > 0
    ),
    summary_stats AS (
        -- Calculate summary statistics for insights
        SELECT 
            COUNT(*) as total_time_slots,
            COUNT(CASE WHEN interactions > 0 THEN 1 END) as active_time_slots,
            ROUND(AVG(interactions), 1) as avg_interactions_per_slot,
            MAX(interactions) as peak_interactions,
            COUNT(CASE WHEN time_category = 'business_hours' AND interactions > 0 THEN 1 END) as active_business_hours,
            COUNT(CASE WHEN time_category = 'weekend' AND interactions > 0 THEN 1 END) as active_weekend_slots,
            COUNT(CASE WHEN time_category = 'evening' AND interactions > 0 THEN 1 END) as active_evening_slots
        FROM heatmap_with_intensity
    )
    SELECT json_build_object(
        'period_info', json_build_object(
            'period_days', p_period_days,
            'start_date', start_date,
            'end_date', end_date,
            'timezone', p_timezone,
            'is_premium', p_is_premium
        ),
        'filters_applied', json_build_object(
            'has_filters', (p_tag_ids IS NOT NULL OR p_touchpoint_ids IS NOT NULL),
            'tags_count', COALESCE(array_length(p_tag_ids, 1), 0),
            'touchpoints_count', COALESCE(array_length(p_touchpoint_ids, 1), 0)
        ),
        'heatmap_data', (
            SELECT json_agg(
                json_build_object(
                    'day_of_week', day_of_week,
                    'day_name', day_name,
                    'hour_of_day', hour_of_day,
                    'interactions', interactions,
                    'unique_users', unique_users,
                    'active_touchpoints', active_touchpoints,
                    'interactions_per_user', interactions_per_user,
                    'intensity_score', intensity_score,
                    'activity_level', activity_level,
                    'time_category', time_category,
                    'breakdown', json_build_object(
                        'link_clicks', link_clicks,
                        'qr_scans', qr_scans,
                        'nfc_taps', nfc_taps,
                        'wifi_accesses', wifi_accesses
                    )
                ) ORDER BY day_of_week, hour_of_day
            )
            FROM heatmap_with_intensity
        ),
        'insights', json_build_object(
            'peak_performance', (
                SELECT json_build_object(
                    'day_name', day_name,
                    'hour', hour_of_day,
                    'interactions', interactions,
                    'time_category', time_category,
                    'unique_users', unique_users
                ) 
                FROM top_performers 
                WHERE rank = 1
            ),
            'top_5_time_slots', (
                SELECT json_agg(
                    json_build_object(
                        'rank', rank,
                        'day_name', day_name,
                        'hour', hour_of_day,
                        'interactions', interactions,
                        'unique_users', unique_users,
                        'time_category', time_category
                    ) ORDER BY rank
                )
                FROM top_performers 
                WHERE rank <= 5
            ),
            'activity_summary', (
                SELECT json_build_object(
                    'total_time_slots', total_time_slots,
                    'active_time_slots', active_time_slots,
                    'activity_rate_pct', ROUND(active_time_slots::DECIMAL / total_time_slots * 100, 1),
                    'avg_interactions_per_slot', avg_interactions_per_slot,
                    'peak_interactions', peak_interactions,
                    'business_hours_active', active_business_hours,
                    'weekend_active', active_weekend_slots,
                    'evening_active', active_evening_slots
                )
                FROM summary_stats
            ),
            'recommendations', json_build_object(
                'best_posting_times', (
                    SELECT json_agg(
                        json_build_object(
                            'day_name', day_name,
                            'hour_range', CONCAT(hour_of_day, ':00-', (hour_of_day + 1), ':00'),
                            'expected_interactions', interactions,
                            'time_category', time_category
                        ) ORDER BY rank
                    )
                    FROM top_performers 
                    WHERE rank <= 3
                ),
                'optimization_tip', (
                    SELECT CASE
                        WHEN active_business_hours = 0 THEN 'Consider targeting business hours (9 AM - 5 PM weekdays)'
                        WHEN active_weekend_slots >= active_business_hours THEN 'Strong weekend performance - focus on weekend campaigns'
                        WHEN active_evening_slots > active_business_hours THEN 'Evening hours show good engagement'
                        WHEN peak_interactions < 10 THEN 'Low overall activity - consider increasing touchpoint promotion'
                        ELSE 'Good activity distribution across time periods'
                    END
                    FROM summary_stats
                )
            )
        )
    ) INTO result;
    
    RETURN result;
    
EXCEPTION WHEN OTHERS THEN
    RETURN json_build_object(
        'error', TRUE,
        'message', SQLERRM,
        'period_days', p_period_days,
        'organization_id', p_organization_id
    );
END;$$;


--
-- Name: get_overview_stats_panel(uuid, integer, text, uuid[], uuid[], boolean, uuid[], boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_overview_stats_panel(p_organization_id uuid, p_period_days integer, p_timezone text DEFAULT 'UTC'::text, p_tag_ids uuid[] DEFAULT NULL::uuid[], p_touchpoint_ids uuid[] DEFAULT NULL::uuid[], p_is_premium boolean DEFAULT false, p_collection_ids uuid[] DEFAULT NULL::uuid[], p_include_null_collection boolean DEFAULT false) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    current_start_date TIMESTAMPTZ;
    current_end_date TIMESTAMPTZ;
    previous_start_date TIMESTAMPTZ;
    previous_end_date TIMESTAMPTZ;
    result JSON;
BEGIN
    -- Validate tier restrictions
    IF NOT p_is_premium AND p_period_days != 7 THEN
        RETURN json_build_object(
            'error', TRUE,
            'message', 'Free tier limited to 7 days only'
        );
    END IF;
    
    IF NOT p_is_premium AND p_touchpoint_ids IS NOT NULL AND array_length(p_touchpoint_ids, 1) > 1 THEN
        RETURN json_build_object(
            'error', TRUE,
            'message', 'Free tier limited to 1 touchpoint only'
        );
    END IF;

    -- Calculate date ranges in user's timezone
    current_end_date := CURRENT_TIMESTAMP AT TIME ZONE p_timezone;
    current_start_date := current_end_date - (p_period_days || ' days')::INTERVAL;
    previous_end_date := current_start_date;
    previous_start_date := previous_end_date - (p_period_days || ' days')::INTERVAL;
    
    -- Apply hierarchical filtering logic
    WITH base_touchpoints AS (
        -- If tags are provided, filter touchpoints by tags first
        SELECT DISTINCT tp.id as tp_id
        FROM touch_points tp
        WHERE tp.organization_id = p_organization_id            
            AND (
                p_tag_ids IS NULL 
                OR tp.id IN (
                    SELECT DISTINCT ttl.tp_id 
                    FROM tp_tag_links ttl 
                    WHERE ttl.tag_id = ANY(p_tag_ids)
                )
            )
            AND (
                p_collection_ids IS NULL
                OR tp.collection_id = ANY(p_collection_ids)
                OR (p_include_null_collection AND tp.collection_id IS NULL)
            )
    ),
    filtered_touchpoints AS (
        -- Step 2: Apply specific touchpoint filter if provided
        SELECT tp_id
        FROM base_touchpoints
        WHERE (
            p_touchpoint_ids IS NULL 
            OR tp_id = ANY(p_touchpoint_ids)
        )
    ),
    current_period AS (
        SELECT 
            COUNT(*) as total_visits,
            COUNT(DISTINCT fp) as unique_visits,
            COUNT(CASE WHEN type = 'LINK' THEN 1 END) as link_clicks,
            COUNT(CASE WHEN type = 'QR' THEN 1 END) as qr_scans,
            COUNT(CASE WHEN type = 'NFC' THEN 1 END) as nfc_taps,
            COUNT(CASE WHEN type = 'WIFI' THEN 1 END) as wifi_accesses,
            COUNT(DISTINCT tp_id) as touchpoints_active
        FROM visits v
        WHERE v.organization_id = p_organization_id
            AND v.created_at >= current_start_date
            AND v.created_at < current_end_date            
            AND (
                -- No filtering if no touchpoints specified
                (p_tag_ids IS NULL AND p_touchpoint_ids IS NULL)
                OR 
                -- Apply hierarchical filtering
                v.tp_id IN (SELECT tp_id FROM filtered_touchpoints)
            )
    ),
    previous_period AS (
        SELECT 
            COUNT(*) as total_visits,
            COUNT(DISTINCT fp) as unique_visits,
            COUNT(CASE WHEN type = 'LINK' THEN 1 END) as link_clicks,
            COUNT(CASE WHEN type = 'QR' THEN 1 END) as qr_scans,
            COUNT(CASE WHEN type = 'NFC' THEN 1 END) as nfc_taps,
            COUNT(CASE WHEN type = 'WIFI' THEN 1 END) as wifi_accesses
        FROM visits v
        WHERE v.organization_id = p_organization_id
            AND v.created_at >= previous_start_date
            AND v.created_at < previous_end_date            
            AND (
                -- Apply same filtering logic for comparison
                (p_tag_ids IS NULL AND p_touchpoint_ids IS NULL)
                OR 
                v.tp_id IN (SELECT tp_id FROM filtered_touchpoints)
            )
    ),
    percentage_calculations AS (
        SELECT 
            -- Current period metrics
            c.total_visits,
            c.unique_visits,
            c.link_clicks,
            c.qr_scans,
            c.nfc_taps,
            c.wifi_accesses,
            c.touchpoints_active,
            
            -- Percentage changes with proper handling of division by zero
            CASE 
                WHEN p.total_visits = 0 THEN 
                    CASE WHEN c.total_visits > 0 THEN 100.0 ELSE 0.0 END
                ELSE 
                    ROUND(((c.total_visits - p.total_visits)::DECIMAL / p.total_visits) * 100, 1)
            END as total_visits_change_pct,
            
            CASE 
                WHEN p.unique_visits = 0 THEN 
                    CASE WHEN c.unique_visits > 0 THEN 100.0 ELSE 0.0 END
                ELSE 
                    ROUND(((c.unique_visits - p.unique_visits)::DECIMAL / p.unique_visits) * 100, 1)
            END as unique_visits_change_pct,
            
            CASE 
                WHEN p.link_clicks = 0 THEN 
                    CASE WHEN c.link_clicks > 0 THEN 100.0 ELSE 0.0 END
                ELSE 
                    ROUND(((c.link_clicks - p.link_clicks)::DECIMAL / p.link_clicks) * 100, 1)
            END as link_clicks_change_pct,
            
            CASE 
                WHEN p.qr_scans = 0 THEN 
                    CASE WHEN c.qr_scans > 0 THEN 100.0 ELSE 0.0 END
                ELSE 
                    ROUND(((c.qr_scans - p.qr_scans)::DECIMAL / p.qr_scans) * 100, 1)
            END as qr_scans_change_pct,
            
            CASE 
                WHEN p.nfc_taps = 0 THEN 
                    CASE WHEN c.nfc_taps > 0 THEN 100.0 ELSE 0.0 END
                ELSE 
                    ROUND(((c.nfc_taps - p.nfc_taps)::DECIMAL / p.nfc_taps) * 100, 1)
            END as nfc_taps_change_pct,
            
            CASE 
                WHEN p.wifi_accesses = 0 THEN 
                    CASE WHEN c.wifi_accesses > 0 THEN 100.0 ELSE 0.0 END
                ELSE 
                    ROUND(((c.wifi_accesses - p.wifi_accesses)::DECIMAL / p.wifi_accesses) * 100, 1)
            END as wifi_accesses_change_pct
            
        FROM current_period c
        CROSS JOIN previous_period p
    )
    SELECT json_build_object(
        -- 'period_info', json_build_object(
        --     'period_days', p_period_days,
        --     'current_start', current_start_date,
        --     'current_end', current_end_date,
        --     'timezone', p_timezone,
        --     'is_premium', p_is_premium
        -- ),
        -- 'filters_applied', json_build_object(
        --     'has_filters', (p_tag_ids IS NOT NULL OR p_touchpoint_ids IS NOT NULL),
        --     'tags_count', COALESCE(array_length(p_tag_ids, 1), 0),
        --     'touchpoints_count', COALESCE(array_length(p_touchpoint_ids, 1), 0),
        --     'filtered_touchpoints_available', (SELECT COUNT(*) FROM filtered_touchpoints)
        -- ),
        'stats', json_build_object(
            'total_visits', json_build_object(
                'value', total_visits,
                'change_pct', total_visits_change_pct,
                'trend', CASE 
                    WHEN total_visits_change_pct > 0 THEN 'up'
                    WHEN total_visits_change_pct < 0 THEN 'down' 
                    ELSE 'stable' 
                END
            ),
            'unique_visits', json_build_object(
                'value', unique_visits,
                'change_pct', unique_visits_change_pct,
                'trend', CASE 
                    WHEN unique_visits_change_pct > 0 THEN 'up'
                    WHEN unique_visits_change_pct < 0 THEN 'down' 
                    ELSE 'stable' 
                END
            ),
            'link_clicks', json_build_object(
                'value', link_clicks,
                'change_pct', link_clicks_change_pct,
                'trend', CASE 
                    WHEN link_clicks_change_pct > 0 THEN 'up'
                    WHEN link_clicks_change_pct < 0 THEN 'down' 
                    ELSE 'stable' 
                END
            ),
            'qr_scans', json_build_object(
                'value', qr_scans,
                'change_pct', qr_scans_change_pct,
                'trend', CASE 
                    WHEN qr_scans_change_pct > 0 THEN 'up'
                    WHEN qr_scans_change_pct < 0 THEN 'down' 
                    ELSE 'stable' 
                END
            ),
            'nfc_taps', json_build_object(
                'value', nfc_taps,
                'change_pct', nfc_taps_change_pct,
                'trend', CASE 
                    WHEN nfc_taps_change_pct > 0 THEN 'up'
                    WHEN nfc_taps_change_pct < 0 THEN 'down' 
                    ELSE 'stable' 
                END
            ),
            'wifi_accesses', json_build_object(
                'value', wifi_accesses,
                'change_pct', wifi_accesses_change_pct,
                'trend', CASE 
                    WHEN wifi_accesses_change_pct > 0 THEN 'up'
                    WHEN wifi_accesses_change_pct < 0 THEN 'down' 
                    ELSE 'stable' 
                END
            ),
            'touchpoints_active', touchpoints_active
        )
    ) INTO result
    FROM percentage_calculations;
    
    RETURN result;
    
EXCEPTION WHEN OTHERS THEN
    RETURN json_build_object(
        'error', TRUE,
        'message', SQLERRM,
        'period_days', p_period_days,
        'organization_id', p_organization_id
    );
END;
$$;


--
-- Name: get_overview_stats_panel_old(uuid, integer, text, uuid[], uuid[], boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_overview_stats_panel_old(p_organization_id uuid, p_period_days integer, p_timezone text DEFAULT 'UTC'::text, p_tag_ids uuid[] DEFAULT NULL::uuid[], p_touchpoint_ids uuid[] DEFAULT NULL::uuid[], p_is_premium boolean DEFAULT false) RETURNS json
    LANGUAGE plpgsql
    AS $$DECLARE
    current_start_date TIMESTAMPTZ;
    current_end_date TIMESTAMPTZ;
    previous_start_date TIMESTAMPTZ;
    previous_end_date TIMESTAMPTZ;
    result JSON;
BEGIN
    -- Validate tier restrictions
    IF NOT p_is_premium AND p_period_days != 7 THEN
        RETURN json_build_object(
            'error', TRUE,
            'message', 'Free tier limited to 7 days only'
        );
    END IF;
    
    IF NOT p_is_premium AND p_touchpoint_ids IS NOT NULL AND array_length(p_touchpoint_ids, 1) > 1 THEN
        RETURN json_build_object(
            'error', TRUE,
            'message', 'Free tier limited to 1 touchpoint only'
        );
    END IF;

    -- Calculate date ranges in user's timezone
    current_end_date := CURRENT_TIMESTAMP AT TIME ZONE p_timezone;
    current_start_date := current_end_date - (p_period_days || ' days')::INTERVAL;
    previous_end_date := current_start_date;
    previous_start_date := previous_end_date - (p_period_days || ' days')::INTERVAL;
    
    -- Apply hierarchical filtering logic
    WITH base_touchpoints AS (
        -- If tags are provided, filter touchpoints by tags first
        SELECT DISTINCT tp.id as tp_id
        FROM touch_points tp
        WHERE tp.organization_id = p_organization_id            
            AND (
                p_tag_ids IS NULL 
                OR tp.id IN (
                    SELECT DISTINCT ttl.tp_id 
                    FROM tp_tag_links ttl 
                    WHERE ttl.tag_id = ANY(p_tag_ids)
                )
            )
    ),
    filtered_touchpoints AS (
        -- Step 2: Apply specific touchpoint filter if provided
        SELECT tp_id
        FROM base_touchpoints
        WHERE (
            p_touchpoint_ids IS NULL 
            OR tp_id = ANY(p_touchpoint_ids)
        )
    ),
    current_period AS (
        SELECT 
            COUNT(*) as total_visits,
            COUNT(DISTINCT fp) as unique_visits,
            COUNT(CASE WHEN type = 'LINK' THEN 1 END) as link_clicks,
            COUNT(CASE WHEN type = 'QR' THEN 1 END) as qr_scans,
            COUNT(CASE WHEN type = 'NFC' THEN 1 END) as nfc_taps,
            COUNT(CASE WHEN type = 'WIFI' THEN 1 END) as wifi_accesses,
            COUNT(DISTINCT tp_id) as touchpoints_active
        FROM visits v
        WHERE v.organization_id = p_organization_id
            AND v.created_at >= current_start_date
            AND v.created_at < current_end_date            
            AND (
                -- No filtering if no touchpoints specified
                (p_tag_ids IS NULL AND p_touchpoint_ids IS NULL)
                OR 
                -- Apply hierarchical filtering
                v.tp_id IN (SELECT tp_id FROM filtered_touchpoints)
            )
    ),
    previous_period AS (
        SELECT 
            COUNT(*) as total_visits,
            COUNT(DISTINCT fp) as unique_visits,
            COUNT(CASE WHEN type = 'LINK' THEN 1 END) as link_clicks,
            COUNT(CASE WHEN type = 'QR' THEN 1 END) as qr_scans,
            COUNT(CASE WHEN type = 'NFC' THEN 1 END) as nfc_taps,
            COUNT(CASE WHEN type = 'WIFI' THEN 1 END) as wifi_accesses
        FROM visits v
        WHERE v.organization_id = p_organization_id
            AND v.created_at >= previous_start_date
            AND v.created_at < previous_end_date            
            AND (
                -- Apply same filtering logic for comparison
                (p_tag_ids IS NULL AND p_touchpoint_ids IS NULL)
                OR 
                v.tp_id IN (SELECT tp_id FROM filtered_touchpoints)
            )
    ),
    percentage_calculations AS (
        SELECT 
            -- Current period metrics
            c.total_visits,
            c.unique_visits,
            c.link_clicks,
            c.qr_scans,
            c.nfc_taps,
            c.wifi_accesses,
            c.touchpoints_active,
            
            -- Percentage changes with proper handling of division by zero
            CASE 
                WHEN p.total_visits = 0 THEN 
                    CASE WHEN c.total_visits > 0 THEN 100.0 ELSE 0.0 END
                ELSE 
                    ROUND(((c.total_visits - p.total_visits)::DECIMAL / p.total_visits) * 100, 1)
            END as total_visits_change_pct,
            
            CASE 
                WHEN p.unique_visits = 0 THEN 
                    CASE WHEN c.unique_visits > 0 THEN 100.0 ELSE 0.0 END
                ELSE 
                    ROUND(((c.unique_visits - p.unique_visits)::DECIMAL / p.unique_visits) * 100, 1)
            END as unique_visits_change_pct,
            
            CASE 
                WHEN p.link_clicks = 0 THEN 
                    CASE WHEN c.link_clicks > 0 THEN 100.0 ELSE 0.0 END
                ELSE 
                    ROUND(((c.link_clicks - p.link_clicks)::DECIMAL / p.link_clicks) * 100, 1)
            END as link_clicks_change_pct,
            
            CASE 
                WHEN p.qr_scans = 0 THEN 
                    CASE WHEN c.qr_scans > 0 THEN 100.0 ELSE 0.0 END
                ELSE 
                    ROUND(((c.qr_scans - p.qr_scans)::DECIMAL / p.qr_scans) * 100, 1)
            END as qr_scans_change_pct,
            
            CASE 
                WHEN p.nfc_taps = 0 THEN 
                    CASE WHEN c.nfc_taps > 0 THEN 100.0 ELSE 0.0 END
                ELSE 
                    ROUND(((c.nfc_taps - p.nfc_taps)::DECIMAL / p.nfc_taps) * 100, 1)
            END as nfc_taps_change_pct,
            
            CASE 
                WHEN p.wifi_accesses = 0 THEN 
                    CASE WHEN c.wifi_accesses > 0 THEN 100.0 ELSE 0.0 END
                ELSE 
                    ROUND(((c.wifi_accesses - p.wifi_accesses)::DECIMAL / p.wifi_accesses) * 100, 1)
            END as wifi_accesses_change_pct
            
        FROM current_period c
        CROSS JOIN previous_period p
    )
    SELECT json_build_object(
        -- 'period_info', json_build_object(
        --     'period_days', p_period_days,
        --     'current_start', current_start_date,
        --     'current_end', current_end_date,
        --     'timezone', p_timezone,
        --     'is_premium', p_is_premium
        -- ),
        -- 'filters_applied', json_build_object(
        --     'has_filters', (p_tag_ids IS NOT NULL OR p_touchpoint_ids IS NOT NULL),
        --     'tags_count', COALESCE(array_length(p_tag_ids, 1), 0),
        --     'touchpoints_count', COALESCE(array_length(p_touchpoint_ids, 1), 0),
        --     'filtered_touchpoints_available', (SELECT COUNT(*) FROM filtered_touchpoints)
        -- ),
        'stats', json_build_object(
            'total_visits', json_build_object(
                'value', total_visits,
                'change_pct', total_visits_change_pct,
                'trend', CASE 
                    WHEN total_visits_change_pct > 0 THEN 'up'
                    WHEN total_visits_change_pct < 0 THEN 'down' 
                    ELSE 'stable' 
                END
            ),
            'unique_visits', json_build_object(
                'value', unique_visits,
                'change_pct', unique_visits_change_pct,
                'trend', CASE 
                    WHEN unique_visits_change_pct > 0 THEN 'up'
                    WHEN unique_visits_change_pct < 0 THEN 'down' 
                    ELSE 'stable' 
                END
            ),
            'link_clicks', json_build_object(
                'value', link_clicks,
                'change_pct', link_clicks_change_pct,
                'trend', CASE 
                    WHEN link_clicks_change_pct > 0 THEN 'up'
                    WHEN link_clicks_change_pct < 0 THEN 'down' 
                    ELSE 'stable' 
                END
            ),
            'qr_scans', json_build_object(
                'value', qr_scans,
                'change_pct', qr_scans_change_pct,
                'trend', CASE 
                    WHEN qr_scans_change_pct > 0 THEN 'up'
                    WHEN qr_scans_change_pct < 0 THEN 'down' 
                    ELSE 'stable' 
                END
            ),
            'nfc_taps', json_build_object(
                'value', nfc_taps,
                'change_pct', nfc_taps_change_pct,
                'trend', CASE 
                    WHEN nfc_taps_change_pct > 0 THEN 'up'
                    WHEN nfc_taps_change_pct < 0 THEN 'down' 
                    ELSE 'stable' 
                END
            ),
            'wifi_accesses', json_build_object(
                'value', wifi_accesses,
                'change_pct', wifi_accesses_change_pct,
                'trend', CASE 
                    WHEN wifi_accesses_change_pct > 0 THEN 'up'
                    WHEN wifi_accesses_change_pct < 0 THEN 'down' 
                    ELSE 'stable' 
                END
            ),
            'touchpoints_active', touchpoints_active
        )
    ) INTO result
    FROM percentage_calculations;
    
    RETURN result;
    
EXCEPTION WHEN OTHERS THEN
    RETURN json_build_object(
        'error', TRUE,
        'message', SQLERRM,
        'period_days', p_period_days,
        'organization_id', p_organization_id
    );
END;$$;


--
-- Name: get_overview_top_touchpoints(uuid, integer, text, uuid[], uuid[], boolean, uuid[], boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_overview_top_touchpoints(p_organization_id uuid, p_period_days integer, p_timezone text DEFAULT 'UTC'::text, p_tag_ids uuid[] DEFAULT NULL::uuid[], p_touchpoint_ids uuid[] DEFAULT NULL::uuid[], p_is_premium boolean DEFAULT false, p_collection_ids uuid[] DEFAULT NULL::uuid[], p_include_null_collection boolean DEFAULT false) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    start_date TIMESTAMPTZ;
    end_date TIMESTAMPTZ;
    result JSON;
BEGIN
    -- Validate tier restrictions
    IF NOT p_is_premium AND p_period_days != 7 THEN
        RETURN json_build_object('error', TRUE, 'message', 'Free tier limited to 7 days only');
    END IF;
    
    IF NOT p_is_premium AND p_touchpoint_ids IS NOT NULL AND array_length(p_touchpoint_ids, 1) > 1 THEN
        RETURN json_build_object('error', TRUE, 'message', 'Free tier limited to 1 touchpoint only');
    END IF;

    -- Calculate date range in user's timezone
    end_date := CURRENT_TIMESTAMP AT TIME ZONE p_timezone;
    start_date := end_date - (p_period_days || ' days')::INTERVAL;
    
    WITH filtered_touchpoints AS (
        -- Apply hierarchical filtering logic
        SELECT DISTINCT tp.id as tp_id, tp.name, tp.slug
        FROM touch_points tp
        WHERE tp.organization_id = p_organization_id
            AND tp.deleted_at IS NULL
            AND (
                p_tag_ids IS NULL
                OR tp.id IN (
                    SELECT DISTINCT ttl.tp_id
                    FROM tp_tag_links ttl
                    WHERE ttl.tag_id = ANY(p_tag_ids)
                )
            )
            AND (
                p_touchpoint_ids IS NULL
                OR tp.id = ANY(p_touchpoint_ids)
            )
            AND (
                p_collection_ids IS NULL
                OR tp.collection_id = ANY(p_collection_ids)
                OR (p_include_null_collection AND tp.collection_id IS NULL)
            )
    ),
    touchpoint_performance AS (
        SELECT 
            ft.tp_id,
            ft.name as touchpoint_name,            
            ft.slug as touchpoint_slug,
            COUNT(*) as total_interactions,
            COUNT(DISTINCT v.fp) as unique_users,
            COUNT(CASE WHEN v.type = 'LINK' THEN 1 END) as link_clicks,
            COUNT(CASE WHEN v.type = 'QR' THEN 1 END) as qr_scans,
            COUNT(CASE WHEN v.type = 'NFC' THEN 1 END) as nfc_taps,
            COUNT(CASE WHEN v.type = 'WIFI' THEN 1 END) as wifi_accesses,
            -- Advanced engagement metrics
            ROUND(COUNT(*)::DECIMAL / NULLIF(COUNT(DISTINCT v.fp), 0), 2) as interactions_per_user,
            COUNT(DISTINCT DATE(v.created_at AT TIME ZONE p_timezone)) as active_days,
            -- Geographic and device insights
            COUNT(DISTINCT v.country) as countries_reached,
            COUNT(DISTINCT v.city) as cities_reached,
            COUNT(CASE WHEN v.platform = 'Mobile' THEN 1 END) as mobile_interactions,
            COUNT(CASE WHEN v.platform = 'Desktop' THEN 1 END) as desktop_interactions,
            -- Traffic source analysis
            COUNT(CASE WHEN v.referrer = 'direct' THEN 1 END) as direct_visits,
            COUNT(CASE WHEN v.referrer != 'direct' AND v.referrer IS NOT NULL THEN 1 END) as referred_visits,
            -- Time-based patterns
            COUNT(CASE WHEN EXTRACT(dow FROM v.created_at AT TIME ZONE p_timezone) BETWEEN 1 AND 5 THEN 1 END) as weekday_interactions,
            COUNT(CASE WHEN EXTRACT(dow FROM v.created_at AT TIME ZONE p_timezone) IN (0, 6) THEN 1 END) as weekend_interactions,
            -- Peak performance hour
            MODE() WITHIN GROUP (ORDER BY EXTRACT(hour FROM v.created_at AT TIME ZONE p_timezone)) as peak_hour,
            -- Tags associated with this touchpoint
            (
                SELECT json_agg(
                    json_build_object('id', t.id, 'name', t.name)
                )
                FROM tp_tag_links ttl
                JOIN tags t ON ttl.tag_id = t.id
                WHERE ttl.tp_id = ft.tp_id
            ) as associated_tags
        FROM filtered_touchpoints ft
        LEFT JOIN visits v ON ft.tp_id = v.tp_id
            AND v.organization_id = p_organization_id
            AND v.created_at >= start_date
            AND v.created_at < end_date            
        GROUP BY ft.tp_id, ft.name, ft.slug
    ),
    ranked_touchpoints AS (
        SELECT 
            *,
            -- Multiple ranking criteria
            ROW_NUMBER() OVER (ORDER BY total_interactions DESC) as rank_by_volume,
            ROW_NUMBER() OVER (ORDER BY unique_users DESC) as rank_by_reach,
            ROW_NUMBER() OVER (ORDER BY interactions_per_user DESC) as rank_by_engagement,
            ROW_NUMBER() OVER (ORDER BY active_days DESC) as rank_by_consistency,
            ROW_NUMBER() OVER (ORDER BY countries_reached DESC) as rank_by_geographic_reach,
            -- Composite performance score (weighted)
            (
                COALESCE(total_interactions::DECIMAL / NULLIF(MAX(total_interactions) OVER(), 0), 0) * 0.3 +
                COALESCE(unique_users::DECIMAL / NULLIF(MAX(unique_users) OVER(), 0), 0) * 0.25 +
                COALESCE(interactions_per_user::DECIMAL / NULLIF(MAX(interactions_per_user) OVER(), 0), 0) * 0.2 +
                COALESCE(active_days::DECIMAL / NULLIF(MAX(active_days) OVER(), 0), 0) * 0.15 +
                COALESCE(countries_reached::DECIMAL / NULLIF(MAX(countries_reached) OVER(), 0), 0) * 0.1
            ) * 100 as performance_score,
            -- Market share calculations
            ROUND(total_interactions::DECIMAL / NULLIF(SUM(total_interactions) OVER(), 0) * 100, 1) as volume_share_pct,
            ROUND(unique_users::DECIMAL / NULLIF(SUM(unique_users) OVER(), 0) * 100, 1) as user_share_pct,
            -- Usage pattern insights
            ROUND(mobile_interactions::DECIMAL / NULLIF(total_interactions, 0) * 100, 1) as mobile_usage_pct,
            ROUND(weekend_interactions::DECIMAL / NULLIF(total_interactions, 0) * 100, 1) as weekend_usage_pct,
            ROUND(direct_visits::DECIMAL / NULLIF(total_interactions, 0) * 100, 1) as direct_traffic_pct
        FROM touchpoint_performance
        WHERE total_interactions > 0  -- Only include touchpoints with activity
    ),
    top_performers AS (
        SELECT 
            *,
            ROW_NUMBER() OVER (ORDER BY performance_score DESC) as overall_rank,
            -- Performance tier classification
            CASE 
                WHEN performance_score >= 80 THEN 'top_performer'
                WHEN performance_score >= 60 THEN 'good_performer'
                WHEN performance_score >= 40 THEN 'average_performer'
                WHEN performance_score >= 20 THEN 'underperformer'
                ELSE 'poor_performer'
            END as performance_tier,
            -- Engagement quality assessment
            CASE 
                WHEN interactions_per_user >= 3.0 THEN 'high_engagement'
                WHEN interactions_per_user >= 2.0 THEN 'medium_engagement'
                WHEN interactions_per_user >= 1.5 THEN 'low_engagement'
                ELSE 'very_low_engagement'
            END as engagement_quality
        FROM ranked_touchpoints
    ),
    summary_stats AS (
        SELECT 
            COUNT(*) as total_touchpoints_analyzed,
            SUM(total_interactions) as total_interactions_all,
            COUNT(DISTINCT tp_id) as active_touchpoints_count,
            ROUND(AVG(performance_score), 1) as avg_performance_score,
            ROUND(AVG(interactions_per_user), 2) as avg_engagement_rate
        FROM top_performers
    )
    SELECT json_build_object(
        'period_info', json_build_object(
            'period_days', p_period_days,
            'start_date', start_date,
            'end_date', end_date,
            'timezone', p_timezone,
            'is_premium', p_is_premium
        ),
        'filters_applied', json_build_object(
            'has_filters', (p_tag_ids IS NOT NULL OR p_touchpoint_ids IS NOT NULL),
            'tags_count', COALESCE(array_length(p_tag_ids, 1), 0),
            'touchpoints_count', COALESCE(array_length(p_touchpoint_ids, 1), 0),
            'total_touchpoints_in_filter', (SELECT COUNT(*) FROM filtered_touchpoints),
            'active_touchpoints_in_period', (SELECT active_touchpoints_count FROM summary_stats)
        ),
        'top_touchpoints', COALESCE(
            (
                SELECT json_agg(
                    json_build_object(
                        'rank', overall_rank,
                        'touchpoint_id', tp_id,
                        'name', touchpoint_name,                        
                        'slug', touchpoint_slug,
                        'performance_score', ROUND(performance_score::NUMERIC, 1),
                        'performance_tier', performance_tier,
                        'engagement_quality', engagement_quality,
                        'associated_tags', associated_tags,
                        'core_metrics', json_build_object(
                            'total_interactions', total_interactions,
                            'unique_users', unique_users,
                            'interactions_per_user', interactions_per_user,
                            'active_days', active_days,
                            'volume_share_pct', volume_share_pct,
                            'user_share_pct', user_share_pct
                        ),
                        'interaction_breakdown', json_build_object(
                            'link_clicks', link_clicks,
                            'qr_scans', qr_scans,
                            'nfc_taps', nfc_taps,
                            'wifi_accesses', wifi_accesses
                        ),
                        'audience_insights', json_build_object(
                            'countries_reached', countries_reached,
                            'cities_reached', cities_reached,
                            'mobile_usage_pct', mobile_usage_pct,
                            'weekend_usage_pct', weekend_usage_pct,
                            'direct_traffic_pct', direct_traffic_pct,
                            'peak_hour', peak_hour
                        ),
                        'rankings', json_build_object(
                            'by_volume', rank_by_volume,
                            'by_reach', rank_by_reach,
                            'by_engagement', rank_by_engagement,
                            'by_consistency', rank_by_consistency,
                            'by_geographic_reach', rank_by_geographic_reach
                        )
                    ) ORDER BY overall_rank
                )
                FROM top_performers 
                WHERE overall_rank <= 5
            ),
            '[]'::json
        ),
        'summary', json_build_object(
            'total_touchpoints_analyzed', (SELECT total_touchpoints_analyzed FROM summary_stats),
            'active_touchpoints_count', (SELECT active_touchpoints_count FROM summary_stats),
            'total_interactions_all', (SELECT total_interactions_all FROM summary_stats),
            'avg_performance_score', (SELECT avg_performance_score FROM summary_stats),
            'avg_engagement_rate', (SELECT avg_engagement_rate FROM summary_stats),
            'top_performer', COALESCE(
                (
                    SELECT json_build_object(
                        'name', touchpoint_name,
                        'performance_score', ROUND(performance_score::NUMERIC, 1),
                        'total_interactions', total_interactions,
                        'performance_tier', performance_tier
                    )
                    FROM top_performers 
                    WHERE overall_rank = 1
                ),
                json_build_object('message', 'No active touchpoints in selected period')
            ),
            'performance_distribution', json_build_object(
                'top_performers', (SELECT COUNT(*) FROM top_performers WHERE performance_tier = 'top_performer'),
                'good_performers', (SELECT COUNT(*) FROM top_performers WHERE performance_tier = 'good_performer'),
                'average_performers', (SELECT COUNT(*) FROM top_performers WHERE performance_tier = 'average_performer'),  
                'underperformers', (SELECT COUNT(*) FROM top_performers WHERE performance_tier = 'underperformer'),
                'poor_performers', (SELECT COUNT(*) FROM top_performers WHERE performance_tier = 'poor_performer')
            )
        )
    ) INTO result
    FROM summary_stats;
    
    RETURN result;
    
EXCEPTION WHEN OTHERS THEN
    RETURN json_build_object(
        'error', TRUE,
        'message', SQLERRM,
        'period_days', p_period_days,
        'organization_id', p_organization_id
    );
END;
$$;


--
-- Name: get_overview_top_touchpoints_old(uuid, integer, text, uuid[], uuid[], boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_overview_top_touchpoints_old(p_organization_id uuid, p_period_days integer, p_timezone text DEFAULT 'UTC'::text, p_tag_ids uuid[] DEFAULT NULL::uuid[], p_touchpoint_ids uuid[] DEFAULT NULL::uuid[], p_is_premium boolean DEFAULT false) RETURNS json
    LANGUAGE plpgsql
    AS $$DECLARE
    start_date TIMESTAMPTZ;
    end_date TIMESTAMPTZ;
    result JSON;
BEGIN
    -- Validate tier restrictions
    IF NOT p_is_premium AND p_period_days != 7 THEN
        RETURN json_build_object('error', TRUE, 'message', 'Free tier limited to 7 days only');
    END IF;
    
    IF NOT p_is_premium AND p_touchpoint_ids IS NOT NULL AND array_length(p_touchpoint_ids, 1) > 1 THEN
        RETURN json_build_object('error', TRUE, 'message', 'Free tier limited to 1 touchpoint only');
    END IF;

    -- Calculate date range in user's timezone
    end_date := CURRENT_TIMESTAMP AT TIME ZONE p_timezone;
    start_date := end_date - (p_period_days || ' days')::INTERVAL;
    
    WITH filtered_touchpoints AS (
        -- Apply hierarchical filtering logic
        SELECT DISTINCT tp.id as tp_id, tp.name, tp.slug
        FROM touch_points tp
        WHERE tp.organization_id = p_organization_id
            AND tp.deleted_at IS NULL
            AND (
                p_tag_ids IS NULL 
                OR tp.id IN (
                    SELECT DISTINCT ttl.tp_id 
                    FROM tp_tag_links ttl 
                    WHERE ttl.tag_id = ANY(p_tag_ids)
                )
            )
            AND (
                p_touchpoint_ids IS NULL 
                OR tp.id = ANY(p_touchpoint_ids)
            )
    ),
    touchpoint_performance AS (
        SELECT 
            ft.tp_id,
            ft.name as touchpoint_name,            
            ft.slug as touchpoint_slug,
            COUNT(*) as total_interactions,
            COUNT(DISTINCT v.fp) as unique_users,
            COUNT(CASE WHEN v.type = 'LINK' THEN 1 END) as link_clicks,
            COUNT(CASE WHEN v.type = 'QR' THEN 1 END) as qr_scans,
            COUNT(CASE WHEN v.type = 'NFC' THEN 1 END) as nfc_taps,
            COUNT(CASE WHEN v.type = 'WIFI' THEN 1 END) as wifi_accesses,
            -- Advanced engagement metrics
            ROUND(COUNT(*)::DECIMAL / NULLIF(COUNT(DISTINCT v.fp), 0), 2) as interactions_per_user,
            COUNT(DISTINCT DATE(v.created_at AT TIME ZONE p_timezone)) as active_days,
            -- Geographic and device insights
            COUNT(DISTINCT v.country) as countries_reached,
            COUNT(DISTINCT v.city) as cities_reached,
            COUNT(CASE WHEN v.platform = 'Mobile' THEN 1 END) as mobile_interactions,
            COUNT(CASE WHEN v.platform = 'Desktop' THEN 1 END) as desktop_interactions,
            -- Traffic source analysis
            COUNT(CASE WHEN v.referrer = 'direct' THEN 1 END) as direct_visits,
            COUNT(CASE WHEN v.referrer != 'direct' AND v.referrer IS NOT NULL THEN 1 END) as referred_visits,
            -- Time-based patterns
            COUNT(CASE WHEN EXTRACT(dow FROM v.created_at AT TIME ZONE p_timezone) BETWEEN 1 AND 5 THEN 1 END) as weekday_interactions,
            COUNT(CASE WHEN EXTRACT(dow FROM v.created_at AT TIME ZONE p_timezone) IN (0, 6) THEN 1 END) as weekend_interactions,
            -- Peak performance hour
            MODE() WITHIN GROUP (ORDER BY EXTRACT(hour FROM v.created_at AT TIME ZONE p_timezone)) as peak_hour,
            -- Tags associated with this touchpoint
            (
                SELECT json_agg(
                    json_build_object('id', t.id, 'name', t.name)
                )
                FROM tp_tag_links ttl
                JOIN tags t ON ttl.tag_id = t.id
                WHERE ttl.tp_id = ft.tp_id
            ) as associated_tags
        FROM filtered_touchpoints ft
        LEFT JOIN visits v ON ft.tp_id = v.tp_id
            AND v.organization_id = p_organization_id
            AND v.created_at >= start_date
            AND v.created_at < end_date            
        GROUP BY ft.tp_id, ft.name, ft.slug
    ),
    ranked_touchpoints AS (
        SELECT 
            *,
            -- Multiple ranking criteria
            ROW_NUMBER() OVER (ORDER BY total_interactions DESC) as rank_by_volume,
            ROW_NUMBER() OVER (ORDER BY unique_users DESC) as rank_by_reach,
            ROW_NUMBER() OVER (ORDER BY interactions_per_user DESC) as rank_by_engagement,
            ROW_NUMBER() OVER (ORDER BY active_days DESC) as rank_by_consistency,
            ROW_NUMBER() OVER (ORDER BY countries_reached DESC) as rank_by_geographic_reach,
            -- Composite performance score (weighted)
            (
                COALESCE(total_interactions::DECIMAL / NULLIF(MAX(total_interactions) OVER(), 0), 0) * 0.3 +
                COALESCE(unique_users::DECIMAL / NULLIF(MAX(unique_users) OVER(), 0), 0) * 0.25 +
                COALESCE(interactions_per_user::DECIMAL / NULLIF(MAX(interactions_per_user) OVER(), 0), 0) * 0.2 +
                COALESCE(active_days::DECIMAL / NULLIF(MAX(active_days) OVER(), 0), 0) * 0.15 +
                COALESCE(countries_reached::DECIMAL / NULLIF(MAX(countries_reached) OVER(), 0), 0) * 0.1
            ) * 100 as performance_score,
            -- Market share calculations
            ROUND(total_interactions::DECIMAL / NULLIF(SUM(total_interactions) OVER(), 0) * 100, 1) as volume_share_pct,
            ROUND(unique_users::DECIMAL / NULLIF(SUM(unique_users) OVER(), 0) * 100, 1) as user_share_pct,
            -- Usage pattern insights
            ROUND(mobile_interactions::DECIMAL / NULLIF(total_interactions, 0) * 100, 1) as mobile_usage_pct,
            ROUND(weekend_interactions::DECIMAL / NULLIF(total_interactions, 0) * 100, 1) as weekend_usage_pct,
            ROUND(direct_visits::DECIMAL / NULLIF(total_interactions, 0) * 100, 1) as direct_traffic_pct
        FROM touchpoint_performance
        WHERE total_interactions > 0  -- Only include touchpoints with activity
    ),
    top_performers AS (
        SELECT 
            *,
            ROW_NUMBER() OVER (ORDER BY performance_score DESC) as overall_rank,
            -- Performance tier classification
            CASE 
                WHEN performance_score >= 80 THEN 'top_performer'
                WHEN performance_score >= 60 THEN 'good_performer'
                WHEN performance_score >= 40 THEN 'average_performer'
                WHEN performance_score >= 20 THEN 'underperformer'
                ELSE 'poor_performer'
            END as performance_tier,
            -- Engagement quality assessment
            CASE 
                WHEN interactions_per_user >= 3.0 THEN 'high_engagement'
                WHEN interactions_per_user >= 2.0 THEN 'medium_engagement'
                WHEN interactions_per_user >= 1.5 THEN 'low_engagement'
                ELSE 'very_low_engagement'
            END as engagement_quality
        FROM ranked_touchpoints
    ),
    summary_stats AS (
        SELECT 
            COUNT(*) as total_touchpoints_analyzed,
            SUM(total_interactions) as total_interactions_all,
            COUNT(DISTINCT tp_id) as active_touchpoints_count,
            ROUND(AVG(performance_score), 1) as avg_performance_score,
            ROUND(AVG(interactions_per_user), 2) as avg_engagement_rate
        FROM top_performers
    )
    SELECT json_build_object(
        'period_info', json_build_object(
            'period_days', p_period_days,
            'start_date', start_date,
            'end_date', end_date,
            'timezone', p_timezone,
            'is_premium', p_is_premium
        ),
        'filters_applied', json_build_object(
            'has_filters', (p_tag_ids IS NOT NULL OR p_touchpoint_ids IS NOT NULL),
            'tags_count', COALESCE(array_length(p_tag_ids, 1), 0),
            'touchpoints_count', COALESCE(array_length(p_touchpoint_ids, 1), 0),
            'total_touchpoints_in_filter', (SELECT COUNT(*) FROM filtered_touchpoints),
            'active_touchpoints_in_period', (SELECT active_touchpoints_count FROM summary_stats)
        ),
        'top_touchpoints', COALESCE(
            (
                SELECT json_agg(
                    json_build_object(
                        'rank', overall_rank,
                        'touchpoint_id', tp_id,
                        'name', touchpoint_name,                        
                        'slug', touchpoint_slug,
                        'performance_score', ROUND(performance_score::NUMERIC, 1),
                        'performance_tier', performance_tier,
                        'engagement_quality', engagement_quality,
                        'associated_tags', associated_tags,
                        'core_metrics', json_build_object(
                            'total_interactions', total_interactions,
                            'unique_users', unique_users,
                            'interactions_per_user', interactions_per_user,
                            'active_days', active_days,
                            'volume_share_pct', volume_share_pct,
                            'user_share_pct', user_share_pct
                        ),
                        'interaction_breakdown', json_build_object(
                            'link_clicks', link_clicks,
                            'qr_scans', qr_scans,
                            'nfc_taps', nfc_taps,
                            'wifi_accesses', wifi_accesses
                        ),
                        'audience_insights', json_build_object(
                            'countries_reached', countries_reached,
                            'cities_reached', cities_reached,
                            'mobile_usage_pct', mobile_usage_pct,
                            'weekend_usage_pct', weekend_usage_pct,
                            'direct_traffic_pct', direct_traffic_pct,
                            'peak_hour', peak_hour
                        ),
                        'rankings', json_build_object(
                            'by_volume', rank_by_volume,
                            'by_reach', rank_by_reach,
                            'by_engagement', rank_by_engagement,
                            'by_consistency', rank_by_consistency,
                            'by_geographic_reach', rank_by_geographic_reach
                        )
                    ) ORDER BY overall_rank
                )
                FROM top_performers 
                WHERE overall_rank <= 5
            ),
            '[]'::json
        ),
        'summary', json_build_object(
            'total_touchpoints_analyzed', (SELECT total_touchpoints_analyzed FROM summary_stats),
            'active_touchpoints_count', (SELECT active_touchpoints_count FROM summary_stats),
            'total_interactions_all', (SELECT total_interactions_all FROM summary_stats),
            'avg_performance_score', (SELECT avg_performance_score FROM summary_stats),
            'avg_engagement_rate', (SELECT avg_engagement_rate FROM summary_stats),
            'top_performer', COALESCE(
                (
                    SELECT json_build_object(
                        'name', touchpoint_name,
                        'performance_score', ROUND(performance_score::NUMERIC, 1),
                        'total_interactions', total_interactions,
                        'performance_tier', performance_tier
                    )
                    FROM top_performers 
                    WHERE overall_rank = 1
                ),
                json_build_object('message', 'No active touchpoints in selected period')
            ),
            'performance_distribution', json_build_object(
                'top_performers', (SELECT COUNT(*) FROM top_performers WHERE performance_tier = 'top_performer'),
                'good_performers', (SELECT COUNT(*) FROM top_performers WHERE performance_tier = 'good_performer'),
                'average_performers', (SELECT COUNT(*) FROM top_performers WHERE performance_tier = 'average_performer'),  
                'underperformers', (SELECT COUNT(*) FROM top_performers WHERE performance_tier = 'underperformer'),
                'poor_performers', (SELECT COUNT(*) FROM top_performers WHERE performance_tier = 'poor_performer')
            )
        )
    ) INTO result
    FROM summary_stats;
    
    RETURN result;
    
EXCEPTION WHEN OTHERS THEN
    RETURN json_build_object(
        'error', TRUE,
        'message', SQLERRM,
        'period_days', p_period_days,
        'organization_id', p_organization_id
    );
END;$$;


--
-- Name: get_paginated_data(text, integer, integer, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_paginated_data(table_name text, page_num integer, page_size integer, search_column text DEFAULT NULL::text, search_value text DEFAULT NULL::text, filter_column text DEFAULT NULL::text, filter_value text DEFAULT NULL::text) RETURNS json[]
    LANGUAGE plpgsql
    AS $$
DECLARE
  result json[];
  sql text;
BEGIN
  sql := format('
    SELECT array_agg(row_to_json(t))
    FROM (
      SELECT * FROM %I
      WHERE ( %L IS NULL OR %L IS NULL OR %I::text ILIKE %L )
      AND   ( %L IS NULL OR %L IS NULL OR %I::text ILIKE %L )
      ORDER BY created_at DESC
      LIMIT %s OFFSET %s
    ) t',
    table_name,
    search_column, search_value, COALESCE(search_column, 'user_id'), 
    CASE WHEN search_value IS NOT NULL THEN '%' || search_value || '%' ELSE NULL END,
    filter_column, filter_value, COALESCE(filter_column, 'status'),
    CASE WHEN filter_value IS NOT NULL THEN '%' || filter_value || '%' ELSE NULL END,
    page_size, (page_num - 1) * page_size
  );

  EXECUTE sql INTO result;

  RETURN result;
END;
$$;


--
-- Name: get_profile_visits(timestamp with time zone, timestamp with time zone, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_profile_visits(_from timestamp with time zone, _to timestamp with time zone, _limit integer DEFAULT NULL::integer) RETURNS TABLE(email text, unique_visits bigint, total_visits bigint, total_scans bigint, total_clicks bigint)
    LANGUAGE sql STABLE
    AS $$
    SELECT 
        pf.email,
        COUNT(DISTINCT v.fp) AS unique_visits,
        COUNT(*) AS total_visits,
        COUNT(*) FILTER (WHERE v.type = 'QR') AS total_scans,
        COUNT(*) FILTER (WHERE v.type = 'LINK') AS total_clicks
    FROM profiles pf
    LEFT JOIN visits v 
        ON pf.id = v.user_id
    WHERE v.created_at AT TIME ZONE 'Asia/Ho_Chi_Minh'
          BETWEEN (_from AT TIME ZONE 'Asia/Ho_Chi_Minh')
              AND (_to AT TIME ZONE 'Asia/Ho_Chi_Minh')
    GROUP BY pf.email
    ORDER BY total_visits DESC
    LIMIT _limit;
$$;


--
-- Name: get_profiles_list(integer, integer, text, text, uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_profiles_list(page_num integer, page_size integer, search_column text DEFAULT NULL::text, search_value text DEFAULT NULL::text, filter_plan uuid DEFAULT NULL::uuid, created_from timestamp with time zone DEFAULT NULL::timestamp with time zone, created_to timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS json
    LANGUAGE plpgsql
    AS $_$
DECLARE
  result JSON;
  offset_val INT := (page_num - 1) * page_size;
  sql TEXT;
BEGIN
  sql := '
    SELECT COALESCE(json_agg(t), ''[]''::json)
    FROM (
      SELECT m.id,
             m.name,
             m.email,
             m.created_at,
             m.signup_ip,
             m.signup_fp,
             m.last_logged_in,
             up.expires_at,
             up.subscribed_at,
             row_to_json(p) AS plan
      FROM profiles m
      LEFT JOIN user_plans up ON up.user_id = m.id
      LEFT JOIN plans p ON p.id = up.plan_id
      WHERE 1=1';

  -- Dynamic filters
  IF search_column IS NOT NULL AND search_value IS NOT NULL THEN
    sql := sql || ' AND m.' || quote_ident(search_column) || ' ILIKE $1';
  END IF;

  IF filter_plan IS NOT NULL THEN
    sql := sql || ' AND up.plan_id = $2';
  END IF;

  IF created_from IS NOT NULL THEN
    sql := sql || ' AND m.created_at >= $3';
  END IF;

  IF created_to IS NOT NULL THEN
    sql := sql || ' AND m.created_at <= $4';
  END IF;

  -- Final pagination
  sql := sql || '
      ORDER BY m.created_at DESC
      LIMIT $5 OFFSET $6
    ) t';

  -- Execute the SQL
  EXECUTE sql
  INTO result
  USING
    CASE WHEN search_column IS NOT NULL AND search_value IS NOT NULL THEN '%' || search_value || '%' ELSE NULL END,
    filter_plan,
    created_from,
    created_to,
    page_size,
    offset_val;

  RETURN result;
END;
$_$;


--
-- Name: get_rage_click_summary(uuid, text, timestamp with time zone, timestamp with time zone, text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_rage_click_summary(_org_id uuid, _page_path text, _from timestamp with time zone, _to timestamp with time zone, _device_type text DEFAULT NULL::text, _hostname text DEFAULT NULL::text, _limit integer DEFAULT 20) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    AS $$
BEGIN
  RETURN coalesce(
    (SELECT jsonb_agg(row_to_json(r))
     FROM (
       SELECT
         selector_path AS selector,
         element_text AS text,
         element_tag AS tag,
         element_href AS href,
         count(*) AS rage_click_count,
         count(DISTINCT session_id) AS affected_sessions,
         max(timestamp) AS last_seen
       FROM interactions
       WHERE organization_id = _org_id
         AND page_path = _page_path
         AND timestamp >= _from AND timestamp < _to + interval '1 day'
         AND interaction_type = 'rage_click'
         AND is_bot = false
         AND (_device_type IS NULL OR device_type = _device_type)
         AND (_hostname IS NULL
              OR page_url LIKE 'https://' || _hostname || '/%'
              OR page_url LIKE 'http://' || _hostname || '/%')
         AND selector_path IS NOT NULL
       GROUP BY selector_path, element_text, element_tag, element_href
       ORDER BY rage_click_count DESC
       LIMIT _limit
     ) r),
    '[]'::jsonb
  );
END;
$$;


--
-- Name: get_rage_click_summary(uuid, text, timestamp with time zone, timestamp with time zone, text, text, integer, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_rage_click_summary(_org_id uuid, _page_path text, _from timestamp with time zone, _to timestamp with time zone, _device_type text DEFAULT NULL::text, _hostname text DEFAULT NULL::text, _limit integer DEFAULT 20, _tp_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    AS $$
BEGIN
  RETURN coalesce(
    (SELECT jsonb_agg(row_to_json(r))
     FROM (
       SELECT
         selector_path AS selector,
         element_text AS text,
         element_tag AS tag,
         element_href AS href,
         count(*) AS rage_click_count,
         count(DISTINCT session_id) AS affected_sessions,
         max(timestamp) AS last_seen
       FROM interactions
       WHERE organization_id = _org_id
         AND page_path = _page_path
         AND timestamp >= _from AND timestamp < _to + interval '1 day'
         AND interaction_type = 'rage_click'
         AND is_bot = false
         AND (_device_type IS NULL OR device_type = _device_type)
         AND (_hostname IS NULL
              OR page_url LIKE 'https://' || _hostname || '/%'
              OR page_url LIKE 'http://' || _hostname || '/%')
         AND selector_path IS NOT NULL
         AND (_tp_id IS NULL OR session_id IN (
             SELECT DISTINCT session_id FROM pageviews
             WHERE tp_id = _tp_id AND organization_id = _org_id
         ))
       GROUP BY selector_path, element_text, element_tag, element_href
       ORDER BY rage_click_count DESC
       LIMIT _limit
     ) r),
    '[]'::jsonb
  );
END;
$$;


--
-- Name: get_ranking_by_destinations(uuid, text, uuid[], uuid[], uuid[], uuid[], boolean, timestamp without time zone, timestamp without time zone, boolean, text[], text[], text[], uuid, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_ranking_by_destinations(_organization_id uuid, _type text, _campaign_ids uuid[] DEFAULT NULL::uuid[], _tp_ids uuid[] DEFAULT NULL::uuid[], _tag_ids uuid[] DEFAULT NULL::uuid[], _collection_ids uuid[] DEFAULT NULL::uuid[], _include_null_collection boolean DEFAULT false, _start_time timestamp without time zone DEFAULT NULL::timestamp without time zone, _end_time timestamp without time zone DEFAULT NULL::timestamp without time zone, _exclude_bot boolean DEFAULT false, _utm_source_values text[] DEFAULT NULL::text[], _utm_medium_values text[] DEFAULT NULL::text[], _utm_campaign_values text[] DEFAULT NULL::text[], _user_id uuid DEFAULT NULL::uuid, _interaction_types text[] DEFAULT NULL::text[]) RETURNS jsonb
    LANGUAGE plpgsql
    AS $_$
DECLARE
    result jsonb;
    tp_ids_from_tags uuid[];
    filtered_tp_ids uuid[];
    has_collection_filter boolean := false;
BEGIN
    -- Handle tag_ids
    IF _tag_ids IS NOT NULL AND array_length(_tag_ids, 1) > 0 THEN
        SELECT array_agg(DISTINCT tp_id)
        INTO tp_ids_from_tags
        FROM tp_tag_links
        WHERE tag_id = ANY(_tag_ids);

        IF _tp_ids IS NOT NULL AND array_length(_tp_ids, 1) > 0 THEN
            _tp_ids := _tp_ids || tp_ids_from_tags;
        ELSE
            _tp_ids := tp_ids_from_tags;
        END IF;
    END IF;

    -- Collection filtering
    IF _collection_ids IS NOT NULL THEN
        has_collection_filter := true;

        SELECT array_agg(DISTINCT tp.id)
        INTO filtered_tp_ids
        FROM touch_points tp
        WHERE (
            tp.collection_id = ANY(_collection_ids)
            OR (_include_null_collection = true AND tp.collection_id IS NULL AND tp.user_id = _user_id)
        )
        AND (
            _tp_ids IS NULL
            OR array_length(_tp_ids, 1) IS NULL
            OR tp.id = ANY(_tp_ids)
        );

        _tp_ids := COALESCE(filtered_tp_ids, ARRAY[]::uuid[]);
    END IF;

    WITH filtered_visits AS (
        SELECT *
        FROM visits
        WHERE organization_id = _organization_id
          AND (_campaign_ids IS NULL OR array_length(_campaign_ids, 1) IS NULL OR campaign_id = ANY(_campaign_ids))
          AND (
              CASE
                  WHEN has_collection_filter THEN tp_id = ANY(_tp_ids)
                  ELSE (_tp_ids IS NULL OR array_length(_tp_ids, 1) IS NULL OR tp_id = ANY(_tp_ids))
              END
          )
          AND (_start_time IS NULL OR created_at >= _start_time)
          AND (_end_time IS NULL OR created_at <= _end_time)
          AND (NOT _exclude_bot OR is_bot = FALSE)
          AND (_interaction_types IS NULL OR array_length(_interaction_types, 1) IS NULL OR type = ANY(_interaction_types))
          AND (_utm_source_values IS NULL OR array_length(_utm_source_values, 1) IS NULL OR utm_tags->>'utm_source' = ANY(_utm_source_values))
          AND (_utm_medium_values IS NULL OR array_length(_utm_medium_values, 1) IS NULL OR utm_tags->>'utm_medium' = ANY(_utm_medium_values))
          AND (_utm_campaign_values IS NULL OR array_length(_utm_campaign_values, 1) IS NULL OR utm_tags->>'utm_campaign' = ANY(_utm_campaign_values))
          AND content_value IS NOT NULL
          AND content_value != ''
    ),

    ranking_by_full_urls AS (
        SELECT
            v.content_value AS destination,
            'full' AS segment,
            COUNT(v.id) AS count,
            COUNT(DISTINCT v.fp) FILTER (WHERE v.fp IS NOT NULL) AS unique_count
        FROM filtered_visits v
        GROUP BY v.content_value
        ORDER BY count DESC
    ),

    ranking_by_base_urls AS (
        SELECT
            CASE 
                WHEN v.content_value ~ '^https?://' THEN
                    -- Extract domain + path (without query params or hash)
                    regexp_replace(
                        regexp_replace(v.content_value, '^(https?://[^?#]+).*$', '\1'),
                        '^(https?://)www\.', '\1'
                    )
                ELSE
                    v.content_value
            END AS destination,
            'base' AS segment,
            COUNT(v.id) AS count,
            COUNT(DISTINCT v.fp) FILTER (WHERE v.fp IS NOT NULL) AS unique_count
        FROM filtered_visits v
        GROUP BY 
            CASE 
                WHEN v.content_value ~ '^https?://' THEN
                    -- Extract domain + path (without query params or hash)
                    regexp_replace(
                        regexp_replace(v.content_value, '^(https?://[^?#]+).*$', '\1'),
                        '^(https?://)www\.', '\1'
                    )
                ELSE
                    v.content_value
            END
        ORDER BY count DESC
    )

    SELECT 
        CASE 
            WHEN _type = 'full_urls' THEN
                jsonb_build_object(
                    'data', (SELECT jsonb_agg(jsonb_build_object('destination', destination, 'segment', segment, 'count', count, 'unique_count', unique_count)) FROM ranking_by_full_urls),
                    'type', 'full_urls',
                    'total', (SELECT COUNT(*) FROM filtered_visits),
                    'total_unique', (SELECT COUNT(DISTINCT fp) FROM filtered_visits WHERE fp IS NOT NULL)
                )
            WHEN _type = 'base_urls' THEN
                jsonb_build_object(
                    'data', (SELECT jsonb_agg(jsonb_build_object('destination', destination, 'segment', segment, 'count', count, 'unique_count', unique_count)) FROM ranking_by_base_urls),
                    'type', 'base_urls',
                    'total', (SELECT COUNT(*) FROM filtered_visits),
                    'total_unique', (SELECT COUNT(DISTINCT fp) FROM filtered_visits WHERE fp IS NOT NULL)
                )
            ELSE
                jsonb_build_object(
                    'data', '[]'::jsonb,
                    'type', _type,
                    'total', 0,
                    'total_unique', 0
                )
        END
    INTO result;

    RETURN COALESCE(result, '{}'::jsonb);
END;
$_$;


--
-- Name: get_ranking_by_links(uuid, text, uuid[], uuid[], uuid[], uuid[], boolean, timestamp without time zone, timestamp without time zone, boolean, text[], text[], text[], uuid, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_ranking_by_links(_organization_id uuid, _type text, _campaign_ids uuid[] DEFAULT NULL::uuid[], _tp_ids uuid[] DEFAULT NULL::uuid[], _tag_ids uuid[] DEFAULT NULL::uuid[], _collection_ids uuid[] DEFAULT NULL::uuid[], _include_null_collection boolean DEFAULT false, _start_time timestamp without time zone DEFAULT NULL::timestamp without time zone, _end_time timestamp without time zone DEFAULT NULL::timestamp without time zone, _exclude_bot boolean DEFAULT false, _utm_source_values text[] DEFAULT NULL::text[], _utm_medium_values text[] DEFAULT NULL::text[], _utm_campaign_values text[] DEFAULT NULL::text[], _user_id uuid DEFAULT NULL::uuid, _interaction_types text[] DEFAULT NULL::text[]) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    result jsonb;
    tp_ids_from_tags uuid[];
    filtered_tp_ids uuid[];
    has_collection_filter boolean := false;
BEGIN
    -- Handle tag_ids
    IF _tag_ids IS NOT NULL AND array_length(_tag_ids, 1) > 0 THEN
        SELECT array_agg(DISTINCT tp_id)
        INTO tp_ids_from_tags
        FROM tp_tag_links
        WHERE tag_id = ANY(_tag_ids);

        IF _tp_ids IS NOT NULL AND array_length(_tp_ids, 1) > 0 THEN
            _tp_ids := _tp_ids || tp_ids_from_tags;
        ELSE
            _tp_ids := tp_ids_from_tags;
        END IF;
    END IF;

    -- Collection filtering
    IF _collection_ids IS NOT NULL THEN
        has_collection_filter := true;

        SELECT array_agg(DISTINCT tp.id)
        INTO filtered_tp_ids
        FROM touch_points tp
        WHERE (
            tp.collection_id = ANY(_collection_ids)
            OR (_include_null_collection = true AND tp.collection_id IS NULL AND tp.user_id = _user_id)
        )
        AND (
            _tp_ids IS NULL
            OR array_length(_tp_ids, 1) IS NULL
            OR tp.id = ANY(_tp_ids)
        );

        _tp_ids := COALESCE(filtered_tp_ids, ARRAY[]::uuid[]);
    END IF;

    WITH filtered_visits AS (
        SELECT *
        FROM visits
        WHERE organization_id = _organization_id
          AND (_campaign_ids IS NULL OR array_length(_campaign_ids, 1) IS NULL OR campaign_id = ANY(_campaign_ids))
          AND (
              CASE
                  WHEN has_collection_filter THEN tp_id = ANY(_tp_ids)
                  ELSE (_tp_ids IS NULL OR array_length(_tp_ids, 1) IS NULL OR tp_id = ANY(_tp_ids))
              END
          )
          AND (_start_time IS NULL OR created_at >= _start_time)
          AND (_end_time IS NULL OR created_at <= _end_time)
          AND (NOT _exclude_bot OR is_bot = FALSE)
          AND (_interaction_types IS NULL OR array_length(_interaction_types, 1) IS NULL OR type = ANY(_interaction_types))
          AND (_utm_source_values IS NULL OR array_length(_utm_source_values, 1) IS NULL OR utm_tags->>'utm_source' = ANY(_utm_source_values))
          AND (_utm_medium_values IS NULL OR array_length(_utm_medium_values, 1) IS NULL OR utm_tags->>'utm_medium' = ANY(_utm_medium_values))
          AND (_utm_campaign_values IS NULL OR array_length(_utm_campaign_values, 1) IS NULL OR utm_tags->>'utm_campaign' = ANY(_utm_campaign_values))
    ),

    ranking_by_links AS (
        SELECT
            tp.id,
            tp.short_url AS name,
            COUNT(v.id) AS count,
            COUNT(DISTINCT v.fp) FILTER (WHERE v.fp IS NOT NULL) AS unique_count
        FROM filtered_visits v
        INNER JOIN touch_points tp ON v.tp_id = tp.id
        GROUP BY tp.id, tp.short_url
        ORDER BY count DESC
    ),

    ranking_by_tags AS (
        SELECT
            t.id,
            t.name,
            COUNT(v.id) AS count,
            COUNT(DISTINCT v.fp) FILTER (WHERE v.fp IS NOT NULL) AS unique_count
        FROM filtered_visits v
        INNER JOIN touch_points tp ON v.tp_id = tp.id
        INNER JOIN tp_tag_links ttl ON tp.id = ttl.tp_id
        INNER JOIN tags t ON ttl.tag_id = t.id
        GROUP BY t.id, t.name
        ORDER BY count DESC
    ),

    ranking_by_spaces AS (
        SELECT
            c.id,
            c.name,
            COUNT(v.id) AS count,
            COUNT(DISTINCT v.fp) FILTER (WHERE v.fp IS NOT NULL) AS unique_count
        FROM filtered_visits v
        INNER JOIN touch_points tp ON v.tp_id = tp.id
        INNER JOIN collections c ON tp.collection_id = c.id
        WHERE tp.collection_id IS NOT NULL
        GROUP BY c.id, c.name
        ORDER BY count DESC
    )

    SELECT 
        CASE 
            WHEN _type = 'by_links' THEN
                jsonb_build_object(
                    'data', (SELECT jsonb_agg(jsonb_build_object('id', id, 'name', name, 'count', count, 'unique_count', unique_count)) FROM ranking_by_links),
                    'type', 'by_links',
                    'total', (SELECT COUNT(*) FROM filtered_visits),
                    'total_unique', (SELECT COUNT(DISTINCT fp) FROM filtered_visits WHERE fp IS NOT NULL)
                )
            WHEN _type = 'by_tags' THEN
                jsonb_build_object(
                    'data', (SELECT jsonb_agg(jsonb_build_object('id', id, 'name', name, 'count', count, 'unique_count', unique_count)) FROM ranking_by_tags),
                    'type', 'by_tags',
                    'total', (SELECT COUNT(*) FROM filtered_visits),
                    'total_unique', (SELECT COUNT(DISTINCT fp) FROM filtered_visits WHERE fp IS NOT NULL)
                )
            WHEN _type = 'by_spaces' THEN
                jsonb_build_object(
                    'data', (SELECT jsonb_agg(jsonb_build_object('id', id, 'name', name, 'count', count, 'unique_count', unique_count)) FROM ranking_by_spaces),
                    'type', 'by_spaces',
                    'total', (SELECT COUNT(*) FROM filtered_visits),
                    'total_unique', (SELECT COUNT(DISTINCT fp) FROM filtered_visits WHERE fp IS NOT NULL)
                )
            ELSE
                jsonb_build_object(
                    'data', '[]'::jsonb,
                    'type', _type,
                    'total', 0,
                    'total_unique', 0
                )
        END
    INTO result;

    RETURN COALESCE(result, '{}'::jsonb);
END;
$$;


--
-- Name: get_ranking_by_referrers(uuid, text, uuid[], uuid[], uuid[], boolean, timestamp without time zone, timestamp without time zone, boolean, text[], text[], text[], uuid, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_ranking_by_referrers(_organization_id uuid, _type text, _tag_ids uuid[] DEFAULT NULL::uuid[], _tp_ids uuid[] DEFAULT NULL::uuid[], _collection_ids uuid[] DEFAULT NULL::uuid[], _include_null_collection boolean DEFAULT false, _start_time timestamp without time zone DEFAULT NULL::timestamp without time zone, _end_time timestamp without time zone DEFAULT NULL::timestamp without time zone, _exclude_bot boolean DEFAULT false, _utm_source_values text[] DEFAULT NULL::text[], _utm_medium_values text[] DEFAULT NULL::text[], _utm_campaign_values text[] DEFAULT NULL::text[], _user_id uuid DEFAULT NULL::uuid, _interaction_types text[] DEFAULT NULL::text[]) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    result jsonb;
    tp_ids_from_tags uuid[];
    filtered_tp_ids uuid[];
    has_collection_filter boolean := false;
BEGIN
    -- Handle tag_ids
    IF _tag_ids IS NOT NULL AND array_length(_tag_ids, 1) > 0 THEN
        SELECT array_agg(DISTINCT tp_id)
        INTO tp_ids_from_tags
        FROM tp_tag_links
        WHERE tag_id = ANY(_tag_ids);

        IF _tp_ids IS NOT NULL AND array_length(_tp_ids, 1) > 0 THEN
            _tp_ids := _tp_ids || tp_ids_from_tags;
        ELSE
            _tp_ids := tp_ids_from_tags;
        END IF;
    END IF;

    -- Collection filtering
    IF _collection_ids IS NOT NULL THEN
        has_collection_filter := true;

        SELECT array_agg(DISTINCT tp.id)
        INTO filtered_tp_ids
        FROM touch_points tp
        WHERE (
            tp.collection_id = ANY(_collection_ids)
            OR (_include_null_collection = true AND tp.collection_id IS NULL AND tp.user_id = _user_id)
        )
        AND (
            _tp_ids IS NULL
            OR array_length(_tp_ids, 1) IS NULL
            OR tp.id = ANY(_tp_ids)
        );

        _tp_ids := COALESCE(filtered_tp_ids, ARRAY[]::uuid[]);
    END IF;

    WITH filtered_visits AS (
        SELECT *
        FROM visits
        WHERE organization_id = _organization_id
          AND (
              CASE
                  WHEN has_collection_filter THEN tp_id = ANY(_tp_ids)
                  ELSE (_tp_ids IS NULL OR array_length(_tp_ids, 1) IS NULL OR tp_id = ANY(_tp_ids))
              END
          )
          AND (_start_time IS NULL OR created_at >= _start_time)
          AND (_end_time IS NULL OR created_at <= _end_time)
          AND (NOT _exclude_bot OR is_bot = FALSE)
          AND (_interaction_types IS NULL OR array_length(_interaction_types, 1) IS NULL OR type = ANY(_interaction_types))
          AND (_utm_source_values IS NULL OR array_length(_utm_source_values, 1) IS NULL OR utm_tags->>'utm_source' = ANY(_utm_source_values))
          AND (_utm_medium_values IS NULL OR array_length(_utm_medium_values, 1) IS NULL OR utm_tags->>'utm_medium' = ANY(_utm_medium_values))
          AND (_utm_campaign_values IS NULL OR array_length(_utm_campaign_values, 1) IS NULL OR utm_tags->>'utm_campaign' = ANY(_utm_campaign_values))
    ),

    total_counts AS (
        SELECT 
            COUNT(id) AS total,
            COUNT(DISTINCT fp) FILTER (WHERE fp IS NOT NULL) AS total_unique
        FROM filtered_visits
    ),

    ranking_data AS (
        SELECT
            CASE 
                WHEN _type = 'referrer' THEN
                    CASE 
                        WHEN v.referrer IS NULL OR v.referrer = '' OR LOWER(v.referrer) = 'direct' THEN 'direct'
                        ELSE v.referrer
                    END
                WHEN _type = 'raw' THEN
                    CASE 
                        WHEN v.raw_referrer IS NULL OR v.raw_referrer = '' OR LOWER(v.raw_referrer) = 'direct' THEN 'direct'
                        ELSE v.raw_referrer
                    END
                ELSE 'direct'
            END AS referrer,
            COUNT(v.id) AS count,
            COUNT(DISTINCT v.fp) FILTER (WHERE v.fp IS NOT NULL) AS unique_count
        FROM filtered_visits v
        GROUP BY 
            CASE 
                WHEN _type = 'referrer' THEN
                    CASE 
                        WHEN v.referrer IS NULL OR v.referrer = '' OR LOWER(v.referrer) = 'direct' THEN 'direct'
                        ELSE v.referrer
                    END
                WHEN _type = 'raw' THEN
                    CASE 
                        WHEN v.raw_referrer IS NULL OR v.raw_referrer = '' OR LOWER(v.raw_referrer) = 'direct' THEN 'direct'
                        ELSE v.raw_referrer
                    END
                ELSE 'direct'
            END
        ORDER BY count DESC
        LIMIT 100
    )

    SELECT jsonb_build_object(
        'data', COALESCE((SELECT jsonb_agg(jsonb_build_object('referrer', referrer, 'count', count, 'unique_count', unique_count)) FROM ranking_data), '[]'::jsonb),
        'type', _type,
        'total', (SELECT total FROM total_counts),
        'total_unique', (SELECT total_unique FROM total_counts)
    )
    INTO result;

    RETURN COALESCE(result, '{}'::jsonb);
END;
$$;


--
-- Name: get_ranking_by_utm_parameters(uuid, text, uuid[], uuid[], uuid[], boolean, timestamp without time zone, timestamp without time zone, boolean, text[], text[], text[], uuid, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_ranking_by_utm_parameters(_organization_id uuid, _type text, _tag_ids uuid[] DEFAULT NULL::uuid[], _tp_ids uuid[] DEFAULT NULL::uuid[], _collection_ids uuid[] DEFAULT NULL::uuid[], _include_null_collection boolean DEFAULT false, _start_time timestamp without time zone DEFAULT NULL::timestamp without time zone, _end_time timestamp without time zone DEFAULT NULL::timestamp without time zone, _exclude_bot boolean DEFAULT false, _utm_source_values text[] DEFAULT NULL::text[], _utm_medium_values text[] DEFAULT NULL::text[], _utm_campaign_values text[] DEFAULT NULL::text[], _user_id uuid DEFAULT NULL::uuid, _interaction_types text[] DEFAULT NULL::text[]) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    result jsonb;
    tp_ids_from_tags uuid[];
    filtered_tp_ids uuid[];
    has_collection_filter boolean := false;
    utm_field text;
BEGIN
    -- Handle tag_ids
    IF _tag_ids IS NOT NULL AND array_length(_tag_ids, 1) > 0 THEN
        SELECT array_agg(DISTINCT tp_id)
        INTO tp_ids_from_tags
        FROM tp_tag_links
        WHERE tag_id = ANY(_tag_ids);

        IF _tp_ids IS NOT NULL AND array_length(_tp_ids, 1) > 0 THEN
            _tp_ids := _tp_ids || tp_ids_from_tags;
        ELSE
            _tp_ids := tp_ids_from_tags;
        END IF;
    END IF;

    -- Collection filtering
    IF _collection_ids IS NOT NULL THEN
        has_collection_filter := true;

        SELECT array_agg(DISTINCT tp.id)
        INTO filtered_tp_ids
        FROM touch_points tp
        WHERE (
            tp.collection_id = ANY(_collection_ids)
            OR (_include_null_collection = true AND tp.collection_id IS NULL AND tp.user_id = _user_id)
        )
        AND (
            _tp_ids IS NULL
            OR array_length(_tp_ids, 1) IS NULL
            OR tp.id = ANY(_tp_ids)
        );

        _tp_ids := COALESCE(filtered_tp_ids, ARRAY[]::uuid[]);
    END IF;

    -- Determine which UTM field to query based on type
    utm_field := CASE _type
        WHEN 'by_source' THEN 'utm_source'
        WHEN 'by_medium' THEN 'utm_medium'
        WHEN 'by_campaign' THEN 'utm_campaign'
        WHEN 'by_term' THEN 'utm_term'
        WHEN 'by_content' THEN 'utm_content'
        ELSE 'utm_source'
    END;

    WITH filtered_visits AS (
        SELECT *
        FROM visits
        WHERE organization_id = _organization_id
          AND (
              CASE
                  WHEN has_collection_filter THEN tp_id = ANY(_tp_ids)
                  ELSE (_tp_ids IS NULL OR array_length(_tp_ids, 1) IS NULL OR tp_id = ANY(_tp_ids))
              END
          )
          AND (_start_time IS NULL OR created_at >= _start_time)
          AND (_end_time IS NULL OR created_at <= _end_time)
          AND (NOT _exclude_bot OR is_bot = FALSE)
          AND (_interaction_types IS NULL OR array_length(_interaction_types, 1) IS NULL OR type = ANY(_interaction_types))
          AND (_utm_source_values IS NULL OR array_length(_utm_source_values, 1) IS NULL OR utm_tags->>'utm_source' = ANY(_utm_source_values))
          AND (_utm_medium_values IS NULL OR array_length(_utm_medium_values, 1) IS NULL OR utm_tags->>'utm_medium' = ANY(_utm_medium_values))
          AND (_utm_campaign_values IS NULL OR array_length(_utm_campaign_values, 1) IS NULL OR utm_tags->>'utm_campaign' = ANY(_utm_campaign_values))
          AND utm_tags->>utm_field IS NOT NULL
          AND utm_tags->>utm_field != ''
    ),

    total_counts AS (
        SELECT 
            COUNT(id) AS total,
            COUNT(DISTINCT fp) FILTER (WHERE fp IS NOT NULL) AS total_unique
        FROM filtered_visits
    ),

    ranking_data AS (
        SELECT
            v.utm_tags->>utm_field AS utm_value,
            COUNT(v.id) AS count,
            COUNT(DISTINCT v.fp) FILTER (WHERE v.fp IS NOT NULL) AS unique_count
        FROM filtered_visits v
        GROUP BY v.utm_tags->>utm_field
        ORDER BY count DESC
        LIMIT 100
    )

    SELECT jsonb_build_object(
        'data', COALESCE((SELECT jsonb_agg(jsonb_build_object('utm_value', utm_value, 'count', count, 'unique_count', unique_count)) FROM ranking_data), '[]'::jsonb),
        'type', _type,
        'total', (SELECT total FROM total_counts),
        'total_unique', (SELECT total_unique FROM total_counts)
    )
    INTO result;

    RETURN COALESCE(result, '{}'::jsonb);
END;
$$;


--
-- Name: get_raw_visit_data(uuid, integer, text, boolean, uuid[], uuid[], uuid[], boolean, boolean, timestamp with time zone, timestamp with time zone, integer, integer, text[], text[], text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_raw_visit_data(p_organization_id uuid, p_last_hours integer, p_timezone text DEFAULT 'UTC'::text, p_is_premium boolean DEFAULT false, p_tp_ids uuid[] DEFAULT NULL::uuid[], p_tag_ids uuid[] DEFAULT NULL::uuid[], p_collection_ids uuid[] DEFAULT NULL::uuid[], p_include_null_collection boolean DEFAULT false, p_exclude_bot boolean DEFAULT false, p_start_time timestamp with time zone DEFAULT NULL::timestamp with time zone, p_end_time timestamp with time zone DEFAULT NULL::timestamp with time zone, p_limit integer DEFAULT NULL::integer, p_offset integer DEFAULT 0, p_utm_source_values text[] DEFAULT NULL::text[], p_utm_medium_values text[] DEFAULT NULL::text[], p_utm_campaign_values text[] DEFAULT NULL::text[]) RETURNS TABLE(touchpoint_id uuid, touchpoint_name text, os text, platform text, channel text, country text, city text, ip text, isp text, referrer text, created_at timestamp with time zone, id uuid, total_count bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE
    end_local timestamp;
    start_local timestamp;
    filtered_tp_ids uuid[];
BEGIN
    -- Determine end time (use provided end_time or current time in timezone)
    end_local := coalesce(
        p_end_time AT TIME ZONE p_timezone,
        now() AT TIME ZONE p_timezone
    );

    -- Determine start time (use provided start_time or calculate from p_last_hours)
    start_local := coalesce(
        p_start_time AT TIME ZONE p_timezone,
        end_local - make_interval(hours => p_last_hours)
    );

    -- Apply collection filtering to tp_ids
    IF p_collection_ids IS NOT NULL AND array_length(p_collection_ids, 1) > 0 THEN
        SELECT array_agg(DISTINCT touch_points.id) INTO filtered_tp_ids
        FROM touch_points
        WHERE (
            -- Touch-points in specified collections
            collection_id = ANY(p_collection_ids)

            -- OR uncategorized touch-points (if includeNull is true)
            OR (
                p_include_null_collection = true
                AND collection_id IS NULL
            )
        )
        -- Also apply existing tp_ids filter if present
        AND (p_tp_ids IS NULL OR p_tp_ids = '{}' OR touch_points.id = ANY(p_tp_ids));

        -- Replace tp_ids with filtered list
        p_tp_ids := filtered_tp_ids;
    END IF;

    RETURN QUERY
    WITH filtered AS (
        SELECT
            v.tp_id,
            coalesce(tp.name, 'Touch point has been deleted') as touchpoint_name,
            v.os,
            v.platform,
            v.type as channel,
            v.country,
            v.referrer,
            v.city,
            v.ip::text as ip,
            v.isp,
            v.created_at,
            v.id
        FROM public.visits v
        LEFT JOIN public.touch_points tp
            ON tp.id = v.tp_id
            AND tp.deleted_at is null
        WHERE v.organization_id = p_organization_id
            AND (v.created_at AT TIME ZONE p_timezone) >= start_local
            AND (v.created_at AT TIME ZONE p_timezone) <  end_local
            -- Filter by touch point IDs if provided
            AND (p_tp_ids is null or p_tp_ids = '{}' or v.tp_id = any(p_tp_ids))
            -- Filter by tags if provided (join with tp_tag_links through touch points)
            AND (
                p_tag_ids is null
                or p_tag_ids = '{}'
                or exists (
                    select 1 from public.tp_tag_links tl
                    where tl.tp_id = v.tp_id
                        and tl.tag_id = any(p_tag_ids)
                )
            )
            -- Exclude bots if requested
            AND (NOT p_exclude_bot OR v.is_bot = FALSE)
            -- AND v.is_bot != p_exclude_bot
            -- UTM filters
            AND (p_utm_source_values IS NULL OR p_utm_source_values = '{}' OR v.utm_tags->>'utm_source' = ANY(p_utm_source_values))
            AND (p_utm_medium_values IS NULL OR p_utm_medium_values = '{}' OR v.utm_tags->>'utm_medium' = ANY(p_utm_medium_values))
            AND (p_utm_campaign_values IS NULL OR p_utm_campaign_values = '{}' OR v.utm_tags->>'utm_campaign' = ANY(p_utm_campaign_values))
    ),
    total AS (
        SELECT count(*) as total_count
        FROM filtered
    )
    SELECT
        f.tp_id as touchpoint_id,
        f.touchpoint_name,
        f.os,
        f.platform,
        f.channel,
        f.country,
        f.city,
        f.ip,
        f.isp,
        f.referrer,
        f.created_at,
        f.id,
        t.total_count
    FROM filtered f
    CROSS JOIN total t
    ORDER BY f.created_at DESC
    LIMIT p_limit
    OFFSET p_offset;
END;
$$;


--
-- Name: get_raw_visit_data_old(uuid, integer, text, boolean, uuid[], uuid[], boolean, timestamp with time zone, timestamp with time zone, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_raw_visit_data_old(p_organization_id uuid, p_last_hours integer, p_timezone text DEFAULT 'UTC'::text, p_is_premium boolean DEFAULT false, p_tp_ids uuid[] DEFAULT NULL::uuid[], p_tag_ids uuid[] DEFAULT NULL::uuid[], p_exclude_bot boolean DEFAULT false, p_start_time timestamp with time zone DEFAULT NULL::timestamp with time zone, p_end_time timestamp with time zone DEFAULT NULL::timestamp with time zone, p_limit integer DEFAULT NULL::integer, p_offset integer DEFAULT 0) RETURNS TABLE(touchpoint_id uuid, touchpoint_name text, os text, platform text, channel text, country text, city text, ip text, isp text, referrer text, created_at timestamp with time zone, id uuid, total_count bigint)
    LANGUAGE plpgsql
    AS $$declare
  end_local   timestamp;
  start_local timestamp;
begin
  -- Determine end time (use provided end_time or current time in timezone)
  end_local := coalesce(
    p_end_time at time zone p_timezone,
    now() at time zone p_timezone
  );

  -- Determine start time (use provided start_time or calculate from p_last_hours)
  start_local := coalesce(
    p_start_time at time zone p_timezone,
    end_local - make_interval(hours => p_last_hours)
  );

  return query
  with filtered as (
    select
      v.tp_id,
      coalesce(tp.name, 'Touch point has been deleted') as touchpoint_name,
      v.os,
      v.platform,
      v.type      as channel,
      v.country,
      v.referrer,
      v.city,
      v.ip::text  as ip,
      v.isp,
      v.created_at,
      v.id
    from public.visits v
    left join public.touch_points tp
      on tp.id = v.tp_id
     and tp.deleted_at is null
    where v.organization_id = p_organization_id
      and v.created_at >= (start_local at time zone p_timezone)
      and v.created_at <  (end_local at time zone p_timezone)
      -- Filter by touch point IDs if provided
      and (p_tp_ids is null or p_tp_ids = '{}' or v.tp_id = any(p_tp_ids))
      -- Filter by tags if provided (join with tp_tag_links through touch points)
      and (
        p_tag_ids is null
        or p_tag_ids = '{}'
        or exists (
          select 1 from public.tp_tag_links tl
          where tl.tp_id = v.tp_id
            and tl.tag_id = any(p_tag_ids)
        )
      )
      -- Exclude bots if requested
      and (p_exclude_bot = false or v.platform != 'bot')
  ),
  total as (
    select count(*) as total_count
    from filtered
  )
  select
    f.tp_id               as touchpoint_id,
    f.touchpoint_name,
    f.os,
    f.platform,
    f.channel,
    f.country,
    f.city,
    f.ip,
    f.isp,
    f.referrer,
    f.created_at,
    f.id,
    t.total_count
  from filtered f
  cross join total t
  order by f.created_at desc
  limit p_limit
  offset p_offset;
end;$$;


--
-- Name: get_raw_visit_data_v2(uuid, integer, text, boolean, uuid[], uuid[], uuid[], boolean, boolean, timestamp with time zone, timestamp with time zone, integer, integer, text[], text[], text[], uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_raw_visit_data_v2(p_organization_id uuid, p_last_hours integer, p_timezone text DEFAULT 'UTC'::text, p_is_premium boolean DEFAULT false, p_tp_ids uuid[] DEFAULT NULL::uuid[], p_tag_ids uuid[] DEFAULT NULL::uuid[], p_collection_ids uuid[] DEFAULT NULL::uuid[], p_include_null_collection boolean DEFAULT false, p_exclude_bot boolean DEFAULT false, p_start_time timestamp with time zone DEFAULT NULL::timestamp with time zone, p_end_time timestamp with time zone DEFAULT NULL::timestamp with time zone, p_limit integer DEFAULT NULL::integer, p_offset integer DEFAULT 0, p_utm_source_values text[] DEFAULT NULL::text[], p_utm_medium_values text[] DEFAULT NULL::text[], p_utm_campaign_values text[] DEFAULT NULL::text[], p_user_id uuid DEFAULT NULL::uuid) RETURNS TABLE(touchpoint_id uuid, touchpoint_name text, os text, platform text, channel text, country text, city text, ip text, isp text, referrer text, created_at timestamp with time zone, id uuid, total_count bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE
    end_local timestamp;
    start_local timestamp;
    filtered_tp_ids uuid[];
    has_collection_filter boolean;
BEGIN
    -- Determine end time (use provided end_time or current time in timezone)
    end_local := coalesce(
        p_end_time at time zone p_timezone,
        now() at time zone p_timezone
    );

    -- Determine start time (use provided start_time or calculate from p_last_hours)
    start_local := coalesce(
        p_start_time at time zone p_timezone,
        end_local - make_interval(hours => p_last_hours)
    );

    -- Track if collection filtering was applied
    has_collection_filter := false;

    -- Apply collection filtering to tp_ids
    -- Fixed: Use IS NOT NULL instead of array_length check (empty array returns NULL from array_length)
    IF p_collection_ids IS NOT NULL THEN
        has_collection_filter := true;

        SELECT array_agg(DISTINCT touch_points.id) INTO filtered_tp_ids
        FROM touch_points
        WHERE touch_points.organization_id = p_organization_id
        AND touch_points.deleted_at IS NULL
        AND (
            -- Touch-points in specified collections
            collection_id = ANY(p_collection_ids)
            -- OR uncategorized touch-points owned by user (if includeNull is true)
            OR (
                p_include_null_collection = true
                AND collection_id IS NULL
                AND user_id = p_user_id
            )
        )
        -- Also apply existing tp_ids filter if present
        AND (p_tp_ids IS NULL OR p_tp_ids = '{}' OR touch_points.id = ANY(p_tp_ids));

        -- Replace tp_ids with filtered list (use empty array if null to return no results)
        p_tp_ids := COALESCE(filtered_tp_ids, ARRAY[]::uuid[]);
    END IF;

    RETURN QUERY
    WITH filtered AS (
        SELECT
            v.tp_id,
            coalesce(tp.name, 'Touch point has been deleted') as touchpoint_name,
            v.os,
            v.platform,
            v.type as channel,
            v.country,
            v.referrer,
            v.city,
            v.ip::text as ip,
            v.isp,
            v.created_at,
            v.id
        FROM public.visits v
        LEFT JOIN public.touch_points tp
            ON tp.id = v.tp_id
            AND tp.deleted_at is null
        WHERE v.organization_id = p_organization_id
            AND v.created_at >= (start_local at time zone p_timezone)
            AND v.created_at <  (end_local at time zone p_timezone)
            -- Filter by touch point IDs
            -- When collection filter was applied: only show visits for filtered TPs (empty = no results)
            -- When no collection filter: show all or filter by provided p_tp_ids
            AND (
                CASE
                    WHEN has_collection_filter THEN v.tp_id = ANY(p_tp_ids)
                    ELSE (p_tp_ids IS NULL OR p_tp_ids = '{}' OR v.tp_id = ANY(p_tp_ids))
                END
            )
            -- Filter by tags if provided (join with tp_tag_links through touch points)
            AND (
                p_tag_ids is null
                or p_tag_ids = '{}'
                or exists (
                    select 1 from public.tp_tag_links tl
                    where tl.tp_id = v.tp_id
                        and tl.tag_id = any(p_tag_ids)
                )
            )
            -- Exclude bots if requested
            AND (NOT p_exclude_bot OR v.is_bot = FALSE)
            -- UTM filters
            AND (p_utm_source_values IS NULL OR p_utm_source_values = '{}' OR v.utm_tags->>'utm_source' = ANY(p_utm_source_values))
            AND (p_utm_medium_values IS NULL OR p_utm_medium_values = '{}' OR v.utm_tags->>'utm_medium' = ANY(p_utm_medium_values))
            AND (p_utm_campaign_values IS NULL OR p_utm_campaign_values = '{}' OR v.utm_tags->>'utm_campaign' = ANY(p_utm_campaign_values))
    ),
    total AS (
        SELECT count(*) as total_count
        FROM filtered
    )
    SELECT
        f.tp_id as touchpoint_id,
        f.touchpoint_name,
        f.os,
        f.platform,
        f.channel,
        f.country,
        f.city,
        f.ip,
        f.isp,
        f.referrer,
        f.created_at,
        f.id,
        t.total_count
    FROM filtered f
    CROSS JOIN total t
    ORDER BY f.created_at DESC
    LIMIT p_limit
    OFFSET p_offset;
END;
$$;


--
-- Name: get_raw_visit_data_v4(uuid, integer, text, boolean, uuid[], uuid[], uuid[], boolean, boolean, timestamp with time zone, timestamp with time zone, integer, integer, text[], text[], text[], uuid, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_raw_visit_data_v4(p_organization_id uuid, p_last_hours integer, p_timezone text DEFAULT 'UTC'::text, p_is_premium boolean DEFAULT false, p_tp_ids uuid[] DEFAULT NULL::uuid[], p_tag_ids uuid[] DEFAULT NULL::uuid[], p_collection_ids uuid[] DEFAULT NULL::uuid[], p_include_null_collection boolean DEFAULT false, p_exclude_bot boolean DEFAULT false, p_start_time timestamp with time zone DEFAULT NULL::timestamp with time zone, p_end_time timestamp with time zone DEFAULT NULL::timestamp with time zone, p_limit integer DEFAULT NULL::integer, p_offset integer DEFAULT 0, p_utm_source_values text[] DEFAULT NULL::text[], p_utm_medium_values text[] DEFAULT NULL::text[], p_utm_campaign_values text[] DEFAULT NULL::text[], p_user_id uuid DEFAULT NULL::uuid, p_interaction_types text[] DEFAULT NULL::text[]) RETURNS TABLE(touchpoint_id uuid, touchpoint_name text, os text, platform text, channel text, country text, city text, ip text, isp text, referrer text, created_at timestamp with time zone, id uuid, total_count bigint, visitor_id character varying, customer_profile_id uuid, customer_name text, customer_email text, customer_external_id text)
    LANGUAGE plpgsql
    AS $$
DECLARE
    end_local timestamp;
    start_local timestamp;
    filtered_tp_ids uuid[];
    has_collection_filter boolean;
BEGIN
    end_local := coalesce(
        p_end_time at time zone p_timezone,
        now() at time zone p_timezone
    );

    start_local := coalesce(
        p_start_time at time zone p_timezone,
        end_local - make_interval(hours => p_last_hours)
    );

    has_collection_filter := false;

    IF p_collection_ids IS NOT NULL THEN
        has_collection_filter := true;

        SELECT array_agg(DISTINCT touch_points.id) INTO filtered_tp_ids
        FROM touch_points
        WHERE touch_points.organization_id = p_organization_id
          AND touch_points.deleted_at IS NULL
          AND (
              collection_id = ANY(p_collection_ids)
              OR (p_include_null_collection = true AND collection_id IS NULL AND user_id = p_user_id)
          )
          AND (p_tp_ids IS NULL OR p_tp_ids = '{}' OR touch_points.id = ANY(p_tp_ids));

        p_tp_ids := COALESCE(filtered_tp_ids, ARRAY[]::uuid[]);
    END IF;

    RETURN QUERY
    WITH filtered AS (
        SELECT
            v.tp_id,
            coalesce(tp.name, 'Touch point has been deleted') as touchpoint_name,
            v.os,
            v.platform,
            v.type as channel,
            v.country,
            v.referrer,
            v.city,
            v.ip::text as ip,
            v.isp,
            v.created_at,
            v.id,
            v.li2_cid,
            v.fp
        FROM public.visits v
        LEFT JOIN public.touch_points tp
            ON tp.id = v.tp_id
            AND tp.deleted_at IS NULL
        WHERE v.organization_id = p_organization_id
          AND v.created_at >= (start_local at time zone p_timezone)
          AND v.created_at <  (end_local at time zone p_timezone)
          AND (
              CASE
                  WHEN has_collection_filter THEN v.tp_id = ANY(p_tp_ids)
                  ELSE (p_tp_ids IS NULL OR p_tp_ids = '{}' OR v.tp_id = ANY(p_tp_ids))
              END
          )
          AND (
              p_tag_ids IS NULL
              OR p_tag_ids = '{}'
              OR EXISTS (
                  SELECT 1 FROM public.tp_tag_links tl
                  WHERE tl.tp_id = v.tp_id
                    AND tl.tag_id = ANY(p_tag_ids)
              )
          )
          AND (NOT p_exclude_bot OR v.is_bot = FALSE)
          AND (p_interaction_types IS NULL OR p_interaction_types = '{}' OR v.type = ANY(p_interaction_types))
          AND (p_utm_source_values IS NULL OR p_utm_source_values = '{}' OR v.utm_tags->>'utm_source' = ANY(p_utm_source_values))
          AND (p_utm_medium_values IS NULL OR p_utm_medium_values = '{}' OR v.utm_tags->>'utm_medium' = ANY(p_utm_medium_values))
          AND (p_utm_campaign_values IS NULL OR p_utm_campaign_values = '{}' OR v.utm_tags->>'utm_campaign' = ANY(p_utm_campaign_values))
    ),
    total AS (
        SELECT count(*) as total_count FROM filtered
    )
    SELECT
        f.tp_id as touchpoint_id,
        f.touchpoint_name,
        f.os,
        f.platform,
        f.channel,
        f.country,
        f.city,
        f.ip,
        f.isp,
        f.referrer,
        f.created_at,
        f.id,
        t.total_count,
        COALESCE(
            s.visitor_id,
            CASE WHEN f.fp IS NOT NULL
                THEN ('vis_' || left(encode(sha256((f.fp || ':' || p_organization_id::text)::bytea), 'hex'), 16))::character varying
            END
        ) as visitor_id,
        ce.customer_profile_id,
        cp.name as customer_name,
        cp.email as customer_email,
        cp.external_id as customer_external_id
    FROM filtered f
    CROSS JOIN total t
    LEFT JOIN LATERAL (
        SELECT s.visitor_id
        FROM public.sessions s
        WHERE s.li2_cid = f.li2_cid
          AND s.organization_id = p_organization_id
        LIMIT 1
    ) s ON true
    LEFT JOIN LATERAL (
        SELECT ce.customer_profile_id
        FROM public.conversion_events ce
        WHERE ce.visitor_id = s.visitor_id
        ORDER BY ce.created_at ASC
        LIMIT 1
    ) ce ON true
    LEFT JOIN public.customer_profiles cp ON cp.id = ce.customer_profile_id
    ORDER BY f.created_at DESC
    LIMIT p_limit
    OFFSET p_offset;
END;
$$;


--
-- Name: get_realtime_data(uuid, integer, text, boolean, uuid[], boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_realtime_data(p_organization_id uuid, p_last_hours integer, p_timezone text DEFAULT 'UTC'::text, p_is_premium boolean DEFAULT false, p_collection_ids uuid[] DEFAULT NULL::uuid[], p_include_null_collection boolean DEFAULT true) RETURNS TABLE(touchpoint_id uuid, touchpoint_name text, os text, platform text, channel text, country text, city text, ip text, isp text, referrer text, created_at timestamp with time zone, id uuid)
    LANGUAGE plpgsql
    AS $$
declare
  end_local   timestamp;
  start_local timestamp;
  has_collection_filter boolean;
begin
  end_local   := now() at time zone p_timezone;
  start_local := end_local - make_interval(hours => p_last_hours);

  -- Check if collection filtering is needed
  has_collection_filter := p_collection_ids IS NOT NULL AND array_length(p_collection_ids, 1) > 0;

  return query
  with filtered as (
    select
      v.tp_id,
      coalesce(tp.name, 'Touch point has been deleted') as touchpoint_name,
      v.os,
      v.platform,
      v.type      as channel,
      v.country,
      v.referrer,
      v.city,
      v.ip::text  as ip,          -- cast inet -> text
      v.isp,
      v.created_at,
      v.id
    from public.visits v
    left join public.touch_points tp
      on tp.id = v.tp_id
     and tp.deleted_at is null
    where v.organization_id = p_organization_id
      and v.created_at >= (start_local at time zone p_timezone)
      and v.created_at <  (end_local   at time zone p_timezone)
      -- NEW: Apply collection filtering
      and (
        NOT has_collection_filter
        OR tp.collection_id = ANY(p_collection_ids)
        OR (p_include_null_collection = true AND tp.collection_id IS NULL)
      )
  )
  select
    f.tp_id               as touchpoint_id,
    f.touchpoint_name,
    f.os,
    f.platform,
    f.channel,
    f.country,
    f.city,
    f.ip,
    f.isp,
    f.referrer,
    f.created_at,
    f.id
  from filtered f
  order by f.created_at desc;
end;
$$;


