CREATE FUNCTION public.get_realtime_data_v4(p_organization_id uuid, p_last_hours integer, p_timezone text DEFAULT 'UTC'::text, p_is_premium boolean DEFAULT false, p_collection_ids uuid[] DEFAULT NULL::uuid[], p_include_null_collection boolean DEFAULT true, p_user_id uuid DEFAULT NULL::uuid, p_exclude_bot boolean DEFAULT true) RETURNS TABLE(touchpoint_id uuid, touchpoint_name text, os text, platform text, channel text, country text, city text, ip text, isp text, referrer text, created_at timestamp with time zone, id uuid, visitor_id character varying, customer_profile_id uuid, customer_name text, customer_email text, customer_external_id text)
    LANGUAGE plpgsql
    AS $$
DECLARE
  end_local   timestamp;
  start_local timestamp;
  has_collection_filter boolean;
BEGIN
  end_local   := now() at time zone p_timezone;
  start_local := end_local - make_interval(hours => p_last_hours);

  has_collection_filter := p_collection_ids IS NOT NULL;

  RETURN QUERY
  WITH filtered AS (
    SELECT
      v.tp_id,
      coalesce(tp.name, 'Touch point has been deleted') AS touchpoint_name,
      v.os,
      v.platform,
      v.type      AS channel,
      v.country,
      v.referrer,
      v.city,
      v.ip::text  AS ip,
      v.isp,
      v.created_at,
      v.id,
      v.li2_cid,
      v.fp
    FROM public.visits v
    LEFT JOIN public.touch_points tp
      ON tp.id = v.tp_id
     AND tp.deleted_at IS NULL
    WHERE v.organization_id = p_organization_id
      AND v.created_at >= (start_local AT TIME ZONE p_timezone)
      AND v.created_at <  (end_local   AT TIME ZONE p_timezone)
      AND (
        NOT has_collection_filter
        OR tp.collection_id = ANY(p_collection_ids)
        OR (p_include_null_collection = true AND tp.collection_id IS NULL AND tp.user_id = p_user_id)
      )
      AND (NOT p_exclude_bot OR v.is_bot = FALSE)
  )
  SELECT
    f.tp_id               AS touchpoint_id,
    f.touchpoint_name,
    f.os,
    f.platform,
    f.channel,
    f.country,
    f.city,
    f.ip,
    f.isp,
    f.referrer,
    f.created_at,
    f.id,
    COALESCE(
      s.visitor_id,
      CASE WHEN f.fp IS NOT NULL
        THEN ('vis_' || left(encode(sha256((f.fp || ':' || p_organization_id::text)::bytea), 'hex'), 16))::character varying
      END
    ) AS visitor_id,
    ce.customer_profile_id,
    cp.name          AS customer_name,
    cp.email         AS customer_email,
    cp.external_id   AS customer_external_id
  FROM filtered f
  LEFT JOIN LATERAL (
    SELECT s.visitor_id
    FROM public.sessions s
    WHERE s.li2_cid = f.li2_cid
      AND s.organization_id = p_organization_id
    LIMIT 1
  ) s ON true
  LEFT JOIN LATERAL (
    SELECT ce.customer_profile_id
    FROM public.conversion_events ce
    WHERE ce.visitor_id = s.visitor_id
    ORDER BY ce.created_at ASC
    LIMIT 1
  ) ce ON true
  LEFT JOIN public.customer_profiles cp ON cp.id = ce.customer_profile_id
  ORDER BY f.created_at DESC;
END;
$$;


--
-- Name: get_realtime_summary(uuid, integer, text, boolean, uuid[], boolean, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_realtime_summary(p_organization_id uuid, p_last_hours integer DEFAULT 24, p_timezone text DEFAULT 'UTC'::text, p_exclude_bot boolean DEFAULT true, p_collection_ids uuid[] DEFAULT NULL::uuid[], p_include_null_collection boolean DEFAULT true, p_user_id uuid DEFAULT NULL::uuid) RETURNS TABLE(active_visitors_5min bigint, clicks_1hr bigint, clicks_24hr bigint, clicks_prev_24hr bigint, top_channel text)
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
  has_collection_filter boolean;
  now_utc timestamptz;
BEGIN
  now_utc := now();
  has_collection_filter := p_collection_ids IS NOT NULL;

  RETURN QUERY
  SELECT
    -- Unique IPs in last 5 minutes as proxy for "active visitors"
    COUNT(DISTINCT v.ip) FILTER (
      WHERE v.created_at >= now_utc - interval '5 minutes'
    ) AS active_visitors_5min,

    -- Clicks in last 1 hour
    COUNT(*) FILTER (
      WHERE v.created_at >= now_utc - interval '1 hour'
    ) AS clicks_1hr,

    -- Clicks in last 24 hours
    COUNT(*) FILTER (
      WHERE v.created_at >= now_utc - interval '24 hours'
    ) AS clicks_24hr,

    -- Clicks in the previous 24-hour window (24h-48h ago) for trend comparison
    COUNT(*) FILTER (
      WHERE v.created_at >= now_utc - interval '48 hours'
        AND v.created_at < now_utc - interval '24 hours'
    ) AS clicks_prev_24hr,

    -- Most common channel in last 24 hours (aligned with the 24h engagements card)
    (
      SELECT v2.type
      FROM public.visits v2
      LEFT JOIN public.touch_points tp2
        ON tp2.id = v2.tp_id
       AND tp2.deleted_at IS NULL
      WHERE v2.organization_id = p_organization_id
        AND v2.created_at >= now_utc - interval '24 hours'
        AND (NOT p_exclude_bot OR v2.is_bot = FALSE)
        AND (
          NOT has_collection_filter
          OR tp2.collection_id = ANY(p_collection_ids)
          OR (p_include_null_collection = true AND tp2.collection_id IS NULL AND tp2.user_id = p_user_id)
        )
      GROUP BY v2.type
      ORDER BY COUNT(*) DESC
      LIMIT 1
    ) AS top_channel

  FROM public.visits v
  LEFT JOIN public.touch_points tp
    ON tp.id = v.tp_id
   AND tp.deleted_at IS NULL
  WHERE v.organization_id = p_organization_id
    AND v.created_at >= now_utc - interval '48 hours'
    AND (NOT p_exclude_bot OR v.is_bot = FALSE)
    AND (
      NOT has_collection_filter
      OR tp.collection_id = ANY(p_collection_ids)
      OR (p_include_null_collection = true AND tp.collection_id IS NULL AND tp.user_id = p_user_id)
    );
END;
$$;


--
-- Name: FUNCTION get_realtime_summary(p_organization_id uuid, p_last_hours integer, p_timezone text, p_exclude_bot boolean, p_collection_ids uuid[], p_include_null_collection boolean, p_user_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_realtime_summary(p_organization_id uuid, p_last_hours integer, p_timezone text, p_exclude_bot boolean, p_collection_ids uuid[], p_include_null_collection boolean, p_user_id uuid) IS 'Aggregated real-time summary for dashboard hero metrics bar.
Returns active visitors (5min), click counts (1hr/24hr), previous 24hr for trend, and top channel (24hr).
Uses same collection filtering + bot exclusion pattern as get_realtime_data_v3.';


--
-- Name: get_realtime_top_links(uuid, integer, text, boolean, uuid[], boolean, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_realtime_top_links(p_organization_id uuid, p_last_hours integer DEFAULT 24, p_timezone text DEFAULT 'UTC'::text, p_exclude_bot boolean DEFAULT true, p_collection_ids uuid[] DEFAULT NULL::uuid[], p_include_null_collection boolean DEFAULT true, p_user_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 5) RETURNS TABLE(touchpoint_id uuid, touchpoint_name text, short_url text, click_count bigint, qr_count bigint, link_count bigint, nfc_count bigint)
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
  end_local   timestamp;
  start_local timestamp;
  has_collection_filter boolean;
BEGIN
  end_local   := now() AT TIME ZONE p_timezone;
  start_local := end_local - make_interval(hours => p_last_hours);

  has_collection_filter := p_collection_ids IS NOT NULL;

  RETURN QUERY
  SELECT
    tp.id AS touchpoint_id,
    COALESCE(tp.name, 'Deleted touch point') AS touchpoint_name,
    tp.short_url,
    COUNT(*)                                    AS click_count,
    COUNT(*) FILTER (WHERE v.type = 'QR')       AS qr_count,
    COUNT(*) FILTER (WHERE v.type = 'LINK')     AS link_count,
    COUNT(*) FILTER (WHERE v.type = 'NFC')      AS nfc_count
  FROM public.visits v
  LEFT JOIN public.touch_points tp
    ON tp.id = v.tp_id
   AND tp.deleted_at IS NULL
  WHERE v.organization_id = p_organization_id
    AND v.created_at >= (start_local AT TIME ZONE p_timezone)
    AND v.created_at <  (end_local   AT TIME ZONE p_timezone)
    -- Bot filtering
    AND (NOT p_exclude_bot OR v.is_bot = FALSE)
    -- Collection filtering
    AND (
      NOT has_collection_filter
      OR tp.collection_id = ANY(p_collection_ids)
      OR (p_include_null_collection = true AND tp.collection_id IS NULL AND tp.user_id = p_user_id)
    )
  GROUP BY tp.id, tp.name, tp.short_url
  ORDER BY click_count DESC
  LIMIT p_limit;
END;
$$;


--
-- Name: FUNCTION get_realtime_top_links(p_organization_id uuid, p_last_hours integer, p_timezone text, p_exclude_bot boolean, p_collection_ids uuid[], p_include_null_collection boolean, p_user_id uuid, p_limit integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_realtime_top_links(p_organization_id uuid, p_last_hours integer, p_timezone text, p_exclude_bot boolean, p_collection_ids uuid[], p_include_null_collection boolean, p_user_id uuid, p_limit integer) IS 'Top N links by click count within a time window, with per-channel breakdown (QR/LINK/NFC).
Uses same collection filtering + bot exclusion pattern as get_realtime_data_v3.';


--
-- Name: get_scroll_heatmap(uuid, text, timestamp with time zone, timestamp with time zone, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_scroll_heatmap(p_organization_id uuid, p_page_path text DEFAULT NULL::text, p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_device_type text DEFAULT NULL::text, p_hostname text DEFAULT NULL::text) RETURNS TABLE(scroll_depth_percent smallint, sessions_reached bigint, avg_time_at_depth numeric)
    LANGUAGE sql STABLE
    AS $$
  SELECT
    i.scroll_depth_percent,
    COUNT(DISTINCT i.session_id)              AS sessions_reached,
    ROUND(AVG(i.time_at_depth)::numeric, 0)  AS avg_time_at_depth
  FROM interactions i
  WHERE i.organization_id  = p_organization_id
    AND (p_page_path IS NULL OR i.page_path = p_page_path)
    AND i.interaction_type = 'scroll'
    AND i.timestamp        >= p_from
    AND i.timestamp        < (p_to::date + interval '1 day')
    AND i.is_bot           = false
    AND (p_device_type IS NULL OR i.device_type = p_device_type)
    AND (p_hostname IS NULL OR i.page_url LIKE '%' || p_hostname || '%')
    AND i.scroll_depth_percent IS NOT NULL
  GROUP BY i.scroll_depth_percent
  ORDER BY i.scroll_depth_percent;
$$;


--
-- Name: get_scroll_heatmap_v2(uuid, text, timestamp with time zone, timestamp with time zone, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_scroll_heatmap_v2(p_organization_id uuid, p_page_path text DEFAULT NULL::text, p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_device_type text DEFAULT NULL::text, p_hostname text DEFAULT NULL::text) RETURNS TABLE(scroll_depth_percent smallint, sessions_reached bigint, avg_time_at_depth numeric, total_sessions bigint)
    LANGUAGE sql STABLE
    AS $$
  WITH base AS (
    SELECT
      i.scroll_depth_percent,
      i.session_id,
      i.time_at_depth
    FROM interactions i
    WHERE i.organization_id  = p_organization_id
      AND (p_page_path IS NULL OR i.page_path = p_page_path)
      AND i.interaction_type = 'scroll'
      AND i.timestamp        >= p_from
      AND i.timestamp        < (p_to::date + interval '1 day')
      AND i.is_bot           = false
      AND (p_device_type IS NULL OR i.device_type = p_device_type)
      AND (p_hostname IS NULL OR i.page_url LIKE '%' || p_hostname || '%')
      AND i.scroll_depth_percent IS NOT NULL
  ),
  totals AS (
    SELECT COUNT(DISTINCT session_id) AS total_sessions FROM base
  )
  SELECT
    b.scroll_depth_percent,
    COUNT(DISTINCT b.session_id)             AS sessions_reached,
    ROUND(AVG(b.time_at_depth)::numeric, 0) AS avg_time_at_depth,
    t.total_sessions
  FROM base b, totals t
  GROUP BY b.scroll_depth_percent, t.total_sessions
  ORDER BY b.scroll_depth_percent;
$$;


--
-- Name: get_session_analytics(uuid, date, date, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_session_analytics(_org_id uuid, _from date, _to date, _hostname text DEFAULT NULL::text, _page_path text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
  _result jsonb;
BEGIN
  WITH filtered_sessions AS (
    SELECT DISTINCT ON (s.session_id)
      s.session_id,
      s.visitor_id,
      s.device_type,
      s.browser,
      s.os,
      s.country,
      s.referrer_domain,
      s.utm_source,
      s.channel,
      s.started_at
    FROM sessions s
    INNER JOIN pageviews pv
      ON  pv.session_id      = s.session_id
      AND pv.organization_id = s.organization_id
      AND pv.timestamp       >= _from::timestamptz
      AND pv.timestamp       <  _to::timestamptz + interval '1 day'
    WHERE s.organization_id = _org_id
      AND s.started_at::date BETWEEN _from AND _to
      AND s.is_bot  = false
      AND pv.is_bot = false
      AND (
        _hostname IS NULL
        OR regexp_replace(pv.page_url, '^https?://([^/]+).*', '\1') = _hostname
      )
      AND (
        _page_path IS NULL
        OR pv.page_path = _page_path
      )
  ),
  by_date AS (
    SELECT
      started_at::date                    AS date,
      count(*)::int                       AS sessions,
      count(DISTINCT visitor_id)::int     AS visitors
    FROM filtered_sessions
    GROUP BY 1
    ORDER BY 1
  ),
  by_device AS (
    SELECT COALESCE(device_type, 'Unknown') AS device_type, count(*)::int AS count
    FROM filtered_sessions
    GROUP BY 1
    ORDER BY 2 DESC
    LIMIT 10
  ),
  by_browser AS (
    SELECT COALESCE(browser, 'Unknown') AS browser, count(*)::int AS count
    FROM filtered_sessions
    GROUP BY 1
    ORDER BY 2 DESC
    LIMIT 10
  ),
  by_os AS (
    SELECT COALESCE(os, 'Unknown') AS os, count(*)::int AS count
    FROM filtered_sessions
    GROUP BY 1
    ORDER BY 2 DESC
    LIMIT 10
  ),
  by_country AS (
    SELECT COALESCE(NULLIF(country, ''), 'Unknown') AS country, count(*)::int AS count
    FROM filtered_sessions
    GROUP BY 1
    ORDER BY 2 DESC
    LIMIT 20
  ),
  by_referrer AS (
    SELECT COALESCE(NULLIF(referrer_domain, ''), 'Direct') AS referrer_domain, count(*)::int AS count
    FROM filtered_sessions
    GROUP BY 1
    ORDER BY 2 DESC
    LIMIT 20
  ),
  by_utm_source AS (
    SELECT utm_source, count(*)::int AS count
    FROM filtered_sessions
    WHERE utm_source IS NOT NULL AND utm_source <> ''
    GROUP BY 1
    ORDER BY 2 DESC
    LIMIT 20
  ),
  by_channel AS (
    SELECT COALESCE(NULLIF(channel, ''), 'Unassigned') AS channel, count(*)::int AS count
    FROM filtered_sessions
    GROUP BY 1
    ORDER BY 2 DESC
    LIMIT 20
  )
  SELECT jsonb_build_object(
    'by_date',        COALESCE((SELECT jsonb_agg(row_to_json(t)) FROM by_date       t), '[]'::jsonb),
    'by_device',      COALESCE((SELECT jsonb_agg(row_to_json(t)) FROM by_device     t), '[]'::jsonb),
    'by_browser',     COALESCE((SELECT jsonb_agg(row_to_json(t)) FROM by_browser    t), '[]'::jsonb),
    'by_os',          COALESCE((SELECT jsonb_agg(row_to_json(t)) FROM by_os         t), '[]'::jsonb),
    'by_country',     COALESCE((SELECT jsonb_agg(row_to_json(t)) FROM by_country    t), '[]'::jsonb),
    'by_referrer',    COALESCE((SELECT jsonb_agg(row_to_json(t)) FROM by_referrer   t), '[]'::jsonb),
    'by_utm_source',  COALESCE((SELECT jsonb_agg(row_to_json(t)) FROM by_utm_source t), '[]'::jsonb),
    'by_channel',     COALESCE((SELECT jsonb_agg(row_to_json(t)) FROM by_channel    t), '[]'::jsonb)
  ) INTO _result;

  RETURN _result;
END;
$$;


--
-- Name: get_site_page_sessions(uuid, timestamp with time zone, timestamp with time zone, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_site_page_sessions(_org_id uuid, _from timestamp with time zone, _to timestamp with time zone, _limit integer DEFAULT 500) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    AS $$
BEGIN
  RETURN coalesce(
    (SELECT jsonb_agg(row_to_json(p))
     FROM (
       SELECT
         scheme,
         hostname,
         page_path,
         count(DISTINCT session_id)  AS total_sessions,
         count(DISTINCT visitor_id)  AS unique_visitors,
         round(
           count(DISTINCT session_id) FILTER (WHERE is_bounce = true)::numeric
           / nullif(count(DISTINCT session_id), 0) * 100,
           1
         )                           AS bounce_rate,
         round(
           avg(duration_ms) FILTER (WHERE duration_ms > 0) / 1000.0,
           1
         )                           AS avg_duration_sec
       FROM (
         SELECT
           regexp_replace(pv.page_url, '^(https?)://.*', '\1')      AS scheme,
           regexp_replace(pv.page_url, '^https?://([^/]+).*', '\1') AS hostname,
           pv.page_path,
           s.id          AS session_id,
           s.visitor_id,
           s.is_bounce,
           s.duration_ms
         FROM pageviews pv
         JOIN sessions s
           ON s.session_id = pv.session_id
          AND s.organization_id = pv.organization_id
         WHERE pv.organization_id = _org_id
           AND pv.timestamp >= _from AND pv.timestamp < _to + interval '1 day'
           AND pv.is_bot  = false
           AND s.is_bot   = false
           AND pv.page_url IS NOT NULL
       ) raw
       GROUP BY scheme, hostname, page_path
       ORDER BY total_sessions DESC
       LIMIT _limit
     ) p),
    '[]'::jsonb
  );
END;
$$;


--
-- Name: get_statistic(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_statistic(p_key text) RETURNS TABLE(id uuid, analyze_link jsonb, analyze_visit jsonb, created_at timestamp without time zone, updated_at timestamp without time zone)
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN QUERY 
  SELECT s.id, s.analyze_link, s.analyze_visit, s.created_at, s.updated_at
  FROM public.statistics s
  WHERE s.api_key = p_key;
END;
$$;


--
-- Name: get_step_visitors(uuid, uuid, smallint, date, date, text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_step_visitors(_org_id uuid, _funnel_id uuid, _step_position smallint, _period_start date, _period_end date, _filter text DEFAULT 'all'::text, _page integer DEFAULT 1, _limit integer DEFAULT 50) RETURNS TABLE(session_id character varying, visitor_id character varying, reached_step smallint, total_steps smallint, dropped_off boolean, completed boolean, browser character varying, os character varying, device_type character varying, country character varying, city character varying, referrer_domain character varying, started_at timestamp with time zone, total_count bigint)
    LANGUAGE plpgsql STABLE
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        sfr.session_id,
        sfr.visitor_id,
        sfr.reached_step,
        sfr.total_steps,
        sfr.dropped_off,
        sfr.completed,
        s.browser,
        s.os,
        s.device_type,
        s.country,
        s.city,
        s.referrer_domain,
        s.started_at,
        COUNT(*) OVER() AS total_count
    FROM session_funnel_results sfr
    JOIN sessions s ON sfr.session_id = s.session_id
    WHERE sfr.organization_id = _org_id
      AND sfr.funnel_id = _funnel_id
      AND sfr.reached_step >= _step_position
      AND sfr.period_start >= _period_start
      AND sfr.period_end <= _period_end
      AND (
          _filter = 'all'
          OR (_filter = 'proceeded' AND sfr.reached_step > _step_position)
          OR (_filter = 'dropped_off' AND sfr.reached_step = _step_position)
      )
    ORDER BY s.started_at DESC
    LIMIT _limit
    OFFSET (_page - 1) * _limit;
END;
$$;


--
-- Name: get_top_interaction_pages(uuid, timestamp with time zone, timestamp with time zone, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_top_interaction_pages(_org_id uuid, _from timestamp with time zone, _to timestamp with time zone, _limit integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    AS $$
BEGIN
  RETURN coalesce(
    (SELECT jsonb_agg(row_to_json(p))
     FROM (
       SELECT page_path, count(*) AS click_count
       FROM interactions
       WHERE organization_id = _org_id
         AND timestamp BETWEEN _from AND _to
         AND is_bot = false
       GROUP BY page_path
       ORDER BY click_count DESC
       LIMIT _limit
     ) p),
    '[]'::jsonb
  );
END;
$$;


--
-- Name: get_top_interaction_pages(uuid, timestamp with time zone, timestamp with time zone, integer, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_top_interaction_pages(_org_id uuid, _from timestamp with time zone, _to timestamp with time zone, _limit integer DEFAULT 200, _tp_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    AS $$
BEGIN
  RETURN coalesce(
    (SELECT jsonb_agg(row_to_json(p))
     FROM (
       SELECT
         scheme,
         hostname,
         page_path,
         sum(type_count) AS total_count,
         -- kept for heatmap backward compat (PageTreeSidebar sorts by click_count)
         sum(type_count) AS click_count,
         jsonb_agg(
           jsonb_build_object('type', interaction_type, 'count', type_count)
           ORDER BY type_count DESC
         ) AS by_type
       FROM (
         SELECT
           regexp_replace(page_url, '^(https?)://.*', '\1')        AS scheme,
           regexp_replace(page_url, '^https?://([^/]+).*', '\1')   AS hostname,
           page_path,
           interaction_type,
           count(*) AS type_count
         FROM interactions
         WHERE organization_id = _org_id
           AND timestamp >= _from AND timestamp < _to + interval '1 day'
           AND is_bot = false
           AND page_url IS NOT NULL
           AND (_tp_id IS NULL OR session_id IN (
               SELECT DISTINCT session_id FROM pageviews
               WHERE tp_id = _tp_id AND organization_id = _org_id
           ))
         GROUP BY 1, 2, page_path, interaction_type
       ) typed
       GROUP BY scheme, hostname, page_path
       ORDER BY total_count DESC
       LIMIT _limit
     ) p),
    '[]'::jsonb
  );
END;
$$;


--
-- Name: get_total_count(text, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_total_count(table_name text, filter_user_id uuid DEFAULT NULL::uuid, search_column text DEFAULT NULL::text, search_value text DEFAULT NULL::text) RETURNS integer
    LANGUAGE plpgsql
    AS $_$
DECLARE
  total_count int;
BEGIN
  EXECUTE format('
    SELECT COUNT(*)
    FROM %I t
    WHERE ($1 IS NULL OR t.user_id = $1)
    AND ($2 IS NULL OR $3 IS NULL OR t.%I ILIKE $4)',
    table_name,
    CASE WHEN search_column IS NOT NULL THEN search_column ELSE 'user_id' END
  )
  INTO total_count
  USING filter_user_id, search_column, search_value,
        (CASE WHEN search_value IS NOT NULL THEN '%' || search_value || '%' END);

  RETURN total_count;
END;
$_$;


--
-- Name: get_total_list(text, text, text, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_total_list(search_column text DEFAULT NULL::text, search_value text DEFAULT NULL::text, filter_plan text DEFAULT NULL::text, created_from timestamp with time zone DEFAULT NULL::timestamp with time zone, created_to timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS integer
    LANGUAGE plpgsql
    AS $_$
DECLARE
  total_count INT;
BEGIN
  IF search_column IS NOT NULL AND search_value IS NOT NULL THEN
    EXECUTE $sql$
      SELECT COUNT(*)
      FROM profiles m
      LEFT JOIN user_plans up ON up.user_id = m.id
      LEFT JOIN plans p ON p.id = up.plan_id
      WHERE m.$sql$ || quote_ident(search_column) || $sql$ ILIKE $1
        AND ($2 IS NULL OR p.id::text = $2)
        AND ($3 IS NULL OR m.created_at >= $3)
        AND ($4 IS NULL OR m.created_at <= $4)
    $sql$
    INTO total_count
    USING '%' || search_value || '%', filter_plan, created_from, created_to;
  ELSE
    EXECUTE $sql$
      SELECT COUNT(*)
      FROM profiles m
      LEFT JOIN user_plans up ON up.user_id = m.id
      LEFT JOIN plans p ON p.id = up.plan_id
      WHERE ($1 IS NULL OR p.id::text = $1)
        AND ($2 IS NULL OR m.created_at >= $2)
        AND ($3 IS NULL OR m.created_at <= $3)
    $sql$
    INTO total_count
    USING filter_plan, created_from, created_to;
  END IF;

  RETURN total_count;
END;
$_$;


--
-- Name: get_touchpoint_attribution_full(uuid, uuid[], uuid[], uuid[], uuid[], timestamp without time zone, timestamp without time zone, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_touchpoint_attribution_full(_organization_id uuid, _viewable_tp_ids uuid[], _tag_ids uuid[] DEFAULT NULL::uuid[], _tp_ids uuid[] DEFAULT NULL::uuid[], _collection_ids uuid[] DEFAULT NULL::uuid[], _start_time timestamp without time zone DEFAULT NULL::timestamp without time zone, _end_time timestamp without time zone DEFAULT NULL::timestamp without time zone, _exclude_bot boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    result jsonb;
    tp_ids_from_tags uuid[];
    tp_ids_from_collections uuid[];
    final_tp_ids uuid[];
BEGIN
    -- Start with viewable touch points as the base
    final_tp_ids := _viewable_tp_ids;

    -- Apply tp_ids filter if provided
    IF _tp_ids IS NOT NULL AND array_length(_tp_ids, 1) > 0 THEN
        IF final_tp_ids IS NOT NULL THEN
            -- Intersect with viewable
            SELECT array_agg(DISTINCT tp_id)
            INTO final_tp_ids
            FROM unnest(final_tp_ids) AS tp_id
            WHERE tp_id = ANY(_tp_ids);
        ELSE
            final_tp_ids := _tp_ids;
        END IF;
    END IF;

    -- Apply tag_ids filter if provided
    IF _tag_ids IS NOT NULL AND array_length(_tag_ids, 1) > 0 THEN
        SELECT array_agg(DISTINCT tp_id)
        INTO tp_ids_from_tags
        FROM tp_tag_links
        WHERE tag_id = ANY(_tag_ids)
          AND tp_id = ANY(_viewable_tp_ids);

        IF final_tp_ids IS NOT NULL THEN
            -- Intersect with current filter
            SELECT array_agg(DISTINCT tp_id)
            INTO final_tp_ids
            FROM unnest(final_tp_ids) AS tp_id
            WHERE tp_id = ANY(tp_ids_from_tags);
        ELSE
            final_tp_ids := tp_ids_from_tags;
        END IF;
    END IF;

    -- Apply collection_ids filter if provided
    IF _collection_ids IS NOT NULL AND array_length(_collection_ids, 1) > 0 THEN
        SELECT array_agg(DISTINCT id)
        INTO tp_ids_from_collections
        FROM touch_points
        WHERE collection_id = ANY(_collection_ids)
          AND id = ANY(_viewable_tp_ids);

        IF final_tp_ids IS NOT NULL THEN
            -- Intersect with current filter
            SELECT array_agg(DISTINCT tp_id)
            INTO final_tp_ids
            FROM unnest(final_tp_ids) AS tp_id
            WHERE tp_id = ANY(tp_ids_from_collections);
        ELSE
            final_tp_ids := tp_ids_from_collections;
        END IF;
    END IF;

    -- Get touchpoint attribution data
    WITH filtered_visits AS (
        SELECT 
            v.tp_id,
            v.fp,
            v.created_at
        FROM visits v
        WHERE v.organization_id = _organization_id
          AND (final_tp_ids IS NULL OR array_length(final_tp_ids, 1) IS NULL OR v.tp_id = ANY(final_tp_ids))
          AND (_start_time IS NULL OR v.created_at >= _start_time)
          AND (_end_time IS NULL OR v.created_at <= _end_time)
          AND (NOT _exclude_bot OR v.is_bot = FALSE)
    ),
    
    filtered_conversions AS (
        SELECT 
            ce.touch_point_id,
            ce.event_type,
            ce.amount,
            ce.currency
        FROM conversion_events ce
        WHERE ce.organization_id = _organization_id
          AND ce.touch_point_id IS NOT NULL
          AND (final_tp_ids IS NULL OR array_length(final_tp_ids, 1) IS NULL OR ce.touch_point_id = ANY(final_tp_ids))
          AND (_start_time IS NULL OR ce.created_at >= _start_time)
          AND (_end_time IS NULL OR ce.created_at <= _end_time)
    ),
    
    visit_counts AS (
        SELECT 
            tp_id,
            COUNT(*) as visit_count,
            COUNT(DISTINCT fp) FILTER (WHERE fp IS NOT NULL) as unique_visit_count
        FROM filtered_visits
        WHERE tp_id IS NOT NULL
        GROUP BY tp_id
    ),
    
    lead_counts AS (
        SELECT 
            touch_point_id,
            COUNT(*) as lead_count
        FROM filtered_conversions
        WHERE event_type = 'lead'
        GROUP BY touch_point_id
    ),
    
    -- Group sales by touchpoint AND currency to preserve currency info
    sale_by_currency AS (
        SELECT 
            touch_point_id,
            UPPER(COALESCE(currency, 'USD')) as currency,
            COUNT(*) as sale_count,
            SUM(COALESCE(amount, 0)) as revenue
        FROM filtered_conversions
        WHERE event_type = 'sale'
        GROUP BY touch_point_id, UPPER(COALESCE(currency, 'USD'))
    ),
    
    -- Aggregate sales data per touchpoint with currency breakdown
    sale_metrics AS (
        SELECT 
            touch_point_id,
            SUM(sale_count) as sale_count,
            jsonb_object_agg(currency, revenue) as revenue_by_currency
        FROM sale_by_currency
        GROUP BY touch_point_id
    ),
    
    touchpoint_data AS (
        SELECT 
            tp.id as touchpoint_id,
            tp.name as touchpoint_name,
            tp.short_url as touchpoint_short_url,
            COALESCE(vc.visit_count, 0) as visit_count,
            COALESCE(vc.unique_visit_count, 0) as unique_visit_count,
            COALESCE(lc.lead_count, 0) as lead_count,
            COALESCE(sm.sale_count, 0) as sale_count,
            COALESCE(sm.revenue_by_currency, '{}'::jsonb) as revenue_by_currency,
            CASE 
                WHEN COALESCE(lc.lead_count, 0) > 0 
                THEN ROUND((COALESCE(sm.sale_count, 0)::numeric / lc.lead_count::numeric * 100), 1)
                ELSE 0 
            END as conversion_rate
        FROM touch_points tp
        LEFT JOIN visit_counts vc ON tp.id = vc.tp_id
        LEFT JOIN lead_counts lc ON tp.id = lc.touch_point_id
        LEFT JOIN sale_metrics sm ON tp.id = sm.touch_point_id
        WHERE tp.organization_id = _organization_id
          AND (final_tp_ids IS NULL OR array_length(final_tp_ids, 1) IS NULL OR tp.id = ANY(final_tp_ids))
          -- Only include touchpoints with some activity
          AND (
              COALESCE(vc.visit_count, 0) > 0 
              OR COALESCE(lc.lead_count, 0) > 0 
              OR COALESCE(sm.sale_count, 0) > 0
          )
    ),
    
    org_currency AS (
        SELECT default_currency
        FROM organizations
        WHERE id = _organization_id
        LIMIT 1
    )
    
    SELECT jsonb_build_object(
        'touchpoints', (
            SELECT COALESCE(jsonb_agg(
                jsonb_build_object(
                    'touchPointId', touchpoint_id,
                    'touchPointName', touchpoint_name,
                    'touchPointShortUrl', touchpoint_short_url,
                    'visitCount', visit_count,
                    'uniqueVisitCount', unique_visit_count,
                    'leadCount', lead_count,
                    'saleCount', sale_count,
                    'conversionRate', conversion_rate,
                    'revenueByCurrency', revenue_by_currency
                )
                ORDER BY sale_count DESC, lead_count DESC
            ), '[]'::jsonb)
            FROM touchpoint_data
        ),
        'currency', COALESCE((SELECT default_currency FROM org_currency), 'USD')
    )
    INTO result;

    RETURN COALESCE(result, '{}'::jsonb);
END;
$$;


--
-- Name: get_touchpoint_attribution_full_v2(uuid, uuid[], uuid[], uuid[], uuid[], timestamp without time zone, timestamp without time zone, boolean, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_touchpoint_attribution_full_v2(_organization_id uuid, _viewable_tp_ids uuid[], _tag_ids uuid[] DEFAULT NULL::uuid[], _tp_ids uuid[] DEFAULT NULL::uuid[], _collection_ids uuid[] DEFAULT NULL::uuid[], _start_time timestamp without time zone DEFAULT NULL::timestamp without time zone, _end_time timestamp without time zone DEFAULT NULL::timestamp without time zone, _exclude_bot boolean DEFAULT true, _event_names text[] DEFAULT NULL::text[]) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    result jsonb;
    tp_ids_from_tags uuid[];
    tp_ids_from_collections uuid[];
    final_tp_ids uuid[];
BEGIN
    final_tp_ids := _viewable_tp_ids;

    IF _tp_ids IS NOT NULL AND array_length(_tp_ids, 1) > 0 THEN
        IF final_tp_ids IS NOT NULL THEN
            SELECT array_agg(DISTINCT tp_id) INTO final_tp_ids
            FROM unnest(final_tp_ids) AS tp_id WHERE tp_id = ANY(_tp_ids);
        ELSE
            final_tp_ids := _tp_ids;
        END IF;
    END IF;

    IF _tag_ids IS NOT NULL AND array_length(_tag_ids, 1) > 0 THEN
        SELECT array_agg(DISTINCT tp_id) INTO tp_ids_from_tags
        FROM tp_tag_links WHERE tag_id = ANY(_tag_ids) AND tp_id = ANY(_viewable_tp_ids);
        IF final_tp_ids IS NOT NULL THEN
            SELECT array_agg(DISTINCT tp_id) INTO final_tp_ids
            FROM unnest(final_tp_ids) AS tp_id WHERE tp_id = ANY(tp_ids_from_tags);
        ELSE
            final_tp_ids := tp_ids_from_tags;
        END IF;
    END IF;

    IF _collection_ids IS NOT NULL AND array_length(_collection_ids, 1) > 0 THEN
        SELECT array_agg(DISTINCT id) INTO tp_ids_from_collections
        FROM touch_points WHERE collection_id = ANY(_collection_ids) AND id = ANY(_viewable_tp_ids);
        IF final_tp_ids IS NOT NULL THEN
            SELECT array_agg(DISTINCT tp_id) INTO final_tp_ids
            FROM unnest(final_tp_ids) AS tp_id WHERE tp_id = ANY(tp_ids_from_collections);
        ELSE
            final_tp_ids := tp_ids_from_collections;
        END IF;
    END IF;

    WITH filtered_visits AS (
        SELECT v.tp_id, v.fp, v.created_at
        FROM visits v
        WHERE v.organization_id = _organization_id
          AND (final_tp_ids IS NULL OR array_length(final_tp_ids, 1) IS NULL OR v.tp_id = ANY(final_tp_ids))
          AND (_start_time IS NULL OR v.created_at >= _start_time)
          AND (_end_time IS NULL OR v.created_at <= _end_time)
          AND (NOT _exclude_bot OR v.is_bot = FALSE)
    ),
    filtered_conversions AS (
        SELECT ce.touch_point_id, ce.event_type, ce.amount, ce.currency
        FROM conversion_events ce
        WHERE ce.organization_id = _organization_id
          AND ce.touch_point_id IS NOT NULL
          AND (final_tp_ids IS NULL OR array_length(final_tp_ids, 1) IS NULL OR ce.touch_point_id = ANY(final_tp_ids))
          AND (_start_time IS NULL OR ce.created_at >= _start_time)
          AND (_end_time IS NULL OR ce.created_at <= _end_time)
          AND (_event_names IS NULL OR array_length(_event_names, 1) IS NULL OR ce.event_name = ANY(_event_names))
    ),
    visit_counts AS (
        SELECT tp_id,
               COUNT(*) as visit_count,
               COUNT(DISTINCT fp) FILTER (WHERE fp IS NOT NULL) as unique_visit_count
        FROM filtered_visits WHERE tp_id IS NOT NULL GROUP BY tp_id
    ),
    lead_counts AS (
        SELECT touch_point_id, COUNT(*) as lead_count
        FROM filtered_conversions WHERE event_type = 'lead' GROUP BY touch_point_id
    ),
    sale_by_currency AS (
        SELECT touch_point_id,
               UPPER(COALESCE(currency, 'USD')) as currency,
               COUNT(*) as sale_count,
               SUM(COALESCE(amount, 0)) as revenue
        FROM filtered_conversions WHERE event_type = 'sale'
        GROUP BY touch_point_id, UPPER(COALESCE(currency, 'USD'))
    ),
    sale_metrics AS (
        SELECT touch_point_id,
               SUM(sale_count) as sale_count,
               jsonb_object_agg(currency, revenue) as revenue_by_currency
        FROM sale_by_currency GROUP BY touch_point_id
    ),
    touchpoint_data AS (
        SELECT
            tp.id as touchpoint_id,
            tp.name as touchpoint_name,
            tp.short_url as touchpoint_short_url,
            COALESCE(vc.visit_count, 0) as visit_count,
            COALESCE(vc.unique_visit_count, 0) as unique_visit_count,
            COALESCE(lc.lead_count, 0) as lead_count,
            COALESCE(sm.sale_count, 0) as sale_count,
            COALESCE(sm.revenue_by_currency, '{}'::jsonb) as revenue_by_currency,
            CASE
                WHEN COALESCE(lc.lead_count, 0) > 0
                THEN ROUND((COALESCE(sm.sale_count, 0)::numeric / lc.lead_count::numeric * 100), 1)
                ELSE 0
            END as conversion_rate
        FROM touch_points tp
        LEFT JOIN visit_counts vc ON tp.id = vc.tp_id
        LEFT JOIN lead_counts lc ON tp.id = lc.touch_point_id
        LEFT JOIN sale_metrics sm ON tp.id = sm.touch_point_id
        WHERE tp.organization_id = _organization_id
          AND (final_tp_ids IS NULL OR array_length(final_tp_ids, 1) IS NULL OR tp.id = ANY(final_tp_ids))
          AND (
              COALESCE(vc.visit_count, 0) > 0
              OR COALESCE(lc.lead_count, 0) > 0
              OR COALESCE(sm.sale_count, 0) > 0
          )
    ),
    org_currency AS (
        SELECT default_currency FROM organizations WHERE id = _organization_id LIMIT 1
    )
    SELECT jsonb_build_object(
        'touchpoints', (
            SELECT COALESCE(jsonb_agg(
                jsonb_build_object(
                    'touchPointId', touchpoint_id,
                    'touchPointName', touchpoint_name,
                    'touchPointShortUrl', touchpoint_short_url,
                    'visitCount', visit_count,
                    'uniqueVisitCount', unique_visit_count,
                    'leadCount', lead_count,
                    'saleCount', sale_count,
                    'conversionRate', conversion_rate,
                    'revenueByCurrency', revenue_by_currency
                )
                ORDER BY sale_count DESC, lead_count DESC
            ), '[]'::jsonb)
            FROM touchpoint_data
        ),
        'currency', COALESCE((SELECT default_currency FROM org_currency), 'USD')
    ) INTO result;

    RETURN COALESCE(result, '{}'::jsonb);
END;
$$;


--
-- Name: get_touchpoint_attribution_full_v3(uuid, uuid[], uuid[], uuid[], uuid[], timestamp without time zone, timestamp without time zone, boolean, text[], text[], text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_touchpoint_attribution_full_v3(_organization_id uuid, _viewable_tp_ids uuid[], _tag_ids uuid[] DEFAULT NULL::uuid[], _tp_ids uuid[] DEFAULT NULL::uuid[], _collection_ids uuid[] DEFAULT NULL::uuid[], _start_time timestamp without time zone DEFAULT NULL::timestamp without time zone, _end_time timestamp without time zone DEFAULT NULL::timestamp without time zone, _exclude_bot boolean DEFAULT true, _event_names text[] DEFAULT NULL::text[], _utm_sources text[] DEFAULT NULL::text[], _channels text[] DEFAULT NULL::text[]) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    result                  jsonb;
    tp_ids_from_tags        uuid[];
    tp_ids_from_collections uuid[];
    final_tp_ids            uuid[];
    utm_filter_active       boolean;
    matched_click_ids       text[];
    matched_session_ids     text[];
BEGIN
    final_tp_ids := _viewable_tp_ids;

    IF _tp_ids IS NOT NULL AND array_length(_tp_ids, 1) > 0 THEN
        IF final_tp_ids IS NOT NULL THEN
            SELECT array_agg(DISTINCT tp_id) INTO final_tp_ids
            FROM unnest(final_tp_ids) AS tp_id WHERE tp_id = ANY(_tp_ids);
        ELSE
            final_tp_ids := _tp_ids;
        END IF;
    END IF;

    IF _tag_ids IS NOT NULL AND array_length(_tag_ids, 1) > 0 THEN
        SELECT array_agg(DISTINCT tp_id) INTO tp_ids_from_tags
        FROM tp_tag_links WHERE tag_id = ANY(_tag_ids) AND tp_id = ANY(_viewable_tp_ids);
        IF final_tp_ids IS NOT NULL THEN
            SELECT array_agg(DISTINCT tp_id) INTO final_tp_ids
            FROM unnest(final_tp_ids) AS tp_id WHERE tp_id = ANY(tp_ids_from_tags);
        ELSE
            final_tp_ids := tp_ids_from_tags;
        END IF;
    END IF;

    IF _collection_ids IS NOT NULL AND array_length(_collection_ids, 1) > 0 THEN
        SELECT array_agg(DISTINCT id) INTO tp_ids_from_collections
        FROM touch_points WHERE collection_id = ANY(_collection_ids) AND id = ANY(_viewable_tp_ids);
        IF final_tp_ids IS NOT NULL THEN
            SELECT array_agg(DISTINCT tp_id) INTO final_tp_ids
            FROM unnest(final_tp_ids) AS tp_id WHERE tp_id = ANY(tp_ids_from_collections);
        ELSE
            final_tp_ids := tp_ids_from_collections;
        END IF;
    END IF;

    -- ── UTM/channel: resolve once ────────────────────────────────────────────
    utm_filter_active := (
        (_utm_sources IS NOT NULL AND array_length(_utm_sources, 1) > 0)
        OR (_channels  IS NOT NULL AND array_length(_channels,  1) > 0)
    );

    IF utm_filter_active THEN
        SELECT array_agg(DISTINCT li2_cid) INTO matched_click_ids
        FROM visits
        WHERE organization_id = _organization_id
          AND li2_cid IS NOT NULL
          AND (_utm_sources IS NULL OR array_length(_utm_sources, 1) IS NULL OR utm_tags->>'utm_source' = ANY(_utm_sources))
          AND (_channels    IS NULL OR array_length(_channels,    1) IS NULL OR channel                = ANY(_channels));

        SELECT array_agg(DISTINCT session_id) INTO matched_session_ids
        FROM sessions
        WHERE organization_id = _organization_id
          AND session_id IS NOT NULL
          AND (_utm_sources IS NULL OR array_length(_utm_sources, 1) IS NULL OR utm_source = ANY(_utm_sources))
          AND (_channels    IS NULL OR array_length(_channels,    1) IS NULL OR channel    = ANY(_channels));

        IF matched_click_ids   IS NULL THEN matched_click_ids   := '{}'; END IF;
        IF matched_session_ids IS NULL THEN matched_session_ids := '{}'; END IF;
    END IF;

    WITH filtered_visits AS (
        -- Filter visits directly by UTM/channel — visits already has the columns
        SELECT v.tp_id, v.fp, v.created_at
        FROM visits v
        WHERE v.organization_id = _organization_id
          AND (final_tp_ids IS NULL OR array_length(final_tp_ids, 1) IS NULL OR v.tp_id = ANY(final_tp_ids))
          AND (_start_time IS NULL OR v.created_at >= _start_time)
          AND (_end_time   IS NULL OR v.created_at <= _end_time)
          AND (NOT _exclude_bot OR v.is_bot = FALSE)
          AND (
              NOT utm_filter_active
              OR (
                  (_utm_sources IS NULL OR array_length(_utm_sources, 1) IS NULL OR v.utm_tags->>'utm_source' = ANY(_utm_sources))
                  AND (_channels IS NULL OR array_length(_channels, 1) IS NULL OR v.channel = ANY(_channels))
              )
          )
    ),
    filtered_conversions AS (
        -- conversion_events has no UTM columns — use resolved IDs
        SELECT ce.touch_point_id, ce.event_type, ce.amount, ce.currency
        FROM conversion_events ce
        WHERE ce.organization_id = _organization_id
          AND ce.touch_point_id IS NOT NULL
          AND (final_tp_ids IS NULL OR array_length(final_tp_ids, 1) IS NULL OR ce.touch_point_id = ANY(final_tp_ids))
          AND (_start_time IS NULL OR ce.created_at >= _start_time)
          AND (_end_time   IS NULL OR ce.created_at <= _end_time)
          AND (_event_names IS NULL OR array_length(_event_names, 1) IS NULL OR ce.event_name = ANY(_event_names))
          AND (
              NOT utm_filter_active
              OR ce.click_id   = ANY(matched_click_ids)
              OR ce.session_id = ANY(matched_session_ids)
          )
    ),
    visit_counts AS (
        SELECT tp_id,
               COUNT(*) as visit_count,
               COUNT(DISTINCT fp) FILTER (WHERE fp IS NOT NULL) as unique_visit_count
        FROM filtered_visits WHERE tp_id IS NOT NULL GROUP BY tp_id
    ),
    lead_counts AS (
        SELECT touch_point_id, COUNT(*) as lead_count
        FROM filtered_conversions WHERE event_type = 'lead' GROUP BY touch_point_id
    ),
    sale_by_currency AS (
        SELECT touch_point_id,
               UPPER(COALESCE(currency, 'USD')) as currency,
               COUNT(*) as sale_count,
               SUM(COALESCE(amount, 0)) as revenue
        FROM filtered_conversions WHERE event_type = 'sale'
        GROUP BY touch_point_id, UPPER(COALESCE(currency, 'USD'))
    ),
    sale_metrics AS (
        SELECT touch_point_id,
               SUM(sale_count) as sale_count,
               jsonb_object_agg(currency, revenue) as revenue_by_currency
        FROM sale_by_currency GROUP BY touch_point_id
    ),
    touchpoint_data AS (
        SELECT
            tp.id as touchpoint_id,
            tp.name as touchpoint_name,
            tp.short_url as touchpoint_short_url,
            COALESCE(vc.visit_count, 0) as visit_count,
            COALESCE(vc.unique_visit_count, 0) as unique_visit_count,
            COALESCE(lc.lead_count, 0) as lead_count,
            COALESCE(sm.sale_count, 0) as sale_count,
            COALESCE(sm.revenue_by_currency, '{}'::jsonb) as revenue_by_currency,
            CASE
                WHEN COALESCE(lc.lead_count, 0) > 0
                THEN ROUND((COALESCE(sm.sale_count, 0)::numeric / lc.lead_count::numeric * 100), 1)
                ELSE 0
            END as conversion_rate
        FROM touch_points tp
        LEFT JOIN visit_counts vc ON tp.id = vc.tp_id
        LEFT JOIN lead_counts lc ON tp.id = lc.touch_point_id
        LEFT JOIN sale_metrics sm ON tp.id = sm.touch_point_id
        WHERE tp.organization_id = _organization_id
          AND (final_tp_ids IS NULL OR array_length(final_tp_ids, 1) IS NULL OR tp.id = ANY(final_tp_ids))
          AND (
              COALESCE(vc.visit_count, 0) > 0
              OR COALESCE(lc.lead_count, 0) > 0
              OR COALESCE(sm.sale_count, 0) > 0
          )
    ),
    org_currency AS (
        SELECT default_currency FROM organizations WHERE id = _organization_id LIMIT 1
    )
    SELECT jsonb_build_object(
        'touchpoints', (
            SELECT COALESCE(jsonb_agg(
                jsonb_build_object(
                    'touchPointId',       touchpoint_id,
                    'touchPointName',     touchpoint_name,
                    'touchPointShortUrl', touchpoint_short_url,
                    'visitCount',         visit_count,
                    'uniqueVisitCount',   unique_visit_count,
                    'leadCount',          lead_count,
                    'saleCount',          sale_count,
                    'conversionRate',     conversion_rate,
                    'revenueByCurrency',  revenue_by_currency
                )
                ORDER BY sale_count DESC, lead_count DESC
            ), '[]'::jsonb)
            FROM touchpoint_data
        ),
        'currency', COALESCE((SELECT default_currency FROM org_currency), 'USD')
    ) INTO result;

    RETURN COALESCE(result, '{}'::jsonb);
END;
$$;


--
-- Name: get_touchpoint_summary(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_touchpoint_summary(p_campaign_id uuid) RETURNS TABLE(type text, count bigint)
    LANGUAGE plpgsql
    AS $$
begin
  return query
  select tp.type, count(*) as count
  from touch_points tp
  where tp.campaign_id = p_campaign_id
  group by tp.type;

  return query
  select 'TOTAL', count(*)
  from touch_points tp
  where tp.campaign_id = p_campaign_id;
end;
$$;


--
-- Name: get_tp_analytic(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_tp_analytic(tp_id uuid) RETURNS TABLE(date date, total integer, os jsonb[], platform jsonb[], type jsonb[], unique_visit jsonb[])
    LANGUAGE sql
    AS $$
  WITH base AS (
    SELECT
      DATE(created_at) AS date,
      os,
      platform,
      type,
      fp
    FROM visits
    WHERE tp_id = get_tp_analytic.tp_id
  ),
  agg_data AS (
    SELECT
      date,
      os,
      platform,
      type,
      fp,
      COUNT(*) OVER (PARTITION BY date, os) AS os_count,
      COUNT(*) OVER (PARTITION BY date, platform) AS platform_count,
      COUNT(*) OVER (PARTITION BY date, type) AS type_count
    FROM base
  ),
  fp_visits AS (
    SELECT
      date,
      fp,
      COUNT(*) AS visit
    FROM base
    GROUP BY date, fp
  )
  SELECT
    a.date,
    COUNT(*) AS total,
    ARRAY_AGG(DISTINCT jsonb_build_object('os', a.os, 'count', a.os_count)) AS os,
    ARRAY_AGG(DISTINCT jsonb_build_object('platform', a.platform, 'count', a.platform_count)) AS platform,
    ARRAY_AGG(DISTINCT jsonb_build_object('type', a.type, 'count', a.type_count)) AS type,
    ARRAY_AGG(DISTINCT jsonb_build_object('fp', f.fp, 'visit', f.visit)) AS unique_visit
  FROM agg_data a
  LEFT JOIN fp_visits f ON a.date = f.date AND a.fp = f.fp
  GROUP BY a.date
  ORDER BY a.date ASC;
$$;


--
-- Name: get_tp_details(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_tp_details(tp_ids uuid[]) RETURNS TABLE(tp_id uuid, total_tag integer)
    LANGUAGE sql
    AS $$
  SELECT 
    t.tp_id,
    COALESCE(COUNT(ttl.tag_id), 0)::INTEGER AS total_tag
  FROM 
    unnest(tp_ids) AS t(tp_id)
  LEFT JOIN 
    tp_tag_links ttl ON t.tp_id = ttl.tp_id
  GROUP BY 
    t.tp_id;
$$;


--
-- Name: get_utm_campaign_analytics(uuid, uuid, uuid[], uuid[], timestamp with time zone, timestamp with time zone, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_utm_campaign_analytics(_organization_id uuid, _utm_campaign_id uuid, _channel_ids uuid[] DEFAULT NULL::uuid[], _tp_ids uuid[] DEFAULT NULL::uuid[], _start_time timestamp with time zone DEFAULT NULL::timestamp with time zone, _end_time timestamp with time zone DEFAULT NULL::timestamp with time zone, _exclude_bot boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
  result jsonb;
BEGIN
  WITH filtered_visits AS (
    SELECT *
    FROM visits
    WHERE
      organization_id = _organization_id           -- required org
      AND utm_campaign_id = _utm_campaign_id       -- required UTM campaign
      AND (
        _channel_ids IS NULL 
        OR array_length(_channel_ids, 1) IS NULL
        OR utm_channel_id = ANY(_channel_ids)
      )
      AND (
        _tp_ids IS NULL
        OR array_length(_tp_ids, 1) IS NULL
        OR tp_id = ANY(_tp_ids)
      )
      AND (_start_time IS NULL OR created_at >= _start_time)
      AND (_end_time   IS NULL OR created_at <= _end_time)
      AND (NOT _exclude_bot OR is_bot = FALSE)
  ),

  -- channel grouping
  channel_counts AS (
    SELECT
      utm_channel_id,
      COUNT(*)            AS total_visits,
      COUNT(DISTINCT fp)  AS unique_visits
    FROM filtered_visits
    GROUP BY utm_channel_id
    ORDER BY total_visits DESC
  ),

  -- touchpoint grouping
  touchpoint_counts AS (
    SELECT
      tp_id,
      COALESCE(content_value, 'unknown') AS label,
      COUNT(*)            AS total_visits,
      COUNT(DISTINCT fp)  AS unique_visits
    FROM filtered_visits
    GROUP BY tp_id, COALESCE(content_value, 'unknown')
    ORDER BY total_visits DESC
  ),

  -- daily aggregation
  daily_counts AS (
    SELECT
      DATE(created_at)   AS visit_date,
      COUNT(*)           AS total_visits,
      COUNT(DISTINCT fp) AS unique_visits
    FROM filtered_visits
    GROUP BY DATE(created_at)
    ORDER BY visit_date
  ),

  -- channel daily aggregation (NEW)
  channel_daily_counts AS (
    SELECT
      COALESCE(v.utm_channel_id, ucc.channel_id) AS utm_channel_id,
      DATE(v.created_at)   AS visit_date,
      COUNT(*)           AS total_visits,
      COUNT(DISTINCT v.fp) AS unique_visits
    FROM filtered_visits v
    LEFT JOIN utm_campaign_channels ucc 
      ON ucc.campaign_id = _utm_campaign_id
      AND (_channel_ids IS NULL OR array_length(_channel_ids, 1) IS NULL OR ucc.channel_id = ANY(_channel_ids))
    WHERE v.utm_channel_id IS NOT NULL OR ucc.channel_id IS NOT NULL
    GROUP BY COALESCE(v.utm_channel_id, ucc.channel_id), DATE(v.created_at)
    ORDER BY utm_channel_id, visit_date
  ),

  -- referrer / os / platform
  referrer_counts AS (
    SELECT COALESCE(referrer, 'unknown') AS referrer, COUNT(*) AS count
    FROM filtered_visits
    GROUP BY 1 ORDER BY count DESC
  ),
  os_counts AS (
    SELECT COALESCE(os, 'unknown') AS os, COUNT(*) AS count
    FROM filtered_visits
    GROUP BY 1 ORDER BY count DESC
  ),
  platform_counts AS (
    SELECT COALESCE(platform, 'unknown') AS platform, COUNT(*) AS count
    FROM filtered_visits
    GROUP BY 1 ORDER BY count DESC
  )

  SELECT jsonb_build_object(
    'utmCampaignId', _utm_campaign_id,
    'totalVisits', (SELECT COUNT(*) FROM filtered_visits),
    'totalUniqueVisits', (SELECT COUNT(DISTINCT fp) FROM filtered_visits WHERE fp IS NOT NULL),

    'channels', (
      SELECT COALESCE(jsonb_agg(
        jsonb_build_object(
          'id', utm_channel_id,
          'totalVisits', total_visits,
          'totalUniqueVisits', unique_visits
        )
        ORDER BY total_visits DESC
      ), '[]'::jsonb)
      FROM channel_counts
    ),

    'touchpoints', (
      SELECT COALESCE(jsonb_agg(
        jsonb_build_object(
          'id', tp_id,
          'label', label,
          'totalVisits', total_visits,
          'totalUniqueVisits', unique_visits
        )
        ORDER BY total_visits DESC
      ), '[]'::jsonb)
      FROM touchpoint_counts
    ),

    'daily', (
      SELECT COALESCE(jsonb_agg(
        jsonb_build_object(
          'date', to_char(visit_date, 'YYYY-MM-DD'),
          'totalVisits', total_visits,
          'totalUniqueVisits', unique_visits
        )
        ORDER BY visit_date
      ), '[]'::jsonb)
      FROM daily_counts
    ),

    'channelDaily', (
      SELECT COALESCE(jsonb_agg(
        jsonb_build_object(
          'channelId', utm_channel_id,
          'date', to_char(visit_date, 'YYYY-MM-DD'),
          'totalVisits', total_visits,
          'totalUniqueVisits', unique_visits
        )
        ORDER BY utm_channel_id, visit_date
      ), '[]'::jsonb)
      FROM channel_daily_counts
    ),

    'referrers', (
      SELECT COALESCE(jsonb_agg(
        jsonb_build_object('name', referrer, 'count', count)
        ORDER BY count DESC
      ), '[]'::jsonb)
      FROM referrer_counts
    ),

    'os', (
      SELECT COALESCE(jsonb_agg(
        jsonb_build_object('name', os, 'count', count)
        ORDER BY count DESC
      ), '[]'::jsonb)
      FROM os_counts
    ),

    'platforms', (
      SELECT COALESCE(jsonb_agg(
        jsonb_build_object('name', platform, 'count', count)
        ORDER BY count DESC
      ), '[]'::jsonb)
      FROM platform_counts
    )
  )
  INTO result;

  RETURN COALESCE(result, '{}'::jsonb);
END;
$$;


--
-- Name: get_visits_analytics(uuid, uuid[], uuid[], uuid[], uuid[], boolean, timestamp without time zone, timestamp without time zone, boolean, text[], text[], text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_visits_analytics(_organization_id uuid, _campaign_ids uuid[] DEFAULT NULL::uuid[], _tp_ids uuid[] DEFAULT NULL::uuid[], _tag_ids uuid[] DEFAULT NULL::uuid[], _collection_ids uuid[] DEFAULT NULL::uuid[], _include_null_collection boolean DEFAULT false, _start_time timestamp without time zone DEFAULT NULL::timestamp without time zone, _end_time timestamp without time zone DEFAULT NULL::timestamp without time zone, _exclude_bot boolean DEFAULT false, _utm_source_values text[] DEFAULT NULL::text[], _utm_medium_values text[] DEFAULT NULL::text[], _utm_campaign_values text[] DEFAULT NULL::text[]) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$DECLARE
    result JSONB;
    tp_ids_from_tags UUID[];
    filtered_tp_ids UUID[];
BEGIN
    -- If tag_ids are provided, get all touch points linked to those tags
    IF _tag_ids IS NOT NULL AND array_length(_tag_ids, 1) > 0 THEN
        SELECT array_agg(DISTINCT tp_id) INTO tp_ids_from_tags
        FROM tp_tag_links
        WHERE tag_id = ANY(_tag_ids);

        -- Combine with explicitly provided tp_ids if any
        IF _tp_ids IS NOT NULL AND array_length(_tp_ids, 1) > 0 THEN
            _tp_ids := _tp_ids || tp_ids_from_tags;
        ELSE
            _tp_ids := tp_ids_from_tags;
        END IF;
    END IF;

    -- Apply collection filtering to tp_ids
    IF _collection_ids IS NOT NULL AND array_length(_collection_ids, 1) > 0 THEN
        SELECT array_agg(DISTINCT touch_points.id) INTO filtered_tp_ids
        FROM touch_points
        WHERE (
            collection_id = ANY(_collection_ids)
            OR (
                _include_null_collection = true
                AND collection_id IS NULL
            )
        )
        AND (_tp_ids IS NULL OR array_length(_tp_ids, 1) IS NULL OR touch_points.id = ANY(_tp_ids));

        _tp_ids := filtered_tp_ids;
    END IF;

    WITH filtered_visits AS (
        SELECT *
        FROM visits
        WHERE
            organization_id = _organization_id
            AND (_campaign_ids IS NULL OR array_length(_campaign_ids, 1) IS NULL OR campaign_id = ANY(_campaign_ids))
            AND (_tp_ids IS NULL OR array_length(_tp_ids, 1) IS NULL OR tp_id = ANY(_tp_ids))
            AND (_start_time IS NULL OR created_at >= _start_time)
            AND (_end_time IS NULL OR created_at <= _end_time)
            AND (NOT _exclude_bot OR is_bot = FALSE)
            -- UTM filters
            AND (_utm_source_values IS NULL OR array_length(_utm_source_values, 1) IS NULL OR utm_tags->>'utm_source' = ANY(_utm_source_values))
            AND (_utm_medium_values IS NULL OR array_length(_utm_medium_values, 1) IS NULL OR utm_tags->>'utm_medium' = ANY(_utm_medium_values))
            AND (_utm_campaign_values IS NULL OR array_length(_utm_campaign_values, 1) IS NULL OR utm_tags->>'utm_campaign' = ANY(_utm_campaign_values))
    ),
    -- Group by referrer
    referrer_counts AS (
        SELECT
            COALESCE(referrer, 'unknown') AS referrer,
            COUNT(*) AS count
        FROM filtered_visits
        GROUP BY referrer
        ORDER BY count DESC
    ),
    -- Group by type
    type_counts AS (
        SELECT
            COALESCE(type, 'unknown') AS type,
            COUNT(*) AS count
        FROM filtered_visits
        GROUP BY type
        ORDER BY count DESC
    ),
    -- Group by OS
    os_counts AS (
        SELECT
            COALESCE(os, 'unknown') AS os,
            COUNT(*) AS count
        FROM filtered_visits
        GROUP BY os
        ORDER BY count DESC
    ),
    -- Group by platform
    platform_counts AS (
        SELECT
            COALESCE(platform, 'unknown') AS platform,
            COUNT(*) AS count
        FROM filtered_visits
        GROUP BY platform
        ORDER BY count DESC
    ),
    -- Group by country
    country_counts AS (
        SELECT
            COALESCE(country, 'unknown') AS country,
            COUNT(*) AS count
        FROM filtered_visits
        GROUP BY country
        ORDER BY count DESC
    ),
    -- Group by country and city
    country_city_counts AS (
        SELECT
            COALESCE(country, 'unknown') AS country,
            COALESCE(city, 'unknown') AS city,
            COUNT(*) AS count
        FROM filtered_visits
        GROUP BY country, city
        ORDER BY country, count DESC
    ),
    -- Format country and city data
    countries_formatted AS (
        SELECT
            cc.country,
            cnt.count AS total_count,
            (
                SELECT jsonb_agg(
                    jsonb_build_object(
                        'city', city,
                        'count', count
                    )
                )
                FROM country_city_counts cc2
                WHERE cc2.country = cc.country
            ) AS cities
        FROM country_counts cnt
        JOIN country_city_counts cc ON cnt.country = cc.country
        GROUP BY cc.country, cnt.count
        ORDER BY cnt.count DESC
    ),
    -- Get top 3 days with most visits
    top_dates AS (
        SELECT
            DATE(created_at) AS visit_date,
            COUNT(*) AS count
        FROM filtered_visits
        GROUP BY DATE(created_at)
        ORDER BY count DESC
        LIMIT 3
    )

    SELECT jsonb_build_object(
        'referrers', (SELECT jsonb_agg(jsonb_build_object('name', referrer, 'count', count)) FROM referrer_counts),
        'types', (SELECT jsonb_agg(jsonb_build_object('name', type, 'count', count)) FROM type_counts),
        'os', (SELECT jsonb_agg(jsonb_build_object('name', os, 'count', count)) FROM os_counts),
        'platforms', (SELECT jsonb_agg(jsonb_build_object('name', platform, 'count', count)) FROM platform_counts),
        'countries', (SELECT jsonb_agg(
                          jsonb_build_object(
                              'name', country,
                              'count', total_count,
                              'cities', cities
                          )
                      ) FROM countries_formatted),
        'topPerformingDates', (SELECT jsonb_agg(
                                  jsonb_build_object(
                                      'name', to_char(visit_date, 'YYYY-MM-DD'),
                                      'count', count
                                  )
                              ) FROM top_dates),
        'totalVisits', (SELECT COUNT(*) FROM filtered_visits)        
    ) INTO result;

    RETURN COALESCE(result, '{}'::jsonb);
END;$$;


--
-- Name: get_visits_analytics_old(uuid, uuid[], uuid[], uuid[], timestamp with time zone, timestamp with time zone, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_visits_analytics_old(_organization_id uuid, _campaign_ids uuid[] DEFAULT NULL::uuid[], _tp_ids uuid[] DEFAULT NULL::uuid[], _tag_ids uuid[] DEFAULT NULL::uuid[], _start_time timestamp with time zone DEFAULT NULL::timestamp with time zone, _end_time timestamp with time zone DEFAULT NULL::timestamp with time zone, _exclude_bot boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$DECLARE
    result JSONB;
    tp_ids_from_tags UUID[];
BEGIN
    -- If tag_ids are provided, get all touch points linked to those tags
    IF _tag_ids IS NOT NULL AND array_length(_tag_ids, 1) > 0 THEN
        SELECT array_agg(DISTINCT tp_id) INTO tp_ids_from_tags
        FROM tp_tag_links
        WHERE tag_id = ANY(_tag_ids);

        -- Combine with explicitly provided tp_ids if any
        IF _tp_ids IS NOT NULL AND array_length(_tp_ids, 1) > 0 THEN
            _tp_ids := _tp_ids || tp_ids_from_tags;
        ELSE
            _tp_ids := tp_ids_from_tags;
        END IF;
    END IF;

    WITH filtered_visits AS (
        SELECT *
        FROM visits
        WHERE
            organization_id = _organization_id
            AND (_campaign_ids IS NULL OR array_length(_campaign_ids, 1) IS NULL OR campaign_id = ANY(_campaign_ids))
            AND (_tp_ids IS NULL OR array_length(_tp_ids, 1) IS NULL OR tp_id = ANY(_tp_ids))
            AND (_start_time IS NULL OR created_at >= _start_time)
            AND (_end_time IS NULL OR created_at <= _end_time)
            AND (NOT _exclude_bot OR is_bot = FALSE)  -- NEW: Filter out bots when _exclude_bot is true
    ),
    -- Group by referrer
    referrer_counts AS (
        SELECT
            COALESCE(referrer, 'unknown') AS referrer,
            COUNT(*) AS count
        FROM filtered_visits
        GROUP BY referrer
        ORDER BY count DESC
    ),
    -- Group by type
    type_counts AS (
        SELECT
            COALESCE(type, 'unknown') AS type,
            COUNT(*) AS count
        FROM filtered_visits
        GROUP BY type
        ORDER BY count DESC
    ),
    -- Group by OS
    os_counts AS (
        SELECT
            COALESCE(os, 'unknown') AS os,
            COUNT(*) AS count
        FROM filtered_visits
        GROUP BY os
        ORDER BY count DESC
    ),
    -- Group by platform
    platform_counts AS (
        SELECT
            COALESCE(platform, 'unknown') AS platform,
            COUNT(*) AS count
        FROM filtered_visits
        GROUP BY platform
        ORDER BY count DESC
    ),
    -- Group by country
    country_counts AS (
        SELECT
            COALESCE(country, 'unknown') AS country,
            COUNT(*) AS count
        FROM filtered_visits
        GROUP BY country
        ORDER BY count DESC
    ),
    -- Group by country and city
    country_city_counts AS (
        SELECT
            COALESCE(country, 'unknown') AS country,
            COALESCE(city, 'unknown') AS city,
            COUNT(*) AS count
        FROM filtered_visits
        GROUP BY country, city
        ORDER BY country, count DESC
    ),
    -- Format country and city data
    countries_formatted AS (
        SELECT
            cc.country,
            cnt.count AS total_count,
            (
                SELECT jsonb_agg(
                    jsonb_build_object(
                        'city', city,
                        'count', count
                    )
                )
                FROM country_city_counts cc2
                WHERE cc2.country = cc.country
            ) AS cities
        FROM country_counts cnt
        JOIN country_city_counts cc ON cnt.country = cc.country
        GROUP BY cc.country, cnt.count
        ORDER BY cnt.count DESC
    ),
    -- Get top 3 days with most visits
    top_dates AS (
        SELECT
            DATE(created_at) AS visit_date,
            COUNT(*) AS count
        FROM filtered_visits
        GROUP BY DATE(created_at)
        ORDER BY count DESC
        LIMIT 3
    )

    SELECT jsonb_build_object(
        'referrers', (SELECT jsonb_agg(jsonb_build_object('name', referrer, 'count', count)) FROM referrer_counts),
        'types', (SELECT jsonb_agg(jsonb_build_object('name', type, 'count', count)) FROM type_counts),
        'os', (SELECT jsonb_agg(jsonb_build_object('name', os, 'count', count)) FROM os_counts),
        'platforms', (SELECT jsonb_agg(jsonb_build_object('name', platform, 'count', count)) FROM platform_counts),
        'countries', (SELECT jsonb_agg(
                          jsonb_build_object(
                              'name', country,
                              'count', total_count,
                              'cities', cities
                          )
                      ) FROM countries_formatted),
        'topPerformingDates', (SELECT jsonb_agg(
                                  jsonb_build_object(
                                      'name', to_char(visit_date, 'YYYY-MM-DD'),
                                      'count', count
                                  )
                              ) FROM top_dates),
        'totalVisits', (SELECT COUNT(*) FROM filtered_visits),
        'totalUniqueVisits', (
            SELECT COUNT(DISTINCT fp)
            FROM filtered_visits
            WHERE fp IS NOT NULL
        )
    ) INTO result;

    RETURN COALESCE(result, '{}'::jsonb);
END;$$;


--
-- Name: get_visits_analytics_v4(uuid, uuid[], uuid[], uuid[], uuid[], boolean, timestamp without time zone, timestamp without time zone, boolean, text[], text[], text[], uuid, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_visits_analytics_v4(_organization_id uuid, _campaign_ids uuid[] DEFAULT NULL::uuid[], _tp_ids uuid[] DEFAULT NULL::uuid[], _tag_ids uuid[] DEFAULT NULL::uuid[], _collection_ids uuid[] DEFAULT NULL::uuid[], _include_null_collection boolean DEFAULT false, _start_time timestamp without time zone DEFAULT NULL::timestamp without time zone, _end_time timestamp without time zone DEFAULT NULL::timestamp without time zone, _exclude_bot boolean DEFAULT false, _utm_source_values text[] DEFAULT NULL::text[], _utm_medium_values text[] DEFAULT NULL::text[], _utm_campaign_values text[] DEFAULT NULL::text[], _user_id uuid DEFAULT NULL::uuid, _interaction_types text[] DEFAULT NULL::text[]) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    result jsonb;
    tp_ids_from_tags uuid[];
    filtered_tp_ids uuid[];
    has_collection_filter boolean := false;
BEGIN
    IF _tag_ids IS NOT NULL AND array_length(_tag_ids, 1) > 0 THEN
        SELECT array_agg(DISTINCT tp_id) INTO tp_ids_from_tags
        FROM tp_tag_links
        WHERE tag_id = ANY(_tag_ids);

        IF _tp_ids IS NOT NULL AND array_length(_tp_ids, 1) > 0 THEN
            _tp_ids := _tp_ids || tp_ids_from_tags;
        ELSE
            _tp_ids := tp_ids_from_tags;
        END IF;
    END IF;

    IF _collection_ids IS NOT NULL THEN
        has_collection_filter := true;

        SELECT array_agg(DISTINCT tp.id) INTO filtered_tp_ids
        FROM touch_points tp
        WHERE (
            tp.collection_id = ANY(_collection_ids)
            OR (_include_null_collection = true AND tp.collection_id IS NULL AND tp.user_id = _user_id)
        )
        AND (_tp_ids IS NULL OR array_length(_tp_ids, 1) IS NULL OR tp.id = ANY(_tp_ids));

        _tp_ids := COALESCE(filtered_tp_ids, ARRAY[]::uuid[]);
    END IF;

    WITH filtered_visits AS (
        SELECT *
        FROM visits
        WHERE organization_id = _organization_id
          AND (_campaign_ids IS NULL OR array_length(_campaign_ids, 1) IS NULL OR campaign_id = ANY(_campaign_ids))
          AND (
              CASE
                  WHEN has_collection_filter THEN tp_id = ANY(_tp_ids)
                  ELSE (_tp_ids IS NULL OR array_length(_tp_ids, 1) IS NULL OR tp_id = ANY(_tp_ids))
              END
          )
          AND (_start_time IS NULL OR created_at >= _start_time)
          AND (_end_time IS NULL OR created_at <= _end_time)
          AND (NOT _exclude_bot OR is_bot = FALSE)
          AND (_interaction_types IS NULL OR array_length(_interaction_types, 1) IS NULL OR type = ANY(_interaction_types))
          AND (_utm_source_values IS NULL OR array_length(_utm_source_values, 1) IS NULL OR utm_tags->>'utm_source' = ANY(_utm_source_values))
          AND (_utm_medium_values IS NULL OR array_length(_utm_medium_values, 1) IS NULL OR utm_tags->>'utm_medium' = ANY(_utm_medium_values))
          AND (_utm_campaign_values IS NULL OR array_length(_utm_campaign_values, 1) IS NULL OR utm_tags->>'utm_campaign' = ANY(_utm_campaign_values))
    ),
    referrer_counts AS (
        SELECT COALESCE(referrer, 'unknown') AS referrer, COUNT(*) AS count
        FROM filtered_visits GROUP BY referrer ORDER BY count DESC
    ),
    type_counts AS (
        SELECT COALESCE(type, 'unknown') AS type, COUNT(*) AS count
        FROM filtered_visits GROUP BY type ORDER BY count DESC
    ),
    os_counts AS (
        SELECT COALESCE(os, 'unknown') AS os, COUNT(*) AS count
        FROM filtered_visits GROUP BY os ORDER BY count DESC
    ),
    platform_counts AS (
        SELECT COALESCE(platform, 'unknown') AS platform, COUNT(*) AS count
        FROM filtered_visits GROUP BY platform ORDER BY count DESC
    ),
    country_counts AS (
        SELECT COALESCE(country, 'unknown') AS country, COUNT(*) AS count
        FROM filtered_visits GROUP BY country ORDER BY count DESC
    ),
    country_city_counts AS (
        SELECT COALESCE(country, 'unknown') AS country, COALESCE(city, 'unknown') AS city, COUNT(*) AS count
        FROM filtered_visits GROUP BY country, city ORDER BY country, count DESC
    ),
    countries_formatted AS (
        SELECT
            cc.country,
            cnt.count AS total_count,
            (
                SELECT jsonb_agg(jsonb_build_object('city', city, 'count', count))
                FROM country_city_counts cc2
                WHERE cc2.country = cc.country
            ) AS cities
        FROM country_counts cnt
        JOIN country_city_counts cc ON cnt.country = cc.country
        GROUP BY cc.country, cnt.count
        ORDER BY cnt.count DESC
    ),
    by_date_type AS (
        SELECT DATE(created_at) AS visit_date, COALESCE(type, 'unknown') AS type, COUNT(*) AS count
        FROM filtered_visits
        GROUP BY DATE(created_at), type
    ),
    by_date AS (
        SELECT
            DATE(created_at) AS visit_date,
            COUNT(*) AS total,
            COUNT(DISTINCT fp) FILTER (WHERE fp IS NOT NULL) AS unique_count
        FROM filtered_visits
        GROUP BY DATE(created_at)
    ),
    performance_by_date AS (
        SELECT
            to_char(d.visit_date, 'YYYY-MM-DD') AS day,
            jsonb_build_object(
                'total', d.total,
                'unique', d.unique_count,
                'by_interaction_types', COALESCE(
                    (SELECT jsonb_object_agg(bt.type, bt.count) FROM by_date_type bt WHERE bt.visit_date = d.visit_date),
                    '{}'::jsonb
                )
            ) AS value
        FROM by_date d
        ORDER BY d.visit_date
    )
    SELECT jsonb_build_object(
        'referrers', COALESCE((SELECT jsonb_agg(jsonb_build_object('name', referrer, 'count', count)) FROM referrer_counts), '[]'::jsonb),
        'types', COALESCE((SELECT jsonb_agg(jsonb_build_object('name', type, 'count', count)) FROM type_counts), '[]'::jsonb),
        'os', COALESCE((SELECT jsonb_agg(jsonb_build_object('name', os, 'count', count)) FROM os_counts), '[]'::jsonb),
        'platforms', COALESCE((SELECT jsonb_agg(jsonb_build_object('name', platform, 'count', count)) FROM platform_counts), '[]'::jsonb),
        'countries', COALESCE((SELECT jsonb_agg(jsonb_build_object('name', country, 'count', total_count, 'cities', cities)) FROM countries_formatted), '[]'::jsonb),
        'totalVisits', (SELECT COUNT(*) FROM filtered_visits),
        'totalUniqueVisits', (SELECT COUNT(DISTINCT fp) FROM filtered_visits WHERE fp IS NOT NULL),
        'interaction_types', COALESCE((SELECT jsonb_agg(DISTINCT type) FROM filtered_visits WHERE type IS NOT NULL), '[]'::jsonb),
        'performance_by_date', COALESCE((SELECT jsonb_object_agg(day, value) FROM performance_by_date), '{}'::jsonb)
    ) INTO result;

    RETURN COALESCE(result, '{}'::jsonb);
END;
$$;


--
-- Name: get_visits_by_country_and_city(uuid, uuid[], uuid[], uuid[], timestamp without time zone, timestamp without time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_visits_by_country_and_city(_organization_id uuid, _campaign_ids uuid[] DEFAULT NULL::uuid[], _tp_ids uuid[] DEFAULT NULL::uuid[], _tag_ids uuid[] DEFAULT NULL::uuid[], _start_time timestamp without time zone DEFAULT NULL::timestamp without time zone, _end_time timestamp without time zone DEFAULT NULL::timestamp without time zone) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    result JSONB;
    tp_ids_from_tags UUID[];
BEGIN
    -- If tag_ids are provided, get all touch points linked to those tags
    IF _tag_ids IS NOT NULL AND array_length(_tag_ids, 1) > 0 THEN
        SELECT array_agg(DISTINCT tp_id) INTO tp_ids_from_tags
        FROM tp_tag_links
        WHERE tag_id = ANY(_tag_ids);
        
        -- Combine with explicitly provided tp_ids if any
        IF _tp_ids IS NOT NULL AND array_length(_tp_ids, 1) > 0 THEN
            _tp_ids := _tp_ids || tp_ids_from_tags;
        ELSE
            _tp_ids := tp_ids_from_tags;
        END IF;
    END IF;

    WITH filtered_visits AS (
        SELECT *
        FROM visits
        WHERE 
            organization_id = _organization_id
            AND (_campaign_ids IS NULL OR array_length(_campaign_ids, 1) IS NULL OR campaign_id = ANY(_campaign_ids))
            AND (_tp_ids IS NULL OR array_length(_tp_ids, 1) IS NULL OR tp_id = ANY(_tp_ids))
            AND (_start_time IS NULL OR created_at >= _start_time)
            AND (_end_time IS NULL OR created_at <= _end_time)
    ),
    country_counts AS (
        SELECT 
            country, 
            COUNT(*) AS visit_count
        FROM filtered_visits
        GROUP BY country
    ),
    city_counts AS (
        SELECT 
            country,
            city,
            COUNT(*) AS visit_count
        FROM filtered_visits
        GROUP BY country, city
    ),
    formatted_data AS (
        SELECT
            cc.country,
            cc.visit_count,
            (
                SELECT jsonb_agg(
                    jsonb_build_object(
                        'city', cic.city,
                        'visitCount', cic.visit_count
                    )
                )
                FROM city_counts cic
                WHERE cic.country = cc.country
            ) AS cities
        FROM country_counts cc
    )
    SELECT jsonb_agg(
        jsonb_build_object(
            'country', country,
            'visitCount', visit_count,
            'cities', cities
        )
    ) INTO result
    FROM formatted_data;

    RETURN COALESCE(result, '[]'::jsonb);
END;
$$;


--
-- Name: get_visits_by_destinations_v2(uuid, uuid, timestamp with time zone, timestamp with time zone, text, boolean, uuid[], boolean, text[], text[], text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_visits_by_destinations_v2(p_tp_id uuid, p_org_id uuid, p_start_time timestamp with time zone DEFAULT NULL::timestamp with time zone, p_end_time timestamp with time zone DEFAULT NULL::timestamp with time zone, p_timezone text DEFAULT 'UTC'::text, p_exclude_bot boolean DEFAULT false, p_collection_ids uuid[] DEFAULT NULL::uuid[], p_include_null_collection boolean DEFAULT false, p_utm_source_values text[] DEFAULT NULL::text[], p_utm_medium_values text[] DEFAULT NULL::text[], p_utm_campaign_values text[] DEFAULT NULL::text[]) RETURNS TABLE(destination text, segment_type text, total_visits bigint, unique_visits bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE
    tp_allowed boolean;
BEGIN
    -- Check if the touch-point passes collection filtering
    -- If collection_ids is NULL or empty, allow all touch-points (no filtering)
    IF p_collection_ids IS NULL OR array_length(p_collection_ids, 1) IS NULL THEN
        tp_allowed := true;
    ELSE
        -- Check if the touch-point is in an allowed collection or is uncategorized
        SELECT EXISTS (
            SELECT 1
            FROM touch_points tp
            WHERE tp.id = p_tp_id
            AND (
                tp.collection_id = ANY(p_collection_ids)
                OR (
                    p_include_null_collection = true
                    AND tp.collection_id IS NULL
                )
            )
        ) INTO tp_allowed;
    END IF;

    -- If touch-point is not allowed, return empty result
    IF NOT tp_allowed THEN
        RETURN;
    END IF;

    -- Return visit data for allowed touch-point
    RETURN QUERY
    SELECT
        v.content_value AS destination,
        v.segment_type AS segment_type,
        COUNT(v.fp) AS total_visits,
        COUNT(DISTINCT v.fp) AS unique_visits
    FROM public.visits v
    WHERE v.organization_id = p_org_id
        AND v.tp_id = p_tp_id
        AND (p_start_time IS NULL OR v.created_at >= p_start_time)
        AND (p_end_time IS NULL OR v.created_at <= p_end_time)
        AND (NOT p_exclude_bot OR v.is_bot = FALSE)
        -- UTM filters
        AND (p_utm_source_values IS NULL OR p_utm_source_values = '{}' OR v.utm_tags->>'utm_source' = ANY(p_utm_source_values))
        AND (p_utm_medium_values IS NULL OR p_utm_medium_values = '{}' OR v.utm_tags->>'utm_medium' = ANY(p_utm_medium_values))
        AND (p_utm_campaign_values IS NULL OR p_utm_campaign_values = '{}' OR v.utm_tags->>'utm_campaign' = ANY(p_utm_campaign_values))
    GROUP BY v.content_value, v.segment_type
    ORDER BY total_visits DESC;
END;
$$;


--
-- Name: get_visits_by_destinations_v2_old(uuid, uuid, timestamp with time zone, timestamp with time zone, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_visits_by_destinations_v2_old(p_tp_id uuid, p_org_id uuid, p_start_time timestamp with time zone DEFAULT NULL::timestamp with time zone, p_end_time timestamp with time zone DEFAULT NULL::timestamp with time zone, p_timezone text DEFAULT 'UTC'::text, p_exclude_bot boolean DEFAULT false) RETURNS TABLE(destination text, segment_type text, total_visits bigint, unique_visits bigint)
    LANGUAGE plpgsql
    AS $$BEGIN
  RETURN QUERY
  SELECT 
    v.content_value AS destination,
    v.segment_type AS segment_type,
    COUNT(v.fp) AS total_visits,
    COUNT(DISTINCT v.fp) AS unique_visits
  FROM public.visits v
  WHERE v.organization_id = p_org_id
    AND v.tp_id = p_tp_id
    AND (p_start_time IS NULL OR v.created_at >= p_start_time)
    AND (p_end_time IS NULL OR v.created_at <= p_end_time)
    AND (NOT p_exclude_bot OR v.is_bot = FALSE)
  GROUP BY v.content_value, v.segment_type
  ORDER BY total_visits DESC;
END;$$;


--
-- Name: get_visits_geo_breakdown(uuid, uuid[], uuid[], uuid[], boolean, timestamp without time zone, timestamp without time zone, boolean, uuid, text[], text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_visits_geo_breakdown(_organization_id uuid, _tp_ids uuid[] DEFAULT NULL::uuid[], _tag_ids uuid[] DEFAULT NULL::uuid[], _collection_ids uuid[] DEFAULT NULL::uuid[], _include_null_collection boolean DEFAULT false, _start_time timestamp without time zone DEFAULT NULL::timestamp without time zone, _end_time timestamp without time zone DEFAULT NULL::timestamp without time zone, _exclude_bot boolean DEFAULT false, _user_id uuid DEFAULT NULL::uuid, _interaction_types text[] DEFAULT NULL::text[], _country text DEFAULT NULL::text) RETURNS TABLE(country text, region text, city text, region_iso text, count bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE
    tp_ids_from_tags uuid[];
    filtered_tp_ids uuid[];
    has_collection_filter boolean := false;
BEGIN
    IF _tag_ids IS NOT NULL AND array_length(_tag_ids, 1) > 0 THEN
        SELECT array_agg(DISTINCT tp_id) INTO tp_ids_from_tags
        FROM tp_tag_links
        WHERE tag_id = ANY(_tag_ids);

        IF _tp_ids IS NOT NULL AND array_length(_tp_ids, 1) > 0 THEN
            _tp_ids := _tp_ids || tp_ids_from_tags;
        ELSE
            _tp_ids := tp_ids_from_tags;
        END IF;
    END IF;

    IF _collection_ids IS NOT NULL THEN
        has_collection_filter := true;

        SELECT array_agg(DISTINCT tp.id) INTO filtered_tp_ids
        FROM touch_points tp
        WHERE (
            tp.collection_id = ANY(_collection_ids)
            OR (_include_null_collection = true AND tp.collection_id IS NULL AND tp.user_id = _user_id)
        )
        AND (_tp_ids IS NULL OR array_length(_tp_ids, 1) IS NULL OR tp.id = ANY(_tp_ids));

        _tp_ids := COALESCE(filtered_tp_ids, ARRAY[]::uuid[]);
    END IF;

    RETURN QUERY
    SELECT
        v.country,
        v.region,
        v.city,
        v.region_iso,
        COUNT(*) AS count
    FROM visits v
    WHERE v.organization_id = _organization_id
      AND (
          CASE
              WHEN has_collection_filter THEN v.tp_id = ANY(_tp_ids)
              ELSE (_tp_ids IS NULL OR array_length(_tp_ids, 1) IS NULL OR v.tp_id = ANY(_tp_ids))
          END
      )
      AND (_start_time IS NULL OR v.created_at >= _start_time)
      AND (_end_time IS NULL OR v.created_at <= _end_time)
      AND (NOT _exclude_bot OR v.is_bot = FALSE)
      AND (_interaction_types IS NULL OR array_length(_interaction_types, 1) IS NULL OR v.type = ANY(_interaction_types))
      -- Lọc quốc gia ở SQL để cấp vùng không phải kéo cả thế giới về. So không phân biệt chữ hoa
      -- vì cột `country` do GeoIP ghi, chưa có ràng buộc nào bắt nó hoa.
      AND (_country IS NULL OR upper(v.country) = upper(_country))
    GROUP BY v.country, v.region, v.city, v.region_iso;
END;
$$;


--
-- Name: get_widget_data_conversions(uuid, text, text, jsonb, timestamp with time zone, timestamp with time zone, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_widget_data_conversions(_organization_id uuid, _metric text, _group_by text, _filters jsonb DEFAULT '[]'::jsonb, _date_from timestamp with time zone DEFAULT (now() - '7 days'::interval), _date_to timestamp with time zone DEFAULT now(), _limit integer DEFAULT 50, _target_currency text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $_$
DECLARE
  _result JSONB;
  _metric_expr TEXT;
  _group_expr TEXT;
  _group_select TEXT;
  _filter_clause TEXT := '';
  _f JSONB;
  _field TEXT;
  _op TEXT;
  _val TEXT;
  _effective_currency TEXT;
  _er_join TEXT := '';
BEGIN
  -- Resolve target currency: param > org default > 'USD' fallback
  IF _target_currency IS NOT NULL THEN
    _effective_currency := _target_currency;
  ELSE
    SELECT default_currency INTO _effective_currency
    FROM organizations WHERE id = _organization_id;
    _effective_currency := COALESCE(_effective_currency, 'USD');
  END IF;

  -- Allowlist: metric
  -- Revenue uses a converted amount expression via exchange_rates CTE (applied in query below)
  CASE _metric
    WHEN 'count' THEN _metric_expr := 'COUNT(*)';
    WHEN 'lead_count' THEN _metric_expr := 'COUNT(*) FILTER (WHERE ce.event_type = ''lead'')';
    WHEN 'sale_count' THEN _metric_expr := 'COUNT(*) FILTER (WHERE ce.event_type = ''sale'')';
    WHEN 'revenue' THEN _metric_expr := 'COALESCE(SUM(
      CASE
        WHEN ce.currency = ' || quote_literal(_effective_currency) || ' THEN ce.amount
        WHEN ce.currency IS NULL THEN ce.amount
        ELSE ce.amount * COALESCE(er.rate, 1)
      END
    ), 0)';
    ELSE RAISE EXCEPTION 'Invalid metric: %', _metric;
  END CASE;

  -- Allowlist: group_by
  CASE _group_by
    WHEN 'day' THEN
      _group_select := 'ce.created_at::date::text';
      _group_expr := 'ce.created_at::date';
    WHEN 'week' THEN
      _group_select := 'date_trunc(''week'', ce.created_at)::date::text';
      _group_expr := 'date_trunc(''week'', ce.created_at)';
    WHEN 'month' THEN
      _group_select := 'date_trunc(''month'', ce.created_at)::date::text';
      _group_expr := 'date_trunc(''month'', ce.created_at)';
    WHEN 'event_type' THEN
      _group_select := 'ce.event_type::text';
      _group_expr := 'ce.event_type';
    WHEN 'event_name' THEN
      _group_select := 'COALESCE(ce.event_name, ''Unknown'')';
      _group_expr := 'COALESCE(ce.event_name, ''Unknown'')';
    WHEN 'touch_point' THEN
      _group_select := 'COALESCE(tp.name, ''(no link)'')';
      _group_expr := 'COALESCE(tp.name, ''(no link)'')';
    WHEN 'referrer' THEN
      _group_select := 'COALESCE(regexp_replace(ce.referrer, ''^https?://([^/]+).*'', ''\1''), ''Direct'')';
      _group_expr := 'COALESCE(regexp_replace(ce.referrer, ''^https?://([^/]+).*'', ''\1''), ''Direct'')';
    WHEN 'utm_source' THEN
      _group_select := 'COALESCE(tp.utm_tags->>''utm_source'', ''(none)'')';
      _group_expr := 'COALESCE(tp.utm_tags->>''utm_source'', ''(none)'')';
    WHEN 'utm_medium' THEN
      _group_select := 'COALESCE(tp.utm_tags->>''utm_medium'', ''(none)'')';
      _group_expr := 'COALESCE(tp.utm_tags->>''utm_medium'', ''(none)'')';
    WHEN 'utm_campaign' THEN
      _group_select := 'COALESCE(tp.utm_tags->>''utm_campaign'', ''(none)'')';
      _group_expr := 'COALESCE(tp.utm_tags->>''utm_campaign'', ''(none)'')';
    WHEN 'none' THEN
      _group_select := NULL;
      _group_expr := NULL;
    ELSE RAISE EXCEPTION 'Invalid group_by: %', _group_by;
  END CASE;

  -- Build filter clause from JSONB array
  IF _filters IS NOT NULL AND jsonb_array_length(_filters) > 0 THEN
    FOR _f IN SELECT * FROM jsonb_array_elements(_filters) LOOP
      _field := _f->>'field';
      _op := _f->>'op';
      _val := _f->>'value';

      -- event_type: explicit value allowlist to prevent enum cast errors
      IF _field = 'event_type' THEN
        IF _val NOT IN ('lead', 'sale') THEN
          RAISE EXCEPTION 'Invalid event_type value: %', _val;
        END IF;
        IF _op = '=' THEN _filter_clause := _filter_clause || format(' AND ce.event_type = %L::conversion_event_type', _val);
        ELSIF _op = '!=' THEN _filter_clause := _filter_clause || format(' AND ce.event_type != %L::conversion_event_type', _val);
        END IF;
        CONTINUE;
      END IF;

      -- UTM fields use JSONB path on touch_points
      IF _field = 'utm_source' THEN
        IF _op = '=' THEN _filter_clause := _filter_clause || format(' AND tp.utm_tags->>''utm_source'' = %L', _val);
        ELSIF _op = '!=' THEN _filter_clause := _filter_clause || format(' AND tp.utm_tags->>''utm_source'' != %L', _val);
        ELSIF _op = 'contains' THEN _filter_clause := _filter_clause || format(' AND tp.utm_tags->>''utm_source'' ILIKE %L', '%' || _val || '%');
        END IF;
        CONTINUE;
      END IF;
      IF _field = 'utm_medium' THEN
        IF _op = '=' THEN _filter_clause := _filter_clause || format(' AND tp.utm_tags->>''utm_medium'' = %L', _val);
        ELSIF _op = '!=' THEN _filter_clause := _filter_clause || format(' AND tp.utm_tags->>''utm_medium'' != %L', _val);
        ELSIF _op = 'contains' THEN _filter_clause := _filter_clause || format(' AND tp.utm_tags->>''utm_medium'' ILIKE %L', '%' || _val || '%');
        END IF;
        CONTINUE;
      END IF;
      IF _field = 'utm_campaign' THEN
        IF _op = '=' THEN _filter_clause := _filter_clause || format(' AND tp.utm_tags->>''utm_campaign'' = %L', _val);
        ELSIF _op = '!=' THEN _filter_clause := _filter_clause || format(' AND tp.utm_tags->>''utm_campaign'' != %L', _val);
        ELSIF _op = 'contains' THEN _filter_clause := _filter_clause || format(' AND tp.utm_tags->>''utm_campaign'' ILIKE %L', '%' || _val || '%');
        END IF;
        CONTINUE;
      END IF;

      -- touch_point filter uses tp_id, not tp.name
      IF _field = 'touch_point_id' THEN
        IF _op = '=' THEN _filter_clause := _filter_clause || format(' AND ce.touch_point_id = %L::uuid', _val);
        ELSIF _op = '!=' THEN _filter_clause := _filter_clause || format(' AND ce.touch_point_id != %L::uuid', _val);
        END IF;
        CONTINUE;
      END IF;

      -- Remaining allowlisted fields (direct column access on ce)
      IF _field NOT IN ('event_name', 'referrer') THEN
        RAISE EXCEPTION 'Invalid filter field: %', _field;
      END IF;
      IF _op NOT IN ('=', '!=', 'contains') THEN
        RAISE EXCEPTION 'Invalid filter operator: %', _op;
      END IF;

      IF _op = '=' THEN
        _filter_clause := _filter_clause || format(' AND ce.%I = %L', _field, _val);
      ELSIF _op = '!=' THEN
        _filter_clause := _filter_clause || format(' AND ce.%I != %L', _field, _val);
      ELSIF _op = 'contains' THEN
        _filter_clause := _filter_clause || format(' AND ce.%I ILIKE %L', _field, '%' || _val || '%');
      END IF;
    END LOOP;
  END IF;

  -- Build exchange_rates JOIN clause (only needed for revenue metric)
  IF _metric = 'revenue' THEN
    _er_join := format(
      'LEFT JOIN LATERAL (
         SELECT rate FROM exchange_rates
         WHERE base_currency = ce.currency AND target_currency = %L
         ORDER BY rate_date DESC LIMIT 1
       ) er ON true',
      _effective_currency
    );
  END IF;

  -- Execute query (ALWAYS LEFT JOIN touch_points; exchange_rates only for revenue)
  IF _group_expr IS NULL THEN
    EXECUTE format(
      'SELECT jsonb_build_object(
         ''total'', COALESCE(%s, 0),
         ''rows'', ''[]''::jsonb
       )
       FROM conversion_events ce
       LEFT JOIN touch_points tp ON ce.touch_point_id = tp.id
       %s
       WHERE ce.organization_id = $1
         AND ce.created_at >= $2 AND ce.created_at < $3
         %s',
      _metric_expr, _er_join, _filter_clause
    ) INTO _result USING _organization_id, _date_from, _date_to;
  ELSE
    EXECUTE format(
      'WITH total_q AS (
         SELECT COALESCE(%s, 0) AS total
         FROM conversion_events ce
         LEFT JOIN touch_points tp ON ce.touch_point_id = tp.id
         %s
         WHERE ce.organization_id = $1 AND ce.created_at >= $2 AND ce.created_at < $3 %s
       ),
       grouped_q AS (
         SELECT %s AS label, %s AS value
         FROM conversion_events ce
         LEFT JOIN touch_points tp ON ce.touch_point_id = tp.id
         %s
         WHERE ce.organization_id = $1 AND ce.created_at >= $2 AND ce.created_at < $3 %s
         GROUP BY %s
         ORDER BY value DESC
         LIMIT $4
       )
       SELECT jsonb_build_object(
         ''total'', (SELECT total FROM total_q),
         ''rows'', COALESCE((SELECT jsonb_agg(jsonb_build_object(''label'', label, ''value'', value)) FROM grouped_q), ''[]''::jsonb)
       )',
      _metric_expr, _er_join, _filter_clause,
      _group_select, _metric_expr,
      _er_join, _filter_clause, _group_expr
    ) INTO _result USING _organization_id, _date_from, _date_to, _limit;
  END IF;

  RETURN COALESCE(_result, '{"total":0,"rows":[]}'::jsonb);
END;
$_$;


--
-- Name: get_widget_data_events(uuid, text, text, jsonb, timestamp with time zone, timestamp with time zone, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_widget_data_events(_organization_id uuid, _metric text, _group_by text, _filters jsonb DEFAULT '[]'::jsonb, _date_from timestamp with time zone DEFAULT (now() - '7 days'::interval), _date_to timestamp with time zone DEFAULT now(), _limit integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $_$
DECLARE
  _result JSONB;
  _metric_expr TEXT;
  _group_expr TEXT;
  _group_select TEXT;
  _filter_clause TEXT := '';
  _f JSONB;
  _field TEXT;
  _op TEXT;
  _val TEXT;
BEGIN
  -- Allowlist: metric
  CASE _metric
    WHEN 'count' THEN _metric_expr := 'COUNT(*)';
    WHEN 'unique_visitors' THEN _metric_expr := 'COUNT(DISTINCT visitor_id)';
    WHEN 'sessions' THEN _metric_expr := 'COUNT(DISTINCT session_id)';
    ELSE RAISE EXCEPTION 'Invalid metric: %', _metric;
  END CASE;

  -- Allowlist: group_by
  CASE _group_by
    WHEN 'day' THEN
      _group_select := 'timestamp::date::text';
      _group_expr := 'timestamp::date';
    WHEN 'week' THEN
      _group_select := 'date_trunc(''week'', timestamp)::date::text';
      _group_expr := 'date_trunc(''week'', timestamp)';
    WHEN 'month' THEN
      _group_select := 'date_trunc(''month'', timestamp)::date::text';
      _group_expr := 'date_trunc(''month'', timestamp)';
    WHEN 'event_name' THEN
      _group_select := 'COALESCE(event_name, ''(unnamed)'')';
      _group_expr := 'COALESCE(event_name, ''(unnamed)'')';
    WHEN 'page_path' THEN
      _group_select := 'COALESCE(page_path, ''/'')';
      _group_expr := 'COALESCE(page_path, ''/'')';
    WHEN 'country' THEN
      _group_select := 'COALESCE(country, ''Unknown'')';
      _group_expr := 'COALESCE(country, ''Unknown'')';
    WHEN 'device' THEN
      _group_select := 'COALESCE(device_type, ''Unknown'')';
      _group_expr := 'COALESCE(device_type, ''Unknown'')';
    WHEN 'referrer' THEN
      _group_select := 'COALESCE(regexp_replace(page_referrer, ''^https?://([^/]+).*'', ''\1''), ''Direct'')';
      _group_expr := 'COALESCE(regexp_replace(page_referrer, ''^https?://([^/]+).*'', ''\1''), ''Direct'')';
    WHEN 'utm_source' THEN
      _group_select := 'COALESCE(utm_source, ''(none)'')';
      _group_expr := 'COALESCE(utm_source, ''(none)'')';
    WHEN 'utm_medium' THEN
      _group_select := 'COALESCE(utm_medium, ''(none)'')';
      _group_expr := 'COALESCE(utm_medium, ''(none)'')';
    WHEN 'utm_campaign' THEN
      _group_select := 'COALESCE(utm_campaign, ''(none)'')';
      _group_expr := 'COALESCE(utm_campaign, ''(none)'')';
    WHEN 'none' THEN
      _group_select := NULL;
      _group_expr := NULL;
    ELSE RAISE EXCEPTION 'Invalid group_by: %', _group_by;
  END CASE;

  -- Build filter clause
  IF _filters IS NOT NULL AND jsonb_array_length(_filters) > 0 THEN
    FOR _f IN SELECT * FROM jsonb_array_elements(_filters) LOOP
      _field := _f->>'field';
      _op := _f->>'op';
      _val := _f->>'value';

      -- Normalize aliases
      IF _field = 'device' THEN _field := 'device_type'; END IF;
      IF _field = 'referrer' THEN _field := 'page_referrer'; END IF;

      -- Allowlist: filter fields (actual DB column names)
      IF _field NOT IN ('event_name', 'event_category', 'page_path', 'page_referrer',
                         'country', 'device_type', 'utm_source', 'utm_medium', 'utm_campaign') THEN
        RAISE EXCEPTION 'Invalid filter field: %', _field;
      END IF;
      IF _op NOT IN ('=', '!=', 'contains') THEN
        RAISE EXCEPTION 'Invalid filter operator: %', _op;
      END IF;

      IF _op = '=' THEN
        _filter_clause := _filter_clause || format(' AND %I = %L', _field, _val);
      ELSIF _op = '!=' THEN
        _filter_clause := _filter_clause || format(' AND %I != %L', _field, _val);
      ELSIF _op = 'contains' THEN
        _filter_clause := _filter_clause || format(' AND %I ILIKE %L', _field, '%' || _val || '%');
      END IF;
    END LOOP;
  END IF;

  -- Execute query
  IF _group_expr IS NULL THEN
    -- KPI mode: single aggregate value
    EXECUTE format(
      'SELECT jsonb_build_object(
         ''total'', COALESCE(%s, 0),
         ''rows'', ''[]''::jsonb
       )
       FROM pageviews
       WHERE organization_id = $1
         AND event_name IS NOT NULL
         AND timestamp >= $2 AND timestamp < $3
         AND is_bot = false
         %s',
      _metric_expr, _filter_clause
    ) INTO _result USING _organization_id, _date_from, _date_to;
  ELSE
    -- Grouped mode: rows with label + value
    EXECUTE format(
      'WITH total_q AS (
         SELECT COALESCE(%s, 0) AS total
         FROM pageviews
         WHERE organization_id = $1
           AND event_name IS NOT NULL
           AND timestamp >= $2 AND timestamp < $3
           AND is_bot = false
           %s
       ),
       grouped_q AS (
         SELECT %s AS label, %s AS value
         FROM pageviews
         WHERE organization_id = $1
           AND event_name IS NOT NULL
           AND timestamp >= $2 AND timestamp < $3
           AND is_bot = false
           %s
         GROUP BY %s
         ORDER BY value DESC
         LIMIT $4
       )
       SELECT jsonb_build_object(
         ''total'', (SELECT total FROM total_q),
         ''rows'', COALESCE((SELECT jsonb_agg(jsonb_build_object(''label'', label, ''value'', value)) FROM grouped_q), ''[]''::jsonb)
       )',
      _metric_expr, _filter_clause,
      _group_select, _metric_expr,
      _filter_clause, _group_expr
    ) INTO _result USING _organization_id, _date_from, _date_to, _limit;
  END IF;

  RETURN COALESCE(_result, '{"total":0,"rows":[]}'::jsonb);
END;
$_$;


--
-- Name: FUNCTION get_widget_data_events(_organization_id uuid, _metric text, _group_by text, _filters jsonb, _date_from timestamp with time zone, _date_to timestamp with time zone, _limit integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_widget_data_events(_organization_id uuid, _metric text, _group_by text, _filters jsonb, _date_from timestamp with time zone, _date_to timestamp with time zone, _limit integer) IS 'Widget data query for custom events (pageviews with event_name). Supports configurable metric, group_by, and filters with allowlisted inputs.';


--
-- Name: get_widget_data_interactions(uuid, text, text, jsonb, timestamp with time zone, timestamp with time zone, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_widget_data_interactions(_organization_id uuid, _metric text, _group_by text, _filters jsonb DEFAULT '[]'::jsonb, _date_from timestamp with time zone DEFAULT (now() - '7 days'::interval), _date_to timestamp with time zone DEFAULT now(), _limit integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $_$
DECLARE
  _result JSONB;
  _metric_expr TEXT;
  _group_expr TEXT;
  _group_select TEXT;
  _filter_clause TEXT := '';
  _f JSONB;
  _field TEXT;
  _op TEXT;
  _val TEXT;
BEGIN
  -- Allowlist: metric
  CASE _metric
    WHEN 'count' THEN _metric_expr := 'COUNT(*)';
    WHEN 'unique_visitors' THEN _metric_expr := 'COUNT(DISTINCT visitor_id)';
    WHEN 'unique_sessions' THEN _metric_expr := 'COUNT(DISTINCT session_id)';
    ELSE RAISE EXCEPTION 'Invalid metric: %', _metric;
  END CASE;

  -- Allowlist: group_by
  -- Uses `timestamp` column (client time) for time-based grouping
  CASE _group_by
    WHEN 'day' THEN
      _group_select := 'timestamp::date::text';
      _group_expr := 'timestamp::date';
    WHEN 'week' THEN
      _group_select := 'date_trunc(''week'', timestamp)::date::text';
      _group_expr := 'date_trunc(''week'', timestamp)';
    WHEN 'month' THEN
      _group_select := 'date_trunc(''month'', timestamp)::date::text';
      _group_expr := 'date_trunc(''month'', timestamp)';
    WHEN 'interaction_type' THEN
      _group_select := 'COALESCE(interaction_type, ''Unknown'')';
      _group_expr := 'COALESCE(interaction_type, ''Unknown'')';
    WHEN 'page_path' THEN
      _group_select := 'COALESCE(page_path, ''Unknown'')';
      _group_expr := 'COALESCE(page_path, ''Unknown'')';
    WHEN 'device_type' THEN
      _group_select := 'COALESCE(device_type, ''Unknown'')';
      _group_expr := 'COALESCE(device_type, ''Unknown'')';
    WHEN 'country' THEN
      _group_select := 'COALESCE(country, ''Unknown'')';
      _group_expr := 'COALESCE(country, ''Unknown'')';
    WHEN 'element_tag' THEN
      _group_select := 'COALESCE(element_tag, ''Unknown'')';
      _group_expr := 'COALESCE(element_tag, ''Unknown'')';
    WHEN 'none' THEN
      _group_select := NULL;
      _group_expr := NULL;
    ELSE RAISE EXCEPTION 'Invalid group_by: %', _group_by;
  END CASE;

  -- Build filter clause from JSONB array
  IF _filters IS NOT NULL AND jsonb_array_length(_filters) > 0 THEN
    FOR _f IN SELECT * FROM jsonb_array_elements(_filters) LOOP
      _field := _f->>'field';
      _op := _f->>'op';
      _val := _f->>'value';

      -- Allowlist: filter fields
      IF _field NOT IN ('interaction_type', 'page_path', 'device_type', 'country', 'element_tag') THEN
        RAISE EXCEPTION 'Invalid filter field: %', _field;
      END IF;
      IF _op NOT IN ('=', '!=', 'contains') THEN
        RAISE EXCEPTION 'Invalid filter operator: %', _op;
      END IF;

      IF _op = '=' THEN
        _filter_clause := _filter_clause || format(' AND %I = %L', _field, _val);
      ELSIF _op = '!=' THEN
        _filter_clause := _filter_clause || format(' AND %I != %L', _field, _val);
      ELSIF _op = 'contains' THEN
        _filter_clause := _filter_clause || format(' AND %I ILIKE %L', _field, '%' || _val || '%');
      END IF;
    END LOOP;
  END IF;

  -- Execute query
  -- DUAL DATE FILTER: created_at for partition pruning + timestamp for semantic correctness
  -- BOT FILTER: COALESCE handles NULL is_bot (in-flight rows before worker enrichment)
  IF _group_expr IS NULL THEN
    -- KPI mode: single aggregate value
    EXECUTE format(
      'SELECT jsonb_build_object(
         ''total'', COALESCE(%s, 0),
         ''rows'', ''[]''::jsonb
       )
       FROM interactions
       WHERE organization_id = $1
         AND created_at >= $2 AND created_at < $3
         AND timestamp >= $2 AND timestamp < $3
         AND COALESCE(is_bot, false) = false
         %s',
      _metric_expr, _filter_clause
    ) INTO _result USING _organization_id, _date_from, _date_to;
  ELSE
    -- Grouped mode: rows with label + value
    EXECUTE format(
      'WITH total_q AS (
         SELECT COALESCE(%s, 0) AS total
         FROM interactions
         WHERE organization_id = $1
           AND created_at >= $2 AND created_at < $3
           AND timestamp >= $2 AND timestamp < $3
           AND COALESCE(is_bot, false) = false
           %s
       ),
       grouped_q AS (
         SELECT %s AS label, %s AS value
         FROM interactions
         WHERE organization_id = $1
           AND created_at >= $2 AND created_at < $3
           AND timestamp >= $2 AND timestamp < $3
           AND COALESCE(is_bot, false) = false
           %s
         GROUP BY %s
         ORDER BY value DESC
         LIMIT $4
       )
       SELECT jsonb_build_object(
         ''total'', (SELECT total FROM total_q),
         ''rows'', COALESCE((SELECT jsonb_agg(jsonb_build_object(''label'', label, ''value'', value)) FROM grouped_q), ''[]''::jsonb)
       )',
      _metric_expr, _filter_clause,
      _group_select, _metric_expr,
      _filter_clause, _group_expr
    ) INTO _result USING _organization_id, _date_from, _date_to, _limit;
  END IF;

  RETURN COALESCE(_result, '{"total":0,"rows":[]}'::jsonb);
END;
$_$;


--
-- Name: get_widget_data_pageviews(uuid, text, text, jsonb, timestamp with time zone, timestamp with time zone, integer, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_widget_data_pageviews(_organization_id uuid, _metric text, _group_by text, _filters jsonb DEFAULT '[]'::jsonb, _date_from timestamp with time zone DEFAULT (now() - '7 days'::interval), _date_to timestamp with time zone DEFAULT now(), _limit integer DEFAULT 50, _exclude_bot boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $_$
DECLARE
  _result JSONB;
  _metric_expr TEXT;
  _group_expr TEXT;
  _group_select TEXT;
  _filter_clause TEXT := '';
  _bot_clause TEXT := '';
  _f JSONB;
  _field TEXT;
  _op TEXT;
  _val TEXT;
BEGIN
  -- Bot filter
  IF _exclude_bot THEN
    _bot_clause := ' AND (is_bot = false)';
  END IF;

  -- Allowlist: metric
  CASE _metric
    WHEN 'count' THEN _metric_expr := 'COUNT(*)';
    WHEN 'unique_visitors' THEN _metric_expr := 'COUNT(DISTINCT visitor_id)';
    WHEN 'sessions' THEN _metric_expr := 'COUNT(DISTINCT session_id)';
    ELSE RAISE EXCEPTION 'Invalid metric: %', _metric;
  END CASE;

  -- Allowlist: group_by
  CASE _group_by
    WHEN 'day' THEN
      _group_select := 'timestamp::date::text';
      _group_expr := 'timestamp::date';
    WHEN 'week' THEN
      _group_select := 'date_trunc(''week'', timestamp)::date::text';
      _group_expr := 'date_trunc(''week'', timestamp)';
    WHEN 'month' THEN
      _group_select := 'date_trunc(''month'', timestamp)::date::text';
      _group_expr := 'date_trunc(''month'', timestamp)';
    WHEN 'page_path' THEN
      _group_select := 'COALESCE(page_path, ''/'')';
      _group_expr := 'COALESCE(page_path, ''/'')';
    WHEN 'referrer' THEN
      _group_select := 'COALESCE(regexp_replace(page_referrer, ''^https?://([^/]+).*'', ''\1''), ''Direct'')';
      _group_expr := 'COALESCE(regexp_replace(page_referrer, ''^https?://([^/]+).*'', ''\1''), ''Direct'')';
    WHEN 'country' THEN
      _group_select := 'COALESCE(country, ''Unknown'')';
      _group_expr := 'COALESCE(country, ''Unknown'')';
    WHEN 'device' THEN
      _group_select := 'COALESCE(device_type, ''Unknown'')';
      _group_expr := 'COALESCE(device_type, ''Unknown'')';
    WHEN 'utm_source' THEN
      _group_select := 'COALESCE(utm_source, ''(none)'')';
      _group_expr := 'COALESCE(utm_source, ''(none)'')';
    WHEN 'utm_medium' THEN
      _group_select := 'COALESCE(utm_medium, ''(none)'')';
      _group_expr := 'COALESCE(utm_medium, ''(none)'')';
    WHEN 'utm_campaign' THEN
      _group_select := 'COALESCE(utm_campaign, ''(none)'')';
      _group_expr := 'COALESCE(utm_campaign, ''(none)'')';
    WHEN 'none' THEN
      _group_select := NULL;
      _group_expr := NULL;
    ELSE RAISE EXCEPTION 'Invalid group_by: %', _group_by;
  END CASE;

  -- Build filter clause from JSONB array
  IF _filters IS NOT NULL AND jsonb_array_length(_filters) > 0 THEN
    FOR _f IN SELECT * FROM jsonb_array_elements(_filters) LOOP
      _field := _f->>'field';
      _op := _f->>'op';
      _val := _f->>'value';

      -- Normalize aliases to actual column names
      IF _field = 'device' THEN _field := 'device_type'; END IF;
      IF _field = 'referrer' THEN _field := 'page_referrer'; END IF;

      -- Allowlist: filter fields (actual DB column names)
      IF _field NOT IN ('page_path', 'page_referrer', 'country', 'device_type', 'utm_source', 'utm_medium', 'utm_campaign') THEN
        RAISE EXCEPTION 'Invalid filter field: %', _field;
      END IF;
      IF _op NOT IN ('=', '!=', 'contains') THEN
        RAISE EXCEPTION 'Invalid filter operator: %', _op;
      END IF;

      IF _op = '=' THEN
        _filter_clause := _filter_clause || format(' AND %I = %L', _field, _val);
      ELSIF _op = '!=' THEN
        _filter_clause := _filter_clause || format(' AND %I != %L', _field, _val);
      ELSIF _op = 'contains' THEN
        _filter_clause := _filter_clause || format(' AND %I ILIKE %L', _field, '%' || _val || '%');
      END IF;
    END LOOP;
  END IF;

  -- Execute query
  IF _group_expr IS NULL THEN
    -- KPI mode: single aggregate value
    EXECUTE format(
      'SELECT jsonb_build_object(
         ''total'', COALESCE(%s, 0),
         ''rows'', ''[]''::jsonb
       )
       FROM pageviews
       WHERE organization_id = $1
         AND timestamp >= $2 AND timestamp < $3
         %s %s',
      _metric_expr, _bot_clause, _filter_clause
    ) INTO _result USING _organization_id, _date_from, _date_to;
  ELSE
    -- Grouped mode: rows with label + value
    EXECUTE format(
      'WITH total_q AS (
         SELECT COALESCE(%s, 0) AS total
         FROM pageviews
         WHERE organization_id = $1 AND timestamp >= $2 AND timestamp < $3 %s %s
       ),
       grouped_q AS (
         SELECT %s AS label, %s AS value
         FROM pageviews
         WHERE organization_id = $1 AND timestamp >= $2 AND timestamp < $3 %s %s
         GROUP BY %s
         ORDER BY value DESC
         LIMIT $4
       )
       SELECT jsonb_build_object(
         ''total'', (SELECT total FROM total_q),
         ''rows'', COALESCE((SELECT jsonb_agg(jsonb_build_object(''label'', label, ''value'', value)) FROM grouped_q), ''[]''::jsonb)
       )',
      _metric_expr, _bot_clause, _filter_clause,
      _group_select, _metric_expr,
      _bot_clause, _filter_clause, _group_expr
    ) INTO _result USING _organization_id, _date_from, _date_to, _limit;
  END IF;

  RETURN COALESCE(_result, '{"total":0,"rows":[]}'::jsonb);
END;
$_$;


--
-- Name: FUNCTION get_widget_data_pageviews(_organization_id uuid, _metric text, _group_by text, _filters jsonb, _date_from timestamp with time zone, _date_to timestamp with time zone, _limit integer, _exclude_bot boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_widget_data_pageviews(_organization_id uuid, _metric text, _group_by text, _filters jsonb, _date_from timestamp with time zone, _date_to timestamp with time zone, _limit integer, _exclude_bot boolean) IS 'Widget data query for pageviews (Website Analytics). Supports configurable metric, group_by, and filters with allowlisted inputs. Includes UTM dimensions.';


--
-- Name: get_widget_data_visits(uuid, text, text, jsonb, timestamp with time zone, timestamp with time zone, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_widget_data_visits(_organization_id uuid, _metric text, _group_by text, _filters jsonb DEFAULT '[]'::jsonb, _date_from timestamp with time zone DEFAULT (now() - '7 days'::interval), _date_to timestamp with time zone DEFAULT now(), _limit integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $_$
DECLARE
  _result JSONB;
  _metric_expr TEXT;
  _group_expr TEXT;
  _group_select TEXT;
  _filter_clause TEXT := '';
  _f JSONB;
  _field TEXT;
  _op TEXT;
  _val TEXT;
BEGIN
  -- Allowlist: metric
  CASE _metric
    WHEN 'count' THEN _metric_expr := 'COUNT(*)';
    WHEN 'unique_count' THEN _metric_expr := 'COUNT(DISTINCT fp) FILTER (WHERE fp IS NOT NULL)';
    ELSE RAISE EXCEPTION 'Invalid metric: %', _metric;
  END CASE;

  -- Allowlist: group_by
  -- User-facing names map to actual DB columns
  CASE _group_by
    WHEN 'day' THEN
      _group_select := 'created_at::date::text';
      _group_expr := 'created_at::date';
    WHEN 'week' THEN
      _group_select := 'date_trunc(''week'', created_at)::date::text';
      _group_expr := 'date_trunc(''week'', created_at)';
    WHEN 'month' THEN
      _group_select := 'date_trunc(''month'', created_at)::date::text';
      _group_expr := 'date_trunc(''month'', created_at)';
    WHEN 'channel' THEN
      _group_select := 'COALESCE(type, ''Unknown'')';
      _group_expr := 'COALESCE(type, ''Unknown'')';
    WHEN 'country' THEN
      _group_select := 'COALESCE(country, ''Unknown'')';
      _group_expr := 'COALESCE(country, ''Unknown'')';
    WHEN 'device' THEN
      _group_select := 'COALESCE(platform, ''Unknown'')';
      _group_expr := 'COALESCE(platform, ''Unknown'')';
    WHEN 'os' THEN
      _group_select := 'COALESCE(os, ''Unknown'')';
      _group_expr := 'COALESCE(os, ''Unknown'')';
    WHEN 'referrer' THEN
      _group_select := 'COALESCE(referrer, ''Direct'')';
      _group_expr := 'COALESCE(referrer, ''Direct'')';
    WHEN 'touch_point' THEN
      _group_select := 'tp_id::text';
      _group_expr := 'tp_id';
    WHEN 'utm_source' THEN
      _group_select := 'COALESCE(utm_tags->>''utm_source'', ''(none)'')';
      _group_expr := 'COALESCE(utm_tags->>''utm_source'', ''(none)'')';
    WHEN 'utm_medium' THEN
      _group_select := 'COALESCE(utm_tags->>''utm_medium'', ''(none)'')';
      _group_expr := 'COALESCE(utm_tags->>''utm_medium'', ''(none)'')';
    WHEN 'utm_campaign' THEN
      _group_select := 'COALESCE(utm_tags->>''utm_campaign'', ''(none)'')';
      _group_expr := 'COALESCE(utm_tags->>''utm_campaign'', ''(none)'')';
    WHEN 'none' THEN
      _group_select := NULL;
      _group_expr := NULL;
    ELSE RAISE EXCEPTION 'Invalid group_by: %', _group_by;
  END CASE;

  -- Build filter clause from JSONB array
  IF _filters IS NOT NULL AND jsonb_array_length(_filters) > 0 THEN
    FOR _f IN SELECT * FROM jsonb_array_elements(_filters) LOOP
      _field := _f->>'field';
      _op := _f->>'op';
      _val := _f->>'value';

      -- UTM fields use JSONB path expressions (not column names)
      -- Must handle before alias normalization and %I quoting
      IF _field = 'utm_source' THEN
        IF _op = '=' THEN _filter_clause := _filter_clause || format(' AND utm_tags->>''utm_source'' = %L', _val);
        ELSIF _op = '!=' THEN _filter_clause := _filter_clause || format(' AND utm_tags->>''utm_source'' != %L', _val);
        ELSIF _op = 'contains' THEN _filter_clause := _filter_clause || format(' AND utm_tags->>''utm_source'' ILIKE %L', '%' || _val || '%');
        END IF;
        CONTINUE;
      END IF;
      IF _field = 'utm_medium' THEN
        IF _op = '=' THEN _filter_clause := _filter_clause || format(' AND utm_tags->>''utm_medium'' = %L', _val);
        ELSIF _op = '!=' THEN _filter_clause := _filter_clause || format(' AND utm_tags->>''utm_medium'' != %L', _val);
        ELSIF _op = 'contains' THEN _filter_clause := _filter_clause || format(' AND utm_tags->>''utm_medium'' ILIKE %L', '%' || _val || '%');
        END IF;
        CONTINUE;
      END IF;
      IF _field = 'utm_campaign' THEN
        IF _op = '=' THEN _filter_clause := _filter_clause || format(' AND utm_tags->>''utm_campaign'' = %L', _val);
        ELSIF _op = '!=' THEN _filter_clause := _filter_clause || format(' AND utm_tags->>''utm_campaign'' != %L', _val);
        ELSIF _op = 'contains' THEN _filter_clause := _filter_clause || format(' AND utm_tags->>''utm_campaign'' ILIKE %L', '%' || _val || '%');
        END IF;
        CONTINUE;
      END IF;

      -- Normalize aliases to actual column names
      IF _field = 'channel' THEN _field := 'type'; END IF;
      IF _field = 'device' THEN _field := 'platform'; END IF;
      IF _field = 'touch_point' THEN _field := 'tp_id'; END IF;

      -- Allowlist: filter fields (actual DB column names)
      IF _field NOT IN ('type', 'country', 'platform', 'os', 'referrer', 'tp_id') THEN
        RAISE EXCEPTION 'Invalid filter field: %', _field;
      END IF;
      IF _op NOT IN ('=', '!=', 'contains') THEN
        RAISE EXCEPTION 'Invalid filter operator: %', _op;
      END IF;

      IF _op = '=' THEN
        _filter_clause := _filter_clause || format(' AND %I = %L', _field, _val);
      ELSIF _op = '!=' THEN
        _filter_clause := _filter_clause || format(' AND %I != %L', _field, _val);
      ELSIF _op = 'contains' THEN
        _filter_clause := _filter_clause || format(' AND %I ILIKE %L', _field, '%' || _val || '%');
      END IF;
    END LOOP;
  END IF;

  -- Execute query
  IF _group_expr IS NULL THEN
    -- KPI mode: single aggregate value
    EXECUTE format(
      'SELECT jsonb_build_object(
         ''total'', COALESCE(%s, 0),
         ''rows'', ''[]''::jsonb
       )
       FROM visits
       WHERE organization_id = $1
         AND created_at >= $2 AND created_at < $3
         AND is_bot = false
         %s',
      _metric_expr, _filter_clause
    ) INTO _result USING _organization_id, _date_from, _date_to;
  ELSE
    -- Grouped mode: rows with label + value
    EXECUTE format(
      'WITH total_q AS (
         SELECT COALESCE(%s, 0) AS total
         FROM visits
         WHERE organization_id = $1 AND created_at >= $2 AND created_at < $3 AND is_bot = false %s
       ),
       grouped_q AS (
         SELECT %s AS label, %s AS value
         FROM visits
         WHERE organization_id = $1 AND created_at >= $2 AND created_at < $3 AND is_bot = false %s
         GROUP BY %s
         ORDER BY value DESC
         LIMIT $4
       )
       SELECT jsonb_build_object(
         ''total'', (SELECT total FROM total_q),
         ''rows'', COALESCE((SELECT jsonb_agg(jsonb_build_object(''label'', label, ''value'', value)) FROM grouped_q), ''[]''::jsonb)
       )',
      _metric_expr, _filter_clause,
      _group_select, _metric_expr,
      _filter_clause, _group_expr
    ) INTO _result USING _organization_id, _date_from, _date_to, _limit;
  END IF;

  RETURN COALESCE(_result, '{"total":0,"rows":[]}'::jsonb);
END;
$_$;


--
-- Name: FUNCTION get_widget_data_visits(_organization_id uuid, _metric text, _group_by text, _filters jsonb, _date_from timestamp with time zone, _date_to timestamp with time zone, _limit integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_widget_data_visits(_organization_id uuid, _metric text, _group_by text, _filters jsonb, _date_from timestamp with time zone, _date_to timestamp with time zone, _limit integer) IS 'Widget data query for visits (Link Clicks). Supports configurable metric, group_by, and filters with allowlisted inputs. UTM dimensions via utm_tags JSONB.';


--
-- Name: grant_premium_to_first_200(uuid, text, inet, text, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.grant_premium_to_first_200(_user_id uuid, _user_email text, _signup_ip inet, _signup_fp text, _user_agent text, _request_id text DEFAULT NULL::text, _session_id text DEFAULT NULL::text, _registration_source text DEFAULT 'ORGANIC'::text, _registration_campaign text DEFAULT 'grant_premium_to_first_200'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$DECLARE
  premium_plan_id UUID := '804ad067-6a44-4b20-959a-ed67e670d3d6';
  current_counter INTEGER;
  max_counter INTEGER := 200;
  user_sequence_number INTEGER;
  existing_user RECORD;
  request_id TEXT;
  start_time TIMESTAMP;
  processing_time_ms INTEGER;
BEGIN
  -- Lock the entire function to prevent concurrent executions
  PERFORM pg_advisory_xact_lock(hashtext('grant_premium_to_first_200'));

  -- Initialize tracking
  start_time := clock_timestamp();
  
  -- Use provided request_id or generate a new one
  IF _request_id IS NOT NULL THEN
    request_id := _request_id;
  ELSE
    request_id := 'req_' || extract(epoch from now()) || '_' || substr(md5(random()::text), 1, 8);
  END IF;
  
  -- Log attempt
  INSERT INTO logs.audit_logs (
    event_type, user_id, timestamp, ip_address, user_agent,
    request_id, session_id, metadata
  ) VALUES (
    'PREMIUM_GRANT_ATTEMPT', _user_id, NOW(), _signup_ip, _user_agent,
    request_id, _session_id, 
    jsonb_build_object(
      'registration_source', _registration_source,
      'signup_fp', _signup_fp
    )
  );

  -- Check if user already has the specific premium plan
  SELECT p.id, up.plan_id INTO existing_user
  FROM profiles p
  LEFT JOIN user_plans up ON p.id = up.user_id AND up.plan_id = premium_plan_id
  WHERE p.id = _user_id FOR UPDATE OF p;

  IF existing_user.plan_id IS NOT NULL THEN
    INSERT INTO logs.audit_logs (
      event_type, user_id, timestamp, request_id, result, reason
    ) VALUES (
      'PREMIUM_GRANT_FAILED', _user_id, NOW(), request_id, 'FAILED', 'ALREADY_HAS_PREMIUM'
    );
    
    -- Calculate processing time
    processing_time_ms := EXTRACT(MILLISECONDS FROM clock_timestamp() - start_time)::INTEGER;
    RETURN jsonb_build_object('success', false, 'reason', 'ALREADY_HAS_PREMIUM', 'processing_time_ms', processing_time_ms);
  END IF;

  -- Initialize counter if not exists
  INSERT INTO system_counters (counter_type, current_value, max_value, is_active, updated_at)
  VALUES ('premium_users_granted', 0, max_counter, true, NOW())
  ON CONFLICT (counter_type) DO NOTHING;

  -- Atomic counter increment
  UPDATE system_counters 
  SET current_value = current_value + 1,
      updated_at = NOW()
  WHERE counter_type = 'premium_users_granted' 
    AND current_value < max_counter
    AND is_active = true
  RETURNING current_value INTO user_sequence_number;

  IF user_sequence_number IS NULL THEN
    INSERT INTO logs.audit_logs (
      event_type, user_id, timestamp, request_id, result, reason
    ) VALUES (
      'PREMIUM_GRANT_FAILED', _user_id, NOW(), request_id, 'FAILED', 'LIMIT_REACHED'
    );
    
    -- Calculate processing time
    processing_time_ms := EXTRACT(MILLISECONDS FROM clock_timestamp() - start_time)::INTEGER;
    RETURN jsonb_build_object('success', false, 'reason', 'LIMIT_REACHED', 'processing_time_ms', processing_time_ms);
  END IF;

  -- Check device fingerprint limit (max 1 per device_fp)
  -- SELECT COUNT(*) INTO current_counter
  -- FROM logs.premium_grants_log
  -- WHERE device_fp = _signup_fp AND device_fp IS NOT NULL AND registration_campaign = _registration_campaign;
  
  -- IF current_counter >= 1 THEN
  --   INSERT INTO logs.audit_logs (
  --     event_type, user_id, timestamp, request_id, result, reason, metadata
  --   ) VALUES (
  --     'PREMIUM_GRANT_FAILED', _user_id, NOW(), request_id, 'FAILED', 'DEVICE_FP_LIMIT_REACHED',
  --     jsonb_build_object('device_fp', _signup_fp, 'existing_grants', current_counter)
  --   );
    
  --   -- Calculate processing time
  --   processing_time_ms := EXTRACT(MILLISECONDS FROM clock_timestamp() - start_time)::INTEGER;
  --   RETURN jsonb_build_object('success', false, 'reason', 'DEVICE_FP_LIMIT_REACHED', 'processing_time_ms', processing_time_ms);
  -- END IF;
  
  -- Check IP address limit (max 5 per IP)
  -- SELECT COUNT(*) INTO current_counter
  -- FROM logs.premium_grants_log
  -- WHERE ip_address = _signup_ip AND registration_campaign = _registration_campaign;
  
  -- IF current_counter >= 5 THEN
  --   INSERT INTO logs.audit_logs (
  --     event_type, user_id, timestamp, request_id, result, reason, metadata
  --   ) VALUES (
  --     'PREMIUM_GRANT_FAILED', _user_id, NOW(), request_id, 'FAILED', 'IP_LIMIT_REACHED',
  --     jsonb_build_object('ip_address', _signup_ip::text, 'existing_grants', current_counter)
  --   );
    
  --   -- Calculate processing time
  --   processing_time_ms := EXTRACT(MILLISECONDS FROM clock_timestamp() - start_time)::INTEGER;
  --   RETURN jsonb_build_object('success', false, 'reason', 'IP_LIMIT_REACHED', 'processing_time_ms', processing_time_ms);
  -- END IF;

  -- Grant premium (upsert) and log success
  INSERT INTO user_plans (user_id, plan_id, subscribed_at, expires_at)
  VALUES (_user_id, premium_plan_id, NOW(), NOW() + INTERVAL '1 year')
  ON CONFLICT (user_id) DO UPDATE
  SET
    plan_id = EXCLUDED.plan_id,
    subscribed_at = EXCLUDED.subscribed_at,
    expires_at = EXCLUDED.expires_at;

  -- Log detailed premium grant
  INSERT INTO logs.premium_grants_log (
    user_id, user_email, sequence_number, grant_type,
    ip_address, user_agent, device_fp, registration_date, registration_source, registration_campaign,
    premium_expires_at, request_id
  ) VALUES (
    _user_id, _user_email, user_sequence_number, 'AUTO',
    _signup_ip, _user_agent, _signup_fp, NOW(), _registration_source, _registration_campaign,
    NOW() + INTERVAL '1 year', request_id
  );

  -- Calculate processing time
  processing_time_ms := EXTRACT(MILLISECONDS FROM clock_timestamp() - start_time)::INTEGER;

  -- Log successful grant
  INSERT INTO logs.audit_logs (
    event_type, user_id, timestamp, request_id, result,
    user_sequence_number, metadata
  ) VALUES (
    'PREMIUM_GRANT_SUCCESS', _user_id, NOW(), request_id, 'SUCCESS',
    user_sequence_number,
    jsonb_build_object('processing_time_ms', processing_time_ms)
  );

  RETURN jsonb_build_object(
    'success', true,
    'user_number', user_sequence_number,
    'remaining', max_counter - user_sequence_number,
    'request_id', request_id,
    'processing_time_ms', processing_time_ms
  );

EXCEPTION
  WHEN OTHERS THEN
    -- Calculate processing time
    processing_time_ms := EXTRACT(MILLISECONDS FROM clock_timestamp() - start_time)::INTEGER;

    INSERT INTO logs.audit_logs (
      event_type, user_id, timestamp, request_id, result, error_message
    ) VALUES (
      'PREMIUM_GRANT_ERROR', _user_id, NOW(), request_id, 'ERROR', SQLERRM
    );
    
    RETURN jsonb_build_object('success', false, 'error', SQLERRM, 'processing_time_ms', processing_time_ms);
END;$$;


--
-- Name: handle_fp(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handle_fp(input_id uuid, input_canvas_fp text, input_browser_fp text) RETURNS TABLE(id uuid, canvas_fp text, browser_fp text, visit_count integer, canvas_update_count integer, browser_update_count integer, cookies_ls_fail integer)
    LANGUAGE plpgsql
    AS $$
declare
  existing record;
begin
  -- Try to find by ID
  if input_id is not null then
    select * into existing
    from public.test_fp_accurate as t
    where t.id = input_id;
  end if;

  -- If not found by ID, check for existing by canvas_fp or browser_fp
  if not found then
    select * into existing
    from public.test_fp_accurate as t
    where t.canvas_fp = input_canvas_fp
       or t.browser_fp = input_browser_fp
    limit 1;

    -- Found by FP but no ID → cookies_ls_fail + 1 and visit_count + 1
    if found then
      update public.test_fp_accurate as t
      set
        cookies_ls_fail = existing.cookies_ls_fail + 1,
        visit_count = existing.visit_count + 1
      where t.id = existing.id
      returning * into existing;

      return query select
        existing.id,
        existing.canvas_fp,
        existing.browser_fp,
        existing.visit_count,
        existing.canvas_update_count,
        existing.browser_update_count,
        existing.cookies_ls_fail;
      return;
    end if;
  end if;

  -- No record found at all → Insert new record
  if not found then
    insert into public.test_fp_accurate (
      canvas_fp,
      browser_fp,
      visit_count
    ) values (
      input_canvas_fp,
      input_browser_fp,
      1
    )
    returning * into existing;

    return query select
      existing.id,
      existing.canvas_fp,
      existing.browser_fp,
      existing.visit_count,
      existing.canvas_update_count,
      existing.browser_update_count,
      existing.cookies_ls_fail;
    return;
  else
    -- Found by ID
    update public.test_fp_accurate as t
    set
      canvas_fp = case when existing.canvas_fp <> input_canvas_fp then input_canvas_fp else existing.canvas_fp end,
      browser_fp = case when existing.browser_fp <> input_browser_fp then input_browser_fp else existing.browser_fp end,
      canvas_update_count = case when existing.canvas_fp <> input_canvas_fp then existing.canvas_update_count + 1 else existing.canvas_update_count end,
      browser_update_count = case when existing.browser_fp <> input_browser_fp then existing.browser_update_count + 1 else existing.browser_update_count end,
      visit_count = existing.visit_count + 1
    where t.id = existing.id
    returning * into existing;

    return query select
      existing.id,
      existing.canvas_fp,
      existing.browser_fp,
      existing.visit_count,
      existing.canvas_update_count,
      existing.browser_update_count,
      existing.cookies_ls_fail;
    return;
  end if;
end;
$$;


