--
-- Name: handle_organization_created(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handle_organization_created() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  affected_user UUID;
  owner_role_id UUID;
BEGIN
  -- 1. Insert into org_quotas
  INSERT INTO org_quotas (org_id)
  VALUES (NEW.id);

  -- 2. Determine affected user
  affected_user := NEW.user_id;

  -- 3. Update total_organizations in user_plans
  UPDATE user_plans
  SET total_organizations = (
    SELECT COUNT(*) FROM organizations WHERE user_id = affected_user
  )
  WHERE user_id = affected_user;

  -- 4. Find Owner role_id
  SELECT id INTO owner_role_id
  FROM roles
  WHERE is_default = TRUE AND name = 'Owner'
  LIMIT 1;

  -- 5. Insert org member as Owner
  INSERT INTO org_members (user_id, org_id, role_id)
  VALUES (NEW.user_id, NEW.id, owner_role_id);

  RETURN NEW;
END;
$$;


--
-- Name: handle_organization_insert(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handle_organization_insert() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    affected_user UUID;
BEGIN
    -- 1. Insert into org_quotas
    INSERT INTO org_quotas (org_id)
    VALUES (NEW.id);

    -- 2. Determine the affected user (for INSERT only)
    affected_user := NEW.user_id;

    -- 3. Update user_plans.total_organizations
    UPDATE user_plans
    SET total_organizations = (
        SELECT COUNT(*) FROM organizations WHERE user_id = affected_user
    )
    WHERE user_id = affected_user;

    RETURN NEW;
END;
$$;


