--
-- Name: increment_customer_sale(uuid, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.increment_customer_sale(customer_id uuid, sale_amount bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
    UPDATE customer_profiles
    SET sale_count = sale_count + 1,
        total_revenue = total_revenue + COALESCE(sale_amount, 0),
        updated_at = now()
    WHERE id = customer_id;
END;
$$;


--
-- Name: increment_customer_sale(uuid, bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.increment_customer_sale(customer_id uuid, sale_amount bigint, sale_currency text DEFAULT 'USD'::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
  UPDATE customer_profiles
  SET
    sale_count = sale_count + 1,
    -- Increment the appropriate currency column
    total_revenue_usd = CASE WHEN UPPER(sale_currency) = 'USD' THEN total_revenue_usd + COALESCE(sale_amount, 0) ELSE total_revenue_usd END,
    total_revenue_vnd = CASE WHEN UPPER(sale_currency) = 'VND' THEN total_revenue_vnd + COALESCE(sale_amount, 0) ELSE total_revenue_vnd END,
    -- Keep legacy total_revenue updated for backward compatibility
    total_revenue = total_revenue + COALESCE(sale_amount, 0),
    updated_at = now()
  WHERE id = customer_id;
END;
$$;


