BEGIN
  UPDATE org_credits oc
  SET ai_credits_balance = p.max_ai_credits,
      ai_credits_used_this_month = 0,
      ai_credits_last_reset = NOW(),
      updated_at = NOW()
  FROM organizations o
  JOIN user_plans up ON o.user_id = up.user_id
  JOIN plans p ON up.plan_id = p.id
  WHERE oc.org_id = o.id;
END;
$$;


