--
-- Name: schedule_weekly_reports(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.schedule_weekly_reports() RETURNS TABLE(scheduled_count integer, execution_summary text)
    LANGUAGE plpgsql
    AS $$
DECLARE
  last_saturday DATE;
  report_count INTEGER := 0;
  org_count INTEGER := 0;
BEGIN
  -- Get last Saturday
  -- last_saturday := DATE_TRUNC('week', NOW() - INTERVAL '1 week')::DATE;
  last_saturday := (DATE_TRUNC('day', NOW()) - ((EXTRACT(DOW FROM NOW()) + 1) % 7) * INTERVAL '1 day')::DATE;

  
  -- Generate reports for all organizations
  PERFORM generate_all_weekly_reports(last_saturday);
  
  -- Count generated reports
  SELECT COUNT(*) INTO report_count 
  FROM organization_reports 
  WHERE report_period_start = last_saturday 
    AND report_type = 'weekly'
    AND DATE(generated_at) = CURRENT_DATE;
  
  -- Count organizations with data
  SELECT COUNT(DISTINCT organization_id) INTO org_count
  FROM visits 
  WHERE DATE(created_at) BETWEEN last_saturday AND last_saturday + INTERVAL '6 days';
  
  scheduled_count := report_count;
  execution_summary := FORMAT('Generated %s reports for %s organizations. Period: %s to %s', 
    report_count, org_count, last_saturday, last_saturday + INTERVAL '6 days');
  
  RETURN NEXT;
END;
$$;


--
-- Name: sync_touchpoint_campaign_id(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_touchpoint_campaign_id() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- Handle INSERT and UPDATE
  IF (TG_OP = 'INSERT' OR TG_OP = 'UPDATE') THEN
    UPDATE touch_points
    SET utm_campaign_id = NEW.campaign_id
    WHERE id = NEW.touchpoint_id;
    RETURN NEW;
  END IF;

  -- Handle DELETE
  IF (TG_OP = 'DELETE') THEN
    UPDATE touch_points
    SET utm_campaign_id = NULL
    WHERE id = OLD.touchpoint_id;
    RETURN OLD;
  END IF;

  RETURN NULL;
END;
$$;


