  FROM organizations o
  JOIN user_plans up ON o.user_id = up.user_id
  JOIN plans p ON up.plan_id = p.id
  WHERE o.id = NEW.org_id;

  NEW.ai_credits_used_this_month := 0;
  NEW.updated_at := NOW();

  RETURN NEW;
END;
$$;


