--
-- Name: update_org_quotas_collections_counter(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_org_quotas_collections_counter() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'INSERT' AND NEW.deleted_at IS NULL THEN
    -- Increment quota counter on insert
    UPDATE org_quotas
    SET collections = COALESCE(collections, 0) + 1
    WHERE org_id = NEW.organization_id;
  ELSIF TG_OP = 'DELETE' OR (TG_OP = 'UPDATE' AND OLD.deleted_at IS NULL AND NEW.deleted_at IS NOT NULL) THEN
    -- Decrement quota counter on delete or soft delete
    UPDATE org_quotas
    SET collections = GREATEST(COALESCE(collections, 0) - 1, 0)
    WHERE org_id = COALESCE(OLD.organization_id, NEW.organization_id);
  ELSIF TG_OP = 'UPDATE' AND OLD.deleted_at IS NOT NULL AND NEW.deleted_at IS NULL THEN
    -- Increment quota counter on restore
    UPDATE org_quotas
    SET collections = COALESCE(collections, 0) + 1
    WHERE org_id = NEW.organization_id;
  END IF;
  RETURN NULL;
END;
$$;


--
-- Name: FUNCTION update_org_quotas_collections_counter(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.update_org_quotas_collections_counter() IS 'Automatically updates org_quotas.collections counter when collections are created, deleted, soft-deleted, or restored. Handles NULL values and prevents negative counts.';


