--
-- Name: update_org_quotas_event_rules_counter(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_org_quotas_event_rules_counter() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    UPDATE org_quotas
    SET event_rules = COALESCE(event_rules, 0) + 1
    WHERE org_id = NEW.organization_id;
  ELSIF TG_OP = 'DELETE' THEN
    UPDATE org_quotas
    SET event_rules = GREATEST(COALESCE(event_rules, 0) - 1, 0)
    WHERE org_id = OLD.organization_id;
  END IF;
  RETURN NULL;
END;
$$;


--
-- Name: FUNCTION update_org_quotas_event_rules_counter(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.update_org_quotas_event_rules_counter() IS 'Automatically updates org_quotas.event_rules counter when event rules are created or deleted.';


--
-- Name: update_org_static_qr_counter(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_org_static_qr_counter() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'INSERT' AND NEW.deleted_at IS NULL THEN
    -- Increment counter on insert
    UPDATE organizations
    SET total_static_qr = total_static_qr + 1
    WHERE id = NEW.organization_id;
  ELSIF TG_OP = 'DELETE' OR (TG_OP = 'UPDATE' AND OLD.deleted_at IS NULL AND NEW.deleted_at IS NOT NULL) THEN
    -- Decrement counter on delete or soft delete
    UPDATE organizations
    SET total_static_qr = GREATEST(total_static_qr - 1, 0)
    WHERE id = COALESCE(OLD.organization_id, NEW.organization_id);
  ELSIF TG_OP = 'UPDATE' AND OLD.deleted_at IS NOT NULL AND NEW.deleted_at IS NULL THEN
    -- Increment counter on restore
    UPDATE organizations
    SET total_static_qr = total_static_qr + 1
    WHERE id = NEW.organization_id;
  END IF;
  RETURN NULL;
END;
$$;


