--
-- Name: update_touch_points_short_urls(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_touch_points_short_urls(data jsonb) RETURNS void
    LANGUAGE plpgsql
    AS $$
declare
  item jsonb;
  item_id uuid;
  new_short_url text;
begin
  for item in select value from jsonb_array_elements(data) as value loop
    item_id := (item ->> 'id')::uuid;
    new_short_url := item ->> 'short_url';

    update touch_points
    set short_url = new_short_url
    where id = item_id;
  end loop;
end;
$$;


