  RETURN NEW;
END;
$$;


--
-- Name: update_tp_tag_links(uuid, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_tp_tag_links(input_tp_id uuid, input_tag_ids uuid[]) RETURNS void
    LANGUAGE plpgsql
    AS $$
begin
  -- Delete links not in the new list
  delete from tp_tag_links
  where tp_id = input_tp_id
    and tag_id not in (select unnest(input_tag_ids));

  -- Insert new links (avoid duplicates)
  insert into tp_tag_links (tp_id, tag_id)
  select input_tp_id, unnest_tag_id
  from unnest(input_tag_ids) as unnest_tag_id
  where not exists (
    select 1 from tp_tag_links
    where tp_id = input_tp_id and tag_id = unnest_tag_id
  );
end;
$$;


