--
-- Name: write_audit_log(text, text, text, timestamp with time zone, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.write_audit_log(p_request_id text, p_user_id text, p_event_type text, p_timestamp timestamp with time zone, p_result text, p_reason text, p_metadata jsonb) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
    INSERT INTO logs.audit_logs (
        request_id,
        user_id,
        event_type,
        timestamp,
        result,
        reason,
        metadata
    )
    VALUES (
        p_request_id,
        p_user_id,
        p_event_type,
        p_timestamp,
        p_result,
        p_reason,
        p_metadata
    );
END;
$$;


--
-- Name: write_org_audit_log(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.write_org_audit_log(p jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'logs'
    AS $$
declare v_id uuid;
begin
  insert into logs.org_audit_logs
    (organization_id, user_id, module, action, target_id, target_name, target_table,
     target_extra, changes, metadata, created_at)
  values
    ((p->>'organization_id')::uuid,
     nullif(p->>'user_id','')::uuid,
     p->>'module', p->>'action',
     nullif(p->>'target_id','')::uuid,
     p->>'target_name', p->>'target_table',
     p->'target_extra', p->'changes', p->'metadata',
     coalesce((p->>'created_at')::timestamptz, now()))
  returning id into v_id;
  return v_id;
end $$;


--
-- Name: write_plan_logs(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.write_plan_logs() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'INSERT' OR (TG_OP = 'UPDATE' AND (OLD.plan_id IS DISTINCT FROM NEW.plan_id OR OLD.expires_at IS DISTINCT FROM NEW.expires_at)) THEN
        INSERT INTO plan_logs (user_id, plan_id, expires_at)
        VALUES (NEW.user_id, NEW.plan_id, NEW.expires_at);
    END IF;
    RETURN NEW;
END;
$$;


