-- Name: deep_link_events; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.deep_link_events (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    domain_id uuid,
    touch_point_id uuid,
    click_id text NOT NULL,
    event_type text NOT NULL,
    match_method text,
    platform text,
    ip inet,
    user_agent text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    miss_reason text,
    CONSTRAINT deep_link_events_event_type_check CHECK ((event_type = ANY (ARRAY['app_open'::text, 'deferred_match'::text, 'deferred_miss'::text]))),
    CONSTRAINT deep_link_events_match_method_check CHECK ((match_method = ANY (ARRAY['universal_link'::text, 'app_link'::text, 'clipboard'::text, 'ip'::text, 'ip_ua'::text, 'install_referrer'::text]))),
    CONSTRAINT deep_link_events_miss_reason_check CHECK ((miss_reason = ANY (ARRAY['no_candidate'::text, 'ambiguous_candidate'::text, 'ua_mismatch'::text, 'clipboard_denied'::text, 'clipboard_empty'::text, 'cross_tenant_blocked'::text, 'opt_out'::text]))),
    CONSTRAINT deep_link_events_platform_check CHECK ((platform = ANY (ARRAY['ios'::text, 'android'::text])))
);


--
-- Name: TABLE deep_link_events; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.deep_link_events IS 'Append-only log of deep link attribution events. Written by /track/open. Read by deep link analytics widgets (Phase 5).';


--
-- Name: COLUMN deep_link_events.domain_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.deep_link_events.domain_id IS 'Domain that served the deep-link click. ON DELETE SET NULL: nulled (not cascaded) when the domain is deleted so attribution history survives. Historical events stay tied to the link via touch_point_id.';


--
-- Name: COLUMN deep_link_events.touch_point_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.deep_link_events.touch_point_id IS 'NULL for IP-matched deferred events where the slug is unknown (Phase 3).';


--
-- Name: COLUMN deep_link_events.click_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.deep_link_events.click_id IS 'Opaque 16-char base62 token returned to the mobile SDK. Used for conversion attribution starting Phase 2.5.';


--
-- Name: COLUMN deep_link_events.match_method; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.deep_link_events.match_method IS 'How the open was resolved to the original click. NULL when unknown.';


--
-- Name: COLUMN deep_link_events.miss_reason; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.deep_link_events.miss_reason IS 'Reason for deferred_miss. NULL on deferred_match and app_open rows. See plans/deep-links/phase-3-ios-deferred/README.md D-3.I for enum semantics and D-3.D-revision.md for opt_out (added 2026-05-15).';


