    visitor_id character varying(64) NOT NULL,
    li2_cid character varying(64),
    page_url text NOT NULL,
    page_path character varying(2048) NOT NULL,
    x integer,
    y integer,
    target_fixed boolean DEFAULT false,
    viewport_width smallint NOT NULL,
    viewport_height smallint NOT NULL,
    page_height integer,
    scroll_y integer,
    element_tag character varying(32),
    element_text character varying(256),
    element_href character varying(2048),
    element_class character varying(512),
    element_id character varying(256),
    selector_path character varying(1024),
    interaction_type character varying(16) DEFAULT 'click'::character varying NOT NULL,
    "timestamp" timestamp with time zone NOT NULL,
    ip inet,
    user_agent text,
    device_type character varying(16),
    country character varying(2),
    is_bot boolean DEFAULT false,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    scroll_depth_percent smallint,
    scroll_direction character varying(4),
    time_at_depth integer,
    form_id character varying(256),
    form_name character varying(256),
    form_action character varying(2048),
    form_method character varying(4),
    input_count integer,
    filled_count integer,
    time_on_form bigint,
    CONSTRAINT chk_click_coords CHECK ((((interaction_type)::text <> 'click'::text) OR ((x IS NOT NULL) AND (y IS NOT NULL)))),
    CONSTRAINT chk_scroll_depth CHECK ((((interaction_type)::text <> 'scroll'::text) OR (scroll_depth_percent IS NOT NULL)))
)
PARTITION BY RANGE (created_at);


