    id uuid DEFAULT gen_random_uuid() NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    name text NOT NULL,
    user_id uuid DEFAULT public.requesting_user_id() NOT NULL,
    total_touch_points smallint DEFAULT '0'::smallint NOT NULL,
    total_members smallint DEFAULT '1'::smallint NOT NULL,
    total_tags smallint DEFAULT '0'::smallint NOT NULL,
    total_domains smallint DEFAULT '0'::smallint NOT NULL,
    total_integrations smallint DEFAULT '0'::smallint NOT NULL,
    org_slug text,
    setup_completed boolean DEFAULT false,
    default_domain_id uuid,
    total_collections integer DEFAULT 0,
    total_static_qr integer DEFAULT 0,
    default_currency text DEFAULT 'USD'::text,
    CONSTRAINT organizations_default_currency_check CHECK (((default_currency IS NULL) OR (default_currency = ANY (ARRAY['USD'::text, 'VND'::text])))),
    CONSTRAINT organizations_org_slug_format_check CHECK (((org_slug IS NULL) OR ((org_slug ~ '^[a-z0-9]([a-z0-9-]*[a-z0-9])?$'::text) AND (length(org_slug) >= 3) AND (length(org_slug) <= 30))))
);


