--
-- Name: v_report_performance; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_report_performance AS
 SELECT report_type,
    date_trunc('day'::text, generated_at) AS report_date,
    count(*) AS reports_generated,
    avg(EXTRACT(epoch FROM (generated_at - created_at))) AS avg_generation_time_seconds,
    max(EXTRACT(epoch FROM (generated_at - created_at))) AS max_generation_time_seconds
   FROM public.organization_reports
  WHERE (generated_at >= (now() - '30 days'::interval))
  GROUP BY report_type, (date_trunc('day'::text, generated_at))
  ORDER BY (date_trunc('day'::text, generated_at)) DESC;


--
-- Name: v_weekly_report_status; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_weekly_report_status AS
 SELECT o.name AS organization_name,
    o.id AS organization_id,
    count(orp.id) AS total_reports,
    count(
        CASE
            WHEN ((orp.status)::text = 'generated'::text) THEN 1
            ELSE NULL::integer
        END) AS generated_reports,
    count(
        CASE
            WHEN ((orp.status)::text = 'sent'::text) THEN 1
            ELSE NULL::integer
        END) AS sent_reports,
    count(
        CASE
            WHEN ((orp.status)::text = 'failed'::text) THEN 1
            ELSE NULL::integer
        END) AS failed_reports,
    max(orp.generated_at) AS last_report_generated,
    count(
        CASE
            WHEN (orp.generated_at >= (now() - '7 days'::interval)) THEN 1
            ELSE NULL::integer
        END) AS reports_this_week
   FROM (public.organizations o
     LEFT JOIN public.organization_reports orp ON ((o.id = orp.organization_id)))
  GROUP BY o.id, o.name
  ORDER BY (max(orp.generated_at)) DESC NULLS LAST;


