--
-- Name: visits_by_organization; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.visits_by_organization AS
 WITH platform_counts AS (
         SELECT v.organization_id,
            v.platform,
            count(*) AS platform_count
           FROM public.visits v
          GROUP BY v.organization_id, v.platform
        ), os_counts AS (
         SELECT v.organization_id,
            v.os,
            count(*) AS os_count
           FROM public.visits v
          GROUP BY v.organization_id, v.os
        ), type_counts AS (
         SELECT v.organization_id,
            v.type,
            count(*) AS type_count
           FROM public.visits v
          GROUP BY v.organization_id, v.type
        ), visit_totals AS (
         SELECT v.organization_id,
            count(*) AS total,
            count(DISTINCT v.fp) AS fp,
            (min((v.user_id)::text))::uuid AS user_id
           FROM public.visits v
          GROUP BY v.organization_id
        )
 SELECT vt.organization_id,
    vt.total,
    vt.fp,
    vt.user_id,
    jsonb_agg(DISTINCT jsonb_build_object('platform', pc.platform, 'count', pc.platform_count)) AS platform,
    jsonb_agg(DISTINCT jsonb_build_object('os', oc.os, 'count', oc.os_count)) AS os,
    jsonb_agg(DISTINCT jsonb_build_object('type', type.type, 'count', type.type_count)) AS type
   FROM ((((visit_totals vt
     JOIN public.organizations gr ON ((gr.id = vt.organization_id)))
     LEFT JOIN platform_counts pc ON ((vt.organization_id = pc.organization_id)))
     LEFT JOIN os_counts oc ON ((vt.organization_id = oc.organization_id)))
     LEFT JOIN type_counts type ON ((vt.organization_id = type.organization_id)))
  GROUP BY vt.organization_id, vt.total, vt.fp, vt.user_id;


--
-- Name: visits_by_tp; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.visits_by_tp AS
 WITH platform_counts AS (
         SELECT v.tp_id,
            v.platform,
            count(*) AS platform_count
           FROM public.visits v
          GROUP BY v.tp_id, v.platform
        ), os_counts AS (
         SELECT v.tp_id,
            v.os,
            count(*) AS os_count
           FROM public.visits v
          GROUP BY v.tp_id, v.os
        ), visit_totals AS (
         SELECT v.tp_id,
            count(*) AS total,
            count(DISTINCT v.fp) AS fp,
            (min((v.user_id)::text))::uuid AS user_id
           FROM public.visits v
          GROUP BY v.tp_id
        )
 SELECT vt.tp_id,
    vt.total,
    vt.fp,
    vt.user_id,
    jsonb_agg(DISTINCT jsonb_build_object('platform', pc.platform, 'count', pc.platform_count)) AS platform,
    jsonb_agg(DISTINCT jsonb_build_object('os', oc.os, 'count', oc.os_count)) AS os
   FROM (((visit_totals vt
     JOIN public.touch_points sh ON ((sh.id = vt.tp_id)))
     LEFT JOIN platform_counts pc ON ((vt.tp_id = pc.tp_id)))
     LEFT JOIN os_counts oc ON ((vt.tp_id = oc.tp_id)))
  GROUP BY vt.tp_id, vt.total, vt.fp, vt.user_id;


